// every screen that runs inside the locked-down POS shell — the shell owns the bottom nav
// Status-template screens: a blocked action always says what did NOT happen
// `priceConfirm` and `crossConfirm` used to be cards: agreeing a bitcoin price,
// and agreeing to pay somebody at another mint. Both are a person looking at
// figures and deciding, which is what this shell is for.
// Kept as one plain array literal — a suite reads this line as JSON.
const CONFIRM_SCREENS = ['depConfirm', 'sendConfirm', 'reqOffer', 'trConfirm', 'ocConfirm', 'priceConfirm', 'crossConfirm', 'fcMoveConfirm', 'fcLimitConfirm'];
// how long a fetched price still counts when a refresh fails, and how long a
// launch with no price waits before saying so (09-melt-paste-switch.js)
const PRICE_STANDS_MS = 3 * 60 * 1000;
const PRICE_GRACE_MS = 8000;

const BLOCKED = {
  sendFail:   { title: 'PAYMENT FAILED',   reason: 'The amount is more than your available balance.', chip: 'Your money never left your account.', retry: 'CHANGE AMOUNT', back: 'amount', showAmount: true },

  // ---- identity and sign-in ----

  // ---- money in ----

  // ---- money out ----
  mintRefused: { title: 'THE MINT SAID NO', tone: 'warn',
    reason: 'The mint would not carry out this payment.' },
  netLost:    { title: 'CONNECTION LOST',  reason: "We lost signal before this finished. We'll confirm the outcome once you're back online.", chip: 'Nothing is final until you reconnect.', retry: 'RETRY', back: 'amount', showAmount: true, tone: 'warn' },
  lnNoRoute:  { title: 'NO ROUTE FOUND',   reason: "We couldn't find a path to that wallet. It may be offline or short on capacity.", chip: 'Your money never left your account.', retry: 'TRY AGAIN', back: 'amount', showAmount: true },
  badAddress: { title: "THAT WON'T WORK",  reason: "This isn't a valid Lightning invoice or bitcoin address. Check it and paste it again.", chip: 'Nothing was sent.', retry: 'PASTE AGAIN', back: 'sendHow' },
};

const CTA_INK = s => '#fff';
// the host may pin these; local state is the fallback
const TH = c => c.props.startTheme || c.state.theme;
const AC = c => c.props.startAccent || c.state.accent;

const ACCENTS = [
  { id: 'foxy',   name: 'FOXY',        acc: '#E8622A', lt: '#F79A3C', dk: '#C24A1B', rgb: '232,98,42' },
  { id: 'green',  name: 'GREEN', acc: '#3AB54A', lt: '#5CD46C', dk: '#2C9A3B', rgb: '58,181,74' },
  { id: 'teal',   name: 'SEA',         acc: '#0E9E93', lt: '#3CC7BB', dk: '#0A7C73', rgb: '14,158,147' },
  { id: 'sky',    name: 'SKY',         acc: '#2E7CF6', lt: '#5C9BFF', dk: '#215FC4', rgb: '46,124,246' },
  { id: 'indigo', name: 'INDIGO',      acc: '#5B54E8', lt: '#8079FF', dk: '#4640BC', rgb: '91,84,232' },
  { id: 'violet', name: 'VIOLET',      acc: '#8B45D6', lt: '#AC72EC', dk: '#6E34AC', rgb: '139,69,214' },
  { id: 'rose',   name: 'ROSE',        acc: '#D4409A', lt: '#EE6FBB', dk: '#A82F79', rgb: '212,64,154' },
  { id: 'ember',  name: 'EMBER',       acc: '#E0602E', lt: '#F58A5C', dk: '#B44A22', rgb: '224,96,46' },
  { id: 'gold',   name: 'GOLD',        acc: '#D19A0E', lt: '#EDBB3C', dk: '#A87A0A', rgb: '209,154,14' },
];
const ACC_OF = (id) => ACCENTS.filter(a => a.id === id)[0] || ACCENTS[0];

// workbench seeds: enough state for a screen to render out of context

class Component extends DCLogic {
  /* The fork's workbench table of preset screens went with this state: two
   * dozen frames of someone else's demo data — a bank name, a card's last four,
   * a phone number, dollar balances — reachable only through a `startSeed` prop
   * nothing has ever set. Residue of the kind the audit's finding 13 is about,
   * kept alive only by the spreads that read it. */
  /* Screen state is a bag: most of it is set by the screens themselves as they
   * are opened, not listed here. The type says so plainly now — it used to be
   * widened by accident, through a spread of the workbench table that stood
   * where this comment does. */
  /** @type {Record<string, any>} */
  state = {
    ...(this.props.startOpen ? { [this.props.startOpen]: true } : {}),
    screen: this.props.startScreen || 'home',
    // true from the first paint, so the connect screen never flashes its
    // pairing prompt before the saved-wallet check has had a chance to run
    walletSearching: !this.props.startStatic,
    stack: [], mapFull: !!this.props.startFull,
    balUsd: this.props.startFresh ? 0 : null,
    balSats: this.props.startFresh ? 0 : null,
    noCardYet: !!this.props.startNoCard,
    camOk: !this.props.startNoCamera,
    baName: this.props.startBizName || '',
    baAddr: this.props.startBizAddr || '',
    bizReview: this.props.startBizReview || undefined,
    acctLevel: this.props.startLevel || undefined,
    // review frames: a verified or boosted account implies a number on file
    acctPh: this.props.startJm ? '+1 876 555 0143'
      : ((this.props.startLevel === 'verified' || this.props.startLevel === 'boosted') ? '+1 (876) 555-0143' : undefined),
    xCtaBtc: (this.props.startCashOnly && !this.props.startFresh) || undefined,
    asset: '',
    amount: '',
    network: '',
    unit: 'USD',
    theme: 'dark',
    hidden: false, range: '1D', rangeOpen: false, open: { contact: true, account: false, login: false },
    priceCollapsed: false,
    noteOpen: this.props.startPopup === 'noteOpen' || this.props.startOpen === 'noteOpen', note: '', noteDraft: '', kbShift: true, kbSymbols: false,
    priceRemoved: false, removeConfirmOpen: false, addConfirmOpen: false,
    ...(this.props.startOpen ? { [this.props.startOpen]: true } : {}),
    ...(this.props.startScreen ? { screen: this.props.startScreen } : {}),
  };

  /* Is this phone working offline, by the person's own choice?
   *
   * Read from the route every render, never remembered: `_privacy` surrenders the
   * choice the moment Tor is up, so a screen that cached this would go on greying
   * out controls that had started working again. The app already re-renders on
   * every privacy push (`onPrivacy` → `routeAt`), so reading it live costs
   * nothing.
   *
   * Not the same question as "is the route shut". Tor merely connecting is not
   * offline: the person has not chosen anything, the gate is up saying so, and
   * nothing should be greyed out on a screen they cannot see. */
  offlineNow() {
    const W = window.FoxyWallet;
    const p = (W && W.privacy) ? W.privacy() : null;
    return !!(p && p.offline);
  }

  /* What a greyed-out control says when it is tapped anyway. A control that
   * looks dead and does nothing at all reads as a bug; one that says why reads
   * as a state. */
  offlineNo(what) {
    const W = window.FoxyWallet;
    // there is no OFFLINE to tap while a connection is on its way: the banner says SECURING YOUR CONNECTION
    const coming = !!(W && W.routeComing && W.routeComing());
    this.toast((what || 'That') + (coming ? ' needs a connection. One is on its way.'
                                           : ' needs a connection. Tap the banner to retry.'), true);
  }

  toast(msg, amber) {
    clearTimeout(this._toastT);
    this.setState({ toastMsg: msg, toastAmber: !!amber });
    this._toastT = setTimeout(() => this.setState({ toastMsg: '', toastAmber: false }), 2000);
  }

  go(s) { this.setState(p => ({ screen: s, stack: p.stack.concat([p.screen]) })); }

  /* The mint list, opened to switch mints.
   *
   * That one screen does three jobs, and trStep is the whole of what says
   * which: '' switches, 'from' and 'to' are the first two steps of a transfer
   * between your own mints (26a-transfer.js, 27-render-mints-restore-backup.js).
   * back() pops a screen and clears nothing, so a transfer dropped at "FROM
   * WHICH MINT?" left trStep set with no screen showing it: every later way
   * into the list — SWITCH, the balance pill, the mint warning, history —
   * opened it still asking which mint to move from, and tapping a mint began
   * a transfer nobody had asked for. There was no way back to switching short
   * of restarting Foxy.
   *
   * So the mode is never inherited: goTransfer names the job it wants, and
   * every other way in comes through here and names this one. */
  /* The pieces this phone is holding. Local, so it opens with no route — which is
   * the point: offline, whether an exact amount can be paid is the only question
   * that decides whether money can move at all. */
  goChange() { this.go('change'); }

  goSwitchMint(extra) {
    this.setState(p => Object.assign({
      screen: 'switchMint', stack: p.stack.concat([p.screen]),
      trStep: '', trFrom: '', trTo: '',
      // nor a card's question of which mint to move to (26f-flashcard.js)
      fcPick: false,
    }, extra || {}));
  }
  back() {
    this.setState(p => {
      const next = p.stack.length
        ? { screen: p.stack[p.stack.length - 1], stack: p.stack.slice(0, -1) }
        : { screen: 'home', stack: [] };
      return next;
    });
  }
  toggle(k) { this.setState(s => ({ open: Object.assign({}, s.open, { [k]: !s.open[k] }) })); }

  // a row: label, value, and the optional extras the shell reserves space for
  cfRow(label, value, opt) {
    const o = opt || {};
    return {
      label: label, value: value,
      ink: o.ink || 'var(--ink)',
      sub: o.sub || '',
      subH: o.sub ? '24px' : '0px',
      minH: o.reserve ? '69px' : '0px',
      shown: o.hidden ? '0' : '1',
      cursor: o.tap ? 'pointer' : 'default',
      tap: o.tap || (() => {}),
      badge: o.badge || '',
      basis: o.half ? '50%' : '100%',
      /* A row's value is 22px, which is right for a mint name and wrong for
       * four digits somebody is comparing against another phone held beside
       * this one. `big` matches the size the receiver shows them at, so the
       * two screens can be held together and read at a glance rather than
       * squinted at. */
      size: o.big ? '88px' : '22px',
    };
  }

  sendToText() {
    const s = this.state;
    if (s.recipientKind === 'email') return (s.recipient || '').toUpperCase();
    // an invoice is 200-odd characters and filled the screen; five each end is
    // enough to recognise it against what was pasted
    return this.shortId(s.recipient || '');
  }

  /** @typedef {{ label: string, go: () => void, filled?: boolean }} ConfirmSecondary */
  /** @typedef {{ title?: string, titleInk?: string, subtitle?: string, code?: string, amountLabel?: string,
   *    amount?: string, amountInk?: string, amountSub?: string, rows?: any[], warn?: string,
   *    chip?: string, secondary?: ConfirmSecondary, close?: () => void,
   *    cta?: string, ctaTone?: string, ctaBusy?: boolean,
   *    go?: () => void }} ConfirmSpec */
  /* What the confirmation shell shows (renderConfirmShell). */
  /** @returns {ConfirmSpec} */
  confirmSpec() {
    const s = this.state;
    const val = parseFloat(s.amount) || 0;
    // a scanned payment request reads like any other payment going out
    if (s.screen === 'reqOffer') return this.requestSpec();
    // moving money between your own mints (26a-transfer.js)
    if (s.screen === 'trConfirm') return this.transferSpec();
    // paying a Bitcoin address (26b-onchain.js)
    if (s.screen === 'ocConfirm') return this.onchainSpec();
    // a payer's bitcoin price, for a receiver with no route (26d-tap.js)
    if (s.screen === 'priceConfirm') return this.priceSpec();
    // paying somebody at another mint: the fee, and the only button that sends
    if (s.screen === 'crossConfirm') return this.crossSpec();
    // a card moved to another mint: what moves, what arrives, the fee (26f-flashcard.js)
    if (s.screen === 'fcMoveConfirm') return this.fcMoveSpec();
    // a card's limit, before it is set (26f-flashcard.js)
    if (s.screen === 'fcLimitConfirm') return this.fcLimitSpec();
    // sendConfirm
    const rows = [
      this.cfRow('DELIVERED TO', this.sendToText()),
      this.cfRow('PAYING FROM', s.payFrom || 'BITCOIN', { half: true }),
      this.cfRow('NETWORK', s.recipientKind === 'address' ? 'ON-CHAIN' : 'LIGHTNING', { half: true }),
      this.cfRow('ARRIVES', s.recipientKind === 'address' ? '~10 MINUTES' : 'INSTANTLY',
        { ink: s.recipientKind === 'address' ? 'var(--btc-ink)' : 'var(--acc)', half: true }),
      /* The fee, quoted before the payment rather than reported after it.
       *
       * "up to" because the reserve is a ceiling: routing usually costs less
       * and the remainder comes back as change. Naming a number that is
       * normally an overstatement is better than UNKNOWN, which is what this
       * said until the money had already gone. */
      /* Only the quote. Never sendFee.
       *
       * sendFee is written when a payment succeeds. Reading it here put the
       * last payment's fee on the next payment's confirmation, three separate
       * times, each with a different patch. The value simply does not belong
       * on a screen shown before the payment — a quote or nothing. */
      this.cfRow('FEE', s.quotedFee != null
        ? 'UP TO ' + this.money(s.quotedFee).main
        : s.quotingFee ? 'CHECKING…' : 'UNKNOWN',
        { half: true, sub: s.quotedFee != null ? this.money(s.quotedFee).sub : '' }),
    ];
    if ((s.note || '').trim()) rows.push(this.cfRow('NOTE', (s.note || '').trim()));
    /* The code is not a row any more: it is above the amount, the same size,
     * in the accent — the same place and shape as on the receiver's screen, so
     * the two can be held side by side and compared at a glance rather than
     * read. See cfCode in the render values. */
    const feeDue = s.quotedFee != null ? Math.max(0, Math.round(Number(s.quotedFee) || 0)) : 0;
    const shortOf = (() => {
      const W = window.FoxyWallet;
      if (s.recipientKind !== 'invoice' || !s.recipient || !W || !W.amountOf) return 0;
      const need = W.amountOf(s.recipient) || 0;
      const have = s.balSats || 0;
      /* With the fee the mint will hold back for it, once that is known. The
       * invoice alone fitting is not the payment fitting: a mint takes the
       * amount and a reserve for routing, and gives back what it does not
       * use. Two invoices a few hundred sats under the balance were offered
       * a SEND button here and refused a second later on the sending screen
       * with "needs N including the fee reserve, and you hold M". The quote
       * is on this screen already. */
      const owed = need + feeDue;
      return (need && owed > have) ? owed - have : 0;
    })();
    if (shortOf) {
      return {
        title: 'CONFIRMATION', amountLabel: 'SENDING',
        amount: this.sendAmountText(),
        amountInk: '#FF5C5C',
        rows: rows,
        warn: this.heldBlocks(shortOf) || 'More than your balance \u2014 short by ' + this.money(shortOf).main
          + (feeDue > 0 ? ' with the fee' : ''),
        cta: 'CLOSE', ctaTone: 'warn', go: () => this.back(),
      };
    }
    /* Typed in dollars: nothing can be sent until two price sources agree on
     * how many sats that is (checkSendPrice). */
    if (s.recipientKind !== 'invoice' && s.unit !== 'SATS' && s.sendPriceCheck !== 'agreed') {
      const failed = s.sendPriceCheck === 'failed';
      return {
        title: 'CONFIRMATION', amountLabel: 'SENDING',
        amount: '$ ' + this.usd(val),
        amountSub: failed ? '' : 'Checking the price with two sources\u2026',
        rows: rows,
        warn: failed ? 'Two price sources did not agree on the price of bitcoin, so Foxy cannot work out the sats. Nothing was sent.' : '',
        cta: failed ? 'TRY AGAIN' : 'CHECKING THE PRICE\u2026', ctaTone: failed ? 'warn' : 'go',
        go: failed ? () => this.checkSendPrice() : () => {},
      };
    }
    return {
      title: 'CONFIRMATION', amountLabel: 'SENDING',
      amount: this.sendAmountText(),
      // the converted figure sits under the primary one
      amountSub: (() => {
        const W = window.FoxyWallet;
        const inv = (s.recipientKind === 'invoice' && s.recipient && W)
          ? W.amountOf(s.recipient) : null;
        const v = parseFloat(this.state.amount) || 0;
        const st = inv || (this.state.unit === 'SATS' ? Math.round(v) : Math.round(v / this.px() * 1e8));
        if (inv || this.state.unit === 'SATS') return this.money(st).sub;
        // typed in dollars: the sats that will leave, and the price they were
        // worked out from, so a wrong price shows on the screen
        const sats = s.sendSats || st;
        return sats ? '\u20bf ' + this.group(sats) + ' at $ ' + this.group(Math.round(v / sats * 1e8)) + ' per bitcoin' : '';
      })(),
      rows: rows,
      // the DOM sheet, not openNote's template editor — that one renders on
      // top of this screen rather than replacing it, so both headers draw
      secondary: { label: (s.note || '').trim() ? 'EDIT NOTE' : 'ADD A NOTE', go: () => this.editSendNote(), filled: !!(s.note || '').trim() },
      /* Not until the fee is known. The balance check above needs it, and
       * the screen offered SEND for the second or two the mint took to say
       * what it would hold back — long enough to press it and find out on
       * the sending screen that the payment did not fit. While it is being
       * asked, the button says so and does nothing. */
      cta: (s.recipientKind === 'invoice' && s.quotingFee) ? 'CHECKING FEE\u2026' : 'SEND ' + this.sendAmountText(),
      ctaBusy: s.recipientKind === 'invoice' && !!s.quotingFee,
      ctaTone: 'go',
      go: (s.recipientKind === 'invoice' && s.quotingFee) ? () => {} : () => this.startSend(),
    };
  }

  /* Which of your mints issued this invoice, if any, and what you hold there.
   * Cheap: the decode is local, the lookup is a map in storage. */
  sendAmountText() {
    const s = this.state, W = window.FoxyWallet;
    // the invoice is the only figure that will actually leave the wallet
    const invSats = (s.recipientKind === 'invoice' && s.recipient && W)
      ? W.amountOf(s.recipient) : null;
    if (invSats) return this.money(invSats).main;
    const v = parseFloat(s.amount) || 0;
    if (s.unit === 'SATS') return this.money(Math.round(v)).main;
    /* Typed in dollars: the sats are what leaves, so they are the headline,
     * fixed when the confirmation opened (sendSats) and sent exactly. The
     * headline used to read "$20.00" while a wrong price, or one that changed
     * before the tap, decided how many sats went. */
    /* And the dollars are the headline again, with those
     * sats and their price on the line under it — still fixed, still sent
     * exactly, and still on the screen. */
    return '$ ' + this.usd(v);
  }
  // the daily card limit: $2,500 to start, $5,000 once an ID clears
  /* The note the screen in front of you is actually about.
   *
   * state.note belongs to a send or receive flow. The ecash token screen's
   * note belongs to the token and lives on its tag, written by editTokenNote
   * and read back with tagsFor. Reading state.note there showed a note left
   * over from an unrelated invoice.
   */
  noteShown() {
    const s = this.state;
    // the screen is 'tokenOut'; compared as 'tokenout' this never matched, and the
    // token screen showed the send's note instead of the token's own
    if (s.screen !== 'tokenOut') return s.note || '';
    const W = window.FoxyWallet;
    const out = (W && W.lastToken && W.lastToken()) || {};
    if (!out.hash || !W || !W.tagsFor) return '';
    return (W.tagsFor(out.hash) || {}).note || '';
  }

  // ---- account levels ----









  // verification is one-time: once verified we never ask again, we just do the thing.
  // external bank still has to be linked, and a withdraw resumes once it is.


  // a scanned invoice with no amount drops you into the same keypad as receive
  openTx(t) {
    this.setState(p => ({ screen: 'txDetail', stack: p.stack.concat([p.screen]), tx: t }));
    this.receiptCheck(t);
  }

  /* A payment locked to the phone that asked for it, looked at: the mint is
   * asked whether its pieces were spent, and by whose signature
   * (`lockedReceipt`). Once, as the screen opens; the answer is kept on the
   * payment's record, and the screen is drawn again when it changes anything.
   * Only where there is something to ask about and a way to ask. */
  receiptCheck(t) {
    const W = window.FoxyWallet;
    if (!t || t.dir !== 'out' || !t.hash || !W || !W.lockedReceipt || !W.auditTrail) return;
    if (this.offlineNow && this.offlineNow()) return;
    const rec = (W.auditTrail(t.hash) || [])[0];
    if (!rec || !rec.lockedTo || rec.slim || rec.spent || !(rec.inputs || []).length) return;
    W.lockedReceipt(t.hash).then((got) => {
      if (got && this.state.screen === 'txDetail' && this.state.tx && this.state.tx.hash === t.hash) {
        this.setState({ txReceiptAt: got.at });
      }
    }, () => {});
  }

  /* What `sats` of this entry were worth in cents when it settled, or null
   * where the entry carries no price of its own. `rate` is dollars per
   * bitcoin, written once by the wallet (`logTx`) and never again. */
  txFiat(t, sats) {
    const rate = Number(t && t.rate) || 0;
    if (!(rate > 0)) return null;
    return Math.round((Math.round(Number(sats) || 0) / 1e8) * rate * 100);
  }

  /* An amount, dollars first.
   *
   * People using this are thinking in dollars, so dollars are the figure and
   * the sats are the line under it. Every screen that
   * shows money asks here, so the rule is in one place: `main` is dollars
   * where there is a price to say them at and the sats where there is not —
   * never a dollar figure invented from no price — and `sub` is the sats
   * whenever dollars took the top line.
   *
   * `fiatCents` is a dollar amount already fixed, which history entries carry
   * from the moment they settled. Given, it is used as it stands and the
   * price of bitcoin today has no say in it. */
  money(sats, fiatCents) {
    const n = Math.round(Number(sats) || 0);
    const btc = '\u20bf ' + this.group(n);
    const fixed = fiatCents != null && isFinite(Number(fiatCents));
    const rate = this.satUsd ? this.satUsd() : 0;
    if (!fixed && !rate) return { main: btc, sub: '', usd: null };
    const usd = fixed ? Number(fiatCents) / 100 : n * rate;
    /* Not "$0.00" for something that is not nothing: a one-sat fee is under a
     * cent and is still a fee. */
    const text = (n > 0 && usd < 0.005) ? '< $ 0.01' : '$ ' + this.usd(usd);
    return { main: text, sub: btc, usd: usd };
  }

  usd(v) {
    if (v == null || !isFinite(v)) return '···';
    return v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }

  // a pasted invoice is 200-odd characters; five each end fits on one line
  shortId(v) { return v.length > 14 ? v.slice(0, 5) + '…' + v.slice(-5) : v; }

  /* Ask the mint what this invoice would cost. Commits to nothing. */
  quoteSendFee() {
    const W = window.FoxyWallet;
    const s = this.state;
    if (!W || !W.quoteFee) return;
    const inv = s.recipientKind === 'invoice' ? s.recipient : null;
    const target = inv || s.recipient || '';
    if (!target || this._quotedFor === target) return;
    this._quotedFor = target;

    /* Clear first, quote second.
     *
     * An earlier version only cleared when there was an invoice to quote. A
     * lightning address has none until LNURL resolves it during the send, so
     * that path kept the previous payment's fee on screen — a 200-sat payment
     * that cost 1, then a 9,862-sat payment still showing 1 when it cost 15.
     *
     * Where no quote is possible the row says UNKNOWN, which is true. */
    if (!inv) {
      this.setState({ quotingFee: false, quotedFee: null, sendFee: null });
      return;
    }
    /* Clear the last payment's fee.
     *
     * sendFee is written when a payment succeeds and was never cleared, and
     * the FEE row reads it before the quote. So a second payment showed the
     * first one's fee — a same-mint payment costing 0, followed by a
     * cross-mint one that actually cost 29, still displayed 0. A stale number
     * stated confidently is worse than UNKNOWN. */
    this.setState({ quotingFee: true, quotedFee: null, sendFee: null });
    W.quoteFee(inv).then(q => {
      this.setState({ quotingFee: false, quotedFee: q ? q.feeReserve : null });
    }).catch(() => {
      /* Let the next render try again. This was set before the request and
       * never cleared, and componentDidUpdate's guard then returned on every
       * pass — so one failed quote, which over Tor is ordinary, left the
       * confirmation reading UNKNOWN for that invoice for the whole session. */
      this._quotedFor = null;
      this.setState({ quotingFee: false });
    });
  }

  startSend() {
    const onchain = this.state.recipientKind === 'address';
    this.setState(p => ({ screen: 'sendDone', stack: p.stack.concat([p.screen]), sendPhase: onchain ? 'onchain' : 'in', etaLeft: 600 }));
    clearTimeout(this._sendA); clearTimeout(this._sendB); clearInterval(this._eta);
    if (onchain) {
      /* On chain settles in about ten minutes: the screen holds a live
       * countdown. It stops at zero — it used to go on calling setState every
       * second for the life of the app, a render a second behind whatever
       * screen the person had moved on to (the timer sweep). */
      this._eta = setInterval(() => this.setState(p => {
        const left = Math.max((p.etaLeft || 0) - 1, 0);
        if (!left) clearInterval(this._eta);
        return { etaLeft: left };
      }), 1000);
      return;
    }
    const W = window.FoxyWallet;
    if (!W || !W.connected) {
      // a card over the confirmation, rather than a screen instead of it
      this.blockedCard('netLost', {
        /* Back to the confirmation, as the failure path below does.
         *
         * The sending screen's only buttons are gated on onchainSending and
         * sentDone, and neither is set while sendPhase is 'in' — so with no
         * onClose here, closing this card left the person on a SENDING screen
         * with no button at all, and the edge swipe deliberately refuses to go
         * back while a send is in flight. The only way out was relaunching. */
        onClose: () => {
          if (this.state.screen === 'sendDone' || this.state.sendPhase) {
            this.setState({ screen: 'sendConfirm', sendPhase: null });
          }
        },
      });
      return;
    }
    // a lightning address has to be resolved into an invoice first
    const to = String(this.state.recipient || '');
    console.log('[foxy] send starting to', to.slice(0, 24),
      '|', (window.FoxyGate && window.FoxyGate.stamp) ? window.FoxyGate.stamp() : 'no gate');

    // Tor can drop while the app sits open, and a melt is the one call that
    // tells the mint where money went. The native side refuses it without Tor
    // either way; this gives a reconnect a moment, and says so if it does not.
    const G = window.FoxyGate;
    if (G && G.recheck) {
      const fresh = G.recheck();
      if (fresh && fresh.then) {
        return fresh.then(ok => {
          if (!ok) {
            // not silent: a send that stops with nothing on screen reads as a hang
            console.log('[foxy] send stopped: Tor is reconnecting');
            this.blockedCard('netLost', {
              title: 'RECONNECTING TO TOR',
              reason: 'Foxy lost its Tor connection and is getting it back. Nothing was sent.',
              onClose: () => {
                if (this.state.screen === 'sendDone' || this.state.sendPhase) {
                  this.setState({ screen: 'sendConfirm', sendPhase: null });
                }
              },
              retry: 'TRY AGAIN', back: '',
              go: () => this.startSend(),
            });
            return;
          }
          this.startSendNow(to);
        });
      }
    }
    return this.startSendNow(to);
  }

  /* A payment still going through: said so, with no way to pay it again.
   *
   * A pending melt used to show the settled screen, and a held one fell
   * through to CONNECTION LOST with TRY AGAIN — an invitation to pay twice. */
  showPayPending() {
    const W = window.FoxyWallet;
    this.blockedCard('payPending', {
      tone: 'warn',
      title: 'PAYMENT PENDING',
      reason: 'This payment is still going through. Foxy is holding the ecash and '
        + 'will settle it when the mint answers. Do not pay this again.',
      onClose: () => {
        this.setState({ screen: 'home', stack: [], sendPhase: null });
        this.refreshBalance();
        this.loadHistory();
      },
    });
    /* Twice: at 30 s for a payment that settles quickly, and at 150 s, past the
     * two minutes before the sweep gives back a hold that reads UNPAID or
     * PENDING with its ecash untouched. */
    if (W && W.sweepMelts) {
      [30000, 150000].forEach(ms => setTimeout(() => {
        W.sweepMelts().then(() => this.refreshBalance()).catch(() => {});
      }, ms));
    }
  }

  /* A payment typed in dollars: its sats come from a price two sources agree
   * on, asked for as the confirmation opens. The first source to answer used
   * to decide alone, and its sats were what went. Until an agreed price is in,
   * the confirmation cannot send; if no two sources agree, it says so. */
  checkSendPrice() {
    const W = window.FoxyWallet;
    const val = parseFloat(this.state.amount) || 0;
    const run = this._priceCheck = (this._priceCheck || 0) + 1;
    this.setState({ sendSats: null, sendPriceCheck: 'checking' });
    if (!W || !W.agreedRate) { this.setState({ sendPriceCheck: 'failed' }); return; }
    W.agreedRate().then(px => {
      if (run !== this._priceCheck || this.state.screen !== 'sendConfirm') return;
      const sats = Math.round(val / px * 1e8);
      this.setState(sats > 0 ? { sendSats: sats, sendPriceCheck: 'agreed' } : { sendPriceCheck: 'failed' });
    }, e => {
      if (run !== this._priceCheck || this.state.screen !== 'sendConfirm') return;
      console.warn('[foxy] send price:', e && e.message);
      this.setState({ sendPriceCheck: 'failed' });
    });
  }

  startSendNow(to) {
    const W = window.FoxyWallet;
    const P = window.FoxyProgress;
    // an invoice already held in a payment is not paid a second time
    const inv = String(to || '').trim().replace(/^lightning:/i, '');
    const want = inv.toLowerCase();
    // an invoice read from an uppercase QR is the same invoice; a lightning
    // address gets a fresh invoice every time, so it is matched by the address
    if (W && W.pendingMelts && W.pendingMelts().some(m => m && (
      (m.bolt11 && m.bolt11.toLowerCase() === want) || (m.payee && m.payee === want)))) {
      this.showPayPending();
      return;
    }
    /* One send at a time. The 150-second backstop below ends the wait, not
     * the payment: the wallet call keeps running, and a second send started
     * then queued behind it and paid again. */
    if (this._sendRun) {
      this.showPayPending();
      return;
    }
    console.log('[foxy] overlay module:', P ? (P.complete ? 'has complete()' : 'OLD - no complete()') : 'NOT LOADED');
    if (P) P.begin();
    const onStage = n => { console.log('[foxy] stage', n); if (P) P.stage(n); };
    /* A send that never answers must still end.
     *
     * A lightning address with no timeout on its fetches left the app on
     * "sending" indefinitely: the overlay finished, nothing rejected, and
     * there was no card and no way back. The fetches have deadlines now, but
     * a promise that never settles must not be able to strand the screen —
     * whatever the reason. This is the backstop, well beyond any individual
     * call's own limit. */
    /* Sats for an invoice that names none. Worked out the same way an LNURL's
     * are: typed in sats it is what was typed, typed in dollars it is only the
     * figure two price sources agreed on (checkSendPrice). `pay` refuses the
     * pair if the invoice does carry an amount, so this is never a way to send
     * something other than what the payee asked for. */
    const typed = this.state.unit === 'SATS' ? this.wantedSats() : (this.state.sendSats || 0);
    const run = W.classify(to) === 'lnurl'
      ? W.payLnurl(to, typed, '', onStage)
      : W.pay(to, onStage, W.amountOf(to) ? undefined : { sats: typed });
    this._sendRun = run;
    const settled = () => { if (this._sendRun === run) this._sendRun = null; };
    run.then(settled, settled);
    const job = Promise.race([
      run,
      // pending, not failed: the payment may still be going, so no TRY AGAIN
      new Promise((_, no) => setTimeout(() => {
        const e = new Error('This is taking longer than it should. '
          + 'Check your history before trying again \u2014 it may have gone through.');
        /** @type {any} */ (e).pending = true;
        no(e);
      }, 150000)),
    ]);
    job.then(r => {
      if (r && r.pending) {
        console.log('[foxy] send pending');
        if (P) P.end();
        W.tag(r.hash, { to: to, note: (this.state.note || '').trim() });
        this.showPayPending();
        return;
      }
      console.log('[foxy] send complete');
      W.tag(r.hash, { to: to, note: (this.state.note || '').trim() });
      // an invoice a tap offered: the other phone is told, over the link that is still open
      if (this.tapPaidByLightning) this.tapPaidByLightning(to);

      const showDone = () => {
        console.log('[foxy] showDone: switching to the confirmation');
        // tear the overlay down here too — whatever happens inside the module,
        // nothing from the send should survive into the confirmation
        if (P && P.end) P.end();
        // Straight to 'settled', in ONE state change. Going 'done' first and
        // 'settled' a beat later rendered the confirmation twice: once bare,
        // then again with its white flash and falling bolts, which belong to
        // the settled phase.
        /* On the instance, not in state.
         *
         * The fee went into state twice and was lost both times — once
         * cleared by the confirmation's quote, once written to a key nothing
         * set because the script that added it died on an assertion before
         * writing. A field on the component is set here and read during the
         * render this setState triggers, and nothing else can touch it. */
        this._lastFee = Math.max(0, Number(r.feeSats || 0));
        this.setState({ sendPhase: 'settled', sendFee: r.feeSats, note: '', noteDraft: '' });
      };

      // Nothing heavy runs while the burst is playing. refreshBalance() and
      // loadHistory() both fetch and then re-render a large tree, and doing
      // that here blocked the main thread through the whole completion — the
      // overlay's writes landed in memory but nothing repainted until the
      // thread freed up, which is why the confirmation appeared to overtake
      // an animation the log said had already finished.
      const settleUp = () => {
        console.log('[foxy] settleUp: refreshing balance and history now');
        // The refresh runs behind the overlay, so the pill already holds the
        // new figure by the time the confirmation is dismissed — and a count-up
        // from the new number to the new number shows nothing. Keep the old
        // one so the animation has somewhere to start.
        if (this._preSettle == null) this._preSettle = this.balNow();
        this.refreshBalance();
        this.loadHistory();
        // and the small pieces this payment used are made again, now
        if (this.tidyChangeNow) this.tidyChangeNow();
      };

      if (P && P.complete) {
        // Refresh WHILE the overlay still covers the screen, not after the
        // confirmation has landed. Doing it afterwards re-rendered the
        // confirmation and replayed its flash and falling bolts, which read as
        // the green screen arriving a second time.
        P.whenFull(settleUp);
        P.complete(showDone, 500);
      } else {
        this._sendA = setTimeout(() => { showDone(); settleUp(); }, 400);
      }
    }).catch(e => {
      const m = String((e && e.message) || '');
      console.error('[foxy] send failed:', e);
      if (P) P.end();
      // stopped by the person before it was made: they are home already
      if (e && e.foxyStopped) return;
      // held, not failed: the pending card, never TRY AGAIN
      if (e && e.pending) { this.showPayPending(); return; }
      // before the classification below, which would call "invalid" a refusal and offer TRY AGAIN
      if (this.isBadSignatures(e)) {
        this.badSignatureCard(null, 'pay', () => {
          if (this.state.screen === 'sendDone' || this.state.sendPhase) this.setState({ screen: 'sendConfirm', sendPhase: null });
        });
        return;
      }

      /* A card over the confirmation, not a screen instead of it.
       *
       * These four used to be full screens and they render black in this
       * build, so a failed send stranded you. The classification is unchanged;
       * only where it lands is. */
      /* A refusal is not a connection problem.
       *
       * Anything unrecognised used to land on netLost — "CONNECTION LOST" —
       * so a mint declining an already-paid invoice showed a connection card
       * with "Invoice already paid" written under it. The message was right
       * and the title sent people to check their wifi.
       *
       * The mint answering "no" is its own category: it replied, clearly, and
       * the answer was no. */
      const refused = /already paid|already spent|expired|not paid|quote|invalid|unsupported/i.test(m)
        /* A mint that will not pay an amountless invoice is saying no, clearly,
         * and it landed on CONNECTION LOST — which blames the network for an
         * answer the mint gave in 22 ms. Anything naming the mint and what it
         * will not do belongs with the other refusals. */
        || /does not pay|names no amount|already names an amount/i.test(m);
      /* Saying no to "Allow Foxy to contact this address" is not a connection
       * problem, and CONNECTION LOST blamed the network for the person's own
       * answer. It is about the address. */
      const kind = /did not allow Foxy/i.test(m) ? 'badAddress'
        : /insufficient|balance|not enough/i.test(m) ? 'sendFail'
        : /route|path/i.test(m) ? 'lnNoRoute'
        : /address|lnurl|answer|receive payments/i.test(m) ? 'badAddress'
        : refused ? 'mintRefused'
        : 'netLost';

      /* Off the sending screen now, not when the card is closed. A card that
       * was queued behind another never showed, the screen sat on SENDING, and
       * `sendPhase` stayed 'in', which also stops this phone listening for a
       * tap. */
      if (this.state.screen === 'sendDone' || this.state.sendPhase) {
        this.setState({ screen: 'sendConfirm', sendPhase: null, sendSlow: false });
      }

      // not enough money needs a different amount, not another attempt
      const again = (kind === 'sendFail') ? null : () => this.startSend();

      /* CLOSE must not strand you on the sending screen.
       *
       * blockedCard leaves you where you were, which is right when a failure
       * arrives over the home screen. Here the progress overlay has gone, the
       * payment did not happen, and that screen has nothing on it — closing
       * left no way out. Back to the confirmation, where the buttons are. */
      this.blockedCard(kind, {
        title: kind === 'mintRefused' ? 'THE MINT SAID NO' : undefined,
        reason: W.reason(e),
        retry: again ? 'TRY AGAIN' : 'CHANGE AMOUNT',
        back: again ? '' : 'amount',
        go: again,
        onClose: () => {
          /* Back to the send confirmation — 'sendConfirm', not 'confirm'.
           *
           * 'confirm' is the receive invoice screen. Sending someone there
           * after a failed payment is worse than the dead end it replaced. */
          if (this.state.screen === 'sendDone' || this.state.sendPhase) {
            this.setState({ screen: 'sendConfirm', sendPhase: null });
          }
        },
      });
    });
  }

  // an on-chain receive can't settle while you watch: close drops you home, then the
  // pending screen surfaces once the sender has broadcast
  closeReceive() {
    this.stopReceive();
    clearTimeout(this._slideWait);
    if (this._unlisten) this._unlisten();
    if (window.FoxyWallet) { window.FoxyWallet.stopPreview(); window.FoxyWallet.stopPasteButton(); }
    clearTimeout(this._sendA); clearTimeout(this._sendB); clearInterval(this._eta);
    this.setState({ screen: 'home', stack: [], noteOpen: false });
  }

  // leaving the pending receive: the confirmation lands a beat after the home screen does
  dismissPending() {
    if (this.state.sendExit) return;
    clearInterval(this._eta);
    clearTimeout(this._sendA); clearTimeout(this._sendB);
    this.setState({ sendExit: true });
    setTimeout(() => {
      this.setState({ screen: 'home', stack: [], recvPending: false, sendExit: false });
      this._sendA = setTimeout(() => this.setState(p => ({
        screen: 'paid', recvResolved: true, recv: Object.assign({}, p.recv, { live: 'in' }),
      })), 1000);
    }, 380);
  }

  // leaving the on-chain screen: the confirmation lands a beat after the home screen does
  dismissOnchain() {
    if (this.state.sendExit) return;
    clearInterval(this._eta);
    clearTimeout(this._sendA); clearTimeout(this._sendB);
    this.setState({ sendExit: true });
    setTimeout(() => {
      this.setState({ screen: 'home', stack: [], sendExit: false });
      this._sendA = setTimeout(() => this.setState({ screen: 'sendDone', sendPhase: 'done' }), 1000);
      this._sendB = setTimeout(() => this.setState({ sendPhase: 'settled' }), 2700);
    }, 380);
  }

  // on a real phone (narrow + touch) drop the mockup bezel and run full-bleed
  isRealDevice() {
    try {
      return window.matchMedia('(max-width: 600px)').matches
        || window.matchMedia('(display-mode: standalone)').matches
        || (window.navigator.standalone === true);
    } catch (e) { return false; }
  }
  applyShell() {
    const bare = this.isRealDevice();
    const el = this.shellRef && this.shellRef.current;
    if (el) {
      el.style.padding = bare ? '0' : '28px';
      el.style.minHeight = bare ? '100dvh' : '100vh';
      el.style.alignItems = bare ? 'stretch' : 'center';
      el.style.background = bare ? '#050505' : '#111214';
    }
    if (bare !== this.state.bare) this.setState({ bare });
  }
  // one shared context, created lazily. iOS starts it suspended until a gesture, so it is
  // resumed on the first touch and every play attempt thereafter.
  audioCtx() {
    if (this._ac === null) return null;
    if (!this._ac) {
      const Ctx = window.AudioContext || window.webkitAudioContext;
      if (!Ctx) { this._ac = null; return null; }
      try { this._ac = new Ctx(); } catch (e) { this._ac = null; return null; }
    }
    if (this._ac.state === 'suspended') { try { this._ac.resume(); } catch (e) {} }
    return this._ac;
  }

  // note: [frequency, startOffset, duration, peakGain, waveform]
  tone(notes) {
    const ac = this.audioCtx();
    if (!ac || ac.state !== 'running') return;
    const t0 = ac.currentTime;
    notes.forEach(n => {
      const osc = ac.createOscillator();
      const gain = ac.createGain();
      osc.type = n[4] || 'sine';
      osc.frequency.setValueAtTime(n[0], t0 + n[1]);
      // a ramp to zero rather than a hard stop, or the cut sounds like a click
      gain.gain.setValueAtTime(0.0001, t0 + n[1]);
      gain.gain.exponentialRampToValueAtTime(n[3], t0 + n[1] + 0.012);
      gain.gain.exponentialRampToValueAtTime(0.0001, t0 + n[1] + n[2]);
      osc.connect(gain).connect(ac.destination);
      osc.start(t0 + n[1]);
      osc.stop(t0 + n[1] + n[2] + 0.02);
    });
  }

  sound(kind) {
    if (this.state.soundOff) return;   // hook for a future Settings toggle
    if (kind === 'success') {
      // rising major triad — the confirmation chime
      this.tone([[880, 0, 0.16, 0.16], [1174.66, 0.055, 0.16, 0.15], [1567.98, 0.11, 0.30, 0.13]]);
    } else if (kind === 'error') {
      // two low square blips falling away: the denial buzz
      this.tone([[196, 0, 0.13, 0.10, 'square'], [155, 0.115, 0.20, 0.09, 'square']]);
    } else {
      // popups: a soft, quiet tick so 29 cards never become noisy
      this.tone([[660, 0, 0.05, 0.035]]);
    }
  }

  haptic(kind, silent) {
    // The send path reaches a confirmation through two state changes a beat apart
    // (sendPhase done -> settled, and the dismissOnchain timers), so the same event can
    // ask to be felt twice. One buzz of a given kind per 1.2s.
    const now = Date.now();
    this._hapLast = this._hapLast || {};
    if (now - (this._hapLast[kind] || 0) < 1200) return;
    this._hapLast[kind] = now;

    if (!silent) this.sound(kind);
    const bridge = (window.webkit || {}).messageHandlers;
    if (bridge && bridge.foxy) {
      try { bridge.foxy.postMessage({ haptic: kind }); return; } catch (e) {}
    }
    // Android WebViews and desktop Chrome do support the web API
    if (navigator.vibrate) {
      navigator.vibrate(kind === 'success' ? [18, 60, 26] : kind === 'warning' ? [30, 80, 30] : 14);
    }
  }

  // every popup/sheet flag, so a card appearing can be felt without wiring each one
  POPUP_KEYS = ['noteOpen','bankRemoveOpen','ccOpen','mapAsk','bizHoursSheet','mapPlaceSheet','mapFilters',
    'acctSheetOpen','bkAsk','posRailSheet','rangeOpen','removeConfirmOpen','addConfirmOpen',
    'advSheet','biz','ctSearch','mapSearch','locating'];

  // Confirmations, errors and popups all buzz, each keyed so a re-render cannot repeat one.
  // Errors and popups are compared as sets: what matters is a flag going from off to ON.
  syncHaptics() {
    const s = this.state;
    if (this.props.startStatic || this.props.startScreen) return;   // review pages stay silent

    // ---- confirmations: one buzz on arrival ----
    // sendPhase walks in -> onchain -> done -> settled on the same screen; only the
    // settled/confirmed moment is a completion
    // sendPhase advances done -> settled on the same screen a beat apart, so keying on the
    // phase buzzed twice. One buzz per visit to the screen instead.
    const done = (s.screen === 'sendDone' && (s.sendPhase === 'done' || s.sendPhase === 'settled')) ? 'sendDone'
      : s.screen === 'paid' ? 'paid:' + (s.payOut ? 'out' : 'in')
      : '';
    if (done !== this._hapDone) {
      this._hapDone = done;
      if (done) this.haptic('success');
    }

    // ---- errors: the sharper double tap ----
    // _amtOver is stashed by renderVals, which owns the balance/limit maths
    const errs = [
      this._amtOver ? 'amt' : '',
      s.pinMismatch ? 'pin' : '',
      s.clWarnKey ? 'cl:' + s.clWarnKey : '',
      s.screen === 'feeTooLow' ? 'feeTooLow' : '',
      s.screen === 'sendFail' ? 'sendFail' : '',
    ].filter(Boolean).join('|');
    if (errs !== this._hapErr) {
      const before = this._hapErr || '';
      this._hapErr = errs;
      // only a NEW error, so clearing one never buzzes
      if (errs.split('|').filter(Boolean).some(e => before.indexOf(e) < 0)) this.haptic('error');
    }

    // ---- popups: a light tap as the card lands ----
    const open = this.POPUP_KEYS.filter(k => !!s[k])
      .concat((s.photoIdx !== null && s.photoIdx !== undefined) ? ['photo'] : []).join('|');
    if (open !== this._hapPop) {
      const before = this._hapPop || '';
      this._hapPop = open;
      if (open.split('|').filter(Boolean).some(k => before.indexOf(k) < 0)) this.haptic('tap');
    }
  }

  // widgets live in a separate process and cannot read the page, so the current accent,
  // currency and Lightning address are pushed to Swift, which stores them in the App Group.
  pushToNative() {
    const bridge = (window.webkit || {}).messageHandlers;
    if (!bridge || !bridge.foxy) return;
    const id = AC(this) || 'green';
    const a = ACC_OF(id);
    // Foxy has no lightning address. This used to build one against a
    // custodial service the project has no relationship with, and post it
    // to a widget target that does not exist.
    const payload = { username: (this.state.un || '').trim() };
    const key = JSON.stringify(payload);
    if (key === this._nativeKey) return;   // only on real change
    this._nativeKey = key;
    try { bridge.foxy.postMessage(payload); } catch (e) {}
  }

  /* Deep links: the Swift shell loads index.html#foxy=<target>, so a widget tap
   * lands on the right screen instead of wherever the app was left.
   *
   * A Debug build also registers a URL scheme, and turns `foxy://receive?amt=50&unit=sat`
   * into the same hash with its parameters (FoxyWebView.receiveDeepLink). Putting a
   * simulator on a screen with an amount already on it took a dozen taps; it now takes
   * one `xcrun simctl openurl` (DEVICE-TESTS.md, "Driving Foxy from outside").
   *
   * THE PARAMETERS ARE A DEBUG AFFORDANCE, AND NOTHING ELSE. A link that can put a
   * wallet on a send screen with an amount filled in is an attack surface, so it exists
   * in one build only, three times over: Release registers no scheme, the Swift that
   * receives one is compiled out, and the reads below are fenced behind window.FOXY_DEBUG
   * — set by a document-start script that itself sits inside #if DEBUG. A Release build
   * handed one of these hashes anyway opens the bare screen, as it always did.
   *
   * Every parameter is checked against what it is allowed to be and dropped when it is
   * not: an unknown key, a bad value and a missing one are all simply absent. Nothing
   * here throws — half a link should still land somewhere sensible.
   */
  applyDeepLink() {
    const hash = String(location.hash || '');
    const m = /[#&]foxy=([a-z]+)/i.exec(hash);
    if (!m) return false;
    const target = m[1].toLowerCase();
    const W = window.FoxyWallet;
    const go = (patch) => this.setState(Object.assign({ stack: [] }, patch));
    const done = () => {
      try { history.replaceState(null, '', location.pathname + location.search); } catch (e) {}
      return true;
    };

    // '' unless this is a Debug build and the hash carries that key
    const raw = (name) => {
      if (!window.FOXY_DEBUG) return '';
      const p = new RegExp('[#&]' + name + '=([^&]*)', 'i').exec(hash);
      if (!p) return '';
      let v = p[1];
      try { v = decodeURIComponent(v); } catch (e) {}
      return v.trim();
    };
    /* An amount the keypad could have produced, in the unit being shown: digits, at
     * most two decimal places in dollars and none in sats, and more than nothing.
     * '' means "they did not say", which leaves the keypad empty as before. */
    const amountFor = (unit) => {
      const v = raw('amt');
      if (!/^[0-9]{1,9}(\.[0-9]{1,2})?$/.test(v)) return '';
      if (unit === 'SATS' && v.indexOf('.') >= 0) return '';
      if (!(parseFloat(v) > 0)) return '';
      return v.replace(/^0+(?=[0-9])/, '');
    };
    const unitOr = (fallback) => {
      const u = raw('unit').toUpperCase();
      if (u === 'SAT' || u === 'SATS') return 'SATS';
      if (u === 'USD') return 'USD';
      return fallback;
    };
    // the app's own names for the networks, matched ignoring the hyphen: onchain, ON-CHAIN
    const railIn = (rails) => {
      const r = raw('rail').toUpperCase().replace(/[^A-Z]/g, '');
      if (!r) return '';
      return rails.filter(x => x.replace(/[^A-Z]/g, '') === r)[0] || '';
    };

    /* `foxy://nfc` opened the payer's tap screen. There is no such screen:
     * this phone listens from home and from SEND, so home is where a link
     * that meant "get ready to tap" now goes. */
    if (target === 'nfc') { go({ screen: 'home' }); return done(); }
    if (target === 'home') { go({ screen: 'home' }); return done(); }
    if (target === 'send') { go({ screen: 'sendHow', flow: 'send' }); return done(); }

    if (target === 'receive') {
      const unit = unitOr('USD');
      const rail = railIn(['LIGHTNING', 'CASHU', 'ON-CHAIN']);
      /* A receive opens on the network this wallet defaults to, and openReceiveNow reads
       * that default when NEXT is pressed — so naming one here has to set the default,
       * or the screen would move back to Lightning one tap later. recvRail is set too,
       * so the NETWORK chip is already right on the way in. */
      if (rail && W && W.defaultRail) { try { W.defaultRail(rail); } catch (e) {} }
      go(Object.assign({
        screen: 'amount', flow: 'receive', asset: '', network: '',
        amount: amountFor(unit), unit: unit,
        note: '', noteDraft: '',
        // these belong to sending; left set, they decide what the receive screen shows
        recipient: '', recipientKind: '',
      }, rail ? { recvRail: rail } : {}));
      return done();
    }

    /* The one send-side screen with an amount on it that needs no payee: making an
     * ecash token (renderSend's goMakeEcash). Dollars, as that screen opens. */
    if (target === 'token') {
      const unit = unitOr('USD');
      go({
        screen: 'amount', flow: 'send', tokenMode: true, asset: 'BITCOIN',
        amount: amountFor(unit), unit: unit,
        recipient: '', recipientKind: '', note: '', noteDraft: '',
      });
      return done();
    }

    /* Splitting a bill. Its keypad counts in cents, the way it is typed — amt=200 is
     * the $2.00 that spAmtNext is the minimum for — and on chain is not a way to
     * collect a share, so it is not one here (goSplit). */
    if (target === 'split') {
      const cents = raw('amt');
      const rail = railIn(['LIGHTNING', 'CASHU']);
      go({
        screen: 'spAmount',
        spAmt: /^[0-9]{1,9}$/.test(cents) && parseInt(cents, 10) > 0
          ? String(parseInt(cents, 10)) : '0',
        spWays: 4, spIdx: 0, spAssigns: [], spPaid: [], spShares: null, spInvoices: [],
        spRail: rail || ((W && W.defaultRail && W.defaultRail() === 'CASHU') ? 'CASHU' : 'LIGHTNING'),
        spEditIdx: -1, spEditBuf: '', spCopied: -1, spShared: -1, spFromWaiting: false,
      });
      return done();
    }

    return false;
  }


  /* wallet wiring */

  // loads the wallet layer, then either reconnects or asks for a pairing scan
  bootWallet() {
    this.mirrorConsole();
    this.watchEdgeSwipe();
    // Tor comes first. Until it connects, or the person chooses to continue
    // unprotected, the native side refuses every mint call, price and address
    // lookup; the gate's screens only say why.
    this._gateThenBoot = () => {
      const G = window.FoxyGate;
      if (!G) return this.bootWalletNow();
      // The verifying screen is held open across the wallet search, so the
      // app's own SEARCHING FOR WALLET screen never gets a frame to itself.
      const done = () => {
        if (G.holdVerify) G.holdVerify(false);
        /* Home first, no screen of the gate's ever went up, so nothing told
         * the phone the page had the screen: the splash would sit over a
         * loaded home screen for the eight seconds of its backstop. */
        if (G.uncover && !G.visible()) G.uncover();
      };
      if (G.holdVerify) G.holdVerify(true);
      return G.check(() => this._gateThenBoot()).then(ok => {
        // Tor could not connect: that screen is up with RETRY and CONTINUE UNPROTECTED
        if (!ok) { this.setState({ walletSearching: false }); return done(); }
        // An already-connected wallet must not be booted again: reconnecting
        // lands on the home screen, which is why passing the gate mid-session
        // threw you off whatever screen you were on.
        const W = window.FoxyWallet;
        /* The price, started beside the mint rather than behind it.
         *
         * The launch screen waits for the balance, and the balance waits for
         * the price (refreshBalance). The price needs no mint — only a route,
         * which passing the gate has just proved — so it used to sit idle for
         * the whole of connect and then take its own two to ten seconds after
         * it. rate() shares a request already in flight, so the ask inside
         * refreshBalance joins this one rather than starting a second. */
        if (W && W.rate) W.rate().catch(() => {});
        if (W && W.connected) return done();
        return Promise.resolve(this.bootWalletNow()).catch(() => {}).then(done);
      }).catch(done);
    };
    if (this.props.startStatic) return;
    this.watchKeyboard();
    this.watchWake();
    this.armKeyboardPrimer();
    // the gate lives outside the runtime, so it has to ask for a render
    window.__foxyGateChanged = () => this.setState({ gateTick: Date.now() });
    const load = src => new Promise((ok, no) => {
      if (document.querySelector('script[src="' + src + '"]')) return ok();
      const el = document.createElement('script');
      el.src = src; el.onload = ok; el.onerror = () => no(new Error(src + ' did not load'));
      document.head.appendChild(el);
    });
    load('qrcode.js')
      // only present on the ecash build; the LNbits build has no such file and
      // must not fail because of it
      .then(() => load('cashu-ts.js').catch(() => {}))
      // no bip39.js: the words are made, shown and checked on the phone, never in this page
      .then(() => load('foxy-send-progress.js').catch(() => {}))
      // and its receiving counterpart: "verifying ecash" (FoxyReceiving)
      .then(() => load('foxy-receive-progress.js').catch(() => {}))
      // and the one for a token from a mint you do not use (FoxyMoving)
      .then(() => load('foxy-move-progress.js').catch(() => {}))
      .then(() => load('foxy-tor-gate.js').catch(() => {}))
      .then(() => load('foxy-wallet.js'))
      /* The seed comes in here, and nowhere earlier.
       *
       * bootWallet is what loads foxy-wallet.js, so nothing before this line
       * can ask the wallet for anything. An earlier version waited for the
       * wallet in componentDidMount and made bootWallet wait for that — a
       * circle, broken only by a timeout, after which the app booted with no
       * wallet, found no seed, and generated one over a real one. */
      .then(() => {
        const W = window.FoxyWallet;
        /* Redraw when the route changes, so the home banner is never a moment
         * behind what it is telling the person about their IP address. */
        if (W.onPrivacy) W.onPrivacy(() => {
          this.setState({ routeAt: Date.now() });
          this.sayBackOnline();
          this.connectForRealOnceOnline();
          this.claimWhenRouteReturns();
        });
        // A mint whose signatures do not match the keys it publishes is broken
        // or singling this wallet out. Said plainly, with nothing to retry.
        if (W.onMintTrouble) {
          W.onMintTrouble((t) => {
            if (t.badSignatures) { this.badSignatureCard(t.mint, t.where); return; }
            if (t.keysetsUnseen) {
              this.blockedCard('mintTrouble', {
                tone: 'warn',
                title: 'THIS MINT MAY BE MARKING THIS WALLET',
                reason: t.mint + ' gave this wallet signing keys it does not show to anyone else. '
                  + 'Ecash signed with them could be recognised wherever it is spent. '
                  + 'Your ecash is kept. Consider moving your balance to another mint.',
              });
              return;
            }
            this.blockedCard('mintTrouble', {
              tone: 'warn',
              title: 'THIS MINT FAILED A SIGNATURE CHECK',
              reason: t.mint + ' issued ' + t.invalid + ' proof' + (t.invalid === 1 ? '' : 's')
                + ' whose signature does not match the keys it publishes. The ecash is kept, '
                + 'but a mint doing this may be marking this wallet. Consider moving your balance to another mint.',
            });
          });
        }
        // Ecash a payment found spent elsewhere was taken out of the balance: said.
        if (W.onSpentElsewhere) {
          W.onSpentElsewhere((r) => {
            this.toast(this.group(r.sats) + ' sats of your ecash had already been spent elsewhere, '
              + 'so they are no longer in your balance.', true);
            this.refreshBalance();
            this.offerQuarantine();
          });
        }
        // A paid invoice that will not claim is said, not only logged.
        if (W.onClaimTrouble) W.onClaimTrouble((hit) => this.showStuckInvoice(hit));
        /* The one question the wallet cannot answer for itself: both phones are
         * offline and a payment has arrived that nothing here can settle. The
         * card returns the person's answer, and no handler at all means no — so
         * a build without this line takes no money on trust rather than taking
         * it silently. */
        if (W.onOfflineOffer) W.onOfflineOffer((info) => this.offlineRiskCard(info));
        if (W.onChangeStuck) W.onChangeStuck((info) => this.changeStuckCard(info));
        if (W.onChangeMaking) W.onChangeMaking((info) => this.changeMaking(info));
        if (W.onTrustLost) W.onTrustLost((info) => this.trustLostCard(info));
        if (W.onTrustSettled) W.onTrustSettled((info) => this.trustSettled(info));
        // the launch screen has gone: the tap may listen now (26d-tap.js)
        if (!this._gateDownHeard) {
          this._gateDownHeard = true;
          window.addEventListener('foxy-gate-down', () => {
            if (this.syncTap) this.syncTap();
            // and the camera may come back to a scan screen (syncPreview)
            if (this.syncPreview) this.syncPreview();
          });
          window.addEventListener('foxy-gate-up', () => { if (this.syncPreview) this.syncPreview(); });
        }
        if (W.onLateClaim) W.onLateClaim((info) => this.moneyIsSafe(info));
        /* A payment Foxy was closed in the middle of making. The mint had made
         * it, so it is rebuilt from what was written down and put on its own
         * entry — but it never reached the other phone, and the person has to
         * be told or it sits in history as a payment that looks sent. */
        if (W.onSendRebuilt) W.onSendRebuilt((info) => {
          this.refreshBalance();
          if (this.loadHistory) this.loadHistory();
          if (info && info.change) return;
          this.toast('A payment was cut short when Foxy closed. It is in your history, ready to hand over.', true);
        });
        /* A payment taken at a payer's mint and not home yet, looked at by
         * the wallet on a launch or a connection: landed, on its way, to be
         * asked about, or sent back (26d-tap.js `carryOutcome`). */
        if (W.onCarry) W.onCarry((r) => { if (this.carryOutcome) this.carryOutcome(r, {}); });
        // a crossing of this phone's own, finished late: the sats are at the mint it paid toward
        if (W.onMoveFinished) W.onMoveFinished((info) => {
          this._seenTx = this._seenTx || {};
          if (info && info.quote) this._seenTx[info.quote] = true;
          this.refreshBalance();
          if (this.loadHistory) this.loadHistory();
          const at = this.mintNameOf ? (this.mintNameOf(info && info.to) || 'the other mint') : 'the other mint';
          this.toast(this.group(Math.round(Number(info && info.sats) || 0)) + ' sats you moved have arrived at ' + at + '.');
        });
        /* Ecash another phone refused and did not send back, settled now
         * that there is a route: safe again, or found redeemed. */
        if (W.onAtRisk) W.onAtRisk((info) => {
          this.refreshBalance();
          if (this.loadHistory) this.loadHistory();
          const sats = this.group(Math.round(Number(info && info.sats) || 0));
          if (info && info.state === 'taken') {
            this.blockedCard('atRiskTaken', {
              tone: 'warn',
              title: 'THEY TOOK THE PAYMENT',
              reason: 'A payment they refused was redeemed afterwards: ' + sats + ' sats. Its entry in your history now says paid.',
              chip: 'If they are sending it back, they will show you a code to scan. If they were paid a second time for it, that is theirs to give back.',
            });
          } else if (info && info.state === 'refunded') {
            this.toast('The ' + sats + ' sats they refused came back, locked to this phone.');
          } else if (info && info.state === 'safe') {
            this.toast('The ' + sats + ' sats they refused are safe again.');
          }
        });
        // a payment somebody refused, swapped back into the wallet by itself
        if (W.onTakenBack) W.onTakenBack((info) => {
          this.refreshBalance();
          if (this.loadHistory) this.loadHistory();
          this.toast('The ' + this.group(Math.round(Number(info && info.sats) || 0)) + ' sats they did not take are back in your wallet.');
        });
        // back on a network and caught up: fill the small-change pool again
        W._putAway = (on) => this.putAway(on);
        /* The lock at boot (18-lifecycle-and-chart.js) runs before the wallet
         * is on the page, and with no wallet it cannot know a PIN is set: a
         * phone killed and reopened came up on its last screen with no PIN
         * asked, while a return from the background asked it. Asked here
         * instead, once, now that the wallet can say. */
        if (!this._lockedOnce && this.pinLock) this.pinLock();
        if (W.onCaughtUp) W.onCaughtUp(() => {
          console.log('[foxy] small change: connected and caught up; checking the pool');
          this.refreshBalance();
          if (this.tidyChangeLater) this.tidyChangeLater();
        });
        // the phone turned over: the invoice screen follows (syncFlip)
        if (W.onTurned) W.onTurned((on) => this.setState({ upsideDown: !!on }));
        /* The paying phone's price, for a request this phone made in dollars.
         * Nothing has moved: the card is a person agreeing to a number, and
         * only their ACCEPT sends the request back in sats. */
        if (W.onTapQuote) W.onTapQuote((text) => this.tapPriceOffered(text));
        // the payer says it has paid this screen's invoice over Lightning (26d-tap.js)
        if (W.onTapPaid) W.onTapPaid((info) => this.tapPaidNotice(info));
        // A mint that has stopped answering, once a session per mint (11-mint-risk.js).
        if (W.onMintDown) W.onMintDown((mint) => this.mintDownNotice(mint));
        if (W.stuckInvoices) {
          // ones left over from an earlier launch, once the first sweep has had its go
          setTimeout(() => W.stuckInvoices().forEach(hit => this.showStuckInvoice(hit)), 15000);
        }
        /* No screen in this page shows the words any more: the phone's own
         * screens hide them from a recording and warn after a screenshot. */
        if (W.captureCheck) W.captureCheck();
        /* The native side says when Foxy returns, and for how long it was away.
         * watchWake registers for that when it first runs, which can be before
         * this script had loaded, and then the registration silently never
         * happened: every return reached the app only through page events,
         * which carry no time away, so the confirming screen never showed at
         * once after a long absence. Registering again here is harmless. */
        if (W.onResume && this._onWake) W.onResume(this._onWake);
        /* After the lock, not beside it. The seed lives in a keychain item that
         * needs Face ID or the passcode; read while the lock screen is up, it
         * asked for its own Face ID on top of the lock's. Read after a Face ID
         * unlock, the unlock's approval covers it. */
        /* Home first, the home screen is what is drawn, and the phone's
         * cover comes off it now rather than at its own four seconds. With
         * the lock up, the lock says so itself (pinLock, 10-pin.js). */
        const G0 = window.FoxyGate;
        if (G0 && G0.isHomeFirst && G0.isHomeFirst() && !this._pinLocked && !G0.visible() && G0.uncover) G0.uncover();
        return this.pinUnlocked().then(() => {
          /* One screen from here to a loaded balance: Tor, the mint, then the
           * balance. It used to come down once the mint answered, so the home
           * screen showed before its balance had loaded. */
          const G = window.FoxyGate;
          if (G && G.holdVerify) G.holdVerify(true);
          if (G && G.showLaunch) G.showLaunch();
          /* The seed read is the Face ID prompt, so the fox starts running
           * here — through the asking, not after it. */
          if (G && G.introStart) G.introStart();
          return W.seedReady ? W.seedReady() : null;
        });
      })
      .then(r => {
        /* Face ID is behind us — the seed read is what asks for it — so the
         * intro can run now. Starting it earlier meant the fox was halfway
         * through his stretch while the prompt was still up. It runs whether the seed was read or not: a phone that
         * refused is a screen the person is looking at either way. */
        const G = window.FoxyGate;
        if (G && G.introGo) G.introGo();
        return r;
      })
      .then(() => this._gateThenBoot())
      .catch(e => {
        console.warn('[wallet]', e);
        // nothing else is coming to take the launch screen down
        const G = window.FoxyGate;
        if (G && G.introGo) G.introGo();
        if (G && G.holdVerify) G.holdVerify(false);
        if (G && G.visible && G.visible() && G.hide) G.hide();
        this.setState({ walletErr: String(e && e.message || e) });
      });
  }

  /* Everything past the gate: runs once Tor is up or the person chose to
   * continue. Resolves once the balance has loaded, the mint has failed three
   * times, or 45 seconds have passed; the launch screen stays up until then. */
  bootWalletNow() {
    const W = window.FoxyWallet;
    const saved = W.saved();
    const G = window.FoxyGate;
    if (G && G.launchStage) {
      const url = (saved && saved.url) || W.defaultMint;
      /* The step is named for the log's sake, not the screen's: the launch
       * screen shows one title and never says which mint this is. */
      G.launchStage('mint', 60, 92);
    }
    return new Promise(settled => {
      this.settleLaunch();                       // an earlier boot's wait ends here
      this._launchSettled = settled;
      // a mint that neither answers nor refuses does not hold the screen for good
      this._launchCapT = setTimeout(() => this.settleLaunch(), 45000);
      // A saved mint is used as saved; only a fresh install takes the default.
      // Falling back from one to the other would hide the balance held at the
      // saved mint, which is exactly what per-mint storage exists to prevent.
      /* Home first, the wallet is built from what is on file, at once, and
       * the mint is spoken to behind the home screen. */
      const fromFile = !!(G && G.isHomeFirst && G.isHomeFirst());
      this.retryConnect(saved && saved.url ? undefined : W.defaultMint, 0, fromFile);
    });
  }

  /* Back from the background: a private connection set up again, as at
   * launch, and the home screen only once the balance has loaded. Tor went
   * off the network as Foxy left, and the native side is setting it up now;
   * nothing is tried on the connection from before. The same screen as
   * launch: CONNECTING TO TOR, then Loading your balance. */
  setUpAfterReturn() {
    const G = window.FoxyGate;
    const W = window.FoxyWallet;
    if (!G || !W) return null;
    // never got as far as a wallet: that is launch, and launch's boot does it
    if (!W.connected) return this._gateThenBoot ? this._gateThenBoot() : null;
    if (this._returning) return this._returning;
    const run = this.pinUnlocked().then(() => {
      /* Back with the connection Foxy left with: nothing to set up, so no
       * screen about setting it up.
       *
       * The native side keeps Tor on the network for a few seconds after Foxy
       * is put away, and up to twenty while a payment is with the mint, so a
       * glance at another app comes back to a circuit that never went down
       * ("nothing to set up", TorService.resumed). The launch screen went up
       * over it all the same and played its ending: a second and a half of
       * SECURING YOUR CONNECTION after one second away, with SEND's camera
       * dark behind it. Asked of the phone now, not read from what the page
       * last heard: a circuit taken down while Foxy was away says so here. */
      const asked = W.refreshPrivacy ? W.refreshPrivacy().catch(() => null) : Promise.resolve(null);
      return asked.then(() => {
        if (G.connected && G.connected() && !G.visible()) {
          console.log('[foxy] back with the connection still up; no connection screen');
          // and the phone's cover over the return comes off now, not after its four seconds
          if (G.uncover) G.uncover();
          return 'quiet';
        }
        G.holdVerify(true);
        G.showLaunch();
        const checked = G.check(() => this.setUpAfterReturn());
        /* Working offline, the launch screen does not go up either, and the
         * cover was left to its four seconds on every return. Whatever the
         * reason, a return that puts up nothing says so. */
        if (G.uncover && !G.visible()) G.uncover();
        return checked;
      });
    }).then(ok => {
      // CANNOT CONNECT or Orbot is on screen; clearing it runs this again
      if (!ok) { G.holdVerify(false); return; }
      // with no screen up there is none to move along, and none to let go of
      const quiet = ok === 'quiet';
      if (!quiet) G.launchStage('balance', 60, 100);
      this.listenWallet();
      this.loadHistory();
      const swept = W.resumeSweeps ? W.resumeSweeps().catch(() => {}) : null;
      return Promise.race([
        Promise.resolve(this.resumeLoad()).catch(() => {}),
        new Promise(r => setTimeout(r, 20000)),
      ]).then(() => {
        if (!quiet) G.holdVerify(false);
        // paid while away, or a melt that settled: the balance again once swept
        if (swept) swept.then(() => this.refreshBalance());
      });
    }).catch(() => { G.holdVerify(false); })
      .then(() => { this._returning = null; });
    this._returning = run;
    return run;
  }

  /* The launch screen may come down: the balance loaded, or the mint would not. */
  settleLaunch() {
    clearTimeout(this._launchCapT);
    const settled = this._launchSettled;
    this._launchSettled = null;
    if (settled) settled();
  }

  // two scans: address, then admin key. The admin key covers invoices too.
  /* What to call this mint in a sentence.
   *
   * mintHost() gives an address — mint.minibits.cash/Bitcoin — which is right
   * for a list and wrong for prose. This gives the name: Minibits.
   *
   * Derived rather than tabulated, so a mint nobody has heard of still gets a
   * reasonable name. The table is only for the ones where capitalising the
   * first letter reads wrong. */
  MINT_NAMES = { westernbtc: 'WesternBTC', minibits: 'Minibits', coinos: 'Coinos',
                 macadamia: 'Macadamia' };

  mintName() {
    return this.mintNameOf(this.mintHost());
  }

  /* A mint's short name from its address: its own in MINT_NAMES, else the
   * first label after "mint.". */
  mintNameOf(url) {
    const host = String(url || '').replace(/^https?:\/\//, '');
    if (!host) return '';
    const domain = host.split('/')[0].replace(/^mint\./i, '');
    const label = domain.split('.')[0].toLowerCase();
    return this.MINT_NAMES[label] || (label.charAt(0).toUpperCase() + label.slice(1));
  }

  mintHost() {
    const W = window.FoxyWallet;
    return (W && W.mintHost && W.mintHost()) || '';
  }

  /* Working offline, and the connection came back.
   *
   * The choice is surrendered by the wallet itself the moment Tor is really up
   * (`_privacy`), and the banner turns from OFFLINE to SECURE with it. That is a
   * quiet change on a screen somebody may not be looking at, and they have been
   * living without a connection — so it is said out loud, once. */
  sayBackOnline() {
    const W = window.FoxyWallet;
    const p = (W && W.privacy && W.privacy()) || {};
    const offline = !!p.offline;
    const secure = p.tor === 'up' && p.network !== 'none';
    /* Said out loud only when the phone had really been without a network.
     * Every session starts offline now and is online a few seconds later,
     * and a toast for that is noise: the banner turning is the news. */
    if (offline && p.network === 'none') this._offlineDark = true;
    if (this._wasOffline && !offline && secure) {
      if (this._offlineDark) this.toast('Back online \u2014 connected over Tor');
      this._offlineDark = false;
      // and anything that was waiting on a route can go now
      this.refreshBalance();
      this.loadHistory();
    }
    this._wasOffline = offline;
    /* The price line is asked for once at launch and once when the wallet is
     * ready. Offline, both are refused, and nothing asked again — so a phone
     * that came online later showed the price with no line under it. Asked on every route change that has a route; `loadSeries`
     * answers at once when the line is already there or on its way. */
    if (secure && !offline && !((this.state.series || {})[this.state.range])) {
      this.loadSeries(this.state.range);
    }
  }

  /* Money waiting on a route, the moment there is one.
   *
   * Everything that claims what is waiting hangs off `connect()`: its sweep
   * chain runs `claimUnclaimed` on a launch or a mint switch. Neither happens
   * when a network comes back mid-session — so a payment taken on trust while
   * both phones were offline sat in history as AT RISK with wifi in the room,
   * and the red ring turned until the app was restarted (the circuit came up
   * and nothing was claimed after it).
   *
   * That row is the one that matters most: it is the only money in Foxy that
   * somebody else can still take away, and every second it stays unswapped is a
   * second they can. Asked on every route change, which is cheap — the claim
   * answers at once when the list is empty — and guarded so a flapping route
   * cannot stack them. */
  claimWhenRouteReturns() {
    const W = window.FoxyWallet;
    if (!W || !W.claimUnclaimed || !W.connected) return;
    const p = (W.privacy && W.privacy()) || {};
    if (!(p.tor === 'up' || p.unprotected)) return;
    if (p.network === 'none') return;
    /* And what was left between two mints, which needs a route just as much:
     * a crossing to claim, a payment to bring home, a refusal to take back. */
    if (!this._crossingsOnRoute && W.crossingsWaiting && W.crossingsWaiting()) {
      this._crossingsOnRoute = true;
      console.log('[foxy] a route came back and something is waiting between two mints');
      W.catchUpCrossings().then(() => {
        this._crossingsOnRoute = false;
        this.refreshBalance(); this.loadHistory();
      }, () => { this._crossingsOnRoute = false; });
    }
    if (this._claimingOnRoute) return;
    const waiting = (() => {
      try { return (W.trustedWaiting && W.trustedWaiting().length) || W.unclaimedSats() > 0; }
      catch (e) { return false; }
    })();
    if (!waiting) return;
    this._claimingOnRoute = true;
    console.log('[foxy] a route came back and something is waiting to be swapped in');
    W.claimUnclaimed().then((took) => {
      this._claimingOnRoute = false;
      if (took) { this.refreshBalance(); this.loadHistory(); }
    }, () => { this._claimingOnRoute = false; });
  }

  /* A wallet built with no route was built from what the mint said last time:  /* A wallet built with no route was built from what the mint said last time:
   * its keysets may have rotated since, nothing paid while the phone was away
   * has been claimed, and no sweep has run. So the moment there is a route,
   * connect again for real — once, and only for such a wallet.
   *
   * Without this the phone works perfectly offline and then stays offline-shaped
   * for the rest of the launch: a route appears, the banner says so, and the
   * wallet is still the one assembled from storage. */
  connectForRealOnceOnline() {
    const W = window.FoxyWallet;
    if (!W || !W.fromCache || !W.fromCache()) return;
    const p = (W.privacy && W.privacy()) || {};
    if (!(p.tor === 'up' || p.unprotected)) return;
    if (this._catchUpConnect) return;
    if (p.network === 'none') return;
    this._catchUpConnect = true;
    const url = W.mintUrl;
    console.log('[foxy] a route is up and this wallet came from storage \u2014 connecting to', url, 'for real');
    /* Behind whatever the person is doing. This went through `retryConnect`,
     * whose `walletReady` puts the home screen up and empties the back stack:
     * right for a launch, and a jump out of RECEIVE or a payment for somebody
     * who had started one in the seconds before the mint answered. Every
     * launch is such a wallet now, so the catch-up only connects, and then
     * refreshes what is shown. A failure changes nothing (`connect` keeps the
     * wallet it had) and is tried again: 3s, 6s, 12s, then every 30s. */
    const again = (attempt) => {
      W.connect(url).then(() => {
        this.refreshBalance();
        this.loadHistory();
        this.offerQuarantine();
      }, (e) => {
        console.warn('[foxy] the connect behind the home screen failed, attempt', attempt + 1, '\u2014', W.reason(e));
        const still = W.fromCache && W.fromCache();
        if (!still) return;
        clearTimeout(this._catchUpT);
        this._catchUpT = setTimeout(() => again(attempt + 1), Math.min(3000 * Math.pow(2, attempt), 30000));
      });
    };
    again(0);
  }

  /* There is no screen to park on any more, so a mint that will not load is
   * simply tried again — 3s, 6s, 12s, then every 30s. A mint that is briefly
   * down recovers without the person doing anything. */
  retryConnect(url, attempt, fromFile) {
    const W = window.FoxyWallet;
    clearTimeout(this._reconnectT);
    return W.connect(url, null, null, fromFile ? { fromCache: true } : undefined).then(w => {
      const balance = this.walletReady(w);
      /* The mint is not asked about every proof held, here or on a return: the
       * same list each launch let it know this wallet over any exit. Ecash
       * spent elsewhere is found when a payment picks it (onSpentElsewhere). */
      this.offerQuarantine();
      if (fromFile) {
        /* Home first: the sats are local and the last price is on file, so
         * there is nothing to hold the home screen back for. It waited for the
         * price walk, up to twelve seconds behind the phone's splash now that
         * no connection screen stands there. And the mint is spoken to for
         * real the moment there is a route, which may be now. */
        this.settleLaunch();
        this.connectForRealOnceOnline();
        // the balance is on its way to the screen by itself; a price that would not load is not a failed connect
        Promise.resolve(balance).catch(() => {});
        return null;
      }
      if (!this._launchSettled) return;
      const G = window.FoxyGate;
      if (G && G.launchStage) G.launchStage('balance', 92, 100);
      // the price can walk every source; 20 seconds at most, as on a return
      return Promise.race([
        Promise.resolve(balance).catch(() => {}),
        new Promise(r => setTimeout(r, 20000)),
      ]).then(() => this.settleLaunch());
    }).catch(e => {
      const why = W.reason(e);
      console.warn('[foxy] connect failed, attempt', attempt + 1, '\u2014', why);
      /* Hold the searching screen through the first two tries.
       *
       * A failed connect says nothing about the balance — the proofs are in
       * local storage and are still there. Announcing "no wallet" on attempt
       * one turned an ordinary Tor retry into an alarming screen, while the
       * retry quietly succeeded a few seconds later. */
      if (attempt >= 2) {
        this.setState({ walletSearching: false, walletErr: why });
        this.settleLaunch();                     // the home screen, with the error, rather than waiting on
      }
      if (attempt === 2) this.toast(why, true);
      const wait = Math.min(3000 * Math.pow(2, attempt), 30000);
      this._reconnectT = setTimeout(() => this.retryConnect(url, attempt + 1, fromFile), wait);
    });
  }

  /* Every mint the app knows to look at. The switch screen's list and this
   * one are the same set; if one grows the other should. */
  /* The mints on offer: the ones shipped with the app, then anything this
   * device has connected to since — a QR scan puts a mint here, which is what
   * makes it reachable again after switching away. */
  DEFAULT_MINTS = [
    { url: 'https://mint.minibits.cash/Bitcoin', name: 'Minibits mint',
      host: 'mint.minibits.cash', tint: '#4E7BE8' },
    /* Coinos was here and was taken out for being unreliable. A phone that has used it still lists it, from its own
     * record of the mints it has connected to. */
    { url: 'https://mint.westernbtc.com', name: 'WesternBTC',
      host: 'mint.westernbtc.com', tint: '#C9822F' },
    { url: 'https://mint.macadamia.cash', name: 'macadamia Mint',
      host: 'mint.macadamia.cash', tint: '#8A5A2B' },
    /* Test mints. The ecash they issue is backed by nothing and is worthless
     * by design — they exist so the money paths can be exercised without
     * spending anything. Named so that is unmistakable, and last in the list.
     *
     * The fee-charging one is not redundant: Foxy's fee handling has only ever
     * run against a mint that charges none. */
    { url: 'https://nofee.testnut.cashu.space', name: 'TEST MINT \u00b7 fake money',
      host: 'nofee.testnut.cashu.space', tint: '#6B6B6B', test: true },
    { url: 'https://testnut.cashu.space', name: 'TEST MINT \u00b7 fake money, with fees',
      host: 'testnut.cashu.space', tint: '#6B6B6B', test: true },
  ];

  allMints() {
    const strip = u => String(u || '').replace(/^https?:\/\//, '').replace(/\/+$/, '');
    /** @type {{ url: string, name: string, host: string, tint: string, logo?: string, test?: boolean }[]} */
    const out = this.DEFAULT_MINTS.slice();
    const known = out.map(m => strip(m.url));
    const W = window.FoxyWallet;
    const seen = (W && W.mints) ? W.mints() : [];
    seen.forEach(url => {
      if (known.indexOf(strip(url)) >= 0) return;
      known.push(strip(url));
      // a mint nobody shipped: no logo, and its host stands in for a name
      out.push({ url: url, name: strip(url), host: strip(url), logo: '', tint: '#5A5A5A' });
    });
    return out;
  }

  knownMints() {
    return this.allMints().map(m => m.url);
  }

  /* Rows land one at a time rather than all at the end — a mint can take five
   * seconds, and six of them behind a single spinner is a long silence.
   *
   * The words are typed on the phone's own screen and never reach this page;
   * the phone answers with a candidate that holds them, and that is what is
   * scanned. A retry scans the same candidate, or this wallet's own seed once
   * the candidate was adopted. Cancelled: nothing happens. */
  runSeedScan(onlyFailed) {
    const W = window.FoxyWallet;
    if (this.state.rsBusy) return;
    if (onlyFailed) return this.scanSeedRows(true, this.state.rsCandidate ? { candidate: this.state.rsCandidate } : null);
    if (this._rsEntering) return;
    this._rsEntering = true;
    return Promise.resolve().then(() => W.enterSeedNative()).then(candidate => {
      this._rsEntering = false;
      this.scanCandidate(candidate);
    }, e => {
      this._rsEntering = false;
      this.setState({ rsErr: W.reason(e) });
    });
  }

  /* RESTORE from the menu: the phone's RESTORE A WALLET screen over home, and
   * the restore screen only once there are words to look for balances with.
   * Cancelled, nothing changes and home is where it was. */
  restoreFromMenu() {
    const W = window.FoxyWallet;
    if (!W || !W.enterSeedNative || this.state.rsBusy || this._rsEntering) return;
    this._rsEntering = true;
    return Promise.resolve().then(() => W.enterSeedNative()).then(candidate => {
      this._rsEntering = false;
      if (!candidate) return;
      this.setState(p => ({
        screen: 'importSeed', stack: p.stack.concat([p.screen]),
        rsRows: [], rsErr: '', rsBusy: false, rsKept: '',
      }));
      this.scanCandidate(candidate);
    }, e => {
      this._rsEntering = false;
      this.toast(W.reason(e), true);
    });
  }

  /* Words entered on the phone's screen, as a candidate: look for balances. */
  scanCandidate(candidate) {
    if (!candidate) return;
    this._rsCandidates = this._rsCandidates || new Set();
    this._rsCandidates.add(candidate);
    this.setState({ rsCandidate: candidate });
    this.forgetRestoreCandidates(candidate);     // an earlier one, never adopted
    this.scanSeedRows(false, { candidate: candidate });
  }

  /* The scan itself, of this wallet's seed (null) or a candidate. */
  scanSeedRows(onlyFailed, words) {
    const W = window.FoxyWallet;
    const urls = onlyFailed
      // a partial row — a keyset that did not answer — is asked again too
      ? (this.state.rsRows || []).filter(r => r.state === 'failed' || r.partial).map(r => r.url)
      : this.knownMints();
    if (!urls.length) return;

    this.setState(p => ({
      rsBusy: true, rsErr: '', rsKept: '', rsAdopted: false,
      rsRows: onlyFailed ? (p.rsRows || []).filter(r => r.state !== 'failed' && !r.partial) : [],
    }));

    this._rsScanning = true;
    W.scanSeed(words, urls, row => {
      // The seed may already have been adopted while this was still running —
      // a mint that answers now still belongs to it, so it is written here
      // rather than being dropped when the screen goes away.
      if (this.state.rsAdopted && row.state === 'done' && (row.sats > 0 || this.rowUnits(row).length)) {
        /* Merged, not overwritten. The words were adopted a moment ago, so
         * the pile at this mint may still hold proofs from the seed they
         * replaced. An overwrite with no words counted those as rebuildable
         * and dropped them — recoverable only with the old words. A merge
         * keeps everything; a spent proof kept here goes at the next
         * reconcile.
         *
         * adoptScan runs in the wallet's proof lock and answers with a
         * promise, so the balance is read after it lands, and a failure is
         * logged rather than lost in a try that could never see it. */
        Promise.resolve().then(() => W.adoptScan([row], { merge: true })).then(() => {
          console.log('[foxy] late arrival kept:', row.host, row.sats, 'sats');
          if (window.FoxyWallet.mintHost() === row.host) this.refreshBalance();
        }).catch(e => console.warn('[foxy] late arrival not kept:', row.host, W.reason(e)));
      }
      this.setState(p => {
        const rows = (p.rsRows || []).slice();
        const at = rows.map(r => r.url).indexOf(row.url);
        if (at >= 0) rows[at] = row; else rows.push(row);
        return { rsRows: rows };
      });
    }).then(() => {
      this.setState({ rsBusy: false });
      this.seedScanEnded();
    }).catch(e => {
      this.setState({ rsBusy: false, rsErr: W.reason(e) });
      this.seedScanEnded();
    });
  }

  /* A candidate left to forget while its scan was running goes now, unless
   * the restore screen still has it as the words to adopt. */
  seedScanEnded() {
    this._rsScanning = false;
    if (!this._rsForgetLater) return;
    this._rsForgetLater = false;
    const restoring = this.state.screen === 'importSeed' || this.state.screen === 'rsConfirm';
    this.forgetRestoreCandidates(restoring ? this.state.rsCandidate : null);
  }

  /* Words typed on the phone for RESTORE stay there under their candidate
   * until forgotten: when the restore screens are left, after a candidate was
   * adopted (it is the phone's seed by then), and when new words replace it.
   * Never while a scan may still be asking with it — that waits for the scan to
   * end (seedScanEnded), so a mint answering late is still restored. `keep`
   * names one to leave. */
  forgetRestoreCandidates(keep) {
    const W = window.FoxyWallet;
    if (!this._rsCandidates || !this._rsCandidates.size || !W || !W.forgetSeedCandidate) return;
    if (this._rsScanning) { this._rsForgetLater = true; return; }
    this._rsCandidates.forEach(id => {
      if (id === keep) return;
      this._rsCandidates.delete(id);
      Promise.resolve().then(() => W.forgetSeedCandidate(id))
        .catch(e => console.warn('[foxy] the phone did not forget restore words:', W.reason(e)));
    });
  }

  /* A row was tapped. Nothing is written yet — this only stages the choice
   * and shows what it would cost. */
  pickRestoreMint(row) {
    if (!row || row.state !== 'done') return;
    this.setState(p => ({
      screen: 'rsConfirm',
      stack: p.stack.concat([p.screen]),
      rsPick: row, rsPickErr: '', rsBusy: false,
    }));
  }

  /* Confirmed. The entered phrase becomes this device's seed and EVERY mint
   * that answered is written, not just the one tapped — the tap decides where
   * you land, not what is kept. Anything still being scanned is picked up by
   * runSeedScan as it arrives. */
  adoptRestoreMint() {
    const W = window.FoxyWallet;
    const row = this.state.rsPick;
    if (!row || this.state.rsBusy2) return;
    // the candidate of words typed on the phone, which the phone adopts first
    const candidate = this.state.rsCandidate || null;
    const found = (this.state.rsRows || []).filter(r => r.state === 'done' && (r.sats > 0 || this.rowUnits(r).length > 0));
    const keep = found.length ? found : [row];

    // landing on the chosen mint is a switch like any other
    if (this.refuseSwitchWhileBusy()) return;

    this.setState({ rsBusy2: true, rsPickErr: '' });
    const total = keep.reduce((n, r) => n + r.sats, 0);

    /* Adopt, wait, and only then connect.
     *
     * adoptScan runs in the wallet's proof lock and answers with a promise.
     * This used to call it inside a try and connect straight away: a refusal
     * arrived as a rejection the try never saw, rsPickErr stayed empty, and
     * the app went on to the mint as if the words had been written. */
    Promise.resolve().then(() =>
      // the seed goes in once, with the first write
      W.adoptScan(keep, candidate ? { overwrite: true, candidate: candidate } : { overwrite: true })
    ).then(() => {
      console.log('[foxy] adopted', keep.length, 'mints,', total, 'sats');
      return W.connect(row.url);
    }).then(w => {
      // rsAdopted keeps the scan writing as later mints answer; the rows are
      // left alone so a scan in flight still has somewhere to land
      this.setState({ rsBusy2: false, rsPick: null, rsAdopted: true });
      // the adopted words are the phone's seed now; their candidate goes once no scan needs it
      if (candidate) {
        this.setState({ rsCandidate: null });
        this.forgetRestoreCandidates(null);
      }
      this.walletReady({ name: (w && w.name) || row.host });
      // other units are named in their own, never added to the sat total
      const inUnits = keep.reduce((a, r) => a.concat(this.rowUnits(r)), []);
      this.toast((keep.length > 1
        ? 'Restored ' + this.group(total) + ' sats across ' + keep.length + ' mints'
        : 'Restored on ' + row.host)
        + (inUnits.length ? ', and ' + inUnits.map(u => this.unitMoney(u.amount, u.unit)).join(' + ') + ' in other units' : ''));
    }).catch(e => {
      this.setState({ rsBusy2: false, rsPickErr: W.reason(e) });
    });
  }

  /* Pull-to-refresh, by hand.
   *
   * There is no touch binding in the runtime, so the list is handed over as a
   * ref and the gesture is attached directly. Only fires when the list is
   * already at the top, so it never fights an ordinary scroll.
   */
  histRef(el) {
    if (!el || el === this._histEl) return;
    this._histEl = el;

    const bar = document.createElement('div');
    bar.style.cssText =
      'position:absolute;left:0;right:0;top:0;height:56px;display:flex;' +
      'align-items:center;justify-content:center;pointer-events:none;' +
      'font-family:SatSymbol,Sora,system-ui,sans-serif;font-size:15px;font-weight:800;' +
      'letter-spacing:.06em;color:rgba(255,255,255,.55);opacity:0;' +
      'transition:opacity .15s ease';
    bar.textContent = 'PULL TO REFRESH';
    el.style.position = el.style.position || 'relative';
    el.appendChild(bar);

    let y0 = null, pulled = 0, busy = false;
    const READY = 64;

    el.addEventListener('touchstart', e => {
      y0 = el.scrollTop <= 0 ? e.touches[0].clientY : null;
      pulled = 0;
    }, { passive: true });

    el.addEventListener('touchmove', e => {
      if (y0 === null || busy) return;
      pulled = e.touches[0].clientY - y0;
      if (pulled <= 0) { bar.style.opacity = '0'; el.style.transform = ''; return; }
      // resistance, so it feels like pulling against something
      const shift = Math.min(pulled * 0.4, 72);
      el.style.transform = 'translateY(' + shift + 'px)';
      bar.style.opacity = String(Math.min(shift / READY, 1));
      bar.textContent = shift >= READY * 0.9 ? 'RELEASE TO REFRESH' : 'PULL TO REFRESH';
    }, { passive: true });

    const finish = () => {
      if (y0 === null) return;
      const go = pulled * 0.4 >= READY * 0.9 && !busy;
      y0 = null; pulled = 0;
      el.style.transition = 'transform .22s cubic-bezier(.2,.9,.25,1)';
      el.style.transform = '';
      setTimeout(() => { el.style.transition = ''; }, 240);
      if (!go) { bar.style.opacity = '0'; return; }

      busy = true;
      bar.textContent = 'REFRESHING\u2026';
      bar.style.opacity = '1';
      // the mint is not asked about every proof held (see retryConnect)
      Promise.resolve(this.refreshBalance())
        .then(() => this.loadHistory())
        .catch(() => {})
        .then(() => {
          busy = false;
          bar.style.opacity = '0';
          bar.textContent = 'PULL TO REFRESH';
        });
    };
    el.addEventListener('touchend', finish, { passive: true });
    el.addEventListener('touchcancel', finish, { passive: true });
  }

  /* Hear when a token is redeemed, within seconds where that gives nothing away.
   *
   * The wallet keeps the watch (FoxyWallet.watchTokenClaim, 05-paying-this-mint.js)
   * and asks about the token's fingerprints alone, on a circuit of its own. The
   * timing is here, each wait random within its range:
   * - A token made with a swap: the first question 15 to 45 seconds after it,
   *   so the mint cannot tie the question, and the token, to that swap.
   * - A token made from pieces already held (no swap), or any token after a
   *   return from the background: the first question in 2 to 4 seconds. There
   *   is no swap in that moment for it to be tied to.
   * - After that, every 3 to 5 seconds for its first two minutes, 15 to 30
   *   seconds until ten, then 1 to 2 minutes, for a day; and 2 to 3 seconds
   *   again when Tor was not up to ask.
   * Every token is watched on every screen. A token redeemed while its ECASH
   * TOKEN screen is open gets the payment confirmation; anywhere else, a note
   * (a confirmation two hours later interrupted another
   * payment). */
  /* How long to wait before asking the mint again whether a sent token has
   * been redeemed. A range, not a figure: an exact cadence is a pattern at the
   * mint, and every wallet asking on the same beat is easier to tell apart.
   *
   * `watching` is for a token on its own screen. Someone standing there has
   * handed over a QR code and is waiting for one thing only, and until now
   * they waited for it on the same ladder as a token nobody is looking at:
   * three to five seconds between asks, and up to forty-five before the FIRST
   * ask on a token just made. So the person who redeemed it saw their money
   * arrive while the person who sent it watched a screen that had not caught
   * up. While they are looking, it is asked about roughly
   * once a second; the moment they leave, the ordinary ladder takes over. */
  CLAIM_WAITS = { watching: [900, 1500], first: [15000, 45000], quick: [2000, 4000],
    soon: [3000, 5000], later: [15000, 30000], rarely: [60000, 120000], offline: [2000, 3000] };

  claimWait(kind) {
    const [lo, hi] = this.CLAIM_WAITS[kind];
    return lo + Math.floor(Math.random() * (hi - lo + 1));
  }

  /* How long until the next question about a watch that has been running `age`
   * ms. `onScreen` is that token shown on the ECASH TOKEN screen right now. */
  claimWaitFor(age, onScreen) {
    if (onScreen) return this.claimWait('watching');
    return this.claimWait(age < 120000 ? 'soon' : age < 600000 ? 'later' : 'rarely');
  }

  /* This token is the one the ECASH TOKEN screen is showing. */
  tokenOnScreen(hash) {
    return this.state.screen === 'tokenOut' && !!hash && this.state.tokenOutHash === hash;
  }

  /* Opening a token's own screen: ask about it now, not on whatever the ladder
   * had scheduled — which for a token just made is up to 45 seconds away. */
  tokenWatchNow() {
    const hash = this.state.tokenOutHash;
    if (!hash) return;
    this._claimNext = this._claimNext || {};
    if (this._claimNext[hash] !== Infinity) this._claimNext[hash] = 0;   // not mid-question
    this.claimWatchTick();
  }

  watchToken(sats, hash, quick) {
    const W = window.FoxyWallet;
    if (!W || !W.watchTokenClaim || !hash) return;
    if (!W.watchTokenClaim(hash, { persist: true, quick: !!quick })) return;
    this._claimNext = this._claimNext || {};
    this._claimNext[hash] = Date.now() + this.claimWait(quick ? 'quick' : 'first');
    this.claimWatchTick();
  }

  /* After a return from the background: every watch is asked about within seconds. */
  claimWatchResume() {
    const W = window.FoxyWallet;
    this._claimNext = {};
    if (W && W.watchedTokens) {
      W.watchedTokens().forEach(r => { this._claimNext[r.hash] = Date.now() + this.claimWait('quick'); });
    }
    this.claimWatchTick();
  }

  claimWatchTick() {
    const W = window.FoxyWallet;
    clearTimeout(this._claimT);
    /* No wallet on the page yet: ask again rather than never.
     *
     * This is ticked from a screen as well as from a watch (the ECASH TOKEN
     * screen's DONE), and a tick that lands before the wallet script has
     * loaded used to return leaving no timer — the same shape as the on-chain
     * watcher's dead pass. */
    if (!W || !W.watchedTokens) {
      this._claimT = setTimeout(() => this.claimWatchTick(), 20000);
      return;
    }
    this._claimNext = this._claimNext || {};
    // a watch kept from before every token was watched on every screen
    W.watchedTokens().forEach(r => { if (!r.persist) W.dropTokenWatch(r.hash); });
    const live = W.watchedTokens();
    /* Nothing being watched needs no timer: unlike an on-chain deposit, a
     * watch cannot appear on its own — watchToken makes one and ticks, and a
     * return calls claimWatchResume. */
    if (!live.length) return;
    const now = Date.now();
    let soonest = Infinity;
    live.forEach(r => {
      if (this._claimNext[r.hash] == null) this._claimNext[r.hash] = now + this.claimWait(r.quick ? 'quick' : 'first');
      soonest = Math.min(soonest, this._claimNext[r.hash]);
    });
    this._claimT = setTimeout(() => this.claimWatchDue(), Math.max(0, soonest - now));
  }

  /* Every path out of this asks again.
   *
   * The token has already left this wallet; this loop is the only thing that
   * ever turns its history entry green and clears the text out of the notes.
   * The chain below re-ticks on both settlements, but a throw before the
   * chain is built — no wallet on the page, or a mint call that fails on the
   * spot rather than in a promise — used to end the watching for the rest of
   * the session, the way every early return in onchainWatch did. */
  claimWatchDue() {
    const W = window.FoxyWallet;
    if (!W || !W.watchedTokens) { this.claimWatchTick(); return; }
    const now = Date.now();
    this._claimNext = this._claimNext || {};
    const due = W.watchedTokens().filter(r => (this._claimNext[r.hash] || 0) <= now);
    // one question at a time, so two tokens are not asked about in the same second
    const r = due[0];
    if (!r) { this.claimWatchTick(); return; }
    this._claimNext[r.hash] = Infinity;
    // a mint call that throws where it stands still leaves the loop a timer
    let asked;
    try { asked = W.tokenClaimState(r.hash); } catch (e) { asked = Promise.reject(e); }
    Promise.resolve(asked).then(st => {
      if (st === 'offline') { this._claimNext[r.hash] = Date.now() + this.claimWait('offline'); return; }
      if (st !== 'claimed') {
        this._claimNext[r.hash] = Date.now()
          + this.claimWaitFor(Date.now() - (r.since || 0), this.tokenOnScreen(r.hash));
        return;
      }
      /* The watch may have ended while the question was out: the token taken
       * back into this wallet (dropTokenWatchesFor), whose own redemption is
       * the SPENT this answer reports. Seen on a phone: a token pasted back
       * in was noted as redeemed 130 ms later. */
      if (!W.watchedTokens().some(x => x.hash === r.hash)) { delete this._claimNext[r.hash]; return; }
      W.dropTokenWatch(r.hash);
      delete this._claimNext[r.hash];
      W.settleTx(r.hash);
      // claimed: its text has no reason to stay in the notes or the audit trail
      if (W.forgetClaimedToken) W.forgetClaimedToken(r.hash);
      if (W.lastTokenHash() === r.hash) W.clearLastToken();
      const onItsScreen = this.state.screen === 'tokenOut' && this.state.tokenOutHash === r.hash;
      if (this.state.tokenOutHash === r.hash) {
        this.setState({ tokenOut: '', tokenOutSats: 0, tokenCopied: false, tokenForPayee: false });
      }
      this.refreshBalance();
      this.loadHistory();
      console.log('[foxy] token claimed:', r.sats, 'sats', onItsScreen ? '(on its screen)' : '(a note)');
      if (onItsScreen) {
        this.announcePayment({ dir: 'out', sats: r.sats, hash: 'tokenclaim-' + r.hash, to: 'ecash', tokenHash: r.hash });
      } else {
        this.toast('Your ecash token for ' + this.group(r.sats) + ' sats was redeemed');
      }
    }).catch(() => {
      this._claimNext[r.hash] = Date.now() + this.claimWait('later');
    }).then(() => this.claimWatchTick());
  }

  /* The ECASH TOKEN screen's QR code, animated for a token of more than two
   * proofs (FoxyWallet.tokenQrAnimates): one code for such a token was too
   * dense for some cameras. A new frame every 200 ms, the same UR frames
   * cashu.me shows, so cashu.me and Foxy read them (06-animated-qr.js). The
   * code is drawn as large as the screen allows. Each frame is drawn straight
   * into the image, not through a render; renderToken shows the latest one. */
  /* Nothing is drawn on a token's animated code, so its frames carry the
   * lightest error correction and two and a half times the data.
   *
   * Every code in Foxy had the badge in its middle, and the badge covers
   * modules a reader needs: a frame at 'L' can lose 7% of its codewords and
   * the badge took 12%, so the frames were raised to 'Q' to be read at all.
   * That paid for a picture with half of every frame. A frame that is missed
   * is made up by the ones after it (that is what the fountain is for), which
   * a still code has no way to do; so the badge stays on still codes and
   * comes off the ones that move (`tokenQrBadge`), and the frames go back to
   * 'L'. With the compact mode asked for (`FoxyWallet.qr`), a fragment of
   * 500 is 89 modules where one of 200 was 97: fewer frames, and each
   * drawn larger. tests/qr-readable.js holds both. */
  TOKEN_QR = { fragment: 500, everyMs: 200, ecc: 'L' };

  /* A request too dense for one code is animated too, and that code has the
   * TAP button in its middle, which is a control and stays. So these frames
   * keep the heavy correction the button needs.
   *
   * And are smaller. A fragment of 200 made a frame of 97 modules, which is
   * 2.3 points each in the 240-point box this screen has on the smallest
   * phone, under the 3 a camera wants; the test meant to hold that line
   * measured a frame less than half as long as a real one. At 150, in the
   * compact mode, a frame is 69 modules and 3.1 points. */
  REQ_QR = { fragment: 150, everyMs: 200, ecc: 'Q' };

  /* How much of a code the badge in its middle hides, as a fraction of the
   * width of the whole box. The markup draws it at 50 points inside 240. */
  QR_BADGE = 50 / 240;

  syncTokenQr() {
    const W = window.FoxyWallet;
    const shown = this.state.screen === 'tokenOut'
      ? (this.state.tokenOut || ((W && W.lastToken && W.lastToken()) || {}).token || '') : '';
    const animate = !!(shown && W && W.tokenQrAnimates && W.tokenQrAnimates(shown));
    if (this._tokQr && (!animate || this._tokQr.token !== shown)) {
      clearInterval(this._tokQr.timer);
      this._tokQr = null;
    }
    if (!animate || this._tokQr) return;
    const frames = W.animatedQr(shown, this.TOKEN_QR.fragment);
    const run = { token: shown, src: '', timer: 0 };
    const tick = () => {
      // error correction L: the fountain code already makes up for a frame missed
      const src = W.qr(frames.next(), { ecc: this.TOKEN_QR.ecc });
      if (!src) return;
      run.src = src;
      const img = document.querySelector('[data-token-qr]');
      if (img && img.getAttribute('src') !== src) img.setAttribute('src', src);
    };
    this._tokQr = run;
    tick();
    run.timer = setInterval(tick, this.TOKEN_QR.everyMs);
  }

  /* The receive screen's code, animated when one static code would be too dense
   * to read.
   *
   * `qrTooDense` has measured this for a while and nothing acted on it: a
   * request carrying both an onion address and a Nostr profile is 93 modules,
   * which is 2.6 points each in the box an iPhone XS gives it, and phone
   * cameras want about three — more at an angle or in poor light. So the code
   * was shown, and it was unreadable, and it was scanned again and again on
   * the small phone while the same code read fine on the big one.
   *
   * The same frames the token screen uses, for the same reason and read by the
   * same wallets. Only where the measurement says so: a request with a sat
   * amount and one transport is well inside the limit, and a code that stands
   * still is easier to scan than one that does not.
   */
  /* What went into the QR on screen, said once per change.
   *
   * Three reports in a row that "the QRs do not work" and nothing in the diary
   * could tell them apart: a code that was never drawn, one drawn from the
   * wrong text, one too dense to read, and one the camera simply could not see
   * all look identical afterwards. So the screen says what
   * it drew — the rail, where the text came from, how long it was, how many
   * modules that made, and whether it is animating.
   *
   * Once per change, never per render: this runs inside the render and a line
   * per frame would bury everything else.
   */
  noteQr(src, about) {
    const s = String(src || '');
    const key = (about.rail || '') + '|' + (about.from || '') + '|' + about.chars
      + '|' + (about.dense ? 'd' : '') + (about.animating ? 'a' : '') + '|' + s.length;
    if (this._qrSaid === key) return;
    this._qrSaid = key;
    /* The module count is the thing that decides whether a camera can read it:
     * the box is about 240 points across, so 93 modules is 2.6 points each and
     * 65 is 3.7. Most phone cameras want about three. */
    let modules = 0;
    try {
      const svg = decodeURIComponent(s.replace(/^data:image\/svg\+xml;utf8,/, ''));
      const m = /viewBox="0 0 (\d+)/.exec(svg);
      modules = m ? Number(m[1]) : 0;
    } catch (e) {}
    const loading = s && s === this.qrLoadingSrc();
    const kind = !s ? 'NOTHING'
      : loading ? 'the waiting animation, no code yet'
      : modules ? modules + ' modules' : 'a code';
    console.log('[foxy] qr: ' + about.rail + ' shows ' + kind
      + ' from ' + about.from + ' (' + about.chars + ' chars)'
      + (about.dense ? ', too dense for one' : '')
      + (about.animating ? ', animating' : ''));
  }

  /* Is one code too dense to read, asked once per request rather than per
   * render.
   *
   * `qrTooDense` encodes the whole code to count its modules, and the render
   * asked it on every pass — several times a second, on the phone least able
   * to afford it. The answer cannot change for a given request, so it is
   * remembered. One entry: the request on screen is the only one being asked
   * about.
   */
  qrDense(text) {
    const W = window.FoxyWallet;
    const t = String(text || '');
    if (!t || !W || !W.qrTooDense) return false;
    if (this._denseOf !== t) {
      this._denseOf = t;
      this._denseWas = !!W.qrTooDense(t);
    }
    return this._denseWas;
  }

  syncReqQr() {
    const W = window.FoxyWallet;
    const s = this.state;
    const on = s.screen === 'confirm' && s.flow === 'receive' && s.recvRail === 'CASHU';
    const text = on ? (this.cashuRequest() || '') : '';
    const animate = !!(text && this.qrDense(text));
    if (this._reqQr && (!animate || this._reqQr.text !== text)) {
      clearInterval(this._reqQr.timer);
      this._reqQr = null;
      /* And a render, so the right code comes back. Without it the image keeps
       * the last frame of the request before it — a code for the wrong amount,
       * or a fragment of one, which is what "it scanned once and never again"
       * looks like from the outside. */
      this.setState({ creqMade: Date.now() });
    }
    if (!animate || this._reqQr) return;
    console.log('[foxy] the request is too dense for one code on a small screen; animating it');
    const frames = W.animatedQr(text, this.REQ_QR.fragment);
    const run = { text: text, src: '', timer: 0 };
    const tick = () => {
      const src = W.qr(frames.next(), { ecc: this.REQ_QR.ecc });
      if (!src) return;
      run.src = src;
      const img = document.querySelector('[data-req-qr]');
      if (img && img.getAttribute('src') !== src) img.setAttribute('src', src);
    };
    this._reqQr = run;
    tick();
    run.timer = setInterval(tick, this.REQ_QR.everyMs);
  }

  /* Small change on hand, so most tokens need no swap and are heard about as
   * soon as they are redeemed (FoxyWallet.tidyChange). At a random moment 4
   * to 10 seconds after the wallet is ready or money has moved; not while
   * money is moving, and going looking at most once every twenty seconds. It
   * was 20 to 90 seconds and two minutes, and the pool was still nearly empty
   * after ten minutes of use. A pile that already has its
   * small change asks nothing. */
  TIDY_WAIT = [4000, 10000];

  /* And how long between one swap and the next while the pool is still short.
   *
   * Each run splits one piece, and a pool filling from scratch is twelve of each
   * of eight small denominations before the deep ones even begin. At the idle
   * pace above — twenty to ninety seconds, floored at two minutes, and only when
   * something re-armed it — that is far longer than anybody holds an app open,
   * so the pool was found half full when exact change was needed.
   *
   * So the wait is for going looking, not for making progress: once a swap has
   * worked and something is still short, the next follows in a few seconds and
   * keeps following until nothing is short or the mint says no. The spacing that
   * matters for not making a recognisable burst at the mint is still there — it
   * is random, and it is the gap between the runs themselves. */
  TIDY_AWAY_STOP = 12000;
  TIDY_MORE = [2500, 6000];

  /* A token from a mint this wallet does not use is being priced, or moved.
   *
   * moneyBusy() does not see this whole stretch: the fee is quoted, and then
   * nothing holds the proof lock while the person reads the screen and decides,
   * and the claim only takes it once they tap. A tidy armed earlier landed in
   * exactly that gap on a phone and spent fourteen seconds asking the mint
   * about change it turned out not to need — then the claim that followed took
   * six seconds to reconnect to a mint it had been connected to a moment
   * before (seen in a device log). A move between
   * mints is six round trips over Tor already; it does not share them with
   * housekeeping. */
  movingMints() {
    const s = this.state;
    return s.screen === 'newMint' || !!s.nmBusy;
  }

  /* `more` is a run that follows one that worked: it comes sooner and is not
   * held back by the two-minute floor, which exists to stop this going looking
   * over and over, not to stop it finishing what it started. */
  /* The phone says Foxy has been put away (FoxyWebView.appEnteredBackground).
   * A top-up still waiting its turn goes now, while Tor is held up for it. */
  /* The phone says Foxy has been put away (FoxyWebView.appEnteredBackground),
   * or back. Put away is the only time a top-up swap runs: never in front of
   * somebody who might be about to pay, and never behind a screen asking
   * them to wait. The phone keeps Tor on the network for
   * it, twenty seconds; no swap starts after twelve, and one still out at
   * eighteen has its piece checked and left spendable (`topUpClosing`). */
  putAway(on) {
    this._putAway = !!on;
    clearTimeout(this._closingT);
    if (!on) return;
    this._putAwayAt = Date.now();
    if (this._tidyOwed || this._tidyT) this.tidyChangeLater(this._tidyMore);
    this._closingT = setTimeout(() => {
      const W = window.FoxyWallet;
      if (this._putAway && W && W._tidying && W.topUpClosing) W.topUpClosing().catch(() => {});
    }, 18000);
  }

  /// Whether a send is waiting its turn behind the change top-up.
  sendBehindChange() {
    const W = window.FoxyWallet;
    const h = W && W.proofLockHolder && W.proofLockHolder();
    return !!h && h.what === 'tidyChange' && (this.state.sendPhase || 'in') === 'in';
  }

  onConfirmation() {
    const s = this.state;
    return s.screen === 'paid' || (s.screen === 'sendDone' && (s.sendPhase === 'done' || s.sendPhase === 'settled'));
  }

  /* Straight after a payment, not seconds later. The wait before a top-up
   * was long enough for somebody to be paid, pocket the phone, and find no
   * change to give at the next payment. */
  /* A payment changes what there is to break. Nothing runs here: the top-up
   * waits for Foxy to be put away (putAway), and the "not twice in twenty
   * seconds" rule is set aside for it. */
  tidyChangeNow() {
    this._tidyOwed = true;
    this._tidyAt = 0;
  }



  tidyChangeLater(more) {
    const W = window.FoxyWallet;
    if (!W || !W.tidyChange) return;
    clearTimeout(this._tidyT);
    this._tidyT = null;
    if (!this._putAway) { this._tidyOwed = true; this._tidyMore = !!more; return; }
    this._tidyOwed = false;
    const [lo, hi] = more ? this.TIDY_MORE : this.TIDY_WAIT;
    /* Put away with a top-up still to do: it starts now, and the phone is told
     * so. The wait is for a person who is still here; one who has left gives
     * Foxy seconds, and Tor stays on the network only while `_tidying` says
     * there is something for it to carry (FoxyWebView.appEnteredBackground). */
    const away = true;
    this._tidyMore = !!more;
    W._tidying = true;
    this._tidyT = setTimeout(() => {
      this._tidyT = null;
      W._tidying = false;
      /* No new swap once Foxy has been away twelve seconds. The phone takes
       * Tor off the network at twenty, and a swap cut off there has its piece
       * held out of the balance until the phone is online again — which an
       * offline wallet may not be for a while. Eight seconds is room for the
       * last one to be answered. The rest is done on return (`_onWake`). */
      if (this._putAway && Date.now() - (this._putAwayAt || 0) > this.TIDY_AWAY_STOP) {
        console.log('[foxy] small change: away too long to start another swap; the rest on return');
        this._tidyOwed = true;
        return;
      }
      /* Nor while change is on its way back to this phone: the top-up would
       * hold the proof lock, the change would wait behind it, and the
       * receiver would not be told in time that it was kept. */
      if (this.moneyBusy() || this.movingMints() || this._changeDueAt) { this.tidyChangeLater(more); return; }
      // brought back meanwhile: the rest waits for the next put-away
      if (!this._putAway || this._tapTalking || this.state.tapArmed) {
        this.tidyChangeLater(more);
        return;
      }
      if (!more && Date.now() - (this._tidyAt || 0) < 20000) return;
      this._tidyAt = Date.now();
      W._tidying = true;
      W.tidyChange().then(r => {
        W._tidying = false;
        /* A swap that worked means there may be more to do, so the next one is
         * armed straight away. It stops on its own: `tidyChange` answers
         * `skipped` the moment the pool has what it wants, or there is no route,
         * or the piece it would need is not there. */
        if (r && r.split) {
          this.refreshBalance();
          this.tidyChangeLater(true);
          return;
        }
        if (r && r.skipped) console.log('[foxy] small change: ' + r.skipped);
      }).catch(() => { W._tidying = false; });
    }, away ? 400 : lo + Math.floor(Math.random() * (hi - lo + 1)));
  }

  /* An invoice made by the mint this wallet pays from: its payer and payee are
   * both that mint's users, and paying by Lightning shows the mint both. A
   * token instead leaves it amount and timing. The token screen says who it
   * is for, and the token is watched until it is redeemed. */
  payThisMintWithToken(sats, go) {
    const W = window.FoxyWallet;
    if (!(sats > 0) || this.state.makeBusy) return;
    this.setState({ makeBusy: true });
    this.showMelt('Making the token\u2026', 0, { sats: sats });
    this._preSettle = this.balNow();
    /* With no route the token is made from the pieces on hand, covering the
     * amount where they cannot make it exactly — asked about first. */
    const off = !!(this.offlineNow && this.offlineNow());
    W.sendToken(sats, off ? { cover: true, changeNote: true, overpayOk: !!(go && go.overpayOk) } : undefined).then(r => {
      this.hideMelt();
      this._seenTx = this._seenTx || {};
      this._seenTx[r.hash] = true;
      this.setState({
        makeBusy: false, tokenCopied: false,
        tokenOut: r.token, tokenOutSats: r.sats, tokenOutHash: r.hash, tokenForPayee: true,
        tokenOutFee: Math.max(0, sats - r.sats),
        screen: 'tokenOut', stack: [],
      });
      if (off) this.needScanStage(r);
      this.refreshBalance();
      this.watchToken(r.sats, r.hash, r.swapped === false);
      this.tidyChangeLater();
    }).catch(e => {
      this.hideMelt();
      this.setState({ makeBusy: false });
      if (e && e.foxyNeedsOverpay) {
        this.overpayCard(Object.assign({}, e.foxyNeedsOverpay, { changeComesBack: false,
          says: 'This phone is offline and cannot make change, so they keep the extra'
            + ' unless they hand it back.' })).then((yes) => {
          if (yes) this.payThisMintWithToken(sats, { overpayOk: true });
        });
        return;
      }
      if (this.isBadSignatures(e)) { this.badSignatureCard(null, 'swap'); return; }
      this.toast(W.reason(e), true);
    });
  }

  /* The receive screen's SCAN: someone paying this invoice may hand over a
   * token instead. Taken as any scanned token is; the invoice screen closes,
   * and the history pass says the payment arrived, as it does for an invoice. */
  scanTokenToReceive() {
    const W = window.FoxyWallet;
    if (!W || !W.scan) return;
    W.scan('Scan an ecash token').then(text => {
      const t = String(text || '').trim();
      if (W.classify(t) !== 'token') {
        this.toast('That QR is not a Cashu token.', true);
        return;
      }
      this.closeReceive();
      this.showMelt('Receiving ecash\u2026');
      if (this.offerNewMint(t)) { this.hideMelt(); return; }
      if (this.tokenSwitchRefused(t)) { this.hideMelt(); return; }
      this._preSettle = this.balNow();
      return W.receiveToken(t).then(r => {
        this.hideMelt();
        if (r.switched) { this.walletReady({ name: r.host }); this.toast('Now on ' + r.host); }
        this.tookToken(r);
        this.announceTaken(r);
        this.refreshBalance();
        this.loadHistory();
        this.noteReceived();
        this.keptOfflineSaid(r);
      });
    }).catch(e => { this.hideMelt(); this.claimFailed(e, () => this.scanTokenToReceive()); });
  }

  /* Hand someone ecash directly. The amount on the keypad is what leaves;
   * the token screen shows it as a QR and a string. */
  makeEcashToken() {
    const W = window.FoxyWallet;
    const sats = this.amountInSats();
    if (!(sats > 0)) {
      this.toast('Enter an amount first', true);
      return;
    }
    if (this.state.makeBusy) return;
    this.setState({ makeBusy: true });
    this.showMelt('Making the token\u2026');
    // the sats leave as soon as the token exists; hold the old figure so the
    // pill can count down when the screen is closed
    this._preSettle = this.balNow();
    // a plain token: Foxy never locks what it sends
    W.sendToken(sats).then(r => {
      this.hideMelt();
      // our own entry, not an incoming payment — the sweep must not announce
      // it over the top of the screen holding the token
      this._seenTx = this._seenTx || {};
      this._seenTx[r.hash] = true;
      this.setState({
        makeBusy: false, tokenCopied: false,
        tokenOut: r.token, tokenOutSats: r.sats, tokenOutHash: r.hash, tokenForPayee: false,
        tokenOutFee: Math.max(0, sats - r.sats),
        screen: 'tokenOut', stack: [],
      });
      this.refreshBalance();
      this.watchToken(r.sats, r.hash, r.swapped === false);
      this.tidyChangeLater();
    }).catch(e => {
      this.hideMelt();
      this.setState({ makeBusy: false });
      if (this.isBadSignatures(e)) { this.badSignatureCard(null, 'swap'); return; }
      this.toast(W.reason(e), true);
    });
  }

  /* Whatever is on the keypad, in sats, whichever unit it was typed in. */
  amountInSats() {
    const s = this.state;
    const v = parseFloat(s.amount) || 0;
    if (!v) return 0;
    if (s.unit === 'SATS') return Math.round(v);
    const px = this.px();
    if (!px) return 0;
    return Math.round((v / px) * 1e8);
  }

  /* A payment request. Nothing here can deliver over nostr, so the offer is
   * the honest one: make the token, hand it over yourself. */
  /* `opts.viaTap` when this request came over an open Bluetooth link, so the
   * payment can go back over it. Never inferred: a scanned request must not be
   * paid to whichever phone is connected. */
  openRequest(text, opts) {
    const W = window.FoxyWallet;
    const req = W.decodeRequest(text);
    if (req && opts && opts.viaTap) req.viaTap = true;
    /* Whether the phone that made this request has a route, as it said in its
     * tap offer. Carried on the request because that is what `payRequest`
     * reads, and it is the one fact the hand-over rules cannot be held up
     * without (`handoverRefusal`). */
    if (req && opts && typeof opts.theirRoute === 'boolean') req.theirRoute = opts.theirRoute;
    // and whether it answers a question before the payment (`askFirst`), from the same offer
    if (req && opts && opts.asks) req.asks = true;
    /* A request just opened is not one being paid.
     *
     * `reqBusy` is what makes the button say PAYING…, and a route that leaves
     * it set — a payment abandoned part way, a screen left — carried it into
     * the next request, which arrived already claiming to be paying and could
     * not be tapped. Nothing has been asked of the
     * wallet at this point, so it is false by definition. */
    this.setState({ reqBusy: false });
    if (!req) { this.toast('That request could not be read.', true); return; }
    if (req.unit && req.unit !== 'sat') {
      this.toast('That request asks for ' + this.unitLabel(req.unit) + ' ecash. Foxy can only send sats as ecash.', true);
      return;
    }
    /* A request that asks in dollars, scanned rather than tapped.
     *
     * A phone with no route asks in dollars and leaves the sats to whoever has
     * a current price. Over a tap the two phones then agree the figure; a code
     * read off a screen has nobody to agree it with, so nothing worked the
     * amount out at all — the offer opened on no amount and PAY answered "Ask
     * for an amount above zero".
     *
     * This phone's price makes the sats, and the screen shows both figures
     * before anything is paid. The receiver sees what arrived when they take
     * the token, which is where a scanned payment has always been agreed. */
    if (W.asksInDollars && W.asksInDollars(req)) {
      const q = W.quoteFor ? W.quoteFor(req) : null;
      if (!q) {
        console.log('[foxy] request: asks in dollars and this phone has no price to work it out with');
        this.toast('They asked in dollars, and this phone has no bitcoin price yet. Try again in a moment.', true);
        return;
      }
      req.sats = q.sats;
      console.log('[foxy] request: they asked for $' + (q.usd / 100).toFixed(2) + ', which is '
        + q.sats + ' sats at this phone\u2019s price of $ ' + this.group(Math.round(q.rate)));
    }
    /* What is held at a mint includes what arrived locked to this phone and is
     * waiting to be swapped in. A phone that had only been paid offline held
     * nothing in its pile, so it was told it held nothing at its own mint, a
     * moment before paying from exactly that. */
    // at that mint, not anywhere: what waits at one mint pays nothing at another
    const waitingAt = (u) => { try { return W.unclaimedSats ? W.unclaimedSats(u) : 0; } catch (e) { return 0; } };
    const holdsAt = (m) => {
      const u = String(m).replace(/\/+$/, '');
      return W.balanceAt(u) > 0 || waitingAt(u) > 0;
    };
    if (req.mints.length && !req.mints.some(holdsAt)) {
      this.toast('That request wants a mint you hold nothing at.', true);
    }
    this.setState(p => ({ screen: 'reqOffer', stack: p.stack.concat([p.screen]), req: req,
      // a note left on an earlier send is not this payment's note
      note: '', noteDraft: '' }));
  }

  /* Will an over-payment's change come back by itself?
   *
   * Only from a phone with a route, because making change is a swap. It says
   * so in its tap offer (`theirRoute`), or shows it by naming somewhere to be
   * paid. A receiver on the ecash rail names nowhere and is online all the
   * same, which is why the transports alone were not the answer. */
  changeComesBack(req) {
    if (!req) return false;
    if (req.theirRoute === true) return true;
    if (req.theirRoute === false) return false;
    return !!(req.transports && req.transports.length);
  }

  /* RECEIVER NEEDS TO SCAN: the payment as a code, for the other phone's
   * camera, with SHARE for a receiver who is not in the room.
   *
   * DONE goes home. It used to leave the token screen underneath, so that it
   * could watch for the token being taken — but this screen is only shown
   * offline, where nothing can be watched, and what the person saw after
   * DONE was a token screen they had not asked for. When change is owed, DONE
   * opens the camera instead: the receiver's phone is showing the change code
   * by then, and the way to collect it is to scan it. */
  needScanStage(made) {
    if (!this.stageScreen || !made || !made.token) return;
    const W = window.FoxyWallet;
    const due = !!(made.changeAsked && Number(made.over) > 0);
    this.stageScreen('needScan', {
      title: 'Receiver<br>needs to scan', qr: made.token,
      /* What is being paid, not what it is being paid with; and where the
       * rest is coming back, how to collect it. */
      amount: this.stageMoney(Math.max(0, Number(made.sats) - (Number(made.over) || 0))),
      body: (made.changeAsked && Number(made.over) > 0)
        ? 'Ask the receiver to scan this QR code. Their phone will then show a code for your <strong>'
          + this.stageMoney(made.over) + '</strong> change: scan it to collect.'
        : 'Ask the receiver to scan this QR code to finalize the payment.',
      above: 'SHARE',
      aboveGo: () => {
        if (!W || !W.share || !W.share(made.token)) this.toast('Sharing is not available here.', true);
      },
      button: due ? 'SCAN FOR CHANGE' : 'DONE',
      go: () => {
        if (W && W.clearLastToken) W.clearLastToken();
        this.setState(p => ({
          screen: due ? 'sendScan' : 'home', stack: [], flow: due ? 'send' : p.flow,
          tokenOut: '', tokenCopied: false, tokenForPayee: false,
          scanWhy: due ? 'SCAN FOR YOUR ' + this.stageMoney(made.over).toUpperCase() + ' CHANGE' : '',
        }));
        if (this.claimWatchTick) setTimeout(() => this.claimWatchTick(), 0);
      },
    });
  }

  /* Mint it at the mint the request names, switching there if needed. */
  /* `go.overpayOk` is the person's answer to the over-pay card, threaded rather
   * than stashed: this function's work is asynchronous, so a flag on `this`
   * would be cleared before the send reads it. */
  makeTokenForRequest(go) {
    const W = window.FoxyWallet;
    const req = this.state.req;
    if (!req || this.state.reqBusy) return;
    const want = String(req.mints[0] || '').replace(/\/+$/, '');
    const here = W.mintHost && ('https://' + W.mintHost()) === want;
    // making it somewhere else switches mints, which waits for any payment
    if (want && !here && this.refuseSwitchWhileBusy()) return;

    /* A payment request names its own mint, and this used to connect to it on
     * one tap. Tokens from an attacker-chosen mint are worthless, and the
     * request only has to be scanned to get here.
     *
     * So a mint this device has never used gets named in full first, with
     * connecting as the deliberate action. One already on the list goes
     * through — it has been accepted before. */
    if (want && !here && !this._reqMintOk) {
      const known = (W.mints ? W.mints() : []).some(m =>
        String(m.id || m).replace(/\/+$/, '') === want);
      if (!known) {
        const host = want.replace(/^https?:\/\//, '');
        const mine = W.mintHost ? W.mintHost() : 'none';
        this.blockedCard('reqMint', {
          tone: 'warn',
          title: 'A DIFFERENT MINT',
          reason: 'This request wants ' + host + '. You are on ' + mine
            + '. Ecash from a mint you do not know may not be worth anything, '
            + 'and only that mint can redeem it.',
          retry: 'USE ' + host.toUpperCase().slice(0, 22),
          go: () => { this._reqMintOk = want; this.makeTokenForRequest(go); },
        });
        return;
      }
    }
    this._reqMintOk = null;
    this.setState({ reqBusy: true });

    /* A request that says where to deliver is paid there: onion, straight to
     * the requester's phone over Tor; nostr, an encrypted message through Tor
     * (07-request-delivery.js). The token is made either way, so a delivery
     * that fails leaves it on the token screen to show instead. */
    /* An open Bluetooth link is a way to deliver, and the best one there is.
     *
     * `delivery` comes from the transports the request names, and an offline
     * receiver names none — it cannot make an onion or reach a relay. So a
     * payment between two offline phones fell straight through to "show them a
     * token", and the person was handed a QR to scan while the two phones were
     * linked and the code was on both screens. The link
     * the offer arrived over is the answer, and `viaTap` is what says there is
     * one; `payRequest` has preferred it over the request's own transports
     * since the change leg was built. */
    /* Not over an onion or a relay from a phone with no route. A request read
     * off a screen names the receiver's address, and this phone cannot reach
     * it: the payment failed with "needs a connection" three times running,
     * when what it needed was to be shown as a code for the other phone to
     * scan. The tap is a link, not a route,
     * and still delivers. */
    const reachable = req.viaTap || (req.delivery && !(this.offlineNow && this.offlineNow()));
    const direct = !!(reachable && req.sats > 0);
    /* A payment going out looks like a payment going out.
     *
     * Paying a request had the gold melting overlay, which is the wallet
     * turning ecash into something else — here nothing is being melted, the
     * money is simply leaving, and it should look the way a Lightning send
     * looks. Making a token to show somebody keeps the
     * overlay: that really is the wallet working, with no send to animate.
     *
     * The amount goes into state because the send screen reads it from there
     * (renderContext), and `recipientKind` is deliberately not 'invoice' —
     * that would send it looking for an amount inside a recipient there is
     * none of. */
    if (direct) {
      this.setState(p => ({
        screen: 'sendDone', stack: p.stack.concat([p.screen]), sendPhase: 'in',
        flow: 'send', recipientKind: 'ecash', amount: String(req.sats), unit: 'SATS',
        /* Who this one goes to, not who the last one went to: the address of
         * an earlier send was still in state, so a tap said it was sending to
         * it. A tap goes to the code on both screens. */
        recipient: (req.viaTap && p.tapCode) ? String(p.tapCode) : '',
      }));
    } else {
      this.showMelt('Making the token\u2026');
    }
    const ready = (want && !here) ? W.connect(want) : Promise.resolve(null);
    /* Agreed before it is asked, where the change comes straight back. The
     * question was being skipped already, but only after the send had refused
     * once for want of an answer — so the screen went to sending, back to the
     * offer and to sending again, and where the receiver had named no address
     * the card came up anyway, telling a payer whose change was on its way
     * back that the other phone would keep it. */
    const overOk = !!(go && go.overpayOk) || (direct && this.changeComesBack(req));
    ready.then(() => direct
      ? W.payRequest(req, null, { overpayOk: overOk })
      /* Locked to them when they asked for it and this phone can: a token shown
       * on a screen is one anybody's camera can take, and a receiver with no
       * route can only accept ecash locked to it. It went out plain, so the
       * lock a scanned request asked for was dropped without a word. */
      /* And with no route, made from what is on hand: an amount the pieces
       * cannot make exactly is covered and the difference is change, which is
       * the person's to agree to first. It used to fall through to a swap and
       * say "this needs a connection" about a payment that needed none. */
      : W.sendToken(req.sats, (req.lockTo && !(this.offlineNow && this.offlineNow()))
          ? { unit: req.unit || 'sat', lockTo: req.lockTo }
          : ((this.offlineNow && this.offlineNow())
            ? { unit: req.unit || 'sat', cover: true, overpayOk: !!(go && go.overpayOk) }
            : { unit: req.unit || 'sat' }))).then(r => {
      this.hideMelt();
      /* No fee on this path, and say so.
       *
       * `_lastFee` is written by the Lightning send and never cleared, so the
       * completion screen showed whatever the last routed payment had cost —
       * ₿3 on a mint-to-mint payment that cost nothing, while the transaction
       * record beside it correctly said ₿0. Ecash
       * to the same mint is free; a token handed over is free. */
      this._lastFee = 0;
      this._seenTx = this._seenTx || {};
      this._seenTx[r.hash] = true;
      const note = (this.state.note || '').trim();
      if (note) W.tag(r.hash, { note: note });
      if (direct) {
        this._crossMovedTo = null;
        this.requestDelivered(req, r);
        this.crossComeHome();
        return;
      }
      this.setState({
        reqBusy: false, req: null, tokenCopied: false,
        tokenOut: r.token, tokenOutSats: r.sats, tokenOutHash: r.hash, tokenForPayee: true,
        screen: 'tokenOut', stack: [],
      });
      this.needScanStage(r);
      this.refreshBalance();
      this.watchToken(r.sats, r.hash, r.swapped === false);
      this.tidyChangeLater();
    }).catch(e => {
      this.hideMelt();
      // off the sending animation, whichever way this ends: it is not sending
      this.setState({ reqBusy: false, sendPhase: null });
      // stopped by the person before it was made: nothing to report, and they are home already
      if (e && e.foxyStopped) return;
      /* No exact change: ask, and go again with the answer. Nothing has been
       * made at this point — `sendToken` refuses before it touches a proof —
       * so a cancel leaves the pile exactly as it was. */
      if (e && e.foxyNeedsOverpay) {
        // off the sending screen while the question is up, back where they were
        this.setState(p0 => ({ reqBusy: false, sendPhase: null,
          screen: p0.screen === 'sendDone' ? 'reqOffer' : p0.screen }));
        /* Only where the extra is a gift.
         *
         * An offline receiver names no transports, so it cannot give change and
         * the difference is money the person is giving away — that is worth
         * stopping for. Where the receiver has a route the difference comes
         * straight back over the same link within seconds, and a card about it
         * is a question with one sensible answer asked in the middle of paying
         * somebody. Handled, not asked about. */
        const comesBack = this.changeComesBack(req);
        if (comesBack) {
          console.log('[foxy] no exact pieces, and the change comes straight back;'
            + ' paying ' + e.foxyNeedsOverpay.pay + ' for ' + e.foxyNeedsOverpay.asked);
          this.makeTokenForRequest({ overpayOk: true });
          return;
        }
        this.overpayCard(Object.assign({}, e.foxyNeedsOverpay,
                                       { changeComesBack: false })).then((yes) => {
          if (!yes) { this.setState({ req: null, sendPhase: null, screen: 'home', stack: [] }); return; }
          this.makeTokenForRequest({ overpayOk: true });
        });
        return;
      }
      /* They heard it and said no. Three endings, and the phone says which
       * (20-helpers.js `payRequest`, 07-request-delivery.js `afterRefusal`):
       * the ecash came back locked to this phone; it did not, and is in the
       * wallet again at risk; or the question asked first was answered no
       * and nothing was ever sent. */
      if (e && (e.foxyRefunded || (e.foxyAtRisk && !e.foxyAtRisk.onEntry) || (e.foxyAskedNo && !e.foxySilent))) {
        this.setState(p0 => ({ req: null, sendPhase: null, screen: p0.screen === 'sendDone' ? 'home' : p0.screen, stack: [] }));
        if (this._crossCameFrom) this.crossComeHome();
        this.refreshBalance();
        this.loadHistory();
        if (e.foxyAskedNo) {
          console.warn('[foxy] the payment was not made: they said no before anything was sent:', W.reason(e));
          this.blockedCard('theyRefused', {
            tone: 'warn',
            title: 'THEY CANNOT TAKE IT',
            reason: W.reason(e),
            chip: 'Nothing was sent. Your sats are where they were.',
          });
          return;
        }
        if (e.foxyRefunded) {
          const back = e.foxyRefunded;
          this.blockedCard('theyRefused', back.short ? {
            tone: 'warn',
            title: 'THEY DID NOT TAKE IT',
            reason: W.reason(e) + ' They sent back ' + this.group(back.sats) + ' of the ' + this.group(back.paid) + ' sats.',
            chip: this.group(back.paid - back.sats) + ' sats were not returned.',
          } : {
            tone: 'warn',
            title: 'THEY DID NOT TAKE IT',
            reason: W.reason(e),
            chip: 'Your ' + this.group(back.sats) + ' sats came back, locked to this phone. Nothing is at risk.',
          });
          return;
        }
        /* With a route the wallet has already dealt with it (`afterRefusal`):
         * the pieces are swapped, or the phone that said no had redeemed
         * them first. Neither is a risk still standing. */
        if (e.foxyAtRisk.safe) {
          this.blockedCard('theyRefused', {
            tone: 'warn',
            title: 'THEY DID NOT TAKE IT',
            reason: 'They refused this payment and sent nothing back. Foxy has swapped your ecash for new pieces, so the copy they saw is worth nothing.',
            chip: 'Your ' + this.group(e.foxyAtRisk.sats) + ' sats are in your wallet. Nothing is at risk. They said: ' + W.reason(e),
          });
          return;
        }
        if (e.foxyAtRisk.taken) {
          this.blockedCard('theyRefused', {
            tone: 'warn',
            title: 'THEY TOOK THE PAYMENT',
            reason: 'They said no, and your ecash has been redeemed all the same: ' + this.group(e.foxyAtRisk.sats) + ' sats. Its entry in your history says paid.',
            chip: 'Do not pay again. If they are sending it back, they will show you a code to scan. They said: ' + W.reason(e),
          });
          return;
        }
        this.blockedCard('theyRefused', {
          tone: 'warn',
          title: 'HIGH RISK',
          reason: 'They refused this payment and did not send it back locked to you. They have seen your ecash and can still redeem it. '
            + 'Do not pay again until you are online.',
          chip: this.group(e.foxyAtRisk.sats) + ' sats are in your wallet again, at risk until Foxy has a connection. They said: ' + W.reason(e),
        });
        return;
      }
      const made = e && e.foxyToken;
      if (!made) {
        /* Said in the diary as well as on screen. A toast is two seconds and
         * then gone, so a payment that died between two phones standing
         * together left a log that read as if nothing had been attempted at all
         * — the screens went to sendDone and back to home in nineteen
         * milliseconds and nothing anywhere said why. */
        console.warn('[foxy] the payment was not made:', W.reason(e));
        // after a crossing, back to the mint this phone banks at
        if (this._crossCameFrom) this.crossComeHome();
        /* Told to the other phone while the link is still there, so it does
         * not sit waiting for a payment that is not coming. It rides M10,
         * as the other things a payer says before the money do. */
        if (req && req.viaTap && W.tapQuote) {
          W.tapQuote(JSON.stringify({ gaveUp: String(W.reason(e) || 'The payment was not made.') })).catch(() => {});
        }
        this.setState(p => ({ screen: p.screen === 'sendDone' ? 'home' : p.screen, stack: [] }));
        this.toast(W.reason(e), true);
        return;
      }
      /* They heard it and said no, in words. That is not a delivery that failed,
       * and it must not be answered with a QR: the token screen says nothing
       * about why and asks the person to solve it with a camera. The token is
       * still theirs to hand over if they want to, and the card offers that. */
      if (e && e.foxyRefused) {
        /* Refused, so it is not on its way either — and the money is back in
         * this phone's hands as a token. The row is a real one now. */
        try { if (W.tag) W.tag(made.hash, { inflight: false }); } catch (x) {}
        this._seenTx = this._seenTx || {};
        this._seenTx[made.hash] = true;
        this.setState({ req: null, sendPhase: null });
        /* Its own kind: a refusal is not a lost connection, and the card
         * queue drops a waiting card that shares a kind with a new one. */
        /* And where the money is, when Foxy moved it to pay them.
         *
         * A cross-mint tap melts the sats to their mint before paying. If the
         * payment then fails the money is fine and it is theirs, but it is at a
         * mint they were not on when they tapped — which reads as money going
         * missing unless somebody says so (26d-tap.js, `tapCrossMint`). */
        const movedTo = this._crossMovedTo;
        this._crossMovedTo = null;
        /* And home, whichever way it ended. It stayed at their mint "on
         * purpose" after a failure, showing a balance the person had never
         * seen at a mint they had not chosen; the card below says where the
         * sats are, and the mint list shows them. */
        if (this._crossCameFrom) this.crossComeHome();
        this.blockedCard('theyRefused', {
          tone: 'warn',
          title: 'THEY DID NOT TAKE IT',
          reason: W.reason(e),
          /* True of plain ecash, and not of ecash locked to them: nothing
           * this phone holds opens that, so "still yours" promised a way
           * back that does not exist. It is theirs to take, and the token
           * is how they take it. */
          chip: made.lockedTo
            ? 'HIGH RISK: these ' + this.group(made.sats) + ' sats are locked to them, so only they can take them and you cannot take them back. Show them the token to finish.'
            : (e.foxyAtRisk && e.foxyAtRisk.onEntry)
            ? 'HIGH RISK: they have seen these ' + this.group(made.sats) + ' sats and can still redeem them. Foxy takes them back when it has a connection.'
            : 'Your ' + this.group(made.sats) + ' sats are still yours'
              + (movedTo ? ', and they are now at ' + (this.mintNameOf(movedTo)
                  || String(movedTo).replace(/^https?:\/\//, '')) + '.' : '.'),
          retry: 'SHOW THEM A TOKEN',
          go: () => this.setState({
            tokenCopied: false, tokenOut: made.token, tokenOutSats: made.sats,
            tokenOutHash: made.hash, tokenForPayee: true, screen: 'tokenOut', stack: [],
          }),
          shut: { label: 'CLOSE', tap: () => this.setState({ screen: 'home', stack: [] }) },
        });
        return;
      }
      // made but not delivered: the token screen, to show them instead
      try { if (W.tag) W.tag(made.hash, { inflight: false }); } catch (x) {}
      this._seenTx = this._seenTx || {};
      this._seenTx[made.hash] = true;
      this.setState({
        req: null, tokenCopied: false,
        tokenOut: made.token, tokenOutSats: made.sats, tokenOutHash: made.hash, tokenForPayee: true,
        screen: 'tokenOut', stack: [],
      });
      /* And over it, what to do about it. The token screen is for a token
       * somebody chose to make; this one was meant to cross by itself and did
       * not, and the person needs telling that the payment is not finished
       * until the other phone scans. DONE leaves
       * the token screen underneath, which watches for it being taken. */
      this.needScanStage(made);
      this.refreshBalance();
      this.watchToken(made.sats, made.hash, made.swapped === false);
      this.tidyChangeLater();
      this.toast('It did not reach them (' + W.reason(e) + '). Show them this token instead.', true);
    });
  }

  /* A request paid straight to whoever asked.
   *
   * Forgetting the payer's copy turns on whether the receiver said in so many
   * words that it had written the payment down (`r.confirmed`, payRequest) —
   * not on which transport the request happened to name. It used to ask
   * `req.delivery.kind === 'onion'`, and every Foxy request names an onion even
   * when the money went over a Bluetooth tap. Tap's M6 said "ok" before the
   * receiving page had looked at the payment, so a receiver that refused a
   * moment later — its page reloaded, the mint no longer matching, a duplicate
   * — left this phone with the token text already deleted, the audit record's
   * inputs blanked and the last-token record dropped: a payment nobody had
   * taken and nobody could re-show.
   *
   * Unconfirmed is the Nostr case and is no worse than it ever was: a relay
   * took the message, or a tap came back 409 or unanswered. The token is
   * watched as any token is and history turns green when the mint reports the
   * proofs spent — and that watch is what forgets it, later and on evidence. */
  /* Back to the mint the person actually banks at, after a crossing.
   *
   * Paying somebody at another mint leaves this phone there, because that is
   * where the payment is made from. The person did not choose that mint and
   * does not keep their money at it: they tapped from one mint, paid somebody
   * at another, and came home to a tiny balance at the other with their own
   * nowhere in sight.
   *
   * Only after the payment has gone through, and only to the mint this phone
   * was on when the tap started. A failure leaves it where it is on purpose —
   * the change from the crossing is at the far mint and the refusal card says
   * so, and moving the person away from it would hide the thing they were just
   * told about.
   */
  crossComeHome() {
    const W = window.FoxyWallet;
    const back = this._crossCameFrom;
    this._crossCameFrom = null;
    if (!back || !W || String(W.mintUrl || '').replace(/\/+$/, '') === back) return;
    console.log('[foxy] back to ' + back + ', the mint this phone was on before the crossing');
    W.connect(back).then(() => { this.refreshBalance(); this.loadHistory(); },
                         () => {});
  }

  requestDelivered(req, r) {
    const W = window.FoxyWallet;
    const confirmed = !!(r && r.confirmed);
    /* It has arrived somewhere, so it is no longer on its way: the history pass
     * may announce it, and this function does so itself below. Cleared first, so
     * a pass landing between here and `announcePayment` finds a finished
     * payment rather than a hidden one. */
    if (W.tag && r && r.hash) { try { W.tag(r.hash, { inflight: false }); } catch (e) {} }
    /* `sendPhase` as well as `reqBusy`, and this is the only place that ends
     * this path.
     *
     * A direct payment sets `sendPhase: 'in'` on its way to the sending screen
     * and the success branch above returns straight into here, so the two
     * places that clear it — the token branch and the `.catch` — are both
     * paths a successful tap never takes. It stayed `'in'` for the life of the
     * app, and `syncTap` reads it to decide whether this phone may listen for
     * a receiver: one tap paid, and no tap ever worked again (one payment,
     * then silence for the next 37 seconds on home).
     *
     * `'settled'` rather than null, which is what the Lightning send leaves
     * behind for the same moment (03-send.js). */
    this.setState({ reqBusy: false, req: null, sendPhase: 'settled' });
    // paid by tap: remembered, so the same offer heard again is not paid again (26d-tap.js)
    if (req && req.viaTap && this.tapMarkPaid) this.tapMarkPaid(this._tapOfferNow, req);
    /* A payment locked to them has a receipt to collect: the signature its
     * pieces are spent with, which the mint says once they have swapped it
     * in (`lockedReceipt`). A receiver with a route swaps at once, so a few
     * seconds on is when to ask; one without has not yet, and the payment's
     * own screen asks again whenever it is opened. */
    if (r && r.hash && r.lockedTo && W.lockedReceipt && !(this.offlineNow && this.offlineNow())) {
      const hash = r.hash;
      setTimeout(() => { try { W.lockedReceipt(hash); } catch (e) {} }, 8000);
    }
    /* Over-paid, so the receiver owes change back over this link. It has to
     * swap at the mint to make it, which takes seconds — and the payer was
     * letting the link go the moment the person got back to home, one second
     * before the change was ready. */
    if (r && Number(r.over) > 0) this.expectChange(Number(r.over), r.hash);
    // a payment they are carrying home: the entry a refund would settle
    if (this._carriedPay && !this._carriedPay.hash && r && r.hash) this._carriedPay.hash = r.hash;
    /* A locked payment is done when it leaves, because the payer cannot ever
     * take it back: the proofs carry the receiver's key and nothing this phone
     * holds will open them. Shown as pending it reads as money still within
     * reach — the amber row invites a reclaim that cannot work — and the claim
     * watch then raises a note weeks later that reads as a second payment. Unconfirmed or not, there is nothing the payer can
     * do about it, so there is nothing to keep it open for.
     *
     * A delivery that failed outright never reaches here: it throws with the
     * token attached and the token screen shows it, which is the one case where
     * the payer still has something to hand over. */
    /* Marked as having crossed a tap, whatever became of the answer.
     *
     * The token itself is kept — an unconfirmed tap may genuinely not have
     * arrived, and forgetting it would lose the money outright, which is why the
     * branch below is unchanged. What the mark buys is the other half: this
     * payment is never offered back.
     *
     * RECLAIM takes a token's proofs back with a swap. On a payment that crossed
     * a tap the receiver may be holding it on trust and unswapped, because they
     * have no route — that is the whole of what they agreed to — and the mint
     * will honour the payer's swap. A payer did exactly that and the receiver
     * read `spent by the payer`. Foxy does not put that button in front of
     * anybody. The token is still there to
     * show or copy, which hands it to the same person again and is not a double
     * spend. */
    if (req && req.viaTap && W.tag) {
      try { W.tag(r.hash, { handed: 'tap' }); } catch (e) {}
    }
    if (confirmed || (r && r.lockedTo)) {
      W.settleTx(r.hash);
      if (W.forgetClaimedToken) W.forgetClaimedToken(r.hash);
      if (W.lastTokenHash && W.lastTokenHash() === r.hash) W.clearLastToken();
      if (!confirmed) {
        console.log('[foxy] a locked payment was handed over and nobody confirmed it;'
          + ' settled anyway, because it is not this phone\u2019s to take back');
      }
    } else {
      this.watchToken(r.sats, r.hash, false);
    }
    this.refreshBalance();
    this.loadHistory();
    this.tidyChangeLater();
    /* What was paid, not the piece it was paid with.
     *
     * With no exact pieces the payer covers the amount and the receiver hands
     * the difference straight back, so a 2-sat payment made with a 4-sat piece
     * is still a 2-sat payment. The receiver already says 2; the payer said 4.
     * `over` is 0 on every ordinary send, so this is r.sats everywhere else. */
    const paidOut = Math.max(0, Number(r.sats) - (Number(r.over) || 0));
    this.announcePayment({ dir: 'out', sats: paidOut, hash: 'request-' + r.hash, to: 'ecash', tokenHash: r.hash });
  }

  /* A token from a mint with nothing filed under it. Ask before adding a mint
   * to the wallet, since that is what claiming it does. */
  offerNewMint(text) {
    const W = window.FoxyWallet;
    const info = W.tokenInfo(text);
    if (!info) { this.toast('That token could not be read.', true); return false; }
    const mint = String(info.mint || '').replace(/\/+$/, '');
    const unit = info.unit || 'sat';
    /* Your mint is the one you are on. A token from any other goes through
     * MOVE TO YOUR MINT, whatever is held there: it used to be offered only
     * where nothing was, so the change a first move left at WesternBTC made
     * the next WesternBTC token switch the wallet there and claim it, with no
     * say. Moving it home is the main choice; keeping it
     * at its own mint is asked for, never assumed. */
    if (mint === String(W.mintUrl || '').replace(/\/+$/, '')) return false;

    /* No route, and ecash from a mint this phone is not on. Nothing about it
     * can be checked and it cannot be brought home, so it is refused at once
     * rather than after a screen that says it is being verified. Nothing is kept: the token is still theirs to show again. */
    if (this.offlineNow && this.offlineNow()) {
      console.log('[foxy] offline, and the token is from another mint: refused');
      this.receivingDown();
      this.blockedCard('offlineOtherMint', {
        tone: 'warn',
        title: 'HIGH RISK \u2014 YOU\u2019RE OFFLINE',
        reason: 'This ecash is from ' + (this.mintNameOf(mint) || 'another mint')
          + ', not your mint. Offline, Foxy cannot check it or bring it home, so it was not accepted. '
          + 'Reconnect and scan it again.',
      });
      return true;
    }

    this.setState(p => ({
      screen: 'newMint', stack: p.stack.concat([p.screen]),
      nmInfo: { sats: info.sats, mint: mint, unit: unit, amount: info.amount }, nmToken: text,
      nmPlan: null, nmErr: '', nmStage: '', nmBusy: false, nmTooSmall: false,
    }));
    setTimeout(() => this.nmQuote(), 60);
    return true;
  }

  /* Another unit's token from a mint with nothing filed: it cannot be moved
   * home (a move is a Lightning payment in sats), so redeeming keeps it at its
   * own mint, in its own unit. */
  newMintKeep() {
    const W = window.FoxyWallet;
    const info = this.state.nmInfo;
    if (!info || this.state.nmBusy) return;
    // claiming at the token's mint switches there
    if (this.refuseSwitchWhileBusy()) return;
    const name = this.mintNameOf(info.mint);
    /* Kept at its own mint, and the wallet back on yours afterwards: keeping a
     * token there is not choosing that mint to use. */
    const home = String(W.mintUrl || '');
    this.setState({ nmBusy: true, nmErr: '', nmStage: 'Keeping it at ' + name + '\u2026' });
    this.showMelt('Keeping it at ' + name + '\u2026');
    W.receiveToken(this.state.nmToken).then(r => {
      const back = (r.switched && home) ? W.connect(home).then(() => true, () => false) : Promise.resolve(false);
      return back.then(returned => {
        this.hideMelt();
        this.setState({ nmBusy: false, nmStage: '', nmInfo: null, nmPlan: null, nmToken: '', nmTooSmall: false, screen: 'home', stack: [] });
        this.walletReady({ name: returned ? this.mintNameOf(home) : r.host });
        if (r.unit && r.unit !== 'sat') this.tookToken(r);
        else this.toast('Kept ' + this.group(r.sats || info.sats) + ' sats at ' + name);
      });
    }).catch(e => {
      this.hideMelt();
      this.setState({ nmBusy: false, nmStage: '', nmErr: W.reason(e) });
    });
  }

  /* Say what a token receive took, when it was not sats. A sat receive is
   * confirmed by the balance counting up; another unit does not move it. */
  /* Ecash kept with no route, and what the person is shown for it.
   *
   * Locked to this phone, it is received and gets the confirmation any
   * payment gets. Taken on trust, it is not — it says so in history, in red,
   * and gets its confirmation when it settles. */
  keptOfflineSaid(r) {
    if (!r || !r.kept || r.trusted) return;
    this._seenTx = this._seenTx || {};
    if (r.hash) this._seenTx[r.hash] = true;
    this.loadHistory();
    this.announcePayment({ dir: 'in', sats: r.sats, force: true, to: 'ecash',
                           hash: r.hash || ('kept-' + Date.now()) });
  }

  /* PAYMENT RECEIVED for a token the person scanned or pasted themselves.
   *
   * It was left to the history pass, which announces every new entry — and
   * holds its tongue for two minutes after a move between mints, so a token
   * scanned 27 seconds after one was taken, counted, and never confirmed
   * (the log said "confirmation held back: in 800").
   * A person who just scanned a code is owed the screen, whatever else is
   * going on. Marked seen first, so the pass does not announce it twice. */
  announceTaken(r) {
    if (!r || r.kept || !r.hash || !(Number(r.sats) > 0)) return;
    if (r.unit && r.unit !== 'sat') return;
    this._seenTx = this._seenTx || {};
    if (this._seenTx[r.hash]) return;
    this._seenTx[r.hash] = true;
    this.announcePayment({ dir: 'in', sats: Number(r.sats), hash: r.hash, force: true });
  }

  tookToken(r) {
    if (!r || !r.unit || r.unit === 'sat') return;
    this.toast('Received ' + this.unitMoney(r.amount, r.unit) + ' in ' + this.unitLabel(r.unit)
      + ' ecash at ' + r.host);
  }

  /* Is the new-mint screen showing a token in a unit other than sats? */
  nmUnit() {
    const i = this.state.nmInfo;
    return !!(i && i.unit && i.unit !== 'sat');
  }

  nmUnitNote() {
    if (!this.nmUnit()) return '';
    const i = this.state.nmInfo;
    const label = this.unitLabel(i.unit);
    return 'This is ' + label + ' ecash. Foxy cannot move it to your mint, so redeeming keeps it at '
      + String(i.mint).replace(/^https?:\/\//, '') + ' as ' + label + ' ecash. Reject and the token stays as it is.';
  }

  /* Price it while it is still a string, so rejecting costs nothing. */
  nmQuote() {
    const W = window.FoxyWallet;
    const info = this.state.nmInfo;
    if (!info) return;
    // nothing to price: another unit is kept where it is, not moved
    if (info.unit && info.unit !== 'sat') {
      this.setState({ nmPlan: null, nmStage: '', nmErr: '' });
      return;
    }
    this.setState({ nmStage: '', nmErr: '' });
    /* The two banks, with the move being priced between them (FoxyMoving).
     * The same picture carries on under MOVING ECASH TO YOUR MINT when they
     * say to go ahead. The melt loader is what a page
     * without that file falls back to. */
    if (!this.movingUp('VERIFYING ECASH', info.mint)) {
      if (!document.getElementById('foxy-melt')) this.showMelt('');
      this.meltHeading(this.mintNameOf(info.mint).toUpperCase(),
        'This token is from a mint you don\u2019t use. Foxy is checking the fee to move it.');
      this.meltSays('');
    }

    // Tor's first request through a new circuit fails often enough that one
    // refusal means little. Try again after a moment before reporting it.
    const ask = (tries) => W.sweepQuote(info.mint, info.sats).catch(e => {
      // a fee larger than the token is an answer, not a failure to get one
      if (tries <= 0 || /more than the token is worth/i.test(String((e && e.message) || e))) throw e;
      console.log('[foxy] fee quote failed, retrying:', (e && e.message) || e);
      this.meltSays('Still checking\u2026');
      return new Promise(r => setTimeout(r, 2500)).then(() => ask(tries - 1));
    });

    ask(2).then(plan => {
      // the figures are on screen and REDEEM is live: nothing left to wait for
      this.movingDown();
      this.setState({ nmPlan: plan, nmStage: '' });
    }).catch(e => {
      this.movingDown();
      // too small to move: keeping it at its mint, or leaving it, is what is left
      const tooSmall = /more than the token is worth/i.test(String((e && e.message) || e));
      this.setState({ nmPlan: null, nmStage: '', nmErr: W.reason(e), nmTooSmall: tooSmall });
    });
  }

  /* Claim at the token's own mint, then pay it home.
   *
   * The claim is first and is never skipped: if the move fails the sats are
   * already yours at that mint rather than sitting in a string somebody else
   * holds a copy of.
   */
  newMintRedeem() {
    const W = window.FoxyWallet;
    const plan = this.state.nmPlan;
    if (!plan || this.state.nmBusy) return;
    // the claim and the move both connect to other mints
    if (this.refuseSwitchWhileBusy()) return;
    // one line for the whole move, claim and payment alike
    this.setState({ nmBusy: true, nmErr: '', nmStage: 'Moving to your mint\u2026' });
    // the same two banks again, now with the sats actually crossing between them
    if (!this.movingUp('MOVING ECASH TO YOUR MINT', this.state.nmInfo && this.state.nmInfo.mint)) {
      this.showMelt('Moving to your mint\u2026');
    }
    this._quiet = true;
    this._hushUntil = Date.now() + 120000;
    this.expectOwnSpend();
    // what history holds before any of this, so the entries the sweep creates
    // can be marked as already seen rather than announced one by one later
    W.transactions(50).then(list => {
      this._sweepBefore = new Set(list.map(x => x.hash));
    }).catch(() => { this._sweepBefore = null; });

    W.receiveToken(this.state.nmToken).then(r => {
      return W.moveRun(plan, () => {}).then(done => this.hushSweepEntries().then(() => done)).then(done => {
        /* The move's own history entries are marked seen, and taken out of the
         * confirmation queue, before anything reloads history. walletReady ran
         * first, queued the claim at this mint as a payment received, and it
         * showed as a second confirmation when the move's own was dismissed. */
        this.movingDown();
        this._quiet = false;
        // what landed, not what the token said before fees
        this._netLanded = done.sats;
        this.setState({ nmBusy: false, nmStage: '', nmInfo: null, nmPlan: null, nmToken: '' });
        this.walletReady({ name: done.name || plan.to.replace(/^https?:\/\//, '') });
        console.log('[foxy] sweep done:', done.sats, 'sats landed |',
                    'quoted at most', plan.feeMax, 'fee |',
                    (done.leftBehind || 0), 'left at the source');

        // A second pass for the change whenever it can pay for itself.
        //
        // This used to be a flat 60-sat threshold, which was a guess: 19 sats
        // of change is well worth moving at a cost of 3, and the guess left it
        // behind. Ask the mint what the move costs and let the answer decide —
        // sweepQuote refuses outright when the fee exceeds the amount, so a
        // failed quote IS the answer for dust.
        const left = done.leftBehind || 0;
        if (left > 0) {
          console.log('[foxy] change of', left, 'sats \u2014 asking what moving it costs');
          this.sweepChange(done.from, left, done.sats);
          return;
        }
        // stragglers can still arrive after this, so the window stays open a
        // little longer and closes itself
        this._hushUntil = Date.now() + 30000;
        this.noteReceived();
        this.announcePayment({
          dir: 'in', sats: done.sats, force: true,
          hash: 'sweep-' + Date.now(), to: 'ecash',
        });
      }).catch(e => {
        this.movingDown();
        this._quiet = false;
        this.setState({
          nmBusy: false, nmStage: '',
          nmErr: W.reason(e) + ' The sats are safe at ' + r.host + '.',
        });
        this.walletReady({ name: r.host });
      });
    }).catch(e => {
      this.movingDown();
      this._quiet = false;
      this.setState({ nmBusy: false, nmStage: '', nmErr: W.reason(e) });
    });
  }

  /* Expect proofs to disappear, because we are about to spend them.
   *
   * reconcile runs on a timer and compares what the mint says is unspent
   * against what is filed here, so a melt this wallet performed shows up as a
   * discrepancy a few seconds later. The window stays open long enough to
   * cover the reconcile that follows, then closes on its own — a flag that
   * stayed set would hide a real loss.
   */
  expectOwnSpend(ms) {
    this._expectSpend = true;
    clearTimeout(this._expectT);
    this._expectT = setTimeout(() => {
      this._expectSpend = false;
      console.log('[foxy] watching for outside spends again');
    }, ms || 90000);
  }

  /* Mark every entry the sweep created as already announced.
   *
   * A sweep writes three: claimed at their mint, melted out of it, credited at
   * yours. All three are real and all three belong in history — but the person
   * did one thing, so they get one confirmation. The history sweep runs on its
   * own schedule, which is why silencing for a moment was not enough.
   */
  hushSweepEntries() {
    const W = window.FoxyWallet;
    const before = this._sweepBefore;
    this._sweepBefore = null;
    return W.transactions(50).then(list => {
      this._seenTx = this._seenTx || {};
      let n = 0;
      const mine = {};
      list.forEach(x => {
        if (before && before.has(x.hash)) return;
        this._seenTx[x.hash] = true;
        mine[x.hash] = true;
        n++;
      });
      // and any a history pass already queued for a confirmation
      if (this._paidQueue && this._paidQueue.length) {
        this._paidQueue = this._paidQueue.filter(q => !(q && mine[q.hash]));
      }
      if (n) console.log('[foxy] sweep wrote', n, 'entries, none to announce');
    }).catch(() => {});
  }

  /* Move the change left at the source mint, then confirm the total.
   *
   * Runs quietly: the person asked for one transfer, not two, so the second
   * pass reports as part of the first. If it cannot be quoted or fails, the
   * change simply stays where it is and the confirmation says what landed.
   */
  sweepChange(from, left, already) {
    const W = window.FoxyWallet;
    this.expectOwnSpend();
    // one extra pass only: the second move leaves its own change, and chasing
    // that forever would spend more on quotes than it recovers
    if (this._chasingChange) { return; }
    /* Collecting the change connects to the source mint. If a payment started
     * while the first move ran, that switch would pull it onto the wrong mint,
     * so the change stays where it is — still spendable there — and the
     * confirmation reports what landed. Checked before this pass marks itself
     * busy, or it would always refuse. */
    if (this.moneyBusy()) {
      console.log('[foxy] change of', left, 'sats left at the source: a payment is in progress');
      this._quiet = false;
      this._hushUntil = Date.now() + 30000;
      this.announcePayment({
        dir: 'in', sats: already, force: true,
        hash: 'sweep-' + Date.now(), to: 'ecash',
      });
      return;
    }
    this._chasingChange = true;
    this._sweepBefore = null;
    this.showMelt('Moving to your mint\u2026');
    this._quiet = true;

    const done = (extra, note) => {
      this.hideMelt();
      this._quiet = false;
      this._chasingChange = false;
      this.refreshBalance();
      this.loadHistory();
      if (note) console.log('[foxy] change:', note);
      this._hushUntil = Date.now() + 30000;
      this.announcePayment({
        dir: 'in', sats: already + (extra || 0), force: true,
        hash: 'sweep-' + Date.now(), to: 'ecash',
      });
    };

    // Quote FIRST, while this wallet is still on the destination mint.
    // Connecting to the source before quoting made sweepQuote read the source
    // as both ends and refuse with "already from this mint" — and left the app
    // sitting on the source mint's balance afterwards.
    W.sweepQuote(from, left)
      .then(plan => W.connect(from).then(() => W.moveRun(plan, () => {})))
      .then(r => this.hushSweepEntries()
        .then(() => done(r.sats, 'moved ' + r.sats + ', ' + (r.leftBehind || 0) + ' still left')))
      .catch(e => {
        // the quote refused, which means the fee is more than the change
        // no banner: dust staying put is not news, and the log has it
        console.log('[foxy] change left where it is:', (e && e.message) || e);
        done(0, 'not worth moving');
      });
  }

  /* Somebody pasted ecash into the send box. It is still just a token. */
  takeTokenFromPaste(text) {
    const W = window.FoxyWallet;
    console.log('[foxy] token pasted into send |', String(text || '').length, 'chars');
    /* Guarded for as long as the claim runs (takingToken). This door had
     * nothing at all: a second paste while the first was still swapping
     * started a second claim of the same token. */
    this.takingToken(() => {
      if (this.offerNewMint(text)) return null;
      if (this.tokenSwitchRefused(text)) return null;
      this._preSettle = this.balNow();
      // something moving between the paste and the payment landing.
      // The full screen when it is there, the small loader when it is not.
      this.receivingUp('VERIFYING ECASH');
      return W.receiveToken(text).then(r => {
        this.receivingDown();
        this.walletReady({ name: r.host });
        this.tookToken(r);
        this.announceTaken(r);
        this.keptOfflineSaid(r);
        this.settleAnimate('btc');
        this.noteReceived();
        if (r.switched) this.toast('Now on ' + r.host);
      }).catch(e => {
        this.receivingDown();
        /* Retry with the token already in hand. It used to retry by calling
         * pasteEcashToken, which refuses to run anywhere but the amount
         * screen — and nothing reaching here is on it. So TRY AGAIN closed
         * the card and did nothing at all. */
        this.claimFailed(e, () => this.takeTokenFromPaste(text));
      });
    });
  }

  /* The verifying-ecash screen (Web/foxy-receive-progress.js), with the small
   * melt loader behind it for a page where that file did not load. */
  receivingUp(title) {
    /* Nothing is verified with no route, and a screen that says so is up
     * for an answer that is already known. */
    if (this.offlineNow && this.offlineNow()) return;
    const R = window.FoxyReceiving;
    /* What STOP WAITING on that screen does: back to home, and the next scan
     * is let through. The check itself is not stopped — nothing here can stop
     * a request already with the mint — and its answer still lands when it
     * comes. */
    /** @type {any} */ (window).__foxyStopWaiting = () => {
      console.log('[foxy] receiving: the person stopped waiting for the mint; the check goes on behind');
      clearTimeout(this._takingT);
      this._takingToken = false;
      this.setState({ screen: 'home', stack: [] });
      this.toast('Still checking with the mint.', false);
    };
    if (R && R.begin(title)) return;
    this.showMelt('Receiving ecash\u2026');
  }

  receivingDown() {
    const R = window.FoxyReceiving;
    if (R && R.visible()) { R.end(); return; }
    this.hideMelt();
  }

  /* The two-bank screen for a token from a mint this wallet does not use
   * (Web/foxy-move-progress.js). Already up, it keeps its animation and only
   * the words change — the move is priced and then made, and it is the same
   * move. Answers false when that file did not load, so the caller can fall
   * back to the melt loader.
   *
   * `from` is the token's mint; the other bank is the one you are on. */
  movingUp(title, from) {
    const M = window.FoxyMoving;
    if (!M) return false;
    if (M.visible()) return M.retitle(title);
    return M.begin(title, {
      from: this.mintNameOf(from) || 'THEIR MINT',
      to: this.mintName() || 'YOUR MINT',
    });
  }

  movingDown() {
    const M = window.FoxyMoving;
    if (M && M.visible()) { M.end(); return; }
    this.hideMelt();
  }

  /* The same thing through the camera. A token is often handed over as a QR,
   * and the string is too long to retype. */
  scanEcashToken() {
    const W = window.FoxyWallet;
    if (!W || !W.scan) return;
    W.scan('Scan an ecash token').then(text => {
      const t = String(text || '').trim();
      if (W.classify(t) !== 'token') {
        this.toast('That QR is not a Cashu token.', true);
        return;
      }
      this.receivingUp('VERIFYING ECASH');
      if (this.offerNewMint(t)) { this.receivingDown(); return; }
      if (this.tokenSwitchRefused(t)) { this.receivingDown(); return; }
      // the figure before the claim, for the count-up
      this._preSettle = this.balNow();
      return W.receiveToken(t).then(r => {
        this.receivingDown();
        this.walletReady({ name: r.host });
        this.tookToken(r);
        this.announceTaken(r);
        this.settleAnimate('btc');
        this.noteReceived();
        // no banner: the pill counting up is the confirmation. A switched mint
        // is worth saying out loud, though — the wallet moved under them.
        if (r.switched) this.toast('Now on ' + r.host);
      });
    }).catch(e => { this.receivingDown(); this.claimFailed(e, () => this.scanEcashToken()); });
  }

  /* Pull back a token that never landed. Whoever swaps first wins, so this
   * fails cleanly if the other person already claimed it. */
  reclaimFromTx(token) {
    const W = window.FoxyWallet;
    if (!token || this.state.txReclaiming) return;
    this.setState({ txReclaiming: true });
    // the same animation a receive shows: a swap at the mint over Tor takes seconds
    this.showMelt('Taking back your sats\u2026');
    // whatever it is made of: a payment out of ecash locked to this phone is taken back too (`takeBackToken`)
    (W.takeBackToken ? W.takeBackToken(token) : W.reclaimToken(token)).then(r => {
      this.hideMelt();
      this.setState({ txReclaiming: false, screen: 'home', stack: [] });
      this.walletReady({ name: r.host });
      this.toast('Took back ' + this.group(r.sats) + ' sats');
      this.loadHistory();
    }).catch(e => {
      this.hideMelt();
      this.setState({ txReclaiming: false });
      this.toast(W.reason(e), true);
    });
  }

  /* Type a mint url rather than scanning one. Uses the same prompt sheet the
   * rest of the app uses for text entry. */
  /* Type a mint's address.
   *
   * window.prompt was a placeholder: it renders as an iOS system dialog with
   * none of the app's styling and no control over the keyboard. This is the
   * app's own sheet, with the keyboard up on open and ADD live only once what
   * has been typed could actually be a mint.
   */
  typeMint() {
    const root = document.createElement('div');
    root.style.cssText =
      'position:fixed;inset:0;z-index:2147483500;background:rgba(0,0,0,.72);' +
      'display:flex;flex-direction:column;justify-content:flex-end;' +
      'animation:foxyIn .16s ease';

    const card = document.createElement('div');
    card.style.cssText =
      'background:#141518;border-radius:28px 28px 0 0;padding:26px 24px ' +
      'calc(26px + env(safe-area-inset-bottom));display:flex;flex-direction:column;gap:14px;' +
      'transition:transform .18s ease';

    /* Sit above the keyboard.
     *
     * The page is not resized for the keyboard here, so a card anchored to the
     * bottom ends up underneath it — field invisible, ADD unreachable.
     * visualViewport reports how much is covered; the card moves by that. */
    const kbTimers = [];
    const pinScroll = () => {
      if (window.scrollY || document.documentElement.scrollTop) window.scrollTo(0, 0);
    };
    window.addEventListener('scroll', pinScroll, true);
    const lift = () => {
      pinScroll();
      const vv = window.visualViewport;
      if (!vv) return;
      const gap = Math.max(0, window.innerHeight - vv.height - vv.offsetTop);
      card.style.transform = gap > 80 ? 'translateY(-' + Math.round(gap) + 'px)' : 'none';
    };
    if (window.visualViewport) {
      window.visualViewport.addEventListener('resize', lift);
      window.visualViewport.addEventListener('scroll', lift);
    }
    const done = () => {
      kbTimers.forEach(clearTimeout);
      window.removeEventListener('scroll', pinScroll, true);
      if (window.visualViewport) {
        window.visualViewport.removeEventListener('resize', lift);
        window.visualViewport.removeEventListener('scroll', lift);
      }
      root.remove();
    };

    const title = document.createElement('div');
    title.style.cssText =
      'font-family:Sora,system-ui,sans-serif;font-size:22px;font-weight:800;' +
      'letter-spacing:-0.022em;color:#F5F1EC;text-align:center';
    title.textContent = 'MINT ADDRESS';
    card.appendChild(title);

    const hint = document.createElement('div');
    hint.style.cssText =
      'font-size:18px;font-weight:600;line-height:1.4;color:rgba(245,241,236,.55);' +
      'text-align:center;text-wrap:pretty';
    hint.textContent = 'The web address of a Cashu mint.';
    card.appendChild(hint);

    const input = document.createElement('input');
    input.type = 'url';
    input.value = 'https://';
    input.autocapitalize = 'none';
    /* The attribute, not the property. The autocorrect property is a boolean, so
     * assigning it 'off' turned autocorrect on where WebKit has the property,
     * and did nothing where it does not. Found by the app's type check. */
    input.setAttribute('autocorrect', 'off');
    input.spellcheck = false;
    input.style.cssText =
      'height:56px;border-radius:18px;background:#0B0B0C;border:1.5px solid ' +
      'rgba(245,241,236,.18);box-sizing:border-box;padding:0 16px;color:#F5F1EC;' +
      'font-family:ui-monospace,Menlo,monospace;font-size:17px;outline:none';
    card.appendChild(input);

    const add = document.createElement('div');
    const setLive = () => {
      const ok = /^https:\/\/[a-z0-9.-]+\.[a-z]{2,}(\/\S*)?$/i.test(input.value.trim());
      add.style.background = ok ? '#F2802E' : 'rgba(245,241,236,.12)';
      add.style.color = ok ? '#fff' : 'rgba(245,241,236,.4)';
      add.style.cursor = ok ? 'pointer' : 'default';
      add.dataset.ok = ok ? '1' : '';
    };
    add.style.cssText =
      'height:60px;border-radius:30px;display:flex;align-items:center;' +
      'justify-content:center;font-family:Sora,system-ui,sans-serif;font-size:20px;' +
      'font-weight:800;letter-spacing:0.02em';
    add.textContent = 'ADD';
    add.addEventListener('click', () => {
      if (!add.dataset.ok) return;
      if (add.dataset.busy) return;
      const clean = input.value.trim().replace(/\/+$/, '');

      /* Stay up while it connects.
       *
       * Over Tor this is a second or two. Closing first put the person back on
       * the list with nothing moving and no sign the tap had registered. */
      add.dataset.busy = '1';
      input.blur();
      add.innerHTML =
        '<div style="width:19px;height:19px;border-radius:50%;border:2px solid ' +
        'rgba(255,255,255,.28);border-top-color:#fff;margin-right:10px" ' +
        'id="fx-mint-spin"></div>CONNECTING\u2026';
      add.style.display = 'flex';
      add.style.alignItems = 'center';
      add.style.justifyContent = 'center';

      const spin = document.getElementById('fx-mint-spin');
      const t0 = performance.now();
      let raf = requestAnimationFrame(function turn(now) {
        if (spin) spin.style.transform = 'rotate(' + ((now - t0) / 900 * 360 % 360).toFixed(1) + 'deg)';
        raf = requestAnimationFrame(turn);
      });

      // justSwitch owns switchBusy; watching it means the sheet closes on
      // whatever ends the connect, success or failure, with no second timer
      // that could disagree with it.
      const watch = setInterval(() => {
        if (this.state.switchBusy) return;
        clearInterval(watch);
        cancelAnimationFrame(raf);
        done();
      }, 200);
      // and a ceiling, so a connect that never settles cannot strand the sheet
      setTimeout(() => {
        clearInterval(watch);
        cancelAnimationFrame(raf);
        done();
      }, 45000);

      this.justSwitch(clean);
    });
    card.appendChild(add);

    const cancel = document.createElement('div');
    cancel.style.cssText =
      'height:52px;display:flex;align-items:center;justify-content:center;' +
      'font-family:Sora,system-ui,sans-serif;font-size:18px;font-weight:800;' +
      'color:rgba(245,241,236,.55);cursor:pointer';
    cancel.textContent = 'CANCEL';
    cancel.addEventListener('click', done);
    card.appendChild(cancel);

    input.addEventListener('input', setLive);
    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') add.click(); });
    setLive();

    root.appendChild(card);
    root.addEventListener('click', (e) => { if (e.target === root) done(); });
    document.body.appendChild(root);
    /* Synchronous, for the same reason as the note sheet: iOS only opens the
     * keyboard for a focus inside the gesture that caused it. */
    input.focus();
    try {
      const n = input.value.length;
      input.setSelectionRange(n, n);
    } catch (e) {}
    lift();
    kbTimers.push(setTimeout(() => {
      input.focus();
      const n = input.value.length;
      try { input.setSelectionRange(n, n); } catch (e) {}
      lift();
    }, 140));
    kbTimers.push(setTimeout(lift, 320));
    kbTimers.push(setTimeout(lift, 700));
  }

  /* Money arrived, by whatever route.
   *
   * The prompt used to hang off the invoice watcher alone, so a token claimed
   * by paste or scan — which is most of how this wallet receives — never
   * raised it. Every arrival calls this instead.
   */
  noteReceived() {
    const W = window.FoxyWallet;
    this.setState({ everReceived: true });
    if (!W.backedUp || W.backedUp() || this.state.dismissedBackup) return;
    if (this.backupAskedLately()) return;

    // Wait for home. The prompt was rising over the payment confirmation,
    // stacking one thing to read on top of another and burying the amount
    // that had just arrived. It belongs on the screen you land on afterwards.
    clearTimeout(this._bkAskT);
    let waited = 0;
    const raise = () => {
      if (W.backedUp() || this.state.dismissedBackup) return;
      // another arrival may have raised it while this one waited for home
      if (this.backupAskedLately()) return;
      if (this.state.screen !== 'home') {
        waited += 900;
        if (waited > 90000) return;
        this._bkAskT = setTimeout(raise, 900);
        return;
      }
      this.backupAskedNow();
      this.setState({ bkAskOpen: true });
    };
    this._bkAskT = setTimeout(raise, 1400);
  }

  /* BACK UP YOUR BITCOIN, once in a day.
   *
   * It rose after every payment until the words were written down, which is
   * the right thing to say and the wrong number of times to say it: somebody
   * taking payments all afternoon pressed DO THIS LATER after each one. Now
   * it is said once and not again for twenty-four hours, counted from when
   * it was raised and kept across launches. A clock that has gone backwards
   * does not silence it. The line on the home screen is still there in
   * between. */
  BACKUP_ASK_EVERY_MS = 86400000;

  backupAskedLately() {
    let at = 0;
    try { at = Number(localStorage.getItem('foxy.backup.asked')) || 0; } catch (e) {}
    const since = Date.now() - at;
    return at > 0 && since >= 0 && since < this.BACKUP_ASK_EVERY_MS;
  }

  backupAskedNow() {
    try { localStorage.setItem('foxy.backup.asked', String(Date.now())); } catch (e) {}
  }

  /* Check the phrase was actually written down: the phone's own quiz, with
   * the words it keeps (showSeedOnPhone). The page's quiz, which tapped the
   * twelve words back in order here, is gone with the words. */
  showVerify() {
    return this.showSeedOnPhone(true);
  }

  /* The note on a payment being sent, on its own overlay.
   *
   * Same reason as the token screen's: the shared editor renders on top of
   * the screen beneath it rather than replacing it, so both headers draw at
   * once and neither is readable.
   */
  editSendNote() {
    this.noteSheet(this.state.note || '', (text) => {
      this.setState({ note: text });
    });
  }

  /* A note on the token, written on its own overlay.
   *
   * The shared note editor assumes the invoice screen underneath it; on this
   * screen both headers drew at once. This is plain DOM, like the seed screen
   * and the loader, so nothing can render through it.
   */
  editTokenNote() {
    const W = window.FoxyWallet;
    const out = W.lastToken() || {};
    const hash = out.hash;
    if (!hash) { this.toast('Nothing to note yet.', true); return; }
    this.noteSheet((W.tagsFor(hash) || {}).note || '', (text) => {
      W.tag(hash, { note: text });
      this.loadHistory();
    });
  }

  /* The note on a payment already made, from its detail screen: added where
   * there is none, changed where there is one, and taken off by saving it
   * empty. Kept on this phone only (`W.tag`), like every note. */
  editTxNote() {
    const W = window.FoxyWallet;
    const tx = this.state.tx || {};
    if (!tx.hash || !W || !W.tag) return;
    this.noteSheet(tx.note || '', (text) => {
      const note = String(text || '').trim();
      W.tag(tx.hash, { note: note });
      this.setState(p => ({ tx: Object.assign({}, p.tx, { note: note }) }));
      this.loadHistory();
    }, { edit: true });
  }

  /* One sheet, every caller. `o.edit`: a note that exists may be saved
   * empty, which removes it. */
  noteSheet(existing, onSave, o) {
    const editing = !!(o && o.edit) && !!String(existing || '').trim();

    const root = document.createElement('div');
    root.style.cssText =
      'position:fixed;inset:0;z-index:2147483500;background:rgba(0,0,0,.72);' +
      'display:flex;flex-direction:column;justify-content:flex-end;' +
      'animation:foxyIn .16s ease';

    const card = document.createElement('div');
    card.style.cssText =
      'background:#141518;border-radius:28px 28px 0 0;padding:26px 24px ' +
      'calc(26px + env(safe-area-inset-bottom));display:flex;flex-direction:column;gap:14px;' +
      'transition:transform .18s ease';

    /* Sit above the keyboard.
     *
     * iOS does not resize the page for the keyboard here, so a sheet anchored
     * to the bottom ends up underneath it — the field invisible and the button
     * unreachable.
     *
     * visualViewport is the measurement when it works: it says how much of the
     * page is covered and the card lifts by exactly that. In this web view it
     * frequently reports nothing at all, and then there is no height to lift
     * by. So the fallback does not guess a keyboard height — it moves the card
     * to the top of the screen, which no keyboard can reach. Decided ~420ms
     * after focus, by which time a real measurement would have arrived.
     */
    const timers = [];
    let pinned = false;

    /* iOS scrolls the document to bring a focused field into view. This card
     * is position:fixed, so there is nothing to scroll to and the attempt just
     * slides the page, showing whatever is behind it. Hold it at zero. */
    const pinScroll = () => {
      if (window.scrollY || document.documentElement.scrollTop) window.scrollTo(0, 0);
    };
    window.addEventListener('scroll', pinScroll, true);

    const covered = () => {
      const vv = window.visualViewport;
      if (!vv) return 0;
      return Math.max(0, window.innerHeight - vv.height - vv.offsetTop);
    };

    const lift = () => {
      pinScroll();
      const gap = covered();
      if (gap > 80) {
        pinned = false;
        root.style.justifyContent = 'flex-end';
        card.style.borderRadius = '28px 28px 0 0';
        card.style.paddingTop = '26px';
        card.style.paddingBottom = '26px';
        card.style.transform = 'translateY(-' + Math.round(gap) + 'px)';
      } else if (!pinned) {
        root.style.justifyContent = 'flex-end';
        card.style.borderRadius = '28px 28px 0 0';
        card.style.paddingTop = '26px';
        card.style.paddingBottom = 'calc(26px + env(safe-area-inset-bottom))';
        card.style.transform = 'none';
      }
    };

    const pinTop = () => {
      if (covered() > 80) return;
      pinned = true;
      root.style.justifyContent = 'flex-start';
      card.style.borderRadius = '0 0 28px 28px';
      card.style.paddingTop = 'calc(26px + env(safe-area-inset-top))';
      card.style.paddingBottom = '26px';
      card.style.transform = 'none';
    };

    if (window.visualViewport) {
      window.visualViewport.addEventListener('resize', lift);
      window.visualViewport.addEventListener('scroll', lift);
    }

    const title = document.createElement('div');
    title.style.cssText =
      'font-family:Sora,system-ui,sans-serif;font-size:22px;font-weight:800;' +
      'letter-spacing:-0.022em;color:#F5F1EC;text-align:center';
    title.textContent = 'WHAT IS THIS FOR?';
    card.appendChild(title);

    const input = document.createElement('input');
    input.type = 'text';
    input.maxLength = 120;
    input.value = existing;
    input.placeholder = 'Lunch, rent, a gift\u2026';
    input.style.cssText =
      'height:56px;border-radius:18px;background:#0B0B0C;border:1.5px solid ' +
      'rgba(245,241,236,.18);box-sizing:border-box;padding:0 16px;color:#F5F1EC;' +
      'font-family:Figtree,system-ui,sans-serif;font-size:18px;outline:none';
    card.appendChild(input);

    const save = document.createElement('div');
    save.style.cssText =
      'height:60px;border-radius:30px;display:flex;align-items:center;' +
      'justify-content:center;font-family:Sora,system-ui,sans-serif;font-size:20px;' +
      'font-weight:800;letter-spacing:0.02em';
    save.textContent = editing ? 'SAVE' : 'ADD';
    const setLive = () => {
      const ok = editing || input.value.trim().length > 0;
      save.style.background = ok ? '#F2802E' : 'rgba(245,241,236,.12)';
      save.style.color = ok ? '#fff' : 'rgba(245,241,236,.4)';
      save.style.cursor = ok ? 'pointer' : 'default';
      save.dataset.ok = ok ? '1' : '';
    };
    save.addEventListener('click', () => {
      if (!save.dataset.ok) return;
      close();
      onSave(input.value.trim());
    });
    input.addEventListener('input', setLive);
    input.addEventListener('keydown', (e) => { if (e.key === 'Enter') save.click(); });
    setLive();
    card.appendChild(save);

    const cancel = document.createElement('div');
    cancel.style.cssText =
      'height:52px;display:flex;align-items:center;justify-content:center;' +
      'font-family:Sora,system-ui,sans-serif;font-size:18px;font-weight:800;' +
      'color:rgba(245,241,236,.55);cursor:pointer';
    cancel.textContent = 'CANCEL';
    cancel.addEventListener('click', () => close());
    card.appendChild(cancel);

    function close() {
      timers.forEach(clearTimeout);
      window.removeEventListener('scroll', pinScroll, true);
      if (window.visualViewport) {
        window.visualViewport.removeEventListener('resize', lift);
        window.visualViewport.removeEventListener('scroll', lift);
      }
      root.remove();
    }

    root.appendChild(card);
    root.addEventListener('click', (e) => { if (e.target === root) close(); });
    document.body.appendChild(root);
    /* Synchronous, inside the tap that opened this sheet.
     *
     * iOS raises the keyboard only for a focus that happens within the user
     * gesture. Deferring it by even one tick left the field focused with the
     * keyboard down, which is why tapping the field again fixed it — that tap
     * was itself a gesture. The timed call below stays as a fallback. */
    input.focus();
    timers.push(setTimeout(() => { input.focus(); lift(); }, 90));
    timers.push(setTimeout(lift, 260));
    timers.push(setTimeout(pinTop, 420));
    timers.push(setTimeout(pinTop, 900));
  }

  /* The melt animation, for the waits that are long enough to look broken.
   *
   * Claiming at an unfamiliar mint means loading its keysets and swapping,
   * which over Tor is several seconds of nothing. The clipboard read plus a
   * claim is shorter but still long enough to feel stuck.
   */
  /* How long the overlay stays up with nobody taking it down. Long enough for
   * the short waits; callers whose work can run longer pass their own. */
  MELT_PATIENCE_MS = 45000;

  /* `o.sats` and `o.mint` are the two figures on the bill, and `o.onCancel` is
   * the only thing that puts a CANCEL under it — a button that cannot stop what
   * it is over would be worse than none, and most of these waits are a swap the
   * mint has already begun. */
  showMelt(label, patience, o) {
    const opts = o || {};
    this.hideMelt();
    const W = window.FoxyWallet;
    const root = document.createElement('div');
    root.id = 'foxy-melt';
    root.style.cssText =
      'position:fixed;inset:0;z-index:2147483400;'
      + 'display:flex;flex-direction:column;animation:foxyIn .18s ease';

    /* The heading is the caller's own words, which are already what this wait
     * is. The export's dots animate under it and say "still going", so the
     * ellipsis those words end with is dropped rather than shown twice. */
    const title = String(label || 'Verifying ecash').replace(/[\u2026.]+\s*$/, '');
    const sats = Number(opts.sats) > 0 ? this.group(Math.round(opts.sats)) : '';
    const mintName = String(opts.mint || (this.mintNameOf && this.mintNameOf(W && W.mintUrl)) || '');
    const esc = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    root.innerHTML = this.loaderVerifying()
      .replace('{{TITLE}}', esc(title))
      .replace('{{SATS}}', esc(sats))
      .replace('{{MINT}}', esc(mintName.toUpperCase()))
      .replace('{{CANCEL}}', '');

    /* The caption the old overlay carried, kept: `meltSays` writes to it while
     * a wait goes on, and several callers do. Under the dots, quiet. */
    const cap = document.createElement('div');
    cap.id = 'foxy-melt-label';
    cap.style.cssText = 'display:none';
    root.appendChild(cap);

    if (typeof opts.onCancel === 'function') {
      const wrap = document.createElement('div');
      wrap.style.cssText = 'position:absolute;left:0;right:0;bottom:0;z-index:2;'
        + 'padding:0 24px calc(44px + env(safe-area-inset-bottom))';
      const b = document.createElement('div');
      b.style.cssText = 'width:100%;height:60px;border-radius:18px;'
        + 'border:2px solid rgba(19,51,60,.85);background:rgba(255,255,255,.35);'
        + "font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:17px;"
        + 'letter-spacing:.08em;color:#13333C;display:flex;align-items:center;'
        + 'justify-content:center;cursor:pointer';
      b.textContent = 'CANCEL';
      b.addEventListener('click', () => { this.hideMelt(); opts.onCancel(); });
      wrap.appendChild(b);
      root.appendChild(wrap);
    }

    document.body.appendChild(root);
    this._meltEl = root;

    /* A loader that outlives its task is worse than none: it hides a working
     * screen. So the overlay comes off by itself and whatever is underneath
     * can be used.
     *
     * But a backstop shorter than the work it covers is its own bug: it takes
     * the overlay off in the MIDDLE of a payment, so the screen goes live
     * while sats are still moving, and the hideMelt that ends the payment
     * finds nothing to hide. Delivering to an onion address retries for 90
     * seconds (ONION_REACH_MS) inside a 130-second bridge call, and at a flat
     * 45 seconds that is exactly what happened on a device (four `onion post
     * failed`, and `melt overlay timed out` among them). So the caller says
     * how long its work can take, and 45 seconds is only the default for the
     * short ones. */
    clearTimeout(this._meltT);
    this._meltT = setTimeout(() => {
      if (document.getElementById('foxy-melt')) {
        console.warn('[foxy] melt overlay timed out after', Math.round((patience || this.MELT_PATIENCE_MS) / 1000) + 's');
        this.hideMelt();
      }
    }, patience || this.MELT_PATIENCE_MS);
  }

  /* A title and a line above the animation, without restarting it. */
  meltHeading(title, line) {
    const root = document.getElementById('foxy-melt');
    if (!root) return;
    let head = document.getElementById('foxy-melt-head');
    if (!head) {
      head = document.createElement('div');
      head.id = 'foxy-melt-head';
      head.style.cssText = 'display:flex;flex-direction:column;align-items:center;gap:8px;padding:0 30px 10px;'
        + 'text-align:center;font-family:SatSymbol,Sora,system-ui,sans-serif';
      const t = document.createElement('div');
      t.style.cssText = 'font-size:22px;font-weight:800;letter-spacing:-0.022em;color:#F5F1EC';
      const l = document.createElement('div');
      l.style.cssText = 'font-size:18px;font-weight:500;line-height:1.4;color:rgba(245,241,236,.62);'
        + 'max-width:320px;text-wrap:pretty';
      head.appendChild(t);
      head.appendChild(l);
      root.insertBefore(head, root.firstChild);
    }
    head.children[0].textContent = title || '';
    head.children[1].textContent = line || '';
  }

  /* Change the line without restarting the animation. */
  meltSays(label) {
    const cap = document.getElementById('foxy-melt-label');
    if (cap) {
      cap.textContent = label;
      cap.style.display = label ? '' : 'none';
    }
  }

  hideMelt() {
    clearTimeout(this._meltT);
    const old = document.getElementById('foxy-melt');
    if (old && old.parentNode) old.parentNode.removeChild(old);
    this._meltEl = null;
  }

  /* Read a bearer token off the clipboard and take it.
   *
   * Only while the amount is empty — the token says what it is worth. If it
   * was issued by another mint the wallet connects there, because ecash is
   * only good at the mint that signed it, and the toast names the mint so
   * that is never a surprise.
   */
  /* One token claim at a time, however it was started.
   *
   * There are two doors to taking a pasted token — the PASTE button on the
   * amount screen, and a token recognised in whatever was pasted or scanned
   * somewhere else — and they guarded themselves separately or not at all.
   * The button held a flag for a flat 1.5 seconds; a claim is a swap over
   * Tor and takes 4 to 6. So the flag was long gone while the claim was
   * still running, and the other door had no flag in the first place.
   *
   * Both now take this, and it is held until the claim actually finishes
   * rather than until a timer says it probably has. That matters more than
   * it sounds: two claims of one token race at the mint, the loser is told
   * "already spent", and the person is looking at a wallet that says their
   * money was taken twice and arrived once.
   *
   * The backstop is only for a promise that never settles at all, and is set
   * far beyond any real claim so it can never fire during one. */
  TOKEN_CLAIM_MAX_MS = 90000;

  takingToken(run) {
    if (this._takingToken) {
      console.log('[foxy] a token is already being taken \u2014 ignored');
      return false;
    }
    this._takingToken = true;
    clearTimeout(this._takingT);
    this._takingT = setTimeout(() => {
      if (!this._takingToken) return;
      console.warn('[foxy] a token claim never finished \u2014 letting the next one through');
      this._takingToken = false;
    }, this.TOKEN_CLAIM_MAX_MS);
    const free = () => { clearTimeout(this._takingT); this._takingToken = false; };
    let out;
    try { out = run(); } catch (e) { free(); throw e; }
    if (out && typeof out.then === 'function') out.then(free, free);
    else free();          // it decided not to claim anything after all
    return true;
  }

  pasteEcashToken() {
    const W = window.FoxyWallet;
    // one at a time, and only from the screen that offers it — a share sheet
    // closing was enough to fire this a second time
    console.log('[foxy] paste ecash tapped | screen', this.state.screen,
                '| amount', JSON.stringify(this.state.amount || ''));
    if (this.state.screen !== 'amount') {
      console.log('[foxy] paste ignored: not on the amount screen');
      return;
    }
    if (parseFloat(this.state.amount) > 0) {
      console.log('[foxy] paste ignored: an amount is entered');
      this.toast('Clear the amount first \u2014 a token carries its own', true);
      return;
    }
    if (!W || !W.clipboard) return;
    this.takingToken(() => {
    this.showMelt('Reading the clipboard\u2026');
    return W.clipboard().then(text => {
      const t = String(text || '').trim();
      console.log('[foxy] clipboard:', t.length, 'chars, starts',
                  JSON.stringify(t.slice(0, 24)), '| classify', W.classify(t));
      if (!t) { this.toast('Nothing on the clipboard.', true); return; }
      if (W.classify(t) !== 'token') {
        this.hideMelt();
        console.log('[foxy] clipboard rejected:', t.length, 'chars, starts',
                    JSON.stringify(t.slice(0, 24)));
        this.toast('That is not a Cashu token.', true);
        return;
      }
      if (this.offerNewMint(t)) return;
      if (this.tokenSwitchRefused(t)) { this.hideMelt(); return; }
      const info = W.tokenInfo(t);
      // the figure before the claim, for the count-up
      this._preSettle = this.balNow();
      if (info && info.mint) {
        console.log('[foxy] token for', info.unit && info.unit !== 'sat' ? this.unitMoney(info.amount, info.unit) : this.group(info.sats) + ' sats', 'from', info.mint);
      }
      return W.receiveToken(t).then(r => {
        this.hideMelt();
        this.walletReady({ name: r.host });
        this.tookToken(r);
        this.settleAnimate('btc');
        this.noteReceived();
        // no banner: the pill counting up is the confirmation. A switched mint
        // is worth saying out loud, though — the wallet moved under them.
        if (r.switched) this.toast('Now on ' + r.host);
      });
    }).catch(e => { this.hideMelt(); this.claimFailed(e, null); });
    });
  }

  /* What is filed under a mint, read straight from storage. No network: the
   * proofs are the balance, and they are already here. */
  mintPile(url) {
    let sats = 0;
    try {
      const raw = localStorage.getItem('foxy.cashu.proofs.' + url);
      sats = raw ? JSON.parse(raw).reduce((n, p) => n + Number(p.amount || 0), 0) : 0;
    } catch (e) {}
    // other units at this mint, each in its own: '1,200 sats + $1.23'
    const units = this.otherUnitsAt(url);
    const parts = (sats > 0 ? [this.group(sats) + ' sats'] : []).concat(units.map(b => this.unitMoney(b.amount, b.unit)));
    return {
      sats: sats,
      units: units,
      text: parts.join(' + '),
      ink: (sats > 0 || units.length) ? 'var(--acc-ink)' : 'rgba(var(--ink-rgb),.35)',
    };
  }

  /* Balances at a mint in units other than sats: [{ mint, unit, amount }].
   * Never added to a sat figure. Empty without a wallet (the static preview). */
  otherUnitsAt(url) {
    const W = window.FoxyWallet;
    if (!W || typeof W.balances !== 'function') return [];
    const strip = u => String(u || '').replace(/\/+$/, '');
    return W.balances().filter(b => b.unit !== 'sat' && strip(b.mint) === strip(url));
  }

  /* An amount in its own unit: '$1.23', '€0.50', '5 msat'. */
  unitMoney(amount, unit) {
    const W = window.FoxyWallet;
    if (W && W.formatAmount) return W.formatAmount(amount, unit);
    return String(amount) + ' ' + unit;
  }

  /* 'USD', 'EUR', or the unit's code in capitals. */
  unitLabel(unit) {
    const W = window.FoxyWallet;
    return (W && W.unitName) ? W.unitName(unit) : String(unit || '').toUpperCase();
  }

  /* A scan row's other units with something in them: [{ unit, amount }]. */
  rowUnits(row) {
    const u = (row && row.units) || {};
    return Object.keys(u).sort().filter(k => u[k] && u[k].amount > 0).map(k => ({ unit: k, amount: u[k].amount }));
  }

  /* A scan row's findings in every unit: '1,200 sats + $1.23'. */
  rowAmounts(row) {
    return (row && row.sats > 0 ? [this.group(row.sats) + ' sats'] : [])
      .concat(this.rowUnits(row).map(b => this.unitMoney(b.amount, b.unit))).join(' + ');
  }

  /* Every balance in a unit other than sats, anywhere, as one line:
   * 'Also $1.23 in USD ecash at mint.example.com.' Empty when there is none. */
  otherUnitsLine() {
    const W = window.FoxyWallet;
    if (!W || typeof W.balances !== 'function') return '';
    const list = W.balances().filter(b => b.unit !== 'sat');
    if (!list.length) return '';
    return 'Also ' + list.map(b => this.unitMoney(b.amount, b.unit) + ' in ' + this.unitLabel(b.unit)
      + ' ecash at ' + String(b.mint).replace(/^https?:\/\//, '')).join(', ') + '.';
  }

  /* Is money moving right now?
   *
   * The proof lock alone missed stages that run outside it: a Lightning
   * address being looked up before there is an invoice to pay, a send still
   * running after its screen stopped waiting, an invoice being watched (the
   * watch polls and claims at whichever mint is connected), a token being
   * claimed and moved home, and the change collected after that. Switching
   * mints during any of them pointed the rest of the operation at the wrong
   * mint. */
  moneyBusy() {
    const W = window.FoxyWallet;
    return !!((W && W.proofLockDepth && W.proofLockDepth() > 0)
      || this._sendRun || this._watching || this._chasingChange
      || this.state.nmBusy || this.state.reqBusy);
  }

  /* Every mint switch a person starts asks here first. The wallet's own
   * connects — at launch, or a move's second leg — do not: they are part of
   * the operation in progress, not a second one. */
  /* Money actually in flight, as against a screen doing its job.
   *
   * `moneyBusy` is the right question for a person switching mints by hand: a
   * receive screen watching for a payment, or a request being made, are both
   * reasons to make them wait. It is the wrong question for work that IS the
   * payment — carrying a cross-mint payment home runs on the receive screen,
   * with that screen watching, so asking `moneyBusy` refused every single
   * attempt: "This phone is busy moving money", five times in four minutes,
   * for money it was itself trying to move.
   *
   * What genuinely conflicts is a swap or a melt already under way, because
   * those hold the proof lock and a mint switch under them loses track of
   * which mint the money is at. */
  moneyMoving() {
    const W = window.FoxyWallet;
    return !!((W && W.proofLockDepth && W.proofLockDepth() > 0)
      || this._sendRun || this._chasingChange);
  }

  /* Which of them it was, for the diary. `moneyBusy` is six questions and the
   * refusal named none of them, so "a payment is in progress" could not be
   * told apart from an invoice nobody was looking at. */
  busyWhy() {
    const W = window.FoxyWallet;
    const why = [];
    const held = W && W.proofLockHolder && W.proofLockHolder();
    if (held) why.push('the proof lock, held by ' + held.what + ' for ' + Math.round(held.ms / 1000) + 's');
    else if (W && W.proofLockDepth && W.proofLockDepth() > 0) why.push('the proof lock');
    if (this._sendRun) why.push('a send is running');
    if (this._watching) why.push('an invoice is being watched');
    if (this._chasingChange) why.push('change is being chased');
    if (this.state.nmBusy) why.push('a new mint is being set up');
    if (this.state.reqBusy) why.push('a request is being paid');
    return why.join('; ') || 'nothing';
  }

  refuseSwitchWhileBusy() {
    /* An invoice nobody has paid is let go, not waited for.
     *
     * A watched invoice used to count as a payment in progress, and it is
     * not one: nothing has moved, and there is nothing to finish. It stopped
     * a person switching mints until they found their way back to the
     * invoice and closed it. The watch ends here. The invoice stays on file
     * with its key, and if somebody pays it after all, it is collected the
     * next time this phone is on that mint (the sweep). What still waits is
     * money that is really moving: a swap, a payment, a token being claimed. */
    if (this._watching || this._stopWatch) {
      console.log('[foxy] mint switch: an unpaid invoice is let go; it stays on file and is collected if it is paid');
      this._invoiceRun = (this._invoiceRun || 0) + 1;
      this.stopReceive();
    }
    if (!this.moneyBusy()) return false;
    console.log('[foxy] mint switch refused: a payment is in progress (' + this.busyWhy()
      + '), on ' + this.state.screen);
    this.toast('Wait for the payment to finish before switching mints.', true);
    return true;
  }

  /* Claiming a token from another mint switches the wallet there, so it waits
   * like any other switch. A token from this mint switches nothing and goes
   * through; the wallet queues it behind the proof lock. */
  tokenSwitchRefused(text) {
    const W = window.FoxyWallet;
    const info = (W && W.tokenInfo) ? W.tokenInfo(text) : null;
    const strip = u => String(u || '').replace(/\/+$/, '');
    if (!info || !info.mint || strip(info.mint) === strip(W.mintUrl)) return false;
    return this.refuseSwitchWhileBusy();
  }

  /* Point the wallet at another mint. Nothing moves — each mint's proofs stay
   * filed under it, so switching back brings that balance into view again. */
  justSwitch(url) {
    const W = window.FoxyWallet;
    const host = String(url).replace(/^https?:\/\//, '');
    if (this.state.switchBusy) return;
    // a payment or claim in progress finishes at the mint it started on
    if (this.refuseSwitchWhileBusy()) return;
    // Connecting takes a second or two over Tor, and until now the row gave no
    // sign it had been tapped at all.
    this.setState({ switchBusy: true, mintBusy: String(url).replace(/\/+$/, '') });
    const back = this.state.mintReturn;
    // asked before connecting, which adds it to the list
    const usedBefore = !!(W.mintUsedBefore && W.mintUsedBefore(url));
    W.connect(url).then(w => {
      this.setState({ switchBusy: false, mintBusy: '', mintReturn: '' });
      this.walletReady({ name: (w && w.name) || host });
      // came from history, so go back to it — now showing this mint
      if (back === 'history') {
        this.setState({ screen: 'history', stack: ['home'] });
        this.loadHistory();
      }
      this.toast('Now on ' + host);
      if (!usedBefore) this.sweepNewMint(url, host);
    }).catch(e => {
      this.setState({ switchBusy: false, mintBusy: '' });
      this.toast(W.reason(e), true);
    });
  }

  /* Nothing filed under this mint — so ask it what it has signed for our seed
   * before concluding the balance is zero. Runs after the switch rather than
   * blocking it: a restore is seconds of round trips, and the screen should
   * not wait on it. Anything found is merged, never overwritten.
   *
   * Only for a mint this device has never used (justSwitch asks). A restore
   * sends every output this seed ever had signed there, so the mint learns this
   * wallet's whole history with it; on a mint Foxy has used, and emptied, that
   * was handed over on every switch back. The RESTORE screen still scans any
   * mint the person picks (MINT-PRIVACY.md C9). */
  sweepNewMint(url, host) {
    const W = window.FoxyWallet;
    if (!W || !W.scanSeed) return;
    if (this.mintPile(url).sats > 0) return;       // already know this one
    if (this._sweeping === url) return;
    this._sweeping = url;

    console.log('[foxy] nothing filed for', host, '\u2014 checking the seed');
    // this wallet's own seed is scanned with no words: they stay on the phone
    W.scanSeed(null, [url]).then(rows => {
      this._sweeping = null;
      const row = (rows || [])[0];
      if (!row || row.state !== 'done' || !(row.sats > 0 || this.rowUnits(row).length > 0)) return;
      // adoptScan waits its turn in the proof lock, so the balance is read and
      // the find announced only once the proofs are actually filed
      return Promise.resolve(W.adoptScan([row], { merge: true })).then((res) => {
        /* What was added, not what the scan saw. A scan also sees proofs a
         * payment or a sent token holds; those are not filed, and a toast of
         * the scan's total announced them as found (audit finding W1). */
        const sats = ((res && res.kept) || []).reduce((n, k) => n + (k.added || 0), 0);
        const units = {};
        ((res && res.units) || []).forEach(u => { if (u.added > 0) units[u.unit] = { amount: u.added }; });
        if (!(sats > 0 || Object.keys(units).length)) {
          console.log('[foxy] nothing new at', host, 'under this seed');
          return;
        }
        console.log('[foxy] found', sats, 'sats at', host, 'under this seed');
        if (W.mintHost() === host) this.refreshBalance();
        this.toast('Found ' + this.rowAmounts({ sats, units }) + ' at ' + host);
      });
    }).catch(e => {
      this._sweeping = null;
      console.warn('[foxy] seed check at', host, 'failed:', (e && e.message) || e);
    });
  }

  /* Is this the mint we are on? Compared without the scheme or a trailing
   * slash, since the same mint gets written both ways. */
  onMint(url) {
    const strip = u => String(u || '').replace(/^https?:\/\//, '').replace(/\/+$/, '');
    return !!this.mintHost() && strip(url) === strip(this.mintHost());
  }

  /* Any mint that is not on the list. The scan is the same native one the
   * connect screen uses. */
  scanOtherMint() {
    const W = window.FoxyWallet;
    W.scan('Scan the mint address')
      .then(url => {
        // the same validation the typed path gets, before anything acts on it
        const u = String(url || '').trim();
        const bad = W.mintProblem && W.mintProblem(u);
        if (bad) { this.toast(bad, true); return; }
        this.justSwitch(u);
      })
      .catch(e => this.toast(W.reason(e), true));
  }

  /* Tell them who holds the bitcoin, once per mint.
   *
   * Cashu is custodial: the mint holds the sats and the wallet holds claims
   * on them. Nothing in this app said so, and a balance on screen looks the
   * same either way. Shown before any money exists, and remembered — this is
   * a thing to understand once, not a warning to dismiss daily. */
  /* Is the wallet pointed at a mint that issues worthless ecash? */
  onTestMint() {
    const host = (this.mintHost() || '').toLowerCase();
    return host.indexOf('testnut.cashu.space') >= 0;
  }

  custodyNotice() {
    const W = window.FoxyWallet;
    if (this.onTestMint()) {
      this.blockedCard('testmint', {
        tone: 'warn',
        title: 'THIS IS A TEST MINT',
        reason: 'Ecash from this mint is backed by nothing and is worth nothing. '
          + 'It exists so the app can be tested without spending real money. '
          + 'Do not send anything here expecting to get it back.',
      });
      return;
    }
    const host = this.mintName() || 'this mint';
    let told = {};
    try { told = JSON.parse(localStorage.getItem('foxy.custody.told') || '{}'); } catch (e) {}
    if (told[host]) return;
    told[host] = true;
    try { localStorage.setItem('foxy.custody.told', JSON.stringify(told)); } catch (e) {}

    this.blockedCard('custody', {
      tone: 'warn',
      title: 'THE MINT HOLDS YOUR BITCOIN',
      reason: 'Ecash in this wallet is issued by ' + host + '. You are trusting '
        + 'that mint to back it with bitcoin until you move your money to '
        + 'another bitcoin lightning wallet. If it goes offline or refuses to '
        + 'pay out, there is no one to appeal to. Hold only what you can '
        + 'afford to lose.',
    });
  }

  /* No passcode on the phone. The rule is Face ID, else the passcode, and
   * with neither Foxy goes ahead on its alerts and warns.
   * Shown at launch until turned off: with no passcode, anyone holding the phone
   * can open the seed screen, replace the seed or delete it. */
  passcodeNotice() {
    const W = window.FoxyWallet;
    if (!W || !W.phoneHasPasscode || W.phoneHasPasscode() !== false) return;
    try { if (localStorage.getItem('foxy.nopasscode.off') === '1') return; } catch (e) {}
    this.blockedCard('nopasscode', {
      tone: 'warn',
      title: 'THIS IPHONE HAS NO PASSCODE',
      reason: 'Anyone who picks up this iPhone can open Foxy, see your twelve words, and replace or '
        + 'delete them. Face ID or a passcode is what normally asks first, and this phone has neither.',
      chip: 'Set one in Settings, under Face ID & Passcode.',
      also: { label: 'DON\u2019T SHOW AGAIN', tap: () => { try { localStorage.setItem('foxy.nopasscode.off', '1'); } catch (e) {} } },
    });
  }

  walletReady(w) {
    this.setState({
      walletLive: true,
      walletSearching: false,
      walletErr: '',
      screen: 'home',
      stack: [],
    });
    /* The heartbeat first, before anything that can throw.
     *
     * This pair is how an arrival nobody watched for reaches the screen at
     * all, and it used to be armed on the last line of this method — behind
     * eight calls out to the wallet and the notices, any one of which throwing
     * would take the balance and history with it for the rest of the session,
     * on a mint switch as much as on a launch. Nothing re-armed it either: the
     * same shape as the on-chain watcher that stopped asking. Armed here it
     * does not depend on the rest of this method finishing. */
    clearInterval(this._refreshT);
    this._refreshT = setInterval(() => { this.refreshBalance(); this.loadHistory(); }, 15000);
    // The mount-time fetch runs before Tor is up and is refused. Now that
    // the gate is through, ask for the price line.
    this.loadSeries(this.state.range);
    /* Lock keys, made now where nothing stands in front of the seed. They
     * come from the seed, and were only asked for when a request was made —
     * too late for that request, which went out unlocked, and a payer sends
     * unlocked ecash to a request that names no lock ("arrived 5 pieces, 0
     * locked"). Not where the seed
     * is behind Face ID: reading it is a prompt, and a launch does not ask. */
    const W = window.FoxyWallet;
    if (W && W.seedProtection && W.primeLocks && !this._locksPrimed) {
      this._locksPrimed = true;
      W.seedProtection().then((m) => {
        if (m && m.mode === 'none') return W.primeLocks();
        this._locksPrimed = false;
        return null;
      }).catch(() => { this._locksPrimed = false; });
    }
    // and, the first time on any mint, say who is holding the money
    setTimeout(() => this.custodyNotice(), 900);
    // and, where there is no passcode, that nothing but an alert guards the seed
    setTimeout(() => this.passcodeNotice(), 1000);
    // the concentration nudge waits past those, for a later refresh
    this._readyAt = Date.now();
    // A mint switch that paid but died before claiming leaves the money at the
    // new mint. This is where it gets picked up.
    if (window.FoxyWallet && window.FoxyWallet.finishMove) {
      window.FoxyWallet.finishMove().then(sats => { if (sats) this.refreshBalance(); });
    }
    /* A token made but never marked as handed over is money sitting in a
     * string: said once for each such token. The mint is not asked whether it
     * was claimed. That question, from this wallet at every launch, told the
     * mint which wallet had sent what the receiver redeemed; it is asked only
     * while the token's screen is open. */
    const out = window.FoxyWallet.lastToken && window.FoxyWallet.lastToken();
    if (out && out.token && !out.reminded) {
      setTimeout(() => {
        if (window.FoxyWallet.noteTokenReminded) window.FoxyWallet.noteTokenReminded();
        this.toast('An ecash token you made for ' + this.group(out.sats) +
          ' sats may not have been claimed yet');
      }, 1500);
    }
    // what this mint does on chain, and anything waiting on a block (26b-onchain.js)
    this.onchainAsk();
    this.onchainWatchLater();
    this.resumeSplit();
    // tokens made to pay someone, still waiting to be redeemed
    this.claimWatchResume();
    // and small change on hand for the next token
    this.tidyChangeLater();
    // the first balance, which a launch waits on before showing this screen
    const balance = this.refreshBalance();
    this.loadHistory();
    this.listenWallet();
    // NOT checking the clipboard on launch: reading it makes iOS put up its
    // "allow paste?" prompt every time the app opens. The paste button uses
    // UIPasteControl, which needs no prompt, so paste stays one tap away.
    return balance;
  }

  /* The sats first, and the price when it comes.
   *
   * These used to be awaited together, and the launch waits on this — so the
   * screen stayed up for as long as a price fetch took. On a phone Tor was
   * back in about two seconds and the wait ran to ten, with "price source
   * failed … timed out" filling the gap (seen in a device log). The
   * balance is local and instant; the price is a network call over Tor, and
   * the launch waits for both (see below).
   *
   * whatever LNbits says, verbatim — never arithmetic on the old figure */
  /* While part of the balance is held for a swap that got no answer, the mint
   * is asked every three seconds what became of it. One
   * timer, started wherever the balance is read; it stops by itself when
   * nothing is held, and does nothing with Foxy out of sight or with no
   * route — the wallet's own connect asks then. */
  watchHeld() {
    const W = window.FoxyWallet;
    if (!W || !W.heldSats || !W.recoverSwaps || this._heldT) return;
    if (!(W.heldSats() > 0)) return;
    const again = () => {
      this._heldT = null;
      if (!(W.heldSats() > 0)) return;
      const idle = (typeof document !== 'undefined' && document.hidden) || (this.offlineNow && this.offlineNow());
      const go = idle ? Promise.resolve() : W.recoverSwaps().then(() => {
        if (!(W.heldSats() > 0)) {
          console.log('[foxy] the sats held for a swap are settled; the balance has them again');
          this.refreshBalance();
          if (this.loadHistory) this.loadHistory();
        }
      }, () => {});
      go.then(() => { if (W.heldSats() > 0 && !this._heldT) this._heldT = setTimeout(again, 3000); });
    };
    this._heldT = setTimeout(again, 3000);
  }

  refreshBalance() {
    const W = window.FoxyWallet;
    if (!W || !W.connected) return Promise.resolve();
    /* Not while a late claim has the wallet at another mint (`awayClaiming`):
     * the balance read then is that mint's, and it went on the home screen
     * under this one's name. Read when the phone is home, once. */
    if (W.awayClaiming && W.awayClaiming()) {
      if (!this._balWhenHome) {
        this._balWhenHome = W.whenHome().then(() => { this._balWhenHome = null; return this.refreshBalance(); });
      }
      return this._balWhenHome;
    }
    if (this.watchHeld) this.watchHeld();
    // the figure that is actually the person's, which is local and instant
    /* With the change that is on its way back. An over-payment leaves the
     * wallet whole and its change returns seconds later, and for those seconds
     * the balance showed the payment as if it had cost all of it: a small
     * figure where thousands of sats were held. Counted while it is awaited,
     * and dropped if it never comes. */
    const owed = () => (this._changeDueAt && Date.now() < this._changeDueAt)
      ? Math.max(0, Math.round(Number(this._changeOwedSats) || 0)) : 0;
    const known = W.balanceSats().then(n => {
      const all = n + owed();
      this.setState({ balSats: all });
      return all;
    });
    /* Both halves, and the launch waits for both.
     *
     * For a time it waited only for the sats, because the price sources were
     * timing out for eight seconds after a circuit that had taken two and the
     * launch screen sat there for all of it. Waiting is the better choice: a
     * home screen that opens with no dollar figure and fills one in a moment
     * later is worse than a launch screen that is honest about still working.
     *
     * It cannot hang on it. The rate's own walk has a deadline — twelve seconds
     * direct, thirty through a bridge — and the catch below turns a refusal
     * into a value, so this settles whether or not a price was found. What the
     * launch waits for is the answer, not a number. */
    this._priced = Promise.all([known, W.rate().catch(e => e)]).then(([sats, rate]) => {
      // A made-up price is worse than none: it shows a dollar figure that is
      // simply wrong, and there is no way to tell from the screen. So there is
      // no fallback number anywhere — if the price cannot be fetched, the
      // dollar amounts go blank and a retry appears.
      const ok = typeof rate === 'number' && isFinite(rate) && rate > 0;
      if (!ok) {
        /* A price from the last three minutes still stands. A single failed
         * refresh put NO BITCOIN PRICE up, and the next one, a second or two
         * later, took it down again. A real price that
         * recent is not a made-up one. */
        const last = W._rate, age = Date.now() - (W._rateAt || 0);
        /* And offline, at any age.
         *
         * Three minutes is the window for a fetch that failed once and will
         * succeed in a moment. With no route there is no next fetch, so that
         * window put NO BITCOIN PRICE on an offline phone for the rest of the
         * session — and a blank where the price was tells somebody less than a
         * figure that says how old it is. Every screen that shows it shows its
         * age (`priceAgo`), and nothing converts a send at it. */
        if (last && (age < PRICE_STANDS_MS || this.offlineNow())) {
          this.setState({ balSats: sats, balUsd: (sats / 1e8) * last, satUsd: last / 1e8,
            livePrice: last, priceErr: false });
          return;
        }
        this.setState({ balSats: sats, priceErr: true });
        // with no recent price, one more try before saying so: at launch the
        // first request often goes out before Tor's circuits are ready
        this._priceMissAt = this._priceMissAt || Date.now();
        if (Date.now() - this._priceMissAt < PRICE_GRACE_MS) {
          clearTimeout(this._priceRetryT);
          this._priceRetryT = setTimeout(() => this.refreshBalance(), PRICE_GRACE_MS);
          return;
        }
        this.showPriceError();
        return;
      }
      this._priceMissAt = 0;
      clearTimeout(this._priceRetryT);
      this.setState({
        balSats: sats,
        balUsd: (sats / 1e8) * rate,
        satUsd: rate / 1e8,
        livePrice: rate,
        priceErr: false,
      });
      // a working price re-arms the card for the next real failure
      this._priceOff = false;
      this.hidePriceError();
      // a large balance at one mint, at most once in 30 days (11-mint-risk.js)
      this.spreadNudge();
    }).catch(() => {});
    return this._priced;
  }

  /* How long ago the price on screen was fetched, or '' while it is current.
   *
   * Read from the wallet's own stamp rather than from state, because that is the
   * one place it is really recorded (`_rateAt`), and nothing copies it. '' under
   * PRICE_STANDS_MS, which is the window refreshBalance already treats as a real
   * price rather than a stale one — saying "1M AGO" about a figure the app itself
   * considers current would be noise.
   *
   * Coarse on purpose: a person wants to know whether this is minutes or hours
   * old, and a number that ticks every second on a figure that is not moving
   * reads as though something is happening. */
  priceAgo() {
    const W = window.FoxyWallet;
    const at = (W && Number(W._rateAt)) || 0;
    if (!at || !this.state.livePrice) return '';
    const ms = Date.now() - at;
    if (ms < PRICE_STANDS_MS) return '';
    const mins = Math.floor(ms / 60000);
    if (mins < 60) return mins + 'M AGO';
    const hours = Math.floor(mins / 60);
    if (hours < 24) return hours + 'H AGO';
    return Math.floor(hours / 24) + 'D AGO';
  }

  /* The age as the home screen says it: "37 MINUTES AGO", and nothing while
   * the price is current. */
  priceAgeWords() {
    if (!this.priceAgo()) return '';
    const W = window.FoxyWallet;
    return this.agoWords(Date.now() - ((W && Number(W._rateAt)) || 0)).toUpperCase();
  }

  /* The same age, in the words a sentence needs: "2 hours ago".
   *
   * `priceAgo` is a label — "2H AGO", shouted, and empty while the price is
   * current — and a card that says "That is 2% more than the price this phone
   * last saw, " needs the rest of the sentence whatever the age is. Coarse in
   * the same way and for the same reason. */
  agoWords(ms) {
    const n = Number(ms) || 0;
    if (n < 90 * 1000) return 'a moment ago';
    const mins = Math.floor(n / 60000);
    if (mins < 60) return mins + ' minute' + (mins === 1 ? '' : 's') + ' ago';
    const hours = Math.floor(mins / 60);
    if (hours < 24) return hours + ' hour' + (hours === 1 ? '' : 's') + ' ago';
    const days = Math.floor(hours / 24);
    return days + ' day' + (days === 1 ? '' : 's') + ' ago';
  }

  /* No price means no dollars, so the keypad goes back to sats.
   *
   * `satUsd()` answers null until a price lands, and every conversion then gives
   * zero: `amountInSats` cannot turn a typed dollar figure into sats, and
   * `renderContext`'s cap becomes zero so every figure reads as more than the
   * balance. A keypad left in USD is therefore one that cannot send anything at
   * all — and offline that is permanent, which is exactly the state an offline
   * payer has to be able to spend from (the price sources all timed out for
   * minutes at a stretch).
   *
   * `toggleUnit` already refuses to go the other way without a price; this is the
   * half that was missing, for somebody already in dollars when the price went.
   * It does nothing at all while there is one. */
  /* Offline, asking to be paid is in dollars and only in dollars.
   *
   * This phone cannot convert honestly — its price may be hours old — so it
   * does not convert at all. It names a price in the money the price is named
   * in, and the phone with a current rate says what that makes in sats and
   * offers it back (`tapQuote`); nothing is paid until this phone agrees to
   * that number. Showing sats beside the dollars here would be showing a
   * conversion this phone is refusing to make.
   *
   * Only where the conversion is actually possible. With no price ever seen
   * there is nothing to type dollars against, and the keypad stays in sats —
   * `syncUnit` and `toggleUnit` both already hold that line. */
  dollarsOnly() {
    return !!(this.offlineNow() && this.state.flow === 'receive' && this.satUsd());
  }

  syncUnit() {
    if (this.dollarsOnly() && this.state.unit !== 'USD') {
      console.log('[foxy] offline and asking to be paid, so the keypad is in dollars');
      /* The figure is converted, not relabelled. Switching the unit under a
       * typed number turns 2,100 sats into $2,100 — the same digits standing
       * for eighty thousand times the money. `toggleUnit` converts for exactly
       * this reason and so does this; the price is the one this phone last saw,
       * which is the price the person is naming their amount in anyway. */
      const px = this.px();
      this.setState(p => {
        const v = parseFloat(p.amount) || 0;
        return { unit: 'USD', amount: (v && px) ? (v / 1e8 * px).toFixed(2) : '' };
      });
      return;
    }
    if (this.state.unit !== 'USD') return;
    /* Offline, a stale price may be shown but must not decide how much money
     * moves. The figure on the home screen carries its age and is there to be
     * read; a send converts at it silently, and a rate hours old converting a
     * typed dollar amount into sats is a real mis-send. Sats are exact and need
     * no rate at all. */
    /* Sending, yes. Asking to be paid, no.
     *
     * The two carry the risk in opposite directions. A send converts silently
     * and a rate hours old is a real mis-send, so a send stays in sats, which
     * are exact and need no rate. Asking for a dollar amount is the person
     * naming a price, they are the one who carries a stale one, and Foxy says
     * so under the figure (`priceWarn`) rather than taking the choice away. */
    if (this.offlineNow() && this.state.flow !== 'receive') {
      console.log('[foxy] offline, so the keypad is in sats');
      this.setState({ unit: 'SATS' });
      return;
    }
    if (this.satUsd()) return;
    console.log('[foxy] no price, so the keypad goes back to sats');
    this.setState({ unit: 'SATS' });
  }

  // dollars per bitcoin, and per sat. Null when there is no live price —
  // callers must handle that rather than fall back to a guess.
  /* Dollars per bitcoin. Their price where this phone has no route of its own.
   *
   * A phone working offline converts at whatever it last saw, which can be
   * hours old. In a tap with a phone that IS online, that phone's price is both
   * fresher and the one this payment is being agreed at — so it is the one to
   * convert with, and `peerRateLabel` is what says on screen whose it is. It never becomes this wallet's own price: `_rate` is
   * untouched, and a route coming back puts this phone's own figure in front
   * again. */
  peerRate() {
    if (!this.offlineNow()) return 0;
    const n = Number(this.state.peerRate) || 0;
    return n > 0 ? n : 0;
  }

  /* Whose price the figures on screen are in, when it is not this phone's. */
  peerRateLabel() {
    const n = this.peerRate();
    if (!n) return '';
    return 'At their bitcoin price, $ ' + this.group(Math.round(n));
  }

  px() {
    const theirs = this.peerRate();
    if (theirs) return theirs;
    const r = this.state.satUsd;
    if (r) return r * 1e8;
    return this.state.livePrice || null;
  }

  satUsd() {
    if (this.state.satUsd) return this.state.satUsd;
    return this.state.livePrice ? this.state.livePrice / 1e8 : null;
  }

  // Retry banner, built in plain DOM so it does not depend on the design
  // runtime re-rendering.
  /* A failure, over the screen it happened on.
   *
   * The BLOCKED entries were designed as full screens. As screens they render
   * black here, and they take the whole view for something that should not
   * cost you the amount you just typed. Same words, same tone, same retry
   * target — as a card.
   *
   * Plain DOM on document.body, so it does not depend on the design runtime,
   * and therefore outside the theme scope: every colour here is literal.
   */
  /* The lock, and the flow that sets it up.
   *
   * These are DOM overlays rather than template screens: the lock has to be
   * up before the app is usable, including before the gate, and an overlay
   * does not wait on a render. It is the same approach blockedCard uses.
   */
  /* ---- SECURE FOXY: what stands in front of the wallet ---------------------
   *
   * Shown once, when the first money has landed and its confirmation has been
   * dismissed (paidDismissed). Before that there is nothing to protect and the
   * ask is friction in front of somebody who has not started; after it, Face ID starts being asked on every return to the
   * foreground, and this is where that is explained rather than sprung.
   *
   * Three answers, and none of them is a trap:
   *
   *   FACE ID        the seed stays behind .userPresence, which is what every
   *                  Foxy did before there was a choice
   *   FOXY PIN       a code for Foxy itself — the only one of the three that
   *                  helps when somebody is holding the phone already unlocked
   *   NO PROTECTION  the seed moves to the older keychain item, which the
   *                  phone's own lock screen protects and nothing else
   *
   * The last one is a deliberate choice, and it really is none: it would be
   * worse to offer it and still ask for Face ID on every return. The card says
   * what it costs, it is never the default, and MENU > SECURITY changes it
   * later.
   */
  SECURE_ASKED = 'foxy.secure.asked';

  /* Due once: money has arrived, and this has never been shown. */
  secureCardDue() {
    const W = window.FoxyWallet;
    if (!W || !W.bridged || !W.bridged()) return false;
    try { if (localStorage.getItem(this.SECURE_ASKED)) return false; } catch (e) { return false; }
    // the figure the screen is showing, which is an object of both units
    return (this.balNow().sats || 0) > 0;
  }

  secureCardShown() {
    try { localStorage.setItem(this.SECURE_ASKED, String(Date.now())); } catch (e) {}
  }

  offerSecureFoxy() {
    if (!this.secureCardDue()) return;
    this.secureCardShown();
    const W = window.FoxyWallet;
    this.blockedCard('secureFoxy', {
      tone: 'ask',
      title: 'SECURE FOXY',
      reason: 'You have bitcoin in Foxy now. What should stand in front of it?',
      chip: 'Face ID also guards your twelve words. With no protection, nothing does.',
      retry: 'USE FACE ID',
      go: () => this.chooseProtection('device'),
      shut: { label: 'SET A FOXY PIN', tap: () => this.pinSetup(() => {}) },
      also: { label: 'NO PROTECTION', tap: () => this.confirmNoProtection() },
    });
  }

  /* Never on one tap: this is the one choice that takes a guard off. */
  /* Reached from the SECURE FOXY card and from MENU > STOP FACE ID, so it says
   * what it costs rather than what to pick. */
  confirmNoProtection() {
    this.blockedCard('noProtection', {
      tone: 'warn',
      title: 'NO PROTECTION?',
      reason: 'Anyone holding your phone unlocked will be able to spend what is in '
        + 'Foxy and read your twelve words.',
      chip: 'MENU \u203a USE FACE ID turns it back on.',
      retry: 'KEEP FACE ID',
      go: () => this.chooseProtection('device'),
      shut: { label: 'TURN IT OFF', tap: () => this.chooseProtection('none') },
    });
  }

  chooseProtection(mode) {
    const W = window.FoxyWallet;
    if (!W || !W.setSeedProtection) return;
    W.setSeedProtection(mode).then(() => {
      // what they answered, which openSeedForVisit reads on every wake
      if (W.secureChoice) W.secureChoice(mode);
      /* Says what it now does, which is more than it used to: this answer
       * locks the screen as well as the seed. */
      this.toast(mode === 'none' ? 'Foxy is not protected.' : 'Face ID now locks Foxy.');
      this.forceUpdate();
    }, e => {
      this.toast(W.reason ? W.reason(e) : 'That could not be changed.', true);
    });
  }

  /* Three things a card's PIN pad asks of this one (26f-flashcard.js), none
   * of which the lock uses:
   *   `o.warn`  a line already in red when the pad comes up: a wrong PIN, said
   *             on the pad that asks for it again;
   *   `o.back`  a back button at the top left, where every screen's is, in
   *             place of CANCEL at the bottom;
   *   `o.gate`  the button is grey and does nothing until four digits are in,
   *             because it says what the PIN will do ("PAY $0.43") and must
   *             not look ready before it is. */
  pinOverlay(opts) {
    const o = opts || {};
    if (this._pinEl) this._pinEl.remove();

    const el = (style, text) => {
      const d = document.createElement('div');
      d.style.cssText = style;
      if (text != null) d.textContent = text;
      return d;
    };

    // Above everything the page draws: the seed screens (2147483550), the
    // delete prompts (2147483600) and the Tor gate (2147483602) included.
    const root = el('position:fixed;inset:0;z-index:2147483647;background:var(--bg,#050505);'
      + 'display:flex;flex-direction:column;align-items:center;justify-content:flex-start;'
      // under the back button's row, where there is one
      + 'padding:' + (o.back ? '118px' : '76px') + ' 26px 26px;box-sizing:border-box;'
      /* No fade for the lock. It is a cover, drawn under the phone's own
       * cover before that comes off, and its fade-in showed the home screen
       * through it for a moment: the connection screen used to sit underneath
       * and hide that, and opens on the home screen now. */
      + 'font-family:SatSymbol,Sora,system-ui,sans-serif'
      + (o.cover ? '' : ';animation:foxyIn .16s ease'));

    const title = el('font-size:26px;font-weight:800;letter-spacing:-0.02em;'
      + 'color:var(--ink,#F5F1EC);text-align:center', o.title || '');
    const sub = el('margin-top:10px;font-size:17px;font-weight:500;line-height:1.4;'
      + 'color:rgba(245,241,236,.6);text-align:center;text-wrap:pretty', o.subtitle || '');
    root.appendChild(title);
    root.appendChild(sub);

    // the dots
    const dots = el('display:flex;gap:14px;margin-top:38px;height:18px;align-items:center');
    root.appendChild(dots);

    const note = el('margin-top:18px;min-height:22px;font-size:16px;font-weight:700;'
      + 'color:#FF5C5C;text-align:center', o.warn || '');
    root.appendChild(note);

    let entry = '';
    const MAXLEN = 8;

    const paint = () => {
      dots.textContent = '';
      const n = Math.max(entry.length, 4);
      for (let i = 0; i < n; i++) {
        const filled = i < entry.length;
        dots.appendChild(el('width:14px;height:14px;border-radius:50%;'
          + (filled ? 'background:var(--acc,#F2802E)'
                    : 'background:transparent;border:2px solid rgba(245,241,236,.28)')));
      }
    };
    if (!o.noKeypad) paint();
    /* Whether the button may be pressed (`o.gate`), drawn with every key. Set
     * once the button exists, further down. */
    let ready = () => {};

    // the keypad
    /* The whole cell takes the touch, not only the round key drawn in it.
     *
     * The keys were 66 high with 14 between them, and the 14 was dead: a thumb
     * landing between two keys pressed neither. And they waited for a click,
     * which iOS gives only for a touch that barely moves and ends alone, so a
     * quick second key, or a thumb that slid a little, was a tap that did
     * nothing. Now the cells meet edge to edge, a key takes the touch the
     * moment it lands, and it turns orange while it is down so there is no
     * doubt it was felt. */
    const pad = el('margin-top:auto;display:grid;grid-template-columns:repeat(3,1fr);'
      + 'width:100%;max-width:336px;touch-action:manipulation;'
      + '-webkit-user-select:none;user-select:none;-webkit-touch-callout:none');
    const key = (label, onTap, quiet) => {
      const k = el('height:80px;display:flex;align-items:center;justify-content:center;'
        + 'cursor:pointer;-webkit-tap-highlight-color:transparent');
      const rest = quiet ? 'transparent' : 'rgba(245,241,236,.08)';
      const ink = quiet ? 'rgba(245,241,236,.55)' : 'var(--ink,#F5F1EC)';
      const face = el('flex:1;margin:0 7px;height:66px;border-radius:33px;display:flex;align-items:center;'
        + 'justify-content:center;font-size:26px;font-weight:700;pointer-events:none;'
        + 'transition:background .1s ease;color:' + ink + ';background:' + rest, label);
      k.appendChild(face);
      // the empty corner is not a key
      if (!label) return k;
      let litAt = 0, dim = null, touched = false;
      const lit = () => {
        clearTimeout(dim);
        litAt = Date.now();
        face.style.background = 'var(--acc,#F2802E)';
        face.style.color = '#fff';
      };
      // long enough to be seen, however quick the tap
      const unlit = () => {
        clearTimeout(dim);
        dim = setTimeout(() => { face.style.background = rest; face.style.color = ink; },
                         Math.max(0, 140 - (Date.now() - litAt)));
      };
      k.addEventListener('pointerdown', () => { touched = true; lit(); onTap(); });
      ['pointerup', 'pointercancel', 'pointerleave'].forEach((kind) => k.addEventListener(kind, unlit));
      // a click with no touch before it (a pointer-less browser, a test): the same key press
      k.addEventListener('click', () => {
        if (touched) { touched = false; return; }
        lit(); onTap(); unlit();
      });
      return k;
    };
    for (let d = 1; d <= 9; d++) {
      pad.appendChild(key(String(d), () => {
        if (entry.length >= MAXLEN) return;
        entry += String(d);
        note.textContent = '';
        paint(); ready();
        this.haptic && this.haptic('light');
      }));
    }
    pad.appendChild(key('', () => {}, true));
    pad.appendChild(key('0', () => {
      if (entry.length >= MAXLEN) return;
      entry += '0';
      note.textContent = '';
      paint();
      this.haptic && this.haptic('light');
    }));
    pad.appendChild(key('\u232B', () => {
      entry = entry.slice(0, -1);
      note.textContent = '';
      paint(); ready();
    }, true));
    /* No keypad when a face is the only way in: there is no PIN to type, and
     * a dead keypad on a lock screen reads as a wallet that will not open. */
    if (!o.noKeypad) root.appendChild(pad);

    const cta = el((o.noKeypad ? 'margin-top:auto;' : 'margin-top:16px;')
      + 'width:100%;max-width:300px;height:60px;border-radius:30px;'
      + 'background:var(--acc,#F2802E);color:#fff;display:flex;align-items:center;'
      + 'justify-content:center;font-size:19px;font-weight:800;letter-spacing:0.02em;'
      + 'cursor:pointer', o.cta || 'CONTINUE');
    if (o.gate) {
      cta.setAttribute('data-pin-cta', '1');
      /* The SET AMOUNT screen's NEXT, to the pixel: the same width, height,
       * type and fur when it can be pressed, and the same grey when it
       * cannot (build/markup.html, `next`). */
      cta.style.cssText = 'margin-top:16px;align-self:stretch;margin-left:2px;margin-right:2px;height:60px;'
        + 'border-radius:30px;display:flex;align-items:center;justify-content:center;'
        + 'font-family:SatSymbol,Sora,sans-serif;font-size:22px;font-weight:800;letter-spacing:0.02em;'
        + 'background-repeat:no-repeat,no-repeat,no-repeat;background-size:auto,auto,150% auto;'
        + 'background-position:center,center,50% 34%;white-space:nowrap';
      const FUR = 'radial-gradient(120% 84% at 26% 0%,rgba(255,240,220,.26),rgba(255,240,220,0) 62%),'
        + 'linear-gradient(168deg,rgba(247,154,60,.62),rgba(232,98,42,.72) 48%,rgba(194,74,27,.78)),'
        + "url('foxy-fur.webp')";
      ready = () => {
        const on = entry.length >= 4;
        cta.style.backgroundColor = on ? 'var(--acc,#E8622A)' : 'rgba(245,241,236,.14)';
        cta.style.backgroundImage = on ? FUR : 'none';
        cta.style.boxShadow = on
          ? 'inset 0 2px 0 rgba(255,255,255,.4),inset 0 -4px 0 rgba(0,0,0,.16),0 12px 24px rgba(232,98,42,.34)' : 'none';
        cta.style.color = on ? '#fff' : 'rgba(245,241,236,.4)';
        cta.style.cursor = on ? 'pointer' : 'default';
        cta.setAttribute('data-pin-ready', on ? '1' : '0');
      };
      ready();
    }
    cta.addEventListener('click', () => {
      // with no keypad the button IS the face: it asks again
      if (o.noKeypad) { if (o.face) o.face(); return; }
      if (entry.length < 4) {
        // a gated button says nothing: it is grey, and that is the saying
        if (!o.gate) note.textContent = 'At least four digits.';
        return;
      }
      const value = entry;
      entry = '';
      paint(); ready();
      o.onSubmit(value, (message) => { note.textContent = message; });
    });
    root.appendChild(cta);

    if (o.face) {
      const W = window.FoxyWallet;
      const face = el('margin-top:10px;width:100%;max-width:300px;height:52px;'
        + 'border-radius:26px;border:1.5px solid rgba(245,241,236,.2);'
        + 'display:flex;align-items:center;justify-content:center;font-size:17px;'
        + 'font-weight:800;letter-spacing:0.02em;color:var(--ink,#F5F1EC);'
        + 'cursor:pointer;display:none', 'USE FACE ID');
      face.addEventListener('click', o.face);
      root.appendChild(face);
      /* Shown only where the menu's USE FACE ID is on and there is a PIN to
       * type beside it — and never beside a CTA that is already the same
       * button (noKeypad, the face-alone lock, where the face IS the way in). */
      if (W && W.biometric && !o.noKeypad
          && W.faceLock && W.faceLock()) {
        face.style.display = 'flex';
      }
    }

    if (o.onCancel) {
      const back = el('margin-top:8px;height:46px;display:flex;align-items:center;'
        + 'justify-content:center;font-size:17px;font-weight:700;'
        + 'color:rgba(245,241,236,.5);cursor:pointer', 'CANCEL');
      back.addEventListener('click', () => { root.remove(); this._pinEl = null; o.onCancel(); });
      root.appendChild(back);
    }

    /* Back, at the top left, as on every screen: the same round button, in
     * the same place. Added last so the pad's own parts keep their order. */
    if (o.back) {
      const b = el('position:absolute;left:22px;top:56px;width:52px;height:52px;border-radius:50%;'
        + 'background:linear-gradient(180deg,var(--lift,#2A2B2E),var(--sink,#151618)),var(--chip,#1C1D20);'
        + 'border-top:1px solid var(--lift-edge,rgba(255,255,255,.14));'
        + 'box-shadow:inset 0 2px 0 var(--lift-edge,rgba(255,255,255,.14)),inset 0 -3px 0 var(--sink-edge,rgba(0,0,0,.5)),0 8px 16px rgba(0,0,0,.34);'
        + 'box-sizing:border-box;display:flex;align-items:center;justify-content:center;cursor:pointer');
      b.innerHTML = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="var(--ink,#F5F1EC)" '
        + 'stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M19.5 12H5m0 0 6-6m-6 6 6 6"></path></svg>';
      b.setAttribute('data-pin-back', '1');
      b.setAttribute('role', 'button');
      b.setAttribute('aria-label', 'Back');
      b.addEventListener('click', () => { root.remove(); this._pinEl = null; o.back(); });
      root.appendChild(b);
    }

    document.body.appendChild(root);
    this._pinEl = root;
    return root;
  }

  pinDismiss() {
    if (this._pinEl) { this._pinEl.remove(); this._pinEl = null; }
  }

  /* Setup: enter, repeat, then read what forgetting it costs. */
  pinSetup(onDone) {
    const W = window.FoxyWallet;
    this.pinOverlay({
      title: 'CHOOSE A PIN',
      // true to the menu's switch: with USE FACE ID on, a face opens Foxy first
      subtitle: W && W.faceLock && W.faceLock()
        ? 'Four digits or more. It opens Foxy when Face ID does not.'
        : 'Four digits or more. You will enter this every time you open Foxy.',
      cta: 'NEXT',
      onCancel: () => { if (onDone) onDone(false); },
      onSubmit: (first) => {
        this.pinOverlay({
          title: 'ENTER IT AGAIN',
          subtitle: 'So a mistyped digit does not become your PIN.',
          cta: 'NEXT',
          onCancel: () => { if (onDone) onDone(false); },
          onSubmit: (second, warn) => {
            if (second !== first) {
              warn('Those did not match. Start again.');
              setTimeout(() => this.pinSetup(onDone), 700);
              return;
            }
            this.pinConfirmWarning(first, onDone);
          },
        });
      },
    });
  }

  /* The honest screen.
   *
   * A PIN that gates this app does not destroy the seed, so "you can never
   * get back in" would be false — and a user who believed it might do
   * something worse than reinstall. What is true is the route back, and what
   * it depends on. */
  pinConfirmWarning(pin, onDone) {
    const W = window.FoxyWallet;
    this.pinDismiss();
    this.blockedCard('pinWarn', {
      tone: 'warn',
      title: 'IF YOU FORGET THIS PIN',
      reason: 'There is no way to reset it and no one to ask. You would have to '
        + 'delete Foxy, reinstall it, and restore from your twelve words. '
        + 'If those words are not written down somewhere safe, the money is '
        + 'gone. Write them down before you set a PIN.',
      retry: 'SET THE PIN',
      /* CLOSE on this card abandons setup, and said nothing about it — the
       * likeliest reason a PIN "was set" and then never appeared. It says so
       * now, because a lock the user believes is on and is not is worse than
       * no lock at all. */
      onClose: () => { if (!W.pinIsSet()) this.toast('No PIN was set.', true); },
      go: () => {
        try {
          W.pinSet(pin);
          this.toast('PIN set');
          /* Nothing is asked about a face here. It was, once, and the answer
           * was kept where no switch showed it: a face then opened Foxy with
           * the PIN screen never appearing, under a menu that said Face ID
           * was off. MENU > USE FACE ID is the one place a face is turned on
           * or off (faceLock, 22-screen-lock.js). */
          if (onDone) onDone(true);
        } catch (e) {
          this.toast(W.reason(e), true);
          if (onDone) onDone(false);
        }
      },
    });
  }

  /* One PIN attempt, through the wallet's stored count of wrong ones.
   *
   * Used by the app lock and by leaving POS mode. The count outlives the app,
   * and while a wait runs the PIN is not checked at all — typing quickly, or
   * closing Foxy and opening it again, does not get more guesses. */
  pinTry(pin) {
    const W = window.FoxyWallet;
    const r = W.pinAttempt ? W.pinAttempt(pin) : { ok: W.pinCheck(pin), waitMs: 0 };
    if (r.ok) return { ok: true };
    const secs = Math.ceil((r.waitMs || 0) / 1000);
    const span = secs >= 120 ? Math.ceil(secs / 60) + ' minutes'
      : secs + (secs === 1 ? ' second' : ' seconds');
    if (r.locked) return { ok: false, message: 'Too many wrong PINs. Try again in ' + span + '.' };
    return { ok: false, message: secs > 0 ? 'Wrong PIN. Try again in ' + span + '.' : 'Wrong PIN.' };
  }

  /* Resolves once the lock is dismissed; at once when there is no lock up. */
  pinUnlocked() {
    return this._pinLocked && this._unlockWait ? this._unlockWait : Promise.resolve();
  }

  /* The lock itself, at launch and on resume.
   *
   * A PIN, or a face, or both — `screenLocked()`. It used to be a PIN alone:
   * `pinIsSet()` and nothing else, so somebody who had turned Face ID on and
   * set no PIN had no lock at all — kill Foxy, open it, and the balance, the
   * history and the mint were on screen with nothing asked. The menu's Face
   * ID row sets `secureChoice`, which guards the
   * SEED, so a face was asked when money was spent and never for looking.
   *
   * One setting decides whether a face is offered, the menu's USE FACE ID
   * (`faceLock()`, 22-screen-lock.js), and whether a PIN is set decides what
   * the face is:
   *
   *   no PIN     the face is the lock, and the phone's own passcode may
   *              stand in for it
   *   a PIN      the face is the quick way in and the PIN is the way in when
   *              it will not scan; with USE FACE ID off, only the PIN opens */
  pinLock() {
    const W = window.FoxyWallet;
    if (!W || !W.screenLocked || !W.screenLocked()) return;
    const byFaceAlone = !W.pinIsSet();
    /* Nothing the lock guards stays open, above it or under it.
     *
     * The seed and verify screens and the delete prompts sat above the lock
     * and were not closed: a phone handed over after a trip to the background
     * showed TAP TO REVEAL, the words to verify, or DELETE over FOXY IS
     * LOCKED, and no PIN was asked. They close now, and opening them again
     * goes through the unlocked app. The words themselves are on the phone's
     * screens, which close as Foxy goes to the background; the BACKUP sheet
     * around them, with its DELETE, is marked like the prompts. */
    document.querySelectorAll('[data-foxy-close-on-lock]')
      .forEach(n => n.remove());
    if (this._pinLocked) return;
    this._pinLocked = true;
    this._lockedOnce = true;
    // said, so a diary shows the lock: it drew and asked in silence, and a report about it had nothing to go on
    console.log('[foxy] lock: up, ' + (byFaceAlone ? 'a face is the way in' : 'the PIN pad') + (W.faceLock && W.faceLock() ? ', a face is asked' : ''));
    this._unlockWait = new Promise(resolve => { this._unlockDone = resolve; });
    const unlocked = () => {
      this._pinLocked = false;
      this.pinDismiss();
      if (this._unlockDone) { this._unlockDone(); this._unlockDone = null; }
    };

    /* Face ID first, when it is there and wanted.
     *
     * The keypad is built either way, so a refusal or a cancel lands on
     * something usable rather than on nothing.
     *
     * With a face and no PIN there is nothing behind it, so the phone's own
     * passcode is allowed to stand in: a face that will not scan must not mean
     * the money cannot be reached. It gives nothing away — anybody who can
     * unlock the phone can open Foxy anyway. With a PIN set, that PIN is the
     * way in and Face ID stays biometrics-only. */
    const tryFace = (auto) => {
      // the menu's switch, whether or not a PIN stands behind the face
      const wanted = W.faceLock && W.faceLock();
      if (!W.biometric || !wanted) return;
      W.biometric('Unlock Foxy', byFaceAlone).then(answer => {
        if (answer === 'unavailable' && byFaceAlone) {
          /* A face was the only lock and this phone cannot check one — Face ID
           * turned off in Settings, or no passcode at all. Refusing to open
           * would strand the money behind a door with no key, so Foxy says so
           * and lets them in, which is no worse than the phone itself. */
          console.warn('[foxy] lock: this phone cannot check a face or a passcode; opening');
          unlocked();
          return;
        }
        if (answer !== 'yes') return;
        if (W.pinTriesClear) W.pinTriesClear();
        unlocked();
      }).catch(() => {});
    };

    const ask = (message) => {
      this.pinOverlay({
        title: 'FOXY IS LOCKED',
        // no keypad to point at when a face is the only way in
        subtitle: message || (byFaceAlone ? 'Look at your phone to unlock.' : 'Enter your PIN.'),
        cta: byFaceAlone ? 'UNLOCK WITH FACE ID' : 'UNLOCK',
        noKeypad: byFaceAlone,
        cover: true,
        face: () => tryFace(false),
        onSubmit: (pin, warn) => {
          /* Slow down guessing on a phone in someone's hand. This does
           * nothing against reading the stored hash offline — that is in the
           * threat model, not hidden behind a delay. */
          const r = this.pinTry(pin);
          if (r.ok) {
            unlocked();
            return;
          }
          warn(r.message);
        },
      });
    };
    ask();
    tryFace(true);
    /* And the phone is told the page has the screen: the lock is drawn, opaque
     * and without a fade, so the launch image over it, or the cover put up as
     * Foxy went away, can come off now. Said from here, whoever raised the lock.
     * At launch it is raised from the wallet's boot, a moment after the page
     * mounted, and nothing there said it: the splash sat over the PIN pad for
     * the phone's eight seconds. */
    if (window.FoxyGate && window.FoxyGate.uncover) window.FoxyGate.uncover();
  }

  blockedCard(kind, over) {
    const spec = Object.assign({}, this.BLOCKED_INFO(kind) || {}, over || {});
    if (!spec.title) return;

    /* One card at a time, and none lost.
     *
     * A new card used to replace whatever card was open. On a simulator tour
     * "PAID, NOT COLLECTED YET" appeared and, four seconds later, the test-mint
     * card took its place — the stuck invoice was never seen. A card arriving
     * while another is open now waits, and shows when that one closes. The same
     * kind arriving again replaces the one waiting, so repeats do not pile up;
     * the same kind as the open card replaces it, as before. */
    if (this._blockedEl) {
      if (this._blockedKind !== kind) {
        this._cardQueue = (this._cardQueue || []).filter(c => c.kind !== kind);
        this._cardQueue.push({ kind, over });
        return;
      }
      this._blockedEl.remove();
    }
    this._blockedKind = kind;

    /* Three tones. Red is something that failed, amber something to be
     * careful of — and `ask` is neither: a card that offers a choice rather
     * than reporting trouble (SECURE FOXY). It borrows the iceberg blue the
     * home screen's Tor banner uses, so it reads as calm rather than as one
     * more thing that has gone wrong. */
    const warn = spec.tone === 'warn';
    const ask = spec.tone === 'ask';
    const accent = ask ? '#BFE3EC' : warn ? '#F7931A' : '#FF5C5C';
    const glowRgb = ask ? '191,227,236' : warn ? '247,147,26' : '255,92,92';

    const el = (style, html) => {
      const d = document.createElement('div');
      d.style.cssText = style;
      if (html) d.innerHTML = html;
      return d;
    };

    const root = el('position:fixed;inset:0;z-index:2147483400;background:rgba(0,0,0,.7);' +
      'display:flex;flex-direction:column;justify-content:flex-end;' +
      'font-family:SatSymbol,Sora,system-ui,sans-serif;animation:foxyIn .16s ease');

    const stage = el('position:relative;isolation:isolate');
    stage.appendChild(el('position:absolute;left:0;right:0;top:-290px;height:330px;' +
      'pointer-events:none;z-index:0;background:radial-gradient(ellipse 128% 100% at 50% 100%,' +
      'rgba(' + glowRgb + ',' + (ask ? '.30' : warn ? '.42' : '.38') + ') 0%,' +
      'rgba(' + glowRgb + ',' + (ask ? '.14' : warn ? '.20' : '.18') + ') 42%,rgba(0,0,0,0) 78%)'));

    const card = el('position:relative;z-index:1;background:#141518;' +
      'border-radius:28px 28px 0 0;padding:28px 26px calc(31px + env(safe-area-inset-bottom));' +
      'display:flex;flex-direction:column;align-items:center;' +
      'border-top:1px solid ' + accent + ';box-shadow:inset 0 2px 0 ' + accent);

    /* A shield for a card that is asking, not reporting: the × and the ! both
     * say something is wrong, and nothing is. */
    const shield = '<svg width="34" height="34" viewBox="0 0 24 24" fill="none" aria-hidden="true">'
      + '<path d="M12 2.6 4.8 5.5v6c0 4.4 3 8.5 7.2 9.9 4.2-1.4 7.2-5.5 7.2-9.9v-6L12 2.6Z" '
      + 'stroke="' + accent + '" stroke-width="1.8" stroke-linejoin="round"/>'
      + '<path d="m8.8 11.9 2.3 2.3 4.1-4.5" stroke="' + accent + '" stroke-width="1.8" '
      + 'stroke-linecap="round" stroke-linejoin="round"/></svg>';
    card.appendChild(el('width:64px;height:64px;border-radius:50%;' +
      'background:rgba(' + glowRgb + ',' + (ask ? '.13' : warn ? '.16' : '.14') + ');' +
      'display:flex;align-items:center;justify-content:center;font-size:34px;' +
      'font-weight:800;line-height:1;color:' + accent, ask ? shield : warn ? '!' : '\u00d7'));

    const title = el('font-size:22px;font-weight:800;letter-spacing:-0.022em;' +
      'color:#F5F1EC;text-align:center;margin-top:16px');
    title.textContent = spec.title;
    card.appendChild(title);

    // pre-line: a card can put its sentences on lines of their own (`tapOfflineCross`)
    const reason = el('font-size:18px;font-weight:500;line-height:1.4;white-space:pre-line;' +
      'color:rgba(245,241,236,.62);text-align:center;margin-top:7px;max-width:310px');
    reason.textContent = spec.reason || '';
    card.appendChild(reason);

    if (spec.chip) {
      const chip = el('margin-top:14px;padding:10px 16px;border-radius:16px;' +
        'background:rgba(' + glowRgb + ',' + (ask ? '.12' : warn ? '.14' : '.12') + ');' +
        'font-size:16px;font-weight:700;color:' + accent + ';text-align:center;' +
        'white-space:pre-line;line-height:1.45');
      chip.textContent = spec.chip;
      card.appendChild(chip);
    }

    const stack = el('align-self:stretch;display:flex;flex-direction:column;gap:12px;margin-top:22px');

    const close = () => {
      root.remove();
      if (this._blockedEl === root) { this._blockedEl = null; this._blockedKind = null; }
      // the scan screen's camera, held back while the card was up, comes back
      if (this.syncPreview) setTimeout(() => this.syncPreview(), 0);
      if (spec.onClose) spec.onClose();
      // the next card that was waiting, once this one (and anything its close opened) is done
      setTimeout(() => {
        if (this._blockedEl || !(this._cardQueue || []).length) return;
        const next = this._cardQueue.shift();
        this.blockedCard(next.kind, next.over);
      }, 250);
    };

    // a card can navigate somewhere or run something; some failures are worth
    // retrying in place rather than going back a screen to do it
    if (spec.retry && (spec.back || spec.go)) {
      const go = el('height:60px;border-radius:30px;background:#F2802E;color:#fff;' +
        'display:flex;align-items:center;justify-content:center;font-size:20px;' +
        'font-weight:800;letter-spacing:0.02em;cursor:pointer');
      go.textContent = spec.retry;
      go.addEventListener('click', () => {
        close();
        if (spec.go) spec.go();
        else this.setState({ screen: spec.back });
      });
      stack.appendChild(go);
    }

    /* With nothing to retry, CLOSE is the only thing to do — so it takes the
     * primary treatment rather than sitting there as a grey afterthought. */
    const alone = !(spec.retry && (spec.back || spec.go));
    const shut = alone
      ? el('height:60px;border-radius:30px;background:#F2802E;color:#fff;' +
           'display:flex;align-items:center;justify-content:center;font-size:20px;' +
           'font-weight:800;letter-spacing:0.02em;cursor:pointer')
      : el('height:52px;display:flex;align-items:center;justify-content:center;' +
           'font-size:18px;font-weight:800;color:rgba(245,241,236,.55);cursor:pointer');
    /* A card can name its second choice and give it something to do
     * (PAYING ANOTHER … USER's CONTINUE OVER LIGHTNING). Tapping outside the
     * card still only closes it. */
    shut.textContent = (spec.shut && spec.shut.label) || 'CLOSE';
    shut.addEventListener('click', () => {
      close();
      if (spec.shut && spec.shut.tap) spec.shut.tap();
    });
    stack.appendChild(shut);

    /* A quieter third choice, for a card that can be turned off for good
     * (A LOT AT ONE MINT's "don't show this again"). */
    if (spec.also && spec.also.label) {
      const also = el('height:44px;display:flex;align-items:center;justify-content:center;' +
        'font-size:16px;font-weight:700;color:rgba(245,241,236,.4);cursor:pointer');
      also.textContent = spec.also.label;
      also.addEventListener('click', () => { close(); if (spec.also.tap) spec.also.tap(); });
      stack.appendChild(also);
    }

    card.appendChild(stack);
    stage.appendChild(card);
    root.appendChild(stage);
    root.addEventListener('click', (e) => { if (e.target === root) close(); });
    document.body.appendChild(root);
    this._blockedEl = root;
    /* So a card that is waiting on something other than a person can be taken
     * down when that thing arrives (the payer's PRICE SENT, below). Every other
     * card is closed by a button, which is what `close` is for. */
    this._blockedClose = close;
    // a native camera preview would sit over the card
    if (this.syncPreview) this.syncPreview();
    console.log('[foxy] blocked:', kind, '\u2014', spec.reason || '');
  }

  /* Why a claim failed, and whether trying again could ever work.
   *
   * The mint's own wording is the signal. Already spent and P2PK-locked are
   * final: the token is not yours to claim and no number of attempts changes
   * that. Everything else is the mint not answering, where the token is still
   * good and retrying is the right move — so that is the only case that gets
   * a retry button.
   */
  /* A mint's signatures failed their check (NUT-12 DLEQ).
   *
   * The ecash it sent cannot be shown to be real, so it was not kept, and
   * nothing here offers to try again: the same mint would send the same thing,
   * and every attempt spends another request's worth of counters. */
  badSignatureCard(host, where, onClose) {
    const W = window.FoxyWallet;
    const name = host || (W && W.mintHost ? W.mintHost() : '') || 'This mint';
    const what = where === 'claim'
      ? 'The invoice was paid, but Foxy will not collect ecash it cannot verify, and will not ask this mint for it again.'
      : where === 'pay'
        ? 'The payment went through; the change it sent back could not be verified and was not kept.'
        : 'Nothing it sent back was kept.';
    this.blockedCard('mintTrouble', {
      tone: 'warn',
      title: 'THIS MINT SENT INVALID SIGNATURES',
      reason: name + ' sent signatures that do not match the keys it publishes. ' + what,
      chip: 'A mint doing this is broken or marking this wallet. Consider moving your balance to another mint.',
      retry: '', back: '',
      onClose: onClose || null,
    });
  }

  isBadSignatures(e) {
    return /dleq verification failed|dleq proof invalid|signatures do not match the keys|sent invalid signatures/i
      .test(String((e && (e.message || e.detail)) || e || ''));
  }

  /* Paid, not collected yet.
   *
   * The invoice was paid and the mint holds the ecash, but the claim keeps
   * failing — which used to be a line in a log, while the balance quietly did
   * not move. Once a session for each invoice, so a retry every few seconds
   * does not become a card every few seconds. */
  showStuckInvoice(hit) {
    if (!hit || !hit.quote || !hit.unclaimed) return;
    this._stuckShown = this._stuckShown || {};
    if (this._stuckShown[hit.quote]) return;
    this._stuckShown[hit.quote] = true;
    const u = hit.unclaimed;
    const host = String(hit.mint || '').replace(/^https?:\/\//, '') || 'the mint';
    const sats = this.group(Number(hit.amount) || 0);
    if (u.badSignatures) {
      this.blockedCard('stuckInvoice', {
        tone: 'warn',
        title: 'PAID, NOT COLLECTED',
        reason: sats + ' sats at ' + host + '. The mint sent invalid signatures for it, so Foxy will not collect it or ask again.',
        chip: 'Consider moving your balance to another mint.',
      });
      return;
    }
    /* Refused three times: Foxy stops asking on its own, since each try uses
     * counters the mint never signs and a long run of them hides later ecash
     * from a restore (audit finding W2). One more try is the person's. */
    if (u.refused >= 3) {
      this.blockedCard('stuckInvoice', {
        tone: 'warn',
        title: 'PAID, NOT COLLECTED',
        reason: sats + ' sats at ' + host + '. The mint refused to hand them over three times'
          + (u.reason ? ' (' + u.reason + ')' : '') + ', so Foxy stopped asking on its own.',
        chip: 'The money is still at the mint. Try again later, or ask the mint what is wrong.',
        retry: 'TRY AGAIN',
        go: () => {
          window.FoxyWallet.retryRefusedClaim(hit.quote).then(() => {
            this.toast('Collected ' + sats + ' sats');
            this.refreshBalance();
          }, e => this.claimFailed(e));
        },
      });
      return;
    }
    /* Asked and asked and never answered. Foxy stops for the same reason it
     * stops after three refusals: every try reserves counters the mint may
     * never sign, and a long run of them hides later ecash from a restore. */
    if (u.gaveUp === 'silence') {
      this.blockedCard('stuckInvoice', {
        tone: 'warn',
        title: 'PAID, NOT COLLECTED',
        reason: sats + ' sats at ' + host + '. Foxy asked for them ' + (u.tries || 10)
          + ' times and the mint never answered'
          + (u.reason ? ' (' + u.reason + ')' : '') + ', so it stopped asking on its own.',
        chip: 'The money is still at the mint. Try again when it is answering.',
        retry: 'TRY AGAIN',
        go: () => {
          window.FoxyWallet.retryRefusedClaim(hit.quote).then(() => {
            this.toast('Collected ' + sats + ' sats');
            this.refreshBalance();
          }, e => this.claimFailed(e));
        },
      });
      return;
    }
    this.blockedCard('stuckInvoice', {
      tone: 'warn',
      title: 'PAID, NOT COLLECTED YET',
      reason: sats + ' sats at ' + host + ' \u2014 retrying. ' + (u.reason || ''),
      chip: 'The money is at the mint, waiting for this phone. Keep Foxy installed until it arrives.',
    });
  }

  claimFailed(e, again) {
    const W = window.FoxyWallet;

    /* Classify on the RAW error, display the translated one.
     *
     * reason() rewrites errors for humans before returning them — "already
     * spent" becomes "Already claimed — somebody took this token." Matching
     * the translated text meant matching words that were no longer in it, so
     * everything landed in the network bucket. The friendly wording is kept
     * here as a fallback for when the raw message is not available. */
    const raw = String((e && (e.message || e.detail)) || e || '').toLowerCase();
    const why = (W && W.reason) ? W.reason(e) : String((e && e.message) || e);
    const low = (raw + ' ' + String(why)).toLowerCase();

    // your own tap on Cancel is not a failure worth a card
    if (/cancelled|canceled/.test(low)) return;

    // not a connection problem, and not one to try again
    if (this.isBadSignatures(e)) { this.badSignatureCard(null, 'swap'); return; }

    /* Each of these three is its own kind, not all `netLost`.
     *
     * The queue below deduplicates by kind: a card arriving while another is
     * open waits, and a waiting card of the same kind is dropped as a repeat.
     * All three claim failures shared one kind, so they counted as repeats of
     * each other — "LOCKED TO SOMEONE ELSE" arriving behind "CONNECTION LOST"
     * threw the connection card away, and the person was told the one thing
     * that happened to arrive last. They are different answers and they queue
     * as different answers. It also means the diary line names what happened
     * rather than saying netLost for a lock that has nothing to do with the
     * network. */
    /* Already here. The mint says spent and this phone is who spent it: a
     * payment that landed while its "paid" did not reach the payer, shown to
     * this phone again as a code. Not a warning, and nothing to do. The two
     * offline refusals of the same thing say it in the same card. */
    if ((e && e.foxyMine) || /already took that ecash|already has that ecash|already been paid this ecash/.test(low)) {
      const at = Number(e && e.foxyTakenAt) || 0;
      const sats = Math.round(Number(e && e.foxyTakenSats) || 0);
      const when = (at > 0 && this.tapAgoWords) ? ' ' + this.tapAgoWords(at) : '';
      this.blockedCard('tokenMine', {
        title: 'YOU ALREADY HAVE THIS PAYMENT',
        reason: 'This phone took this ecash' + when + '.'
          + (sats > 0 ? ' ' + this.group(sats) + ' sats, in your balance.' : ' It is in your balance.'),
        chip: 'Nothing more to do. It was not taken twice.',
        retry: '', back: '', tone: 'ask',
      });
      return;
    }

    if (/already spent|token already|already claimed|somebody took/.test(low)) {
      this.blockedCard('tokenSpent', {
        title: 'TOKEN ALREADY REDEEMED',
        reason: 'This token was claimed already \u2014 by someone else, or by this wallet.',
        chip: 'Nothing was taken from you.',
        retry: '', back: '', tone: 'warn',
      });
      return;
    }

    /* Not the offline refusal, which says "locked to it" about this phone and
     * was shown as LOCKED TO SOMEONE ELSE — about plain ecash with no lock on
     * it at all. */
    if (/p2pk|spend conditions|locked to/.test(low) && !/this phone is offline/.test(low)) {
      this.blockedCard('lockedElsewhere', {
        title: 'LOCKED TO SOMEONE ELSE',
        reason: 'This token is locked to a key this wallet does not hold, so it cannot be claimed here.',
        chip: 'Ask the sender for one that is not locked.',
        retry: '', back: '', tone: 'warn',
      });
      return;
    }


    this.blockedCard('mintUnreachable', {
      /* Amber, as it was while this shared netLost's row: nothing has failed
       * finally — the token is still good and the next attempt may work. */
      tone: 'warn',
      title: 'COULD NOT REACH THE MINT',
      reason: why,
      chip: 'The token is still good. Try again in a moment.',
      retry: again ? 'TRY AGAIN' : '', back: '',
      go: again || null,
    });
  }

  /* The same table the screens read, reachable from a method. */
  /* ---- both phones offline: the one question software cannot answer ------
   *
   * Unlocked ecash taken with no route is not settled and cannot be settled
   * here: the payer keeps a copy, and until this phone can swap, nothing on it
   * can find out whether they spent it again. Whether this particular payer
   * would is not a question about software, so it is put to the person holding
   * the phone, once, with the amount in front of them.
   *
   * Resolves true to take it and false for everything else — REJECT, a tap
   * outside the card, a card that could not be drawn. Never taking the money is
   * the safe failure: the payer keeps their own ecash and can offer it again to
   * either phone with a route.
   *
   * The dollar figure is this phone's own last price and says how old it is,
   * because offline it can be hours old and a stale figure presented as current
   * is its own small lie. Sats are the amount; dollars are the gloss. */
  offlineRiskCard(info) {
    const sats = Number(info && info.sats) || 0;
    const rate = this.satUsd ? this.satUsd() : 0;
    const W0 = window.FoxyWallet;
    const at = (W0 && Number(W0._rateAt)) || 0;
    const age = (at && this.agoWords) ? this.agoWords(Date.now() - at) : '';
    const worth = rate > 0 ? '$ ' + this.usd(sats * rate) : '';
    /* Three lines, dollars first: the amount, the sats
     * under it, and how old the price is that turned one into the other. */
    const chip = worth
      ? 'Amount ' + worth + '\n\u20bf ' + this.group(sats) + (age ? '\nPrice ' + age : '')
      : 'Amount \u20bf ' + this.group(sats);
    /* Nothing over it. A scanned token raises VERIFYING ECASH before anything
     * is known about it, and that screen sits above every card: the question
     * was asked underneath it, where nobody could see it or answer it, and the
     * person watched a verifying screen until they killed the app. */
    if (info && info.scanned && this.receivingDown) this.receivingDown();
    return new Promise((resolve) => {
      let done = false;
      const say = (yes) => { if (done) return; done = true; resolve(yes); };
      this.blockedCard('offlineRisk', {
        tone: 'warn',
        title: info && info.scanned ? 'HIGH RISK \u2014 YOU ARE OFFLINE'
          : 'HIGH RISK \u2014 YOU ARE BOTH OFFLINE',
        reason: info && info.scanned
          ? 'This ecash is not locked to you and this phone is offline, so nothing here can '
            + 'settle it. Until you get online, whoever gave it to you can still spend it. '
            + 'Continue only if you trust them. Otherwise connect first and take it then.'
          : 'You and whoever is paying you are both offline, so nothing here can settle '
          + 'this payment. Until you get online, they can technically take their money back. '
          + 'Continue only if you trust them. Otherwise connect first and take the payment then.',
        chip: chip,
        retry: 'CONTINUE', go: () => say(true),
        shut: { label: 'REJECT', tap: () => say(false) },
        /* A tap outside the card is a rejection, and it has to be, or the payer
         * waits on a promise nobody will ever settle.
         *
         * Deferred by a tick on purpose: `close()` runs `onClose` before it runs
         * the button's own handler, so a straight call here would answer "no"
         * for CONTINUE as well. A tick later, whichever button was pressed has
         * already spoken and `done` is set. */
        onClose: () => setTimeout(() => say(false), 0),
      });
      // a card that could not be drawn must not hold the payer's link open
      if (!this._blockedEl && !(this._cardQueue || []).some((c) => c.kind === 'offlineRisk')) say(false);
    });
  }

  /* Their change did not go back: say so, and put the way to fix it one press
   * away. It is locked to their phone, so showing it costs nothing and only
   * they can take it. */
  /* Change is about to be made for a scanned payment: the payment's
   * confirmation waits behind the change card (announcePayment). Bounded, so
   * a swap that fails or hangs does not swallow the confirmation. */
  changeMaking(info) {
    this._holdConfirmUntil = Date.now() + 12000;
    clearTimeout(this._holdConfirmT);
    this._holdConfirmT = setTimeout(() => this.releaseHeldConfirm('the change took too long'), 12000);
  }

  releaseHeldConfirm(why) {
    clearTimeout(this._holdConfirmT);
    this._holdConfirmUntil = 0;
    const ev = this._heldConfirm;
    if (!ev) return;
    this._heldConfirm = null;
    console.log('[foxy] confirmation: released (' + why + ')');
    this.announcePayment(Object.assign({}, ev, { force: true, again: true }));
  }

  changeStuckCard(info) {
    const sats = Math.round(Number(info && info.sats) || 0);
    const token = String((info && info.token) || '');
    if (!(sats > 0) || !token) return;
    console.log('[foxy] change: ' + sats + ' sats could not be handed back; asking this phone to show it');
    if (!this.stageScreen) { this.releaseHeldConfirm('no stage screen'); this.showTokenCode(token, (info && info.hash) || ''); return; }
    /* The screen: the three amounts, the code, and one thing to do. It is also
     * on the payment's entry in history, so DONE loses nothing. The
     * confirmation, held while the change was made, follows DONE
     * (changeMaking). */
    if (info && info.refund) {
      /* The whole payment going back, because it could not be brought to
       * this phone's own mint. Not received, and the screen says so. */
      clearTimeout(this._holdConfirmT);
      this.stageScreen('changeStuck', {
        title: 'Not received.<br>Send it back', qr: token,
        rows: [{ label: 'GOING BACK', value: this.stageMoney(sats) }],
        body: 'The payment could not be brought to your mint, so it was not received. Ask the payer to scan this to take it back.',
        button: 'DONE',
        go: () => this.releaseHeldConfirm('the refund card was dismissed'),
      });
      return;
    }
    const paid = Math.round(Number(info && info.paid) || 0);
    const asked = Math.round(Number(info && info.asked) || (paid > sats ? paid - sats : 0));
    const rows = [{ label: 'CHANGE DUE', value: this.stageMoney(sats) }];
    if (asked > 0) rows.push({ label: 'AMOUNT CHARGED', value: this.stageMoney(asked) });
    if (paid > 0) rows.push({ label: 'AMOUNT RECEIVED', value: this.stageMoney(paid) });
    clearTimeout(this._holdConfirmT);
    this.stageScreen('changeStuck', {
      title: 'You owe the<br>payer change', qr: token, rows: rows,
      body: 'The payer sent more than you requested. Ask them to scan this to receive their change.',
      button: 'DONE',
      go: () => this.releaseHeldConfirm('the change card was dismissed'),
    });
  }

  /* A token as a code, with the token's own amount. An entry's amount is what
   * the payment came to, which for change owed is a different number: the code
   * for 1,190 sats of change said ₿ 13 above it. */
  showTokenCode(token, hash) {
    const W = window.FoxyWallet;
    let sats = 0;
    try {
      const info = W.tokenInfo(token);
      sats = info ? Math.round(info.sats != null ? info.sats : info.amount) || 0 : 0;
    } catch (e) { sats = 0; }
    this.setState(p => ({
      tokenCopied: false, tokenOut: token, tokenOutSats: sats,
      tokenOutHash: hash || '', tokenOutFee: 0, tokenForPayee: true,
      screen: 'tokenOut', stack: p.screen === 'tokenOut' ? p.stack : p.stack.concat([p.screen]),
    }));
  }

  /* Take a card down because what it was waiting for has happened.
   *
   * Only the named kind, and only if it is the one on screen: a card the person
   * is reading must not vanish because something else finished. A card of that
   * kind still queued is dropped too — showing it after the fact would be
   * telling somebody to wait for a thing that has already come. */
  dismissCard(kind) {
    this._cardQueue = (this._cardQueue || []).filter((c) => c.kind !== kind);
    if (this._blockedEl && this._blockedKind === kind && this._blockedClose) this._blockedClose();
  }

  /* Paying somebody at another mint costs a Lightning fee. Asked, never assumed.
   *
   * Ecash from this phone's mint is no use to them, so the sats have to be
   * moved to theirs first — a melt here and a mint quote there, which is a real
   * Lightning payment with a real routing fee. The person is paying that fee on
   * top of the amount, and a wallet does not spend somebody's money on a route
   * because the alternative was refusing.
   *
   * The fee is a ceiling, not a price: the reserve the route does not use comes
   * back as change, so the card says "up to". Asked before anything melts, so a
   * no costs nothing at all.
   *
   * Resolves true to move and pay. Everything else — CANCEL, a tap outside, a
   * card that could not be drawn — is false.
   */
  /* The other side of the same decision: they will carry the payment home, and
   * this is what it costs.
   *
   * This phone has no route, so its sats cannot leave the mint they are at. The
   * receiver does have one, and has quoted the way home. The figures are the
   * same three — what leaves, what they get, what the crossing costs — so it is
   * the same screen, and pressing PAY is the last thing there is to do.
   *
   * Resolves true to pay. CANCEL, the X, and a screen that could not be raised
   * are all false.
   */
  crossFeeCard(terms, stuck, theirMint) {
    const ask = Math.round(Number(terms && terms.sats) || 0);
    const net = Math.round(Number(terms && terms.net) || 0);
    const fee = Math.max(0, Number(terms && terms.fee) || (ask - net));
    const at = (terms && terms.at) || (stuck && stuck.mint);
    return new Promise((resolve) => {
      let done = false;
      this._crossSay = (yes) => { if (done) return; done = true; resolve(!!yes); };
      this.setState((p) => ({
        screen: 'crossConfirm', stack: p.stack.concat([p.screen]), crossBusy: false,
        crossQ: {
          net: net, fee: fee,
          /* Named, from the offer where the terms do not say: "THEIR MINT"
           * under the heading THEIR MINT told nobody anything. */
          them: this.mintNameOf((terms && terms.to) || theirMint)
            || String((terms && terms.to) || theirMint || 'their mint').replace(/^https?:\/\//, ''),
          mine: this.mintNameOf(at) || String(at || '').replace(/^https?:\/\//, ''),
        },
      }));
    });
  }

  /* Paying somebody at another mint: the fee, and the only button that sends.
   *
   * A screen, and THE confirmation for this payment. It was a card, and
   * agreeing to it opened the ordinary confirmation which then had to be sent —
   * so one decision was put to the person twice ("when they
   * agree to the use of another mint that should be the last thing they need to
   * do"). `crossSpec` lays it out and `crossAnswer` settles this.
   *
   * Resolves true to move and pay. CANCEL, the X, and a screen that could not
   * be raised are all false.
   */
  /* `plan` may be a promise: the screen opens on what is already known — the
   * amount, and both mints — and the fee fills in when the two mints answer.
   * Until then its button says so and does nothing. */
  crossMintCard(plan, theirMint, myMint) {
    if (plan && typeof plan.then === 'function') {
      /* Not until the fee is known. This opened at once on "0 + fee" and
       * WORKING IT OUT, a confirmation with nothing in it to confirm; what is
       * looked at while the two mints answer is CALCULATING FEE, and the
       * confirmation arrives whole. A quote that was asked
       * for ahead is here already, so that screen is only put up for a wait
       * long enough to see. */
      return new Promise((resolve, reject) => {
        let over = false, shown = false;
        const down = () => { if (shown && this.hideStage) this.hideStage('calcFee'); };
        const up = setTimeout(() => {
          if (over || !this.stageScreen) return;
          shown = true;
          this.stageScreen('calcFee', {
            art: 'mints', title: 'Calculating<br>fee', dots: true, forMs: 45000,
            body: 'The receiver uses another mint, wait while I calculate the fee to pay them.',
            button: 'CANCEL',
            go: () => { if (over) return; over = true; console.log('[foxy] crossing: cancelled while the fee was being worked out'); resolve(false); },
          });
        }, 120);
        plan.then((p) => {
          clearTimeout(up); down();
          if (over) return;
          over = true;
          this.crossMintCard(p, theirMint, myMint).then(resolve, reject);
        }, (e) => {
          clearTimeout(up); down();
          if (over) return;
          over = true;
          reject(e);
        });
      });
    }
    const net = Number(plan && plan.net) || Number(plan && plan.moving) || 0;
    const fee = plan ? Math.max(0, Number(plan.feeSats) || 0) : null;
    return new Promise((resolve) => {
      let done = false;
      this._crossSay = (yes) => { if (done) return; done = true; resolve(!!yes); };
      this.setState((p) => ({
        screen: 'crossConfirm', stack: p.stack.concat([p.screen]), crossBusy: false,
        crossQ: {
          net: net, fee: fee,
          them: this.mintNameOf(theirMint) || String(theirMint || '').replace(/^https?:\/\//, ''),
          mine: this.mintNameOf(myMint) || String(myMint || '').replace(/^https?:\/\//, ''),
        },
      }));
    });
  }

  /* The paying phone's price, for a person with no route to agree to.
   *
   * This phone asked in dollars because its own bitcoin price may be hours old
   * (`dollarsOnly`). The payer has a current one and has said what it is and
   * what that makes of the amount. Nothing has left them: the sats move only
   * once this card is accepted and the request goes back in sats (M11).
   *
   * The comparison is worked out here, from what this phone last saw, so a
   * payer cannot dress it up (`readQuote`). With no price ever seen there is
   * nothing to weigh it against, and the card says exactly that rather than
   * implying agreement.
   *
   * Resolves true to accept. Everything else — DENY, a tap outside, a card that
   * could not be drawn — is false, and false is the safe failure: nothing has
   * been asked of anybody and nothing has moved.
   */
  /* The paying phone's price, for a person with no route to agree to.
   *
   * A screen, not a card: it is a person weighing two figures and deciding,
   * which is what the confirmation shell is for, and a card is for something
   * that went wrong. `priceSpec` lays it out and
   * `priceAnswer` settles this promise, whichever control they use.
   *
   * Resolves true to accept. Everything else — NO REJECT, the X, a screen that
   * could not be raised — is false, and false is the safe failure: nothing has
   * been asked of anybody and nothing has moved.
   */
  priceTermsCard(q) {
    /* The same price is not a question. Under a tenth of a percent there is
     * nothing to weigh, so it is agreed without asking.
     * No earlier price at all is not "the same" and is still asked. */
    const pct = (q && q.differsPct != null) ? Number(q.differsPct) : null;
    if (pct != null && isFinite(pct) && Math.abs(pct) < 0.1) {
      console.log('[foxy] price: the same as this phone\u2019s, agreed without asking');
      return Promise.resolve(true);
    }
    return new Promise((resolve) => {
      let done = false;
      this._priceSay = (yes) => { if (done) return; done = true; resolve(!!yes); };
      this.setState((p) => ({ screen: 'priceConfirm', stack: p.stack.concat([p.screen]),
                              priceQ: q }));
    });
  }

  /* No exact change, so the amount cannot be paid without over-paying.
   *
   * Asked, never assumed. Where the receiver has a route the difference comes
   * straight back over the same link; where neither phone has one it cannot come
   * back at all, and the extra is a gift. A wallet does not give somebody's
   * money away because the arithmetic was convenient.
   *
   * Resolves true to send and false for everything else — the cancel, a tap
   * outside, a card that could not be drawn. Not sending is the safe failure:
   * nothing has been made and nothing has moved. */
  overpayCard(info) {
    const asked = Number(info && info.asked) || 0;
    const pay = Number(info && info.pay) || 0;
    const over = Number(info && info.over) || 0;
    const back = !!(info && info.changeComesBack);
    return new Promise((resolve) => {
      let done = false;
      const say = (yes) => { if (done) return; done = true; resolve(yes); };
      this.blockedCard('overpay', {
        tone: 'warn',
        title: 'YOU DON\u2019T HAVE EXACT CHANGE',
        reason: back
          ? 'The smallest you can make is ' + this.group(pay) + ' sats for a '
            + this.group(asked) + '-sat payment. They are online, so the extra '
            + this.group(over) + ' sats come straight back to you as change.'
          : (info && info.says)
          ? 'The smallest you can make is ' + this.group(pay) + ' sats for a '
            + this.group(asked) + '-sat payment. ' + info.says
          : 'The smallest you can make is ' + this.group(pay) + ' sats for a '
            + this.group(asked) + '-sat payment. You are both offline, so they '
            + 'cannot give you the extra ' + this.group(over) + ' sats back \u2014 they keep it.',
        chip: this.group(asked) + ' sats owed  \u00b7  ' + this.group(over) + ' sats over',
        retry: 'YES, SEND ' + this.money(pay).main, go: () => say(true),
        shut: { label: 'NO, CANCEL', tap: () => say(false) },
        // a tap outside is a cancel; deferred a tick so a button answers first
        onClose: () => setTimeout(() => say(false), 0),
      });
      if (!this._blockedEl && !(this._cardQueue || []).some((c) => c.kind === 'overpay')) say(false);
    });
  }

  /* A payment taken on trust while both phones were offline, and the payer spent
   * their copy back. Said plainly: this is money that was shown, counted, and is
   * now gone, and the person who chose to trust them has to hear it from Foxy
   * rather than work it out from a balance that quietly shrank. */
  /* A payment taken at risk has settled: its own confirmation, saying so. */
  trustSettled(info) {
    /* Said by YOUR MONEY IS SAFE, with everything else that was claimed
     * (`moneyIsSafe`). Its own confirmation was raised as a screen and lost at
     * once to the reconnect going on around it: nobody saw it. */
    this.loadHistory();
  }

  /* YOUR MONEY IS SAFE: what was waiting for a connection has been swapped in.
   *
   * One screen for all of it, with the total, because that is the question a
   * person coming back online has — is what I was paid really mine now — and
   * the answer is one figure, not a confirmation per payment. Drawn over everything rather than as a screen of the app, so
   * a reconnect changing screens under it cannot take it away. The total
   * grows while it is up and starts again once it has been dismissed. */
  moneyIsSafe(info) {
    const sats = Math.round(Number(info && info.sats) || 0);
    if (!(sats > 0)) return;
    /* Only what was at risk. Change, and payments locked to this phone, were
     * never anybody else's to spend: saying they are safe now says they were
     * not before, about money the person was never told was in question. They are swapped in and nothing is said. */
    if (!(info && info.trusted)) {
      this.refreshBalance();
      this.loadHistory();
      return;
    }
    this._safeTotal = (this._safeTotal || 0) + sats;
    this._safeCount = (this._safeCount || 0) + 1;
    console.log('[foxy] money is safe: ' + this._safeTotal + ' sats that were at risk are claimed, in '
      + this._safeCount + ' payment(s)');
    this.refreshBalance();
    this.loadHistory();
    if (!this.stageScreen) return;
    this.moneyIsSafeShow();
  }

  moneyIsSafeShow() {
    if (!(this._safeTotal > 0)) return;
    /* Not over another of these screens: a code somebody is scanning, or a
     * wait with the four digits on it, is not this one's to replace. It
     * waits its turn. */
    const up = document.getElementById('foxy-stage');
    if (up && up.getAttribute('data-stage') !== 'moneySafe') {
      clearTimeout(this._safeT);
      this._safeT = setTimeout(() => this.moneyIsSafeShow(), 2000);
      return;
    }
    const money = this.stageMoney(this._safeTotal);
    this.stageScreen('moneySafe', {
      title: 'Your money<br>is safe', amount: money,
      body: (this._safeCount === 1 ? 'The payment you accepted at risk has'
        : 'The ' + this._safeCount + ' payments you accepted at risk have')
        + ' been claimed.<br><strong>\u20bf ' + this.group(this._safeTotal)
        + '</strong> is now yours and nobody else can spend it.',
      button: 'DONE',
      go: () => { this._safeTotal = 0; this._safeCount = 0; },
    });
  }

  /* CLAIM NOW, on an at-risk payment's own screen: the same claim a connect
   * runs, asked for by hand, for the time it has not happened by itself. */
  claimAtRiskNow() {
    const W = window.FoxyWallet;
    if (!W || !W.claimUnclaimed || this.state.txClaiming) return;
    if (this.offlineNow()) {
      this.toast('This phone is offline. Connect first, then claim.', true);
      return;
    }
    console.log('[foxy] history: CLAIM NOW pressed on an at-risk payment');
    this.setState({ txClaiming: true });
    this.showMelt('Claiming\u2026');
    W.claimUnclaimed().then((took) => {
      this.hideMelt();
      this.setState({ txClaiming: false });
      this.refreshBalance();
      this.loadHistory();
      if (!(took > 0)) this.toast('Nothing could be claimed yet. Try again in a moment.', true);
      else if (this.state.screen === 'txDetail') this.back();
    }, (e) => {
      this.hideMelt();
      this.setState({ txClaiming: false });
      this.toast(W.reason ? W.reason(e) : 'That could not be claimed.', true);
    });
  }

  /* MAKE IT SAFE NOW, on a HIGH RISK payment's own screen: the swap a
   * connection runs by itself, asked for by hand. What became of it is said
   * by the wallet's own watcher (`W.onAtRisk`). */
  settleAtRiskNow() {
    const W = window.FoxyWallet;
    if (!W || !W.settleAtRisk || this.state.txClaiming) return;
    if (this.offlineNow()) {
      this.toast('This phone is offline. Connect first; it is made safe as soon as there is a connection.', true);
      return;
    }
    console.log('[foxy] history: MAKE IT SAFE NOW pressed on a high-risk payment');
    this.setState({ txClaiming: true });
    this.showMelt('Making it safe\u2026');
    const before = (W.atRisk ? W.atRisk() : []).length;
    Promise.resolve(W.takeBackRefused ? W.takeBackRefused() : 0).then(() => W.settleAtRisk()).then((out) => {
      this.hideMelt();
      this.setState({ txClaiming: false });
      this.refreshBalance();
      this.loadHistory();
      const left = (W.atRisk ? W.atRisk() : []).length;
      if (!(out && out.length) && left >= before) {
        this.toast(before ? 'It could not be checked yet. Try again in a moment.'
          : 'Nothing here can change that one: only the phone it was locked to can take it.', true);
      } else if (this.state.screen === 'txDetail') this.back();
    }, (e) => {
      this.hideMelt();
      this.setState({ txClaiming: false });
      this.toast(W.reason ? W.reason(e) : 'That could not be checked.', true);
    });
  }

  trustLostCard(info) {
    const sats = Number(info && info.sats) || 0;
    this.blockedCard('trustLost', {
      tone: 'bad',
      title: 'THEY TOOK THAT PAYMENT BACK',
      reason: 'The ' + this.group(sats) + ' sats you accepted while you were both offline had '
        + 'already been spent by the time this phone could check. The mint would not honour them, '
        + 'so they have come off your balance and the payment is marked failed in your history. '
        + 'Nothing else of yours is affected.',
    });
  }

  BLOCKED_INFO(kind) { return BLOCKED[kind]; }

  /* Shaped like BACK UP YOUR BITCOIN, because it is the same kind of thing:
   * something the app wants to tell you, not a system warning bolted to the
   * top of the screen.
   *
   * Plain DOM on document.body, so it does not depend on the design runtime
   * re-rendering — and therefore outside the theme scope, so every colour here
   * is literal rather than a var().
   */
  showPriceError() {
    // dismissed stays dismissed until a price loads and fails again, or this
    // would reappear on every refresh cycle and there would be no using the app
    if (this._priceOff) return;
    /* Not while working offline. Its TRY AGAIN calls `refreshBalance`, which
     * cannot succeed until there is a route, so offline the card is a loop with
     * no way out but NOT NOW — and it would sit over a person who already knows,
     * because they chose it and the banner says OFFLINE. Dollar amounts go blank
     * on their own; that is the honest part, and it needs no card. */
    if (this.offlineNow()) return;
    if (this._priceBar) { this._priceBar.style.display = 'flex'; return; }

    const el = (style, html) => {
      const d = document.createElement('div');
      d.style.cssText = style;
      if (html) d.innerHTML = html;
      return d;
    };

    const root = el('position:fixed;inset:0;z-index:2147483500;background:rgba(0,0,0,.7);' +
      'display:flex;flex-direction:column;justify-content:flex-end;' +
      'font-family:SatSymbol,Sora,system-ui,sans-serif;animation:foxyIn .16s ease');

    const stage = el('position:relative;isolation:isolate');
    stage.appendChild(el('position:absolute;left:0;right:0;top:-290px;height:330px;' +
      'pointer-events:none;z-index:0;background:radial-gradient(ellipse 128% 100% at 50% 100%,' +
      'rgba(242,128,46,.55) 0%,rgba(242,128,46,.26) 42%,rgba(242,128,46,0) 78%)'));

    const card = el('position:relative;z-index:1;background:#141518;' +
      'border-radius:28px 28px 0 0;padding:28px 26px calc(31px + env(safe-area-inset-bottom));' +
      'display:flex;flex-direction:column;align-items:center;' +
      'border-top:1px solid rgba(242,128,46,.5);box-shadow:inset 0 2px 0 rgba(242,128,46,.9)');

    card.appendChild(el('width:72px;height:72px;border-radius:50%;' +
      'background:linear-gradient(160deg,#fff,#F2EFE8);' +
      'box-shadow:0 9px 20px rgba(0,0,0,.24),inset 0 -3px 0 rgba(0,0,0,.1);' +
      'display:flex;align-items:center;justify-content:center;font-size:40px;' +
      'font-weight:400;line-height:1;color:#DC7F1C', '\u20BF'));

    const title = el('font-size:22px;font-weight:700;letter-spacing:-0.022em;' +
      'color:#F5F1EC;text-align:center;margin-top:16px');
    title.textContent = 'NO BITCOIN PRICE';
    card.appendChild(title);

    const body = el('font-size:18px;font-weight:500;line-height:1.4;' +
      'color:rgba(245,241,236,.62);text-align:center;margin-top:7px;max-width:300px');
    body.textContent = 'Your balance is safe. Dollar amounts stay hidden until a price loads.';
    card.appendChild(body);

    const stack = el('align-self:stretch;display:flex;flex-direction:column;gap:12px;margin-top:24px');

    const retry = el('height:60px;border-radius:30px;background:#F2802E;color:#fff;' +
      'display:flex;align-items:center;justify-content:center;font-size:20px;' +
      'font-weight:800;letter-spacing:0.02em;cursor:pointer');
    retry.textContent = 'TRY AGAIN';
    retry.addEventListener('click', () => {
      if (retry.dataset.busy) return;
      retry.dataset.busy = '1';
      retry.textContent = 'TRYING\u2026';
      this.refreshBalance();
      setTimeout(() => { retry.dataset.busy = ''; retry.textContent = 'TRY AGAIN'; }, 2500);
    });
    stack.appendChild(retry);

    const later = el('height:52px;display:flex;align-items:center;justify-content:center;' +
      'font-size:18px;font-weight:800;color:rgba(245,241,236,.55);cursor:pointer');
    later.textContent = 'NOT NOW';
    later.addEventListener('click', () => {
      this._priceOff = true;
      this.hidePriceError();
    });
    stack.appendChild(later);

    card.appendChild(stack);
    stage.appendChild(card);
    root.appendChild(stage);
    // the backdrop dismisses too, same as the back-up card
    root.addEventListener('click', (e) => { if (e.target === root) later.click(); });
    document.body.appendChild(root);
    this._priceBar = root;
  }

  hidePriceError() {
    if (this._priceBar) this._priceBar.style.display = 'none';
  }

  /* ---- mint risk, told plainly --------------------------------------------
   *
   * Cards about the mint itself rather than about a payment.
   *
   * MINT NOT ANSWERING. The wallet decides (build/wallet/98-mint-health.js):
   * 3 counted failures spanning 10 minutes, counted only while Tor is carrying
   * other traffic. Shown once a session per mint, and only if some of the
   * balance is at that mint. The switch list says "not answering since 10:42".
   *
   * A LOT AT ONE MINT. A nudge to spread a large balance. Its numbers: */

  // at least this many sats at the connected mint…
  SPREAD_MIN_SATS = 100000;
  // …shown at most once in this long…
  SPREAD_EVERY_MS = 30 * 24 * 60 * 60 * 1000;
  // …remembered here as { shownAt, off }; off is "don't show this again"
  SPREAD_KEY = 'foxy.mint.spread';

  /* When a mint went quiet, for a person: "10:42", or "12 Sep 10:42" on
   * another day. Spelled out rather than locale-formatted, so it is the same
   * everywhere. */
  mintQuietSince(t, now) {
    const d = new Date(t);
    const pad = n => String(n).padStart(2, '0');
    const time = pad(d.getHours()) + ':' + pad(d.getMinutes());
    if (d.toDateString() === new Date(now || Date.now()).toDateString()) return time;
    return d.getDate() + ' ' + ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug',
      'Sep', 'Oct', 'Nov', 'Dec'][d.getMonth()] + ' ' + time;
  }

  /* The line under a mint in the switch list, or '' while it is answering.
   *
   * Working offline, a mint this phone has never loaded keysets from cannot be
   * connected to at all — there is nothing to connect from — so it says so
   * instead. Said rather than left to the refusal a tap would produce: the row
   * is greyed out beside it, and a dead-looking row with no reason reads as a
   * bug. */
  mintDownText(url) {
    const W = window.FoxyWallet;
    if (this.offlineNow() && W && W.mintCached && !W.mintCached(url)) return 'needs a connection';
    const rec = W && W.mintDown ? W.mintDown(url) : null;
    return rec ? 'not answering since ' + this.mintQuietSince(rec.firstFailAt) : '';
  }

  /* Is this mint usable right now? Offline that means: its keysets are on this
   * phone. With a route, every mint is. */
  mintReachable(url) {
    const W = window.FoxyWallet;
    if (!this.offlineNow()) return true;
    return !!(W && W.mintCached && W.mintCached(url));
  }

  mintDownNotice(mint) {
    const W = window.FoxyWallet;
    const rec = W && W.mintDown ? W.mintDown(mint) : null;
    if (!rec) return;
    const sats = this.mintPile(mint).sats;
    if (!(sats > 0)) return;
    this._mintDownShown = this._mintDownShown || {};
    if (this._mintDownShown[mint]) return;
    this._mintDownShown[mint] = true;
    const host = String(mint).replace(/^https?:\/\//, '');
    this.blockedCard('mintDown:' + host, {
      tone: 'warn',
      title: 'MINT NOT ANSWERING',
      reason: host + ' has not answered since ' + this.mintQuietSince(rec.firstFailAt) + '. '
        + this.group(sats) + ' sats of your balance are there, and ecash can only ever be '
        + 'redeemed at the mint that issued it. It may come back, and if it does, the ecash '
        + 'is still good. If it never does, nothing else can recover it.',
      chip: 'Once it answers again, move some of your balance to another mint.',
    });
  }

  /* Is the concentration nudge due? Pure, so the test holds it to its numbers. */
  spreadNudgeDue(sats, host, rec, now, busy) {
    if (busy) return false;
    if (!(Number(sats) >= this.SPREAD_MIN_SATS)) return false;
    // a test mint's ecash is worth nothing; there is nothing to spread
    if (String(host || '').toLowerCase().indexOf('testnut.cashu.space') >= 0) return false;
    const r = rec || {};
    if (r.off) return false;
    return !r.shownAt || now - r.shownAt >= this.SPREAD_EVERY_MS;
  }

  spreadNudge() {
    const W = window.FoxyWallet;
    if (!W || !W.connected) return;
    // the cards walletReady queues go first; the next refresh asks again
    if (Date.now() - (this._readyAt || 0) < 5000) return;
    let rec = null;
    try { rec = JSON.parse(localStorage.getItem(this.SPREAD_KEY) || 'null'); } catch (e) {}
    const host = this.mintHost();
    const sats = this.mintPile(W.mintUrl).sats;
    // never over or ahead of something more pressing: another card, the PIN, the price card
    const busy = !!(this._blockedEl || (this._cardQueue || []).length || this._pinEl
      || (this._priceBar && this._priceBar.style.display !== 'none'));
    if (!this.spreadNudgeDue(sats, host, rec, Date.now(), busy)) return;
    const keep = (r) => { try { localStorage.setItem(this.SPREAD_KEY, JSON.stringify(r)); } catch (e) {} };
    keep({ shownAt: Date.now(), off: false });
    this.blockedCard('spread', {
      tone: 'warn',
      title: 'A LOT AT ONE MINT',
      reason: this.group(sats) + ' sats of your balance are at ' + host + '. A mint holds the '
        + 'real bitcoin behind the ecash it issues, and a mint can fail or stop paying out.',
      chip: 'Spreading your balance across a few mints means no single mint holds all of it.',
      retry: 'MOVE SOME',
      go: () => this.goSwitchMint(),
      also: { label: 'DON\u2019T SHOW THIS AGAIN', tap: () => keep({ shownAt: Date.now(), off: true }) },
    });
  }

  // sats for whatever is on the keypad, at the live price
  wantedSats() {
    const s = this.state;
    const val = parseFloat(s.amount) || 0;
    if (s.unit === 'SATS') return Math.round(val);
    const px = this.px();
    if (!px) return 0;          // no price, no conversion
    return Math.round(val / px * 1e8);
  }

  // real invoice for the receive screen, then wait for it to be paid
  openReceive() {
    const W = window.FoxyWallet;
    this.stopReceive();
    this.setState({ invoice: '', invoiceHash: '', invoiceErr: '' });
    if (!W || !W.connected) { this.setState({ invoiceErr: 'No wallet connected.' }); return; }

    // Requesting an invoice is a mint call like any other, so Tor is
    // checked first and the work happens in its own method. Calling back into
    // openReceive() re-entered this guard and the check looped forever.
    const G = window.FoxyGate;
    if (G && G.quiet) {
      return G.quiet().then(ok => {
        if (!ok) { this.setState({ invoiceErr: 'Tor is reconnecting. Try again in a moment.' }); return; }
        console.log('[foxy] receive invoice |', G.stamp());
        this.openReceiveNow();
      });
    }
    return this.openReceiveNow();
  }

  /* How a receive is paid: LIGHTNING (the invoice) or CASHU (a payment
   * request a Cashu wallet answers with a token, taken with SCAN). The request
   * is made once for an amount, mint and purpose and kept, so its id does not
   * change with every render.
   *
   * It names this phone's onion address, so a payer on Foxy sends the payment
   * straight here over Tor (07-request-delivery.js, OnionInbox.swift) and
   * nothing needs scanning. The address is made first, which is why this is
   * '' for a moment; without Tor (Orbot) the request goes without one and SCAN
   * takes the token as before. `purpose` is 'receive' or 'split:<payer>'. */
  /* `usdCents` instead of a sat amount, for a phone with no route: the request
   * names dollars and leaves the conversion to the phone that has a current
   * price (`dollarsOnly`, `asksInDollars`). The two are alternatives — a
   * request carries one amount — so the cache key holds both. */
  railRequest(sats, purpose, usdCents) {
    const W = window.FoxyWallet;
    if (!W || !W.paymentRequest) return '';
    const why = purpose || 'receive';
    const cents = Math.round(Number(usdCents) || 0);
    const key = W.mintUrl + '|' + (Number(sats) || 0) + '|' + why + '|$' + cents;
    this._creqs = this._creqs || {};
    const have = this._creqs[key];
    if (have && have.making) return '';
    /* Made once and kept. It used to be remade whenever the open address
     * changed, which fought syncInbox: each made a new address for the other
     * to close (seen in a phone log). Leaving the screen clears these. */
    if (have) return have.text;
    this._creqs[key] = { making: true };
    // `ways` is { onion, nostr }, either of which may be missing
    const make = ways => {
      const text = W.paymentRequest(cents > 0 ? 0 : sats,
        { deliverTo: ways, purpose: why, usd: cents > 0 ? cents : 0 });
      this._creqs[key] = { text: text, inbox: ways };
      this.setState({ creqMade: Date.now() });
      return text;
    };
    /* The key the payer locks the ecash to is derived from the seed by the
     * phone, and `paymentRequest` is synchronous, so it can only take one the
     * phone derived earlier. Primed here, beside the address, because this is
     * the one moment before the code goes on screen when there is time to wait.
     * Without this the first request of a page load would go out unlocked.
     *
     * It never rejects — no key means an unlocked request, which is what every
     * request was before requests were locked — so nothing here has to handle
     * a failure.
     * The address is what decides when the code appears, as it did before. */
    const primed = W.primeLocks ? W.primeLocks() : Promise.resolve(0);
    /* No route, no address, and no waiting to find that out.
     *
     * `openInbox` is a bridge call with a twenty-five second timeout, and an
     * offline phone cannot publish an onion address at all — so it waited out
     * the whole twenty-five and then made the request without one. That is
     * invisible on the receive screen, which simply shows its code a little
     * late. It is not invisible in a tap: the receiver agreed a price, and the
     * request it agreed to went back twenty-five seconds later, by which time
     * the payer's link was gone and the payment never happened.
     *
     * Offline the answer is known, so it is given at once. */
    const opening = this.offlineNow()
      ? Promise.reject(new Error('this phone has no route, so it has no address to give'))
      : (this._inboxOpening || (W.openInbox ? W.openInbox() : Promise.reject(new Error('no inbox'))));
    this._inboxOpening = opening;
    const both = opening.then(ways => {
      this._inboxOpening = null;
      this._inboxUrl = ways;
      return ways;
    }, () => {
      this._inboxOpening = null;
      return null;
    });
    /* Kept so a caller that cannot make do with '' can wait for it
     * (`railRequestReady`). The row is replaced by `make`, which is why this is
     * set on the one that is here now and read only while `making` is true. */
    const ready = Promise.all([both, primed]).then(([ways]) => make(ways), () => make(null));
    this._creqs[key].ready = ready;
    return '';
  }

  /* The same request, for a caller that has to have it.
   *
   * `railRequest` answers '' for an amount it has not made one for yet, because
   * the screen that calls it renders many times a second and simply shows
   * nothing until the code exists. A caller with one shot cannot do that: the
   * receiver agreeing a price has to send the agreed request *now*, and reading
   * '' once made it tell the payer it had been refused — ACCEPT reported a
   * rejection.
   *
   * Resolves to the text, or to '' when it genuinely could not be made.
   */
  railRequestReady(sats, purpose, usdCents) {
    const W = window.FoxyWallet;
    const now = this.railRequest(sats, purpose, usdCents);
    if (now) return Promise.resolve(now);
    if (!W || !W.paymentRequest) return Promise.resolve('');
    const key = W.mintUrl + '|' + (Number(sats) || 0) + '|' + (purpose || 'receive')
      + '|$' + Math.round(Number(usdCents) || 0);
    const have = (this._creqs || {})[key];
    if (have && have.ready) return have.ready.then(t => t || '', () => '');
    /* No row and no promise: `railRequest` refused it outright. */
    return Promise.resolve(have ? (have.text || '') : '');
  }

  /* A request for a phone that is right here, made now.
   *
   * The one the receive screen shows names an onion address, so somebody who
   * scans the code and walks away can still pay it — and publishing that
   * address takes Tor several seconds. A tap needs none of that: the payment
   * comes straight back over the Bluetooth link that carried the offer
   * (`viaTap`), so the request can be made synchronously and offered the
   * instant the phones touch.
   *
   * That is what was making a tap wait on the Lightning invoice and the onion
   * address, neither of which another Foxy at the same mint needs ("a tap from another foxy device on the same mint should pass
   * data immediately"). The invoice still goes in the offer when it arrives,
   * for the wallets that do need one.
   *
   * Kept per amount, like `railRequest`, so the id does not change with every
   * render; cleared with the rest when the screen goes.
   */
  tapOnlyRequest(sats, purpose) {
    const W = window.FoxyWallet;
    if (!W || !W.paymentRequest) return '';
    const n = Math.max(0, Math.round(Number(sats) || 0));
    // a share of a split names itself, which is how `forgetRequests` tells them apart
    const key = 'tap|' + W.mintUrl + '|' + n + (purpose ? '|' + purpose + '|' : '');
    this._creqs = this._creqs || {};
    const have = this._creqs[key];
    if (have && have.text) return have.text;
    /* The lock pool is filled in the background: a request that goes out
     * unlocked is what every request was before requests were locked, and
     * waiting for a key here would put back the delay this exists to remove. */
    if (W.primeLocks) { try { W.primeLocks(); } catch (e) {} }
    const text = W.paymentRequest(n, { purpose: purpose || 'receive' });
    if (!text) return '';
    this._creqs[key] = { text: text };
    return text;
  }

  /* Whether a request for this amount is still being made: the moment between
   * the receive screen opening and its onion address answering. railRequest
   * returns '' both while it is waiting and when it will never come, and the
   * tap offer has to tell those apart (26d-tap.js). */
  railRequestPending(sats, purpose, usdCents) {
    const W = window.FoxyWallet;
    if (!W || !W.paymentRequest) return false;
    const key = W.mintUrl + '|' + (Number(sats) || 0) + '|' + (purpose || 'receive')
      + '|$' + Math.round(Number(usdCents) || 0);
    const have = (this._creqs || {})[key];
    return !!(have && have.making);
  }

  /* The Cashu payment request behind the receive screen's QR, or '' while
   * there is not yet one worth showing.
   *
   * '' is what leaves the loading animation on the QR (21-render-values), and
   * that is the point: a code goes on screen only once it carries the figure
   * the person asked for. A figure typed in dollars is 0 sats until the price
   * lands, and a receive reopened from history has only its invoice to read
   * the figure back out of. In both cases the QR waits, rather than showing a
   * request for no amount — which the payer's wallet offers as "pay any
   * amount", and which they may well scan before the real code replaces it.
   *
   * Someone who typed nothing is asking for anything, and that request is made
   * and shown as it always was. */
  cashuRequest() {
    const W = window.FoxyWallet;
    if (!W) return '';
    const s = this.state;
    if (s.invoiceIsAddress) return this.railRequest(0);
    /* Offline, the amount typed is dollars and stays dollars all the way into
     * the request. Converting it here at a price hours old is the one thing
     * this whole leg exists to avoid. */
    if (this.dollarsOnly()) {
      const cents = Math.round((parseFloat(s.amount) || 0) * 100);
      if (cents > 0) return this.railRequest(0, 'receive', cents);
      return this.railRequest(0);
    }
    const sats = this.wantedSats() || W.amountOf(s.invoice) || 0;
    if (sats > 0) return this.railRequest(sats);
    if ((parseFloat(s.amount) || 0) > 0) return '';   // typed, not converted yet
    return this.railRequest(0);
  }

  /* The onion address is open through a receive and a split, and closed on the
   * way out. It is opened at the keypad rather than when the QR appears: Tor
   * takes half a minute or so to publish an address, and until it is published
   * a payer cannot reach it (the payer's Foxy waited 25 s; seen in a phone
   * log). Nobody is told the address until a request names it.
   *
   * Called on every update, so it must not flap: leaving and coming back would
   * otherwise make a new address every render. */
  /* Foxy left the foreground, so the native side ended the address
   * (FoxyBridge+Delivery.closeInboxForBackground). What the page holds about it
   * is now stale: the URL, and every payment request built around that URL. Let
   * them go, and the next render opens a fresh address and writes a fresh
   * request naming it. */
  inboxWake() {
    this._inboxUrl = null;
    this._inboxOpening = null;
    this._inboxLeftAt = 0;
    this._creqs = {};
    this.syncInbox();
  }

  /* A request is for one payment, so one that has been answered is let go.
   *
   * They are kept per amount so a code does not change with every render, and
   * nothing took them out again once they were paid. The wallet closes a paid
   * request and drops its lock key, so the next person asked for the same
   * amount was handed a request this phone no longer knew: "That payment
   * answers no request open here", after the payer had moved its sats across
   * mints to make it, and ecash locked to a key with no row (1,198 sats asked
   * twice; and 1,201 twice).
   *
   * A split's other shares are kept: they are separate requests, still owed,
   * and their codes may be on somebody's screen. `paid` names the share that
   * has been answered, or nothing for an ordinary receive. */
  forgetRequests(paid) {
    const all = this._creqs || {};
    const keys = Object.keys(all);
    if (!keys.length) return;
    const kept = {};
    let let_go = 0;
    keys.forEach(k => {
      const share = /\|(split:\d+)\|/.exec(k);
      if (share && share[1] !== paid) kept[k] = all[k]; else let_go += 1;
    });
    this._creqs = kept;
    if (let_go) console.log('[foxy] receive: ' + let_go + ' request(s) let go; the next is made fresh');
  }

  syncInbox() {
    const W = window.FoxyWallet;
    const s = this.state;
    const screen = String(s.screen || '');
    const inReceive = (screen === 'amount' || screen === 'confirm') && s.flow === 'receive';
    /* And the two screens that are a tap still being talked about. They are not
     * receive screens, so this read them as leaving and closed the address a
     * payment may be on its way to — the same seam that took the Bluetooth
     * radio down under the price screen (26d-tap.js). */
    const talking = !!this._tapTalking;
    const wants = inReceive || talking || /^sp/.test(screen);
    if (wants) {
      this._inboxLeftAt = 0;
      /* A failure waits a beat before it is asked again.
       *
       * This runs on every render, and with no route `openInbox` rejects in
       * milliseconds — so a receive screen sitting offline asked for an onion
       * address over and over, and the phone built and tore down an inbox each
       * time: eleven "onion inbox closed" in fourteen seconds, none of which
       * could ever have opened. The screen is unchanged; what changes is how
       * often it asks while the answer is no.
       * A route arriving does not have to wait for this: the gate's own
       * reconnect re-renders, and four seconds is shorter than the connect. */
      const rested = !this._inboxFailedAt || Date.now() - this._inboxFailedAt > 4000;
      if (!this._inboxUrl && !this._inboxOpening && rested && W && W.openInbox) {
        const opening = W.openInbox();
        this._inboxOpening = opening;
        opening.then(url => { this._inboxOpening = null; this._inboxFailedAt = 0; this._inboxUrl = url; },
          () => { this._inboxOpening = null; this._inboxFailedAt = Date.now(); });
      }
      return;
    }
    /* No address, and the requests go all the same.
     *
     * They were only ever let go below, beside the address they named — and a
     * phone with no route has no address, so it returned here and kept every
     * request it had made for as long as the page lived (forgetRequests). */
    if (!this._inboxUrl && !this._inboxOpening && this.forgetRequests) this.forgetRequests();
    if (!this._inboxUrl || this._inboxOpening) return;
    // a beat before closing, so a screen change in two steps does not churn
    this._inboxLeftAt = this._inboxLeftAt || Date.now();
    if (Date.now() - this._inboxLeftAt < 1500) {
      clearTimeout(this._inboxWait);
      this._inboxWait = setTimeout(() => this.syncInbox(), 1600);
      return;
    }
    /* The address goes on answering for a minute and a half if a request
     * naming it was ever put on screen.
     *
     * A payment can be crossing to it. The tap that falls back to the onion is
     * exactly that: the receiver changes screen, the Bluetooth link drops, and
     * the payer — who is still minting the token — posts to the address about
     * half a second after this closes it. Closed, that post spends two minutes
     * finding out the service is gone, because the descriptor is still cached
     * where it was published (120893 ms, then 130714 ms). Held open, it
     * arrives in seconds.
     *
     * `_creqs` is empty unless a request naming this address was actually
     * built and shown, so an address nobody was ever given is dropped at once.
     * It costs nothing to wait: the phone hands the next screen a fresh warm
     * address immediately (warmSpare), and backgrounding still closes
     * everything outright. */
    const shown = Object.keys(this._creqs || {}).length > 0;
    this._inboxUrl = null;
    this._creqs = {};
    if (W && W.closeInbox) W.closeInbox(shown ? 90 : 0);
  }

  /* A payment for one of this phone's requests, sent straight here over Tor. */
  requestPaidHere(ev) {
    const W = window.FoxyWallet;
    // the wait is over, whichever way it went
    if (this.hideStage) this.hideStage('waitPayer');
    const split = /^split:(\d+)$/.exec(String(ev.purpose || ''));
    const onIt = split ? /^sp/.test(String(this.state.screen || '')) : this.state.screen === 'confirm';
    if (ev.stage === 'arrived') {
      // it is all here: the percentage's screen gives way to the ordinary one
      clearTimeout(this._recvProgT);
      if (this._recvProg && !onIt) this.hideMelt();
      this._recvProg = false;
      if (onIt) this.showMelt('Receiving ecash\u2026', 0, { sats: ev && ev.sats });
      /* A payment has landed on this screen: it does not go back on the air.
       * It did — the request was let go and a fresh one armed while the claim
       * was still at the mint — and the payer, home again, linked to it a
       * second time. Cleared when the screen is left. */
      this._tapPaidHere = true;
      return;
    }
    this.hideMelt();
    if (ev.stage === 'failed') this._tapPaidHere = false;
    /* And the conversation is over, whichever way it went.
     *
     * The hold is taken when a decision is put to a person and kept through the
     * answer AND the payment that answer was about — because `tapTerms`
     * resolving means the write is queued, not delivered, and because after
     * sending the terms this phone is waiting for exactly this (26d-tap.js).
     * This is where it ends. */
    if (this.tapTalking) this.tapTalking(false);
    /* The tap is over either way, so the screen stops claiming one.
     *
     * `tapArmed` means "this screen has a tap going" and is what keeps the
     * receiver alive through a payment (26d-tap.js). A payment that has landed
     * — taken or refused — is the end of it, and the next customer is a fresh
     * press, because one receiver is one payment's worth of radio. The four
     * digits stay up; they are what the person looks at next. */
    if (this.state.tapArmed) this.setState({ tapArmed: false });
    /* Answered, so the request it answered is not offered again. Whichever way
     * it went: a refused payment's request may be closed too, and a fresh one
     * costs nothing. */
    if (this.forgetRequests) this.forgetRequests(split ? 'split:' + split[1] : '');
    if (ev.stage !== 'paid') {
      if (onIt) this.toast('A payment arrived but could not be redeemed. Ask them to try again.', true);
      return;
    }
    /* A share of a split is reported by the split's own screens — the row
     * turns green on COLLECTING and EVERYONE HAS PAID sums them up — so its
     * history entry must not also queue a confirmation of its own. It did:
     * dismissing EVERYONE HAS PAID dropped the person on home and then played
     * one payment screen per share, back to back, for money they had just been
     * told about (three in a row).
     *
     * Marked seen before the history pass runs, because that pass is what
     * queues them and it is one line below. */
    if (split && ev.id) this.txIsNew('req-' + ev.id);
    /* Nor one that is still to be carried home: it is announced when it has
     * landed at this phone's own mint, and not before (`carryHomeNow`). */
    const carrying = /^carry:/.test(String(ev.purpose || '')) && !!this.carryHomeNow;
    if (carrying && ev.id) this.txIsNew('req-' + ev.id);
    this.refreshBalance();
    this.loadHistory();
    /* A payment taken at somebody else's mint, on their behalf, because they
     * had no route to move it themselves. It is this phone's money now — the
     * swap has come back, which is the whole of the risk — and what is left is
     * melting it home. Ordinary work, and a failure leaves it safe where it is
     * (26d-tap.js). */
    if (/^carry:/.test(String(ev.purpose || '')) && this.carryHomeNow) {
      this.carryHomeNow();
      return;
    }
    if (split) {
      const idx = Number(split[1]);
      const pending = W.splitPending && W.splitPending();
      const row = pending && pending.rows && pending.rows[idx];
      if (row && !row.paid) {
        this.spMarkPaid(idx, row.hash);
        if (this.state.spFromWaiting) this.setState({ screen: 'spWaiting', spFromWaiting: false });
      } else if (!pending && !(this.state.spInvoices || []).length) {
        /* Paid by tap before the share's invoice was made, so there is no row
         * yet: the tally is marked, and the rows are written as paid when
         * they arrive (`spMakeInvoices`). */
        this.spMarkPaid(idx, '');
      }
      // and the screen moves on to the next payer (17-split-bill-and-copy.js)
      setTimeout(() => this.spAdvanceAfterPaid(idx), 0);
      return;
    }
    // as a scanned token: the invoice screen closes, and the history pass announces it
    if (this.state.screen === 'confirm') this.closeReceive();
    this.noteReceived();
    /* And small change is made from it. Only a send armed this, so a wallet
     * that had just been paid 8,357 sats in five pieces sat online for twenty
     * seconds making none, went offline, and paid 8,192 for a 1,194-sat
     * payment. */
    if (this.tidyChangeNow) this.tidyChangeNow();
  }

  /* The choice of LIGHTNING or CASHU, as a sheet over the screen. */
  /* The sheet the NETWORK button and the speed picker both raise: a title and
   * a few rows, one of them ticked. */
  /* `rows` is an array, or a function returning one — which is how a sheet
   * that can be changed from inside itself redraws without closing. */
  chooseFrom(title, rows) {
    document.querySelectorAll('[data-foxy-rail-sheet]').forEach(n => n.remove());
    const root = document.createElement('div');
    root.setAttribute('data-foxy-rail-sheet', '1');
    root.style.cssText = 'position:fixed;inset:0;z-index:2147483300;background:rgba(0,0,0,.6);display:flex;'
      + 'flex-direction:column;justify-content:flex-end;font-family:SatSymbol,Sora,system-ui,sans-serif;animation:foxyIn .16s ease';
    const card = document.createElement('div');
    card.style.cssText = 'background:#141518;border-radius:28px 28px 0 0;padding:26px 22px calc(26px + env(safe-area-inset-bottom));'
      + 'display:flex;flex-direction:column;gap:12px';
    const head = document.createElement('div');
    head.style.cssText = 'font-size:22px;font-weight:800;letter-spacing:-0.022em;color:#F5F1EC;text-align:center;margin-bottom:4px';
    head.textContent = title;
    card.appendChild(head);
    const close = () => root.remove();
    const draw = () => {
    while (card.children.length > 1) card.removeChild(card.lastChild);
    (typeof rows === 'function' ? rows() : rows).forEach(o => {
      const on = !!o.on;
      /* A network this amount cannot use is shown and not offered.
       *
       * It used to be listed like any other and refuse on the tap, with the
       * reason in a toast — so the person chose a network, watched the sheet
       * close, and read why two seconds later somewhere else. Greyed with the
       * reason under its name, the answer is in front of them before they
       * reach for it. */
      const off = !!o.off;
      const row = document.createElement('div');
      row.style.cssText = 'display:flex;align-items:flex-start;gap:14px;padding:14px 18px;border-radius:20px;'
        + 'cursor:' + (off ? 'default' : 'pointer') + ';opacity:' + (off ? '0.45' : '1') + ';'
        + 'background:' + (on ? 'rgba(242,128,46,.14)' : '#1C1C1E') + ';border:1.5px solid ' + (on ? '#F2802E' : 'rgba(255,255,255,.1)');
      /* A block, not a column of flex items: the pill below sits in the
       * description's own text flow, and a float inside a flex container is
       * ignored. */
      const text = document.createElement('div');
      text.style.cssText = 'flex:1;min-width:0';
      const name = document.createElement('div');
      name.style.cssText = 'font-size:18px;font-weight:800;color:#F5F1EC;margin-bottom:3px';
      name.textContent = o.label;
      text.appendChild(name);
      let sub = null;
      if (o.sub) {
        sub = document.createElement('div');
        // flow-root so the floated pill is inside it rather than hanging out
        sub.style.cssText = 'font-size:16px;font-weight:500;line-height:1.35;'
          + 'color:rgba(245,241,236,.6);display:flow-root';
        sub.textContent = o.sub;
        text.appendChild(sub);
      }
      /* Two different questions in one sheet: the tick is which network this
       * screen is on, the pill is which one every receive starts on. The
       * pill answers in place — setting a default is not choosing a network,
       * so the sheet stays open.
       *
       * It floats at the end of the description rather than taking a column
       * of its own. A column squeezed every line of the description into what
       * was left beside the widest word on the pill; floated last, the first
       * lines run the full width of the card and only the last one wraps
       * around it, with the pill sitting at the foot of the row on the right. */
      if (o.isDefault || o.makeDefault) {
        const isDef = !!o.isDefault;
        const pill = document.createElement('div');
        pill.style.cssText = 'float:right;margin:2px 0 0 12px;padding:6px 11px;border-radius:13px;'
          + 'font-size:13px;font-weight:800;letter-spacing:0.06em;white-space:nowrap;'
          + (isDef
            ? 'background:rgba(191,227,236,.16);color:#BFE3EC;border:1.5px solid rgba(191,227,236,.5)'
            : 'background:transparent;color:rgba(245,241,236,.45);border:1.5px solid rgba(255,255,255,.14);cursor:pointer');
        pill.textContent = isDef ? 'DEFAULT' : 'SET DEFAULT';
        if (!isDef && o.makeDefault) {
          pill.addEventListener('click', (e) => {
            e.stopPropagation();
            o.makeDefault();
            draw();
          });
        }
        // last in the description's flow, so it lands on its last line
        (sub || text).appendChild(pill);
      }
      if (off && o.offWhy) {
        const why = document.createElement('div');
        why.style.cssText = 'margin-top:5px;font-size:15px;font-weight:700;color:#F7931A;display:flow-root';
        why.textContent = o.offWhy;
        text.appendChild(why);
      }
      row.appendChild(text);
      if (on) {
        const tick = document.createElement('div');
        tick.style.cssText = 'flex:none;font-size:20px;font-weight:800;color:#F2802E;line-height:1.2';
        tick.textContent = '\u2713';
        row.appendChild(tick);
      }
      // a greyed row is not a control: the sheet stays open and nothing happens
      row.addEventListener('click', () => { if (off) return; close(); if (!on && o.tap) o.tap(); });
      card.appendChild(row);
    });
    };
    draw();
    root.appendChild(card);
    root.addEventListener('click', (e) => { if (e.target === root) close(); });
    document.body.appendChild(root);
  }

  /* LIGHTNING, CASHU, and ON-CHAIN where the mint does it (26b-onchain.js). */
  chooseRail(current, pick) {
    const rails = [
      { rail: 'LIGHTNING', sub: 'Any Lightning wallet pays the invoice.' },
      { rail: 'CASHU', sub: 'A Cashu wallet answers with a token for this amount. Tap SCAN to take it.' },
    ];
    if (this.ocCan('receive')) {
      rails.push({ rail: 'ON-CHAIN', sub: 'An ordinary Bitcoin payment to an address this mint watches.' });
    }
    const W = window.FoxyWallet;
    this.chooseFrom('NETWORK', () => rails.map(o => {
      /* Under the mint's floor an on-chain payment is swallowed rather than
       * refused, so that network is greyed with the reason rather than offered
       * and then refused. */
      const sats = this.state.invoiceIsAddress ? 0
        : (window.FoxyWallet.amountOf(this.state.invoice) || 0);
      const barred = o.rail === 'ON-CHAIN' && this.ocReceiveBlocked(sats);
      return {
        label: o.rail, sub: o.sub, on: o.rail === current,
        off: barred, offWhy: barred ? this.ocFloorShort() : '',
        isDefault: !!(W && W.defaultRail && W.defaultRail() === o.rail),
        // a network this amount cannot use is not one to start every receive on
        makeDefault: (!barred && W && W.defaultRail) ? () => {
          W.defaultRail(o.rail);
          this.toast(o.rail + ' is now the default.');
        } : null,
        tap: () => pick(o.rail),
      };
    }));
  }

  openReceiveNow() {
    const W = window.FoxyWallet;
    const sats = this.wantedSats();
    /* The network this person asked every receive to start on, which used to
     * be Lightning whatever they chose (FoxyWallet.defaultRail). On-chain is
     * refused under the mint's floor, where the payment would be swallowed
     * rather than refused, so that falls back rather than opening on a
     * network this amount cannot use. */
    let rail = (W && W.defaultRail) ? W.defaultRail() : 'LIGHTNING';
    if (rail === 'ON-CHAIN' && (!this.ocCan('receive') || this.ocReceiveBlocked(sats))) rail = 'LIGHTNING';
    /* Offline there is one network, and it is Cashu.
     *
     * A Lightning invoice is the mint's to make and an on-chain address is the
     * mint's to give, so neither exists without a route. A Cashu payment request
     * is this phone's own: the amount, the unit, the mint it will accept and a
     * lock key the phone derives from the seed. `railRequest` already copes with
     * `openInbox` failing by making the request with no transport at all, which
     * is exactly right here — the payer is an inch away and the offer crosses
     * Bluetooth, not an onion. */
    if (this.offlineNow()) rail = 'CASHU';
    this.setState({ recvRail: rail });
    if (sats < 1) {
      /* SKIP on the amount screen: show the address so they choose the amount.
       * Not reachable while the keypad hides SKIP (`hideSkip`, home screen
       * redesign) and NEXT stays dead at zero; kept because it is
       * the fallback that comes back with SKIP, not because anything reaches
       * it today. */
      const addr = W.myAddress();
      this.setState({ invoice: addr, invoiceHash: '', invoiceIsAddress: true });
      return;
    }
    this.setState({ invoiceIsAddress: false });

    /* And offline, no invoice is asked for at all.
     *
     * The screen used to ask for one whatever the rail, because on Lightning it
     * is the QR and on Cashu it costs nothing. Offline it costs everything: the
     * request cannot be made, the three tries are spent, and the person is put
     * back on the screen they came from with an error — so opening RECEIVE while
     * offline would bounce them straight out of it. The Cashu request drives the
     * code on this screen (`creq`), and a payment arriving over Bluetooth is
     * announced through `_requestPaid`, not through an invoice's watch, so
     * nothing here needs one. */
    if (this.offlineNow()) {
      this.setState({ invoice: '', invoiceHash: '', invoiceErr: '' });
      console.log('[foxy] receive: offline, so a Cashu request and no invoice');
      return;
    }

    // the person's note or nothing: 'Foxy' on every invoice told the payer and the mint which wallet made it
    const memo = (this.state.note || '').trim();

    /* Three tries, not one.
     *
     * A first request to a mint failing is ordinary over a tunnel — the logs
     * are full of calls taking two and three seconds, and of a mint answering
     * 400 before working on the retry. Reporting failure two seconds in was
     * reporting the first stumble as the outcome. */
    /* A failure that never left the phone does not spend one of the three.
     *
     * The three tries are for a mint that stumbles. They were being spent on a
     * network that was shut: backgrounding the receive screen takes Tor off the
     * air on purpose, so every request made between then and the next circuit
     * fails without asking the mint anything. On a phone all three went
     * that way inside 100 seconds — two while the app was suspended, and the
     * third two seconds after it woke, with Tor still at "setting up" — and the
     * person was told "Foxy is still connecting to Tor" as the final answer to
     * a receive they had asked for once.
     *
     * `neverSent` is the wallet's own name for that class, the same list the
     * NUT-13 counters use. When it is one of those, wait for the gate to go
     * quiet instead — `FoxyGate.quiet` already waits for a circuit that was up
     * before — and try again without having used a try. Bounded, because a
     * radio that never comes back must still end in an answer rather than a
     * screen that waits for ever. */
    const G = window.FoxyGate;
    const WAITS = 3;
    const attempt = (n, waits) => W.invoice(sats, memo).catch(e => {
      const closed = !!(W.neverSent && W.neverSent(e));
      if (closed && waits < WAITS && G && G.quiet) {
        console.warn('[foxy] invoice: the request never left \u2014 waiting for Tor'
          + ' rather than spending a try (' + (waits + 1) + ' of ' + WAITS + ')');
        return G.quiet().then(ok => {
          if (!ok) throw e;
          return attempt(n, waits + 1);
        });
      }
      if (n >= 3) throw e;
      console.warn('[foxy] invoice attempt', n, 'failed \u2014', W.reason(e), '\u2014 retrying');
      return new Promise(ok => setTimeout(ok, n * 1500)).then(() => attempt(n + 1, waits));
    });

    /* This request, and no earlier one.
     *
     * Asking the mint for an invoice takes a while over Tor, and in that while
     * the person can change the amount and ask again. Both answers came back,
     * both armed a watch, and only the second was remembered — so the first
     * kept asking the mint about an invoice nobody was looking at until it
     * expired. Two of them were still running fifteen minutes on, once every
     * ten seconds, each on its own circuit, on a phone with poor connectivity,
     * the least able to carry it. */
    const mine = (this._invoiceRun = (this._invoiceRun || 0) + 1);

    attempt(1, 0).then(inv => {
      if (mine !== this._invoiceRun) {
        console.log('[foxy] invoice: an older request answered late; letting it go');
        return;
      }
      W.tag(inv.hash, { note: memo });
      // the note belonged to this invoice, not the next one
      this.setState({ invoice: inv.bolt11, invoiceHash: inv.hash, note: '', noteDraft: '' });
      // the watch polls and claims at whichever mint is connected, so a mint
      // switch waits until it has paid, expired or been stopped (moneyBusy)
      // whatever was being watched before, stop watching it
      this.stopReceive();
      this._watching = true;
      this._stopWatch = W.watch(inv.hash, paid => {
        if (mine !== this._invoiceRun) return;
        this._watching = false;
        // the payer said so first, and the mint has now agreed (tapPaidNotice)
        this._tapPaidNote = 0;
        if (this.hideStage) this.hideStage('paidCheck');
        this.haptic && this.haptic('success');
        this.setState(p => ({
          screen: 'paid',
          stack: p.stack.concat([p.screen]),
          recvResolved: true,
          recv: Object.assign({}, p.recv, { live: 'in' }),
        }));
        this.noteReceived();
        // The confirmation is already on screen; the history sweep must not
        // announce the same payment a second time when it catches up.
        this._seenTx = this._seenTx || {};
        this._seenTx[inv.hash] = true;
        // hold the figure from before the money landed, so dismissing the
        // confirmation has something to count up from
        if (this._preSettle == null) this._preSettle = this.balNow();
        this.refreshBalance();
      }, {
        timeoutMs: inv.expiresIn * 1000,
        onExpired: () => { this._watching = false; this.setState({ invoiceErr: 'This invoice expired.' }); },
      });
    }).catch(e => {
      if (mine !== this._invoiceRun) return;
      // invoiceErr is not rendered anywhere on that screen, so a failure here
      // used to be completely silent: no code, no message, nothing to copy.
      console.error('[foxy] invoice failed after 3 tries:', e);
      /* Back to where they came from, not onward to a screen they cannot
       * read. netLost renders black in this build, so it stranded people —
       * worse than the silence it was added to fix. The reason still surfaces,
       * in the toast and in the log. */
      this.setState(p => ({
        invoiceErr: W.reason(e),
        blockedWhy: W.reason(e),
        screen: (p.stack && p.stack.length) ? p.stack[p.stack.length - 1] : 'home',
        stack: (p.stack && p.stack.length) ? p.stack.slice(0, -1) : [],
      }));
      this.toast(W.reason(e), true);
    });
  }

  stopReceive() {
    if (this._stopWatch) { this._stopWatch(); this._stopWatch = null; }
    this._watching = false;
  }

  // A page loaded from a file is not a secure context, so navigator.clipboard
  // is usually missing in the web view. The old execCommand path still works,
  // and it has to run inside the tap that triggered it.
  /* ---- sending ---- */

  // anything payable: a bolt11 invoice, a lightning address, or an lnurl code
  acceptTarget(text) {
    const W = window.FoxyWallet;
    const t = String(text || '').trim().replace(/^lightning:/i, '');
    const kind = W.classify(t);

    if (kind === 'lnurl') {
      W.remember(t);                       // LNbits will not recall this later
      this.setState({ book: W.book() });
      // no amount is carried, so go to the keypad with the payee already set
      this.setState(p => ({
        screen: 'amount',
        stack: p.stack.concat([p.screen]),
        flow: 'send',
        asset: 'BITCOIN',
        network: 'LIGHTNING',
        recipientKind: 'email',
        recipient: t,
        unit: 'USD',
        amount: '',
        payFrom: 'BITCOIN',
      }));
      return true;
    }

    /* An address: paid on chain, if the mint does that. The amount comes with
     * it when the code is a bitcoin: URI. */
    if (kind === 'address') { this.payOnchain(t); return true; }

    // A bearer token is not something to pay TO — it is money handed to you,
    // so take it rather than calling it a bad address.
    if (kind === 'token') { this.takeTokenFromPaste(t); return true; }
    if (kind === 'request') { this.openRequest(t); return true; }
    if (kind === 'fedimint') {
      this.toast('That is a Fedimint invite, not a Cashu token.', true); return false;
    }
    if (kind === 'bolt12') {
      this.toast('That is a BOLT12 offer, which mints cannot pay yet.', true); return false;
    }
    if (kind === 'nostr') {
      this.toast('That is a nostr identity, not something to pay.', true); return false;
    }
    if (/^0[23][0-9a-f]{64}$/i.test(t)) {
      this.toast('That is a public key. Ask them for an invoice or a token.', true);
      return false;
    }

    if (kind !== 'invoice') {
      // 'badAddress' is navigated to but never defined, so setting it renders
      // an empty screen. Say what is wrong and stay put.
      this.toast('That is not an invoice, an address or a token.', true);
      return false;
    }

    const sats = W.amountOf(t);
    if (!sats) {
      /* An invoice that names no amount: ask for one, the way an LNURL does.
       *
       * This used to be turned away — "LNbits needs the amount at pay time,
       * which is a different call" — which was true of LNbits and has not been
       * true since Foxy paid through a mint. NUT-05 carries an `amount_msat`
       * beside the request for exactly this, and a zero-amount invoice is what
       * a "pay me what you like" link hands you, so refusing them refused an
       * ordinary way of being asked for money.
       *
       * Straight to the keypad with the invoice already set, and the same
       * screens after it. If the mint will not do it, `pay` says so by name
       * rather than the person finding out here. */
      this.setState(p => ({
        screen: 'amount',
        stack: p.stack.concat([p.screen]),
        flow: 'send',
        asset: 'BITCOIN',
        network: 'LIGHTNING',
        recipientKind: 'invoice',
        recipient: t,
        unit: 'USD',
        amount: '',
        payFrom: 'BITCOIN',
      }));
      return true;
    }
    /* No route, and an invoice. Lightning cannot be paid from here, but an
     * invoice this phone's own mint made names somebody who takes this mint's
     * ecash, and a token needs no connection to make: they scan it off this
     * screen. Anybody else's invoice is said no to now,
     * rather than after a confirmation screen and a wait. */
    if (this.offlineNow && this.offlineNow()) {
      if (W.invoiceFromThisMint && W.invoiceFromThisMint(t)) {
        console.log('[foxy] offline, and the invoice is from this mint: paying it with a token');
        this.payThisMintWithToken(sats);
      } else {
        console.log('[foxy] offline, and the invoice is not known to be from this mint: refused');
        this.blockedCard('offlineInvoice', {
          tone: 'warn',
          title: 'YOU\u2019RE OFFLINE',
          reason: 'A Lightning invoice can only be paid offline when it comes from your own mint. '
            + 'Ask them for a Cashu request, or reconnect.',
        });
      }
      return true;
    }
    const overLightning = () => this.setState(p => ({
      screen: 'sendConfirm',
      stack: p.stack.concat([p.screen]),
      flow: 'send',
      asset: 'BITCOIN',
      network: 'LIGHTNING',
      recipientKind: 'invoice',
      recipient: t,
      unit: 'SATS',
      amount: String(sats),
      payFrom: 'BITCOIN',
    }));

    /* The mint this wallet pays from made this invoice: paying it by Lightning
     * shows that mint both sides. Offer a token instead (payThisMintWithToken).
     * A fraction of a sat is paid by Lightning, which can carry it. */
    const msat = W.msatOf ? W.msatOf(t) : null;
    const offer = () => {
      const name = (this.mintName() || 'mint').toUpperCase();
      this.blockedCard('sameMintInvoice', {
        tone: 'warn',
        title: 'PAYING ANOTHER ' + name + ' USER',
        reason: 'This payment could have the ultimate privacy. But it requires you to make it over Cashu instead of Lightning.',
        retry: 'USE CASHU',
        go: () => this.payThisMintWithToken(sats),
        shut: { label: 'CONTINUE OVER LIGHTNING', tap: overLightning },
      });
    };
    if (!W.invoiceFromThisMint || msat == null || msat % 1000 !== 0) { overLightning(); return true; }
    if (W.invoiceFromThisMint(t)) { offer(); return true; }
    /* The mint's node not known yet (no invoice from it on this phone, and the
     * check after connecting not done): asked now, so the answer does not
     * depend on which invoice came first. */
    if (W.mintNodeKnown && !W.mintNodeKnown() && W.learnThisMintNode) {
      this._checkingInvoice = true;
      this.showMelt('Checking the invoice\u2026');
      W.learnThisMintNode().catch(() => null).then(() => {
        this._checkingInvoice = false;
        this.hideMelt();
        if (W.invoiceFromThisMint(t)) offer(); else overLightning();
      });
      return true;
    }
    overLightning();
    return true;
  }

  // Has this payment already been announced? The socket and the history sweep
  // both call here, so whichever notices a payment first wins and the other
  // stays quiet. On the very first load everything is marked seen without
  // announcing, or opening the app would replay your whole history at you.
  txIsNew(hash) {
    if (!hash) return false;
    this._seenTx = this._seenTx || {};
    if (this._seenTx[hash]) return false;
    this._seenTx[hash] = true;
    return !!this._seenSeeded;
  }

  // the confirmation screen, from either path
  announcePayment(ev) {
    const W = window.FoxyWallet;
    this.refreshBalance();

    /* Change is never a payment received. It is the rest of a payment this
     * phone made, and it was counted when it came back; swapping it in later
     * is bookkeeping. It was announced as ₿ 29 RECEIVED when the phone next
     * found a network, a minute after the 3-sat payment it belonged to. */
    if (!ev.force && /^(req-)?(tap-)?change-/.test(String(ev.hash || ''))) {
      console.log('[foxy] confirmation: change swapped in, not announced');
      return;
    }

    // A sweep is three transactions — claimed at their mint, melted out of it,
    // credited at yours — and announcing each turns one action into three
    // confirmations. They are all real, but only the last figure means
    // anything, so the sweep silences them and reports once itself.
    // A sweep writes several entries and the history pass finds them on its
    // own schedule — seconds after the fact, which is why marking the entries
    // it had already written was not enough. Nothing announces during a sweep
    // or shortly after it, except the sweep's own confirmation, which says so.
    if (!ev.force && (this._quiet || Date.now() < (this._hushUntil || 0))) {
      console.log('[foxy] confirmation held back:', ev.dir, ev.sats);
      return;
    }

    // a banner over the app you are already looking at is just noise
    const away = document.visibilityState !== 'visible';

    const out = ev.dir !== 'in';
    if (away) {
      /* No amount in the body.
       *
       * This renders on the lock screen and stays in notification history, so
       * "+1,234 sats" showed the activity to anyone who glanced at the phone.
       * The app shows the number when it is opened, which is the right place
       * for it. */
      W.notify(out ? 'sent' : 'received');
    }
    this.haptic && this.haptic('success');

    // This confirmation was not asked for: it arrived while the app was on
    // some other screen. Dismissing it should put that screen back rather
    // than dropping the person on home, which loses whatever they were doing.
    // The invoice screen and the send flow are excluded — those ARE this
    // payment, and going home from them is right.
    /* Every confirmation screen is its own payment's: dismissing a transfer's
     * success used to put the confirmation back, still offering to move the
     * sats again. */
    const own = ['paid', 'sendDone', 'confirm', 'amount', 'tokenOut'].concat(CONFIRM_SCREENS);
    /* A token screen is this payment's own only when it shows the token that
     * was redeemed. Another token's confirmation over it went home on DONE and
     * lost the token screen. */
    const otherToken = this.state.screen === 'tokenOut' && ev.tokenHash
      && ev.tokenHash !== this.state.tokenOutHash;
    if (own.indexOf(this.state.screen) < 0 || otherToken) {
      this._returnTo = { screen: this.state.screen, stack: (this.state.stack || []).slice() };
      console.log('[foxy] confirmation interrupted', this.state.screen);
    } else {
      this._returnTo = null;
    }

    /* Which entry raised it. A confirmation came up thirty milliseconds after
     * a refused payment's token screen opened and nothing said what it was
     * confirming. */
    console.log('[foxy] confirmation: ' + (out ? 'out' : 'in') + ', entry '
      + String(ev.hash || ev.tokenHash || '?').slice(0, 12) + (ev.force ? ', forced' : '')
      + ', raised over ' + this.state.screen);
    /* Held while change for it is being made: the change card comes first
     * and DONE raises this (changeMaking, changeStuckCard). Taking a fresh
     * confirmation down when the card arrived still flashed PAYMENT RECEIVED
     * for the second the swap took. */
    if (!ev.again && Date.now() < (this._holdConfirmUntil || 0)) {
      console.log('[foxy] confirmation: held behind the change being made');
      this._heldConfirm = ev;
      return;
    }
    this._heldConfirm = null;
    // the confirmation screen already knows how to word a payment going out
    this.setState(p => ({
      screen: 'paid',
      stack: p.screen === 'paid' ? p.stack : p.stack.concat([p.screen]),
      recvResolved: true,
      // its own heading, where the ordinary one would say the wrong thing
      paidSays: ev.says || '',
      payOut: out,
      paidTo: ev.to || (out ? p.recipient : ''),
      asset: 'BITCOIN',
      unit: 'SATS',
      amount: String(ev.sats),
      recv: Object.assign({}, p.recv, { live: 'in' }),
    }));
  }

  // Mirror console output to the native log. The web inspector is not always
  // available, and a payment that misbehaves is hard to catch after the fact.
  mirrorConsole() {
    if (this._mirrored) return;
    /* In every build now, and this is a deliberate change.
     *
     * It used to be Debug only. The reason was sound at the time: a Release
     * build silences console.log because the lines name mint hosts, balances,
     * Tor state and clipboard sizes, and this mirror posted every one of them
     * to the native log, which printed in all builds — the app walking around
     * its own guard.
     *
     * What changed is where a native line goes. `print` in a Release build no
     * longer reaches NSLog, the system log or a file; it reaches FieldLog,
     * which is memory on this phone, redacted on the way in, and gets out only
     * when the person taps COPY on the LOGS screen (Foxy/Debug/Print.swift).
     * So mirroring in Release now feeds the screen that exists for them, and
     * silences nothing that was silent before — which is what
     * tools/sim/release-silence.sh still checks. */
    const mh = window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.foxy;
    if (!mh) return;
    this._mirrored = true;
    this._installMirror();
  }

  _installMirror() {
    const post = (kind, args) => {
      try {
        const t = Math.round(performance.now());
        const text = '+' + t + 'ms ' + kind + ' ' + Array.prototype.map.call(args, a => {
          if (a instanceof Error) return a.message;
          if (typeof a === 'object') { try { return JSON.stringify(a); } catch (e) { return String(a); } }
          return String(a);
        }).join(' ');
        window.webkit.messageHandlers.foxy.postMessage({ id: 'log-' + Date.now(), action: 'log', text: text });
      } catch (e) {}
    };
    ['log', 'warn', 'error'].forEach(k => {
      const original = console[k].bind(console);
      console[k] = function () { original.apply(null, arguments); post('[' + k + ']', arguments); };
    });
  }

  // While the mint is being asked for an invoice, the QR slot holds this
  // instead of an empty box. Built as an SVG data URI so it animates inside
  // an <img> with no dependence on the page's own rendering — SMIL runs in
  // the image itself.
  qrLoadingSrc() {
    // A QR stacking itself: modules fall in from above and land row by row
    // from the bottom up, the way tetris pieces settle. The pattern comes from
    // a seeded generator rather than Math.random, so it looks like a real code
    // and is identical on every call.
    // Sized from the box rather than hardcoded: 13 cells at 14px plus gaps and
    // 26px padding came to 263px inside a 240px panel, so the right and bottom
    // columns fell outside it.
    const BOX = 240, GRID = 13, GAP = 2.2, PAD = 13;
    const CELL = (BOX - 2 * PAD - (GRID - 1) * GAP) / GRID;
    const CYCLE = 4.2;      // fall, hold, clear
    const FALL = 0.42;      // how long one module takes to drop
    const ROW_GAP = 0.16;   // delay between rows landing

    let seed = 0x5f3a;
    const rand = () => {
      seed ^= seed << 7; seed ^= seed >> 9; seed &= 0xffff;
      return seed / 0xffff;
    };

    // accelerating fall, then a small settle — gravity rather than a glide
    const EASE = '0.55 0 0.85 0.3';

    const drop = (x, y, w, h, fill, stroke, at) => {
      const k = (t) => (t / CYCLE).toFixed(4);
      const land = at + FALL;
      const inner = stroke
        ? '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="3" ' +
          'fill="none" stroke="#5CD46C" stroke-width="4"/>' +
          '<rect x="' + (x + CELL) + '" y="' + (y + CELL) + '" width="' + CELL + '" height="' + CELL + '" ' +
          'rx="1.5" fill="#5CD46C"/>'
        : '<rect x="' + x + '" y="' + y + '" width="' + w + '" height="' + h + '" rx="1.5" ' +
          'fill="' + fill + '"/>';

      return '<g opacity="0">' + inner +
        // the fall
        '<animateTransform attributeName="transform" type="translate" ' +
        'values="0 -' + (y + 90) + ';0 0;0 0;0 0" ' +
        'keyTimes="' + k(at) + ';' + k(land) + ';0.86;1" ' +
        'keySplines="' + EASE + ';0 0 1 1;0 0 1 1" calcMode="spline" ' +
        'dur="' + CYCLE + 's" repeatCount="indefinite" additive="sum"/>' +
        // visible only once it is on its way down, gone at the end of the loop
        '<animate attributeName="opacity" values="0;0;0.92;0.92;0" ' +
        'keyTimes="0;' + k(at) + ';' + k(land) + ';0.86;1" ' +
        'dur="' + CYCLE + 's" repeatCount="indefinite"/></g>';
    };

    const inFinder = (gx, gy) =>
      (gx < 3 && gy < 3) || (gx > GRID - 4 && gy < 3) || (gx < 3 && gy > GRID - 4);

    const parts = [];
    // bottom row lands first, like a stack filling up
    for (let gy = GRID - 1; gy >= 0; gy--) {
      const rowAt = (GRID - 1 - gy) * ROW_GAP;
      for (let gx = 0; gx < GRID; gx++) {
        if (inFinder(gx, gy)) continue;
        if (rand() > 0.52) continue;
        const x = PAD + gx * (CELL + GAP), y = PAD + gy * (CELL + GAP);
        parts.push(drop(x, y, CELL, CELL, '#5CD46C', false, rowAt + rand() * 0.1));
      }
    }

    // the corner finders drop last, snapping the code together
    const side = 3 * CELL + 2 * GAP;
    const lastRow = (GRID - 1) * ROW_GAP;
    [[0, 0], [GRID - 3, 0], [0, GRID - 3]].forEach(([gx, gy], i) => {
      const x = PAD + gx * (CELL + GAP), y = PAD + gy * (CELL + GAP);
      parts.push(drop(x, y, side, side, null, true, lastRow + 0.12 + i * 0.1));
    });

    const svg = [
      '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 240 240" width="240" height="240">',
      '<rect width="240" height="240" rx="18" fill="#0B140E"/>',
      // everything is clipped to the panel, so modules appear from its top edge
      '<defs><clipPath id="p"><rect width="240" height="240" rx="18"/></clipPath></defs>',
      '<g clip-path="url(#p)">', parts.join(''), '</g>',
      '</svg>'
    ].join('');
    return 'data:image/svg+xml;charset=utf-8,' + encodeURIComponent(svg);
  }

  /* Ecash reconcile set aside instead of deleting: the person sees it and
   * decides. There was no way to see or restore it before. */
  /* Set-aside ecash with no record of its mint (quarantinedUnknown) is said
   * separately. It was counted in the card's figure and offered back, and
   * PUT IT BACK left it where it was without a word: unquarantine will not
   * guess a mint for it. When that is all there is, the card only says so \u2014
   * there is nothing to press. Nothing here deletes anything. */
  offerQuarantine() {
    const W = window.FoxyWallet;
    const sats = W && W.quarantinedSats ? W.quarantinedSats() : 0;
    const unknown = Math.min(sats, W && W.quarantinedUnknown ? W.quarantinedUnknown() : 0);
    const shown = sats + '|' + unknown;
    if (!sats || this._quarantineShown === shown) return;
    this._quarantineShown = shown;
    const noMint = (n) => this.group(n) + ' sats of set-aside ecash ' + (n === sats ? '' : 'also ')
      + 'have no record of which mint issued them, so Foxy keeps them aside rather than guess. '
      + 'They are not in your balance and nothing has been deleted.';
    if (unknown >= sats) {
      this.blockedCard('quarantine', {
        tone: 'warn',
        title: 'ECASH SET ASIDE',
        reason: noMint(unknown),
      });
      return;
    }
    this.blockedCard('quarantine', {
      tone: 'warn',
      title: 'ECASH SET ASIDE',
      reason: this.group(sats - unknown) + ' sats the mint called spent could not be rebuilt from your '
        + 'seed, so Foxy set them aside instead of deleting them. If you know this ecash is '
        + 'still good, put it back; otherwise leave it.',
      chip: unknown ? noMint(unknown) : undefined,
      retry: 'PUT IT BACK',
      go: () => {
        // asks the mint first, and waits its turn behind any payment
        W.unquarantine().then(r => {
          if (r.back) this.toast(this.group(r.back) + ' sats put back');
          else if (r.stillSpent) this.toast('The mint still says that ecash is spent, so it stays set aside.', true);
          else if (r.elsewhere) this.toast('That ecash is from another mint \u2014 switch to it to put it back.', true);
          else if (r.unknown) this.toast(this.group(r.unknown) + ' sats have no record of their mint, so they stay set aside.', true);
          this.refreshBalance();
        }).catch(e => this.toast(W.reason(e), true));
      },
    });
  }

  // The seed phrase, shown on demand. Built in plain DOM for the same reason
  // as the other overlays: it must appear reliably, and it must not depend on
  // the design runtime re-rendering.
  showSeed() {
    const W = window.FoxyWallet;
    if (!W || !W.showSeedNative) { this.toast('Seed phrases are not available on this build.', true); return; }
    /* The words are the phone's, and its own screen shows them
     * (W.showSeedNative), opened as this sheet opens. The sheet keeps what is
     * around them: showing them again, verifying, and deleting everything. */

    const el = (style, text) => {
      const d = document.createElement('div');
      d.style.cssText = style;
      if (text) d.textContent = text;
      return d;
    };

    // Metrics lifted from the confirm screens so this reads as part of the app
    // rather than a panel bolted onto it.
    const TITLE = 'font-family:SatSymbol,Sora,system-ui,sans-serif;font-size:22px;font-weight:800;'
      + 'letter-spacing:-0.022em;color:#fff;text-align:center;line-height:1.25';
    const SUB = 'padding:3px 6px 16px;font-size:22px;font-weight:600;letter-spacing:-0.005em;'
      + 'color:rgba(255,255,255,.62);text-align:center;text-wrap:pretty;line-height:1.35';
    const RULE = 'height:1px;background:rgba(255,255,255,.12);margin:0 0 16px';
    const SECONDARY = 'height:56px;border-radius:28px;background:rgba(255,255,255,.07);'
      + 'border:1.5px solid rgba(255,255,255,.18);box-sizing:border-box;display:flex;'
      + 'align-items:center;justify-content:center;font-family:SatSymbol,Sora,system-ui,sans-serif;'
      + 'font-size:22px;font-weight:700;letter-spacing:0.02em;color:#fff;cursor:pointer';
    const CTA = 'height:60px;border-radius:30px;background-color:#DC7F1C;'
      + "background-image:radial-gradient(120% 84% at 26% 0%,rgba(255,240,220,.26),"
      + "rgba(255,240,220,0) 62%),linear-gradient(168deg,rgba(247,154,60,.62),"
      + "rgba(232,98,42,.72) 48%,rgba(194,74,27,.78)),url('foxy-fur.webp');"
      + 'background-repeat:no-repeat,no-repeat,no-repeat;background-size:auto,auto,150% auto;'
      + 'background-position:center,center,50% 34%;display:flex;align-items:center;'
      + 'justify-content:center;font-family:SatSymbol,Sora,system-ui,sans-serif;font-size:22px;'
      + 'font-weight:700;letter-spacing:0.02em;color:#fff;cursor:pointer;'
      + 'box-shadow:inset 0 2px 0 rgba(255,255,255,.4),inset 0 -4px 0 rgba(0,0,0,.16),'
      + '0 12px 24px rgba(220,127,28,.34)';
    const SHEET = 'position:absolute;inset:0;z-index:2147483551;background:#050805;'
      + 'overflow:auto;font-family:Figtree,system-ui,-apple-system,sans-serif;'
      + 'padding:0 22px 34px;box-sizing:border-box;display:flex;flex-direction:column';

    const root = document.createElement('div');
    root.style.cssText = SHEET.replace('2147483551', '2147483550');
    // its DELETE wipes the wallet: closed by the lock, as the delete prompts are (pinLock)
    root.setAttribute('data-foxy-close-on-lock', '');

    // header row: back on the left, delete on the right, title centred under.
    // Leaving by the back button changes nothing — the words are already saved.
    const bar = el('display:flex;align-items:center;justify-content:space-between;'
      + 'gap:12px;padding:56px 0 0;flex:none');
    const del = el('flex:none;width:52px;height:52px;border-radius:50%;'
      + 'background:rgba(255,92,92,.14);border:1px solid rgba(255,92,92,.4);'
      + 'box-sizing:border-box;display:flex;align-items:center;justify-content:center;'
      + 'cursor:pointer');
    del.innerHTML = '<svg width="21" height="21" viewBox="0 0 24 24" fill="none" '
      + 'stroke="#FF5C5C" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
      + '<path d="M4 7h16M9.5 7V5.2A1.2 1.2 0 0 1 10.7 4h2.6a1.2 1.2 0 0 1 1.2 1.2V7'
      + 'M6.5 7l.8 12.1A1.6 1.6 0 0 0 8.9 20.6h6.2a1.6 1.6 0 0 0 1.6-1.5L17.5 7'
      + 'M10.5 11v5.5M13.5 11v5.5"></path></svg>';
    const back = el('flex:none;width:52px;height:52px;border-radius:50%;'
      + 'background:rgba(255,255,255,.07);border:1px solid rgba(255,255,255,.16);'
      + 'box-sizing:border-box;display:flex;align-items:center;justify-content:center;'
      + 'cursor:pointer');
    back.innerHTML = '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" '
      + 'stroke="#fff" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">'
      + '<path d="M19.5 12H5m0 0 6-6m-6 6 6 6"></path></svg>';
    back.addEventListener('click', () => root.remove());
    bar.appendChild(back);
    bar.appendChild(el('flex:1'));
    bar.appendChild(del);
    root.appendChild(bar);

    root.appendChild(el('padding:14px 0 0;' + TITLE, 'YOUR SEED PHRASE'));
    root.appendChild(el(SUB,
      'These twelve words recover everything, on any Cashu wallet. The phone shows them '
      + 'on its own screen, where Foxy’s page cannot read them. Write them down on paper, '
      + 'never take a photo of them or save them on a computer.'));
    root.appendChild(el(RULE));

    // the words are on the phone's screen, behind its TAP TO REVEAL; from here they are shown again
    const again = el('flex:none;' + SECONDARY, 'SHOW MY WORDS');
    again.addEventListener('click', () => this.showSeedOnPhone(false, shown));
    root.appendChild(again);

    root.appendChild(el('flex:1;min-height:16px'));

    

    // once the phrase has been checked there is nothing left to verify
    const done = el('margin-top:10px;flex:none;' + CTA, 'VERIFY WORDS');
    /* Hidden until the words have been looked at: there is nothing to verify
     * before TAP TO REVEAL has been pressed on the phone's screen. The phone says whether it was, and a quiz passed there
     * leaves nothing to verify here either. */
    done.style.display = 'none';
    const checked = !!(W.backedUp && W.backedUp());
    const shown = (r) => {
      if (checked || (r && r.verified)) { done.style.display = 'none'; return; }
      if (r && r.revealed) done.style.display = '';
    };
    done.addEventListener('click', () => {
      root.remove();
      // straight into the check, which is an overlay like this screen is
      this.showVerify();
    });
    root.appendChild(done);

    del.addEventListener('click', () => this.askDeleteAll(root));

    document.body.appendChild(root);
    this.showSeedOnPhone(false, shown);
  }

  /* DELETE ALL DATA, held on the phone's seed screen (or the delete on the
   * older sheet): two prompts, then the wipe, which asks iOS for Face ID or the
   * passcode. `overlay` is removed once it is done. */
  askDeleteAll(overlay) {
    const el = (style, text) => {
      const d = document.createElement('div');
      d.style.cssText = style;
      if (text) d.textContent = text;
      return d;
    };
    /* Two prompts before anything is erased. The first states what goes, the
     * second exists because the first is the one people tap through. */
    /* A card rather than a full sheet: dimmed backdrop, red-edged panel from
     * the bottom, bin in a red circle, the destructive action first and a
     * plain dismiss under it. Same words as before. */
    const ask = (title, body, onYes) => {
      const back = document.createElement('div');
      back.setAttribute('data-foxy-close-on-lock', '');     // pinLock closes it
      back.style.cssText =
        'position:fixed;inset:0;z-index:2147483600;background:rgba(0,0,0,.72);'
        + 'display:flex;flex-direction:column;justify-content:flex-end;'
        + 'animation:foxyIn .16s ease';

      const card = el(
        'position:relative;background:#141518;border-radius:28px 28px 0 0;'
        + 'padding:28px 26px calc(31px + env(safe-area-inset-bottom));display:flex;'
        + 'flex-direction:column;align-items:center;'
        + 'border-top:1px solid rgba(255,92,92,.5);'
        + 'box-shadow:inset 0 2px 0 rgba(255,92,92,.55)');

      const ring = el('width:72px;height:72px;border-radius:50%;background:rgba(255,92,92,.14);'
        + 'display:flex;align-items:center;justify-content:center;flex:none');
      ring.innerHTML =
        '<svg width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#FF5C5C" '
        + 'stroke-width="1.9" stroke-linecap="round" stroke-linejoin="round">'
        + '<path d="M4 7h16M9.5 7V5.4A1.4 1.4 0 0 1 10.9 4h2.2a1.4 1.4 0 0 1 1.4 1.4V7"></path>'
        + '<path d="M6.4 7 7.3 19a1.6 1.6 0 0 0 1.6 1.5h6.2a1.6 1.6 0 0 0 1.6-1.5L17.6 7"></path>'
        + '</svg>';
      card.appendChild(ring);

      card.appendChild(el('font-family:Sora,system-ui,sans-serif;font-size:22px;font-weight:700;'
        + 'letter-spacing:-0.022em;color:#fff;text-align:center;margin-top:16px', title));
      card.appendChild(el('font-size:18px;font-weight:500;line-height:1.4;'
        + 'color:rgba(255,255,255,.62);text-align:center;margin-top:7px;text-wrap:pretty', body));

      const go = el('align-self:stretch;margin-top:24px;flex:none;height:60px;border-radius:30px;'
        + 'background:#E05252;display:flex;align-items:center;justify-content:center;'
        + 'font-family:Sora,system-ui,sans-serif;font-size:20px;font-weight:800;'
        + 'letter-spacing:0.02em;color:#fff;cursor:pointer', 'DELETE');
      const no = el('align-self:stretch;margin-top:12px;flex:none;height:56px;border-radius:28px;'
        + 'border:1.5px solid rgba(255,255,255,.22);box-sizing:border-box;display:flex;'
        + 'align-items:center;justify-content:center;font-family:Sora,system-ui,sans-serif;'
        + 'font-size:18px;font-weight:800;color:#fff;cursor:pointer', 'DISMISS');

      go.addEventListener('click', () => { back.remove(); onYes(); });
      no.addEventListener('click', () => back.remove());
      back.addEventListener('click', (e) => { if (e.target === back) back.remove(); });
      card.appendChild(go);
      card.appendChild(no);
      back.appendChild(card);
      document.body.appendChild(back);
    };

    ask('DELETE ALL DATA',
        'Are you sure you want to delete the keys and all data on this device?',
        () => ask('ARE YOU TRIPLE SURE?',
          'Every mint balance on this phone is erased and a new seed phrase is '
          + 'generated. Only this wallet’s twelve words can bring it back.',
          () => this.wipeAndRestart(overlay)));
  }

  /* The phone's own screen for the words (verify false) or its quiz (true).
   * Resolves { verified } or null; the wallet marks a passed quiz backed up.
   * `then` hears the answer; a refusal is said as a toast. */
  showSeedOnPhone(verify, then) {
    const W = window.FoxyWallet;
    return Promise.resolve().then(() => W.showSeedNative({ verify: !!verify })).then(r => {
      if (verify && r && r.verified) this.toast('Your seed phrase is checked');
      if (r && r.deleteAsked) this.askDeleteAll(null);
      if (then) then(r);
      return r;
    }).catch(e => {
      this.toast(W.reason(e), true);
      return null;
    });
  }

  /* Wipe, then act as if the app had just been installed. */
  wipeAndRestart(overlay) {
    const W = window.FoxyWallet;
    // the seed's delete waits on an iOS alert; a Cancel there erases nothing
    return Promise.resolve().then(() => W.wipeDevice()).then(res => this.wipedAndRestarting(overlay, res),
      e => this.toast(W.reason(e), true));
  }

  wipedAndRestarting(overlay, res) {
    const W = window.FoxyWallet;
    if (overlay) overlay.remove();
    clearInterval(this._refreshT);
    this.setState({
      walletLive: false, balSats: null, balUsd: null,
      screen: 'home', stack: [], contacts: [], txs: [],
    });
    console.log('[foxy] device wiped;', res.removed, 'keys removed, new seed generated');
    this.toast('Everything erased. A new seed phrase was generated.');
    this.retryConnect(W.defaultMint, 0);
  }

  // Swipe in from the left edge to go back, the way iOS does everywhere else.
  //
  // Listens on the document rather than any one screen, so it works wherever
  // you are without touching the markup. Only gestures that START within 24px
  // of the left edge count, so it never fights a horizontal scroll or a drag
  // inside the page.
  watchEdgeSwipe() {
    if (this._edgeOn) return;
    this._edgeOn = true;

    const EDGE = 24;      // how close to the edge it has to start
    const TRAVEL = 64;    // how far right before it counts
    const SLOP = 48;      // vertical wander allowed
    let live = false, x0 = 0, y0 = 0, t0 = 0;

    const start = (e) => {
      const t = e.touches && e.touches[0];
      if (!t) return;
      live = t.clientX <= EDGE;
      x0 = t.clientX; y0 = t.clientY; t0 = Date.now();
    };

    const end = (e) => {
      if (!live) return;
      live = false;
      const t = (e.changedTouches && e.changedTouches[0]);
      if (!t) return;

      const dx = t.clientX - x0;
      const dy = Math.abs(t.clientY - y0);
      const ms = Date.now() - t0;
      if (dx < TRAVEL || dy > SLOP || ms > 800) return;

      // the menu is a layer, not a screen: close that first
      if (this.state.open0) { this.setState({ open0: false }); return; }
      // and never leave a payment mid-flight
      if (this.state.sendPhase === 'in' || this.state.sendPhase === 'onchain') return;
      if (this.state.screen === 'home') return;

      console.log('[foxy] edge swipe: back');
      this.back();
    };

    document.addEventListener('touchstart', start, { passive: true });
    document.addEventListener('touchend', end, { passive: true });
    this._edgeOff = () => {
      document.removeEventListener('touchstart', start);
      document.removeEventListener('touchend', end);
    };
  }

  // Clear a list, on two taps. A single tap arms it and says so; a second
  // within four seconds does it. Neither touches money — history is a local
  // record the mint does not keep, and contacts are just saved names.
  askClear(which) {
    const W = window.FoxyWallet;
    if (!W) return;
    const now = Date.now();
    if (this._armed === which && now - (this._armedAt || 0) < 4000) {
      this._armed = null;
      if (which === 'history') {
        const clear = (forgetToken) => {
          W.clearHistory({ forgetToken });
          this.loadHistory();
          this.toast('History cleared');
        };
        /* A sent token nobody has claimed is money in a string. Clearing
         * history forgets its text, so say so first. */
        if (!W.tokensNotClaimed) { clear(false); return; }
        W.tokensNotClaimed().then(list => {
          if (!list.length) { clear(true); return; }
          const sats = list.reduce((a, t) => a + (Number(t.sats) || 0), 0);
          this.blockedCard('unclaimedTokens', {
            tone: 'warn',
            title: 'UNCLAIMED ECASH',
            reason: (list.length === 1 ? 'A token you sent' : list.length + ' tokens you sent') + ', '
              + this.group(sats) + ' sats, ' + (list.length === 1 ? 'has' : 'have') + ' not been claimed. '
              + 'Clearing history forgets ' + (list.length === 1 ? 'it' : 'them') + ' on this phone.',
            chip: 'Your twelve words can still restore unclaimed ecash.',
            retry: 'CLEAR ANYWAY',
            go: () => clear(true),
          });
        }).catch(() => clear(false));
      } else {
        W.clearContacts();
        // history would otherwise write every past payee straight back
        this._contactsCleared = true;
        this.setState({ contacts: [] });
        this.toast('Contacts cleared');
      }
      return;
    }
    this._armed = which;
    this._armedAt = now;
    this.toast('Tap again to clear ' + which);
  }

  // Who a sent payment went to: the address if there was one, otherwise the
  // invoice shortened at both ends. LNbits keeps no counterparty, so this comes
  // from what we tagged at send time or from the address still in state.
  paidTargetLabel() {
    const W = window.FoxyWallet;
    const to = String(this.state.paidTo || this.state.recipient || '').trim();
    if (to && W) {
      const kind = W.classify(to);
      if (kind === 'lnurl') return to;
      if (kind === 'invoice') return to.slice(0, 5) + '\u2026' + to.slice(-5);
    }
    return to || '\u2014';
  }

  // Show the next queued payment, if the screen is free to take one.
  //
  // Nothing is dequeued until its confirmation is actually dismissed, so an
  // interruption cannot swallow a payment: whatever was showing stays showing.
  SPLIT_SCREENS = ['spAmount', 'spWays', 'spShares', 'spPayer', 'spAssign', 'spWaiting', 'spAllPaid'];

  /* Whatever is in the queue, something is coming back for it.
   *
   * Every way out of nextPaidScreen with payments still queued used to depend
   * on somebody else calling it again — a dismissal, a render leaving a split,
   * or a history pass that happened to find something new. When none of those
   * came the queue stood still and the arrivals behind it were never shown;
   * the twenty-second give-up below could not fire either, since nothing was
   * there to notice the time had passed. It is the same shape as the on-chain
   * watcher that stopped asking: an exit with no timer behind it. The money is
   * credited by loadHistory either way — what is lost here is the
   * confirmation, not the payment. The poll ends of its own accord, because an
   * empty queue arms nothing. */
  QUEUE_RETRY_MS = 2000;

  queueLater() {
    clearTimeout(this._queueT);
    this._queueT = setTimeout(() => this.nextPaidScreen(), this.QUEUE_RETRY_MS);
  }

  nextPaidScreen() {
    const queue = this._paidQueue || [];
    if (!queue.length) return;
    if (this.state.screen === 'paid') { this.queueLater(); return; }   // one at a time
    // a split has its own running tally and its own all-paid screen; a
    // confirmation per payer would talk over it. They wait in the queue.
    if (this.SPLIT_SCREENS.indexOf(this.state.screen) >= 0) { this.queueLater(); return; }

    const next = queue[0];

    /* Change is never announced, so it never waits its turn either. It was
     * being handed to `announcePayment`, which declines it, and then sat at
     * the head of the queue for twenty seconds being "announced" — with the
     * real payment behind it. Three of them in a row held a received payment's
     * confirmation back for seventy seconds. Out of the queue at once, and on
     * to the next. */
    if (/^(req-)?(tap-)?change-/.test(String(next.hash || ''))) {
      queue.shift();
      console.log('[foxy] confirmation: change swapped in, not announced');
      this.nextPaidScreen();
      return;
    }

    /* Announce once, whatever happens next.
     *
     * Draining is paidDismissed's job, which means the queue only empties if
     * the confirmation reaches the screen and is dismissed. When it did not
     * stick — seen on device with a split open — this announced the same
     * payment every tick, forever. Marking it here breaks that loop without
     * needing to know why the screen failed to hold. */
    if (next.said) {
      // announced but never dismissed: let it go rather than block the rest
      if (Date.now() - next.said > 20000) {
        queue.shift();
        console.log('[foxy] confirmation never landed, dropped it');
        this.nextPaidScreen();
        return;
      }
      // announced and still waiting on its screen: come back and time it out
      this.queueLater();
      return;
    }
    next.said = Date.now();

    this.announcePayment({
      dir: next.dir || 'in', sats: next.sats, hash: next.hash, to: next.party || '',
    });
    // the confirmation may not have landed; this is what notices
    this.queueLater();
  }

  // called when a confirmation is dismissed
  /* How long home waits before Apple's paste control is laid over its PASTE
   * button again, once a payment confirmation has been dismissed.
   *
   * The control is a native view placed on top of the page, and it hands the
   * clipboard straight to acceptTarget — which for a Lightning invoice opens
   * the send flow. A confirmation is dismissed with a tap low on the screen,
   * which is where that control lands; a person dismissed a receive and found
   * an invoice from their clipboard already being sent. Nothing
   * was pasted by the app: the tap that closed one screen arrived on a button
   * that had not been there when their finger went down.
   *
   * So home settles first. The page's own PASTE is untouched and still one tap
   * — this is only the native control, and only for a moment. */
  PASTE_SETTLE_MS = 700;

  paidDismissed() {
    if (this._paidQueue && this._paidQueue.length) this._paidQueue.shift();
    /* Nothing measures or places a native view over the page until this is
     * past (syncPreview waits on it and comes back by itself). */
    this._slideUntil = Math.max(this._slideUntil || 0, Date.now() + this.PASTE_SETTLE_MS);
    if (this.syncPreview) this.syncPreview();
    // let the home screen land before the next one arrives
    clearTimeout(this._queueT);
    this._queueT = setTimeout(() => {
      this.nextPaidScreen();
      /* And once the confirmations are done, the one card that asks rather
       * than reports: how this wallet should be protected now that there is
       * something in it (offerSecureFoxy, 10-pin.js). Behind nextPaidScreen so
       * it never lands on top of a payment still being shown, and it is due at
       * most once. */
      if (!(this._paidQueue && this._paidQueue.length)) this.offerSecureFoxy();
    }, 520);
  }

  // every payment on the wallet surfaces, however it was made
  listenWallet() {
    const W = window.FoxyWallet;
    if (!W || !W.listen) return;
    if (this._unlisten) this._unlisten();
    // payments sent straight to this phone's requests, over Tor (12-receive.js)
    if (!this._requestPaidHooked && W.onRequestPaid) {
      this._requestPaidHooked = true;
      W.onRequestPaid(ev => this.requestPaidHere(ev));
    }
    // tap to pay, both sides (26d-tap.js)
    if (!this._tapHooked && W.onTap) {
      this._tapHooked = true;
      W.onTap(ev => this.tapHeard(ev));
      /* Change coming back, when this phone overpaid because it could not make the
       * amount exactly. Taken the way any ecash is taken, and only then is the
       * receiver told — `tapChangeKept` is what becomes M8, and the receiver holds
       * the link open until it comes. Told `false` on a failure rather than
       * nothing, because the other phone is waiting and "we could not keep it" is
       * something it can act on where silence is only a timeout. */
      if (W.onTapChange) {
        W.onTapChange(token => {
          /* Change is locked to a key only this phone holds, so it is already
           * ours the moment it arrives — the receiver cannot take it back. What is
           * left is whether it can be swapped in now.
           *
           * Offline it cannot: `receiveToken` is a swap. And offline is exactly
           * when change happens, because a payer who could swap would have paid
           * the exact amount. So with no route it is written into the store a
           * locked payment waits in, and the claim that runs on any screen money
           * could leave from takes it when there is one. Either way it is kept,
           * and only then is the receiver told — the ack is what lets them stop
           * holding the link open. */
          const changeHash = 'tap-change-' + Date.now();
          const bits = W.tokenInfo ? W.tokenInfo(token) : null;
          /* The wallet's own total, not one added up here. A piece's amount
           * is cashu-ts's own type, and `Number()` of one is the coercion its
           * next major version throws on: the one sum in the app that had not
           * gone over to `satsOf` with the wallet's, and it warned on the
           * first change to arrive in every session. `sats` is null for a
           * token that is not sats, which is 0 here and refused below. */
          const sats = bits ? Math.round(Number(bits.sats) || 0) : 0;
          /* Checked before it is believed: owed, no more than owed, this mint,
           * and locked to a key this phone asked for (W.checkChange). M7 is
           * the other phone's word, and it used to be kept as it came. A
           * refusal is told, so the receiver shows the change as a code
           * instead of thinking it delivered. */
          /* Or a refund: a payment the receiver was to carry to its own mint
           * and could not, sent back whole. Owed, then, is what was paid. */
          const carried = this._carriedPay && Date.now() < this._carriedPay.until ? this._carriedPay : null;
          const refund = !(Number(this._changeOwedSats) > 0) && !!carried;
          const owed = Math.round(Number(this._changeOwedSats) || (carried ? carried.sats : 0) || 0);
          const chk = W.checkChange ? W.checkChange(token, owed) : { ok: true, signed: true };
          if (!chk.ok) {
            console.warn('[foxy] change refused: ' + chk.why + ' (' + sats + ' sats arrived, ' + owed + ' owed)');
            W.tapChangeKept(false);
            return;
          }
          /* What it is worth here: the token less this mint's fee for taking
           * it. The receiver adds that fee to the token so the change arrives
           * whole, and settling the entry with the token's own figure counted
           * it as money that came back: a sat out for every change kept at a
           * mint that charges (tools/live/tap-scenarios.js 2b). */
          const net = W.changeNet ? W.changeNet(token) : sats;
          const kept = (how) => {
            // the link was being held open for exactly this; it may go now
            /* Change coming back belongs to the payment it came from: its own
             * entry is finished with the figures, and no second row appears for
             * money coming back. The entry `receiveToken`
             * wrote for the swap is marked so it does not interrupt either. */
            /* The receiver is told first, and the link is held a moment for it.
             *
             * `changeArrived` lets the link go, and it ran before the word that
             * the change was kept went out: the link closed, the word was never
             * sent, and the receiver — who had handed the change over — was told
             * it still owed it. */
            this._ackHold = Date.now() + 700;
            const told = W.tapChangeKept(true);
            setTimeout(() => this.syncTap(), 750);
            this.changeArrived(net);
            if (refund) {
              // the payment's own entry says it came back, as it does for change
              this._carriedPay = null;
              // on top of any change that had already come back for it
              try { if (carried.hash && W.changeSettled) W.changeSettled(carried.hash, net, { refund: true }); } catch (e) {}
              /* All of it, or it is not the payment coming back. The check
               * above has a ceiling and no floor: 10 sats locked to this
               * phone passed it for a payment of 310, and the card said the
               * payment had come back. A sat or two short is the mint's fee
               * for making the refund; more than that is said as it is. */
              const short = refund && net < carried.sats - Math.max(6, Math.ceil(carried.sats / 100));
              this.blockedCard('refunded', short ? {
                tone: 'warn',
                title: 'ONLY PART CAME BACK',
                reason: 'They could not bring your payment to their own mint, and sent back '
                  + this.group(net) + ' of the ' + this.group(carried.sats) + ' sats you paid.',
                chip: this.group(carried.sats - net) + ' sats were not returned.',
              } : {
                tone: 'warn',
                title: 'YOUR PAYMENT CAME BACK',
                reason: 'They could not bring it to their own mint, so they sent it back.',
                chip: this.group(net) + ' sats are yours again. They were not paid.',
              });
            }
            try { if (W.tag) W.tag(changeHash, { change: true }); } catch (e) {}
            /* Not announced. The payment said what it cost; change coming back
             * is that payment finishing, and a toast about it is a second
             * event for the person to make sense of. */
            console.log('[foxy] change kept: ' + sats + ' sats' + how);
            this.refreshBalance();
            this.loadHistory();
            return told;
          };
          if (!this.offlineNow()) {
            W.receiveToken(token, { hash: changeHash })
              .then(() => kept(''), e => {
                /* The swap failed but the ecash is still locked to this phone, so
                 * it is kept rather than dropped and claimed on the next try. */
                console.warn('[foxy] change could not be swapped in yet:', e && e.message);
                // kept without the swap only when the mint's signature on it verifies here
                if (!chk.signed) {
                  console.warn('[foxy] change refused: the mint would not swap it and its signatures do not verify');
                  return W.tapChangeKept(false);
                }
                try { W.keepChange(token, sats); return kept(', waiting to settle'); }
                catch (x) { return W.tapChangeKept(false); }
              }).catch(() => {});
            return;
          }
          // offline there is no swap to settle it, so the signature has to verify here
          if (!chk.signed) {
            console.warn('[foxy] change refused: offline, and its signatures cannot be checked here');
            W.tapChangeKept(false);
            return;
          }
          try { W.keepChange(token, sats); kept(', waiting for a connection'); }
          catch (e) {
            console.warn('[foxy] the change could not be written down:', e && e.message);
            this.toast('Change arrived but could not be saved.', true);
            W.tapChangeKept(false);
          }
        });
      }
    }
    this._unlisten = W.listen(ev => {
      this.loadHistory();
      if (!this.txIsNew(ev.hash)) return;
      const tag = W.tagsFor(ev.hash) || {};
      this.announcePayment(Object.assign({}, ev, { to: tag.to || '' }));
    });
  }

  // coming back from the background: the socket died while suspended, so the
  // history sweep is the only thing that will notice what happened meanwhile
  watchWake() {
    if (this._onWake) return;
    this._onWake = (away) => {
      this._putAway = false;
      // a top-up still owed waits for the next put-away; nothing runs in the foreground
      const W = window.FoxyWallet;
      // the native side says how long Foxy was really in the background
      if (typeof away === 'number') {
        // Face ID and Control Center take focus without the background: Foxy never left
        if (away < 1) return;
        console.log('[foxy] wake:', away + 's in the background');
        // A phone handed over while Foxy was in the background: lock first.
        this.pinLock();
        /* The lock is the page's own cover, and the phone's comes off it now.
         * The connection screen waits for the unlock, so until then nothing
         * said the page had the screen: the splash sat over the PIN pad for
         * the four seconds of the phone's backstop, on every return. */
        if (this._pinLocked && window.FoxyGate && window.FoxyGate.uncover) window.FoxyGate.uncover();
        /* The one Face ID of this visit: once past the lock, whose Face ID
         * unlock covers it, the seed is read now rather than when a payment
         * first needs it (FoxyWallet.openSeedForVisit). */
        this.pinUnlocked().then(() => W && W.openSeedForVisit && W.openSeedForVisit());
        // then a private connection set up again, as at launch (06-wallet-boot-and-restore.js)
        this.setUpAfterReturn();
        // a token still waiting to be redeemed is asked about again, after a wait
        this.claimWatchResume();
        /* A bill still being collected: its watchers were suspended with the
         * app and give up after an hour, and a share paid with nobody
         * watching lands at the mint unclaimed. resumeSplit settles what was
         * missed and watches what is still owed. */
        this.resumeSplit();
        /* The one-time .onion a payment request names: the native side ended
         * it as Foxy left (FoxyWebView.appEnteredBackground), so a request
         * still on screen would otherwise name an address nobody answers. */
        this.inboxWake();
        /* On chain settles in blocks, so a return after any real time away is
         * the likeliest moment for a deposit to have confirmed — and the timer
         * that would have asked was suspended with the app. */
        this.onchainAsk();
        this.onchainWatchLater();
        this.tidyChangeLater();
        /* Coming back is arriving at the home screen too, and the launch cover
         * is up again over it while Tor comes back — so the ride waits for it
         * to come down rather than playing behind it. */
        this.riderWhenSeen();
        return;
      }
      // a browser, with no native side and no Tor: history and sweeps, nothing to set up
      const now = Date.now();
      if (this._wakeAt && now - this._wakeAt < 3000) return;
      this._wakeAt = now;
      this.listenWallet();
      this.loadHistory();
      if (W && W.resumeSweeps) W.resumeSweeps().then(() => this.refreshBalance()).catch(() => {});
    };

    // the native side is the reliable signal: a suspended web view does not
    // always fire visibilitychange when iOS wakes it
    if (window.FoxyWallet && window.FoxyWallet.onResume) {
      window.FoxyWallet.onResume(this._onWake);
    }
    /* In the app the native side reports every return, and a page event is not
     * one: the first tap after launch gives the web view focus, and that ran a
     * whole confirming check — LOADING YOUR BALANCE over the home screen. Page
     * events stand in only where there is no native side, in a browser. */
    const native = !!(window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.foxy);
    if (native) return;
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'visible') this._onWake();
    });
    window.addEventListener('focus', this._onWake);
    window.addEventListener('pageshow', this._onWake);
  }

  /* A return's last step before the home screen: the balances, and the price
   * unless one is already on its way.
   *
   * refreshBalance waits on the price. Through a bridge the check's own fresh
   * price could still be walking its sources after the mint had answered, and
   * the check sat on it with the balances already loaded — 2.6 seconds in one
   * obfs4 trial, and up to the walk's whole 30. A price in flight is not
   * waited on now: the balance shows with the last price, and again with the
   * new one when it lands. */
  resumeLoad() {
    const W = window.FoxyWallet;
    const pending = W && W.rateInFlight ? W.rateInFlight() : null;
    const balance = Promise.resolve(this.refreshBalance());
    if (pending) pending.then(() => this.refreshBalance(), () => {});
    return Promise.all([pending ? null : balance]);
  }

  // lift the note sheet clear of the keyboard
  /* Let iOS know a keyboard is wanted, before anything asks for one.
   *
   * The keyboard does not come up for a programmatic focus() until the web
   * view's content view is first responder. Tapping a div does not do it;
   * tapping a text field does. So one invisible field takes focus and gives it
   * straight back, inside the first real touch — the only moment iOS allows a
   * focus to count. After that every focus() we make behaves like a second one.
   *
   * Distinct from the export's own primeKeyboard(), which focuses a ref that
   * only exists on a screen this build no longer has.
   */
  armKeyboardPrimer() {
    if (this._primerArmed || this.props.startStatic) return;
    this._primerArmed = true;

    let own = null;
    const target = () => {
      if (this._primerEl) return this._primerEl;
      if (own) return own;
      own = document.createElement('input');
      own.type = 'text';
      own.tabIndex = -1;
      own.setAttribute('aria-hidden', 'true');
      // has to be laid out to hold focus, so: transparent, one pixel, behind
      // everything, and ignoring taps of its own
      own.style.cssText =
        'position:fixed;top:0;left:0;width:1px;height:1px;opacity:0;border:0;' +
        'padding:0;margin:0;background:transparent;color:transparent;' +
        'pointer-events:none;z-index:-1';
      document.body.appendChild(own);
      return own;
    };

    const prime = () => {
      document.removeEventListener('touchstart', prime, true);
      document.removeEventListener('pointerdown', prime, true);
      const el = target();
      try {
        el.focus({ preventScroll: true });
        el.blur();
        console.log('[foxy] keyboard primed on first touch');
      } catch (e) {}
      setTimeout(() => { if (own && own.parentNode) own.remove(); }, 600);
    };

    // capture, so a handler that stops propagation cannot swallow it
    document.addEventListener('touchstart', prime, true);
    document.addEventListener('pointerdown', prime, true);
  }

  watchKeyboard() {
    const vv = window.visualViewport;
    if (!vv) return;
    const apply = () => {
      const gap = Math.max(0, window.innerHeight - vv.height - vv.offsetTop);
      document.documentElement.style.setProperty('--kb', gap + 'px');
    };
    vv.addEventListener('resize', apply);
    vv.addEventListener('scroll', apply);
    apply();
  }

  // Animate to the balance LNbits actually holds.
  //
  // The prototype's own moveBalance adds the payment to the previous figure,
  // which drifts the moment a fee or a rounding difference appears. Asking
  // first means the count-up ends on the real number every time.
  animateToLive(from, lane) {
    const W = window.FoxyWallet;
    if (!W || !W.connected) return false;
    const start = from || this.balNow();
    Promise.all([W.balanceSats(), W.rate().catch(() => null)]).then(([sats, rate]) => {
      const px = rate || this.px();
      this.setState({
        balSats: sats,
        balUsd: (sats / 1e8) * px,
        satUsd: px / 1e8,
        animFrom: start,
        animT: 0,
        animLane: lane || 'btc',
      });
      this.runBalanceAnim();
    }).catch(() => {});
    return true;
  }

  // leaving a split screen releases anything that queued up while it ran
  syncQueue() {
    const inSplit = this.SPLIT_SCREENS.indexOf(this.state.screen) >= 0;
    if (this._wasSplit && !inSplit) {
      clearTimeout(this._queueT);
      this._queueT = setTimeout(() => this.nextPaidScreen(), 420);
    }
    this._wasSplit = inSplit;
  }

  // Slide the screens.
  //
  // Direction comes from the navigation stack rather than from each call site:
  // the app pushes the previous screen onto `stack` when it goes forward and
  // pops it coming back, so a longer stack means forward and a shorter one
  // means back. Screens that swap without touching the stack don't animate,
  // which is right — those are replacements, not navigation.
  syncSlide() {
    const s = this.state;
    const prev = this._nav;
    const len = (s.stack || []).length;

    if (!prev) { this._nav = { screen: s.screen, len: len }; return; }
    if (prev.screen === s.screen) { this._nav = { screen: s.screen, len: len }; return; }

    const dir = len > prev.len ? 'foxyPushIn' : len < prev.len ? 'foxyPopIn' : null;
    this._nav = { screen: s.screen, len: len };
    if (!dir) return;

    try {
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
    } catch (e) {}

    const el = /** @type {HTMLElement | null} */ (document.querySelector('[data-foxy-theme]'));
    if (!el) return;
    el.style.animation = 'none';
    void el.offsetWidth;                    // forces the animation to restart
    el.style.animation = dir + ' .26s cubic-bezier(.32,.72,0,1) both';
    // anything measuring the page has to wait: while this runs, every element's
    // position is offset by the slide
    this._slideUntil = Date.now() + 300;
  }

  // the send screen's QR pane holds a live camera, not a picture of one
  /* Whether the page's own PASTE is what is on top across its whole face:
   * the middle and four points near the corners. Anything else there — a
   * card, a loader, a drawer, another screen — and Apple's control stays off. */
  pasteUncovered(el, box) {
    if (typeof document === 'undefined' || !document.elementFromPoint) return true;
    const at = [[.5, .5], [.1, .2], [.9, .2], [.1, .8], [.9, .8]];
    return at.every(([fx, fy]) => {
      const top = document.elementFromPoint(box.left + box.width * fx, box.top + box.height * fy);
      return !!top && (top === el || el.contains(top));
    });
  }

  syncPreview() {
    const W = window.FoxyWallet;
    if (!W || !W.startPreview) return;
    const sc = this.state.screen;
    /* Not under a card, or while an invoice is being checked: the camera is a
     * native view over the page, and it covered the top of PAYING ANOTHER …
     * USER, and read the same invoice again behind it. */
    /* Nor while what it read is being taken, or under a screen drawn over the
     * app. The scan screen is still the screen while a token is verified, so
     * the camera came straight back up and sat across VERIFYING ECASH, live,
     * for the four seconds the claim took. */
    /* Nor under the gate. Back from the background on a scan screen, the
     * camera sat live across SECURING YOUR CONNECTION: the gate is drawn on
     * the page and the pane is above it. */
    const R = window.FoxyReceiving, M = window.FoxyMoving, G = window.FoxyGate;
    const gated = !!(G && G.visible && G.visible());
    const covered = gated || !!this._takingToken
      || !!(R && R.visible && R.visible()) || !!(M && M.visible && M.visible())
      || !!(typeof document !== 'undefined' && document.getElementById('foxy-stage'));
    const wants = (sc === 'sendHow' || sc === 'sendScan') && !this._blockedEl && !this._checkingInvoice
      && !covered;
    /* Apple's paste button also sits over home's PASTE, so a token or an
     * invoice on the clipboard is one tap from home. */
    /* Nor under a screen drawn over the page. Apple's paste control is a
     * native view above the web view: with YOUR MONEY IS SAFE, YOU OWE THE
     * PAYER CHANGE or CONNECTING TO INVOICE up over home, it sat invisibly
     * across the right half of their button and ate the taps (in one
     * measurement the control sat at 193,663, 159x82, and the button at
     * 674–734). */
    const overlaid = covered || !!(typeof document !== 'undefined'
      && (document.getElementById('foxy-connecting') || document.getElementById('foxy-stage')));
    const wantsPaste = wants || (sc === 'home' && !this._blockedEl && !this.state.open0 && !overlaid);

    // A screen mid-slide is translated across the viewport, so measuring it now
    // would put the camera and the paste button wherever the animation happens
    // to be. Wait for it to land, then measure.
    const left = (this._slideUntil || 0) - Date.now();
    if ((wants || wantsPaste) && left > 0) {
      clearTimeout(this._slideWait);
      this._slideWait = setTimeout(() => this.syncPreview(), left + 20);
      return;
    }

    if (!wantsPaste && this._pasteOn) { this._pasteOn = false; W.stopPasteButton(); }
    if (!wants) {
      if (this._previewOn) { this._previewOn = false; W.stopPreview(); }
      /* A scan screen with no camera on it, and why. Once per reason. */
      const scanning = sc === 'sendHow' || sc === 'sendScan';
      const why = !scanning ? '' : this._blockedEl ? 'a card is up'
        : gated ? 'the connection screen is up'
        : covered ? 'what it read is being taken' : 'an invoice is being checked';
      if (why !== (this._noCameraWhy || '')) {
        this._noCameraWhy = why;
        if (why) console.log('[foxy] scan: ' + sc + ' has no camera because ' + why);
      }
    } else {
      this._noCameraWhy = '';
    }

    // Apple's paste button, laid over the page's own, so one tap is enough
    let pasteEl = wantsPaste ? document.querySelector('[data-foxy-paste="1"]') : null;
    /* A button measured mid-slide is off the screen, and the phone refuses to
     * put Apple's control there — the page's own paste then answers the tap,
     * and iOS asks again with its own bubble (seen in a phone log: refused at
     * x -288). Measured again in a moment instead. */
    const box = pasteEl && pasteEl.getBoundingClientRect();
    /* And only where the page's PASTE is the thing a finger would land on.
     *
     * The list of overlays above is a list, and every screen drawn over home
     * since it was written had to remember to be on it. GET DOLLARS was not:
     * Apple's control sat over the right half of its CLOSE and answered the
     * tap with a paste prompt. So were the Tor
     * gate's CONTINUE UNPROTECTED, the melt overlay and the PIN pad. Asking
     * the page what is actually on top at the button covers all of them and
     * whatever comes next. */
    if (pasteEl && box && !this.pasteUncovered(pasteEl, box)) {
      if (this._pasteOn) { this._pasteOn = false; W.stopPasteButton(); }
      pasteEl = null;
    }
    if (box && (box.left < 0 || box.width < 30)) {
      clearTimeout(this._slideWait);
      this._slideWait = setTimeout(() => this.syncPreview(), 120);
      pasteEl = null;
    }
    const pasteKey = pasteEl ? sc + ':' + Math.round(box.top) + ':' + Math.round(box.left) : '';
    if (pasteEl && (!this._pasteOn || this._pasteKey !== pasteKey)) {
      if (this._pasteOn) W.stopPasteButton();
      this._pasteKey = pasteKey;
      this._pasteOn = W.startPasteButton(pasteEl, text => this.acceptTarget(text));
    }
    if (!wants) return;

    // the pane is laid out by the template, so measure it rather than guess
    const el = document.querySelector('[data-qr-vignette]');
    if (!el) return;
    const r = el.getBoundingClientRect();
    const key = sc + ':' + Math.round(r.top) + ':' + Math.round(r.height);
    if (this._previewOn && this._previewKey === key) return;

    this._previewKey = key;
    /* Refused by the native side — measured mid-slide, off the screen — it
     * is forgotten and measured again in a moment, rather than believed to be
     * up: a refusal that stayed silent left the scan screen with no camera
     * until it was left and re-entered. */
    W._onPreviewRefused = (why) => {
      console.warn('[foxy] scan: the camera pane was refused (' + why + '); measuring again');
      this._previewOn = false;
      this._previewKey = '';
      clearTimeout(this._slideWait);
      this._slideWait = setTimeout(() => this.syncPreview(), 150);
    };
    this._previewOn = W.startPreview(el, text => {
      if (!this._previewOn) {
        console.log('[foxy] scan: a code came after the camera had been let go; ignored');
        return;
      }
      this._previewOn = false;
      W.stopPreview();
      let kind = '?';
      try { kind = W.classify(String(text || '').trim().replace(/^lightning:/i, '')); } catch (e) {}
      console.log('[foxy] scan: read ' + String(text || '').length + ' chars, a ' + kind);
      this.acceptTarget(text);
    });
    if (!this._previewOn) {
      console.warn('[foxy] scan: the camera pane could not be started ('
        + Math.round(r.width) + 'x' + Math.round(r.height) + ')');
    }
  }

  // one row per contact, for the template's loops
  contactRows() {
    const s = this.state;
    const list = (s.contacts || [])
      .slice()
      .sort((a, b) => String(a.name || a.handle)
        .localeCompare(String(b.name || b.handle), undefined, { sensitivity: 'base' }));
    return list.map(c => ({
      name: c.name || c.handle,
      handle: c.handle,
      ini: String(c.name || c.handle).charAt(0).toUpperCase(),
      tint: c.tint || 'var(--acc)',
      tap: () => this.setState(p => ({
        screen: 'amount',
        stack: p.stack.concat([p.screen]),
        flow: 'send',
        recipient: c.handle,
        recipientKind: 'email',
        asset: 'BITCOIN',
        network: 'LIGHTNING',
        payFrom: 'BITCOIN',
        amount: '',
        unit: 'USD',
      })),
    }));
  }

  // on launch, offer whatever payable thing is already on the clipboard
  /* ---- history and contacts ---- */

  /* What actually left the wallet for this transaction.
   *
   * A send of 500 that cost 2 in fees moved 502. Showing 500 means a week of
   * history cannot be reconciled against the balance, and nothing in the list
   * explains the difference.
   *
   * Incoming is unchanged: the mint's fee came out before the money arrived,
   * so the credited amount is already the true one. */
  /* The audit's arithmetic, in one place: the history screen draws it and
   * the HISTORY button rings for it, and the two must not disagree.
   *
   * Walked back from the balance now, newest first: a receive is taken off on
   * the way down and a send, with its fee, put back. Rows that moved nothing
   * yet — pending, failed, at risk, a bill still being collected, another
   * unit's ecash — carry the balance through unchanged. A payment whose
   * change has not come back cost its gross so far. */
  /* Part of the balance is with the mint and cannot be spent this minute.
   *
   * A swap that got no answer has its pieces held back until the mint says
   * whether it was made (04-lost-answers.js). The balance drops by that much
   * and a payment can only use the rest, with nothing on the screen to say
   * why — a phone showed only a small part of its balance for two minutes
   * while a top-up cut off by the network was being asked about. Said where
   * a person is about to pay: under the amount, and on the confirmation. ''
   * when nothing is held. */
  heldNote() {
    const W = window.FoxyWallet;
    const held = Math.round(Number(W && W.heldSats && W.heldSats()) || 0);
    if (!(held > 0)) return '';
    return this.stageMoney(held) + ' of your balance is currently pending with the mint. '
      + 'Please wait a minute and try again.';
  }

  /// The same, short, for under the balance on home. '' when nothing is held.
  heldPill() {
    const W = window.FoxyWallet;
    const held = Math.round(Number(W && W.heldSats && W.heldSats()) || 0);
    if (held > 0) return this.stageMoney(held) + ' pending with the mint';
    const back = this.recoveringSats();
    return back > 0 ? this.stageMoney(back) + ' being recovered from the mint' : '';
  }

  /// Fees the top-up swaps have cost at this mint, which no history row shows. 0 when none.
  topUpFeeSats() {
    const W = window.FoxyWallet;
    return Math.round(Number(W && W.topUpFeeSats && W.topUpFeeSats()) || 0);
  }

  /// Sats a swap took after Foxy was put away, still to be collected (recoveringSats). 0 when none.
  recoveringSats() {
    const W = window.FoxyWallet;
    return Math.round(Number(W && W.recoveringSats && W.recoveringSats()) || 0);
  }

  /* Why a payment that is `shortBy` sats over the balance cannot go: because
   * that much is held back with the mint, when it is — or '' when it is
   * simply more than this phone has, held or not. It is a block, the same as
   * MORE THAN YOUR BALANCE is: the amount goes red, there is no button that
   * sends, and the words say to wait, not to pay less. */
  heldBlocks(shortBy) {
    const W = window.FoxyWallet;
    const held = Math.round(Number(W && W.heldSats && W.heldSats()) || 0);
    const short = Math.round(Number(shortBy) || 0);
    return (held > 0 && short > 0 && short <= held) ? this.heldNote() : '';
  }

  histAudit() {
    const s = this.state;
    const balOf = new Map();
    // the payments a notice on the card is about, and what to call each
    const flagged = new Map();
    const balNow = Math.round(Number(s.balSats) || 0);
    let run = balNow, dueChange = 0, dueCount = 0, toShow = null, toShowSats = 0, toShowCount = 0;
    const seen = { in: 0, out: 0, inSats: 0, outSats: 0, skipped: 0, skippedSats: 0 };
    (s.fresh ? [] : (s.history || [])).forEach(g => g.items.forEach(t => {
      balOf.set(t, run);
      /* Change that came back over the link has a row of its own, and the
       * payment it is the rest of is already shown at its net. Counting both
       * counted the change twice: a 2,366 sat payment with 1 sat of change
       * was -2,365 and +1, and the card said DOES NOT ADD UP by that one sat
       * for the rest of the wallet's life. The row stays
       * in the list; it is the payment that carries the arithmetic. */
      const changeRow = t.dir === 'in' && (!!t.changeRow || /^(tap|req)-change-/.test(String(t.hash || '')));
      /* Pending means two different things. A receive that is pending has not
       * arrived: nothing moved. A payment that is pending has left — its
       * pieces are out of the balance — and is only waiting to be confirmed.
       * Skipping both left a payment whose answer never came (the payer was
       * put away mid-tap) out of the sum, and the card said DOES NOT ADD UP
       * by exactly that payment. */
      const waitingIn = !!t.pending && t.dir === 'in';
      const moved = !changeRow && !waitingIn && !t.failed && !t.atRisk && !t.split && !(t.unit && t.unit !== 'sat');
      const owedBack = t.dir !== 'in' && t.changeState === 'owed' ? (Number(t.changeSats) || 0) : 0;
      if (owedBack > 0 || (t.dir !== 'in' && t.changeState === 'never came' && Number(t.changeSats) > 0)) {
        dueChange += Number(t.changeSats) || 0;
        dueCount += 1;
      }
      if (owedBack > 0 || (t.dir !== 'in' && t.changeState === 'never came' && Number(t.changeSats) > 0)) flagged.set(t, 'Change not collected');
      // change made here for a payer and still here, as a code on its payment
      if (t.dir === 'in' && t.changeState === 'not handed' && Number(t.changeSats) > 0 && t.token) {
        flagged.set(t, 'Change to hand over');
        if (!toShow) toShow = t;
        toShowSats += Number(t.changeSats) || 0;
        toShowCount += 1;
      }
      if (moved) {
        const by = t.dir === 'in' ? (Number(t.sats) || 0) : this.txTotalOut(t) + owedBack;
        run += t.dir === 'in' ? -by : by;
        if (t.dir === 'in') { seen.in += 1; seen.inSats += by; } else { seen.out += 1; seen.outSats += by; }
      } else {
        seen.skipped += 1; seen.skippedSats += Number(t.sats) || 0;
      }
    }));
    const whole = !!s.historyComplete && !s.fresh && (s.history || []).length > 0;
    /* Less what is held back for a swap the mint has not answered. Those
     * sats are out of the balance on purpose until the mint says whether the
     * swap was made, and the card names them — so they are accounted for, not
     * missing. A top-up cut off by a network that dropped held 32,768 back
     * for two minutes, and for those two minutes the card and the red ring
     * said DOES NOT ADD UP about money Foxy knew the whereabouts of. */
    const W0 = window.FoxyWallet;
    const held = Math.round(Number(W0 && W0.heldSats && W0.heldSats()) || 0);
    // and what a swap took after Foxy was put away, to be collected on the next connection
    const back = this.recoveringSats ? this.recoveringSats() : 0;
    // and the fees the top-ups cost at this mint, which no row carries
    const fees = this.topUpFeeSats ? this.topUpFeeSats() : 0;
    const off = whole ? Math.round(run) + held + back + fees : 0;
    /* Said in the log when it changes, with what it was worked out from: a
     * card that says DOES NOT ADD UP and a diary that cannot say why is a
     * report nobody can act on. */
    const sig = [balNow, off, dueChange, toShowCount, seen.in, seen.out, seen.skipped].join('|');
    if (whole && sig !== this._auditSig) {
      this._auditSig = sig;
      console.log('[foxy] audit: balance ' + balNow + ', off by ' + off + '; ' + seen.in + ' in for ' + seen.inSats
        + ', ' + seen.out + ' out for ' + seen.outSats + ', ' + seen.skipped + ' not counted (' + seen.skippedSats
        + ' sats: pending, failed, at risk, a bill, another unit); change due here ' + dueChange
        + ', change to hand over ' + toShowSats);
      /* And when it does not add up, the rows it was worked out from, newest
       * first: which way, how much, the fee, and what kind of row. Amounts are
       * already in this log; this puts them in one place, in order. */
      if (off !== 0) {
        const rows = [];
        (s.history || []).forEach(g => g.items.forEach(t => {
          rows.push((t.dir === 'in' ? '+' : '-') + (Number(t.sats) || 0)
            + (Number(t.fee || t.feeSats) > 0 ? 'f' + Number(t.fee || t.feeSats) : '')
            + (Number(t.grossSats) > 0 ? 'g' + Number(t.grossSats) : '')
            + (Number(t.changeSats) > 0 ? 'c' + Number(t.changeSats) : '')
            + (t.changeState ? '(' + t.changeState + ')' : '')
            + (t.pending ? 'P' : '') + (t.failed ? 'F' : '') + (t.atRisk ? 'R' : '') + (t.split ? 'S' : '')
            + (t.memo === 'opening' ? 'O' : '') + (t.changeRow ? 'C' : '') + (Number(t.sats) < 10 ? '<' + String(t.hash || '').slice(0, 14) + '>' : ''));
        }));
        for (let i = 0; i < rows.length; i += 20) console.log('[foxy] audit rows ' + i + ': ' + rows.slice(i, i + 20).join(' '));
      }
    }
    return { balOf, balNow, run, whole, off, held, dueChange, dueCount, toShow, toShowSats, toShowCount, flagged };
  }

  txTotalOut(t) {
    const sats = Number((t && t.sats) || 0);
    if (!t || t.dir === 'in') return sats;
    return sats + Math.max(0, Number(t.fee || t.feeSats || 0));
  }

  txWhen(t) {
    const v = t.at;
    if (!v) return new Date();
    if (typeof v === 'number') return new Date(v * (v > 1e11 ? 1 : 1000));
    const d = new Date(v);
    return isNaN(d.getTime()) ? new Date() : d;
  }

  /* When, as the phone's own clock would say it.
   *
   * The time of day, in the phone's time zone; and once a payment is more
   * than twenty-four hours old, the date in front of it, two digits for the
   * month and two for the day: `2:45 PM`, then `10/03 2:45 PM`. It was "3h
   * ago", which has to be worked back to a time by whoever reads it and is
   * wrong the moment the screen has been open a while. A year is added only
   * when it is not this one. */
  txLabel(d, now) {
    if (now - d < 86400000) return this.txClock(d);
    return this.txDay(d, now) + ' ' + this.txClock(d);
  }
  /* The date and the time, always: the detail screen has the room. */
  txStamp(d, now) {
    return this.txDay(d, now || new Date()) + ' ' + this.txClock(d);
  }
  txDay(d, now) {
    const two = (n) => (n < 10 ? '0' : '') + n;
    return two(d.getMonth() + 1) + '/' + two(d.getDate())
      + (d.getFullYear() !== now.getFullYear() ? '/' + two(d.getFullYear() % 100) : '');
  }
  /* Twelve hours or twenty-four, as the phone is set. The phone says which
   * (`__foxyClock24`, FoxyWebView.swift): the page's own locale knows the
   * region's habit and not the switch in Settings. */
  txClock(d) {
    const pref = typeof window !== 'undefined' ? /** @type {any} */ (window).__foxyClock24 : undefined;
    const h = d.getHours(), m = d.getMinutes();
    const mm = (m < 10 ? '0' : '') + m;
    if (pref === true) return (h < 10 ? '0' : '') + h + ':' + mm;
    if (pref === false) return ((h % 12) || 12) + ':' + mm + (h < 12 ? ' AM' : ' PM');
    try { return d.toLocaleTimeString([], { hour: 'numeric', minute: '2-digit' }); }
    catch (e) { return ((h % 12) || 12) + ':' + mm + (h < 12 ? ' AM' : ' PM'); }
  }

  CARD_MEMOS = { 'card': 'From a card', 'to card': 'To card', 'from card': 'From card', 'card, not completed': 'Card, not completed' };

  // best guess at who the other side was: a lightning address if one shows up
  // in the payment's metadata, otherwise the memo, otherwise the rail
  txWho(t) {
    const hay = (t.memo || '') + ' ' + JSON.stringify(t.extra || {});
    const m = hay.match(/[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i);
    if (m) return m[0];
    // the row clearing history leaves behind: the balance that was there
    if (t.memo === 'opening') return 'Balance carried forward';
    // the wallet's own words for money that moved by a card (08a-flashcard.js)
    if (this.CARD_MEMOS[t.memo]) return this.CARD_MEMOS[t.memo];
    if (t.memo && t.memo.trim() && t.memo !== 'Foxy') return t.memo.trim();
    return t.dir === 'in' ? 'Received' : 'Sent';
  }

  loadHistory() {
    const W = window.FoxyWallet;
    if (!W || !W.connected) return;
    // nor the history, which is read mint by mint (`refreshBalance`)
    if (W.awayClaiming && W.awayClaiming()) {
      if (!this._histWhenHome) {
        this._histWhenHome = W.whenHome().then(() => { this._histWhenHome = null; this.loadHistory(); });
      }
      return;
    }
    // change made and never handed over belongs on its payment's entry
    W._onHistoryChanged = () => { clearTimeout(this._histAgainT); this._histAgainT = setTimeout(() => this.loadHistory(), 50); };
    // change that was being shown as a code has been taken: the screen showing it comes down
    W._onChangeTaken = () => { if (this.hideStage) this.hideStage('changeStuck'); this.refreshBalance(); };
    /* While a payment here still shows change to hand over, ask again every
     * fifteen seconds whether it has been taken — the mint is the only one
     * who can say a payer scanned it. One timer, renewed here and nowhere
     * else, and not renewed once nothing is owed or Foxy is not in front. */
    clearTimeout(this._owedPollT);
    try {
      const owing = (this.state.history || []).some(g => g.items.some(t => t.dir === 'in' && t.changeState === 'not handed'));
      if (owing && !document.hidden) this._owedPollT = setTimeout(() => this.loadHistory(), 15000);
    } catch (e) {}
    try { if (W.repairOwedChange) W.repairOwedChange(); } catch (e) {}
    // and entries from before prices were kept stop moving with bitcoin
    try { if (W.stampRates) W.stampRates(); } catch (e) {}
    W.transactions(500).then(all => {
      // One mint at a time: a balance belongs to a mint, so its history should
      // too. Entries written before mints were recorded carry none, and show
      // everywhere rather than vanishing.
      const here = String(W.mintUrl || '').replace(/\/+$/, '');
      const list = all.filter(x => !x.mint || x.mint === here);

      // history already showing money in counts, so the prompt survives a
      // relaunch rather than waiting for the next payment
      if (all.some(x => x.dir === 'in')) this.setState({ everReceived: true });
      const now = new Date();
      const yest = new Date(now.getTime() - 86400000);
      const buckets = { TODAY: [], YESTERDAY: [], EARLIER: [] };
      const seen = {};

      list.forEach(t => {
        const d = this.txWhen(t);
        const key = d.toDateString() === now.toDateString() ? 'TODAY'
          : d.toDateString() === yest.toDateString() ? 'YESTERDAY' : 'EARLIER';
        const meta = W.tagsFor(t.hash) || {};
        const who = meta.to || this.txWho(t);
        buckets[key].push({
          name: who,
          /* The detail screen gets the whole address where there is one.
           *
           * `who` is elided to seventeen characters for the tile, which is all
           * the room a row has. The detail screen has a line that wraps, and an
           * address a person cannot read in full cannot be checked against a
           * block explorer — which is the only reason to look at it there. On chain writes `address`; every other rail
           * has no such field and falls back to what it always showed. */
          party: meta.address || who,
          note: meta.note || '',
          hash: t.hash,
          // the card an entry is for (26f-flashcard.js), so one card's entries can be shown on their own
          card: t.card || '',
          // and what the wallet called it, which is what a card's own list names it by
          memo: t.memo || '',
          dir: t.dir,
          sats: t.sats,
          fee: t.feeSats,
          // another unit's ecash: its own amount and fee, never shown as sats
          unit: t.unit && t.unit !== 'sat' ? t.unit : '',
          amount: t.amount,
          feeAmount: t.feeAmount,
          rail: 'Lightning',
          time: this.txLabel(d, now),
          // the same moment with its date, for the detail screen
          stamp: this.txStamp(d, now),
          /* A token this wallet sent is pending (amber) until it is known to be
           * redeemed: its text is kept until then (forgetClaimedToken). */
          pending: !t.settled || (t.dir === 'out' && meta.to === 'ecash' && !!meta.token),
          failed: t.state === 'failed',
          /* Taken on trust while both phones were offline, and not swapped in
           * yet: the payer can still spend their copy back. Read off the log
           * entry the arrival wrote, and true only while it is still waiting —
           * the claim settles the same entry, and a settled one is ordinary
           * money (20-helpers.js, `trusted`). */
          atRisk: !!t.trusted && !t.settled && t.state !== 'failed',
          /* Refused over the link with nothing sent back, or locked to a
           * phone that then refused it: seen by them, not safe yet. */
          highRisk: !!t.highRisk,
          /* An over-payment and its change are one transaction, and the list
           * shows the net. These carry the other two figures through to the
           * detail screen, which is where a person looks when a payment did not
           * match what they expected — and what they send in a report about it. Absent on every ordinary payment. */
          grossSats: Number(t.grossSats) || 0,
          changeSats: Number(t.changeSats) || 0,
          changeState: t.changeState || '',
          // dollars per bitcoin when this settled; its dollar figures come from this and nothing else
          rate: Number(t.rate) || 0,
          token: meta.token || '',
          // the same text after it was claimed, kept to be shown; and the change this phone made for a payer
          kept: meta.kept || '',
          changeToken: meta.changeToken || '',
          // change that came back for a payment: a row of its own, already netted on that payment
          changeRow: !!meta.change || /^(tap|req)-change-/.test(String(t.hash || '')),
          /* This payment crossed a Bluetooth link. Its token may be shown again
           * to the same person; it may not be taken back. */
          handedByTap: meta.handed === 'tap',
          /* The mint's word for where the money went on chain: `txid:vout` from
           * the NUT-30 melt quote, kept as the transaction id alone. Empty
           * until the mint has broadcast — it answers `outpoint: null` before
           * that — and empty for every other rail. */
          txid: meta.txid || '',
          /* A Lightning payment's preimage, when the mint gave one: the proof
           * that the invoice was paid, for the detail screen. */
          preimage: t.preimage || '',
          // and on a receive, the payment hash of the invoice this phone made
          payHash: t.payHash || '',
        });
        // Anyone address-shaped is saved to the book on sight, once.
        //
        // Contacts used to be the book plus whatever history happened to
        // contain, recomputed on every load — so clearing history also
        // cleared half the contact list. Writing them through means the two
        // are independent: clear history and the names stay; clear contacts
        // and history does not put them back.
        if (who.indexOf('@') > 0 && !seen[who.toLowerCase()]) {
          seen[who.toLowerCase()] = true;
          if (W.remember && !this._contactsCleared) W.remember(who, who.split('@')[0]);
        }
      });

      // a bill still being collected sits at the top, above settled payments.
      // Reconcile first: these transactions are exactly what tells us a share
      // has landed, and a watch may have died without noticing.
      if (W.splitReconcile && !this._spReconciling) {
        this._spReconciling = true;
        W.splitReconcile().then(n => {
          this._spReconciling = false;
          /* Always, not only when this run marked something: the collecting
           * screen's tally is a copy of the ledger's, and this is where the
           * two are put back together whoever settled the row (spSyncPaid). */
          this.spSyncPaid();
          if (n) { this.refreshBalance(); this.loadHistory(); }
        }).catch(() => { this._spReconciling = false; });
      }
      const sp = W.splitPending && W.splitPending();
      // a finished split is kept until its screen is dismissed; it does not
      // belong in history claiming 0 of 3 still owed
      if (sp && !sp.done) {
        const owed = sp.rows.filter(r => !r.paid).length;
        buckets.TODAY.unshift({
          name: 'Split \u2014 ' + owed + ' of ' + sp.rows.length + ' still owed',
          party: 'Split the bill',
          note: '',
          hash: 'split-pending',
          dir: 'in',
          sats: sp.rows.filter(r => !r.paid).reduce((a, r) => a + (r.sats || 0), 0),
          fee: 0,
          rail: 'Lightning',
          time: 'Collecting',
          pending: true,
          split: true,
          token: '',
        });
      }

      const history = ['TODAY', 'YESTERDAY', 'EARLIER']
        .map(label => ({ label: label, items: buckets[label] }))
        .filter(g => g.items.length);

      // saved addresses first, then anything the payments implied
      const book = (W.book() || []).map(c => ({
        name: c.name, handle: c.handle,
        tint: 'var(--acc)',
      }));
      // the book is the whole list now; remember() above has written to it
      const merged = W.book().map((c, i) => ({
        name: c.name, handle: c.handle,
        tint: ['var(--acc)', '#5B45D0', '#0E9E93', '#D4409A', '#2E7CF6', '#E0602E'][i % 6],
      }));

      // Everything settled that has not been announced yet. Incoming ones queue
      // up and are shown one at a time, each waiting for its own dismissal, so
      // coming back to four payments means four confirmations in order rather
      // than one screen standing in for all of them.
      /* A mint switch is not a wave of arrivals.
       *
       * _seenTx is seeded by the first history load, and everything after is
       * a new arrival. Switching mints loads a different mint's transactions,
       * none of which are in _seenTx — so all of them were announced. Eight
       * confirmation screens in a row, each waiting to be dismissed.
       *
       * The seed belongs to a mint. The first load on a mint seeds quietly,
       * however many mints came before it. */
      const W0 = window.FoxyWallet;
      const mintNow = (W0 && W0.mintHost && W0.mintHost()) || '';
      if (this._seededFor !== mintNow) {
        this._seenSeeded = false;
        this._seededFor = mintNow;
      }

      const fresh = [];
      list.forEach(t => {
        /* Money written down and not yet swapped in, which the person has
         * already been shown.
         *
         * An offline receive tells them at the moment it arrives — the amount
         * is on screen, and the row goes into history as PENDING, which is
         * true. Settling it later changes nothing they need to act on: the
         * ecash was locked to this phone from the start, their own twelve words
         * open it, and `forwardLocked` lets them spend it before it settles.
         * Nothing was ever at risk and nothing was ever unavailable.
         *
         * Skipped outright, the pending row was never marked seen — so the
         * moment the route came back, settling it read as a brand-new payment
         * and threw a confirmation screen over whatever they were doing. Three
         * of them in nine seconds, for payments they had already been told
         * about. Marked as seen on the way past, the settle is the
         * bookkeeping it always was.
         *
         * A payment that arrives while the app is closed is not this: it is
         * never pending on a screen anybody is looking at, so it lands settled,
         * has never been seen, and is announced exactly as before. */
        if (!t.settled) { this.txIsNew(t.hash); return; }
        // the balance carried forward past a cleared history is not a payment
        if (t.memo === 'opening') { this.txIsNew(t.hash); return; }
        /* Change handed back to somebody who over-paid is the tail of a payment
         * that has already been confirmed, not a payment of its own. It was
         * announced as one: 3 sats sold, a confirmation for 4, and then a
         * second for 1 sat withdrawn. It is still
         * in the list, where it belongs; it just does not interrupt anybody. */
        const tags = W.tagsFor(t.hash) || {};
        if (tags.change) { this.txIsNew(t.hash); return; }
        /* Money moved between this phone and a card somebody was holding to
         * it: a top-up, a withdrawal, a renewal, a lost card taken back. The
         * FLASHCARD screens say how each went, at the moment it did, and a
         * confirmation screen a second later would say it twice. A payment
         * taken from a card is not this: it is tagged apart and announced like
         * any other. */
        if (tags.to === 'card') { this.txIsNew(t.hash); return; }
        /* Still on its way to somebody. The entry exists because the token
         * does; the payment has not happened yet, and announcing it is how the
         * payer came to see a confirmation of withdrawal while the receiver was
         * still reading a card. `requestDelivered` clears
         * the mark and announces it at the moment it is true. */
        if (tags.inflight) return;
        // another unit's receive is confirmed where it was taken; this screen counts sats
        if (this.txIsNew(t.hash) && !(t.unit && t.unit !== 'sat')) fresh.push(t);
      });
      this._seenSeeded = true;

      // oldest first: they arrived in that order, so they should be shown in it.
      // Sent payments queue too — one you made from elsewhere deserves the same
      // confirmation as one that arrived.
      if (fresh.length) {
        this._paidQueue = (this._paidQueue || []).concat(fresh.slice().reverse());
        this.nextPaidScreen();
      }

      this.setState({
        book: W.book(),
        history: history,
        // five hundred is the most kept; fewer means this is every entry there is
        historyComplete: all.length < 500,
        txs: buckets.TODAY.concat(buckets.YESTERDAY).slice(0, 3).map(t => ({
          name: t.name, dir: t.dir, sats: t.sats, time: t.time, rail: 'LIGHTNING', fee: t.fee || 0,
          // what the detail screen names the network by
          hash: t.hash, memo: t.memo,
        })),
        contacts: merged,
      });
    }).catch(() => {});
  }

  /* ---- split the check ---- */

  // one real invoice per payer, watched from the moment they are made
  spStart() {
    const W = window.FoxyWallet;
    if (!W || !W.connected) { this.toast('No wallet connected.', true); return; }

    // Same guard as sending. Asking the mint for invoices tells it someone is
    // collecting, so it waits for Tor like every other request.
    const G = window.FoxyGate;
    if (G && G.quiet) {
      return G.quiet().then(ok => {
        if (!ok) { this.toast('Tor is reconnecting. Try again in a moment.', true); return; }
        console.log('[foxy] split invoices |', G.stamp());
        this.spMakeInvoices();
      });
    }
    return this.spMakeInvoices();
  }

  spMakeInvoices() {
    const W = window.FoxyWallet;
    const sh = this.spSharesArr();
    const n = this.spOthers();
    const px = this.px();
    if (!px) { this.showPriceError(); return; }

    this.spStopWatch();
    this.setState({ spInvoices: [], spPaid: [], spErr: '' });

    const jobs = [];
    for (let i = 0; i < n; i++) {
      const sats = Math.round((sh[i + 1] / 100) / px * 1e8);
      jobs.push(W.invoice(sats, 'Split ' + (i + 2) + ' of ' + this.spWaysN(), W.expiry.split));
    }

    Promise.all(jobs).then(list => {
      // a share already paid by tap while these were being made stays paid
      const paidBy = (this.state.spPaid || []).slice();
      // on disk before anything else: these are payable invoices in other
      // people's hands, and losing track of them is the whole problem
      W.splitSave({
        ways: this.spWaysN(),
        total: this.state.spTotal,
        at: Date.now(),
        /* The mint that issued these, as the invoices say it. `splitSave`
         * used to fill this in from wherever the wallet was at the moment of
         * saving, and a late claim had it at another mint for those seconds:
         * the bill was filed against a mint that had never heard of its
         * quotes, and the check on return refused to ask the one that had. */
        mint: (list[0] && list[0].mint) || undefined,
        rows: list.map((inv, k) => ({
          hash: inv.hash, bolt11: inv.bolt11, sats: inv.sats,
          label: 'Split ' + (k + 2) + ' of ' + this.spWaysN(), paid: !!paidBy[k],
        })),
      });
      // the collecting screen is the confirmation for these — mark them known
      // so neither the socket nor the history sweep announces them separately
      this._seenTx = this._seenTx || {};
      list.forEach(inv => { this._seenTx[inv.hash] = true; });
      this.setState({ spInvoices: list.map(x => x.bolt11) });
      // an hour, as resumeSplitNow watches them: the second of two timeoutMs
      // keys, the first of which (the invoice's own expiry) never took effect
      this._spWatching = list.map(inv => inv.hash).join(',');
      this._spWatchedAt = Date.now();
      this._spStops = list.map((inv, i) => paidBy[i] ? (() => {})
        : W.watch(inv.hash, () => { this.spMarkPaid(i, inv.hash); this.spPaidOnScreen(i); }, { timeoutMs: 3600000 }));
      // and watched again before that hour is up: a bill on a table outlasts it
      this.splitWatchLater();
    }).catch(e => {
      this.setState({ spErr: W.reason(e) });
      this.toast(W.reason(e), true);
    });
  }

  /* One payer's share in sats, by the same sum the invoices are made with, so
   * a request made before the invoice asks for the same figure. */
  spShareSats(idx) {
    const sh = this.spSharesArr();
    const px = this.px();
    const cents = Number(sh[(Number(idx) || 0) + 1]) || 0;
    if (!px || !(cents > 0)) return 0;
    return Math.round((cents / 100) / px * 1e8);
  }

  spMarkPaid(i, hash) {
    const W = window.FoxyWallet;
    if (hash) W.splitMarkPaid(hash);
    /* And its invoice stops being asked about. A share paid in ecash leaves a
     * Lightning invoice nobody will ever pay, and its watcher went on asking
     * the mint every second and a half, over Tor, for an hour — under every
     * payment made after it. */
    this.spStopOne(i, hash);
    const n = this.spOthers();
    this.setState(p => {
      const paid = (p.spPaid || []).slice();
      while (paid.length < n) paid.push(false);
      paid[i] = true;
      const done = paid.slice(0, n).every(Boolean);
      return { spPaid: paid, screen: done && p.screen === 'spWaiting' ? 'spAllPaid' : p.screen };
    });
    if (this.haptic) this.haptic('success');
    this.refreshBalance();
    this.loadHistory();
  }

  /* A share paid over the tap while its QR was up: on to the next payer.
   *
   * The screen stayed on the paid share, its code card came down, and the
   * radio re-armed for the same share — the next person had to be stepped to
   * by hand. Only from the payer screen showing that very
   * share; a share opened from the waiting list goes back there instead
   * (requestPaidHere). With every share paid it is EVERYONE HAS PAID. */
  spAdvanceAfterPaid(idx, how) {
    const s = this.state;
    if (s.screen !== 'spPayer' || Number(s.spIdx || 0) !== Number(idx)) return;
    const n = this.spOthers();
    const paid = this.spPaidArr();
    let next = -1;
    for (let i = 0; i < n; i++) if (!paid[i]) { next = i; break; }
    // a fresh screen arms afresh
    this._tapPaidHere = false;
    console.log('[foxy] split: share ' + (idx + 1) + ' paid ' + (how || 'by tap') + '; '
      + (next < 0 ? 'everyone has paid' : 'on to payer ' + (next + 1)));
    this.setState(next < 0
      ? { screen: 'spAllPaid', spFromWaiting: false, spCopied: -1, spShared: -1, tapShownCode: '', tapRecvStage: '' }
      : { spIdx: next, spFromWaiting: false, spCopied: -1, spShared: -1, tapShownCode: '', tapRecvStage: '' });
  }

  /* What the ledger says has landed, into the screen's own tally.
   *
   * spPaid is the only thing the collecting screen draws its ticks from, and
   * until now only the per-invoice watcher wrote it (spMarkPaid). But a share
   * can settle by a different path entirely: splitReconcile, which every
   * history load runs, asks the mint about any row the ledger cannot answer
   * and claims one the mint reports PAID. When that got there first — as it
   * does whenever the watcher is late, has timed out, or lost its circuit —
   * the money was in the balance and in history, the ledger row said paid,
   * and the screen the person was actually looking at still read PENDING,
   * 0 of 3, for as long as they left it open.
   *
   * So the screen no longer depends on which path settled a share. Nothing is
   * set here that the ledger does not already say, and a tally that has not
   * moved sets no state at all rather than drawing the screen again on every
   * history load. */
  spSyncPaid() {
    const W = window.FoxyWallet;
    /* The record whether or not it is finished (`splitRecord`). It was
     * `splitPending`, which answers nothing once every row is paid: the last
     * share settled by the sweep was the one share this could never tick. */
    const led = W && (W.splitRecord ? W.splitRecord() : (W.splitPending && W.splitPending()));
    if (!led || !led.rows) return;
    const n = this.spOthers();
    const paid = this.spPaidArr();
    /* A finished record stays on file until its all-paid screen is dismissed,
     * so it may be an earlier bill's. Only the bill this screen is collecting
     * ticks anything: its rows are these invoices. */
    const finished = led.rows.every(r => r.paid);
    const mine = this.state.spInvoices || [];
    const here = (r, i) => !finished || (!!r.bolt11 && r.bolt11 === mine[i]);
    const landed = [];
    led.rows.slice(0, n).forEach((r, i) => { if (r.paid && !paid[i] && here(r, i)) { paid[i] = true; landed.push(i); } });
    if (!landed.length) return;
    const done = paid.every(Boolean);
    this.setState(p => ({
      spPaid: paid,
      // the all-paid screen belongs to the person still watching it collect
      screen: done && p.screen === 'spWaiting' ? 'spAllPaid' : p.screen,
    }));
    if (done && this.haptic) this.haptic('success');
    landed.forEach(i => this.spPaidOnScreen(i));
  }

  /* A share paid by its invoice while its own screen was up: the screen says
   * so, as it does for a share paid over the tap (`spAdvanceAfterPaid`).
   *
   * It did nothing. The tally was marked and the payer's code stayed where it
   * was, so the person holding the phone saw no sign of the payment until
   * they went to the list. Back to the list when the share was opened from
   * it, otherwise on to the next payer; with every share paid it is EVERYONE
   * HAS PAID. */
  spPaidOnScreen(idx) {
    const s = this.state;
    if (s.screen !== 'spPayer' || Number(s.spIdx || 0) !== Number(idx)) return;
    if (s.spFromWaiting) { this.setState({ screen: 'spWaiting', spFromWaiting: false }); return; }
    this.spAdvanceAfterPaid(idx, 'by its invoice');
  }

  /* Pick up a bill left half-collected.
   *
   * Rewatches only the invoices nobody has paid yet. The watchers are the
   * point: without them a payment lands at the mint and this wallet never
   * claims it.
   */
  /* Stop collecting a bill, from the collecting screen's basket.
   *
   * The record is what makes a bill show as still being collected; removing
   * it is the whole of stopping. What it is NOT is a refund or a cancellation
   * of anything at the mint: a share already paid is in history and stays
   * there, and a share paid after this still reaches the wallet, because the
   * invoice stays on the pending list the quote sweep checks on every connect
   * and return (15-receiving.js). It simply stops having a screen of its own.
   *
   * Asked first, because a half-collected bill cannot be brought back: the
   * rows, the names and who has paid are only in this record. */
  spDiscard() {
    const W = window.FoxyWallet;
    const s = (W && W.splitPending) ? W.splitPending() : null;
    const open = s && s.rows ? s.rows.filter(r => !r.paid).length : 0;
    this.blockedCard('splitDiscard', {
      tone: 'warn',
      title: 'STOP COLLECTING THIS BILL?',
      reason: open
        ? open + ' share' + (open === 1 ? '' : 's') + ' still owed. This screen goes away and the bill '
          + 'stops being tracked. Shares already paid stay in your history, and if someone pays '
          + 'their share later it still reaches your wallet \u2014 you just will not see it here.'
        : 'This screen goes away. Everything collected stays in your history.',
      retry: 'STOP COLLECTING',
      go: () => this.spDiscardNow(),
      shut: { label: 'KEEP COLLECTING' },
    });
  }

  spDiscardNow() {
    const W = window.FoxyWallet;
    clearTimeout(this._spResumeT);
    this._spWatching = null;
    this._spWatchedAt = 0;
    if (W && W.splitClear) W.splitClear();
    console.log('[foxy] the bill being collected was stopped by hand');
    this.setState({
      screen: 'home', stack: [], flow: '',
      amount: '', asset: '', unit: 'USD', recipient: '', emailDraft: '',
      spPaid: [], spInvoices: [], spAssigns: [], spShares: null, spErr: '',
    });
  }

  resumeSplit(force) {
    const W = window.FoxyWallet;
    // between mints, or before the wallet script is up: come back to it, since
    // an unwatched share is a payment that lands at the mint and stays there
    if (!W) { this.splitWatchLater(); return; }
    // Settle what the watcher missed before deciding what to watch. This asks
    // the mint for anything the ledger cannot answer, so it is async; the
    // rest runs once it knows.
    const go = W.splitReconcile ? W.splitReconcile() : Promise.resolve(0);
    go.then(() => this.resumeSplitNow(force)).catch(() => this.resumeSplitNow(force));
  }

  /* Watch the open shares again, before the watchers time out.
   *
   * W.watch gives up after an hour (timeoutMs below), and nothing re-armed it:
   * a bill left collecting on the table stopped being watched at the hour mark
   * and every share paid after that landed at the mint unclaimed. The same
   * shape as the on-chain watcher that stopped asking — a timer that ends
   * without leaving another behind. Well
   * inside the hour, so a watch is always replaced rather than mourned. */
  SPLIT_REWATCH_MS = 1500000;

  splitWatchLater() {
    clearTimeout(this._spResumeT);
    /* Forced: this timer is the whole reason the watchers outlive the hour
     * they are given, so its pass always arms a new set. The wake and
     * mint-connect passes are the ones that must not. */
    this._spResumeT = setTimeout(() => this.resumeSplit(true), this.SPLIT_REWATCH_MS);
  }

  resumeSplitNow(force) {
    const W = window.FoxyWallet;
    clearTimeout(this._spResumeT);
    // the wallet cannot say yet whether a bill is open: come back to it
    if (!W || !W.splitPending) { this.splitWatchLater(); return; }
    const s = W.splitPending();
    /* No bill half-collected needs no timer: one cannot appear on its own,
     * since spStart both makes the invoices and watches them. */
    if (!s) return;
    if (s.done) {
      // settled while the app was away; nothing to collect
      console.log('[foxy] the pending split is already settled');
      return;
    }
    // shares still owed: stay watched past the hour the watchers last
    this.splitWatchLater();
    const open = s.rows.filter(r => !r.paid);
    console.log('[foxy] resuming split:', open.length, 'of', s.rows.length, 'still owed');
    /* Same as when the split was created: the collecting screen is the
     * confirmation for these, so nothing else should announce them. Without
     * this the history sweep saw three unknown arrivals on every pass and
     * raised a confirmation for each, over and over. */
    this._seenTx = this._seenTx || {};
    s.rows.forEach(r => { if (r.hash) this._seenTx[r.hash] = true; });
    /* Already watching exactly these shares, and nowhere near the hour a
     * watcher lasts: leave them running.
     *
     * A watcher's own back-off is measured from when it was armed — one ask
     * every two seconds for the first two minutes, then ten, then thirty
     * (FoxyWallet.watch). Re-arming restarted that clock, and this runs on
     * every return to the foreground and every mint connect, so each return
     * put every open share back into the two-second phase. Nine returns in
     * five minutes on a phone held three invoices there the whole time: 165
     * mint requests over Tor in seven minutes for one bill on a table, each
     * its own circuit round trip (seen in a device log).
     *
     * The hour is still covered and nothing stops asking: splitWatchLater
     * above has already set the next pass at SPLIT_REWATCH_MS, well inside
     * it, and that pass passes force — it exists to replace the watchers and
     * always does. A share being paid changes which shares are open, which
     * arms a new set here too. A wake after a long sleep, where the watchers
     * may have run out while the app was away, ages out of the test below. */
    const want = open.map(r => r.hash).join(',');
    if (!force && this._spStops && this._spStops.length && this._spWatching === want
        && Date.now() - (this._spWatchedAt || 0) < this.SPLIT_REWATCH_MS) {
      console.log('[foxy] split: the open shares are already watched');
      return;
    }
    this.spStopWatch();
    this._spWatching = want;
    this._spWatchedAt = Date.now();
    this._spStops = open.map(r => W.watch(r.hash, () => {
      W.splitMarkPaid(r.hash);
      this.refreshBalance();
      this.loadHistory();
    }, { timeoutMs: 3600000 }));
  }

  /* Back into the collecting screen from the history row. */
  openPendingSplit() {
    const W = window.FoxyWallet;
    const s = W.splitPending && W.splitPending();
    if (!s) { this.toast('That split is settled.'); this.loadHistory(); return; }
    this.setState(p => ({
      screen: 'spWaiting',
      stack: p.stack.concat([p.screen]),
      spWays: String(s.ways),
      spTotal: s.total,
      spInvoices: s.rows.map(r => r.bolt11),
      spPaid: s.rows.map(r => !!r.paid),
    }));
  }

  /* A payer on Foxy can hand over ecash instead of paying their invoice: the
   * collector taps SCAN on that payer's screen and scans the token. A token
   * from this wallet's mint for exactly the share is taken and the payer
   * marked paid; anything else is refused and stays the payer's, with why. */
  spScanToken(idx) {
    const W = window.FoxyWallet;
    if (!W || !W.scan) return;
    const split = W.splitPending && W.splitPending();
    const row = split && split.rows && split.rows[idx];
    if (!row) { this.toast('That share\u2019s invoice is still being made.', true); return; }
    if (row.paid) { this.toast('That share is already paid.', true); return; }
    W.scan('Scan an ecash token').then(text => {
      const t = String(text || '').trim();
      if (W.classify(t) !== 'token') { this.toast('That QR is not a Cashu token.', true); return; }
      const info = W.tokenInfo(t);
      const here = String(W.mintUrl || '').replace(/\/+$/, '');
      if (!info || String(info.mint || '').replace(/\/+$/, '') !== here) {
        this.toast('That token is from ' + this.mintNameOf(info && info.mint) + '. Ask for one from '
          + this.mintName() + ', or for the invoice to be paid.', true);
        return;
      }
      if ((info.unit && info.unit !== 'sat') || Number(info.sats) !== Number(row.sats)) {
        this.toast('That token is for ' + this.group(info.sats) + ' sats; this share is '
          + this.group(row.sats) + ' sats.', true);
        return;
      }
      this.showMelt('Receiving ecash\u2026');
      return W.receiveToken(t).then(() => {
        this.hideMelt();
        this.spMarkPaid(idx, row.hash);
        if (this.state.spFromWaiting) this.setState({ screen: 'spWaiting', spFromWaiting: false });
      });
    }).catch(e => { this.hideMelt(); this.claimFailed(e, () => this.spScanToken(idx)); });
  }

  /* One share's watcher, found by its invoice where that is known (the rows a
   * resumed split watches are only the open ones, so their positions are not
   * the shares' own) and by position otherwise. */
  spStopOne(i, hash) {
    const stops = this._spStops || [];
    const hashes = String(this._spWatching || '').split(',');
    let at = hash ? hashes.indexOf(String(hash)) : -1;
    if (at < 0 && !hash && hashes.length === this.spOthers()) at = i;
    if (at < 0 || typeof stops[at] !== 'function') return;
    try { stops[at](); } catch (e) {}
    stops[at] = () => {};
    console.log('[foxy] split: share ' + (i + 1) + ' is paid; its invoice is no longer watched');
  }

  spStopWatch() {
    (this._spStops || []).forEach(f => { try { f(); } catch (e) {} });
    this._spStops = [];
    // stopped on purpose, so the next pass arms rather than recognising these
    this._spWatching = null;
    this._spWatchedAt = 0;
  }

  /* Copy something that is money.
   *
   * A token is spendable by whoever holds the text, and the general
   * pasteboard has no expiry and syncs to every paired Apple device. The
   * native side can mark a copy device-only and short-lived; the web API
   * cannot. Falls back to the ordinary path off-device. */
  copySecret(text) {
    const str = String(text || '');
    if (!str) return false;
    const mh = window.webkit && window.webkit.messageHandlers && window.webkit.messageHandlers.foxy;
    if (mh) {
      try {
        mh.postMessage({ id: 'copy-' + Date.now(), action: 'copy', text: str, sensitive: true });
        return true;
      } catch (e) {}
    }
    return this.copyText(str);
  }

  copyText(text) {
    const str = String(text || '');
    if (!str) return false;
    try {
      if (navigator.clipboard && window.isSecureContext) {
        navigator.clipboard.writeText(str);
        return true;
      }
    } catch (e) {}
    try {
      const ta = document.createElement('textarea');
      ta.value = str;
      ta.setAttribute('readonly', '');
      ta.style.cssText = 'position:fixed;top:0;left:0;opacity:0;pointer-events:none';
      document.body.appendChild(ta);
      ta.select();
      ta.setSelectionRange(0, str.length);   // iOS ignores select() on its own
      const ok = document.execCommand('copy');
      document.body.removeChild(ta);
      return ok;
    } catch (e) { return false; }
  }


  componentDidMount() {
    this.bootWallet();
    this._onDeepLink = () => this.applyDeepLink();
    window.addEventListener('hashchange', this._onDeepLink);
    // the bundled page unpacks itself before the shell finishes booting, so one check on
    // mount can run before the hash has been written — retry briefly, then stop.
    this.pushToNative();
    this.syncHaptics();
    /* Anything put over the page, or taken off it, is a reason to ask again
     * whether Apple's paste control may sit where it sits (syncPreview). The
     * screens drawn straight onto the body do not go through a render. */
    try {
      const Watch = /** @type {any} */ (window).MutationObserver;
      if (Watch && document.body) {
        this._bodyWatch = new Watch(() => {
          clearTimeout(this._bodyWatchT);
          this._bodyWatchT = setTimeout(() => { if (this.syncPreview) this.syncPreview(); }, 30);
        });
        this._bodyWatch.observe(document.body, { childList: true });
      }
    } catch (e) {}
    this._unlockAudio = () => this.audioCtx();
    window.addEventListener('pointerdown', this._unlockAudio, { passive: true });
    this._dlT = [0, 60, 200, 500, 900, 1500].map(ms => setTimeout(() => {
      if (this._onDeepLink && this._onDeepLink()) {
        (this._dlT || []).forEach(clearTimeout);
      }
    }, ms));
    this.syncAccent();
    // before anything else is usable, including the gate
    this.pinLock();
    /* The lock tells the phone it has the screen itself (pinLock): the connecting
     * screen, which is what used to say it, now stays down on every launch but
     * the first (home first), and waited for the unlock even when it did not. */
    // static frames (flow diagrams) skip the live feed, candle fetch and every loop
    if (!this.props.startStatic) { this.openFeed(); this.loadSeries(this.state.range); }
    this.applyShell();
    this._onResize = () => this.applyShell();
    window.addEventListener('resize', this._onResize);
    if (window.visualViewport) {
      // iOS ignores interactive-widget; compress the app above the keyboard by hand
      this._onVv = () => {
        const vv = window.visualViewport;
        const kb = Math.max(0, Math.round(window.innerHeight - vv.height));
        if (kb !== (this.state.kbInset || 0)) this.setState({ kbInset: kb });
        // iOS scrolls the document to reveal the input; undo it — the inset handles visibility
        if (window.scrollY || vv.offsetTop) window.scrollTo(0, 0);
        const sh = document.scrollingElement;
        if (sh && sh.scrollTop) sh.scrollTop = 0;
      };
      this._onWinScroll = () => { if ((this.state.kbInset || 0) > 0 && window.scrollY) window.scrollTo(0, 0); };
      window.addEventListener('scroll', this._onWinScroll, { passive: true });
      window.visualViewport.addEventListener('resize', this._onVv);
      window.visualViewport.addEventListener('scroll', this._onVv);
    }
  }
  componentWillUnmount() {
    if (this._tokQr) { clearInterval(this._tokQr.timer); this._tokQr = null; }
    window.removeEventListener('resize', this._onResize);
    if (this._onDeepLink) window.removeEventListener('hashchange', this._onDeepLink);
    if (this._unlockAudio) window.removeEventListener('pointerdown', this._unlockAudio);
    if (this._ac) { try { this._ac.close(); } catch (e) {} this._ac = undefined; }
    (this._dlT || []).forEach(clearTimeout);
    if (this._onVv && window.visualViewport) { window.visualViewport.removeEventListener('resize', this._onVv); window.visualViewport.removeEventListener('scroll', this._onVv); }
    if (this._onWinScroll) window.removeEventListener('scroll', this._onWinScroll);
    // every timer this component can start, or an orphan keeps running after unmount
    ['_cardBalT','_otpTick','_eta','_balT','_bkT'].forEach(k => { clearInterval(this[k]); this[k] = null; });
    ['_toastT','_nfcT','_scanT','_sendA','_sendB','_retryT','_moreT','_spResumeT','_queueT','_claimT'].forEach(k => { clearTimeout(this[k]); this[k] = null; });
    Object.keys(this).filter(k => k.indexOf('_afT_') === 0).forEach(k => { (this[k] || []).forEach(clearTimeout); this[k] = null; });
    (this._fullT || []).forEach(clearTimeout); this._fullT = null;
    this.closeFeed();
    if (this._bigMap) { this._bigMap.remove(); this._bigMap = null; }
    if (this._homeMap) { this._homeMap.remove(); this._homeMap = null; }
    if (this._cardMap) { this._cardMap.remove(); this._cardMap = null; }
    if (this._bizMap) { this._bizMap.remove(); this._bizMap = null; }
    /* What the second componentWillUnmount did. A class keeps only the last
     * definition of a method, so the first one — every listener and most
     * timers above — never ran; the two are one method now. */
    clearInterval(this._refreshT);
    this.stopReceive();
    this.spStopWatch();
    cancelAnimationFrame(this._mraf);
  }

  // candle configs, one per timeline the chip offers; the data comes from
  // Kraken through the wallet
  rangeCfg(r) {
    const D = 86400;
    return ({
      '1H': { g: 60, span: 3600, label: 'last hour' },
      '1D': { g: 300, span: D, label: 'last 24 hours' },
      '1W': { g: 3600, span: 7 * D, label: 'last week' },
      '1M': { g: 21600, span: 30 * D, label: 'last month' },
      '1Y': { g: D, span: 365 * D, label: 'last year' },
      '4Y': { g: D, span: 1461 * D, label: 'last 4 years' },
    })[r];
  }

  loadSeries(r) {
    if (this.props.startStatic) return;
    const cfg = this.rangeCfg(r);
    if (!cfg) return;
    this._loading = this._loading || {};
    if ((this.state.series || {})[r] || this._loading[r]) return;
    this._loading[r] = true;
    // Through the wallet, so it asserts the gate like every other request.
    // It used to fetch Coinbase straight from here, which meant the one screen
    // that talks to the network on launch was the one screen not behind Tor.
    const W = window.FoxyWallet;
    if (!W || !W.candles) { this._loading[r] = false; return; }
    /* Asked inside a promise. `candles` refuses with a throw when there is no
     * route, and thrown here it went up through `walletReady` into the
     * launch's own catch: "connect failed, attempt 1" for a wallet that had
     * connected, the rest of `walletReady` skipped (no balance, no history,
     * nothing listening), and three seconds before it was tried again. A
     * launch with no route did that every time; opening on the home screen,
     * every launch has no route yet. */
    Promise.resolve().then(() => W.candles(cfg.g, cfg.span))
      .then(series => {
        const rows = (series || [])
          .filter(x => isFinite(x.t) && isFinite(x.c) && x.c > 0)
          .sort((p, q) => p.t - q.t);
        if (rows.length < 4) throw new Error('thin series');
        const built = this.buildChart(rows, cfg.label);
        this.setState(p => {
          const next = Object.assign({}, p.series);
          next[r] = built;
          return { series: next };
        });
      })
      .catch(e => {
        this._loading[r] = false;
        console.warn('[foxy] price line for', r, 'not loaded \u2014', (e && e.message) || e);
        /* And asked again. One refusal at launch left the home screen with no
         * line under the price for the rest of the visit, online or not
         * ("bad URL", never retried).
         * Slower each time, and not while there is no route to ask over. */
        this._seriesTries = (this._seriesTries || 0) + 1;
        clearTimeout(this._seriesT);
        this._seriesT = setTimeout(() => {
          if ((this.state.series || {})[this.state.range]) return;
          if (this.offlineNow && this.offlineNow()) return;
          this.loadSeries(this.state.range);
        }, Math.min(60000, 4000 * this._seriesTries));
      });
  }

  buildChart(rows, label) {
    // average into coarse buckets, then run a weighted smoothing pass so a 9px
    // stroke reads as one clean curve rather than a jitter of trade noise
    const N = Math.min(28, rows.length);
    let vals = [];
    for (let i = 0; i < N; i++) {
      const a = Math.floor(i * rows.length / N);
      const b = Math.max(a + 1, Math.floor((i + 1) * rows.length / N));
      let sum = 0;
      for (let j = a; j < b; j++) sum += rows[j].c;
      vals.push(sum / (b - a));
    }
    for (let pass = 0; pass < 2; pass++) {
      const out = vals.slice();
      for (let i = 1; i < vals.length - 1; i++) out[i] = (vals[i - 1] + vals[i] * 2 + vals[i + 1]) / 4;
      vals = out;
    }
    const lo = Math.min.apply(null, vals), hi = Math.max.apply(null, vals);
    const span = (hi - lo) || 1;
    const X0 = 8, X1 = 372, YLO = 78, YHI = 14;
    let pts = vals.map((v, i) => ({
      x: X0 + (X1 - X0) * (N === 1 ? 1 : i / (N - 1)),
      y: YLO + (YHI - YLO) * ((v - lo) / span),
    }));
    /* The line is drawn past both edges of the screen, so neither end shows as
     * a stub with a rounded cap on it: a point is carried
     * on beyond each end, along the slope it already had, and the view box
     * clips what falls outside. These are drawing only — the price's own first
     * and last points do not move, and the ride still starts and stops on them
     * (riderTrack trims to them). */
    const BLEED = 60, LIFT = 18;
    const lean = (a, b) => Math.max(-LIFT, Math.min(LIFT,
      (b.y - a.y) / ((b.x - a.x) || 1) * BLEED));
    const first = pts[0], second = pts[1] || pts[0];
    const far = pts[pts.length - 1], near = pts[pts.length - 2] || far;
    pts = [{ x: first.x - BLEED, y: first.y - lean(first, second) }]
      .concat(pts, [{ x: far.x + BLEED, y: far.y + lean(near, far) }]);
    const ENDS = 1;                      // how many drawn points at each end are bleed

    const f = n => n.toFixed(1);
    let d = 'M' + f(pts[0].x) + ' ' + f(pts[0].y);
    for (let i = 0; i < pts.length - 1; i++) {
      const p0 = pts[i - 1] || pts[i], p1 = pts[i], p2 = pts[i + 1], p3 = pts[i + 2] || p2;
      d += ' C' + f(p1.x + (p2.x - p0.x) / 6) + ' ' + f(p1.y + (p2.y - p0.y) / 6)
         + ',' + f(p2.x - (p3.x - p1.x) / 6) + ' ' + f(p2.y - (p3.y - p1.y) / 6)
         + ',' + f(p2.x) + ' ' + f(p2.y);
    }
    const diff = rows[rows.length - 1].c - rows[0].c;
    const mag = Math.abs(diff);
    const money = Math.round(mag).toLocaleString('en-US');
    const real = pts.slice(ENDS, pts.length - ENDS);
    return { d: d, y: real[real.length - 1].y, t: (diff >= 0 ? '+' : '-') + '$ ' + money + ' ' + label,
      pts: real.map(p => ({ x: p.x / 402 * 100, y: p.y / 92 * 100 })) };
  }

  // the price line, drawn from whatever the gated feed last reported
  /* The live price.
   *
   * This was a WebSocket straight to Coinbase, opened before the gate had
   * decided anything and reconnected every three seconds for the life of the
   * app. A socket is not a fetch, so it survived every sweep that moved the
   * other requests behind the tunnel.
   *
   * Now it polls through the wallet, which asserts the tunnel and walks the
   * same six sources as everything else. Twenty seconds instead of every
   * trade — a ticker that updates on the second is not worth a company
   * watching the app run.
   */
  openFeed() {
    if (this.props.startStatic || this._feedT) return;
    const tick = () => {
      const W = window.FoxyWallet;
      if (!W || !W.rate) return;
      W.rate().then(p => {
        if (isFinite(p) && p > 0) this.setState({ livePrice: p, feedLive: true });
      }).catch(() => this.setState({ feedLive: false }));
    };
    tick();
    this._feedT = setInterval(tick, 20000);
  }

  closeFeed() {
    if (this._feedT) { clearInterval(this._feedT); this._feedT = null; }
    this.setState({ feedLive: false });
  }

  // walks the bolt marker along the chart curve, spinning as it travels

  /* He does not stop on the line: the ride carries him off the right edge and
   * that is where he waits for the next one. Hidden rather
   * than merely placed outside, since a marker parked past the panel's edge is
   * a page that can be scrolled sideways; the ride shows him again.
   *
   * Also the answer when there is nothing to ride yet — no line drawn, no
   * geometry — so a chart with no rider on it is the resting state either way. */
  /* Snow on the home screen, the same weather as the launch. Each flake is three nested divs — one falls, one sways, one
   * fades — so a handful of CSS animations carry the lot and nothing is driven
   * from JavaScript once they are made.
   *
   * Depth is what makes it read: a flake near the front is bigger, faster and
   * brighter than one behind it. The count is taken from the screen's width,
   * not fixed, because these frames are spent on a phone that is also drawing
   * a price line and, at launch, talking to Tor.
   */
  SNOW_KEYFRAMES = '@keyframes foxySnowFall{0%{transform:translate3d(0,-40px,0)}'
    + '100%{transform:translate3d(var(--drift),var(--fallTo,900px),0)}}'
    + '@keyframes foxySnowSway{0%,100%{transform:translateX(calc(var(--sway) * -1))}'
    + '50%{transform:translateX(var(--sway))}}'
    + '@keyframes foxySnowFade{0%{opacity:0}8%{opacity:var(--op)}88%{opacity:var(--op)}100%{opacity:0}}'
    + '[data-snow] i{position:absolute;top:0;display:block;will-change:transform;'
    + 'animation:foxySnowFall linear infinite}'
    + '[data-snow] i>i{width:100%;height:100%;animation:foxySnowSway ease-in-out infinite}'
    + '[data-snow] i>i>i{width:100%;height:100%;border-radius:50%;opacity:0;'
    + 'background:radial-gradient(circle at 34% 30%,#FFF 0%,#E4EEF6 45%,rgba(190,212,230,.55) 100%);'
    + 'animation:foxySnowFade linear infinite}'
    /* And where it lands on something, it settles. The panel on the home
     * screen, and a card on its own screen, have a top edge, round at both
     * corners, for the snow to gather on (`data-snow-cap`, in the markup at
     * the top of the panel and beside the card): a drift that rises along the
     * edge and clumps that swell on it, each on its own clock, and a band
     * across the whole width that creeps down round both corners to where
     * they end. From nothing to settled in about half a minute, once, and it
     * stays until the screen is left. */
    + '@keyframes foxySnowPile{0%{transform:scale(.9,0)}100%{transform:scale(1,1)}}'
    + '@keyframes foxySnowClump{0%{transform:scale(0)}100%{transform:scale(1)}}'
    + '@keyframes foxySnowDrape{0%{clip-path:inset(-3cqw -3cqw 100% -3cqw)}100%{clip-path:inset(-3cqw -3cqw -1cqw -3cqw)}}'
    + '@media (prefers-reduced-motion: reduce){[data-snow],[data-snow-cap]{display:none}}';

  /* Snow that settles (`data-snow-cap`) is held at nothing while the launch
   * screen is in front and started when it lifts: gathered where nobody
   * could see it, it has already fallen by the time they can. Nothing is
   * written to the page; the clocks themselves are held and let go. */
  syncSnowCap() {
    const G = window.FoxyGate;
    const covered = !!(G && G.visible && G.visible());
    if (!covered && !this._snowCapHeld) return;          // falling or settled: left alone
    /** @type {Animation[]} */
    const clocks = [];
    document.querySelectorAll('[data-snow-cap], [data-snow-cap] i').forEach((el) => {
      if (el.getAnimations) el.getAnimations().forEach((a) => clocks.push(a));
    });
    this._snowCapHeld = covered;
    clocks.forEach((a) => {
      try { a.currentTime = 0; if (covered) a.pause(); else a.play(); } catch (e) {}
    });
  }

  syncSnow() {
    this.syncSnowCap();
    const layer = document.querySelector('[data-snow="home"]');
    if (!layer || layer.firstChild) return;            // made once, then left alone
    if (!this._snowCss) {
      const sheet = document.createElement('style');
      sheet.textContent = this.SNOW_KEYFRAMES;
      document.head.appendChild(sheet);
      this._snowCss = true;
    }
    const wide = Math.max(320, window.innerWidth || 390);
    const count = Math.min(60, Math.round(wide / 9));
    const fallTo = Math.max(900, (window.innerHeight || 800) + 80);
    /* Scattered from a fixed seed rather than Math.random: the same weather
     * every time, which is how the render snapshots can hold it at all — with
     * real randomness every recording differed from the last. Nobody can tell
     * a seeded snowfall from a random one. */
    let seed = 20260919;
    const roll = () => {
      seed = (seed * 1103515245 + 12345) % 2147483648;
      return seed / 2147483648;
    };
    const frag = document.createDocumentFragment();
    for (let n = 0; n < count; n++) {
      const deep = Math.pow(roll(), 1.7);               // 0 far … 1 near
      const size = 1.6 + deep * 5.4;
      const fall = (22 - deep * 12 + roll() * 6).toFixed(2) + 's';
      const late = (-roll() * 26).toFixed(2) + 's';
      const outer = document.createElement('i');
      outer.style.cssText = 'left:' + (roll() * 102 - 1).toFixed(2) + '%;'
        + 'width:' + size.toFixed(1) + 'px;height:' + size.toFixed(1) + 'px;'
        + '--drift:' + ((roll() * 2 - 1) * (20 + deep * 70)).toFixed(0) + 'px;'
        + '--fallTo:' + fallTo + 'px;animation-duration:' + fall + ';animation-delay:' + late + ';';
      const mid = document.createElement('i');
      mid.style.cssText = '--sway:' + (4 + deep * 14).toFixed(0) + 'px;'
        + 'animation-duration:' + (3.4 + roll() * 4.6).toFixed(2) + 's;animation-delay:' + late + ';';
      const dot = document.createElement('i');
      dot.style.cssText = '--op:' + (0.3 + deep * 0.65).toFixed(2) + ';'
        + 'box-shadow:0 0 ' + (2 + deep * 6).toFixed(0) + 'px rgba(207,224,236,.5);'
        + 'animation-duration:' + fall + ';animation-delay:' + late + ';';
      mid.appendChild(dot); outer.appendChild(mid); frag.appendChild(outer);
    }
    layer.appendChild(frag);
  }

  /* Keeping him away.
   *
   * markerGone sets the marker's own style, and the renderer writes the
   * template's style over it on the next draw — which put him back at the end
   * of the line, mid-screen, a beat after he had left. So
   * the update pass asks for it again whenever he is not riding. It sets two
   * properties and reads nothing; doing it every draw costs nothing. */
  markerStayGone() {
    const el = this._marker;
    if (!el || this._riding) return;
    if (el.style.visibility !== 'hidden') el.style.visibility = 'hidden';
  }

  markerGone() {
    const el = this._marker;
    if (!el) return false;
    cancelAnimationFrame(this._mraf);
    this._riding = false;
    this.riderLinesOff();
    el.style.visibility = 'hidden';
    el.style.left = '100%';
    el.style.top = '50%';
    el.style.transform = 'rotate(0deg)';
    const body = el.querySelector('[data-rider="body"]');
    const armsWrap = el.querySelector('[data-rider="armswrap"]');
    const arms = el.querySelector('[data-rider="arms"]');
    if (body) body.style.transform = 'translate(-50%,-100%)';
    if (armsWrap) armsWrap.style.transform = 'translate(-50%,-100%)';
    if (arms) arms.style.transform = 'rotate(0deg)';
    return true;
  }

  /* The rider coming in along the price line.
   *
   * The motion is the coaster from an earlier sketch, kept as it was
   * there and made to happen once: gravity, so it gathers speed into a dip and
   * eases up the far side; squash and stretch on a spring, so it lands heavy
   * and overshoots; a lean into a drop before the track falls away; and arms
   * that lag the turns and whip on a landing before settling. What is not kept
   * is the loop — it rides in from behind the left edge and stops at the end
   * of the line, where the coin used to park.
   *
   * It runs faster than the sketch did (three times, then
   * slower again twice over — it has to cross the line at a pace that reads as
   * riding rather than as a jump cut), and the
   * sketch's emphasis lines come with it: air streaks off the rider's face
   * wherever the line is fast, and a small burst kicked off the rail when a
   * dip bottoms out. Both are drawn from the same gravity speed the motion
   * uses, so they appear where the ride is actually quick and nowhere else.
   */
  RIDE_MS = 7000;
  RIDE_IN_PX = 48;        // starts this far behind the line's left end
  /* 90 left about 30px of him still on screen at the moment he vanished,
   * so the ride ended with a blink rather than an exit. He now rolls clear of the edge before he is reset. */
  RIDE_OUT_PX = 120;      // and carries this far past its right end, off the screen

  /* The rider: a drawing of twelve frames in one sheet, six across and two
   * down (Web/foxy-rider.webp).
   *
   * He bobs on his sled in the drawing; everything else about the ride — the
   * lean into a slope, the squash through a dip, the stretch over a crest —
   * is done here, to the same gravity the character before him had.
   *
   * The frames are cut out of a longer drawing (151 frames, six
   * seconds, which does not loop). The first cut was chosen for how cleanly it
   * came back to its start, and it barely moved: a twelfth of the drawing
   * changed from one frame to the next, which at this size is a still picture. These frames move three times as much.
   *
   * They are played there and back rather than round and round. A stretch with
   * real movement in it does not happen to end where it began, and looping it
   * put a jump three times the size of a normal step into every cycle; a bob
   * reverses perfectly well, so going back through the frames costs nothing
   * and leaves no seam at all.
   *
   * His runners sit on the same line in every frame, which is why the bottom
   * of the drawing is what is held to the price line.
   *
   * RIDE_W_PX is the only number to change to make him bigger or smaller; his
   * height follows the sheet's own proportions. */
  /* The whole drawing now: every one of its 151 frames, played forward at
   * its own 25 fps and looped ("the gif should be 6s
   * long, 25fps"). Thirteen across, twelve down. */
  SLED_COLS = 13;
  SLED_ROWS = 12;
  SLED_FRAMES = 151;
  SLED_CYCLE_MS = 6040;     // the drawing's own length, forward, round and round
  SLED_FRAME_W = 228;       // one frame in the sheet
  SLED_FRAME_H = 116;       // the car: wide and low
  RIDE_W_PX = 160;          // how wide it rides (25% up from 128)
  RIDE_G = 2.2;           // gravity: how much faster a dip is than a crest
  /* No squash and no stretch for the car: the drawing bumps enough on its
   * own, and a car pressed flat through a dip is a car the wrong shape. The spring is still there, at zero. */
  RIDE_SQUASH_GAIN = 0;
  RIDE_SQUASH_MAX = 0;
  RIDE_SQUASH_K = 0.22;   // spring stiffness
  RIDE_SQUASH_DAMP = 0.72;
  RIDE_STRETCH = 0;       // stretch along travel as it speeds up: none, for the car
  RIDE_LEAN_GAIN = 0.5;
  RIDE_LEAN_MAX = 15;     // degrees
  RIDE_ARM_K = 0.12;
  RIDE_ARM_DAMP = 0.84;
  RIDE_ARM_DRIVE = 1.3;
  RIDE_ARM_IMPACT = 42;
  RIDE_ARM_MAX = 42;      // degrees
  /* The emphasis lines, in the sketch's numbers scaled to this rider: its cart
   * is 62px wide and this one is 75, so the offsets and
   * lengths go up by a fifth. Speeds are the gravity speed (1 at a crest,
   * 1 + RIDE_G in a dip) and never needed scaling. */
  RIDE_LINE_MIN = 1.7;    // no air lines slower than this
  RIDE_LINE_LEN = 16;     // streak length per unit of speed
  RIDE_LINE_RATE = 30;    // streaks a second at speed
  RIDE_LINE_FACE = 27;    // they leave the rider's face, not the rail
  RIDE_LINE_LIFE = 0.26;  // seconds before one has faded
  RIDE_IMPACT_MIN = 1.45; // a landing slower than this kicks up nothing

  /* The line in the marker's own pixel space, with an arc-length walk and the
   * gravity warp: travel time integrates 1/speed, so equal steps of phase are
   * short where the line is high and long where it dips. */
  riderTrack(el) {
    const path = el.parentElement && el.parentElement.querySelector('path');
    if (!path || !path.getTotalLength) return null;
    let len = 0;
    try { len = path.getTotalLength(); } catch (e) { return null; }
    const box = el.parentElement.getBoundingClientRect();
    if (!len || !box.width || !box.height) return null;

    /* Sampled across the drawn path, then cut back to the price's own ends: the
     * line is drawn past both edges of the screen so neither end shows, and he
     * would otherwise ride in from off-screen only to park off it. */
    const walk = [];
    for (let i = 0; i <= 240; i++) {
      const p = path.getPointAtLength((i / 240) * len);
      walk.push({ x: p.x / 402 * box.width, y: p.y / 92 * box.height });
    }
    const pts = [];
    let s = 0, px = 0, py = 0, yTop = Infinity, yBot = -Infinity;
    walk.forEach((p, i) => {
      if (i > 0) s += Math.hypot(p.x - px, p.y - py);
      pts.push({ s: s, x: p.x, y: p.y });
      px = p.x; py = p.y;
      if (p.y < yTop) yTop = p.y;
      if (p.y > yBot) yBot = p.y;
    });
    const total = s, range = (yBot - yTop) || 1;
    // in behind the left edge, along the whole drawing, and out past the right
    const whole = this.RIDE_IN_PX + total + this.RIDE_OUT_PX;
    const yOf = q => {
      if (q <= this.RIDE_IN_PX) return pts[0].y;
      const d = Math.min(q - this.RIDE_IN_PX, total);
      let j = 1;
      while (j < pts.length - 1 && pts[j].s < d) j++;
      const a = pts[j - 1], b = pts[j];
      return a.y + (b.y - a.y) * ((d - a.s) / ((b.s - a.s) || 1));
    };
    const speedAt = y => 1 + this.RIDE_G * ((y - yTop) / range);
    const warp = [];
    let time = 0, prev = 0;
    for (let i = 0; i <= 256; i++) {
      const q = (i / 256) * whole;
      if (i > 0) time += (q - prev) / speedAt(yOf((q + prev) / 2));
      warp.push({ s: q, t: time });
      prev = q;
    }
    const last = warp[warp.length - 1].t || 1;
    warp.forEach(o => { o.t /= last; });
    return { pts, total, yTop, range, whole, warp, box, yOf, speedAt };
  }

  /* The pool the emphasis lines are drawn from: eighteen thin divs in a layer
   * of their own, behind the rider and in the same pixel space, made once and
   * reused. The template leaves the layer empty, so nothing the renderer draws
   * is disturbed; a redraw that replaces the layer is noticed by identity and
   * the pool is made again. */
  riderLines(el) {
    const layer = el.parentElement
      && el.parentElement.querySelector('[data-rider="streaks"]');
    if (!layer) return null;
    if (this._streaks && this._streaks.layer === layer) return this._streaks;
    layer.textContent = '';
    const pool = [];
    for (let i = 0; i < 18; i++) {
      const line = document.createElement('div');
      /* The colour comes from the theme's own ink token rather than being
       * composed with rgba(var(...)), which is a substitution some engines
       * drop on the floor — and a line that is there but paints nothing looks
       * exactly like a line that was never made. */
      line.style.cssText = 'position:absolute;left:0;top:0;height:1.5px;border-radius:1px;'
        + 'background:linear-gradient(to right,transparent,var(--ink) 30%,'
        + 'var(--ink) 70%,transparent);opacity:0;pointer-events:none;'
        + 'transform-origin:center;will-change:left,top,opacity,transform';
      layer.appendChild(line);
      pool.push({ el: line, life: 0, max: this.RIDE_LINE_LIFE, op0: 0.5 });
    }
    this._streaks = { layer: layer, pool: pool };
    return this._streaks;
  }

  // one line, placed and lit; the ride fades it over the life it is given
  riderLine(stk, x, y, len, angle, op, life) {
    stk.el.style.width = len.toFixed(1) + 'px';
    stk.el.style.left = x.toFixed(1) + 'px';
    stk.el.style.top = y.toFixed(1) + 'px';
    stk.el.style.transform = 'translate(-50%,-50%) rotate(' + angle.toFixed(1) + 'deg)';
    stk.el.style.opacity = String(op);
    stk.life = life;
    stk.max = life;
    stk.op0 = op;
  }

  // the lines already out there, a frame older
  riderFade(lines, dt) {
    if (!lines) return;
    lines.pool.forEach(stk => {
      if (stk.life <= 0) return;
      stk.life -= dt;
      stk.el.style.opacity = (Math.max(0, stk.life) / stk.max * stk.op0).toFixed(3);
    });
  }

  /* Air off the face, at a rate set by how far over the floor the speed is:
   * nothing above a crest, a stream through a dip. `bag` carries the fraction
   * of a line left over between frames, so a slow frame is not a gap. */
  riderAir(lines, bag, cx, cy, ang, speed, dt) {
    if (!lines || speed <= this.RIDE_LINE_MIN) return;
    const rad = ang * Math.PI / 180;
    const tx = Math.cos(rad), ty = Math.sin(rad);    // along the travel
    const ux = Math.sin(rad), uy = -Math.cos(rad);   // the rider's own up
    const faceX = cx + ux * this.RIDE_LINE_FACE;
    const faceY = cy + uy * this.RIDE_LINE_FACE;
    bag.spawn += dt * (speed - this.RIDE_LINE_MIN) * this.RIDE_LINE_RATE;
    while (bag.spawn >= 1) {
      bag.spawn -= 1;
      const stk = lines.pool.find(one => one.life <= 0);
      if (!stk) break;
      const back = 6 + Math.random() * 10;           // a little behind the face
      const off = (Math.random() * 2 - 1) * 11;      // spread around face level
      const long = Math.max(13, Math.min(45, speed * this.RIDE_LINE_LEN));
      this.riderLine(stk, faceX - tx * back + ux * off,
        faceY - ty * back + uy * off, long, ang, 0.5, this.RIDE_LINE_LIFE);
    }
  }

  // three kicked off the rail: straight down, and splayed either side
  riderImpact(lines, cx, cy) {
    if (!lines) return;
    [[0, 90], [-7, 116], [7, 64]].forEach(hit => {
      const stk = lines.pool.find(one => one.life <= 0);
      if (!stk) return;
      this.riderLine(stk, cx + hit[0] + (Math.random() * 2 - 1) * 2, cy + 4,
        12 + Math.random() * 5, hit[1], 0.65, 0.2);
    });
  }

  // every line out: the ride is over, or there is no ride to draw
  riderLinesOff() {
    if (!this._streaks) return;
    this._streaks.pool.forEach(stk => { stk.life = 0; stk.el.style.opacity = '0'; });
  }

  /* The launch screen is the native-side cover over the whole page, and the
   * home screen is drawn behind it while it is still up. A ride started there
   * plays out unseen and the first thing the person gets is an empty line — so
   * the ride waits for the cover to come down, and the wait is a poll because
   * the gate announces nothing. */
  riderCovered() {
    const G = window.FoxyGate;
    return !!(G && G.visible && G.visible());
  }

  riderWhenSeen() {
    clearTimeout(this._rideWait);
    const tick = () => {
      this._rideWait = null;
      if (!this._marker || this.state.screen !== 'home') return;
      if (this.riderCovered()) { this._rideWait = setTimeout(tick, 250); return; }
      this._rolled = this.riderShow();
    };
    this._rideWait = setTimeout(tick, 250);
  }

  /* One attempt at a ride, and the answer is whether one actually started.
   *
   * This exists because of what it replaced: `markerRoll() || markerGone()`,
   * where the fallback always answers true. A cold launch has no price line
   * for a second or two, so the first attempt could not ride — and the true
   * from putting him away was recorded as "he has ridden", which is why the
   * he was never seen on a first launch. The series landing
   * afterwards found the ride already marked done.
   *
   * So: he is put out of sight when there is nothing to ride, and the caller
   * is told no, which leaves the next update free to try again. */
  riderShow() {
    const rode = this.markerRoll();
    if (!rode) this.markerGone();
    return rode;
  }

  /* Size the rider and scale the sheet behind him, once per ride.
   *
   * The sheet holds twelve frames; sizing the background to the whole grid is
   * what lets a percentage background-position land on exact frame edges in
   * sledFrame below. */
  sledLayout(body) {
    if (!body) return;
    const W = this.RIDE_W_PX;
    body.style.width = W.toFixed(2) + 'px';
    body.style.height = (W * this.SLED_FRAME_H / this.SLED_FRAME_W).toFixed(2) + 'px';
    body.style.backgroundSize = (100 * this.SLED_COLS).toFixed(0) + '% '
      + (100 * this.SLED_ROWS).toFixed(0) + '%';
  }

  /* Frame `fr` of the sheet.
   *
   * A percentage background-position places p% of the image against p% of the
   * element, so with the sizing above each frame lands on an exact boundary:
   * the columns divide 100% into COLS-1 steps, the rows into ROWS-1. */
  sledFrame(body, fr) {
    if (!body) return;
    const col = fr % this.SLED_COLS, row = Math.floor(fr / this.SLED_COLS);
    body.style.backgroundPosition =
      (col * (100 / (this.SLED_COLS - 1))).toFixed(4) + '% '
      + (row * (100 / (this.SLED_ROWS - 1))).toFixed(4) + '%';
  }

  markerRoll() {
    const el = this._marker;
    if (!el) return false;
    if (this.riderCovered()) { this.riderWhenSeen(); return false; }
    const body = el.querySelector('[data-rider="body"]');
    const armsWrap = el.querySelector('[data-rider="armswrap"]');
    const arms = el.querySelector('[data-rider="arms"]');
    const track = this.riderTrack(el);
    /* The sled team has no separate arms — they are drawn into its sheet.
     * This used to refuse to ride at all without them. */
    if (!track || !body) return false;
    this.sledLayout(body);

    cancelAnimationFrame(this._mraf);
    this._riding = true;
    el.style.visibility = 'visible';
    const lines = this.riderLines(el);
    this.riderLinesOff();
    const pts = track.pts, N = pts.length - 1;
    const first = pts[0], lastPt = pts[N];
    const dx0 = pts[1].x - first.x, dy0 = pts[1].y - first.y;
    const inLen = Math.hypot(dx0, dy0) || 1;
    const inDir = { x: dx0 / inLen, y: dy0 / inLen };
    const startAng = Math.atan2(dy0, dx0) * 180 / Math.PI;
    const dxN = lastPt.x - pts[N - 1].x, dyN = lastPt.y - pts[N - 1].y;
    const outLen = Math.hypot(dxN, dyN) || 1;
    const outDir = { x: dxN / outLen, y: dyN / outLen };
    const endAng = Math.atan2(dyN, dxN) * 180 / Math.PI;

    let squash = 0, squashV = 0, lean = 0, armA = 0, armV = 0;
    let lastAng = null, lastSquash = 0, lastFrame = -1;
    let prevCy = null, prevVy = 0;
    const bag = { spawn: 0 };
    const t0 = performance.now();
    let lastNow = t0;

    /* The line at a distance along the ride: before it, on it, or past its
     * end. Both halves ask this, each for its own point, which is what lets
     * them sit at different heights and angles at the same moment. */
    const at = along => {
      if (along < this.RIDE_IN_PX) {
        const back = this.RIDE_IN_PX - along;
        return { x: first.x - inDir.x * back, y: first.y - inDir.y * back, ang: startAng };
      }
      if (along > this.RIDE_IN_PX + track.total) {
        const out = along - this.RIDE_IN_PX - track.total;
        return { x: lastPt.x + outDir.x * out, y: lastPt.y + outDir.y * out, ang: endAng };
      }
      const d = Math.min(along - this.RIDE_IN_PX, track.total);
      let j = 1;
      while (j < N && pts[j].s < d) j++;
      const p0 = pts[j - 1], p1 = pts[j];
      const f = (d - p0.s) / ((p1.s - p0.s) || 1);
      return { x: p0.x + (p1.x - p0.x) * f, y: p0.y + (p1.y - p0.y) * f,
               ang: Math.atan2(p1.y - p0.y, p1.x - p0.x) * 180 / Math.PI };
    };

    const step = now => {
      const raw = Math.min(1, (now - t0) / this.RIDE_MS);
      // phase through the gravity warp: distance, not time, is what eases
      let i = 1;
      while (i < track.warp.length && track.warp[i].t < raw) i++;
      const a = track.warp[i - 1], b = track.warp[i] || a;
      const along = a.s + (b.s - a.s) * ((raw - a.t) / ((b.t - a.t) || 1));

      let cx, cy, ang = startAng, target = 0, leanTo = 0, onLine = false;
      if (along < this.RIDE_IN_PX) {
        const back = this.RIDE_IN_PX - along;
        cx = first.x - inDir.x * back;
        cy = first.y - inDir.y * back;
      } else if (along > this.RIDE_IN_PX + track.total) {
        // off the end of the drawing, still going, on the heading he had
        const out = along - this.RIDE_IN_PX - track.total;
        cx = lastPt.x + outDir.x * out;
        cy = lastPt.y + outDir.y * out;
        ang = endAng;
      } else {
        onLine = true;
        const d = Math.min(along - this.RIDE_IN_PX, track.total);
        let j = 1;
        while (j < N && pts[j].s < d) j++;
        const p0 = pts[j - 1], p1 = pts[j];
        const f = (d - p0.s) / ((p1.s - p0.s) || 1);
        cx = p0.x + (p1.x - p0.x) * f;
        cy = p0.y + (p1.y - p0.y) * f;
        ang = Math.atan2(p1.y - p0.y, p1.x - p0.x) * 180 / Math.PI;
        // a dip squashes, a crest stretches: the curve either side of here
        const look = Math.min(Math.max(track.total * 0.04, 6), 40);
        const curve = track.yOf(this.RIDE_IN_PX + d - look)
          + track.yOf(this.RIDE_IN_PX + d + look) - 2 * cy;
        target = Math.max(-this.RIDE_SQUASH_MAX,
          Math.min(this.RIDE_SQUASH_MAX, -curve * this.RIDE_SQUASH_GAIN));
        // and it leans back at a crest, just before the track drops away
        const ahead = Math.max(Math.min(track.total * 0.10, 60), 12);
        const drop = track.yOf(this.RIDE_IN_PX + d + ahead) - cy;
        const fallen = cy - track.yOf(this.RIDE_IN_PX + d - ahead);
        leanTo = Math.max(-this.RIDE_LEAN_MAX,
          Math.min(this.RIDE_LEAN_MAX, (drop - fallen) * this.RIDE_LEAN_GAIN));
      }

      const speed = track.speedAt(cy);
      const stretch = (speed - 1) * this.RIDE_STRETCH;
      squashV = squashV * this.RIDE_SQUASH_DAMP + (target - squash) * this.RIDE_SQUASH_K;
      squash = Math.max(-0.85, Math.min(0.85, squash + squashV));
      const sx = (1 + squash * 0.7) * (1 + stretch);
      const sy = Math.max(0.12, Math.min(2, (1 - squash) / (1 + stretch)));
      lean += (leanTo - lean) * 0.18;
      const bodyAng = ang - lean;

      let turn = bodyAng - (lastAng === null ? bodyAng : lastAng);
      if (turn > 180) turn -= 360; else if (turn < -180) turn += 360;
      lastAng = bodyAng;
      const landed = squash - lastSquash;
      lastSquash = squash;
      armV = armV * this.RIDE_ARM_DAMP + (0 - armA) * this.RIDE_ARM_K
        + (-turn * this.RIDE_ARM_DRIVE - landed * this.RIDE_ARM_IMPACT);
      armA = Math.max(-this.RIDE_ARM_MAX, Math.min(this.RIDE_ARM_MAX, armA + armV));

      el.style.left = cx + 'px';
      el.style.top = cy + 'px';
      el.style.transform = 'rotate(' + bodyAng.toFixed(2) + 'deg)';
      const shape = 'translate(-50%,-100%) scale(' + sx.toFixed(3) + ',' + sy.toFixed(3) + ')';
      body.style.transform = shape;

      // the drawing on its own clock: forward through every frame, and round again
      const fr = Math.floor(((now - t0) % this.SLED_CYCLE_MS) / this.SLED_CYCLE_MS * this.SLED_FRAMES) % this.SLED_FRAMES;
      if (fr !== lastFrame) {
        lastFrame = fr;
        this.sledFrame(body, fr);
      }
      if (armsWrap) armsWrap.style.transform = shape;
      if (arms) arms.style.transform = 'rotate(' + armA.toFixed(2) + 'deg)';

      /* The emphasis lines. Both read the same gravity speed the motion does,
       * so they mark where the ride is quick rather than being sprinkled. */
      const dt = Math.max(0, Math.min(0.05, (now - lastNow) / 1000));
      lastNow = now;
      this.riderFade(lines, dt);
      if (onLine) {
        this.riderAir(lines, bag, cx, cy, ang, speed, dt);
        // the bottom of a dip: where the falling turns into climbing
        const vy = cy - (prevCy === null ? cy : prevCy);
        if (prevVy > 0.15 && vy <= 0.15 && speed > this.RIDE_IMPACT_MIN) {
          this.riderImpact(lines, cx, cy);
        }
        prevVy = vy;
        prevCy = cy;
      }

      if (raw < 1) { this._mraf = requestAnimationFrame(step); return; }
      // through, and away: the last of the ride is off the right of the screen
      this.markerGone();
    };
    this._mraf = requestAnimationFrame(step);
    return true;
  }

  /* Every screen change, written to the log.
   *
   * Nothing recorded where the person had actually been. A screen that opened
   * when another should have, or one that never appeared at all, could only be
   * reported in words afterwards and then hunted for in the code — the switch
   * screen that showed transfer instead, the collecting screen that never
   * marked a payer paid. A log naming the screens
   * in order, with the few flags that decide which one is drawn, turns that
   * into something a device log answers by itself.
   *
   * What it does NOT carry: amounts, invoices, tokens, mint hosts, contacts.
   * The screen's name, how long it was up, how deep the back stack is, and
   * whichever of the flow flags are set. Those flags are the ones that have
   * actually caused a wrong screen, and none of them is anyone's money.
   *
   * Debug builds only, like every console line (13-console-and-qr.js). */
  noteScreen(prevState) {
    const s = this.state;
    const now = Date.now();
    const held = this._screenAt ? now - this._screenAt : 0;
    this._screenAt = now;
    const flags = [];
    const add = (name, v) => { if (v) flags.push(name + '=' + v); };
    add('flow', s.flow);
    add('rail', s.recvRail);
    add('trStep', s.trStep);
    add('spStep', s.spStep);
    add('card', this._blockedKind);
    if (s.invoiceIsAddress) flags.push('onchain');
    if (this._riding) flags.push('riding');
    /* The sending screen is never the last screen. Eight seconds on it with
     * nothing settled and it says so and offers a way off: a payer whose app
     * had been put away mid-tap came back to SENDING, waited fifteen seconds
     * with nothing to press, and killed Foxy. One
     * timer, started on arriving and cleared on leaving. */
    // paid: the top-up starts while the confirmation is still up
    if (s.screen === 'paid' && this.tidyChangeNow) this.tidyChangeNow();
    clearTimeout(this._sendSlowT);
    if (s.screen === 'sendDone') {
      this._sendSlowT = setTimeout(() => {
        const now = this.state;
        if (now.screen === 'sendDone' && (now.sendPhase || 'in') === 'in') this.setState({ sendSlow: true });
      }, 13000);
    } else if (s.sendSlow || s.sendPct) {
      this.setState({ sendSlow: false, sendPct: 0 });
    }
    console.log('[foxy] screen ' + (prevState.screen || '?') + ' \u2192 ' + s.screen
      + ' after ' + held + 'ms, back stack ' + ((s.stack && s.stack.length) || 0)
      + (flags.length ? ' | ' + flags.join(' ') : ''));
  }

  /* Home is the end of a receive, however it was reached.
   *
   * The invoice watch was stopped by the ways out that remembered to:
   * the close button, a new invoice, a crossing. A request paid by tap
   * goes confirm, paid, home and passes none of them, and neither does
   * plain Back — so the watch went on asking about an invoice nobody
   * would pay, and `moneyBusy` read it as money in flight: "Wait for the
   * payment to finish before switching mints", about a payment that had
   * finished thirty seconds before.
   * The quote stays on file and the sweep claims it if it is ever paid. */
  endReceiveAtHome() {
    /* And an invoice still being asked for is let go when it answers.
     *
     * Back out of the invoice screen within a second, before the mint has
     * answered, and there is no watch to stop yet. The answer then came a
     * moment later, to a screen that was no longer there, and started one:
     * switching mints was refused for "a payment in progress" that was an
     * invoice nobody had ever seen, until home was reached a second time. The
     * request is marked as an older one here, whether or not anything is
     * being watched, so its answer is dropped (`openReceiveNow`). */
    this._invoiceRun = (this._invoiceRun || 0) + 1;
    if (!this._watching && !this._stopWatch) return;
    console.log('[foxy] receive: home, so the invoice watch stops; the sweep has the quote');
    this.stopReceive();
  }

  componentDidUpdate(prevProps, prevState) {
    // every screen the person is actually shown, in order
    if (prevState && prevState.screen !== this.state.screen) {
      this.noteScreen(prevState);
      // landing on a token's own screen: ask the mint about it at once
      if (this.state.screen === 'tokenOut') this.tokenWatchNow();
      if (this.state.screen === 'home') this.endReceiveAtHome();
      // a code somebody was asked to scan goes with the token it belonged to
      if (prevState.screen === 'tokenOut' && this.hideStage) this.hideStage('needScan');
      // a receive's amount screen: the road to the mint is opened while the amount is typed
      if (this.state.screen === 'amount' && this.state.flow === 'receive') {
        const Ww = window.FoxyWallet;
        if (Ww && Ww.warmMint && !(this.offlineNow && this.offlineNow())) Ww.warmMint();
      }
      // the camera opened for a reason says it only while it is open
      if (prevState.screen === 'sendScan' && this.state.scanWhy) this.setState({ scanWhy: '' });
    }
    // the token screen's QR code animates while it is open (syncTokenQr)
    this.syncTokenQr();
    // and the receive screen's, where a request with two transports on it is
    // too dense for one static code on a small phone (07-history-tokens-mints.js)
    this.syncReqQr();
    // the agreed price is forgotten once its screen has gone, and not before
    // (24-render-receive-and-send.js)
    if (this.state.screen !== 'priceConfirm' && (this.state.priceQ || this.state.priceSaid)) {
      this.setState({ priceQ: null, priceSaid: false });
    }
    // words typed on the phone for restore are forgotten there, however the
    // restore screens are left — Back, a card's CLOSE, or anything else
    const restoring = s => s === 'importSeed' || s === 'rsConfirm';
    if (prevState && restoring(prevState.screen) && !restoring(this.state.screen)
        && this._rsCandidates && this._rsCandidates.size) {
      if (this.state.rsCandidate) this.setState({ rsCandidate: null });
      this.forgetRestoreCandidates(null);
    }
    /* A payment typed in dollars is fixed in sats as its confirmation opens,
     * and that is what is shown and sent (sendAmountText, startSendNow). */
    if (this.state.screen === 'sendConfirm' && (!prevState || prevState.screen !== 'sendConfirm')) {
      const typed = this.state.recipientKind !== 'invoice' && this.state.unit !== 'SATS';
      if (typed) this.checkSendPrice();
      else if (this.state.sendSats || this.state.sendPriceCheck) this.setState({ sendSats: null, sendPriceCheck: null });
    }
    // the send confirmation needs a fee before the person decides, not after
    if (this.state.screen === 'sendConfirm') this.quoteSendFee();
    this.syncUnit();
    this.syncQueue();
    this.syncSlide();
    this.syncPreview();
    this.syncInbox();
    this.syncTap();
    this.syncClaim();
    this.syncAwake();
    this.syncShake();
    this.syncFlip();
    this.syncAccent();
    this.pushToNative();
    this.syncHaptics();
    /* The ride is what home opens with, every time it is opened.
     *
     * The price panel is part of the shell and its marker outlives a trip to
     * another screen, so the element's own ref fires once and never again —
     * arriving back at home has to say so itself. The first real price series
     * can also land after the screen is already up, which is the second case
     * here. */
    this.syncSnow();
    this.markerStayGone();
    const home = this.state.screen === 'home';
    if (this._marker && home && this._wasHome === false) {
      this._rolled = this.riderShow();
    } else if (this._marker && home && !this._rolled) {
      this._rolled = this.riderShow();
    }
    this._wasHome = home;
  }

  press(ch) {
    /* Dollars are typed cents first, the way a card terminal takes them:
     * 5 is $0.05, 50 is $0.50, 500 is $5.00. The amount is still kept as a
     * decimal string ("5.00"), so everything that reads it (wantedSats, the
     * deep links, toggleUnit) goes on reading it. "00" appends two zeros in
     * either unit; it replaced the decimal point, which this entry has no
     * use for. */
    this.setState(p => {
      let a = p.amount;
      if (p.unit !== 'SATS') {
        let d = a.replace('.', '').replace(/^0+/, '');
        if (ch === 'del') d = d.slice(0, -1);
        else if (/^[0-9]+$/.test(ch)) { if (d.length + ch.length > 9) return { amount: a }; d += ch; }
        else return { amount: a };
        d = d.replace(/^0+/, '');
        if (d === '') return { amount: '' };
        d = d.padStart(3, '0');
        return { amount: d.slice(0, -2) + '.' + d.slice(-2) };
      }
      if (ch === 'del') return { amount: a.slice(0, -1) };
      if (!/^[0-9]+$/.test(ch)) return { amount: a };
      if (a === '0' || a === '') { if (ch === '00') return { amount: a }; return { amount: ch }; }
      if (a.length + ch.length > 9) return { amount: a };
      return { amount: a + ch };
    });
  }

  toggleUnit() {
    /* No price, no conversion — the same rule wantedSats() follows.
     *
     * px() answers null until a price has landed, and dividing by it made the
     * amount the string "Infinity", which then went on into the send and
     * receive flows as a figure. The other direction was quieter and just as
     * wrong: it multiplied by null and wrote "0.00" over what was typed. */
    /* Offline, asking to be paid has no other unit to swap to: this phone is
     * refusing to convert, which is the whole of why it is asking in dollars
     * (`dollarsOnly`). The control is not on screen either; this is the half
     * that holds if anything else reaches it. */
    if (this.dollarsOnly()) {
      this.toast('Offline, Foxy asks in dollars \u2014 the paying phone works out the sats.', true);
      return;
    }
    const px = this.px();
    if (!px) { this.toast('No bitcoin price yet \u2014 amounts stay in ' + this.state.unit + '.', true); return; }
    this.setState(p => {
      const v = parseFloat(p.amount) || 0;
      if (p.unit === 'USD') return { unit: 'SATS', amount: v ? String(Math.round(v / px * 1e8)) : '' };
      return { unit: 'USD', amount: v ? (v / 1e8 * px).toFixed(2) : '' };
    });
  }

  group(n) {
    if (n == null || !isFinite(n)) return '···';
    return Number(n).toLocaleString('en-US');
  }

  // ---- balance credit animation ----
  // dismissing a payment confirmation lands you on home, where the pill counts up from the
  // old balance to the new one. The committed balance is state; the count-up is a lerp
  // from animFrom → committed, so an interrupted animation still ends on the right number.
  balNow() {
    const s = this.state;
    const to = { usd: s.balUsd, sats: s.balSats };
    if (to.sats == null) return to;
    if (!s.animFrom) return to;
    const t = s.animT || 0;
    const e = 1 - Math.pow(1 - t, 3);
    return {
      usd: s.animFrom.usd + (to.usd - s.animFrom.usd) * e,
      sats: Math.round(s.animFrom.sats + (to.sats - s.animFrom.sats) * e),
    };
  }

  /* Count from the balance before the change to whatever the wallet says now.
   *
   * moveBalance() reads the typed amount to work out the size of the move,
   * which is fine for the prototype's flows and useless for a real one: by the
   * time a confirmation is dismissed the keypad has been cleared, and an ecash
   * token never had an amount typed at all. So it bailed before animating.
   * This asks the wallet instead and needs no amount.
   */
  settleAnimate(lane) {
    // Without a snapshot there is nothing to count from: the pill already
    // holds the new figure, so the animation would run from a number to
    // itself — and worse, it cancels one that is still playing. A second
    // caller arriving a moment later is what made the count-up vanish.
    const from = this._preSettle;
    if (!from) return;
    this._preSettle = null;
    clearInterval(this._balT);
    const ok = this.animateToLive(from, lane || 'btc');
    console.log('[foxy] balance animation: from', from.sats, '| wallet asked:', ok);
    if (!ok) this.runBalanceAnim();
  }

  // shared by the receive invoice and the scan confirm
  openNote() {
    const s = this.state;
    this.setState({ noteOpen: true, noteDraft: s.note || '', kbShift: !(s.note || '').length, kbSymbols: false });
  }

  // native keyboards need the focus to land after the screen transition, so retry a few times.
  // the ref identity is stable (see renderVals) and detach is treated as transient — a ref swap
  // must never cancel a pending focus, or the mount render burst eats every attempt.
  autoFocus(key, el) {
    if (this.props.startStatic) return;
    const flagK = '_af_' + key, timerK = '_afT_' + key, nodeK = '_afN_' + key;
    if (el) {
      if (this[flagK] && this[nodeK] === el) return;
      this[nodeK] = el;
      this[flagK] = true;
      (this[timerK] || []).forEach(clearTimeout);
      try { el.focus({ preventScroll: true }); } catch (e) {}
    Promise.resolve().then(() => { const n = this[nodeK]; if (n && document.contains(n) && document.activeElement !== n) { try { n.focus({ preventScroll: true }); } catch (e) {} } });
    this[timerK] = [60, 200, 420, 700].map(ms => setTimeout(() => {
        const n = this[nodeK];
        if (n && document.contains(n) && document.activeElement !== n) {
          try { n.focus({ preventScroll: true }); } catch (e) {}
        }
      }, ms));
      return;
    }
    // only give up once the node has genuinely left the document
    setTimeout(() => {
      const n = this[nodeK];
      if (n && !document.contains(n)) {
        (this[timerK] || []).forEach(clearTimeout);
        this[timerK] = null; this[flagK] = false; this[nodeK] = null;
      }
    }, 500);
  }


  // sign 1 = money in (received), -1 = money out (sent) — same count animation either way
  runBalanceAnim() {
    const start = Date.now(), DUR = 1150;
    clearInterval(this._balT);
    this._balT = setInterval(() => {
      const t = Math.min((Date.now() - start) / DUR, 1);
      this.setState({ animT: t });
      if (t >= 1) { clearInterval(this._balT); this.setState({ animFrom: null, animLane: null }); }
    }, 40);
  }

  // called on settlement, never on submit — the balance must not move before the money does.
  // home-screen money art: one graphic per denomination with a count, not one per unit
  display() {
    const a = this.state.amount;
    if (a === '') return '0.00';
    const dot = a.indexOf('.');
    if (this.state.unit !== 'SATS') {
      const whole = (dot < 0 ? a : a.slice(0, dot)) || '0';
      const cents = dot < 0 ? '' : a.slice(dot + 1);
      return this.group(whole) + '.' + (cents + '00').slice(0, 2);
    }
    if (dot < 0) return this.group(a);
    return this.group(a.slice(0, dot) || 0) + '.' + a.slice(dot + 1);
  }

  // Sat Symbol (satsymbol.com) — one vertical stem crossed by three evenly
  // spaced horizontals, square ends. Open, unrestricted use per the project.
  // a storm of small bolts sweeping top-right to bottom-left, all inside ~1s
  boltField(active) {
    const R = React.createElement;
    const rnd = n => { const x = Math.sin(n * 12.9898 + 78.233) * 43758.5453; return x - Math.floor(x); };
    const bolts = [];
    // 96 of these was three times what the screen can show at once, and each
    // one is a filtered <img> on its own layer. The spread is by t, so fewer
    // bolts cover the same width rather than crowding into part of it.
    for (let i = 0; i < 32; i++) {
      const t = i / 31;
      bolts.push(R('img', {
        key: 'blt' + i,
        src: (window.__resources && window.__resources.bolt) || 'assets/bolt-on-dark.svg', alt: '',
        style: {
          position: 'absolute',
          left: (18 + t * 100 + (rnd(i) - 0.5) * 14) + '%',
          top: (-72 + rnd(i + 40) * 62) + '%',
          height: 24 + Math.round(rnd(i + 80) * 44), width: 'auto', opacity: 0,
          filter: 'drop-shadow(0 0 13px rgba(255,242,4,.9))',
          animation: active ? 'boltRain ' + (450 + Math.round(rnd(i + 120) * 192)) + 'ms cubic-bezier(.45,0,.85,.55) both' : 'none',
          animationDelay: Math.round(Math.pow(rnd(i + 160), 1.7) * 300) + 'ms',
        },
      }));
    }
    return R('div', { style: { position: 'absolute', inset: 0, overflow: 'hidden', pointerEvents: 'none' } }, bolts);
  }

  satCoinEl(i, phase, fill, count, D, label, tint) {
    const R = React.createElement;
    const partial = fill != null;
    const t = tint || { sand: 'linear-gradient(150deg,#FFE9A8 0%,#F7C24E 26%,#E19420 62%,#B96B0D 100%)', rim: 'rgba(255,214,150,.62)' };
    const pct = partial ? fill : 100;
    const rnd = n => { const x = Math.sin((i + 1) * 12.9898 + n * 78.233) * 43758.5453; return x - Math.floor(x); };
    // droplet count derives from the molten band's area so a shallow coin gets
    // fewer drops instead of a solid blob; ~50% coverage keeps each one legible
    const bandArea = Math.PI * (D / 2) * (D / 2) * (pct / 100);
    const avgDrop = Math.PI * Math.pow(D * 0.041 / 2, 2);
    const byArea = Math.round(bandArea / Math.max(avgDrop, 1) * 0.5);
    // droplets are only legible on a reasonably large coin — below that, and on
    // dense receipts, the pool fill alone carries the effect
    const budget = Math.floor(620 / Math.max(count, 1));
    // only the ragged partial coin melts in; whole coins land already solid gold
    const grainN = (!partial || D < 40 || count > 40) ? 0 : Math.max(8, Math.min(byArea, budget, 24));
    const inDelay = 120 + i * this.step(count, 26, 4300);
    const dropMs = 300, dropGap = Math.max(9, 1000 / grainN);
    // the pool only rises as fast as the droplets land in it
    const fillDelay = grainN ? inDelay + dropMs * 0.72 : inDelay;
    const fillMs = grainN ? Math.max(420, Math.round(dropGap * (grainN - 1) + dropMs)) : 620;
    const fillSteps = grainN ? Math.min(grainN, 40) : 1;
    const grains = [];
    for (let g = 0; g < grainN; g++) { // eslint-disable-line
      const sz = Math.max(2.5, +(D * (0.03 + rnd(g) * 0.024)).toFixed(1));
      // each droplet lands on the pool surface as it stands when that droplet arrives
      const level = Math.max(pct * ((g + 1) / grainN) - 4, 2);
      grains.push(R('div', {
        key: 'g' + g + phase,
        style: {
          position: 'absolute', left: (8 + rnd(g + 40) * 78) + '%',
          bottom: 'calc(' + level + '% - ' + Math.round(sz * 0.45) + 'px)',
          width: sz, height: sz, borderRadius: '50%',
          background: 'radial-gradient(circle at 34% 28%,#FFF3CE 0%,#F7C24E 44%,#D08616 100%)',
          boxShadow: '0 1px 2px rgba(90,45,2,.45)',
          animation: (phase === 'out' ? 'grainOut .4s ease-in both' : 'dropMelt ' + dropMs + 'ms cubic-bezier(.4,.05,.6,1) both'),
          animationDelay: (phase === 'out' ? (g % 24) * 9 : Math.round(inDelay + g * dropGap)) + 'ms',
        },
      }));
    }
    return R('div', {
      key: 's' + i + phase,
      style: {
        position: 'relative', width: D, height: D, borderRadius: '50%', boxSizing: 'border-box', flex: 'none',
        border: partial ? '2px dashed rgba(242,163,66,.8)' : '2.5px solid ' + t.rim,
        background: partial ? 'rgba(220,127,28,.1)' : 'radial-gradient(circle at 32% 26%,rgba(255,255,255,.28),rgba(255,255,255,0) 58%), #7A4409',
        boxShadow: partial ? 'none' : '0 5px 12px rgba(0,0,0,.36)',
        overflow: 'hidden', isolation: 'isolate', WebkitMaskImage: '-webkit-radial-gradient(white, black)',
        animation: (phase === 'out' ? 'coinOut .46s' : 'coinIn .44s') + ' cubic-bezier(.2,.9,.25,1) both',
        animationDelay: (phase === 'out' ? (count - 1 - i) * this.step(count, 11) : i * this.step(count, 34)) + 'ms',
      },
    }, [
      R('div', {
        key: 'sand',
        style: {
          position: 'absolute', left: 0, right: 0, bottom: 0, height: pct + '%',
          background: t.sand,
          boxShadow: 'inset 0 2px 5px rgba(255,255,255,.5), inset 0 -3px 0 rgba(90,45,2,.42)',
          transformOrigin: 'bottom',
          animation: phase === 'out' ? 'sandFall .42s ease-in both' : (partial ? 'sandRise ' + fillMs + 'ms steps(' + fillSteps + ', end) both' : 'none'),
          animationDelay: (phase === 'out' ? i * 10 : fillDelay) + 'ms',
        },
      }),
      R('div', {
        key: 'shine',
        style: {
          position: 'absolute', left: '-40%', top: 0, width: '55%', height: '100%',
          background: 'linear-gradient(100deg,rgba(255,255,255,0) 0%,rgba(255,255,255,.5) 50%,rgba(255,255,255,0) 100%)',
          transform: 'skewX(-16deg)', pointerEvents: 'none', opacity: partial ? 0.35 : 1,
          animation: (phase === 'out' || count > 40) ? 'none' : 'goldSheen 1.15s ease-out both',
          animationDelay: (fillDelay + fillMs) + 'ms',
        },
      }),
      R('div', {
        key: 'ridge',
        style: (function () {
          const teeth = Math.max(20, Math.min(46, Math.round(D * 0.62)));
          const a = 180 / teeth;
          const mask = 'radial-gradient(circle at 50% 50%, transparent 0 ' + (partial ? 84 : 79) + '%, #000 ' + (partial ? 86 : 82) + '%, #000 100%)';
          return {
            position: 'absolute', inset: 0, borderRadius: '50%', pointerEvents: 'none',
            background: 'repeating-conic-gradient(from 0deg, rgba(255,240,200,.62) 0deg ' + a + 'deg, rgba(112,60,4,.5) ' + a + 'deg ' + (a * 2) + 'deg)',
            WebkitMaskImage: mask, maskImage: mask, opacity: partial ? 0.4 : 0.85,
            mixBlendMode: 'overlay',
          };
        })(),
      }),
      R('div', { key: 'gr', style: { position: 'absolute', inset: 0 } }, grains),
      R('div', {
        key: 'gl',
        style: { position: 'absolute', inset: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', opacity: partial ? 0.5 : 0.62 },
      }, R('div', {
        style: {
          display: 'flex', alignItems: 'center', gap: Math.max(1, Math.round(D * 0.03)),
          fontSize: Math.max(6, Math.round(D * (((label || '10K').length >= 4) ? 0.21 : (label || '10K').length === 3 ? 0.25 : 0.3))),
          fontWeight: 800, letterSpacing: '-0.03em', lineHeight: 1,
          color: partial ? 'rgba(var(--ink-rgb),.85)' : (tint && tint.ink) || '#5C3208', fontFamily: 'Figtree,system-ui,sans-serif',
        },
      }, [R('span', { key: 'btc', style: { fontWeight: 700 } }, '\u20BF'), R('span', { key: 'v' }, label || '10K')])),
    ]);
  }

  // 10 coins (100k sats) pile up like poker chips; piles then tile the space
  // the whole payout must land inside 5s no matter how many pieces there are
  step(total, base, budget) {
    return Math.min(base, (budget || 4400) / Math.max((total || 1) - 1, 1));
  }

  // the stack sizes itself to whatever height the container actually has, so coins never clip
  fitStack(build) {
    const R = React.createElement;
    if (!this._FitStack) {
      this._FitStack = function (props) {
        const ref = React.useRef(null);
        const [h, setH] = React.useState(0);
        React.useEffect(() => {
          const el = ref.current;
          if (!el) return;
          const read = () => setH(el.clientHeight);
          read();
          if (typeof ResizeObserver === 'undefined') return;
          const ro = new ResizeObserver(read);
          ro.observe(el);
          return () => ro.disconnect();
        }, []);
        return R('div', { ref: ref, style: { width: '100%', height: '100%' } }, h > 20 ? props.build(h - 2) : null);
      };
    }
    return R(this._FitStack, { build: build });
  }

  satsStack(sats, phase, avail) {
    const R = React.createElement;
    phase = phase || 'in';
    const AW = 322, AH = avail || 452, G = 10;
    const SAND = 'linear-gradient(150deg,#FFE9A8 0%,#F7C24E 26%,#E19420 62%,#B96B0D 100%)';
    // rims alternate black/white by denomination rank so adjacent tiers read apart at a glance
    const DENOMS = [
      { v: 100000000, l: '100M', s: 1, sand: SAND, rim: '#0B0B0B', ink: '#0B0B0B' },
      { v: 10000000, l: '10M', s: 0.94, sand: SAND, rim: '#0B0B0B', ink: '#0B0B0B' },
      { v: 1000000, l: '1M', s: 0.88, sand: SAND, rim: '#0B0B0B', ink: '#0B0B0B' },
      { v: 100000, l: '100K', s: 0.8, sand: SAND, rim: '#0B0B0B', ink: '#0B0B0B' },
      { v: 10000, l: '10K', s: 0.72, sand: SAND, rim: '#0B0B0B', ink: '#0B0B0B' },
      { v: 5000, l: '5K', s: 0.64, sand: SAND, rim: '#0B0B0B', ink: '#0B0B0B' },
      { v: 1000, l: '1K', s: 0.56, sand: SAND, rim: '#0B0B0B', ink: '#0B0B0B' },
    ];
    // greedy denomination break-down; anything under 1K rides on a partial 1K coin
    let rest = Math.max(0, Math.round(sats));
    const groups = [];
    DENOMS.forEach(d => {
      const k = Math.floor(rest / d.v);
      rest -= k * d.v;
      if (k > 0) groups.push({ d: d, n: k });
    });
    const partialFill = rest > 0 ? +(rest / 1000 * 100).toFixed(1) : null;
    const nCoins = groups.reduce((a, g) => a + g.n, 0) + (partialFill != null ? 1 : 0);
    if (!nCoins) return null;
    // each denomination fans out left to right, the way loose change does
    const lift = 0.62;
    const measure = base => {
      const lanes = [];
      groups.forEach(g => {
        const dia = Math.max(12, Math.round(base * g.d.s));
        const st = Math.max(4, Math.round(dia * lift));
        const maxN = Math.max(1, Math.floor((AW - dia) / st) + 1);
        // split an overflowing denomination into even lanes (8 → 4+4, never 6+2)
        const laneCount = Math.ceil(g.n / maxN);
        let left = g.n;
        for (let i = 0; i < laneCount; i++) {
          const n = Math.ceil(left / (laneCount - i));
          lanes.push({ d: g.d, n: n, dia: dia, st: st, w: dia + st * (n - 1) });
          left -= n;
        }
      });
      if (partialFill != null) {
        const pd = DENOMS[DENOMS.length - 1];
        const dia = Math.max(12, Math.round(base * pd.s));
        lanes.push({ d: pd, n: 1, dia: dia, st: 0, w: dia, partial: true });
      }
      // best-fit packing so small tiers tuck in beside big ones instead of stranding a row
      const rows = [];
      lanes.forEach(l => {
        /** @type {{ w: number, h: number, lanes: any[] } | null} */
        let best = null;
        let bestLeft = Infinity;
        rows.forEach(r => {
          const leftOver = AW - (r.w + G + l.w);
          if (leftOver >= 0 && leftOver < bestLeft) { best = r; bestLeft = leftOver; }
        });
        if (!best) { rows.push({ w: l.w, h: l.dia, lanes: [l] }); return; }
        best.w += G + l.w; best.h = Math.max(best.h, l.dia); best.lanes.push(l);
      });
      return { rows: rows, total: rows.reduce((a, r) => a + r.h, 0) + Math.max(rows.length - 1, 0) * G };
    };
    let m = measure(30);
    for (let b = 116; b >= 16; b -= 2) { m = measure(b); if (m.total <= AH) break; }
    let seq = 0;
    const rowEls = m.rows.map((row, ri) => R('div', {
      key: 'srow' + ri,
      style: { display: 'flex', alignItems: 'center', justifyContent: 'center', gap: G, flex: 'none', height: row.h },
    }, row.lanes.map((l, li) => {
      const coins = [];
      for (let k = 0; k < l.n; k++) {
        coins.push(R('div', {
          key: 'sl' + k,
          style: { position: 'absolute', left: k * l.st, top: 0, zIndex: k },
        }, this.satCoinEl(seq, phase, l.partial ? partialFill : null, nCoins, l.dia, l.d.l, l.d)));
        seq++;
      }
      return R('div', {
        key: 'lane' + ri + '-' + li,
        style: { position: 'relative', flex: 'none', width: l.w, height: l.dia },
      }, coins);
    })));
    return R('div', {
      style: { width: '100%', height: '100%', display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: G },
    }, rowEls);
  }

  syncAccent() {
    const a = ACC_OF(this.state.accent);
    const r = document.documentElement.style;
    r.setProperty('--acc', a.acc);
    r.setProperty('--acc-lt', a.lt);
    r.setProperty('--acc-dk', a.dk);
    r.setProperty('--acc-rgb', a.rgb);
    this.syncStatusBar();
  }

  // the device's own status bar is painted by iOS, not us — these metas are the only lever.
  // 'default' gives black glyphs (light mode); 'black-translucent' gives white (dark mode).
  syncStatusBar() {
    const light = (this.props.startTheme || this.state.theme) === 'light';
    const want = light ? 'default' : 'black-translucent';
    const bar = document.querySelector('meta[name="apple-mobile-web-app-status-bar-style"]');
    if (bar && bar.getAttribute('content') !== want) bar.setAttribute('content', want);
    const tc = document.querySelector('meta[name="theme-color"]');
    const col = light ? '#FAFAF8' : '#050505';
    if (tc && tc.getAttribute('content') !== col) tc.setAttribute('content', col);
  }

  shellRef = React.createRef();
  // ---- Split a bill ----
  // Self-contained: every state key is sp-prefixed and every hole is sp-namespaced, so
  // nothing here can collide with an existing screen. The flow ends by handing off to
  // the app's own send scanner.
  spMoney(c) { return '$ ' + this.usd(c / 100); }
  spCents() { return parseInt(this.state.spAmt || '0', 10); }
  spWaysN() { return this.state.spWays || 4; }
  spOthers() { return this.spWaysN() - 1; }

  spEven() {
    const n = this.spWaysN(), base = Math.floor(this.spCents() / n), a = [];
    for (let i = 0; i < n; i++) a.push(base);
    a[0] += this.spCents() - base * n;
    return a;
  }

  spSharesArr() {
    const v = this.state.spShares;
    return (v && v.length === this.spWaysN()) ? v.slice() : this.spEven();
  }

  spSlots() {
    const a = (this.state.spAssigns || []).slice();
    while (a.length < this.spOthers()) a.push({ type: 'qr' });
    return a.slice(0, this.spOthers());
  }

  spPaidArr() {
    const p = (this.state.spPaid || []).slice();
    while (p.length < this.spOthers()) p.push(false);
    return p.slice(0, this.spOthers());
  }

  spNextUnpaid() {
    const p = this.spPaidArr();
    for (let i = 0; i < p.length; i++) if (!p[i]) return i;
    return -1;
  }

  spInitials(n) {
    return n.split(' ').filter(Boolean).slice(0, 2).map(w => w[0].toUpperCase()).join('');
  }

  splitVals(s, sc) {
    const sh = this.spSharesArr();
    const slots = this.spSlots();
    const paid = this.spPaidArr();
    const paidCount = paid.filter(Boolean).length;
    const nu = this.spNextUnpaid();
    const cur = slots[s.spIdx || 0] || { type: 'qr' };
    const isQrSlot = cur.type !== 'contact';
    const idx = s.spIdx || 0;
    const lastPayer = idx >= this.spOthers() - 1;
    const diff = this.spCents() - sh.reduce((a, b) => a + b, 0);
    const v = {
      spIsAmount: sc === 'spAmount', spIsWays: sc === 'spWays', spIsShares: sc === 'spShares',
      spIsPayer: sc === 'spPayer', spIsAssign: sc === 'spAssign',
      spIsWaiting: sc === 'spWaiting', spIsAllPaid: sc === 'spAllPaid',

      goSplit: () => this.setState(p => ({
        screen: 'spAmount', stack: p.stack.concat([p.screen]),
        spAmt: '0', spWays: 4, spIdx: 0, spAssigns: [], spPaid: [], spShares: null, spInvoices: [],
        // the network this person asked to start on (FoxyWallet.defaultRail);
        // on-chain is not a way to collect a share, so it is not one here
        spRail: (window.FoxyWallet && window.FoxyWallet.defaultRail
          && window.FoxyWallet.defaultRail() === 'CASHU') ? 'CASHU' : 'LIGHTNING',
        spEditIdx: -1, spEditBuf: '', spCopied: -1, spShared: -1, spFromWaiting: false,
      })),
      spBack: () => {
        if (sc === 'spPayer' && s.spFromWaiting) return this.setState({ screen: 'spWaiting', spFromWaiting: false });
        if (sc === 'spPayer' && idx > 0) return this.setState({ spIdx: idx - 1 });
        if (sc === 'spAssign') return this.setState({ screen: 'spPayer' });
        this.back();
      },
      spRestartPhone: () => this.setState({ screen: 'home', stack: [] }),

      spAmtDisp: this.spMoney(this.spCents()),
      spAmtInk: this.spCents() > 0 ? 'var(--ink)' : 'rgba(var(--ink-rgb),.3)',
      spCollectedDisp: this.spMoney(sh.slice(1).reduce((a, b) => a + b, 0)),
      spYourShareDisp: this.spMoney(sh[0]),
      spOthersCount: this.spOthers() + (this.spOthers() === 1 ? ' PERSON' : ' PEOPLE'),
    };

    /* The pad, in the same eleven cells as the send/receive pad — so 0 and the
     * delete key stay in the same two columns on both — but counting in cents:
     * 5 then 0 is $0.50 here.
     *
     * Which is why there is no decimal point: on a pad whose decimal point is
     * always in the number there is nothing for it to do. Its cell holds "00",
     * two zeros at once, the same as the send/receive pad since that one went
     * cents-first too. On an empty amount "00" types nothing, like "0".
     */
    const SP_PAD = ['1','2','3','4','5','6','7','8','9','00','0'];
    v.spKeys = SP_PAD.map(l => ({
      label: l,
      tap: () => {
        const n = ((s.spAmt || '0') === '0' ? '' : s.spAmt) + l;
        if (n === '00') return;
        if (n.length > 9) return;
        this.setState({ spAmt: n, spShares: null });
      },
    }));
    v.spDel = () => this.setState({ spAmt: (s.spAmt || '0').length > 1 ? s.spAmt.slice(0, -1) : '0', spShares: null });
    /* Any bill, however small.
     *
     * There used to be a flat $2.00 floor here. It was never the real
     * constraint — it was a round number standing in for one. What actually
     * has to hold is that every payer ends up owing something: spEven() floors
     * the division, so a penny split eight ways gives one person 1c and seven
     * people nothing, and Foxy would go on to make invoices for $0.00.
     *
     * That constraint needs the number of ways, which is chosen on the NEXT
     * screen, so it is enforced there (spWaysNext) where the figure exists.
     * Here the only question is whether an amount was typed at all. */
    const amtOk = this.spCents() > 0;
    v.spAmtBtnBg = amtOk ? 'var(--acc)' : 'var(--chip)';
    v.spAmtBtnInk = amtOk ? '#fff' : 'rgba(var(--ink-rgb),.28)';
    v.spAmtBtnSh = amtOk ? 'inset 0 2px 0 rgba(255,255,255,.34),inset 0 -3px 0 rgba(0,0,0,.22),0 10px 20px rgba(0,0,0,.34)' : 'none';
    v.spAmtBtnAnim = amtOk ? 'shineLoop 4.6s ease-in-out 3s infinite' : 'none';
    /* A grey NEXT that says nothing is a wall: a bill that would not go
     * anywhere just failed silently, and attempts were lost to it. The button
     * still refuses, and now it
     * says why. The screen has no room of its own for the reason — every other
     * word on it is fixed markup — so it is said on the tap. */
    v.spAmtNext = () => {
      if (!amtOk) { this.toast('Type an amount first.', true); return; }
      this.go('spWays');
    };

    v.spWayOpts = [2,3,4,5,6,7,8].map(n => {
      const on = this.spWaysN() === n;
      return {
        n: n, bg: on ? 'var(--acc)' : 'var(--surface)',
        border: on ? 'var(--acc)' : 'rgba(var(--ink-rgb),.12)',
        fg: on ? '#fff' : 'var(--ink)',
        sh: on ? 'inset 0 2px 0 rgba(255,255,255,.3),0 8px 16px rgba(0,0,0,.3)' : 'none',
        pick: () => this.setState({ spWays: n, spIdx: 0, spAssigns: [], spPaid: [], spShares: null }),
      };
    });
    /* The floor that is real, checked where the numbers both exist.
     *
     * spEven() floors the division, so a bill smaller than the number of ways
     * leaves somebody owing $0.00 — and Foxy would then make them an invoice
     * for nothing. Splitting 3 cents four ways is the smallest case that bites.
     * The shares screen refuses a $0.00 share too (spSharesNext), but by then
     * the person has walked past two screens to be told; this says it at the
     * moment the number of ways is chosen. */
    v.spWaysNext = () => {
      if (this.spCents() < this.spWaysN()) {
        this.toast(this.spMoney(this.spCents()) + ' does not divide '
          + this.spWaysN() + ' ways.', true);
        return;
      }
      this.go('spShares');
    };

    v.spSharesSub = this.spWaysN() + ' payers';
    const order = [];
    for (let i = 1; i < sh.length; i++) order.push(i);
    order.push(0);
    v.spShareRows = order.map(i => {
      const isLeader = i === 0;
      const sl = !isLeader ? slots[i - 1] : null;
      const isC = sl && sl.type === 'contact';
      const off = s.spShares != null && sh[i] !== this.spEven()[i];
      return {
        name: isLeader ? 'You' : (isC ? sl.name : 'Payer ' + (i + 1)),
        sub: isLeader ? 'The rest of the bill' : (off ? 'Custom amount' : 'Even share'),
        subInk: off ? 'var(--acc-ink)' : 'rgba(var(--ink-rgb),.42)',
        ini: isLeader ? 'YOU' : (isC ? sl.ini : String(i + 1)),
        avBg: isLeader ? 'rgba(var(--acc-rgb),.18)' : (isC ? 'var(--acc)' : 'var(--chip)'),
        avInk: isLeader ? 'var(--acc-ink)' : (isC ? '#fff' : 'rgba(var(--ink-rgb),.55)'),
        avRadius: (isC || isLeader) ? '50%' : '14px',
        amt: this.spMoney(sh[i]), amtInk: 'var(--ink)',
        rowCursor: isLeader ? 'default' : 'pointer',
        boxBg: isLeader ? 'transparent' : (off ? 'rgba(var(--acc-rgb),.12)' : 'var(--chip)'),
        boxBorder: isLeader ? 'transparent' : (off ? 'rgba(var(--acc-rgb),.5)' : 'transparent'),
        edit: () => { if (!isLeader) this.setState({ spEditIdx: i, spEditBuf: '0' }); },
      };
    });
    v.spBalShown = diff !== 0;
    v.spBalLabel = diff > 0 ? 'STILL TO ALLOCATE' : 'OVER THE BILL BY';
    v.spBalAmt = this.spMoney(Math.abs(diff));
    v.spBalInk = '#FF5C5C';
    const shOk = diff === 0 && sh.every(x => x > 0);
    v.spShNextBg = shOk ? 'var(--acc)' : 'var(--chip)';
    v.spShNextInk = shOk ? '#fff' : 'rgba(var(--ink-rgb),.28)';
    v.spShNextSh = shOk ? 'inset 0 2px 0 rgba(255,255,255,.34),inset 0 -3px 0 rgba(0,0,0,.22),0 10px 20px rgba(0,0,0,.34)' : 'none';
    v.spShNextAnim = shOk ? 'shineLoop 4.6s ease-in-out 3s infinite' : 'none';
    /* Grey here has two causes and the screen only shows one of them: the
     * red balance line covers shares that do not add up, and says nothing
     * about a share left at $0.00. Both are said on the tap that is refused.
     */
    v.spSharesNext = () => {
      if (!shOk) {
        this.toast(diff !== 0
          ? 'The shares have to add up to the bill.'
          : 'Every share needs an amount.', true);
        return;
      }
      this.setState(p => ({ screen: 'spPayer', spIdx: 0, stack: p.stack.concat([p.screen]) }));
      this.spStart();
    };

    v.spEditOpen = (s.spEditIdx != null && s.spEditIdx >= 0);
    const eSlot = s.spEditIdx > 0 ? slots[s.spEditIdx - 1] : null;
    v.spEditName = s.spEditIdx === 0 ? 'YOUR SHARE'
      : (eSlot && eSlot.type === 'contact' ? eSlot.name : 'PAYER ' + ((s.spEditIdx || 0) + 1));
    v.spEditDisp = this.spMoney(parseInt(s.spEditBuf || '0', 10));
    // the same eleven cells, the same cents, the same blank where a decimal
    // point used to be drawn and ignored
    v.spEditKeys = SP_PAD.map(l => ({
      label: l,
      tap: () => {
        const n = ((s.spEditBuf || '0') === '0' ? '' : s.spEditBuf) + l;
        if (n === '00' || n.length > 9) return;
        this.setState({ spEditBuf: n });
      },
    }));
    v.spEditDel = () => this.setState({ spEditBuf: (s.spEditBuf || '0').length > 1 ? s.spEditBuf.slice(0, -1) : '0' });
    v.spEditCancel = () => this.setState({ spEditIdx: -1, spEditBuf: '' });
    v.spEditStop = (e) => { if (e && e.stopPropagation) e.stopPropagation(); };
    v.spEditDone = () => {
      const a = this.spSharesArr();
      a[s.spEditIdx] = parseInt(s.spEditBuf || '0', 10);
      if (s.spEditIdx !== 0) a[0] = this.spCents() - a.slice(1).reduce((x, y) => x + y, 0);
      this.setState({ spShares: a, spEditIdx: -1, spEditBuf: '' });
    };

    v.spPayerStep = s.spFromWaiting ? 'COLLECTING' : (idx + 1) + ' OF ' + this.spOthers();
    v.spPayerTitle = 'PAYER ' + (idx + 2);
    v.spPayerSub = isQrSlot ? 'Scan, Tap or Share' : 'Assigned to a contact';
    v.spPayerIsQr = isQrSlot;
    v.spPayerIsContact = !isQrSlot;
    v.spPayerAmtDisp = this.spMoney(sh[idx + 1]);
    v.spAssignedName = cur.name || '';
    v.spAssignedHandle = cur.handle || '';
    v.spAssignedIni = cur.ini || '';
    const spInvoice = (s.spInvoices || [])[idx] || '';
    // CASHU: a payment request for this share (railRequest), taken back with SCAN
    const spCashu = s.spRail === 'CASHU' && /^sp/.test(String(s.screen || ''));
    const spInv = (spCashu && spInvoice && window.FoxyWallet)
      ? this.railRequest(window.FoxyWallet.amountOf(spInvoice), 'split:' + idx) : spInvoice;
    v.spNetwork = spCashu ? 'CASHU' : 'LIGHTNING';
    v.spQrBolt = !spCashu;
    v.spQrEcash = spCashu;
    v.spQrBolt = !spCashu;
    v.spQrEcash = spCashu;
    v.spPickNetwork = () => this.chooseRail(v.spNetwork, rail => this.setState({ spRail: rail }));
    // error correction H, because the template lays a badge over the middle
    v.spQrSrc = (spInv && window.FoxyWallet)
      ? window.FoxyWallet.qr(spInv, { ecc: 'H' })
      : this.qrLoadingSrc();
    v.spInvoiceReady = !!spInv;
    /* The four digits, over this share's QR, exactly as the receive invoice
     * screen shows them (tapCodeShown). The code arrived and the screen did
     * not draw it: `tapCodeShown` is gated on the confirm screen and its card
     * lives in that screen's markup, so a split payer screen agreed a key,
     * logged "the code is on screen" and showed nothing. The payer was
     * holding four digits to compare against
     * a screen that had none. */
    v.spTapCodeShown = s.screen === 'spPayer' && !!s.tapShownCode && !s.tapCardOff;
    v.spTapCode = s.tapShownCode || '';
    v.spHideTapCode = () => this.setState({ tapCardOff: true });
    v.spDiscard = () => this.spDiscard();
    v.spCopyLabel = s.spCopied === idx ? 'COPIED' : 'COPY';
    v.spShareLabel = s.spShared === idx ? 'SHARED' : 'SHARE';
    v.spCopyInv = () => {
      if (!spInv) { this.toast('That invoice is still being made.', true); return; }
      // a share's code can be a payment request naming this phone's onion
      // address, so it is copied device-only like a token (finding 6)
      if (this.copySecret(spInv)) this.setState({ spCopied: idx, spShared: -1 });
      else this.toast('Could not copy', true);
    };
    v.spShareInv = () => this.setState({ spShared: idx, spCopied: -1 });
    v.spScanToken = () => this.spScanToken(idx);
    /* TAP, on a share. The same press as on the receive screen: it is what
     * puts this phone on the air, and nothing here advertises without it
     * (24-render-receive-and-send.js, TapLink.swift). Each share is its own
     * payment, so each press is its own receiver with its own service UUID —
     * two people paying one bill are not two payments from one number. */
    v.spTapArm = () => this.tapArm();
    v.spTapArmedShown = s.screen === 'spPayer' && !!s.tapArmed && !s.tapShownCode && !s.tapCardOff;
    v.spTapArmedHint = s.tapRecvStage === 'connecting' ? 'CONNECTING\u2026' : 'HOLD A PHONE HERE';
    // the label never changes; the accent is what says it is on the air
    v.spTapArmBg = s.tapArmed ? 'var(--acc)' : 'var(--ink)';
    v.spTapArmInk = s.tapArmed ? '#fff' : 'var(--bg)';
    v.spTapArmLabel = 'TAP';
    v.spEditPayerAmt = () => this.setState({ spEditIdx: idx + 1, spEditBuf: '0' });
    v.spAssignBtnLabel = isQrSlot ? 'ASSIGN TO A CONTACT' : 'CHANGE CONTACT';
    v.spOpenAssign = () => this.setState({ screen: 'spAssign' });
    v.spCloseAssign = () => this.setState({ screen: 'spPayer' });
    v.spPayerNextLabel = s.spFromWaiting ? 'SAVE AND CLOSE' : (lastPayer ? 'NEXT' : 'NEXT PAYER');
    /* The code belongs to the share that was just paid, and the next share is
     * a new tap. Left up, it covered the new QR with the last payer's digits
     * and the screen could not be used at all — the code card is drawn over the
     * QR, so a stale one blocks the very thing the next payer has to scan or
     * tap. The same goes for stepping back to a share from
     * the waiting list. */
    v.spPayerNext = () => {
      if (s.spFromWaiting) {
        return this.setState({ screen: 'spWaiting', spFromWaiting: false, spCopied: -1, spShared: -1,
                               tapShownCode: '', tapRecvStage: '' });
      }
      if (lastPayer) return this.go('spWaiting');
      this.setState({ spIdx: idx + 1, spCopied: -1, spShared: -1,
                      tapShownCode: '', tapRecvStage: '' });
    };

    const taken = slots.filter(x => x.type === 'contact').map(x => x.handle);
    v.spContactList = (this.state.contacts || []).map(c => {
      const isTaken = taken.indexOf(c.handle) >= 0 && cur.handle !== c.handle;
      return {
        name: c.name, sub: c.handle, ini: this.spInitials(c.name), taken: isTaken,
        op: isTaken ? '0.4' : '1',
        avBg: cur.handle === c.handle ? 'var(--acc)' : 'var(--chip)',
        avInk: cur.handle === c.handle ? '#fff' : 'rgba(var(--ink-rgb),.6)',
        tap: () => {
          if (isTaken) return;
          const a = this.spSlots();
          a[idx] = { type: 'contact', name: c.name, handle: c.handle, ini: this.spInitials(c.name) };
          this.setState({ spAssigns: a, screen: 'spPayer' });
        },
      };
    });

    const left = this.spOthers() - paidCount;
    v.spWaitTitle = left === 0 ? 'ALL PAID' : 'COLLECTING';
    v.spWaitSub = left === 0 ? 'Everyone has paid you.' : 'Waiting for ' + left + (left === 1 ? ' payment' : ' payments');
    v.spWaitPct = Math.round((paidCount / this.spOthers()) * 100) + '%';
    v.spWaitFrac = paidCount + '/' + this.spOthers();
    v.spWaitFoot = left === 0 ? 'Ready to pay the bill' : 'Live \u00b7 updates as they pay';
    v.spAdvanceLabel = left === 1 ? 'DEMO \u00b7 RECEIVE THE LAST PAYMENT' : 'DEMO \u00b7 RECEIVE NEXT PAYMENT';
    v.spAdvancePayment = () => {
      const p = this.spPaidArr(), i = this.spNextUnpaid();
      if (i < 0) return;
      p[i] = true;
      const done = p.filter(Boolean).length >= this.spOthers();
      if (done) this.haptic('success');
      this.setState({ spPaid: p, screen: done ? 'spAllPaid' : 'spWaiting' });
    };
    v.spWaitRows = slots.map((sl, i) => {
      const isC = sl.type === 'contact';
      const done = paid[i];
      return {
        name: isC ? sl.name : 'Payer ' + (i + 2),
        ini: isC ? sl.ini : String(i + 2),
        pending: !done,
        avBg: done ? 'var(--acc)' : 'var(--chip)',
        avInk: done ? '#fff' : 'rgba(var(--ink-rgb),.55)',
        avRadius: isC ? '50%' : '14px',
        status: done ? 'RECEIVED' : 'PENDING',
        chipBg: done ? 'rgba(var(--acc-rgb),.18)' : 'rgba(var(--ink-rgb),.08)',
        chipInk: done ? 'var(--acc-ink)' : 'rgba(var(--ink-rgb),.5)',
        amt: this.spMoney(sh[i + 1]), amtInk: 'var(--ink)',
        rowCursor: done ? 'default' : 'pointer',
        open: () => { if (!done) this.setState({ screen: 'spPayer', spIdx: i, spFromWaiting: true, spCopied: -1, spShared: -1 }); },
      };
    });

    v.spPaidBolts = this.boltField(sc === 'spAllPaid');
    v.spPaidBoltFlash = sc === 'spAllPaid' ? 'boltFlash 1s cubic-bezier(.3,0,.5,1) both' : 'none';
    v.spPayBill = () => this.goSendScanFromSplit();
    return v;
  }

  // hand off to the app's own send flow, exactly as the home SEND button does —
  // one enabled rail opens the camera, otherwise the rail list
  /* Leaving the all-paid screen ends the split.
   *
   * The record is kept past the last payment so the screen can show what was
   * collected — deleting it there is what left every amount at $0.00.
   *
   * It used to hand off to the send flow, on the assumption that collecting
   * a bill is followed by paying it. That is a guess about what someone wants
   * next, and a wrong one often enough: the money has arrived, and home is
   * where they can see it. */
  goSendScanFromSplit() {
    const W = window.FoxyWallet;
    if (W && W.splitClear) W.splitClear();
    this.setState({
      screen: 'home', stack: [], flow: '',
      amount: '', asset: '', unit: 'USD', recipient: '', emailDraft: '',
      spPaid: [],
    });
  }

  /* ---- the render ------------------------------------------------------------
   *
   * The renderer (build/foxy-render.js) calls renderVals() on every render and
   * hands what it returns to the template: every {{ binding }} in
   * build/markup.html is a key of it. renderValsBase() gathers them from one
   * function per screen, in parts 22 to 28, and splitVals() in part 20;
   * renderVals() adds the home menu on top. renderContext() is what more than
   * one of those functions reads.
   *
   * tests/render-snapshots.js renders every screen, card and dialog and compares
   * the markup with what it was. */

  /** @typedef {ReturnType<Component["renderContext"]>} RenderContext */

  renderVals() {
    const v = /** @type {ReturnType<Component["renderValsBase"]> & {
      clearHistory: () => void, clearContacts: () => void, open0: boolean, rot0: string,
      toggleMenu: () => void, homeButtons: object[], menuItems: object[], menuAlert: string,
      mintHostLabel: string, qrSrc: string, pageHash: string,
      menuRingInk: string, menuRingInk2: string, menuRing: string,
      histRingInk: string, histRingInk2: string, histRing: string,
    }} */ (this.renderValsBase());
    /* Home's four buttons, icons only: SPLIT, CONTACTS, HISTORY, SETTINGS. SETTINGS
     * lays its own four, labelled, over the same places: RESTORE, BACKUP, the
     * PIN and CLOSE. Switching mints is the balance pill's,
     * and history's. */
    const MENU_ICON = {
      dollars: 'M12 3v18M16.6 7.6c-.8-1.4-2.5-2.1-4.6-2.1-2.5 0-4.2 1.2-4.2 3.1 0 4.6 9.2 2.1 9.2 6.7 0 2-1.9 3.2-4.7 3.2-2.3 0-4.1-.8-4.9-2.3',
      history: 'M12 7v5l3.5 2M12 3.5a8.5 8.5 0 1 0 8.5 8.5A8.5 8.5 0 0 0 12 3.5Z',
      hide: 'm3.5 3.5 17 17M10.6 6.2A9.4 9.4 0 0 1 12 6c5 0 8.5 6 8.5 6a15 15 0 0 1-2.2 3M6.3 8A15.4 15.4 0 0 0 3.5 12s3.5 6 8.5 6a9 9 0 0 0 3.2-.6',
      contacts: 'M15.5 20v-1.6a3.4 3.4 0 0 0-3.4-3.4H7.4A3.4 3.4 0 0 0 4 18.4V20M9.75 11.5a3.75 3.75 0 1 0 0-7.5 3.75 3.75 0 0 0 0 7.5M20 20v-1.6a3.4 3.4 0 0 0-2.6-3.3M15.4 4.2a3.4 3.4 0 0 1 0 6.6',
      split: 'M10.4 3.2H5.6v17.6l2-1.3 2 1.3 .8-.5M13.6 3.2h4.8v17.6l-2-1.3-2 1.3-.8-.5M12 2.2v3.2m0 2.4v3.2m0 2.4v3.2m0 2.4v1.4',
      support: 'M12 20.4S3.6 15.3 3.6 9.5A4.2 4.2 0 0 1 12 7.4a4.2 4.2 0 0 1 8.4 2.1c0 5.8-8.4 10.9-8.4 10.9z',
      backup: 'M12 3.5 4.8 6.6v5.1c0 4.4 3.1 7.8 7.2 8.8 4.1-1 7.2-4.4 7.2-8.8V6.6zM9 12l2.2 2.2L15.4 10',
      transfer: 'M4 8.5h13m0 0-3.4-3.4M17 8.5l-3.4 3.4M20 15.5H7m0 0 3.4-3.4M7 15.5l3.4 3.4',
      restore: 'M3.5 12a8.5 8.5 0 1 0 2.6-6.1M3.4 4.6v4.2h4.2M12 7.6V12l3 1.8',
      lock: 'M6.4 10.4V7.6a5.6 5.6 0 0 1 11.2 0v2.8M5.2 10.4h13.6a1.4 1.4 0 0 1 1.4 1.4v7.4a1.4 1.4 0 0 1-1.4 1.4H5.2a1.4 1.4 0 0 1-1.4-1.4v-7.4a1.4 1.4 0 0 1 1.4-1.4Z',
      settings: 'M12 15.2a3.2 3.2 0 1 0 0-6.4 3.2 3.2 0 0 0 0 6.4ZM19.2 13.4l1.8 1.4-1.9 3.3-2.1-.8a7.3 7.3 0 0 1-2 1.2l-.3 2.2h-3.8l-.3-2.2a7.3 7.3 0 0 1-2-1.2l-2.1.8-1.9-3.3 1.8-1.4a7.3 7.3 0 0 1 0-2.8L3.6 9.2l1.9-3.3 2.1.8a7.3 7.3 0 0 1 2-1.2l.3-2.2h3.8l.3 2.2a7.3 7.3 0 0 1 2 1.2l2.1-.8 1.9 3.3-1.8 1.4a7.3 7.3 0 0 1 0 2.8Z',
      close: 'M6 6l12 12M18 6L6 18',
      bars: 'M4 7h16M4 12h16M4 17h16',
      // a face in a frame: the corners of a viewfinder, two eyes and a smile
      faceid: 'M4 8.5v-3a1.5 1.5 0 0 1 1.5-1.5h3M15.5 4h3A1.5 1.5 0 0 1 20 5.5v3'
        + 'M20 15.5v3a1.5 1.5 0 0 1-1.5 1.5h-3M8.5 20h-3A1.5 1.5 0 0 1 4 18.5v-3'
        + 'M9 9.8v1.6M15 9.8v1.6M9.2 14.8a3.6 3.6 0 0 0 5.6 0',
      switch: 'M7.5 4.5 4 8l3.5 3.5M4 8h12.5a3.5 3.5 0 0 1 0 7H15M16.5 19.5 20 16l-3.5-3.5',
      scan: 'M3.5 8.5v-3a2 2 0 0 1 2-2h3M15.5 3.5h3a2 2 0 0 1 2 2v3M20.5 15.5v3a2 2 0 0 1-2 2h-3M8.5 20.5h-3a2 2 0 0 1-2-2v-3M3.5 12h17',
      paste: 'M9 4.5h6M8.2 6.5H6.4A1.9 1.9 0 0 0 4.5 8.4v10.2a1.9 1.9 0 0 0 1.9 1.9h11.2a1.9 1.9 0 0 0 1.9-1.9V8.4a1.9 1.9 0 0 0-1.9-1.9h-1.8M8.6 3.5h6.8v3H8.6z',
      // the contactless mark: three arcs from a point off the left edge
      tap: 'M7.75 9A3.5 3.5 0 0 1 7.75 15M9.25 6.4A6.5 6.5 0 0 1 9.25 17.6M10.75 3.8A9.5 9.5 0 0 1 10.75 20.2',
      // a warning triangle with a bar and a dot
      errors: 'M12 4.2 3.2 19.2h17.6L12 4.2zM12 10v4M12 16.6v.6',
      // lines on a page, the last one short
      logs: 'M6 3.5h9l3.5 3.5v13.5H6zM15 3.5V7h3.5M9 11.5h6M9 14.5h6M9 17.5h3',
      // a payment card: its outline, the stripe across it, a short line of print
      card: 'M4.6 5.5h14.8a2.1 2.1 0 0 1 2.1 2.1v8.8a2.1 2.1 0 0 1-2.1 2.1H4.6a2.1 2.1 0 0 1-2.1-2.1V7.6a2.1 2.1 0 0 1 2.1-2.1ZM2.5 10h19M6 15h4',
      // three coins of different sizes: the pieces themselves, not a wallet
      change: 'M8.5 7.5a4 4 0 1 0 0 8 4 4 0 0 0 0-8zM15.5 4.5a2.8 2.8 0 1 0 0 5.6 2.8 2.8 0 0 0 0-5.6zM16.5 14a2 2 0 1 0 0 4 2 2 0 0 0 0-4z',
    };
    const shut = (fn) => () => { this.setState({ open0: false }); if (fn) fn(); };
    // the mockup's balance pill: taller, with a soft orange halo that
    // brightens rather than appears when a payment lands
    // the price gave back its height, so the pill takes it
    v.pillH = this.state.priceCollapsed ? 124 : 120;
    /* The pill's resting glow. It was bitcoin orange around a bitcoin-orange
     * pill; the pill is frost now and so is this, except at the moment sats
     * land, which keeps its orange. */
    v.balGlowBtc = /rgba\(247,147,26,\.85\)/.test(v.balGlowBtc || '')
      ? v.balGlowBtc
      : '0 0 30px 2px rgba(207,224,236,.22)';
    v.clearHistory = () => this.askClear('history');
    v.clearContacts = () => this.askClear('contacts');
    v.open0 = !!this.state.open0;
    v.rot0 = this.state.open0 ? 'rotate(90deg)' : 'rotate(0deg)';
    v.toggleMenu = () => this.setState(p => ({ open0: !p.open0 }));
    /* SCAN and PASTE are the two ways money arrives at a phone, so they are on
     * home rather than a screen in. PASTE carries the marker
     * Apple's paste control is laid over (15-paid-wake-keyboard.js).
     *
     * There is no TAP here. There was, for a day, when the
     * payer was the phone on the air and a button was the only honest way to
     * say so — pressing it was the arming.
     *
     * The roles are the other way round now (TapLink.swift): the merchant's
     * phone advertises when they press TAP, and this one simply listens from
     * home and from SEND. Listening emits nothing, needs no permission from
     * the person holding the phone and has nothing to arm, so a button here
     * would do nothing but take up a third of the row. Holding this phone
     * against a merchant's still works; it just never needed asking for. */
    v.homeButtons = [
      // the fur turned around on SCAN; its icon and label are turned back
      { label: 'SCAN', path: MENU_ICON.scan, tap: v.goScan, spin: 'rotate(180deg)' },
      { label: 'PASTE', path: MENU_ICON.paste, tap: v.pickPaste, pasteHere: '1' },
    ].map(b => Object.assign({ pasteHere: '', spin: 'none' }, b));
    /* The menu drawer, from the right: everything that is not RECEIVE, SEND,
     * SCAN, PASTE or HISTORY. */
    /* A balance with no verified backup: the menu button and BACKUP glow red,
     * so the way to fix it is visible from home. */
    const unbacked = !!(window.FoxyWallet && window.FoxyWallet.backedUp
      && !window.FoxyWallet.backedUp() && (this.state.balSats || 0) > 0);
    v.menuAlert = unbacked ? 'alertGlow 10.4s ease-in-out infinite' : 'none';
    /* A red ring turning on the menu button, and on BACKUP inside it: words
     * that hold money and have never been written down and checked. The glow
     * above says something; a ring that is going says it is not finished. */
    const RED = '#FF5C5C';
    const backupRing = {
      ringInk: unbacked ? RED : 'transparent',
      ringInk2: unbacked ? 'rgba(255,92,92,.28)' : 'transparent',
      ring: unbacked ? 'foxyRing 1.15s linear infinite' : 'none',
    };
    v.menuRingInk = backupRing.ringInk;
    v.menuRingInk2 = backupRing.ringInk2;
    v.menuRing = backupRing.ring;

    /* And an amber one on the history button for money that is out there and
     * not yet finished: a payment the mint is still broadcasting, ecash handed
     * over that nobody has redeemed, or a bill still being collected. Every one
     * of them is a row in history, which is where the ring points. */
    const W21 = window.FoxyWallet;
    /* Every one of these is asked of the wallet on every render, and a render
     * that throws takes the whole screen with it — so each is read as "a list
     * if it gave me one, otherwise none". A stand-in wallet in the tests
     * answers undefined, and so does a real one before it has connected. */
    const someOf = (fn) => { try { const r = fn && fn(); return (r && r.length) || 0; } catch (e) { return 0; } };
    const splitOpen = () => {
      try { const sp = W21 && W21.splitPending && W21.splitPending(); return !!(sp && !sp.done); }
      catch (e) { return false; }
    };
    const waiting = !!(W21 && (
      someOf(W21.onchainSending) || someOf(W21.watchedTokens) || splitOpen()
    ));
    /* Red, not amber, and it wins.
     *
     * Every other thing this ring turns for is money in Foxy's own hands that
     * needs time: a broadcast, a redeem, a bill being collected. Nobody can take
     * those away. A payment taken on trust while both phones were offline is the
     * one kind that somebody else can still make disappear, and it is counted in
     * the balance while they can. A person glancing at the home screen should be
     * able to tell those two apart without opening anything.
     *
     * It stops turning the moment the payment is swapped in, because that is the
     * moment the risk ends — the claim drops the row. */
    /* And ecash another phone has seen and refused without sending it back
     * (`atRisk`): in the balance, spendable, and somebody else's to redeem
     * until this phone has swapped it. The same ring, for the same reason. */
    const atRisk = someOf(W21 && W21.trustedWaiting) || someOf(W21 && W21.atRisk);
    const AMBER = '#F7931A';
    const RISK_RED = '#FF5C5C';
    /* And for the audit: red while the balance and the payments disagree,
     * and red too while change is waiting to be scanned or shown. The card is on
     * the history screen; this is what says to go and look. */
    const AU = this.histAudit ? this.histAudit() : { whole: false, off: 0, dueChange: 0, toShowCount: 0 };
    /* Not at the first sign of it. The balance is read a moment before the
     * payment's row is — twelve seconds apart on an older phone after a tap
     * that fell back to a code — and for that long the two disagree about a payment
     * both are about to agree on. History is read again at once, and the ring
     * turns red only if they still disagree four seconds on. */
    if (AU.whole && AU.off !== 0) {
      if (!this._offSince) {
        this._offSince = Date.now();
        clearTimeout(this._offT);
        this._offT = setTimeout(() => {
          if (this.loadHistory) this.loadHistory();
          this._offT = setTimeout(() => this.setState({ menuTick: (this.state.menuTick || 0) + 1 }), 2800);
        }, 1400);
      }
    } else {
      this._offSince = 0;
      clearTimeout(this._offT);
    }
    const short = !!this._offSince && Date.now() - this._offSince >= 4000;
    const changeTodo = AU.dueChange > 0 || AU.toShowCount > 0;
    v.histRingInk = (atRisk || short || changeTodo) ? RISK_RED : waiting ? AMBER : 'transparent';
    v.histRingInk2 = (atRisk || short || changeTodo) ? 'rgba(255,92,92,.28)'
      : waiting ? 'rgba(247,147,26,.28)' : 'transparent';
    v.histRing = (atRisk || waiting || short || changeTodo) ? 'foxyRing 1.5s linear infinite' : 'none';
    /* The drawer, in this order:
     *
     *   BACKUP (only while the words are unverified — verified, it lives at
     *     the foot of SETTINGS)
     *   HIDE BALANCE · SPLIT A BILL · CONTACTS
     *   TRANSFER (only with money at more than one mint)
     *   SWITCH · YOUR CHANGE
     *   SETTINGS, which opens and closes in place:
     *     AUTO TAP TO PAY and USE FACE ID as switches, SET PIN, RESTORE,
     *     BACKUP, LOGS
     *
     * ERRORS is gone: it was the same log with a filter on it. Rows inside
     * SETTINGS are indented; a switch shows its state, so its label never has
     * to — which is what the REMOVE/STOP verbs were for. */
    const W22 = window.FoxyWallet;
    const verified = !!(W22 && W22.backedUp && W22.backedUp());
    const mintsWithMoney = (() => {
      try {
        const list = (W22 && W22.mints ? W22.mints() : []) || [];
        return list.filter(m => W22.balanceAt && W22.balanceAt(String((m && m.id) || m)) > 0).length;
      } catch (e) { return 0; }
    })();
    const settingsOpen = !!this.state.menuSettingsOpen;
    const tapAuto = this.tapAutoArms();
    const faceOn = !!(W22 && W22.secureChoice && W22.secureChoice() === 'device');
    const backupRow = { label: 'BACKUP', path: MENU_ICON.backup, tap: shut(() => this.showSeedOnPhone(false)),
      glow: unbacked ? 'alertGlow 10.4s ease-in-out infinite' : 'none',
      ringInk: backupRing.ringInk, ringInk2: backupRing.ringInk2, ring: backupRing.ring };
    const inSettings = (m) => Object.assign({ indent: '10px' }, m);
    const sw = (on) => ({ hasSwitch: true, swBg: on ? 'var(--acc)' : 'rgba(var(--ink-rgb),.22)', swX: on ? '18px' : '0px' });
    v.menuItems = /** @type {any[]} */ (verified ? [] : [backupRow]).concat([
      /* Hiding the balance moved here from the pill, where its button sat on
       * top of the figures. The label says what the tap
       * will do, so it reads the same whichever way round it is. */
      { label: this.state.hidden ? 'SHOW BALANCE' : 'HIDE BALANCE',
        path: MENU_ICON.hide, tap: shut(v.toggleHide) },
      { label: 'SPLIT A BILL', path: MENU_ICON.split, tap: shut(v.goSplit) },
      { label: 'CONTACTS', path: MENU_ICON.contacts, tap: shut(v.goContacts) },
    ]).concat(mintsWithMoney > 1 ? [
      { label: 'TRANSFER', path: MENU_ICON.transfer, tap: shut(() => this.goTransfer()) },
    ] : []).concat([
      { label: 'SWITCH', path: MENU_ICON.switch,
        tap: shut(() => this.goSwitchMint()) },
      /* What the pool actually holds, which decides whether this phone can pay an
       * exact amount at all — the one question an offline payer has and no other
       * screen answers. */
      { label: 'YOUR CHANGE', path: MENU_ICON.change, tap: shut(() => this.goChange()) },
      /* A card that holds ecash: what is on it, money on and off it, and the
       * cards this phone can take back (26f-flashcard.js). */
      { label: 'FLASHCARD', path: MENU_ICON.card, tap: shut(() => this.goFlashcard()) },
      /* Where bitcoin becomes dollars in a bank account: a list of companies
       * and nothing more. Foxy pays none of them itself. */
      { label: 'GET DOLLARS', path: MENU_ICON.dollars, tap: shut(() => this.showGetDollars()) },
      // opens and closes in place; the drawer stays
      { label: 'SETTINGS', path: MENU_ICON.settings, hasChev: true, chevRot: settingsOpen ? 'rotate(90deg)' : 'rotate(0deg)',
        tap: () => this.setState({ menuSettingsOpen: !settingsOpen }) },
    ]).concat(!settingsOpen ? [] : /** @type {any[]} */ ([
      /* Whether an invoice goes on the air by itself. A switch, and the
       * drawer stays open so it can be seen to move. */
      Object.assign({ label: 'AUTO TAP TO PAY', path: MENU_ICON.change,
        tap: () => { this.tapAutoSet(!tapAuto); this.setState({ menuTick: (this.state.menuTick || 0) + 1 }); } }, sw(tapAuto)),
      /* What stands in front of the wallet, changed after the SECURE FOXY card
       * has been and gone (10-pin.js). Pressing it answers `device`, which
       * locks the screen and keeps the seed where it already was; turning it
       * off is never one tap (confirmNoProtection). One row, two things, and
       * that is deliberate: this answer guards the seed AND locks the screen.
       * Nobody having answered reads as off, which is what `faceLock()` does
       * with it. */
      Object.assign({
        label: 'USE FACE ID',
        path: MENU_ICON.faceid,
        tap: shut(() => {
          const W = window.FoxyWallet;
          if (!W || !W.secureChoice) return;
          if (W.secureChoice() !== 'device') { this.chooseProtection('device'); return; }
          // taking a guard off is never one tap
          this.confirmNoProtection();
        }),
      }, sw(faceOn)),
      /* The label is the tap, not the state: SET, REMOVE — a verb cannot be
       * read as a state. */
      {
        label: (window.FoxyWallet && window.FoxyWallet.pinIsSet
          && window.FoxyWallet.pinIsSet()) ? 'REMOVE PIN' : 'SET PIN',
        path: MENU_ICON.lock,
        tap: shut(() => {
          const W = window.FoxyWallet;
          if (W.pinIsSet()) {
            // turning it off asks for it first, or it is not a lock
            this.pinOverlay({
              title: 'ENTER YOUR PIN',
              subtitle: 'To turn the lock off.',
              cta: 'TURN OFF',
              onCancel: () => {},
              onSubmit: (pin, warn) => {
                // the lock's own attempt count and wait: this used to check
                // the PIN directly, with neither
                const r = this.pinTry(pin);
                if (!r.ok) { warn(r.message); return; }
                W.pinClear();
                this.pinDismiss();
                this.toast('PIN removed');
              },
            });
            return;
          }
          this.pinSetup(() => {});
        }),
      },
      /* The phone's own screens, straight over home: no Foxy screen before
       * RESTORE A WALLET or after YOUR SEED PHRASE. */
      { label: 'RESTORE', path: MENU_ICON.restore, tap: shut(() => this.restoreFromMenu()) },
    ]).concat(verified ? [backupRow] : []).concat([
      /* Everything that happened, errors among them. Kept on the phone and
       * copied out by hand — there is no reporting of any kind behind it. */
      { label: 'LOGS', path: MENU_ICON.logs, tap: shut(() => this.goFieldLog(false)) },
    ]).map(inSettings)).map(m => Object.assign({ glow: 'none', ringInk: 'transparent',
      ringInk2: 'transparent', ring: 'none', indent: '0px', hasSwitch: false, swBg: 'transparent',
      swX: '0px', hasChev: false, chevRot: 'rotate(0deg)' }, m));
    /* The page's own hash, quiet at the foot of the drawer.
     *
     * The native side hashes the files it staged at launch and sets
     * window.__foxyPageHash before any of this script runs
     * (FoxyWebView.manifestHash). `python3 tools/page-hash.py` prints the same
     * string from the repository, so someone holding the phone can tell whether
     * it is running the page that was reviewed — which nothing here could show
     * before. Twelve characters is enough to compare by eye and short enough to
     * stay one line.
     *
     * Empty when the page is not in the app — the test harness, a browser — and
     * an empty div takes no height, so the drawer is unchanged there. */
    const pageHash = String(window.__foxyPageHash || '').replace(/[^0-9a-f]/g, '');
    v.pageHash = pageHash ? 'page ' + pageHash.slice(0, 12) : '';
    v.mintHostLabel = this.mintName() || 'the mint';
    // CASHU: the payment request for the same amount (railRequest), else the invoice
    /* Only while the receive screen is up. CASHU is remembered, so without the
     * screen test this made a request — and an onion address — on every render
     * of every screen, which syncInbox then closed: dozens of addresses a
     * minute, and the one in the QR already dead (seen in a phone log). */
    const onchainRail = this.state.screen === 'confirm' && this.state.recvRail === 'ON-CHAIN' && !!window.FoxyWallet;
    const onchainCode = onchainRail
      ? (this.ocReceiveAddress() ? window.FoxyWallet.bip21(this.ocReceiveAddress(),
        this.state.invoiceIsAddress ? 0 : window.FoxyWallet.amountOf(this.state.invoice)) : '') : '';
    const cashuRail = this.state.screen === 'confirm' && this.state.recvRail === 'CASHU' && !!window.FoxyWallet;
    /* The amount the person asked for, not the one read back out of the
     * Lightning invoice: a CASHU request made before the invoice had landed
     * was built for nothing and shown to the payer as "pay any amount". cashuRequest decides what there is to show, and
     * returns '' whenever the answer is "not yet" — which is what puts the
     * loading animation on the QR below. */
    const creq = cashuRail ? this.cashuRequest() : '';
    // CASHU while its request is being made: the loading code, not the invoice's
    /* A request being animated is drawn by `syncReqQr`, frame by frame, and
     * this must not draw over it.
     *
     * Both write to the same image: the animator sets `src` directly every
     * 200 ms, and a render would put the one dense static code back. They
     * fought, and the code on screen was a frame or the unreadable static one
     * depending on which wrote last — which is a code that scans once and then
     * never again. So while it animates, this shows
     * the animator's current frame, which is the same thing the token screen
     * does with `_tokQr`. */
    const dense = !!(creq && this.qrDense(creq));
    /* THIS request's frame, not whichever one the animator happens to hold.
     *
     * The token screen has always checked that (`_tokQr.token === tk`). This
     * did not — so a second request drew the PREVIOUS request's frames into its
     * image, for at least as long as it took the animator to notice, and a code
     * assembled from two different requests is a code that never assembles.
     * That is "it works once and then the QRs do not work again". */
    const frame = (this._reqQr && this._reqQr.text === creq && this._reqQr.src)
      ? this._reqQr.src : '';
    v.qrSrc = onchainCode ? window.FoxyWallet.qr(onchainCode)
      : onchainRail ? this.qrLoadingSrc()
      : (creq && dense) ? (frame || this.qrLoadingSrc())
      : creq ? window.FoxyWallet.qr(creq) : cashuRail ? this.qrLoadingSrc()
      : (this.state.invoice && window.FoxyWallet)
      ? window.FoxyWallet.qr(this.state.invoice)
      : this.qrLoadingSrc();
    this.noteQr(v.qrSrc, {
      rail: onchainCode ? 'on-chain' : cashuRail ? 'cashu' : 'lightning',
      from: onchainCode ? 'address' : creq ? 'request' : this.state.invoice ? 'invoice' : 'nothing',
      chars: String(onchainCode || creq || this.state.invoice || '').length,
      dense: dense, animating: !!(creq && dense && frame),
    });
    return v;
  }

  /* Every binding the markup reads, one screen at a time. A key belongs to the
   * screen whose markup binds it (build/app/README.md lists the functions); none
   * is defined twice, so the order below decides nothing. */
  renderValsBase() {
    const c = this.renderContext();
    return {
      ...this.renderShell(c),
      ...this.renderNote(c),
      ...this.renderHome(c),
      ...this.renderAmount(c),
      ...this.renderReceive(c),
      ...this.renderPaid(c),
      ...this.renderSend(c),
      ...this.renderSent(c),
      ...this.renderToken(c),
      ...this.renderConfirmShell(c),
      ...this.renderBlocked(c),
      ...this.renderHistory(c),
      ...this.renderTxDetail(c),
      ...this.renderContacts(c),
      ...this.renderMints(c),
      ...this.renderFlashcard(c),
      ...this.renderNewMint(c),
      ...this.renderRestore(c),
      ...this.renderBackup(c),
      ...this.splitVals(c.s, c.sc),
      ...this.renderFieldLog(c),
    };
  }

  /* fieldLog: the ERRORS and LOGS screen (28-field-log.js). */
  /** @param {RenderContext} c */
  renderFieldLog(c) {
    const { s, sc } = c;
    const lines = s.flLines;
    /* Drawn: the newest 1,500. The log holds 10,000 while Foxy is in testing,
     * and that many rows on one screen is a screen that will not scroll. COPY
     * ALL and SHARE still hand over every line. */
    const FL_SHOWN = 1500;
    const rows = (lines || []).slice(0, FL_SHOWN).map((l, i) => ({
      key: 'fl' + i,
      time: this.flStamp(l.at),
      text: String(l.text || ''),
      ink: l.bad ? '#FF5C5C' : 'var(--ink)',
    }));
    const pieces = (sc === 'change' && window.FoxyWallet && window.FoxyWallet.pieces)
      ? window.FoxyWallet.pieces() : [];
    const held = pieces.reduce((a, r) => a + r.count, 0);
    const worth = pieces.reduce((a, r) => a + (r.amount * r.count), 0);
    /* Short counts only denominations the pool is aiming for: a pile holding three
     * 4096s, which nothing targets, is not short of anything. `pieces` lists the
     * small tier even at none held, so a missing denomination is counted here
     * rather than silently absent. */
    const short = pieces.filter(r => r.want && r.count < r.want).length;
    return {
      isChange: sc === 'change',
      chRows: pieces.map(r => ({
        amount: this.group(r.amount),
        count: String(r.count),
        /* The target beside the count, or nothing where there is none: a bare
         * "of 12" against a denomination the pool does not keep would read as a
         * shortfall that is not one. */
        want: r.want ? 'of ' + r.want : '',
        /* Amber where the pool is short of its target, plain where it is met.
         * Never red: being short of small change is not a fault, it is a thing
         * that fixes itself the next time there is a route. */
        ink: (r.want && r.count < r.want) ? '#E6D8A8' : 'var(--ink)',
      })),
      chHasRows: pieces.length > 0,
      chTitle: 'YOUR CHANGE',
      chSub: !pieces.length ? 'No ecash on this phone yet.'
        : held + ' piece' + (held === 1 ? '' : 's') + ', worth \u20bf' + this.group(worth),
      /* Said plainly, because the number of pieces is the whole reason this
       * screen exists: it is what decides whether an exact amount can be paid
       * with no mint, and offline that is the only way to pay at all. */
      chNote: 'Foxy keeps small pieces on hand so it can pay an exact amount without'
        + ' asking the mint — which is the only way to pay with no connection. It tops'
        + ' them up by itself when it has one.',
      chShort: short > 0,
      isFieldLog: sc === 'fieldLog',
      flTitle: s.flBad ? 'ERRORS' : 'LOGS',
      flSub: lines === null ? 'Reading…'
        : !rows.length ? (s.flBad ? 'Nothing has gone wrong.' : 'Nothing recorded yet.')
        : (lines.length > FL_SHOWN
          ? lines.length + ' lines; the newest ' + FL_SHOWN + ' shown, SHARE sends them all'
          : rows.length + ' line' + (rows.length === 1 ? '' : 's') + ', newest first'),
      flRows: rows,
      flHasRows: rows.length > 0,
      /* Said before anything is copied, not after. Tokens and invoices are
       * already gone; what is left still says who you bank with. */
      flNote: 'Kept on this phone only — Foxy sends none of this anywhere. '
        + 'Tokens, invoices, payment requests and keys are already removed. '
        + 'Mint names and amounts are not, so paste it somewhere you trust.',
      flCopyLabel: s.flCopied ? 'COPIED' : 'COPY ALL',
      flCopy: () => this.copyFieldLog(),
      // the share sheet, because a session's worth of log is an attachment
      // rather than a paste — and on a Release build this screen is the only
      // record there is (26c-field-log.js)
      flShare: () => this.shareFieldLog(),
      flClear: () => this.clearFieldLog(),
      flBack: () => this.back(),
    };
  }

  /* What more than one screen's function reads, worked out once a render. */
  renderContext() {
    const s = this.state;
    const sc = s.screen;
    // the wallet you're paying from caps a send
    const balLive = this.balNow();
    // the fork could hide the bitcoin wallet; this one is the bitcoin wallet
    const btcAvailUsd = balLive.sats * this.satUsd();
    // on chain as well: its keypad took any figure and left the refusal to
    // the confirmation, a screen and a fee quote later
    /* A card's amounts are typed on the same keypad (26f-flashcard.js), and
     * two of them have a ceiling it can say under the figure: adding to a
     * card is out of this phone's balance, and withdrawing is out of what the
     * card holds. */
    const capped = s.flow === 'send' || s.flow === 'onchain' || s.flow === 'cardAdd' || s.flow === 'cardWd';
    const sendCapUsd = !capped ? 0
      : s.flow === 'cardWd' ? ((s.fc && s.fc.balance) || 0) * this.satUsd()
      : btcAvailUsd;
    const sendEnteredUsd = s.unit === 'SATS' ? (parseFloat(s.amount) || 0) * this.satUsd() : (parseFloat(s.amount) || 0);
    const SEND_DAY_LIMIT = Infinity; // this fork has no daily limit
    const overLimit = s.flow === 'send' && sendEnteredUsd > SEND_DAY_LIMIT + 0.005;
    const sendOver = capped && (sendEnteredUsd > sendCapUsd + 0.005 || overLimit);
    // handed to syncHaptics, which cannot repeat this balance/limit maths
    this._amtOver = false;
    // live series or nothing: a canned curve next to a real price is a lie
    const chart = (s.series || {})[s.range] || null;
    this._pts = chart ? chart.pts : null;
    const val = parseFloat(s.amount) || 0;
    const landed = val;
    // An invoice's own amount overrides the typed one — but only when paying
    // it. On a receive screen the typed amount IS the amount.
    const invSats = (s.flow === 'send' && s.recipientKind === 'invoice' && s.recipient && window.FoxyWallet)
      ? window.FoxyWallet.amountOf(s.recipient) : null;
    const sats = invSats || (s.unit === 'SATS' ? Math.round(landed) : Math.round(landed / this.px() * 1e8));
    const tx = s.tx || {};
    const emailOk = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test((s.emailDraft || '').trim());
    /* Over the balance only because part of it is with the mint: the same
     * block, with its own words. */
    const overBySats = (sendOver && this.satUsd() > 0)
      ? Math.ceil((sendEnteredUsd - sendCapUsd) / this.satUsd()) : 0;
    // what is held with the mint is this phone's balance; a card's is its own
    const sendHeld = (sendOver && !overLimit && this.heldBlocks && s.flow !== 'cardWd') ? this.heldBlocks(overBySats) : '';
    return { s, sc, balLive, btcAvailUsd, sendCapUsd, sendEnteredUsd, SEND_DAY_LIMIT, overLimit, sendOver, sendHeld, chart, val, landed, invSats, sats, tx, emailOk };
  }

  /* The frame every screen sits in: size, theme and accent, the keyboard, the toast,
   * the Tor warning, Back. */
  /** @param {RenderContext} c */
  renderShell(c) {
    const { s, sc } = c;
    return {
      shellRef: this.shellRef,
      staticAttr: this.props.startStatic ? '1' : '0',
      shellKbPad: (s.kbInset || 0) + 'px',
      theme: TH(this), isDarkTheme: TH(this) !== 'light',
      back: () => this.back(),
      kbPrimerRef: this._refPrimer || (this._refPrimer = (el) => { this._primerEl = el; }),
      wantFocus: !this.props.startStatic,
      showKb: !!this.props.startKeyboard,
      ctaInk: CTA_INK(s),
      accHex: ACC_OF(AC(this)).acc,
      accLt: ACC_OF(AC(this)).lt,
      accDk: ACC_OF(AC(this)).dk,
      accRgb: ACC_OF(AC(this)).rgb,
      stopTap: (e) => e.stopPropagation(),
      toastText: s.toastMsg || '',
      toastBg: s.toastAmber ? '#E0902E' : 'var(--acc)',
      toastShown: s.toastMsg ? '1' : '0',
      toastY: s.toastMsg ? '0%' : '-100%',
      /* The tunnel warning, rendered inline rather than pinned over the app.
       *
       * Read off the gate each render; __foxyGateChanged is what tells us a
       * render is due, since the gate lives outside the runtime. */
      gateWarnShown: !!(window.FoxyGate && window.FoxyGate.warning && window.FoxyGate.warning()),
      gateWarn: ((window.FoxyGate && window.FoxyGate.warning && window.FoxyGate.warning()) || {}).text || '',
      gateWarnBg: ((window.FoxyGate && window.FoxyGate.warning && window.FoxyGate.warning()) || {}).colour || '#8C1D1D',
      gateWarnTap: () => {
        const G = window.FoxyGate;
        if (G && G.rearm) G.rearm(() => this._gateThenBoot && this._gateThenBoot());
      },
    };
  }

  /* A payment's note: its button on the invoice and token screens, and its sheet. */
  /** @param {RenderContext} c */
  renderNote(c) {
    const { s } = c;
    return {
      noteInput: (e) => this.setState({ note: e.target.value.slice(0, 120) }),
      noteFocusRef: this._refNote || (this._refNote = (el) => this.autoFocus('note', el)),
      hasNote: !!this.noteShown(), noNote: !this.noteShown(),
      noteText: this.noteShown(),
      noteBtnBg: this.noteShown() ? 'var(--acc)' : 'var(--ink)',
      noteOpen: this.props.startPopup === 'noteOpen' || !!s.noteOpen,
      noteCount: (s.note || '').length,
      cancelNote: () => this.setState({ noteOpen: false, note: this.state.noteDraft || '' }),
      saveNote: () => this.setState({ noteOpen: false, note: (this.state.note || '').trim() }),
    };
  }

  /* home: the balances, the price chart, RECEIVE and SEND, the backup prompt. */
  /** @param {RenderContext} c */
  renderHome(c) {
    const { s, sc, chart } = c;
    const bal = this.balNow();
    const crediting = s.animFrom ? s.animLane : null;
    return {
      isHome: sc === 'home',
      // SEND opens the ways to pay — scan, type, contacts, paste. This asked
      // clSend() whether only one of them was left, to skip the screen and go
      // straight to the scanner; the fork's hide-* props that could take the
      // others away are gone, so all four are always there (finding 19).
      goSend: () => this.setState(p => ({
        screen: 'sendHow', stack: p.stack.concat([p.screen]), flow: 'send',
        amount: '', asset: '', unit: 'USD', recipient: '', emailDraft: '',
        note: '', noteDraft: '',
      })),
      // home's SCAN: straight to the scanner, which is how a payment request,
      // an invoice or a token gets in
      goScan: () => this.setState(p => ({
        screen: 'sendScan', stack: p.stack.concat([p.screen]), flow: 'send',
        amount: '', asset: '', unit: 'USD', recipient: '', emailDraft: '',
        note: '', noteDraft: '',
      })),
      goReceive: () => this.setState(p => ({
        screen: 'amount', stack: p.stack.concat([p.screen]), flow: 'receive',
        asset: '', network: '', amount: '', unit: 'USD',
        note: '', noteDraft: '',
        // these belong to sending; left set, they decide what the receive
        // invoice screen displays instead of the amount just typed
        recipient: '', recipientKind: '',
      })),
      bkBadge: false,
      bkAskAgain: (e) => { e.stopPropagation(); this.setState({ bkAsk: true }); },
      goRecovery: () => this.setState(p => ({ screen: 'bkStart', stack: p.stack.concat([p.screen]) })),
      chartPath: chart ? chart.d : '',
      /* The same line, closed to the bottom of the box: a wash under the
       * price, which the snow-fox design uses to give it weight. It ends where the drawing does — past both edges — so the
       * wash bleeds off the screen with it. */
      chartFill: chart ? chart.d + ' L462 92 L-60 92 Z' : '',
      /* Sats held for a swap the mint has not answered are out of the
       * balance, and a balance that has simply dropped looks like money gone.
       * The pill under it says where they are until they are back. */
      deltaText: this.heldPill() || (chart ? chart.t : ''),
      deltaShown: !!this.heldPill() || !!chart, markerDisplay: chart ? 'block' : 'none',
      /* Once per visit to this screen, not once per session: the ride is what
       * the home screen opens with. The element is made
       * when the screen is drawn and let go when it is left, so this fires on
       * arrival, and `_rolled` only stops it restarting on every render while
       * the screen is up. A ride that cannot start yet — no line drawn — parks
       * instead, and the balance pass starts it when the series lands. */
      /* A tap anywhere on the price line's panel runs the ride again, for
       * anyone who missed it. He is off the right of the
       * screen the rest of the time, so there is nothing else to aim at. */
      markerTap: this._markerTap || (this._markerTap = e => {
        if (e && e.stopPropagation) e.stopPropagation();
        this.markerRoll();
      }),
      markerRef: this._markerRef || (this._markerRef = el => {
        this._marker = el;
        if (!el) { this._rolled = false; cancelAnimationFrame(this._mraf); return; }
        if (!this._rolled) {
          this._rolled = this.riderShow();
          // the element was made while this screen is up: an arrival already
          this._wasHome = this.state.screen === 'home';
        }
      }),
      priceText: s.livePrice
        ? '$ ' + Math.round(s.livePrice).toLocaleString('en-US')
        : '\u2014',
      /* The label carries the price's age once it has one.
       *
       * `livePrice` is never cleared, so a price that stopped refreshing goes on
       * being shown — and dollar figures go on being computed from it — with
       * nothing on screen to say how old it is. That is the exact thing the
       * comment in refreshBalance warns against: "a dollar figure that is simply
       * wrong, and there is no way to tell from the screen". Offline it can be
       * hours.
       *
       * So the age goes where the eye already is, in the one label both the
       * collapsed pill and the open chart share. Under three minutes it says
       * nothing, because that is the window the app already treats as current. */
      priceLabel: 'BITCOIN PRICE',
      /* The age on its own line under the price, in red:
       * beside the label it read as part of the title. */
      priceAge: this.priceAgeWords(),
      priceAgeShown: !!this.priceAgeWords(),
      markerTop: chart ? (chart.y / 92 * 100).toFixed(1) + '%' : '50%',
      toggleRange: () => this.setState(p => ({ rangeOpen: !p.rangeOpen })),
      fiatDisplay: s.hidden ? '••••••' : this.usd(bal.usd),
      fiatSub: s.hidden ? '' : 'USD',
      /* Dollars on the big line and the sats under it. The
       * names are from when it was the other way up. With no price the sats
       * take the big line alone, rather than a dollar figure nobody can stand
       * behind. */
      satsDisplay: s.hidden ? '••••••'
        : bal.sats == null ? '···'
        : this.satUsd() ? '$ ' + this.usd(bal.sats * this.satUsd())
        : '₿ ' + this.group(bal.sats),
      satsSub: s.hidden ? ''
        : bal.sats == null ? 'Loading balance…'
        : !this.satUsd() ? ''
        : '₿ ' + this.group(bal.sats),
      /* Money landing still lights the pill up, in the snow-fox design's own
       * frost rather than the accent — the orange is kept
       * for the price line, which is the one warm thing on the screen. */
      balGlowUsd: crediting === 'usd'
        ? '0 0 0 2.5px rgba(255,255,255,.6),0 0 38px rgba(207,224,236,.8)'
        : '0 0 26px rgba(207,224,236,.24)',
      balGlowBtc: crediting === 'btc'
        ? '0 0 0 2.5px rgba(255,255,255,.6),0 0 38px rgba(247,147,26,.85)'
        : '0 0 26px rgba(207,224,236,.24)',
      // an open eye while hidden (tap to show), struck through while showing
      hideIconPath: s.hidden
        ? 'M2.5 12S6 6 12 6s9.5 6 9.5 6-3.5 6-9.5 6-9.5-6-9.5-6Z'
          + 'M12 14.2a2.2 2.2 0 1 0 0-4.4 2.2 2.2 0 0 0 0 4.4'
        : 'm3.5 3.5 17 17M10.6 6.2A9.4 9.4 0 0 1 12 6c5 0 8.5 6 8.5 6'
          + 'a15 15 0 0 1-2.2 3M6.3 8A15.4 15.4 0 0 0 3.5 12s3.5 6 8.5 6'
          + 'a9 9 0 0 0 3.2-.6',
      showLimitsCta: !!s.priceCollapsed,
      homeTxs: [].map(t => ({
        name: s.hidden ? '••••••••' : t.name,
        initial: s.hidden ? '•' : t.name.slice(0, 1).toUpperCase(),
        time: s.hidden ? '•••••' : t.time,
        tileBg: s.hidden ? 'rgba(var(--ink-rgb),.16)' : (t.dir === 'in' ? 'var(--acc)' : 'rgba(var(--ink-rgb),.16)'),
        stroke: s.hidden ? 'rgba(var(--ink-rgb),.14)' : (t.dir === 'in' ? 'rgba(var(--acc-rgb),.7)' : 'rgba(229,72,77,.7)'),
        amtColor: s.hidden ? 'rgba(var(--ink-rgb),.55)' : (t.dir === 'in' ? 'var(--acc-ink)' : 'rgba(var(--ink-rgb),.8)'),
        amtText: s.hidden ? '••••••' : (t.dir === 'in' ? '+' : '−') + '₿ ' + this.txTotalOut(t).toLocaleString(),
        open: () => this.openTx(t),
      })),
      // shown from the first payment in until the phrase is verified
      showCtaBackup: !!(window.FoxyWallet && window.FoxyWallet.backedUp
        && !window.FoxyWallet.backedUp())
        && !!s.everReceived
        && !s.dismissedBackup,
      dismissBackup: (e) => { e.stopPropagation(); this.setState({ dismissedBackup: true }); },
      pillH: s.priceCollapsed ? 73 : 68,
      // The pill toggles too, and this button sits inside it — without
      // stopping the event here, one tap fires both handlers and the balance
      // hides and shows again in the same frame.
      toggleHide: (e) => {
        if (e && e.stopPropagation) e.stopPropagation();
        this.setState(p => ({ hidden: !p.hidden }));
      },
      /* The mint this balance is at, in the pill: its first letter in the
       * accent on black where the bitcoin sign was, with its name under it. */
      pillLetter: (this.mintName() || '?').slice(0, 1).toUpperCase(),
      pillMintName: this.mintName() || '',
      /* Two halves, either side of the line at 100px: the mint on the left
       * goes to the mints, the balance on the right goes to history. Hiding
       * stays on the eye, which is what that icon means. */
      togglePill: (e) => {
        let x = 0;
        try {
          const box = e && e.currentTarget && e.currentTarget.getBoundingClientRect
            ? e.currentTarget.getBoundingClientRect() : null;
          x = box ? (Number(e.clientX) || 0) - box.left : 0;
        } catch (x2) { x = 0; }
        if (x > 100) this.go('history'); else this.goSwitchMint();
      },
      priceCollapsed: !!s.priceCollapsed, priceExpanded: !s.priceCollapsed,
      /* The banner is the one thing on the home screen that says how Foxy
       * reaches the world, and it said it in three words. Tapping it says the
       * rest.
       *
       * It used to be fixed markup: "Secure Tor Connection" was on the home
       * screen whenever the home screen was, whatever the route underneath it
       * was doing. Someone who tapped past the gate to continue unprotected
       * was told their connection was secure while their IP address was in
       * the clear. Now it is drawn from the route and
       * says only what is true of it: blue and secure when Tor is carrying
       * everything, red and plain about it when nothing is, and nothing at
       * all while Tor is still connecting — there is no claim to make yet,
       * and the gate is already saying so. */
      ...this.torBannerVals(),
      /* The banner's tap. Offline it is the way back — which is the whole of
       * what TAP TO RETRY promises, so it must do that and not open a card
       * explaining what Tor is to somebody who has already read it once and
       * chosen to go without. Every other state has nothing a tap could change,
       * so it keeps the explainer. */
      torBanner: () => {
        const now = this.torBannerVals();
        if (now.torBannerOffline) {
          /* The connecting screen, which is where the count, RESTART TOR and
           * the way to go without Tor now live. It comes down by itself once
           * Tor is through. */
          if (window.FoxyGate && window.FoxyGate.leaveOffline) window.FoxyGate.leaveOffline();
          if (!now.torBannerMaking) this.toast('Looking for Tor again\u2026');
          return;
        }
        this.blockedCard('torConnection', {
          tone: 'ask',
          title: 'TOR CONNECTION',
          reason: 'Tor is a privacy network that hides your IP address while you use Foxy.',
        });
      },
      toggleCollapse: () => this.setState(p => ({ priceCollapsed: !p.priceCollapsed })),
      chevronRot: s.priceCollapsed ? 'rotate(-90deg)' : 'rotate(0deg)',
      priceFlex: s.priceCollapsed ? '0 0 auto' : '1 1 0%',
      priceTopPad: s.priceCollapsed ? 2 : 4,
      moneyFlex: (s.priceCollapsed || s.priceRemoved) ? '1 1 0%' : '0 0 auto',
      showPriceSection: !s.priceRemoved,
    };
  }

  /* The home banner's three states, from the route as it is right now.
   *
   * Secure is the strict reading: Tor up AND not continuing unprotected.
   * Anything short of that is not a secure connection and must not be
   * described as one. Red is for the one state where the person is actually
   * exposed and might not know it; while Tor is merely connecting the banner
   * is absent, because nothing has been claimed and nothing has leaked. */
  torBannerVals() {
    const W = window.FoxyWallet;
    const p = (W && W.privacy) ? W.privacy() : null;
    /* Chosen first, and a claim about the connection needs a connection.
     *
     * `secure` was Tor saying "up" and nothing else — not whether there was a
     * network under it, and not whether the person had chosen to work offline.
     * Tor reports bootstrap 100% from a state it cannot use: the phone loses
     * wifi, every request times out, the path monitor says none, and the
     * control port still says done. So the home screen told somebody who had
     * deliberately gone offline, on a phone that could not reach a mint, that
     * they had a Secure Tor Connection.
     *
     * This is the one banner whose whole job is to make a claim about the
     * connection, so it now asks what the rest of the app asks: a route is Tor
     * up AND a network under it, which is `setOffline`'s own test. And working
     * offline is a state the person chose and stays in, so it outranks every
     * reading of a route they have told Foxy not to use. */
    const chosen = !!p && !!p.offline;
    const live = !!p && p.tor === 'up' && p.network !== 'none';
    /* Exposure is the louder claim and outranks the choice: somebody whose
     * traffic is leaving unprotected needs telling whatever mode they think
     * they are in. Offline outranks everything below that. */
    const secure = live && !p.unprotected && !chosen;
    const off = !!p && !secure && !!p.unprotected;
    /* Working offline says so, and offers the way back.
     *
     * While Tor is merely connecting the banner is absent, and rightly: nothing
     * has been claimed and nothing has leaked. Offline is not that. It is a state
     * the person chose and stays in, in which most of the app will refuse them,
     * so a home screen that made no claim at all would be the same screen as a
     * healthy one. It is not red either — nothing is exposed, nothing is being
     * sent — so it takes the same amber the tunnels use, and its own tap. */
    const offline = chosen && !p.unprotected;
    /* Not on Foxy's Tor, but behind a tunnel they chose: say which, rather
     * than calling it exposure. Orbot is named because it is not a VPN like
     * the others — it IS Tor, so somebody on it is still on Tor, just not on
     * Foxy's own.
     *
     * Read from the route every time, never remembered: switch the tunnel off
     * and the banner turns red on its own, with no tap and no memory of what
     * was answered. */
    const viaOrbot = off && !!p.orbot && p.orbot !== 'none';
    const viaVpn = off && !viaOrbot && !!p.vpn;
    const exposed = off && !viaOrbot && !viaVpn;
    /* Working offline, and the radios have come back.
     *
     * "OFFLINE — TAP TO RETRY" is right for a phone with nothing to try; it is
     * wrong for one sitting next to the wifi it just rejoined, where the tap is
     * likely to work and the person has no way of knowing that from Foxy. The
     * path monitor knows, so the banner says so — carefully: a network is not a
     * Tor circuit, and "may be" is the whole of what this can honestly claim. It is the same tap either way. */
    /* Offline is where every session begins now, and the banner says which
     * kind it is. Foxy opens on the home screen and works offline until Tor is
     * up (`homeFirst`, foxy-tor-gate.js), so this line is what the connecting
     * screen used to be:
     *
     *   SECURING YOUR CONNECTION   a network, and Tor at work on a circuit:
     *                              nothing to do, it turns to Secure by itself
     *   OFFLINE - NO CONNECTION    no network at all
     *   CANNOT CONNECT             a network, and Tor has stopped or given up:
     *                              the tap brings the screen with the ways on
     *
     * Read from the route every time, as the rest of this banner is. A stale
     * `up` over no network is no connection (the path monitor wins, as it does
     * in the gate), and with a network under it `up` is not offline at all. */
    const noNet = !!p && p.network === 'none';
    const making = offline && !noNet && (p.tor === 'connecting' || p.tor === 'stuck');
    return {
      torBannerShown: secure || off || offline,
      torBannerText: offline
        ? (noNet ? 'OFFLINE - NO CONNECTION'
           : making ? 'SECURING YOUR CONNECTION' : 'CANNOT CONNECT \u2014 TAP TO RETRY')
        : exposed ? 'IP Address Exposed'
        : viaOrbot ? 'Connected Via Orbot'
        : viaVpn ? 'Connected To Your VPN' : 'Secure Tor Connection',
      torBannerBg: offline ? '#E6D8A8' : exposed ? '#FF5C5C'
        : (viaOrbot || viaVpn) ? '#E6D8A8' : '#BFE3EC',
      torBannerInk: offline ? '#3A2F0B' : exposed ? '#3A0B0B'
        : (viaOrbot || viaVpn) ? '#3A2F0B' : '#123642',
      // read by the banner's tap, which is the way back out of offline
      torBannerOffline: offline,
      // and whether there is anything for that tap to announce: Tor is already at it
      torBannerMaking: making,
    };
  }
  /* amount: the keypad, for sending, receiving and making a token. */
  /** @param {RenderContext} c */
  renderAmount(c) {
    const { s, sc, sendOver, val } = c;
    const sendHeld = /** @type {any} */ (c).sendHeld || '';
    const keys = ['1', '2', '3', '4', '5', '6', '7', '8', '9', '00', '0'].map(k => ({
      label: k, size: '30px', tap: () => this.press(k),
    }));
    return {
      isAmount: sc === 'amount',
      nextFur: (val > 0 && !sendOver)
        ? "radial-gradient(120% 84% at 26% 0%,rgba(255,240,220,.26),"
          + "rgba(255,240,220,0) 62%),"
          + "linear-gradient(168deg,rgba(247,154,60,.62),rgba(232,98,42,.72) 48%,"
          + "rgba(194,74,27,.78)),url('foxy-fur.webp')"
        : 'none,none,none',
      _amtOverStash: (this._amtOver = !!sendOver) ? 1 : 0,
      nextSh: (val > 0 && !sendOver) ? 'inset 0 2px 0 rgba(255,255,255,.4),inset 0 -4px 0 rgba(0,0,0,.16),0 12px 24px rgba(var(--acc-rgb),.34)' : 'none',
      nextBg: (val > 0 && !sendOver) ? 'var(--acc)' : 'rgba(var(--ink-rgb),.14)',
      nextInk: (val > 0 && !sendOver) ? CTA_INK(s) : 'rgba(var(--ink-rgb),.4)',
      /* Offline, a dollar amount is converted at whatever price this phone was
       * last told, which may be hours old. The person naming the amount is the
       * one who carries that, so it is said under the figure, in the age's own
       * words, rather than left to a chip on another screen. Only where it is true: with a route, or in sats, there is
       * nothing to warn about. */
      /* And, when the amount is over the balance only because part of it is
       * held back with the mint, that — the block's own words (heldBlocks).
       * It goes first: it is why this payment cannot go. */
      priceWarn: sendHeld ? sendHeld
        : (this.offlineNow() && s.unit === 'USD' && this.satUsd())
        ? 'WARNING: This is based on the price of Bitcoin '
          + (this.priceAgo() ? this.priceAgo().toLowerCase() : 'from a moment ago') + '.'
        : '',
      priceWarnShown: (sendHeld
        || (this.offlineNow() && s.unit === 'USD' && this.satUsd())) ? '1' : '0',
      amountTitle: 'SET AMOUNT',
      amountSubtitle: s.flow === 'onchain'
        ? 'How much to send on chain?'
        : s.flow === 'transfer'
        // what is at the mint it leaves, so the amount is typed against it
        ? 'From ' + (this.mintNameOf(s.trFrom) || 'that mint') + ' \u00b7 \u20bf '
          + this.group(this.trFromSats()) + ' there'
        : s.flow === 'deposit' ? 'How much do you want to deposit?'
        : s.flow === 'cardAdd' ? 'How much to add to your card?'
        : s.flow === 'cardWd' ? 'How much to withdraw?'
        : s.flow === 'cardLimit' ? 'What would you like the daily limit to be?'
        : s.flow === 'receive' ? 'How much to receive?'
        : 'How much to send?',
      hideSkip: true,
      /* A second answer under NEXT, for the card question that has one that is
       * not a number: everything on the card, or, for the daily limit, no
       * limit at all, which is how one is removed (26f-flashcard.js). */
      amtAlt: s.flow === 'cardWd' || s.flow === 'cardLimit',
      amtAltLabel: s.flow === 'cardWd' ? 'ALL OF IT (' + this.fcPrice((s.fc && s.fc.balance) || 0) + ')'
        : s.flow === 'cardLimit' ? 'NO LIMIT' : '',
      amtAltTap: () => {
        if (this.state.flow === 'cardWd') this.fcWithdrawPin(0);
        else if (this.state.flow === 'cardLimit') this.fcLimitConfirm(0);
      },
      next: () => {
        // a card's amount: the screens that asked for it take it from here (26f-flashcard.js)
        if (/^card/.test(String(this.state.flow))) { this.fcAmountNext(); return; }
        if (this.state.flow === 'transfer') { this.trNext(); return; }
        if (this.state.flow === 'onchain') { if (!sendOver) this.ocNext(); return; }
        /* Over the balance already has its own line under the amount
         * (sendOverLabel), so the refusal is explained on screen and a toast
         * would only repeat it. Nothing said why a NEXT at zero did nothing,
         * which is the same wall the split screen's minimum was. */
        if (sendOver) return;
        if (val <= 0) { this.toast('Type an amount first.', true); return; }
        /* One wallet holding one asset, so there is nothing to pick: a send
         * goes straight to its confirmation, anything else opens a Lightning
         * invoice.
         *
         * This used to ask clOneWallet() and clAsset() — true and 'BITCOIN'
         * since the fork's other wallets went — and fall through to a
         * `payFrom` or `asset` picker when they said otherwise. Neither screen
         * renders anything. Receiving went the same way through clGoRail,
         * whose one rail with a screen of its own is Lightning; the receive
         * screen's NETWORK chip is what chooses Cashu or on chain from there
         * (finding 19). The same two paths, said plainly. */
        if (this.state.flow === 'send') {
          this.setState(p => ({ payFrom: 'BITCOIN', screen: 'sendConfirm', stack: p.stack.concat([p.screen]) }));
        } else {
          this.setState({ asset: 'BITCOIN' });
          this.renderVals().pickLightning();
        }
      },
      pickLightning: () => { this.setState(p => ({ network: 'LIGHTNING', depositVia: '', screen: 'confirm', stack: p.stack.concat([p.screen]) })); this.openReceive(); },
      keys: keys, del: () => this.press('del'),
      amountDisplay: s.unit === 'SATS' ? '₿ ' + (s.amount === '' ? '0' : this.display()) : '$ ' + this.display(),
      /* The other unit, under the one being typed.
       *
       * Built from the keypad rather than from any screen's own figure — an
       * earlier definition took its number from elsewhere and sat stale while
       * this one changed. No price means no line, which is the same rule
       * wantedSats follows rather than inventing a rate. */
      amountSub: (() => {
        /* Offline, asking to be paid, there is no second figure: this phone is
         * not converting, so it has no sats to show. The payer's phone says
         * what the amount makes and this phone agrees to it or does not
         * (`dollarsOnly`). */
        if (this.dollarsOnly()) return '';
        const px = this.satUsd();
        if (!px) return '';
        const sats = this.wantedSats() || 0;
        return s.unit === 'SATS'
          ? '$ ' + this.usd(sats * px)
          : '₿ ' + this.group(sats);
      })(),
      /* Hidden, not removed: it is a 46px circle above the keypad, and taking
       * it out of the flow moves every key under the thumb mid-entry — the
       * same reason PASTE ECASH is hidden rather than dropped. */
      swapVis: this.dollarsOnly() ? 'hidden' : 'visible',
      swapPE: this.dollarsOnly() ? 'none' : 'auto',
      toggleUnit: () => this.toggleUnit(),
      // a token carries its own amount, so the two are alternatives
      // gone entirely once there is an amount, back when the field is cleared:
      // a token carries its own value, so the two cannot both be true
      // hidden rather than removed: taking it out of the flow moves the keypad
      // and the amount under the user's thumb mid-entry
      // receiving only: there is nothing to paste into a payment you are making
      pasteSlot: false,
      // NEXT sits on the same line as home's menu button either way — the
      // paste button below it is 56px plus a 10px gap, so the padding absorbs
      // the difference when it is not there
      // NEXT sits where SHARE does on the receive invoice screen
      amtPad: s.flow !== 'send' ? '7px 28px 26px' : '7px 28px 70px',
      pasteVis: parseFloat(s.amount) > 0 ? 'hidden' : 'visible',
      pastePE: parseFloat(s.amount) > 0 ? 'none' : 'auto',
      ecashInk: !(parseFloat(s.amount) > 0) ? 'var(--ink)' : 'rgba(var(--ink-rgb),.3)',
      ecashBorder: !(parseFloat(s.amount) > 0)
        ? 'rgba(var(--acc-rgb),.6)' : 'rgba(var(--ink-rgb),.12)',
      ecashCur: !(parseFloat(s.amount) > 0) ? 'pointer' : 'default',
      scanEcash: () => this.scanEcashToken(),
      // tokenMode is not cleared on the way out of the send flow, so it has to
      // be read together with the flow — otherwise generating once leaves the
      // wrong button on the receive screen
      // Token mode has no recipient by definition, so a recipient is what ends
      // it. Keying on the flow alone left an lnurl send showing GENERATE
      // ECASH TOKEN, because that is a send too.
      tokenMode: !!s.tokenMode && s.flow === 'send' && !s.recipient,
      notTokenMode: !(s.tokenMode && s.flow === 'send' && !s.recipient),
      makeCta: s.makeBusy ? 'MAKING\u2026' : 'GENERATE ECASH TOKEN',
      makeInk: parseFloat(s.amount) > 0 ? 'var(--ink)' : 'rgba(var(--ink-rgb),.3)',
      makeBorder: parseFloat(s.amount) > 0
        ? 'rgba(var(--acc-rgb),.6)' : 'rgba(var(--ink-rgb),.12)',
      makeCur: parseFloat(s.amount) > 0 ? 'pointer' : 'default',
      makeEcash: () => this.makeEcashToken(),
      pasteEcash: () => this.pasteEcashToken(),
      nextAnim: (val > 0 && !sendOver) ? 'shineLoopFur 3.4s cubic-bezier(.32,0,.28,1) 3s infinite' : 'none',
      amountInk: sendOver ? '#FF5C5C' : 'var(--acc)',
      sendOverShown: sendOver ? '1' : '0',
      sendOverLabel: sendHeld ? 'PENDING WITH THE MINT' : 'MORE THAN YOUR BALANCE',
      // withdrawing from a card, the ceiling is the card's and the line says so
      ...(s.flow === 'cardWd' ? { sendOverLabel: 'MORE THAN THE CARD HOLDS' } : {}),
    };
  }

  /* confirm: the receive screen — the invoice, its QR, what it asks for. */
  /** @param {RenderContext} c */
  renderReceive(c) {
    const { s, sc, val, landed, invSats, sats } = c;
    const usd = invSats ? (invSats / 1e8) * this.px()
      : (s.unit === 'SATS' ? landed / 1e8 * this.px() : landed);
    const cashu = s.recvRail === 'CASHU';
    const onchain = s.recvRail === 'ON-CHAIN';
    // the same screen test as renderVals: no request unless this screen is up
    const creq = () => (sc === 'confirm'
      ? this.railRequest(s.invoiceIsAddress ? 0 : window.FoxyWallet.amountOf(s.invoice)) : '');
    /* On chain the code is an address, with the amount only as a hint: it can
     * be paid with anything, and under the mint's floor it is lost. */
    const ocSats = () => (s.invoiceIsAddress ? 0 : (window.FoxyWallet.amountOf(s.invoice) || 0));
    const ocCode = () => {
      if (sc !== 'confirm' || !onchain) return '';
      const address = this.ocReceiveAddress();
      return address ? window.FoxyWallet.bip21(address, ocSats()) : '';
    };
    const recvReady = () => !!(s.recvVia === 'wire' || s.network === 'BANK WIRE'
      || (onchain ? ocCode() : cashu ? creq() : s.invoice));
    return {
      isConfirm: sc === 'confirm',
      /* COPY and SHARE wait for the code. Until the rail on screen has
       * something real behind its QR — the invoice, the request, the address —
       * there is nothing to copy or share, and they are greyed and do nothing. */
      recvReadyDim: recvReady() ? '1' : '0.35',
      invoiceCopy: () => {
        if (!recvReady()) return;
        const wire = s.recvVia === 'wire' || s.network === 'BANK WIRE';
        if (!wire && onchain && ocCode()) {
          this.toast(this.copyText(ocCode()) ? 'Address Copied' : 'Could not copy');
          return;
        }
        if (!wire && cashu && creq()) {
          /* Device-only, like a token. A Cashu request of Foxy's names the
           * onion address this phone is listening on, and the general
           * pasteboard syncs to every Apple device the person owns (audit
           * finding 6). Nothing about where this phone can be reached belongs
           * on someone's iPad. */
          this.toast(this.copySecret(creq()) ? 'Request Copied' : 'Could not copy');
          return;
        }
        if (!wire && s.invoice) {
          this.toast(this.copyText(s.invoice) ? 'Invoice Copied' : 'Could not copy');
          return;
        }
        this.toast(wire ? 'Info Copied' : 'Nothing to copy yet');
      },
      /* A payer has tapped and is looking at this screen for the four digits
       * to match against their own. Above the amount, the same size as it and
       * in the accent, because it is the thing being checked at that moment —
       * not a caption under a QR code. The QR stays
       * exactly as it was: somebody else may still be scanning it. */
      /* Offline, the figure is the dollars asked for and there is no sat line
       * under it. This phone has refused to convert — its price may be hours
       * old — so a sat figure here would be a conversion it is not making, and
       * a wrong one: the sats are whatever the paying phone's current price
       * makes of the amount, which is the number this phone is then asked to
       * agree to (`dollarsOnly`, `priceTermsCard`). */
      confirmAmount: val <= 0 ? 'ANY AMOUNT'
        : this.dollarsOnly() ? '$ ' + this.usd(val)
        : s.asset === 'BITCOIN' ? this.money(sats).main : '$ ' + this.usd(usd),
      confirmAlt: this.dollarsOnly() ? '' : s.asset === 'BITCOIN' ? this.money(sats).sub : '',
      showSats: s.asset === 'BITCOIN' && val > 0 && !this.dollarsOnly(),
      confirmTitle: onchain ? 'RECEIVE ON CHAIN' : 'RECEIVE INVOICE',
      confirmNetwork: onchain ? 'ON-CHAIN' : cashu ? 'CASHU' : (s.network || 'LIGHTNING'),
      // the middle of the QR says which it is: the bolt, ecash, or a coin
      qrBolt: !cashu && !onchain,
      qrEcash: cashu,
      qrChain: onchain,
      /* The code shares the screen with the mint's floor on this network — and
       * on a short phone it has to give way.
       *
       * It was a flat 300px, which is right on a 15 Pro Max and 36pt too tall
       * on an iPhone XS: the four buttons under it kept their circles and lost
       * their labels off the bottom of the screen. The XS
       * is the oldest phone Foxy will ever run on — iOS 17 needs an A12 — so
       * it is the floor to fit, and the SE is shorter still.
       *
       * A viewport-height cap leaves every tall phone exactly as it was and
       * shrinks the code on the ones that cannot afford it; the box also
       * shrinks under flex pressure (`flex:0 1 auto` in the markup), so a
       * screen shorter than any of these still gets a whole row of buttons
       * rather than half of one. A QR that is smaller still scans.
       *
       * The cap is a `max-width`/`max-height` pair rather than the `min()`
       * that says the same thing in one value: the snapshot renderer drops a
       * declaration it cannot parse, and `min()` is one of them, so writing it
       * that way would have left every receive snapshot with no size at all
       * and nothing to catch the next phone that does not fit. */
      qrBoxW: onchain ? '252px' : '300px',
      qrBoxCap: onchain ? '30vh' : '34vh',
      // what the network costs the person to know, under the code
      recvNote: onchain ? this.ocReceiveNote() : '',
      recvNoteShown: onchain,
      recvNoteInk: 'rgba(var(--ink-rgb),.55)',
      /* No network to pick offline: Cashu is the only one this phone can offer
       * by itself, so the chooser says why rather than listing two rails that
       * cannot be made. */
      pickNetwork: () => {
        if (this.offlineNow()) { this.offlineNo('Choosing a network'); return; }
        this.chooseRail(onchain ? 'ON-CHAIN' : cashu ? 'CASHU' : 'LIGHTNING',
          rail => this.setState({ recvRail: rail }));
      },
      // the pill goes grey with it, so it does not look tappable
      networkPillDim: this.offlineNow() ? '0.45' : '1',
      openNote: () => this.editSendNote(),
      shareQr: () => {
        if (!recvReady()) return;
        const inv = onchain ? ocCode() : cashu ? creq() : s.invoice;
        if (!inv) { this.toast('Nothing to share yet.', true); return; }
        if (!window.FoxyWallet.share(inv)) this.toast('Sharing is only available in the app.', true);
      },
      closeToHome: () => this.closeReceive(),
      // tap to pay: a payer's phone connected, and this is the code it shows
      tapCodeShown: sc === 'confirm' && !!s.tapShownCode && !s.tapCardOff,
      tapShownCode: s.tapShownCode || '',
      hideTapCode: () => this.tapDropPayer(),
      /* TAP, and this time it does something.
       *
       * There was no button here for a day. That was right while the payer was
       * the phone on the air: this screen was already listening, so a button
       * would have explained itself and nothing else, and a control nobody
       * presses is only in the way.
       *
       * The roles are the other way round now (TapLink.swift). This phone is
       * the one that advertises, and a receive screen that did it by itself
       * would be a till standing on the air for as long as it was open. So the
       * press is the arming, and nothing goes out without it.
       *
       * It lights up while it is on the air, and goes back to plain once a
       * payer is found — pressing it again then is the next customer, which
       * the bridge answers with a fresh service UUID and fresh keys. */
      tapArm: () => this.tapArm(),
      /* On the air, and saying so over the code somebody was about to scan.
       *
       * A QR and an orange card cannot both be the instruction. Once TAP is
       * pressed the instruction is "hold your phone here", so the card covers
       * the code until a payer arrives — and then the same card becomes the
       * four digits, which is the next thing to look at.
       * The X lifts it and the QR is back, ready to be scanned instead. */
      tapArmedShown: sc === 'confirm' && !!s.tapArmed && !s.tapShownCode && !s.tapCardOff,
      /* What it is actually doing. It said HOLD A PHONE HERE whatever was
       * happening underneath, including when the radio had been refused and
       * the phone was not on the air at all (26d-tap.js). */
      tapArmedHint: s.tapRecvStage === 'connecting' ? 'CONNECTING\u2026'
        : s.tapNotYet ? String(s.tapNotYet).toUpperCase()
        : 'HOLD A PHONE HERE',
      /* The label never changes. It is TAP, the way SCAN is SCAN — a button
        * that renames itself is a button somebody has to read twice. What says this phone is on the air is the accent, which
        * it shares with the card over the QR, and the card itself. */
      /* Greyed with the radio off, denied or missing: pressing it then says
       * "Enable Bluetooth to use tap to pay.". */
      tapArmBg: ['off', 'denied', 'unsupported'].indexOf(s.tapRecvStage) >= 0 ? 'rgba(var(--ink-rgb),.18)'
        : s.tapArmed ? 'var(--acc)' : 'var(--ink)',
      tapArmInk: ['off', 'denied', 'unsupported'].indexOf(s.tapRecvStage) >= 0 ? 'rgba(var(--ink-rgb),.45)'
        : '#050505',
      /* CARD: paid by a card that holds ecash, its PIN typed on this phone
       * (26f-flashcard.js). The button is where TAP was; TAP is the emblem in
       * the middle of the QR. */
      cardPay: () => this.payByCard(),
      scanToReceive: () => this.scanTokenToReceive(),
    };
  }

  /* paid: the confirmation after money moves. A Lightning send ends here. */
  /** @param {RenderContext} c */
  renderPaid(c) {
    const { s, sc, sats } = c;
    return {
      isPaid: sc === 'paid',
      /* Outgoing shows what left the wallet; incoming shows what arrived.
       *
       * This screen is the one a Lightning send lands on — "WITHDRAWAL SENT" —
       * and it showed the amount while the balance fell by amount plus fee. */
      paidHeadline: this.money(sats + (s.payOut ? (this._lastFee || 0) : 0)).main,
      paidHeadlineSub: this.money(sats + (s.payOut ? (this._lastFee || 0) : 0)).sub,
      /* What the total is made of. Only outgoing, and only when there is a
       * fee — "SENT 102 / FEE 0" says nothing the headline did not. */
      paidBreakdown: !!s.payOut && (this._lastFee || 0) > 0,
      paidSentAmt: this.money(sats).main,
      paidFeeAmt: this.money(this._lastFee || 0).main,
      paidAddedTo: s.payOut ? this.paidTargetLabel()
        : (s.asset === 'BITCOIN' ? 'Bitcoin Balance' : 'Cash Balance'),
      paidStack: this.fitStack(H => this.satsStack(sats, s.recv && s.recv.live, H)),
      paidBolts: this.boltField((s.recv && s.recv.live) === 'in'),
      paidBoltFlash: (s.recv && s.recv.live) === 'in' ? 'boltFlash 1s cubic-bezier(.3,0,.5,1) both' : 'none',
      paidChromeAnim: (s.recv && s.recv.live) === 'out' ? 'chromeOut .23s cubic-bezier(.4,0,.7,.4) 60ms both' : 'none',
      paidBg: (s.recv && s.recv.live) === 'out' ? '#050505'
        : (s.recvResolved ? "var(--acc)" : 'var(--bg)'),
      paidGrid: ((s.recv && s.recv.live) === 'out') ? 'rgba(var(--ink-rgb),.05)' : (s.recvResolved ? 'transparent' : 'rgba(var(--ink-rgb),.05)'),
      paidInk: s.recvResolved ? '#050505' : 'var(--ink)',
      paidInkDim: s.recvResolved ? 'rgba(5,5,5,.5)' : 'rgba(var(--ink-rgb),.5)',
      paidBadgeBg: s.recvResolved ? '#050505' : 'var(--acc)',
      paidTitle: s.paidSays || (s.payOut ? 'WITHDRAWAL SENT' : 'PAYMENT RECEIVED'),
      paidAddedLabel: s.payOut ? 'SENT TO' : 'ADDED TO',
      paidBadgeTick: s.recvResolved ? 'var(--acc)' : CTA_INK(s),
      paidLive: (s.recv && s.recv.live) !== 'gone',
      dismissPaid: () => {
        this.setState(p => ({ recv: Object.assign({}, p.recv, { live: 'out' }) }));
        setTimeout(() => {
          // counts to whatever the wallet holds now, in either direction
          this.settleAnimate('btc');
          // back to whatever the confirmation interrupted, when it interrupted
          // something. Cleared either way so it cannot leak into the next one.
          const back = this._returnTo;
          this._returnTo = null;
          if (back) {
            setTimeout(() => this.setState({ screen: back.screen, stack: back.stack }), 0);
          }
          this.paidDismissed();
          this.setState({ screen: 'home', stack: [], amount: '', asset: '', network: '', unit: 'USD', payOut: false, recv: Object.assign({}, this.state.recv, { live: 'gone' }) });
        }, 450);
      },
    };
  }

  /* sendHow, sendType, sendScan: the ways to pay someone.
   *
   * There is no tap screen any more. It existed to be the payer's arming
   * gesture, and the payer no longer arms anything: this phone listens from
   * home and from here, and the merchant's press is what puts a payment on the
   * air (TapLink.swift). */
  /** @param {RenderContext} c */
  renderSend(c) {
    const { s, sc, emailOk } = c;
    /* Offline, two of these four cannot work and the other two can.
     *
     * TYPE and CONTACTS both end in a Lightning address, which has to be
     * resolved and then paid — network, twice over. SCAN and PASTE can carry a
     * Cashu payment request, which a phone with the right pieces already held
     * can answer without asking the mint anything (19-bill-split.js), so they
     * stay live. MAKE ECASH is the same send and stays live too.
     *
     * Greyed rather than hidden: a control that disappears leaves somebody
     * hunting for a feature they used yesterday, and the row of four is a shape
     * people learn. Dimmed, still tappable, and it says why. */
    const off = this.offlineNow();
    return {
      isSendHow: sc === 'sendHow', isSendType: sc === 'sendType', isSendScan: sc === 'sendScan',
      pickType: () => {
        if (off) { this.offlineNo('Typing an address'); return; }
        this.setState(p => ({
          screen: 'sendType', stack: p.stack.concat([p.screen]), flow: 'send',
          asset: 'DOLLARS', recipientKind: 'email', unit: 'USD', amount: '',
        }));
      },
      pickPaste: () => {
        if (navigator.clipboard && navigator.clipboard.readText) {
          navigator.clipboard.readText()
            .then(t => this.acceptTarget(t))
            .catch(() => this.toast('Could not read the clipboard. Try scan.', true));
          return;
        }
        this.toast('Paste is not available here. Use scan.', true);
      },
      camOn: !!s.camOk, camOff: !s.camOk,
      scanHint: !s.camOk ? 'CAMERA IS OFF' : (s.scanWhy || 'HOLD STEADY'),
      /* The viewfinder is not a button.
       *
       * It holds a live camera that reads codes on its own — tapping it used
       * to open the full-screen scanner on top, which froze the preview
       * underneath and did nothing the preview was not already doing. Its
       * twin on the scan screen was disarmed earlier; this is the one on the
       * send screen. */
      howTap: () => {},
      scanTap: () => {},
      emailDraft: s.emailDraft || '',
      onEmail: e => this.setState({ emailDraft: e.target.value }),
      // a disabled CTA goes grey rather than a dimmed accent
      emailActSh: emailOk ? 'inset 0 2px 0 rgba(255,255,255,.4),inset 0 -2px 0 rgba(0,0,0,.16),0 5px 12px rgba(var(--acc-rgb),.3)' : 'none',
      emailSh: emailOk ? 'inset 0 2px 0 rgba(255,255,255,.4),inset 0 -4px 0 rgba(0,0,0,.16),0 12px 24px rgba(var(--acc-rgb),.34)' : 'none',
      emailAnim: emailOk ? 'shineLoop 3.4s cubic-bezier(.32,0,.28,1) 3s infinite' : 'none',
      emailBg: emailOk ? 'var(--acc)' : 'rgba(var(--ink-rgb),.14)',
      emailInk: emailOk ? CTA_INK(s) : 'rgba(var(--ink-rgb),.4)',
      emailNext: () => { if (emailOk) this.setState(p => ({ screen: 'amount', stack: p.stack.concat([p.screen]), recipient: (p.emailDraft || '').trim() })); },
      // TYPE, CONTACTS and PASTE are always on this screen. The markup still
      // asks, so the flags stay; what it asked — clHide over the fork's hide-*
      // props, which nothing here sets — is gone (finding 19).
      clTypeOn: true, clContactsOn: true, clPasteOn: true,
      // and offline the two that need a network are dimmed, not removed
      clTypeDim: off ? '0.38' : '1',
      clContactsDim: off ? '0.38' : '1',
      goMakeEcash: () => this.setState(p => ({
        screen: 'amount', stack: p.stack.concat([p.screen]),
        flow: 'send', tokenMode: true, asset: 'BITCOIN',
        // dollars, like receive's pad; the toggle swaps to sats
        amount: '', unit: 'USD', recipient: '', recipientKind: '',
        note: '', noteDraft: '',
      })),
    };
  }

  /* sendDone: the sending overlay and what it settles into. */
  /** @param {RenderContext} c */
  renderSent(c) {
    const { s, sc, sats } = c;
    const sendPhase = s.sendPhase || 'in';
    return {
      isSendDone: sc === 'sendDone',
      // eight seconds in and still sending: say so, and offer the way off
      sendSlowShown: sc === 'sendDone' && !!s.sendSlow && (sendPhase === 'in'),
      sendStopWaiting: () => {
        /* Still behind something else — the change top-up, usually — means
         * the payment has not begun, and it is dropped rather than made later
         * (`giveUpWaiting`). One already with the mint or the other phone
         * cannot be taken back, and is left to finish. */
        const W = window.FoxyWallet;
        const holder = W && W.proofLockHolder && W.proofLockHolder();
        const notBegun = !!holder && !/^(sendToken|pay|payLnurl)$/.test(String(holder.what || ''));
        if (W && W.giveUpWaiting) W.giveUpWaiting();
        console.log(notBegun
          ? '[foxy] sending: the person stopped waiting before the payment was made; dropped'
          : '[foxy] sending: the person stopped waiting; the payment is in history, unconfirmed');
        // `sendPhase` left at 'in' kept this phone from listening for a tap
        this.setState({ screen: 'home', stack: [], sendSlow: false, sendPhase: null });
        this.toast(notBegun ? 'Stopped. The payment was not made.' : 'Still being confirmed. It is in History.', false);
      },
      sentTitle: 'PAYMENT SENT',
      sendingNow: sendPhase === 'in' || sendPhase === 'onchain',
      sentDone: sendPhase === 'done' || sendPhase === 'settled',
      onchainSending: sendPhase === 'onchain',
      etaClock: Math.floor((s.etaLeft == null ? 600 : s.etaLeft) / 60) + ':' + String((s.etaLeft == null ? 600 : s.etaLeft) % 60).padStart(2, '0'),
      copyTracking: () => {},
      // with how far it has got, when it is big enough to take a while
      pendingLabel: s.recvPending ? 'PAYMENT PENDING'
        : (Number(s.sendPct) > 0 && Number(s.sendPct) < 100 ? 'SENDING ' + Math.round(s.sendPct) + '%'
          // waiting behind the change top-up says so, not SENDING to nobody
          : (this.sendBehindChange() ? 'FINISHING CHANGE' : 'SENDING')),
      trackLabel: s.recvPending ? 'VIEW PENDING TRANSACTION' : 'COPY TRACKING INFO',
      dismissOnchain: () => (s.recvPending ? this.dismissPending() : this.dismissOnchain()),
      /* What left the wallet, not what the recipient got.
       *
       * This said "9,862 withdrawn" after a payment that moved 9,877. The
       * amount and the fee are both real, and the one worth showing on a
       * confirmation is the one the balance actually fell by. */
      /* What left the wallet, read from a key nothing else clears. */
      sentHeadline: this.money(sats + (this._lastFee || 0)).main,
      // the dollar figure, matching the received screen
      /* asset is never set on the live send path — it exists only in the
       * preview fixtures — so branching on it left this blank. */
      sentHeadlineSub: this.money(sats + (this._lastFee || 0)).sub,
      /* What the total is made of.
       *
       * The headline is what left the wallet. Someone who typed 500 and sees
       * 502 needs the other two numbers, or the difference looks like an
       * error. Hidden when the fee is zero, because 500 and 0 on two lines
       * says nothing the headline did not. */
      sentBreakdown: (this._lastFee || 0) > 0,
      sentSentAmt: this.money(sats).main,
      sentFeeAmt: this.money(this._lastFee || 0).main,
      // the money stays on screen through the strike and past it — DONE clears it
      sentStack: this.fitStack(H => this.satsStack(sats, 'in', H)),
      sentToLabel: s.recvPending ? 'DELIVERING TO'
        : (sendPhase === 'done' || sendPhase === 'settled') ? 'DELIVERED TO' : 'SENDING TO',
      sentTo: s.recipientKind === 'email' ? (s.recipient || '').toUpperCase() : this.shortId(s.recipient || ''),
      sentBg: (sendPhase === 'done' || sendPhase === 'settled')
        ? "var(--acc)" : 'var(--bg)',
      sentGrid: (sendPhase === 'done' || sendPhase === 'settled') ? 'transparent' : 'rgba(var(--ink-rgb),.05)',
      sentInk: (sendPhase === 'done' || sendPhase === 'settled') ? '#050505' : 'var(--ink)',
      sentInkDim: (sendPhase === 'done' || sendPhase === 'settled') ? 'rgba(5,5,5,.5)' : 'rgba(var(--ink-rgb),.38)',
      sentBolts: this.boltField(sendPhase === 'done'),
      sentBoltFlash: sendPhase === 'done' ? 'boltFlash 1s cubic-bezier(.3,0,.5,1) both' : 'none',
      // dismissing the sent / pending screen: chrome lifts away, then home lands
      sentExitAnim: s.sendExit ? 'chromeOut .4s cubic-bezier(.4,0,.7,.4) both' : 'none',
      sentHome: () => {
        if (s.sendExit) return;
        this.setState({ sendExit: true });
        setTimeout(() => {
          this.settleAnimate('btc');
          this.setState({
            screen: 'home', stack: [], amount: '', asset: '', network: '', unit: 'USD',
            flow: 'receive', recipient: '', emailDraft: '', sendPhase: null, sendExit: false,
          });
        }, 380);
      },
    };
  }

  /* tokenOut: a generated ecash token. */
  /** @param {RenderContext} c */
  renderToken(c) {
    const { s, sc } = c;
    return {
      isTokenOut: sc === 'tokenOut',
      // made to pay someone at this mint instead of by Lightning (payThisMintWithToken)
      tokenForPayee: !!s.tokenForPayee,
      tokenAmount: (() => {
        const n = s.tokenOutSats
          || ((window.FoxyWallet && window.FoxyWallet.lastToken() || {}).sats) || 0;
        return this.money(n).main;
      })(),
      tokenAlt: (() => {
        const n = s.tokenOutSats
          || ((window.FoxyWallet && window.FoxyWallet.lastToken() || {}).sats) || 0;
        return this.money(n).sub;
      })(),
      tokenShowAlt: true,
      // only when the mint actually charged for the swap
      tokenHasFee: !!s.tokenOutFee,
      tokenFee: this.money(s.tokenOutFee || 0).main,
      /* The badge in the middle of the token's code: on a still code, which
       * has the correction to spare for it, and not on one that moves
       * (TOKEN_QR, 07-history-tokens-mints.js). */
      tokenQrBadge: (() => {
        if (sc !== 'tokenOut') return true;
        const W = window.FoxyWallet;
        const tk = s.tokenOut || ((W && W.lastToken && W.lastToken() || {}).token);
        return !(tk && W && W.tokenQrAnimates && W.tokenQrAnimates(tk));
      })(),
      // falls back to what is on file, so navigating away cannot lose it
      tokenOutQr: (() => {
        /* Only on its own screen. It was drawn on every render of every
         * screen, from the last token on file — thirty times in half a
         * minute for a 3,149-character token nobody was looking at, each one
         * a code too long to make. */
        if (sc !== 'tokenOut') return '';
        const tk = s.tokenOut
          || ((window.FoxyWallet && window.FoxyWallet.lastToken() || {}).token);
        // an animated code's latest frame (syncTokenQr), so a render does not put the dense one back
        if (tk && this._tokQr && this._tokQr.token === tk && this._tokQr.src) return this._tokQr.src;
        return tk ? window.FoxyWallet.qr(tk) : '';
      })(),
      // one word: 'COPY TOKEN' is wide enough to wrap NFC onto its own row
      tokenOutCta: s.tokenCopied ? 'COPIED' : 'COPY',
      tokenOutShare: () => window.FoxyWallet.share(
        this.state.tokenOut
        || ((window.FoxyWallet && window.FoxyWallet.lastToken() || {}).token) || ''),
      tokenNote: () => this.editTokenNote(),
      tokenOutCopy: () => {
        const ok = this.copySecret(this.state.tokenOut || '');
        this.setState({ tokenCopied: ok });
        if (!ok) this.toast('Could not copy.', true);
      },
      tokenOutDone: () => {
        window.FoxyWallet.clearLastToken();
        this.setState({ screen: 'home', stack: [], tokenOut: '', tokenCopied: false, tokenForPayee: false });
        // a watch not kept ends with its screen; a kept one goes on elsewhere
        setTimeout(() => this.claimWatchTick(), 0);
        this.settleAnimate('btc');
      },
    };
  }

  /* reqOffer: a scanned payment request, on the same shell a Lightning send
   * is confirmed on (confirmSpec). Foxy delivers it where
   * the request asks — its phone over Tor, or Nostr — or makes a token to
   * show when it names nowhere Foxy can reach (07-request-delivery.js). */
  /* THEIR BITCOIN PRICE, for a receiver with no route.
   *
   * It was a card, and a card is for something that went wrong. This is a
   * person looking at two figures and deciding — which is exactly what the
   * confirmation shell is for, and what every other decision about money in
   * Foxy uses.
   *
   * The order is: what is being offered, then the price behind it,
   * then how that price compares with the last one this phone saw, then the
   * question. The comparison is worked out here, from what this phone knows,
   * so a payer cannot dress it up (`readQuote`).
   */
  priceSpec() {
    const q = this.state.priceQ || {};
    /* Answered, and still here.
     *
     * A yes is followed by whatever that yes set in motion — a mint quote, a
     * swap — and over Tor on a phone with no route that can take the whole 25
     * seconds before it gives up. This screen stays up for it. It used to clear
     * the figures the moment the answer went, so what the person watched for
     * those seconds was this same screen showing "AMOUNT OFFERED ₿ 0", "THE
     * PAYER'S BITCOIN PRICE OF $0" and "this phone has never seen a bitcoin
     * price" — the question they had just answered, asked again with nothing in
     * it.
     *
     * So the figures stay, and the screen says it is working. */
    const said = !!this.state.priceSaid;
    const sats = Math.round(Number(q.sats) || 0);
    const usd = Number(q.usd) || 0;
    const theirs = Math.round(Number(q.theirRate) || 0);
    const pct = (q.differsPct == null) ? null : Number(q.differsPct);
    const ago = this.agoWords ? this.agoWords(Number(q.myRateAgeMs) || 0) : '';
    /* Under a tenth of a percent is the same price as far as anybody reading
     * this is concerned, and "0.0% higher" reads as a warning about nothing. */
    const near = pct != null && Math.abs(pct) < 0.1;
    /* The copy, the same screen from either side.
     *
     * What it says, in order: that the price has moved since this phone was
     * last online, what it is now, by how much it moved, and what that does to
     * the sats — which is the part a person can weigh. A dollar amount at a
     * higher price is fewer sats and at a lower one is more, whichever way the
     * money is going, so the direction is the opposite of the difference.
     *
     * The amount stays at the top. It is not in the copy, and it is what is
     * being agreed to. */
    const paying = q.side === 'pay';
    const verb = paying ? 'pay' : 'receive';
    const doing = paying ? 'paying' : 'receiving';
    const size = pct == null ? '' : (Math.abs(pct) < 1 ? Math.abs(pct).toFixed(1) : String(Math.round(Math.abs(pct))));
    /* The layout: the price is the big figure, because
     * the price is what is being agreed; then the difference, what it does to
     * the sats, and the question, each on its own line down the middle. */
    const intro = pct == null
      ? 'What you ' + verb + ' is based on the Bitcoin price. This phone has no earlier price to compare it with.'
      : near
      ? 'What you ' + verb + ' is based on the Bitcoin price, which is the same as when you were last online.'
      : 'What you ' + verb + ' is based on the Bitcoin price, which has changed since you were last online.';
    const difference = pct == null ? '\u2014' : near ? '0%' : (pct > 0 ? '+' : '\u2212') + size + '%';
    const result = pct == null ? 'There is nothing to compare it with.'
      : near ? 'You are ' + doing + ' the same in terms of sats.'
      : 'You are ' + doing + ' ' + size + '% ' + (pct > 0 ? 'less' : 'more') + ' in terms of sats.';
    return {
      title: 'BITCOIN PRICE',
      subtitle: intro,
      amountLabel: 'CURRENT BITCOIN PRICE',
      amount: '$ ' + this.group(theirs),
      amountSub: '',
      // the question is the buttons; a row asking it again was one too many
      rows: [
        this.cfRow('DIFFERENCE', difference),
        this.cfRow('RESULT', result),
      ].concat(said ? [this.cfRow('YOU AGREED TO THIS PRICE', 'Working out the rest with their phone\u2026')] : []),
      // answered: there is nothing left to reject, and the tap leg owns what happens next
      secondary: said ? null : { label: 'NO, CANCEL', go: () => this.priceAnswer(false) },
      close: said ? null : () => this.priceAnswer(false),
      cta: said ? 'WORKING\u2026' : 'YES, CONTINUE',
      ctaTone: 'go',
      ctaBusy: said,
      go: () => { if (!said) this.priceAnswer(true); },
    };
  }

  /* The one answer, whichever control gave it. Resolves the promise the tap
   * leg is waiting on and leaves the screen it came from. */
  priceAnswer(yes) {
    const say = this._priceSay;
    this._priceSay = null;
    /* Home only when the answer ends it. A yes is followed by a confirmation —
     * the payer's, or this phone's own — and dropping to home in between is a
     * flash of the wrong screen on the way to the right one ("it should go straight to confirmation and not show home in
     * between"). The screen the answer leads to sets itself. */
    /* The figures are kept on a yes, because this screen is still the one
     * showing while the answer is acted on (`priceSpec`). They are dropped
     * when the screen actually leaves, in `syncPriceQ`. */
    /* A receiver that says yes goes back to the screen it was asked on: the
     * invoice, with the four digits. That is what there is to look at while
     * the payer decides — whether the code on their phone is this one — and
     * WORKING… over a spinner showed neither. A payer
     * that says yes is a moment from its own confirmation and stays put. */
    const paying = !!(this.state.priceQ && this.state.priceQ.side === 'pay');
    if (yes && !paying) {
      this.setState(p => (p.stack && p.stack.length
        ? { screen: p.stack[p.stack.length - 1], stack: p.stack.slice(0, -1), priceSaid: false }
        : { priceSaid: true }));
    } else if (yes) this.setState({ priceSaid: true });
    else this.setState({ screen: 'home', stack: [], priceQ: null, priceSaid: false });
    if (typeof say === 'function') say(!!yes);
  }

  /* THEY USE ANOTHER MINT, and the only button that sends.
   *
   * This used to be a card, and agreeing to it opened the ordinary
   * confirmation, which then had to be sent — so the person agreed to a fee and
   * was then asked to agree to the payment, twice for one decision ("when they agree to the use of another mint that should be the
   * last thing they need to do").
   *
   * So it IS the confirmation. Everything it needs is already known — the
   * amount, what the receiver gets, what the crossing costs — and pressing PAY
   * moves the money and makes the payment, in that order, with nothing else to
   * press.
   */
  crossSpec() {
    const c = this.state.crossQ || {};
    const net = Math.round(Number(c.net) || 0);
    /* `fee` is null until the two mints have answered. Until then there is no
     * total to agree to, so the button says what it is doing and does nothing —
     * a button that could be pressed then would be agreeing to a number Foxy
     * has not worked out yet. */
    const known = c.fee != null && isFinite(Number(c.fee));
    const waiting = !known;
    const fee = known ? Math.max(0, Math.round(Number(c.fee))) : 0;
    const total = net + fee;
    const px = this.px();
    const d = (n) => (px ? ' (\u20bf ' + this.group(n) + ')' : '');
    const m = (n) => (px ? '$ ' + this.usd((n / 1e8) * px) : '\u20bf ' + this.group(n));
    return {
      title: 'THEY USE ANOTHER MINT',
      amountLabel: 'TOTAL PAYMENT',
      amount: waiting ? m(net) + ' + fee' : m(total),
      amountSub: (!waiting && px) ? '\u20bf ' + this.group(total) : '',
      /* The four digits of the phone this is going to, first and large, as on
       * every other confirmation a tap opens. It is the one check that the
       * money is going where the person thinks, and this screen sends it. */
      code: this.state.tapCode || '',
      rows: [
        this.cfRow('RECEIVER GETS', m(net), { sub: d(net).trim() }),
        this.cfRow('SWAP FEE', waiting ? 'WORKING IT OUT…' : m(fee),
          { sub: waiting ? '' : d(fee).trim(), ink: 'var(--btc-ink)' }),
        this.cfRow('THEIR MINT', String(c.them || '').toUpperCase(), { half: true }),
        this.cfRow('PAYING FROM', String(c.mine || '').toUpperCase(), { half: true }),
      ].concat(this.peerRateRow()),
      secondary: { label: 'CANCEL', go: () => this.crossAnswer(false) },
      close: () => this.crossAnswer(false),
      cta: waiting ? 'WORKING OUT THE FEE…'
        : 'PAY ' + m(total),
      ctaTone: 'go',
      ctaBusy: waiting || !!this.state.crossBusy,
      go: () => { if (!waiting) this.crossAnswer(true); },
    };
  }

  crossAnswer(yes) {
    if (this.state.crossBusy) return;
    const say = this._crossSay;
    if (!yes) {
      this._crossSay = null;
      /* Said to the phone in hand, or it reads the leaving as a payment lost
       * in flight and offers to scan. */
      const W = window.FoxyWallet;
      if (this.state.tapCode && W && W.tapQuote) {
        W.tapQuote(JSON.stringify({ gaveUp: 'The payer cancelled.' })).catch(() => {});
      }
      this.setState({ screen: 'home', stack: [], crossQ: null });
      if (typeof say === 'function') say(false);
      return;
    }
    /* The button stays where it is and says what it is doing: the move is a
     * real Lightning payment and takes seconds, and a screen that vanished
     * would leave the person wondering whether they had pressed it. */
    this.setState({ crossBusy: true });
    this._crossSay = null;
    if (typeof say === 'function') say(true);
  }

  /* Whose bitcoin price the dollar figures on this screen are in.
   *
   * Nothing at all when they are this phone's own, which is the normal case. A
   * phone with no route is converting at the price the phone it is tapping
   * gave it — fresher than its own and the one this payment is agreed at — and
   * that is worth saying rather than leaving somebody to wonder why the dollars
   * moved.
   */
  peerRateRow() {
    const label = this.peerRateLabel();
    if (!label) return [];
    return [this.cfRow('BITCOIN PRICE', '$ ' + this.group(Math.round(this.peerRate())),
                       { sub: 'theirs, not this phone\u2019s', ink: 'var(--btc-ink)' })];
  }

  requestSpec() {
    const s = this.state;
    const req = s.req;
    /* The open Bluetooth link is a delivery too.
     *
     * `delivery` comes from the transports the request names, and an offline
     * receiver names none — so this screen told the person it would GENERATE
     * ECASH TOKEN and that it would arrive WHEN THEY TAKE IT, while showing the
     * four-digit code of the phone it was about to be handed straight to. It
     * sends; it should say send. */
    const d = req && req.sats > 0
      ? (req.delivery || (req.viaTap ? { kind: 'tap' } : null)) : null;
    const onion = !!(d && d.kind === 'onion');
    const sats = req ? req.sats : 0;
    const mint = req && req.mints[0] ? String(req.mints[0]).replace(/^https?:\/\//, '') : 'any mint';
    /* Paid by tap: the phone it goes to is the one being held against this
     * one, and the four digits are what says so. They are the thing to check
     * before sending, so they are the value of this row rather than a note
     * under it, in the accent so the eye finds them. */
    const byTap = !!(req && req.viaTap && s.tapCode);
    const W = window.FoxyWallet;
    // locked exactly when the send will be (makeTokenForRequest): a key named, and a route
    const lack = (sats > 0 && W && W.sendShortfall)
      ? W.sendShortfall(sats, { locked: !!(req && req.lockTo && !(this.offlineNow && this.offlineNow())) }) : null;
    const to = byTap ? s.tapCode
      : d ? (onion ? 'THEIR PHONE, OVER TOR'
             : d.kind === 'tap' ? 'THE PHONE IN YOUR HAND' : 'THEIR NOSTR INBOX, OVER TOR')
      : (req && !req.transports.length) ? 'A TOKEN TO SHOW THEM' : 'A TOKEN YOU SEND THEM';
    const rows = (byTap ? [] : [this.cfRow('DELIVERED TO', to)]).concat([
      this.cfRow('PAYING FROM', (this.mintName() || 'THIS MINT').toUpperCase(), { half: true }),
      this.cfRow('NETWORK', 'CASHU', { half: true }),
      // not in the accent: the accent on this screen belongs to the code, and
      // two orange things is one too many to look at
      this.cfRow('ARRIVES', d ? 'IN SECONDS' : 'WHEN THEY TAKE IT',
        { ink: d ? 'var(--ink)' : 'var(--btc-ink)', half: true }),
      this.cfRow('FEE', lack && lack.fee > 0 ? this.money(lack.fee).main : this.px() ? '$ 0.00' : '\u20bf 0', { half: true }),
    ]).concat(this.peerRateRow());
    /* Short with the fee counted, as the send itself counts it. The balance
     * alone let a 980-sat request through on a phone holding 979, to be
     * refused after SEND. */
    const shortBy = lack && lack.short ? lack.need - lack.have : Math.max(0, sats - (s.balSats || 0));
    const short = shortBy > 0;
    if (short) {
      return {
        title: 'CONFIRMATION', amountLabel: 'SENDING', code: byTap ? s.tapCode : '',
        amount: this.money(sats).main, amountSub: this.money(sats).sub, amountInk: '#FF5C5C', rows: rows,
        warn: this.heldBlocks(shortBy)
          || 'More than your balance \u2014 short by ' + this.money(shortBy).main
             + (lack && lack.fee > 0 ? ' with the fee' : ''),
        cta: 'CLOSE', ctaTone: 'warn', go: () => this.setState({ screen: 'home', stack: [], req: null }),
      };
    }
    return {
      title: 'CONFIRMATION',
      code: byTap ? s.tapCode : '',
      amountLabel: 'SENDING',
      amount: sats ? this.money(sats).main : 'ANY AMOUNT',
      amountSub: sats ? this.money(sats).sub : '',
      rows: rows,
      /* The same pair the Lightning confirmation has: the note where the
       * second button goes, and the X at the top to back out. */
      secondary: { label: (s.note || '').trim() ? 'EDIT NOTE' : 'ADD A NOTE',
        go: () => this.editSendNote(), filled: !!(s.note || '').trim() },
      close: () => {
        /* Backing out of a request that came over a tap: the other phone is
         * told, so its screen does not offer to scan a payment that is not
         * coming. */
        const W = window.FoxyWallet;
        if (req && req.viaTap && W && W.tapQuote) {
          W.tapQuote(JSON.stringify({ gaveUp: 'The payer cancelled.' })).catch(() => {});
        }
        this.setState({ screen: 'home', stack: [], req: null, note: '', noteDraft: '' });
      },
      /* SEND over the link in your hand, PAY over Tor. Not one word for both:
       * over Tor it really is a payment going somewhere, and on a tap the two
       * phones are touching and the thing being done is handing it over. What
       * it must never say is GENERATE ECASH TOKEN, which is what it said while
       * showing the code of the phone it was about to send to. */
      cta: s.reqBusy ? (d ? (d.kind === 'tap' ? 'SENDING\u2026' : 'PAYING\u2026') : 'MAKING\u2026')
        : d ? (d.kind === 'tap' ? 'SEND ' : 'PAY ') + this.money(sats).main
        : 'GENERATE ECASH TOKEN',
      ctaTone: 'go',
      ctaBusy: !!s.reqBusy,
      go: () => this.makeTokenForRequest(),
    };
  }

  /* depConfirm, sendConfirm: one shell, filled in by confirmSpec(). */
  /** @param {RenderContext} c */
  renderConfirmShell(c) {
    const { s, sc } = c;
    const cf = CONFIRM_SCREENS.indexOf(sc) >= 0 ? this.confirmSpec() : {};
    return {
      // ---- CONFIRM shell: title, amount, rows, cta. One block renders them all ----
      isConfirmShell: CONFIRM_SCREENS.indexOf(sc) >= 0,
      cfTitle: cf.title || '',
      cfTitleInk: cf.titleInk || 'var(--ink)',
      cfSubtitle: cf.subtitle || '',
      cfSubShown: cf.subtitle ? '1' : '0',
      /* The four digits the two people compare, above the amount and the same
       * size as it, matching where the receiver's screen shows them. Only for
       * the payment that actually came over the tap — `recipient` being the
       * very invoice that crossed the link is what says so. */
      /* Or any confirmation that names the code itself (`code`): on every
       * confirmation with four digits they are the first section, DELIVERED
       * TO, above the amount. */
      cfCodeUp: !!cf.code || !!(s.tapCode && s.tapInvoice && s.recipient === s.tapInvoice),
      cfCode: cf.code || s.tapCode || '',
      cfAmountLabel: cf.amountLabel || '',
      cfAmount: cf.amount || '',
      cfAmountInk: cf.amountInk || 'var(--acc)',
      cfAmountSub: cf.amountSub || '',
      cfAmountSubShown: !!cf.amountSub,
      cfRows: cf.rows || [],
      cfChipBg: cf.warn ? 'rgba(255,92,92,.14)' : 'rgba(var(--acc-rgb),.12)',
      cfChipInk: cf.warn ? '#FF5C5C' : 'var(--acc-ink)',
      // a check when things are fine, a bar and a dot when they are not
      cfChipIcon: cf.warn ? 'M12 6.6v7.4M12 17.4v.3' : 'M4.5 12.5 10 18 19.5 7',
      // the mint-origin line was removed; the element remains for cf.warn
      cfChip: cf.warn || cf.chip || '',
      // the origin line is a chip too, so it has to open the same gate
      cfChipShown: !!cf.warn || !!cf.chip,
      // the top-right X: the way out of a screen whose second button is a note
      cfCloseShown: !!cf.close,
      cfClose: cf.close || (() => {}),
      cfCloseHidden: !cf.close,
      cfSecondaryShown: !!cf.secondary,
      cfSecondaryLabel: (cf.secondary || {}).label || '',
      cfSecondary: (cf.secondary || {}).go || (() => {}),
      cfSecBg: 'var(--surface)',
      cfSecInk: 'var(--ink)',
      cfSecBorder: (cf.secondary || {}).filled ? '1.5px solid rgba(var(--acc-rgb),.7)' : '1.5px solid rgba(var(--ink-rgb),.16)',
      cfSecSh: 'inset 0 2px 0 rgba(255,255,255,.14),inset 0 -3px 0 rgba(0,0,0,.16),0 9px 18px rgba(0,0,0,.26)',
      cfCtaLabel: cf.cta || '',
      // a quote being asked for, or a payment underway: the button says so
      cfCtaBusy: !!cf.ctaBusy,
      cfCtaBg: cf.ctaTone === 'warn' ? '#F7931A' : 'var(--acc)',
      cfCtaInk: cf.ctaTone === 'warn' ? '#2b1e05' : CTA_INK(s),
      cfCtaGlow: cf.ctaTone === 'warn' ? 'rgba(247,147,26,.3)' : 'rgba(var(--acc-rgb),.32)',
      cfGo: cf.go || (() => {}),
    };
  }

  /* The BLOCKED screens: an action that did not happen, and why. */
  /** @param {RenderContext} c */
  renderBlocked(c) {
    const { sc } = c;
    return {
      // ---- send: a failure state that fires before money moves ----
      // every blocked or reversed action lands here — the chip is part of the template
      isBlocked: !!BLOCKED[sc],
      blockedTitle: (BLOCKED[sc] || {}).title,
      blockedReason: (BLOCKED[sc] || {}).reason,
      blockedChip: (BLOCKED[sc] || {}).chip,
      blockedRetryLabel: (BLOCKED[sc] || {}).retry,
      blockedAmount: (BLOCKED[sc] || {}).showAmount ? this.sendAmountText() : '',
      blockedIsFail: (BLOCKED[sc] || {}).tone !== 'warn',
      blockedIsWarn: (BLOCKED[sc] || {}).tone === 'warn',
      blockedInk: (BLOCKED[sc] || {}).tone === 'warn' ? 'var(--btc-ink)' : '#FF5C5C',
      blockedGlyphBg: (BLOCKED[sc] || {}).tone === 'warn' ? 'rgba(247,147,26,.16)' : 'rgba(255,92,92,.14)',
      blockedRetry: () => this.setState({ screen: (BLOCKED[sc] || {}).back || 'amount' }),
      blockedClose: () => this.setState({ screen: 'home', stack: [], amount: '', asset: '', flow: 'receive', unit: 'USD' }),
    };
  }

  /* history: the transaction list and its filters. */
  /** @param {RenderContext} c */
  renderHistory(c) {
    const { s, sc } = c;
    const hf = s.histFilter || 'all';
    /* One card's entries, when this screen was opened from that card's own
     * (26f-flashcard.js): only then, read from where it was opened and not
     * from a flag left behind, so the ordinary history can never come up
     * filtered. */
    const ofCard = (sc === 'history' && s.histCard && (s.stack || [])[(s.stack || []).length - 1] === 'flashcard') ? String(s.histCard) : '';
    /* A running balance on every settled row: what the wallet held after that
     * payment, walked back from the balance now. The list is newest first, so
     * a receive is taken off on the way down and a send (with its fee) put
     * back. Rows that moved nothing yet — pending, failed, at risk, a bill
     * still being collected, another unit's ecash — carry the balance through
     * unchanged. So that a person can see the numbers add up, or where they
     * stop doing so ("$121.69 is wrong"). */
    const A = this.histAudit();
    const balOf = A.balOf, balNow = A.balNow, run = A.run;
    const dueChange = A.dueChange, dueCount = A.dueCount;
    /* The audit. Walked back through every entry, the balance before the
     * first one should be nothing: a wallet starts empty. Whatever is left is
     * money no payment here accounts for — a restore from the words, a swap
     * whose record was lost — and it is said in red so the person can go and
     * find out, rather than trusting a number. Only when
     * the list is the whole ledger; five hundred of more cannot be checked
     * to the start. Sats held back for a lost swap are outside the balance and are
     * named too. */
    const W1 = window.FoxyWallet;
    const held = Math.round(Number(W1 && W1.heldSats && W1.heldSats()) || 0);
    const whole = !!s.historyComplete && !s.fresh && (s.history || []).length > 0;
    const off = A.off;
    const money = (n) => this.stageMoney(Math.abs(n));
    let auditTitle = '', auditBody = '';
    if (whole && off !== 0) {
      auditTitle = 'DOES NOT ADD UP';
      auditBody = 'Your balance is ' + money(balNow) + '. The payments below account for '
        + money(balNow - off) + '. ' + money(off) + (off > 0 ? ' more is here than' : ' less is here than')
        + ' they explain. A restore from your words, or a swap whose record was lost, can do this.';
    } else if (whole) {
      auditTitle = 'ADDS UP';
      auditBody = 'Every sat of your ' + money(balNow) + ' is accounted for by the payments below.';
    } else if (!s.fresh && (s.history || []).length) {
      auditTitle = 'LAST 500 PAYMENTS';
      auditBody = 'Only the latest five hundred are kept, so the balance cannot be checked back to the start.';
    }
    if (held > 0) {
      auditBody += (auditBody ? ' ' : '') + money(held)
        + ' is held back for a swap the mint has not answered; it is not in the balance until it does.';
    }
    const fees = this.topUpFeeSats ? this.topUpFeeSats() : 0;
    if (fees > 0 && whole) {
      auditBody += (auditBody ? ' ' : '') + money(fees)
        + ' went to the mint in fees for making small change, or for a payment that did not go through.';
    }
    const back = this.recoveringSats ? this.recoveringSats() : 0;
    if (back > 0) {
      auditBody += (auditBody ? ' ' : '') + money(back)
        + ' is being recovered from the mint: it took that piece for a swap after Foxy was put away, and the new pieces are collected the next time Foxy is online.';
    }
    /* Change that never arrived, and what to do about it.
     *
     * The receiver made it and holds it as a code on that payment's entry; it
     * is locked to this phone, so only this phone can take it. The card says
     * so and opens the scanner, instead of leaving a red number and no way
     * on. */
    /* And the other side of it: change this phone made for a payer and could
     * not hand over. It is a code on that payment's entry, and the card
     * takes the person straight to it. */
    const showChange = !dueChange && A.toShowCount > 0;
    if (showChange) {
      if (auditTitle === 'ADDS UP') auditTitle = 'CHANGE TO HAND OVER';
      auditBody = money(A.toShowSats) + ' of change for ' + (A.toShowCount === 1 ? 'a payer' : A.toShowCount + ' payers')
        + ' was made and has not reached them. Show them its code to scan.'
        + (auditTitle === 'CHANGE TO HAND OVER' ? ' Everything else adds up.' : ' ' + auditBody);
    }
    const auditAction = dueChange > 0 || showChange;
    if (dueChange > 0) {
      if (auditTitle === 'ADDS UP') auditTitle = 'CHANGE NOT COLLECTED';
      auditBody = money(dueChange) + ' of change from ' + (dueCount === 1 ? 'a payment' : dueCount + ' payments')
        + ' has not reached this phone. Ask the receiver to open that payment in their history and show its code, then scan it.'
        + (auditTitle === 'CHANGE NOT COLLECTED' ? ' Everything else adds up.' : ' ' + auditBody);
    }
    /* One card's list is the card's own account, read from this phone's
     * entries, so each is turned round: money this phone was paid by the card
     * left the card, and money this phone put on it came in. Named for what it
     * was to the card, and counted at what reached or left the card (a load's
     * fee was this phone's). It read the other way: a $5 payment off the card
     * as a $5 credit, and $50 put on it as a withdrawal. */
    const dirOf = (t) => (ofCard ? (t.dir === 'in' ? 'out' : 'in') : t.dir);
    const unfinished = (t) => !!ofCard && t.memo === 'card, not completed';
    const cardName = (t) => (t.dir !== 'in' ? 'Added' : t.memo === 'from card' ? 'Withdrawn' : unfinished(t) ? 'Not completed' : 'Paid');
    const cardRail = (t) => {
      if (unfinished(t)) return t.changeState === 'given back' ? 'Put back on the card' : 'To go back on the card';
      if (t.dir === 'in' && t.changeState === 'not handed' && t.changeSats > 0) return 'Change to go back on the card';
      return '';
    };
    const histGroups = (s.fresh ? [] : (s.history || [])).map(g => ({
      label: g.label,
      items: g.items.filter(t => (hf === 'all' || dirOf(t) === hf) && (!ofCard || t.card === ofCard)).map(t => ({
        // HIDE only masks balances on the home screen — history stays readable
        /* The note, where the person wrote one: "Lunch" says more than
         * "ecash" or the first characters of an invoice. One line, as wide
         * as the card allows, cut with an ellipsis; the card is no taller for
         * it. */
        name: ofCard ? cardName(t) : ((t.note && String(t.note).trim()) || t.name),
        initial: (ofCard ? cardName(t) : t.name).slice(0, 1).toUpperCase(),
        /* The card's outline and its icon say how the payment stands: green
         * done (sent, received or redeemed), amber pending, red failed. The
         * amount says which way it went: green in, red out. */
        /* A payment taken on trust while both phones were offline is pending
         * like any other, and it is not like any other: the payer keeps a copy
         * and can spend it back until this phone can swap. So it says what it
         * is, in red rather than amber, instead of sitting in a list reading
         * "Pending" beside a broadcast nobody can undo.
         *
         * It stops the moment the claim lands, because the claim is what ends
         * the risk. Once it has, the row is an ordinary settled receive. */
        atRisk: !!t.atRisk,
        /* The payments the card's notice is about, picked out: red, with a
         * red edge that turns, so it is plain which row to open. */
        cardBg: A.flagged.has(t)
          ? 'linear-gradient(var(--surface),var(--surface)) padding-box,conic-gradient(from var(--fxa),#FF5C5C,rgba(255,92,92,.12) 40%,#FF5C5C) border-box'
          : 'var(--surface)',
        cardEdge: A.flagged.has(t) ? '2.5px' : '1.5px',
        cardSpin: A.flagged.has(t) ? 'foxyEdge 1.6s linear infinite' : 'none',
        metaRail: A.flagged.has(t) ? A.flagged.get(t) : (ofCard && cardRail(t)) ? cardRail(t) : t.highRisk ? 'HIGH RISK \u00b7 refused, not returned'
          : t.failed ? 'Failed' : t.atRisk ? 'AT RISK \u00b7 not settled'
          /* A payment that is "pending" has left: what is waiting is the other
           * side taking it. The word alone read as if nothing had happened
           * yet. */
          : t.pending ? (t.dir === 'in' ? 'Pending' : 'Sent \u00b7 not yet claimed') : '',
        metaTime: t.time,
        metaColor: (t.failed || t.atRisk || A.flagged.has(t)) ? 'var(--bad)'
          : t.pending ? 'var(--btc-ink)' : 'rgba(var(--ink-rgb),.5)',
        tileBg: (t.failed || t.atRisk || A.flagged.has(t)) ? 'var(--bad)' : t.pending ? 'var(--btc-ink)' : 'var(--ok)',
        stroke: A.flagged.has(t) ? 'transparent' : (t.failed || t.atRisk) ? 'rgba(var(--bad-rgb),.7)'
          : t.pending ? 'var(--btc-ink)' : 'rgba(var(--ok-rgb),.7)',
        amtColor: A.flagged.has(t) ? 'var(--bad)' : unfinished(t) ? 'rgba(var(--ink-rgb),.55)' : dirOf(t) === 'in' ? 'var(--ok-ink)' : 'var(--bad)',
        /* Dollars, and the dollars of the day it settled: `fiat` is written on
         * the entry then and never worked out again, so yesterday's coffee
         * does not change price with bitcoin. */
        amtText: ofCard
          ? (unfinished(t) ? '' : dirOf(t) === 'in' ? '+' : '−') + this.money(t.sats, this.txFiat(t, t.sats)).main
          : (t.dir === 'in' ? '+' : '−') + (t.unit ? this.unitMoney(t.amount, t.unit) : t.usd != null ? '$ ' + t.usd.toFixed(2) : this.money(this.txTotalOut(t), this.txFiat(t, this.txTotalOut(t))).main),
        amtSub: ofCard ? this.money(t.sats, this.txFiat(t, t.sats)).sub
          : t.unit ? this.unitLabel(t.unit) + ' ecash' : t.usd != null ? 'Cash' : this.money(this.txTotalOut(t), this.txFiat(t, this.txTotalOut(t))).sub,
        // dollars at today's price, and the sats that actually add up
        // the wallet's running balance, which is not a card's: left off a card's own list
        balText: ofCard ? '' : 'BAL ' + (this.px()
          ? this.stageMoney(Math.max(0, balOf.get(t) || 0)) + ' \u00b7 \u20bf ' + this.group(Math.max(0, balOf.get(t) || 0))
          : '\u20bf ' + this.group(Math.max(0, balOf.get(t) || 0))),
        // the collecting screen, not a transaction detail, while a bill is open
        open: () => (t.split ? this.openPendingSplit() : this.openTx(t)),
      /* The card is three lines, each shared with a figure on the right: the
       * title beside the amount, so a note runs as far as the amount and no
       * further; then how the payment stands, where it has something to
       * say; then the time. A settled payment has nothing to say, so its
       * time moves up under the title. */
      })).map(r => Object.assign(r, {
        line2: r.metaRail || r.metaTime,
        line3: r.metaRail ? r.metaTime : '',
        line2Color: r.metaRail ? r.metaColor : 'rgba(var(--ink-rgb),.45)',
        line2Weight: r.metaRail ? '600' : '500',
      })),
    })).filter(g => g.items.length);
    return {
      historyEmptySub: ofCard ? 'Nothing has been done with this card on this phone yet.'
        : s.fresh ? 'Your transactions will show up here.' : 'No transactions match this filter.',
      isHistory: sc === 'history',
      histTitle: ofCard ? 'CARD HISTORY' : 'HISTORY',
      // clearing history is the whole wallet's, not one card's
      histClearVis: ofCard ? 'hidden' : 'visible',
      historyMint: (window.FoxyWallet && window.FoxyWallet.mintHost
        && window.FoxyWallet.mintHost()) || 'MINT',
      // switching from here comes back here, showing that mint's activity
      goSwitchFromHistory: () => this.goSwitchMint({ mintReturn: 'history' }),
      histScrollRef: this._refHist || (this._refHist = (el) => this.histRef(el)),
      goHistory: () => this.go('history'),
      fAllBg: hf === 'all' ? 'var(--acc)' : 'transparent',
      fAllFg: hf === 'all' ? CTA_INK(s) : 'rgba(var(--ink-rgb),.5)',
      fInBg: hf === 'in' ? 'var(--acc)' : 'transparent',
      fInFg: hf === 'in' ? CTA_INK(s) : 'rgba(var(--ink-rgb),.5)',
      fOutBg: hf === 'out' ? 'var(--acc)' : 'transparent',
      fOutFg: hf === 'out' ? CTA_INK(s) : 'rgba(var(--ink-rgb),.5)',
      filterAll: () => this.setState({ histFilter: 'all' }),
      filterIn: () => this.setState({ histFilter: 'in' }),
      filterOut: () => this.setState({ histFilter: 'out' }),
      historyGroups: histGroups,
      historyEmpty: histGroups.length === 0,
      histAuditShown: !!auditTitle && hf === 'all' && !ofCard,
      histAuditTitle: auditTitle,
      histAuditBody: auditBody,
      histAuditAction: auditAction && !!auditTitle && hf === 'all' && !ofCard,
      histAuditCta: showChange ? 'SHOW QR CODE' : 'SCAN CHANGE',
      histAuditGo: () => (showChange && A.toShow ? this.openTx(A.toShow)
        : this.setState(p => ({ screen: 'sendScan', stack: p.stack.concat([p.screen]), flow: 'send' }))),
      histAuditInk: (auditTitle === 'DOES NOT ADD UP' || auditAction) ? 'var(--bad)' : auditTitle === 'ADDS UP' ? 'var(--ok-ink)' : 'var(--btc-ink)',
      histAuditEdge: (auditTitle === 'DOES NOT ADD UP' || auditAction) ? 'rgba(var(--bad-rgb),.5)' : 'rgba(var(--ink-rgb),.12)',
    };
  }

  /* txDetail: one transaction — amounts, fee, mint, payment id, audit record. */
  /** @param {RenderContext} c */
  renderTxDetail(c) {
    const { s, sc, tx } = c;
    // the proofs this payment consumed and produced, if the record is still kept
    const audit = (window.FoxyWallet && window.FoxyWallet.auditTrail && tx.hash)
      ? window.FoxyWallet.auditTrail(tx.hash) : [];
    const txText = String((tx && (tx.token || (tx.dir === 'in' ? tx.changeToken : tx.kept))) || '');
    return {
      isTxDetail: sc === 'txDetail',
      /* SENT is what the recipient got; TOTAL is what left the wallet. The
       * difference is the fee, and the screen now shows all three rather than
       * two numbers that do not visibly relate. */
      txSentLabel: tx.dir === 'in' ? 'RECEIVED' : 'SENT',
      txSent: (tx.dir === 'in' ? '+' : '\u2212') + (tx.unit ? this.unitMoney(tx.amount, tx.unit) : this.money(tx.sats, this.txFiat(tx, tx.sats)).main),
      txTotal: (tx.dir === 'in' ? '+' : '\u2212') + (tx.unit ? this.unitMoney(tx.amount, tx.unit) : this.money(this.txTotalOut(tx), this.txFiat(tx, this.txTotalOut(tx))).main),
      txTotalAlt: tx.unit ? this.unitLabel(tx.unit) + ' ecash' : this.money(this.txTotalOut(tx), this.txFiat(tx, this.txTotalOut(tx))).sub,
      /* Which mint carried this. The screen said LIGHTNING and never said
       * whose — and the mint is the party that held the money. */
      txMint: (window.FoxyWallet && window.FoxyWallet.mintHost
        && window.FoxyWallet.mintHost()) || 'unknown',
      txPaymentId: tx.hash || '',
      txHasPaymentId: !!tx.hash,
      /* The one identifier on this screen an explorer can find.
       *
       * PAYMENT ID is the mint's melt quote id with `onchain-` in front — the
       * one pasted into mempool.space finds nothing, which is how this row
       * came to exist. The transaction id comes from the NUT-30
       * outpoint and is a real one. It appears only once the mint has broadcast,
       * and only on an on-chain payment; everything else has no such field and
       * the row stays away rather than showing an empty label.
       *
       * Tap to copy, because sixty-four characters is not something anybody
       * reads off a screen into another one. */
      txTxid: tx.txid || '',
      txHasTxid: !!tx.txid,
      txCopyTxid: () => {
        if (!tx.txid) return;
        this.toast(this.copyText(tx.txid) ? 'TXID Copied' : 'Could not copy');
      },
      /* The proof that a Lightning payment was made: its preimage, which only
       * somebody paid that invoice can know. Shown where the mint gave one;
       * a payment between two wallets at one mint has none. Tap to copy, as
       * the transaction id is. */
      txPreimage: tx.preimage || '',
      txHasPreimage: !!tx.preimage,
      txCopyPreimage: () => {
        if (!tx.preimage) return;
        this.toast(this.copyText(tx.preimage) ? 'Proof of payment copied' : 'Could not copy');
      },
      /* And on a Lightning receive, the payment hash of the invoice: what a
       * payer's proof of payment is held against. */
      txPayHash: tx.payHash || '',
      txHasPayHash: !!tx.payHash,
      txCopyPayHash: () => {
        if (!tx.payHash) return;
        this.toast(this.copyText(tx.payHash) ? 'Payment hash copied' : 'Could not copy');
      },
      /* What this payment consumed and produced: a count and a copy button.
       * The proofs themselves are hex, they are long, and the outputs of a
       * recent payment are live change with no business on screen. */
      txHasAudit: !!(audit && audit.length),
      /* A record older than the last hundred is a receipt: the counts, and the
       * public values of what left, with the pieces themselves let go. */
      txAuditLine: (audit && audit.length)
        ? (audit[0].slim ? Number(audit[0].ins) || 0
           : Math.max((audit[0].inputs || []).length, (audit[0].ys || []).length)) + ' proofs in  \u00b7  '
          + (audit[0].slim ? Number(audit[0].outs) || 0 : (audit[0].outputs || []).length) + ' proofs out'
        : '',
      /* A payment locked to the phone that asked for it, once the mint says
       * its pieces are spent: they could only be spent by that phone's key,
       * and the signature they were spent with is kept here. That is what
       * shows somebody else who took the payment. The pieces are spent, so
       * copying them hands over nothing. DELETE is the person's to press:
       * a receipt is also a record of who was paid. */
      txHasReceipt: !!(audit && audit[0] && audit[0].spent && (audit[0].inputs || []).length),
      txReceiptLine: (audit && audit[0] && audit[0].spent)
        ? 'Taken by the key it was locked to.' : '',
      txReceiptCta: s.txReceiptCopied ? 'COPIED' : 'COPY RECEIPT',
      txCopyReceipt: () => {
        const a = audit && audit[0];
        if (!a || !a.spent) return;
        const text = JSON.stringify({
          what: 'a Cashu payment locked to one key (NUT-11), and the signature its pieces were spent with (NUT-07)',
          mint: a.mint, paid: a.at, sats: a.sats, lockedTo: a.lockedTo, spentSeenAt: a.spent.at,
          proofs: (a.inputs || []).map((p, i) => ({ amount: p.amount, id: p.id, secret: p.secret, C: p.C,
                                                    witness: a.spent.witness[i] })),
        });
        if (!this.copyText(text)) { this.toast('Could not copy', true); return; }
        this.setState({ txReceiptCopied: true });
        setTimeout(() => this.setState({ txReceiptCopied: false }), 1600);
      },
      txDeleteReceipt: () => {
        const W = window.FoxyWallet;
        if (!W || !W.forgetReceipt || !tx.hash) return;
        if (W.forgetReceipt(tx.hash)) { this.toast('Receipt deleted'); this.setState({ txReceiptAt: 0 }); }
      },
      txAuditCta: s.txAuditCopied ? 'COPIED' : 'COPY RECORD',
      txCopyAudit: () => {
        /* A record to share, not money. A proof's secret with its signature
         * spends it, and the outputs here can be live change. The copy keeps
         * amounts, keysets and a secret's first characters to match on. */
        const brief = p => ({ amount: p && p.amount, id: p && p.id,
          secret: String((p && p.secret) || '').slice(0, 8) + '\u2026' });
        const shareable = (audit || []).map(a => Object.assign({}, a, {
          inputs: (a.inputs || []).map(brief),
          outputs: (a.outputs || []).map(brief),
        }));
        const ok = this.copySecret(JSON.stringify(shareable, null, 2));
        this.setState({ txAuditCopied: ok });
        clearTimeout(this._auditT);
        this._auditT = setTimeout(() => this.setState({ txAuditCopied: false }), 2000);
      },
      /* A payment taken on trust says so where the word PENDING would be, and
       * then says what that means. "Pending" on its own is what a broadcast
       * says, and a broadcast cannot be taken away from anybody. */
      // FAILED before PENDING: a refused payment taken back is not settled, and is not waiting either
      txStatus: tx.highRisk ? 'HIGH RISK' : tx.atRisk ? 'AT RISK' : tx.failed ? 'FAILED' : tx.pending ? 'PENDING' : 'COMPLETE',
      txStatusInk: (tx.atRisk || tx.highRisk) ? 'var(--bad)' : 'var(--ink)',
      /* An over-payment and its change, which are one transaction.
       *
       * Offline with no exact pieces the payer covers the amount and the
       * receiver hands the difference back, so the list shows the net — and
       * this is where the arithmetic lives: what moved, what came back, what it
       * came to. Kept on the entry, so somebody reporting a payment that looked
       * wrong can send these three numbers rather than describe them. Nothing shows on an ordinary payment. */
      txHasChange: Number(tx.changeSats) > 0,
      txGross: (tx.dir === 'in' ? 'Received ' : 'Paid ')
        + this.money(Number(tx.grossSats) || 0, this.txFiat(tx, Number(tx.grossSats) || 0)).main,
      txChange: this.money(Number(tx.changeSats) || 0, this.txFiat(tx, Number(tx.changeSats) || 0)).main
        + (tx.changeState === 'never came' || tx.changeState === 'never sent' ? ' expected'
           : tx.changeState === 'not handed' ? ' owed to them'
           : tx.changeState === 'owed' || tx.changeState === 'making' ? ' due'
           : tx.changeState === 'collected' ? ' collected later'
           : tx.dir === 'in' ? ' given back' : ' back'),
      txChangeNet: (tx.dir === 'in' ? '+' : '\u2212') + this.money(tx.sats, this.txFiat(tx, tx.sats)).main,
      txChangeState: tx.changeState === 'never came' ? 'The change never arrived.'
        : tx.changeState === 'never sent' ? 'The change could not be sent, so it was all kept.'
        : (tx.changeState === 'not handed' && /^card/.test(String(tx.memo || '')))
          ? 'Their change was made and is waiting for their card. It is locked to that card: '
            + 'MENU \u203a FLASHCARD, and tap the card, to put it back.'
        : tx.changeState === 'not handed' ? 'Their change was made and could not be handed over. '
          + 'Show them the token below: it is locked to their phone, so only they can take it.'
        : tx.changeState === 'owed' ? 'Waiting for the change.'
        : tx.changeState === 'collected' ? 'The change was collected later, and is a payment of its own in this list.'
        : tx.changeState === 'making' ? 'Making the change.'
        : '',
      txChangeStateInk: (tx.changeState === 'never came' || tx.changeState === 'never sent'
                         || tx.changeState === 'not handed')
        ? 'var(--bad)' : 'rgba(var(--ink-rgb),.55)',
      txAtRisk: !!tx.atRisk || !!tx.highRisk,
      txClaimCta: s.txClaiming ? (tx.highRisk ? 'CHECKING\u2026' : 'CLAIMING\u2026') : tx.highRisk ? 'MAKE IT SAFE NOW' : 'CLAIM NOW',
      txClaimNow: () => (tx.highRisk ? this.settleAtRiskNow() : this.claimAtRiskNow()),
      txAtRiskLine: tx.atRisk
        ? 'You accepted this while you and the payer were both offline, so nothing here could '
          + 'settle it. It is counted in your balance, and until this phone is online the payer '
          + 'can still spend their copy and take it back. Connect to settle it.'
        : tx.highRisk
        ? 'They refused this payment and did not send it back locked to you. They have seen this '
          + 'ecash and can still redeem it. It is in your balance and you can spend it, and Foxy swaps '
          + 'it for ecash nobody has seen as soon as it has a connection.'
        : '',
      /* RECLAIM is a swap that takes a token's proofs back, and offering it is
       * only safe while this phone can find out whether anybody has taken them.
       * Offline it cannot: the receiver may be holding that very payment on
       * trust, unswapped, because they have no route either — and taking it back
       * is the double spend they agreed to risk, handed to them by a button.
       * The token is still on the screen to show
       * or copy; what goes is the offer to undo it. */
      // the token is still there to show or copy: handing it to the same person
      // again is not a double spend
      /* And it stays after it is claimed, and the change a
       * receiver made stays on the payment it was for: somebody who says the
       * money never reached them can be shown the very token, and their own
       * wallet tells them whether it was taken. What is shown is `txText`:
       * the unclaimed token, or the kept one, or — on a payment received —
       * the change made for the payer. */
      txHasToken: !!txText,
      txTokenTitle: tx.dir === 'in' ? 'PAYER CHANGE TOKENS' : (tx.token ? 'PAYMENT TOKEN' : 'PAYMENT TOKEN \u00b7 CLAIMED'),
      txTokenNote: tx.dir === 'in'
        ? (tx.token ? 'Not handed over yet. Locked to the payer\u2019s phone: only they can take it.'
                    : 'Locked to the payer\u2019s phone. If they say it never came, show them this: their wallet will take it, or say it was already claimed.')
        : (tx.token ? '' : 'Already claimed. Shown to whoever was paid, their wallet will say so.'),
      txTokenNoteShown: !(tx.dir !== 'in' && tx.token),
      /* Taking it back is. RECLAIM swaps the proofs away from whoever has them,
       * and on a payment that crossed a tap that is somebody holding it on
       * trust with no route to settle it — the mint will honour the swap and
       * they have no way to see it coming. Offline it is worse again: this
       * phone cannot even find out whether anybody took it. */
      txCanReclaim: !!tx.token && tx.dir !== 'in' && !tx.handedByTap && !this.offlineNow(),
      txReclaimCta: s.txReclaiming ? 'RECLAIMING\u2026' : 'RECLAIM THESE SATS',
      txReclaimInk: s.txReclaiming ? 'rgba(var(--ink-rgb),.4)' : 'var(--ink)',
      txReclaim: () => this.reclaimFromTx(tx.token),
      /* The same token as a code, for somebody standing there with a camera.
       * It is the token screen a send ends on, opened on this entry's token,
       * with the way back leading here. */
      txShowQr: () => {
        if (!txText) return;
        console.log('[foxy] history: showing an entry\u2019s token as a code');
        /* A token still unclaimed goes to the token screen, which watches for
         * it being taken. One already claimed, or change made for a payer, is
         * only shown: that screen would see "claimed" and close under the
         * person looking at it. */
        if (tx.token && tx.dir !== 'in') { this.showTokenCode(tx.token, tx.hash || ''); return; }
        if (this.stageScreen) {
          this.stageScreen('keptToken', {
            title: tx.dir === 'in' ? 'Payer<br>change' : 'Payment<br>token',
            qr: txText,
            body: tx.dir === 'in'
              ? 'The payer scans this to take their change. If it was already taken, their wallet will say so.'
              : 'Already claimed. Scanned by whoever was paid, their wallet will say so.',
            button: 'DONE', go: () => {},
          });
        }
      },
      txTokenCta: 'SHARE TOKEN',
      txCopyToken: () => {
        const W = window.FoxyWallet;
        if (!txText) return;
        if (!W || !W.share || !W.share(txText)) {
          const ok = this.copySecret(txText);
          this.toast(ok ? 'Copied.' : 'Could not share.', !ok);
        }
      },
      // an ecash transaction never touched lightning
      /* An ecash transfer is not Lightning.
       *
       * A token receive showed NETWORK: Lightning while its payment id read
       * token-1789157866360 — no Lightning was involved. The send side got
       * this right because its memo says 'ecash'; the receive side had
       * nothing to go on but the quote id, which is exactly the signal.
       *
       * An on-chain payment read Lightning the same way, with a bc1 address
       * under TO and onchain-01a0c093… under PAYMENT ID.
       * Nothing sets rail on those entries, so they fell through to the
       * default, and the id is the signal here too (16a-onchain.js). */
      /* And a request another Foxy paid, by tap or over Tor: its id starts
       * req-, and it showed as a Lightning payment on the receiver between
       * two phones at one mint. Change that
       * came back and ecash taken back are ecash the same way. */
      txNetwork: (tx.token || tx.memo === 'ecash'
        || /^(token-|req-|tap-change-|reclaim-)/.test(String(tx.hash || ''))) ? 'CASHU'
        : String(tx.hash || '').indexOf('onchain-') === 0 ? 'ON-CHAIN'
        : (tx.rail || 'LIGHTNING'),
      txPartyLabel: tx.dir === 'in' ? 'FROM' : 'TO',
      txParty: tx.party || tx.name || '—',
      txHasNote: !!tx.note,
      txNote: tx.note || '',
      // a note can be added to any payment, and changed
      txNoteCta: tx.note ? 'EDIT NOTE' : 'ADD A NOTE',
      txNoteEdit: () => this.editTxNote(),
      txFee: tx.unit ? this.unitMoney(tx.feeAmount || 0, tx.unit) : this.money(tx.fee == null ? 0 : tx.fee, this.txFiat(tx, tx.fee == null ? 0 : tx.fee)).main,
      txFeeAlt: tx.unit ? this.unitLabel(tx.unit) : this.money(tx.fee == null ? 0 : tx.fee, this.txFiat(tx, tx.fee == null ? 0 : tx.fee)).sub,
      txTime: tx.stamp || tx.time || '—',
    };
  }

  /* contacts: saved handles, and the search over them. */
  /** @param {RenderContext} c */
  renderContacts(c) {
    const { s, sc } = c;
    return {
      isContacts: sc === 'contacts',
      contactAll: this.contactRows(),
      contactLetter: (this.contactRows()[0] || {}).ini || '',
      contactRecents: this.contactRows().slice(0, 3),
      /* A contact is paid at a Lightning address, which offline can be neither
       * resolved nor paid. The list itself is local and could be shown, but a
       * screen of people none of whom can be paid is a worse answer than saying
       * so at the door. */
      goContacts: () => {
        if (this.offlineNow()) { this.offlineNo('Paying a contact'); return; }
        this.go('contacts');
      },
      openContactSearch: () => this.setState({ ctSearch: true, ctQuery: '' }),
      closeContactSearch: () => this.setState({ ctSearch: false, ctQuery: '' }),
      ctSearchOpen: !!s.ctSearch,
      ctQuery: s.ctQuery || '',
      /* Deliberate, not residue. Most people this app is for hold a Wallet
       * of Satoshi account, and a lightning address is easy to mistype in a
       * way that sends money to a stranger. This appends the domain to a
       * recipient being typed — it never claims to be the user's own
       * address, which is the thing the audit found and which stays gone. */
      ctQueryInput: (e) => this.setState({ ctQuery: e.target.value }),
      ctFocusRef: this._refCt || (this._refCt = (el) => this.autoFocus('ct', el)),
      ctEmpty: (s.ctQuery || '').trim().toLowerCase().length === 0,
      contactsEmpty: s.walletLive ? this.contactRows().length === 0 : !!s.fresh,
      contactsAny: s.walletLive ? this.contactRows().length > 0 : !s.fresh,
      ctResults: (function (qq) {
        if (!qq || s.fresh) return [];
        return (s.contacts || []).filter(c => c.name.toLowerCase().indexOf(qq) >= 0 || c.handle.toLowerCase().indexOf(qq) >= 0)
          .map(c => ({ name: c.name, handle: c.handle, initial: c.name.charAt(0), tint: c.tint }));
      })((s.ctQuery || '').trim().toLowerCase()),
      ctHasResults: (function (qq) {
        if (!qq || s.fresh) return false;
        return (s.contacts || []).some(c => c.name.toLowerCase().indexOf(qq) >= 0 || c.handle.toLowerCase().indexOf(qq) >= 0);
      })((s.ctQuery || '').trim().toLowerCase()),
      ctCount: (function (qq) {
        if (!qq) return '';
        const n = (s.contacts || []).filter(c => c.name.toLowerCase().indexOf(qq) >= 0 || c.handle.toLowerCase().indexOf(qq) >= 0).length;
        return n === 1 ? '1 MATCH' : n + ' MATCHES';
      })((s.ctQuery || '').trim().toLowerCase()),
      // a full handle nobody has saved still resolves — payable, flagged as not a contact
      ctStrangerShown: (function (qq) {
        if (qq.indexOf('@') < 0 || qq.length < 5) return false;
        return !(s.contacts || []).some(c => c.handle.toLowerCase() === qq);
      })((s.ctQuery || '').trim().toLowerCase()),
      ctStrangerHandle: (s.ctQuery || '').trim().toLowerCase(),
      ctStrangerInitial: (s.ctQuery || '').trim().toLowerCase().charAt(0).toUpperCase(),
      ctNoneShown: (function (qq) {
        if (!qq) return false;
        const hit = !s.fresh && (s.contacts || []).some(c => c.name.toLowerCase().indexOf(qq) >= 0 || c.handle.toLowerCase().indexOf(qq) >= 0);
        return !hit && qq.indexOf('@') < 0;
      })((s.ctQuery || '').trim().toLowerCase()),
      payContact: () => this.setState(p => {
        const qq = (p.ctQuery || '').trim().toLowerCase();
        const hit = (s.contacts || []).filter(c => c.name.toLowerCase().indexOf(qq) >= 0 || c.handle.toLowerCase().indexOf(qq) >= 0)[0];
        return {
          screen: 'amount', stack: p.stack.concat([p.screen]), flow: 'send',
          recipient: qq ? ((hit && hit.handle) || qq) : '',
          recipientKind: 'email', ctSearch: false,
          amount: '', unit: 'USD', asset: '',
        };
      }),
    };
  }
  /* ---- moving money between the mints you already use ----------------------
   *
   * Five steps, the way a send goes: which mint it leaves, which mint it lands
   * at, how much, a confirmation with the fee, and the screen a payment ends on.
   *
   * The wallet already knows how to do this — it is what a sweep does when a
   * token comes from a mint you do not use: connect to the destination, quote
   * an invoice there, pay it from the source (14-moving-between-mints.js). The
   * fee is that invoice's routing reserve, which is why it is quoted before the
   * confirmation rather than guessed.
   */
  goTransfer() {
    if (!window.FoxyWallet || !window.FoxyWallet.transferQuote) return;
    /* Quoting connects to the destination, which makes this a mint switch like
     * any other, and the audit's finding 17 asks every one of them to wait for
     * money that is already moving. */
    if (this.refuseSwitchWhileBusy()) return;
    // the mint to come back to if the transfer is dropped (quoting connects
    // to the destination, and cancelling used to leave the wallet there)
    this._trWas = window.FoxyWallet.mintUrl || '';
    this.setState(p => ({
      screen: 'switchMint', stack: p.stack.concat([p.screen]),
      trStep: 'from', trFrom: '', trTo: '', trSats: 0, trPlan: null, trFee: null, trErr: '', fcPick: false,
    }));
  }

  /* A mint tapped on the list while a transfer is being set up. */
  trPick(url) {
    const mint = String(url || '').replace(/\/+$/, '');
    /* Only while one is. The two steps were told apart by 'from' against
     * everything else, so called with no transfer in progress this fell into
     * the second step and began one nobody had asked for. The list only
     * routes a tap here while trStep is set, so this never fired — but it
     * read the flow's state from outside the flow, which is the same shape as
     * the bug above. */
    if (!this.state.trStep) return;
    if (this.state.trStep === 'from') {
      this.setState({ trFrom: mint, trStep: 'to' });
      return;
    }
    this.setState(p => ({
      trTo: mint, trStep: '',
      screen: 'amount', stack: p.stack.concat([p.screen]),
      flow: 'transfer', asset: 'BITCOIN', unit: 'SATS', amount: '',
      note: '', noteDraft: '', recipient: '', recipientKind: '',
    }));
  }

  /* What is at the mint the money leaves, for the keypad's line and its cap. */
  trFromSats() {
    return this.mintPile(this.state.trFrom).sats || 0;
  }

  trNext() {
    const sats = this.amountInSats();
    const have = this.trFromSats();
    if (!(sats > 0)) { this.toast('Enter an amount first', true); return; }
    if (sats > have) {
      this.toast('That is more than the ' + this.mintNameOf(this.state.trFrom) + ' balance.', true);
      return;
    }
    /* The amount typed is what lands at the other mint; the fee comes out of
     * the same pile on top of it. The exact fee is the
     * quote's to say, so the room for it is checked there. */
    this.setState(p => ({
      screen: 'trConfirm', stack: p.stack.concat([p.screen]),
      trSats: sats, trPlan: null, trFee: null, trErr: '', trFits: 0,
    }));
    this.quoteTransfer();
  }

  /* The fee, quoted before anything moves: an invoice at the destination and a
   * melt quote at the source. Nothing is spent by asking. */
  quoteTransfer() {
    const W = window.FoxyWallet;
    const { trFrom, trTo, trSats } = this.state;
    if (!W || !trFrom || !trTo || !(trSats > 0)) return;
    /* Asked again here, not only when the flow opened: between the two the
     * person picks two mints and types an amount, and a payment or a claim can
     * start in that window (finding 17). A quote is cheap to ask again, so
     * this waits on the confirmation screen rather than dropping the flow —
     * the watcher's own claims hold the lock for a moment at a time. */
    if (this.moneyBusy()) {
      this.setState({ trQuoting: false,
        trErr: 'Something else is moving money right now. Try again in a moment.' });
      return;
    }
    this.setState({ trQuoting: true, trErr: '', trFits: 0 });
    Promise.resolve()
      .then(() => (W.mintUrl === trTo ? null : W.connect(trTo)))
      .then(() => W.transferQuote(trFrom, trSats))
      .then(plan => {
        this.setState({ trQuoting: false, trPlan: plan, trFee: plan.feeSats });
      })
      .catch(e => {
        // what would have fitted, when the fee is the only thing in the way
        this.setState({ trQuoting: false, trErr: W.reason(e),
                        trFits: (e && e.foxyFits) || 0 });
      });
  }

  /* Move what the fee leaves room for, instead of the amount that did not fit.
   *
   * Straight back into the quote with the smaller figure: the screen is
   * already the confirmation, and there is nothing to go back to the keypad
   * for. */
  trMoveLess(sats) {
    if (!(sats > 0)) return;
    this.setState({ trSats: sats, trPlan: null, trFee: null, trErr: '', trFits: 0 });
    this.quoteTransfer();
  }

  /* Run it: the source pays the destination's invoice, and the destination
   * issues the ecash. An interrupted one is finished on the next launch
   * (FoxyWallet.finishMove). */
  runTransfer() {
    const W = window.FoxyWallet;
    const plan = this.state.trPlan;
    if (!plan || this.state.trBusy) return;
    // and once more before anything moves, for the same reason
    if (this.refuseSwitchWhileBusy()) return;
    const to = this.mintNameOf(this.state.trTo);
    this.setState({ trBusy: true });
    this.showMelt('Moving your sats to ' + to + '…', 0, { sats: this.state.trSats, mint: to });
    /* Back on the mint the money leaves: the quote was made while connected to
     * the destination, and moveRun pays from whichever wallet is connected —
     * run from the destination it found nothing to spend (seen in the
     * simulator). */
    W.connect(this.state.trFrom).then(() => W.moveRun(plan, () => {})).then(done => {
      this.hideMelt();
      this.setState({ trBusy: false, trPlan: null, trStep: '', trErr: '' });
      this.refreshBalance();
      this.loadHistory();
      this.announcePayment({
        dir: 'out', sats: done.sats || this.state.trSats,
        hash: 'move-' + (plan.mintQuote ? plan.mintQuote.quote : Date.now()),
        to: to, force: true,
      });
    }).catch(e => {
      this.hideMelt();
      this.setState({ trBusy: false, trErr: W.reason(e) });
      this.toast(W.reason(e), true);
    });
  }

  /* Dropped: back to the mint the wallet was on before the quote. */
  trCancel() {
    const W = window.FoxyWallet;
    const back = this._trWas;
    this.setState({ screen: 'home', stack: [], trPlan: null, trStep: '', trErr: '', trBusy: false });
    if (W && back && W.mintUrl !== back) W.connect(back).then(() => this.refreshBalance(), () => {});
  }

  /* The confirmation screen's contents (confirmSpec). */
  transferSpec() {
    const s = this.state;
    const sats = s.trSats || 0;
    const fee = s.trFee;
    const rows = [
      this.cfRow('LANDING AT', (this.mintNameOf(s.trTo) || '').toUpperCase()),
      this.cfRow('PAYING FROM', (this.mintNameOf(s.trFrom) || '').toUpperCase(), { half: true }),
      this.cfRow('NETWORK', 'LIGHTNING', { half: true }),
      this.cfRow('ARRIVES', 'IN A MOMENT', { ink: 'var(--acc)', half: true }),
      this.cfRow('FEE ON TOP', s.trErr ? 'UNKNOWN'
        : fee == null ? 'CHECKING…' : 'UP TO ' + this.money(fee).main, { half: true }),
    ];
    if (s.trErr) {
      /* Only the fee was in the way, and this is how much would go instead.
       * Asking again for the same amount would only be refused again, so that
       * is the button this replaces; CANCEL is still there. */
      const fits = s.trFits || 0;
      return {
        title: 'CONFIRMATION', amountLabel: 'MOVING',
        amount: this.money(sats).main, amountSub: this.money(sats).sub, amountInk: '#FF5C5C', rows: rows,
        warn: s.trErr,
        cta: fits > 0 ? 'MOVE ' + this.money(fits).main + ' INSTEAD' : 'TRY AGAIN',
        ctaTone: fits > 0 ? 'go' : 'warn',
        go: () => { if (fits > 0) this.trMoveLess(fits); else this.quoteTransfer(); },
        secondary: { label: 'CANCEL', go: () => this.trCancel() },
      };
    }
    return {
      title: 'CONFIRMATION',
      amountLabel: 'MOVING',
      amount: this.money(sats).main,
      subtitle: fee == null ? '' : 'Up to ' + this.money(sats + fee).main + ' leaves '
        + (this.mintNameOf(s.trFrom) || 'the other mint'),
      amountSub: this.money(sats).sub,
      rows: rows,
      secondary: { label: 'CANCEL', go: () => this.trCancel() },
      cta: s.trBusy ? 'MOVING…' : fee == null ? 'CHECKING THE FEE…' : 'MOVE ' + this.money(sats).main,
      ctaTone: 'go',
      ctaBusy: !!s.trBusy || fee == null,
      go: () => { if (fee != null && !s.trBusy) this.runTransfer(); },
    };
  }
  /* ---- on chain (NUT-30) ---------------------------------------------------
   *
   * Receiving: ON-CHAIN is one of the receive screen's networks. The mint gives
   * an address, the QR carries it with the amount as a BIP-21 hint, and the
   * ecash is issued once the payment has the mint's confirmations. The floor
   * matters: under it a payment is lost rather than refused (16a-onchain.js).
   *
   * Sending: a scanned or pasted address (with its amount, when it carries one)
   * goes to the same confirmation a Lightning send uses, with the mint's fee
   * options — each a fee and a rough wait — to choose from. A payout is not
   * done when it leaves: the mint broadcasts and it is followed until the mint
   * says it confirmed.
   */

  /* What this mint does on chain, kept in state so the screens can ask. */
  onchainAsk() {
    const W = window.FoxyWallet;
    if (!W || !W.onchainLimits || this._ocAsked === W.mintUrl) return;
    this._ocAsked = W.mintUrl;
    W.onchainLimits().then(limits => this.setState({ ocLimits: limits || null }), () => {});
  }

  ocCan(which) {
    const limits = this.state.ocLimits;
    return !!(limits && limits[which]);
  }

  // MARK: receiving

  /* The receive screen's ON-CHAIN network: an address for this wallet, made
   * once per visit and kept while the screen is up. */
  ocReceiveAddress() {
    const W = window.FoxyWallet;
    if (!W || !W.onchainAddress) return '';
    if (this._ocAddr && this._ocAddr.mint === W.mintUrl) return this._ocAddr.address;
    if (this._ocMaking) return '';
    this._ocMaking = true;
    W.onchainAddress().then(made => {
      this._ocMaking = false;
      this._ocAddr = made;
      this.setState({ ocMade: Date.now() });
      this.onchainWatchLater();
    }, e => {
      this._ocMaking = false;
      this.setState({ ocErr: W.reason(e) });
      this.toast(W.reason(e), true);
    });
    return '';
  }

  /* What the receive screen shows under the QR on this network. */
  ocReceiveNote() {
    const limits = this.state.ocLimits;
    const floor = limits && limits.receive ? limits.receive.min : 0;
    const blocks = limits && limits.receive ? limits.receive.confirmations : 0;
    if (!floor) return 'This mint takes ordinary Bitcoin payments.';
    return 'Send at least ' + this.group(floor) + ' sats. Less than that is lost, not returned. '
      + (blocks ? 'Your ecash arrives after ' + blocks + ' confirmations.' : '');
  }

  /* Why a small amount cannot be asked for on chain. */
  /* The same fact in the space a greyed row has for it. The long form explains
   * why and belongs where there is room; a row under a network's name has one
   * line, and what a person needs there is the number. */
  ocFloorShort() {
    const limits = this.state.ocLimits;
    const floor = limits && limits.receive ? limits.receive.min : 0;
    return 'Minimum \u20bf ' + this.group(floor);
  }

  ocFloorSays() {
    const limits = this.state.ocLimits;
    const floor = limits && limits.receive ? limits.receive.min : 0;
    return 'On chain this mint takes ' + this.group(floor) + ' sats or more. '
      + 'Anything less is swallowed, not returned.';
  }

  /* Below the floor the address is worth nothing, so the screen says so rather
   * than showing a QR that eats the money. */
  ocReceiveBlocked(sats) {
    const limits = this.state.ocLimits;
    const floor = limits && limits.receive ? limits.receive.min : 0;
    return !!(floor && sats && sats < floor);
  }

  // MARK: sending

  /* A scanned or pasted address. With an amount it goes straight to the
   * confirmation; without one, to the keypad. */
  payOnchain(text) {
    const W = window.FoxyWallet;
    const read = W.readAddress ? W.readAddress(text) : null;
    if (!read) { this.toast('That is not a Bitcoin address Foxy can read.', true); return; }
    this.onchainAsk();
    const limits = this.state.ocLimits;
    if (limits && !limits.send) {
      this.toast(this.mintName() + ' does not send on chain. Move your sats to a mint that does.', true);
      return;
    }
    this.setState(p => ({
      ocTo: read.address, ocSats: read.sats || 0, ocPlan: null, ocErr: '', ocFee: null,
      screen: read.sats ? 'ocConfirm' : 'amount',
      stack: p.stack.concat([p.screen]),
      flow: read.sats ? p.flow : 'onchain',
      /* Dollars on the keypad, as every other amount screen opens — while
       * there is a price to turn them into sats with. */
      asset: 'BITCOIN', unit: (!read.sats && this.satUsd() > 0) ? 'USD' : 'SATS', amount: '',
      recipient: read.address, recipientKind: 'address',
    }));
    if (read.sats) this.ocQuote();
  }

  /* The keypad's NEXT during an on-chain send. */
  ocNext() {
    const sats = this.amountInSats();
    if (!(sats > 0)) { this.toast('Enter an amount first', true); return; }
    /* More than is here is refused at the keypad, before the mint is asked
     * for a fee: the confirmation said so only after its quote, a screen
     * later. The fee comes on top and is still
     * checked there. */
    if (sats > (this.state.balSats || 0)) { this.toast('That is more than your balance.', true); return; }
    const limits = this.state.ocLimits;
    const floor = limits && limits.send ? limits.send.min : 0;
    const ceiling = limits && limits.send ? limits.send.max : 0;
    if (floor && sats < floor) {
      this.toast('This mint sends at least ' + this.group(floor) + ' sats on chain.', true);
      return;
    }
    if (ceiling && sats > ceiling) {
      this.toast('This mint sends at most ' + this.group(ceiling) + ' sats on chain.', true);
      return;
    }
    this.setState(p => ({ screen: 'ocConfirm', stack: p.stack.concat([p.screen]), ocSats: sats,
      ocPlan: null, ocFee: null, ocErr: '' }));
    this.ocQuote();
  }

  /* The mint's fees for this payment. Nothing is spent by asking, and a
   * mistyped address is refused here, before any ecash moves. */
  ocQuote() {
    const W = window.FoxyWallet;
    const { ocTo, ocSats } = this.state;
    if (!ocTo || !(ocSats > 0)) return;
    this.setState({ ocQuoting: true, ocErr: '' });
    W.onchainQuote(ocTo, ocSats).then(plan => {
      this.setState({
        ocQuoting: false, ocPlan: plan, ocErr: '',
        // the quickest by default; the person can pick another
        ocFee: plan.options.length ? plan.options[0].index : null,
      });
    }, e => {
      this.setState({ ocQuoting: false, ocErr: W.reason(e) });
    });
  }

  /* The fee sheet, when the mint offers more than one. */
  ocPickFee() {
    const plan = this.state.ocPlan;
    if (!plan || plan.options.length < 2) return;
    this.chooseFrom('SPEED', plan.options.map(o => ({
      label: this.ocFeeLabel(o),
      on: o.index === this.state.ocFee,
      tap: () => this.setState({ ocFee: o.index }),
    })));
  }

  ocFeeLabel(option) {
    const blocks = option.blocks;
    const when = !blocks ? 'NEXT BLOCK'
      : blocks === 1 ? 'ABOUT 10 MINUTES'
      : blocks <= 6 ? 'ABOUT ' + blocks + ' BLOCKS'
      : 'ABOUT ' + Math.round(blocks / 6) + ' HOURS';
    return when + ' · ' + this.money(option.fee).main;
  }

  /* Hand it over. The mint takes the ecash and broadcasts; the confirmation
   * screen says it is on its way, and the watcher marks it done. */
  /* The transaction id out of a NUT-30 outpoint, or ''.
   *
   * The mint answers `txid:vout` once it has broadcast, and `null` before that.
   * This is the only explorer-searchable thing in an on-chain payout: PAYMENT ID
   * is the mint's own melt quote id with `onchain-` in front of it, which no
   * explorer has ever heard of. The wallet has
   * been resolving the outpoint all along (16a-onchain.js) and the app threw it
   * away every time.
   *
   * Checked rather than trusted: 64 hex characters, or nothing. It remains the
   * mint's claim — Foxy does not verify that this transaction pays the address
   * that was asked for, and a receipt is not a proof. */
  ocTxidOf(outpoint) {
    const txid = String(outpoint || '').split(':')[0].trim().toLowerCase();
    return /^[0-9a-f]{64}$/.test(txid) ? txid : '';
  }

  ocPay() {
    const W = window.FoxyWallet;
    const { ocPlan, ocFee } = this.state;
    if (!ocPlan || ocFee == null || this.state.ocBusy) return;
    this.setState({ ocBusy: true });
    this.showMelt('Handing it to the mint…');
    W.onchainPay(ocPlan, ocFee, stage => {
      if (stage === 'paying') this.meltSays('Sending it on chain…');
    }).then(done => {
      this.hideMelt();
      this.setState({ ocBusy: false, ocPlan: null, ocTo: '', ocSats: 0 });
      this.refreshBalance();
      this.loadHistory();
      this.onchainWatchLater();
      /* PENDING is what an on-chain payout looks like when it has gone: the
       * mint holds the transaction and the confirmation screen says so. An
       * answer with no state at all is different — the ecash has left and
       * nobody knows whether the mint took it — and saying SENT for that is
       * the mistake finding 9 is about, so it gets the same pending screen a
       * Lightning payment in flight gets. */
      const txid = this.ocTxidOf(done.outpoint);
      if (txid) W.tag('onchain-' + done.quote, { txid: txid });
      if (done.state === 'UNKNOWN') { this.showPayPending(); return; }
      this.announcePayment({ dir: 'out', sats: done.sats, hash: 'onchain-' + done.quote,
        to: 'a bitcoin address', force: true });
    }, e => {
      this.hideMelt();
      this.setState({ ocBusy: false, ocErr: W.reason(e) });
      this.toast(W.reason(e), true);
    });
  }

  /* The confirmation screen (confirmSpec), the same shell a Lightning send
   * uses, with the fee and the wait it buys. */
  onchainSpec() {
    const s = this.state;
    const plan = s.ocPlan;
    const pick = plan ? plan.options.filter(o => o.index === s.ocFee)[0] : null;
    const short = String(s.ocTo || '');
    const rows = [
      this.cfRow('DELIVERED TO', short.slice(0, 12) + '…' + short.slice(-8)),
      this.cfRow('PAYING FROM', (this.mintName() || 'THIS MINT').toUpperCase(), { half: true }),
      this.cfRow('NETWORK', 'ON-CHAIN', { half: true }),
      this.cfRow('ARRIVES', pick ? this.ocFeeLabel(pick).split(' · ')[0] : 'CHECKING…',
        { ink: 'var(--btc-ink)', half: true }),
      this.cfRow('FEE', s.ocErr ? 'UNKNOWN' : pick ? 'UP TO ' + this.money(pick.fee).main : 'CHECKING…',
        { half: true }),
    ];
    /* More than is here: said before the mint is asked to take it, the way a
     * payment request that overruns the balance is. */
    const owed = s.ocSats + (pick ? pick.fee : 0);
    if (pick && owed > (s.balSats || 0)) {
      return {
        title: 'CONFIRMATION', amountLabel: 'SENDING',
        amount: this.money(s.ocSats).main, amountSub: this.money(s.ocSats).sub, amountInk: '#FF5C5C', rows: rows,
        warn: this.heldBlocks(owed - (s.balSats || 0))
          || 'More than your balance — short by ' + this.money(owed - (s.balSats || 0)).main
          + ' with the fee',
        cta: 'CLOSE', ctaTone: 'warn', go: () => this.ocCancel(),
      };
    }
    if (s.ocErr) {
      return {
        title: 'CONFIRMATION', amountLabel: 'SENDING',
        amount: this.money(s.ocSats).main, amountSub: this.money(s.ocSats).sub, amountInk: '#FF5C5C', rows: rows,
        warn: s.ocErr,
        secondary: { label: 'CANCEL', go: () => this.ocCancel() },
        cta: 'TRY AGAIN', ctaTone: 'warn', go: () => this.ocQuote(),
      };
    }
    const many = !!(plan && plan.options.length > 1);
    return {
      title: 'CONFIRMATION',
      amountLabel: 'SENDING',
      amount: this.money(s.ocSats).main,
      amountSub: this.money(s.ocSats).sub,
      rows: rows,
      chip: 'A payment on chain is not instant. It is done when it confirms.',
      secondary: many
        ? { label: 'CHANGE THE SPEED', go: () => this.ocPickFee(), filled: true }
        : { label: 'CANCEL', go: () => this.ocCancel() },
      cta: s.ocBusy ? 'SENDING…' : pick ? 'SEND ' + this.money(s.ocSats).main : 'CHECKING THE FEE…',
      ctaTone: 'go',
      ctaBusy: !!s.ocBusy || !pick,
      go: () => { if (pick && !s.ocBusy) this.ocPay(); },
    };
  }

  ocCancel() {
    this.setState({ screen: 'home', stack: [], ocPlan: null, ocTo: '', ocSats: 0, ocErr: '' });
  }

  // MARK: watching

  /* Addresses waiting on a payment, and payouts waiting on a block. Asked on
   * launch, on return, and every few minutes while the app is open: on-chain
   * settlement is bounded by blocks, so there is nothing to gain by asking
   * more often than that. */
  onchainWatchLater(ms) {
    clearTimeout(this._ocWatchT);
    /* Soon when there is something to ask about.
     *
     * A phone is open for seconds at a time: in testing, a launch was in the
     * background again seventeen seconds later, where the first pass waited
     * twenty — and nothing on chain was asked
     * about for the rest of the day. An address or a payout on file gets a few
     * seconds; an empty wallet can wait, since nothing can arrive for it
     * without this app making it first. */
    const W = window.FoxyWallet;
    let wait = ms;
    if (wait === undefined) {
      let waiting = 0;
      try {
        const due = W && W.connected && (W.onchainDue || W.onchainWatching);
        waiting = (due ? due.call(W).length : 0)
          + (W && W.connected && W.onchainSending ? W.onchainSending().length : 0);
      } catch (e) { waiting = 0; }
      wait = waiting ? 3000 : 20000;
    }
    this._ocWatchT = setTimeout(() => this.onchainWatch(), wait);
  }

  /* The loop must outlive a pass that does nothing.
   *
   * Every early return here used to leave no timer behind, so one pass with
   * the wallet between mints, or with nothing yet to watch, ended the watching
   * for the rest of the session — and nothing re-armed it except a launch, a
   * new address or a payout. On a phone that goes in and out of a pocket that
   * is most of the time: a deposit confirmed at the mint and Foxy never asked
   * again (on a device: an address made, asked about seven minutes later, and
   * never again in the 27 minutes the app kept running). So every path out of
   * this sets the next one. */
  onchainWatch() {
    const W = window.FoxyWallet;
    clearTimeout(this._ocWatchT);
    const again = ms => { this._ocWatchT = setTimeout(() => this.onchainWatch(), ms); };
    // no wallet yet, or between mints: ask again soon rather than never
    if (!W || !W.onchainWatching || !W.connected) { again(20000); return; }
    // only those due this pass: an address a week old is not asked about every
    // two minutes (onchainDue)
    const waiting = W.onchainDue ? W.onchainDue() : W.onchainWatching();
    if (waiting.length && W.onchainAsked) W.onchainAsked(waiting.map(r => r.quote));
    const sending = W.onchainSending ? W.onchainSending() : [];
    if (!waiting.length && !sending.length) { again(120000); return; }

    // one at a time: every claim reserves counters, and two at once derive the same secrets
    const claims = waiting.reduce((chain, record) => chain.then(() => W.onchainClaim(record.quote)
      .then(got => {
        if (!got || !got.sats) return;
        this.refreshBalance();
        this.loadHistory();
        // the hash the wallet logged, so the confirmation and the entry are one thing
        this.announcePayment({ dir: 'in', sats: got.sats, hash: got.hash, to: 'on chain' });
      }, () => {})), Promise.resolve());

    claims.then(() => sending.reduce((chain, record) => chain.then(() => W.onchainFollow(record.quote)
      .then(answer => {
        /* Before the PAID test, because a payment that is still PENDING is
         * exactly the one whose outpoint has only just appeared: the mint
         * answers `null` until it broadcasts, so the melt above almost never
         * has it and this pass is where it arrives. */
        const txid = this.ocTxidOf(answer.outpoint);
        if (txid) W.tag('onchain-' + record.quote, { txid: txid });
        if (answer.state === 'PAID') {
          this.loadHistory();
          this.toast('Your ' + this.group(record.sats) + ' sat payment confirmed on chain');
          return;
        }
        // refused or never sent: the ecash has been put back (onchainFollow)
        if (answer.state === 'UNPAID' || answer.state === 'FAILED') {
          this.refreshBalance();
          this.loadHistory();
          this.toast('That on-chain payment did not go. Your ' + this.group(record.sats)
            + ' sats are back.', true);
        }
      }, () => {})), Promise.resolve()))
      .then(() => again(120000), () => again(120000));
  }

  /* ERRORS and LOGS: what Foxy has been doing, so it can be handed over.
   *
   * One screen, two ways in. ERRORS is the short list — the lines that read as
   * trouble — and LOGS is everything, which is what a hard question usually
   * needs: the screens visited, the mint requests, Tor's state, the timings.
   *
   * The lines come from the phone (FoxyWallet.fieldLog → FieldLog.swift), in
   * every build, and are redacted there rather than here: tokens, invoices,
   * payment requests, onion addresses, nostr keys and long hex are gone before
   * the page sees them, so this screen cannot copy out what it never had. Mint
   * hosts and sat amounts stay, because without them a report cannot be
   * answered — and the screen says that in as many words before anyone copies.
   *
   * Nothing is sent anywhere. There is no reporting in Foxy and this does not
   * add any: the lines are memory on the phone, and the only way out is the
   * person tapping COPY and choosing where to paste it.
   */
  goFieldLog(onlyBad) {
    this.setState(p => ({
      screen: 'fieldLog', stack: p.stack.concat([p.screen]),
      flLines: null, flBad: !!onlyBad, flCopied: false,
    }));
    this.loadFieldLog(!!onlyBad);
  }

  loadFieldLog(onlyBad) {
    const W = window.FoxyWallet;
    if (!W || !W.fieldLog) { this.setState({ flLines: [] }); return; }
    W.fieldLog(onlyBad).then(lines => {
      // newest first: what just went wrong is what someone is looking for
      this.setState({ flLines: (lines || []).slice().reverse() });
    }, () => this.setState({ flLines: [] }));
  }

  /* One line as it is copied and shown: the time, then the text.
   *
   * A time of day rather than a stamp — someone reading their own log is
   * matching it against "it went wrong just after I tapped send", not against
   * another clock. */
  flStamp(at) {
    const d = new Date(Number(at) || 0);
    const two = n => (n < 10 ? '0' : '') + n;
    return two(d.getHours()) + ':' + two(d.getMinutes()) + ':' + two(d.getSeconds());
  }

  flText() {
    const lines = this.state.flLines || [];
    const head = 'Foxy ' + (this.state.flBad ? 'errors' : 'log') + ', '
      + lines.length + ' line' + (lines.length === 1 ? '' : 's')
      + ', newest first. Tokens, invoices, payment requests, onion addresses and '
      + 'keys are already removed; mint hosts and amounts are not.';
    // back to oldest first for reading: a log is a story
    const body = lines.slice().reverse()
      .map(l => this.flStamp(l.at) + '  ' + String(l.text || '')).join('\n');
    return head + '\n\n' + body + '\n';
  }

  copyFieldLog() {
    const lines = this.state.flLines || [];
    if (!lines.length) { this.toast('There is nothing to copy yet.', true); return; }
    /* Device-only and short-lived, like every other copy Foxy makes: the log
     * names mint hosts and amounts, and that is not for every Mac and iPad
     * signed into the same account (copySecret). */
    if (this.copySecret(this.flText())) this.setState({ flCopied: true });
    else this.toast('Could not copy', true);
  }

  /* SHARE, beside COPY ALL, because a log is not a thing to paste.
   *
   * COPY ALL was the only way out of this screen, and it puts two thousand
   * lines on the clipboard for somebody to paste into a message. That is fine
   * for a line or two and hopeless for a session: long pastes are truncated by
   * some apps, the clipboard expires, and nobody scrolls it to check.
   *
   * The share sheet hands the same text to Files, Mail, AirDrop — whatever the
   * person already uses — as one thing they can attach. It matters most on a
   * Release build, where this screen is the only record that exists: `print` is
   * silent, `DebugLog` is not compiled in, and a tester who cannot get the log
   * off the phone has no way to be believed. */
  shareFieldLog() {
    const W = window.FoxyWallet;
    const lines = this.state.flLines || [];
    if (!lines.length) { this.toast('There is nothing to share yet.', true); return; }
    if (!W || !W.share || !W.share(this.flText())) {
      this.toast('Sharing is only available in the app.', true);
    }
  }

  clearFieldLog() {
    const W = window.FoxyWallet;
    this.blockedCard('clearLog', {
      tone: 'ask',
      title: 'CLEAR THE LOG?',
      reason: 'Everything Foxy remembers about what it has been doing is forgotten. '
        + 'It starts again from here. Nothing about your money changes.',
      retry: 'CLEAR IT',
      go: () => {
        if (!W || !W.clearFieldLog) return;
        W.clearFieldLog().then(() => {
          this.setState({ flLines: [], flCopied: false });
          this.toast('The log was cleared');
        });
      },
      shut: { label: 'KEEP IT' },
    });
  }
  /* ---- tap to pay, over Bluetooth (TAP-TO-PAY.md) ------------------------ */

  /* Which side of tap to pay this screen is on, kept in step on every update:
   * a Lightning invoice on screen is advertised, and the TAP TO PAY screen
   * searches. Leaving either stops it. */
  /* What the screen in front of somebody can be paid by tap, if anything:
   * `{ inv, req, waiting }`, or null when this screen has nothing payable on
   * it. `waiting` means a request for it is being made and the offer should
   * hold rather than go out half.
   *
   * One place, because there are four screens and two rails and they kept
   * disagreeing. The receive invoice screen only went on the air on the
   * Lightning rail, so switching it to CASHU — where the QR is a payment
   * request and a tap is the better way to hand it over, not a worse one —
   * silently turned tap to pay off. And the split's payer
   * screen, which shows one share's code exactly as the receive screen shows
   * an invoice, was never on the air at all.
   *
   * ON-CHAIN is not here and cannot be: an address is not a thing a Foxy pays
   * over a Bluetooth link. Nor is a bank wire, nor a receive reopened from
   * history as a plain address. */
  tapOffering() {
    const W = window.FoxyWallet;
    if (!W) return null;
    const s = this.state;
    const cashu = (rail) => rail === 'CASHU';
    // a payment that has arrived and is being moved to this phone's mint: nothing more to be paid here
    if (this._carryingHome) return null;

    /* The amount screen of a receive, where the screen arms itself: on the
     * air with nothing to offer yet. A payer's phone needs about a second and
     * a half to open its quiet link and read which iPhone this is, and both
     * CONNECT TO PAY cards wait for that — so the link is given a head start
     * while the amount is still being typed, and the cards are up the moment
     * the invoice screen is. Nothing can be paid from
     * here: the offer is M4 and there is none until the next screen. With
     * AUTO TAP TO PAY off this screen has no TAP button and never arms. */
    if (s.screen === 'amount' && s.flow === 'receive') {
      return this.tapAutoArms() ? { inv: '', req: '', waiting: true } : null;
    }
    // the receive invoice screen
    if (s.screen === 'confirm' && s.flow === 'receive') {
      if (s.recvRail === 'ON-CHAIN' || s.invoiceIsAddress) return null;
      if (s.recvVia === 'wire' || s.network === 'BANK WIRE') return null;
      if (cashu(s.recvRail)) {
        /* The rail's own request, not one made beside it: the QR on screen and
         * the offer on the air have to be the same request, or a share paid by
         * tap settles a row the screen is not watching. */
        const req = this.cashuRequest();
        return req ? { inv: '', req: req, waiting: false } : { inv: '', req: '', waiting: true };
      }
      /* No invoice yet is *waiting*, not *no*.
       *
       * It used to be `null`, which meant this screen could not be tapped at
       * all — so pressing TAP in the second before the invoice was made
       * answered "Nothing to be paid yet" and did nothing.
       * That is the very second the press is most useful: the handshake needs
       * no offer, so the phones can be talking through it and the offer
       * follows (TapReceiver.offerSent). The refusals above are the real ones —
       * on chain, a wire, a plain address — and they stay `null`. */
      /* The ecash half does not wait for the invoice.
       *
       * A Lightning invoice is the mint's to make and takes seconds over Tor.
       * The Cashu request is this phone's own and needs nothing but the amount
       * the person typed — which is the same amount the invoice will be for.
       * So another Foxy at the same mint can be paid the instant the phones
       * touch, and the invoice arrives when it arrives, for the wallets that
       * actually need one.
       *
       * The request comes from `cashuRequest`, which prefers the typed figure
       * over the invoice's, so the two can never name different amounts. */
      const inv = W.classify(String(s.invoice || '')) === 'invoice' ? String(s.invoice) : '';
      /* Made here and now, with no onion address on it: the payment comes back
       * over the link that carried this (`tapOnlyRequest`). So another Foxy at
       * the same mint can be paid the moment the phones touch, and the invoice
       * joins the offer when the mint gets round to making it. */
      const want = this.wantedSats() || W.amountOf(inv) || 0;
      const req = this.tapOnlyRequest(want) || '';
      if (!inv && !req) return { inv: '', req: '', waiting: true };
      return { inv: inv, req: req, waiting: false };
    }

    /* The split's payer screen: one share, one code, held up to one phone.
     * The same screen the receive invoice screen is, for one person's part of
     * a bill, so it behaves the same way. Its request
     * carries `split:<idx>` as its purpose, which is what settles that row
     * when the payment lands (requestPaidHere). */
    if (s.screen === 'spPayer') {
      const idx = Number(s.spIdx) || 0;
      const inv = String((s.spInvoices || [])[idx] || '');
      const want = W.amountOf(inv) || (this.spShareSats ? this.spShareSats(idx) : 0);
      /* Offered the moment the phones touch, as the receive screen's is: a
       * request with no onion address on it, paid back over this link. It
       * waited on the share's Lightning invoice and then on the address,
       * neither of which another Foxy at this mint needs. */
      const quick = want > 0 ? (this.tapOnlyRequest(want, 'split:' + idx) || '') : '';
      // as above: a share whose code is still being made is waiting, not no
      if (!inv) return quick ? { inv: '', req: quick, waiting: false } : { inv: '', req: '', waiting: true };
      const req = this.railRequest(want, 'split:' + idx) || quick;
      if (cashu(s.spRail)) {
        return req ? { inv: '', req: req, waiting: false }
          : { inv: '', req: '', waiting: this.railRequestPending(want, 'split:' + idx) };
      }
      if (W.classify(inv) !== 'invoice') return { inv: '', req: '', waiting: true };
      return { inv: inv, req: req, waiting: !req && this.railRequestPending(want, 'split:' + idx) };
    }

    return null;
  }

  syncTap() {
    const W = window.FoxyWallet;
    if (!W || !W.tapReceive) return;
    const s = this.state;
    // the CONNECT TO PAY card follows the screen as well as the payer
    if (this.syncConnectRecv) this.syncConnectRecv();
    const asking = this.tapOffering();
    /* Being able to go on the air, and choosing to.
     *
     * `tapOffering` says this screen has something a payer could pay. It used
     * to be the whole condition, because the phone that advertised was the
     * payer's and this side only listened — listening emits nothing, so doing
     * it whenever an invoice was up cost nothing.
     *
     * The roles are the other way round now (TapLink.swift): this side is the
     * one on the air. A receive screen that advertised by itself would be a
     * till standing on the air for as long as it was open, which is exactly
     * the beacon the old arrangement existed to avoid. So the button is the
     * condition. Nothing broadcasts until somebody presses TAP, and it comes
     * off the air again the moment the screen goes or a payer is found. */
    const armed = !!(asking && s.tapArmed);
    const advertise = armed;
    const inv = (asking && asking.inv) || '';
    /* Both ways of being paid go over the air, and the payer picks.
     *
     * A payer on this same mint pays with ecash instead of Lightning: phone to
     * phone, no route, no fee, and the mint never sees a payment between two
     * of its own users. Only the payer knows which mint it is on, so the
     * choice is theirs to make and this side offers both.
     *
     * The request is '' for the moment it takes to open an onion address, and
     * appears on a later pass; `railRequest` then keeps it, so the offer
     * settles rather than churning.
     *
     * No *offer* goes out during that moment. An offer without the request
     * half is paid over Lightning — with a routing fee, and with the mint
     * shown both ends — by two phones sitting on the same mint that could have
     * paid each other directly. A payer quick enough to tap inside that window
     * got exactly that.
     *
     * The radio does. Nothing in the handshake needs the offer: it is M4, and
     * the four digits are settled at M3 from the transcript, which the offer is
     * not in. So the placeholder `{}` means "on the air, nothing to offer yet",
     * the phones talk and both screens show the code while the address is still
     * being published, and the real offer follows as M4 the moment there is one
     * (TapLink.offerSent). If the address never answers,
     * railRequest stops waiting and the invoice goes out alone, which is the
     * right fallback and not this case. */
    const req = (asking && asking.req) || '';
    const waiting = advertise && !req && asking.waiting;
    /* Current, not merely known: `priceAgo()` is '' only while the figure on
     * screen is one this app still treats as live. */
    const mine = (W.lastPrice && W.lastPrice()) || { rate: 0 };
    const fresh = (!this.offlineNow() && !this.priceAgo() && Number(mine.rate) > 0)
      ? Number(mine.rate) : 0;
    const offer = !advertise ? ''
      : waiting ? '{}'
      /* `up`: whether this phone has a route, said by the phone that knows.
       *
       * The payer has to know it to hold the hand-over rules up its own end —
       * an offline receiver may only be handed ecash locked to it, at its own
       * mint — and it was being guessed from whether the request named an onion
       * address. That guess is wrong in the common case: Tor takes half a
       * minute to publish one, and an online receiver on the CASHU rail may
       * name none at all, so a perfectly settleable payment looked like two
       * offline phones. A fact about this phone, stated by this phone.
       *
       * Absent on an older Foxy, and absent is not false: the payer falls back
       * to what it did before, which is to make the payment and let the
       * receiver refuse it. */
      : JSON.stringify({ v: 2, inv: inv || undefined, req: req || undefined,
                         up: !this.offlineNow(),
                         /* This phone answers "I am about to pay this" before
                          * any ecash is made (`askFirst`). Said here so a payer
                          * only asks a phone that will answer; an older Foxy
                          * says nothing and is paid as before. */
                         ask: 1,
                         /* And this phone's bitcoin price, when it is current.
                          *
                          * A phone with no route has a price that may be hours
                          * old, and in a tap it is trusting the other one's —
                          * so it should be able to SEE the other one's rather
                          * than convert at its own and hope. The payer already tells a receiver this
                          * in M10; this is the same fact in the other
                          * direction, so an offline payer learns it too.
                          *
                          * Only when it is current: an offer carrying a stale
                          * price would be worse than carrying none, because the
                          * phone reading it has no way to tell. */
                         rate: fresh > 0 ? Math.round(fresh) : undefined,
                         at: fresh > 0 ? Math.round(Date.now() / 1000) : undefined });
    /* An offer already given stands; one never given may still arrive.
     *
     * Swapping an offer under a payer breaks the digits they are comparing.
     * Sending the first one late does not — they are settled at M3, before any
     * offer exists — so the "nothing yet" placeholder is allowed to become the
     * real offer with a payer on the link, and only that. */
    const withAPayer = !!(s.tapShownCode || s.tapRecvStage === 'connecting');
    const firstOffer = this._tapOffer === '{}' && offer !== '{}';
    /* The invoice, sent after the offer when the offer went without it.
     *
     * An offer given stands, and it goes out the moment there is a request to
     * offer, which is before the mint has answered with an invoice. A payer
     * already touching got "no invoice", took that for a receiver with no
     * route, and moved its sats to this phone's mint to pay in ecash there:
     * a Lightning move, a swap and 51 seconds where paying the invoice was
     * one payment (across two mints: the offer went out, was read 0.4 s
     * later, and the invoice came in 3.1 s after the offer). The payer now
     * waits a few seconds for this, which rides the message the price talk
     * answers on (M11), so the offer itself is not swapped under anybody. */
    /* And not into a talk. It rides the message a question is answered on,
     * and a payer waiting on an answer read it as one: a payer with no
     * route, asking what bringing its sats home would cost, got an invoice
     * with no request in it and took that for "they could not take it" —
     * twice in three tries. The same for a payer waiting on a price to be
     * agreed. It goes when the talk is over, if it is still wanted then. */
    if (advertise && inv && withAPayer && !this._tapTalking && this._tapInvTold !== inv && this._tapOffer && this._tapOffer !== '{}') {
      let had = null;
      try { had = JSON.parse(this._tapOffer); } catch (e) { had = null; }
      if (had && !had.inv) {
        this._tapInvTold = inv;
        console.log('[foxy] tap: the invoice is in after the offer went; sending it to the payer on the link');
        if (W.tapTerms) W.tapTerms(JSON.stringify({ inv: inv })).catch(() => {});
      }
    }
    /* Except while this tap is still being talked about.
     *
     * `priceConfirm` and `crossConfirm` are part of a conversation already in
     * flight: the payer has sent a figure and is holding the link open waiting
     * for the answer. They are not receive screens, so everything below read
     * them as "the person left" and called `tapReceiveStop`, which retires the
     * receiver — and the answer, when it came, had nowhere to go. `sendTerms`
     * found no subscribed central and returned false, so an ACCEPT reached the
     * payer as silence.
     *
     * This is what a card used to buy for free — a card floats over the receive
     * screen and `screen` never changes. Turning the decision into a screen
     * took the radio down with it, so the screen has to say it is still in the
     * same tap. Nothing changes: not the offer, not the advertisement, not the
     * link. The clocks that end it are the link's own (TapLink: 90 seconds once
     * a person is being asked, 95 before the payer gives up). */
    /* A tap being talked about holds everything, and the SCREEN is not what
     * says so.
     *
     * Keying this on the screen was wrong twice. First because the decision
     * moved from a card (which leaves `screen` alone) to a screen, which read
     * as leaving. Then because naming the two new screens here was still not
     * enough: `priceAnswer` navigates home and *then* sends the terms, so the
     * update that matters arrives with `screen` already 'home' — the radio was
     * retired sixteen milliseconds before `tapTerms` was called, and the answer
     * had nowhere to go.
     *
     * So it is not a screen question at all. `_tapTalking` is set when a
     * decision is put to a person with a payer waiting, and cleared when the
     * answer has actually gone — by which time nothing else can race it. */
    if (this._tapTalking) return;
    if (!asking && s.tapArmed) this.setState({ tapArmed: false });
    /* The amount screen is on the air early, and says so: the payer's card
     * waits for NEXT. Told again when the screen moves on,
     * even if the offer itself is still the same "nothing yet". */
    const early = s.screen === 'amount';
    if (advertise && (!withAPayer || firstOffer) && (this._tapOffer !== offer || this._tapEarly !== early)) {
      this._tapEarly = early;
      /* Said out loud, because a missing request half is invisible: the offer
       * still works, the payer still pays, and the only sign that ecash was
       * never on the table is a Lightning payment where one was not wanted. */
      console.log('[foxy] tap: on the air, offering '
        + (waiting ? 'nothing yet — the request is still being made'
          : (inv ? 'an invoice' : 'no invoice')
            + (req ? ' and a request for ' + (W.mintUrl || '?') : ' only — no request yet')));
      const was = this._tapOffer;
      this._tapOffer = offer;
      // the code belongs to a payer, and only a swapped offer loses one
      if (was !== '{}' && (s.tapShownCode || s.tapRecvStage === 'connecting')) {
        this.setState({ tapShownCode: '', tapRecvStage: '' });
      }
      W.tapReceive(offer === '{}' ? '' : offer, early).then(() => {
        if (this.state.tapNotYet) this.setState({ tapNotYet: '' });
      }, (e) => {
        /* A refusal has to undo the optimism above, or nothing tries again.
         *
         * `_tapOffer` is set before the call, and the guard that decides to
         * advertise is `this._tapOffer !== offer` — so a refused tapReceive
         * left the phone off the air with the offer recorded as sent. Nothing
         * retried. The screen went on saying HOLD A PHONE HERE over a radio
         * that was not on, and the only way out was to press TAP again, which
         * clears `_tapOffer` by hand. That is the pressing-several-times that
         * was reported, and the refusal is usually "That payment is still
         * going through. A moment." — which passes on its own in a second or
         * two.
         *
         * So: forget the offer, say so on the screen, and let the next pass
         * try again. On a clock rather than at once, because syncTap runs on
         * every update and an immediate retry against a mint that is busy is a
         * loop. */
        console.warn('[foxy] tap: not advertising:', e.message);
        this._tapOffer = null;
        const why = (W.reason ? W.reason(e) : e.message) || '';
        if (this.state.tapNotYet !== why) this.setState({ tapNotYet: why });
        clearTimeout(this._tapRetryT);
        this._tapRetryT = setTimeout(() => {
          if (this.state.tapArmed) this.syncTap();
        }, 1200);
      });
    } else if (!advertise && this._tapOffer) {
      this._tapPaidHere = false;
      this._nearEdge = '';
      if (this.hideConnectRecv) this.hideConnectRecv();
      clearTimeout(this._tapRetryT);
      if (this.state.tapNotYet) this.setState({ tapNotYet: '' });
      this._tapOffer = null;
      /* `off` goes too. It was the receiver that said the radio was off, and
       * the receiver is being stopped: a stage that outlives it kept the next
       * invoice screen from arming at all — `syncTap` refuses to arm with the
       * radio off — so nothing ever asked the radio again, and the button
       * stayed grey with Bluetooth on until the app was killed. The next
       * screen arms afresh, and a receiver that
       * finds the radio still off says `off` again. */
      if (s.tapShownCode || s.tapRecvStage === 'connecting' || s.tapRecvStage === 'off') {
        this.setState({ tapShownCode: '', tapRecvStage: '' });
      }
      W.tapReceiveStop();
    }

    /* The search runs once per visit to this screen, and stops for good once
     * an offer is in.
     *
     * `tapPay` resolves, `_tapPaying` goes null, and this used to see "on the
     * tap screen with nothing running" and start again — a second later, while
     * the confirmation was still a beat away. Starting again tears down the
     * Bluetooth link to build a new one, and that link is what the payment was
     * about to go over: every ecash payment fell back to the onion with "that
     * phone is no longer connected", and took twelve to twenty-six seconds
     * instead.
     *
     * The link is left alone when the screen changes, too. The payer is on the
     * confirmation by then and the money still has to cross; the native side
     * lets it go by itself after three minutes if nobody pays. */
    /* Listening, from the screens a person pays from.
     *
     * This costs nothing to anybody: a central hears and says nothing, so a
     * phone doing this in a room full of merchants gives away nothing it could
     * be followed by. It is why the payer can be the one always ready, and why
     * paying needs no screen of its own — the merchant presses TAP, this phone
     * hears it, and the confirmation comes up.
     *
     * Home and the send screen, and nowhere else. Not while a payment is
     * already going out (`sendPhase`) or a request is being paid (`reqBusy`):
     * a second payment opening itself over the first is the one way this could
     * cost money rather than a moment. Not in the background either — Foxy has
     * no background modes and asks for none, so this stops with the
     * foreground. */
    /* `sendPhase === 'in'`, not any `sendPhase`.
     *
     * A completed send leaves it `'settled'`, and the paths that clear it are
     * ones a *successful* send never takes (03-send.js). So the first payment
     * of a launch turned listening off for the rest of the app's life: the
     * payer went on the air once and heard nothing for the next nine minutes
     * while the receiver pressed TAP six more times, each with its own
     * service UUID, every one of them inside a window the payer spent sitting
     * on home. What must stop a
     * listen is money actually on the wire, which is what `'in'` means. */
    /* And not under the launch screen. Home is the screen behind it from the
     * first frame, so the listen started there — and the first listen is what
     * makes iOS ask for Bluetooth. On a first launch that put a system alert
     * over SECURING YOUR CONNECTION, and Tor's control link went unanswered
     * for ten seconds behind it. Asked
     * once the connection is up and home is what the person is looking at. */
    const G = window.FoxyGate;
    const gateUp = !!(G && G.visible && G.visible());
    /* The receiver arms itself. An invoice with an amount
     * on screen goes on the air without a press, so two Foxys held together
     * pay with no button. What it gives away is a random UUID for the length
     * of an invoice instead of a tap, unattributable and never repeated — and
     * every invoice advertising means a sniffer who knows Foxy's shape can no
     * longer tell a tap from a QR receive. The payer's side is untouched: it
     * still never advertises. TAP-TO-PAY.md, "The screen is the whole of it".
     *
     * Not while a code is up, not while a payer is connecting, not with the
     * radio off, and not when the person has turned it off in the menu. */
    if (this.tapAutoArms() && asking && !s.tapArmed && !s.tapShownCode
        && s.tapRecvStage !== 'connecting' && ['off', 'denied', 'unsupported'].indexOf(s.tapRecvStage) < 0
        && !gateUp && !this._tapTalking && !this._tapPaidHere && !(this.tapPaidChecking && this.tapPaidChecking())) {
      console.log('[foxy] tap: armed by the screen');
      this._tapOffer = null;
      // the QR stays: the card that covers it is for a press (`tapAutoFresh` gives the first press that)
      this.setState({ tapArmed: true, tapCardOff: true, tapAutoFresh: true });
      return;
    }
    const listening = (s.screen === 'home' || s.screen === 'sendHow')
      && s.sendPhase !== 'in' && !s.reqBusy && !gateUp;
    /* And the marks are cleared only when there is no tap to protect.
     *
     * `_tapKeep` is what stops `syncTap` searching again under a live link —
     * the link the payment is about to cross. It used to be safe to clear both
     * on home, because a payer that had taken an offer was on its own tap
     * screen, never home. The payer lives on home now, so this ran in the same
     * update as the offer landing and tore the link down: the first tap fell
     * back to the onion with "that phone is no longer connected" and took
     * 7941 ms instead of 200. That is
     * the regression the comment above this describes, arriving by the other
     * door. `_tapKeep` is dropped when the payment is done with the link, so
     * waiting for it is exactly right. */
    if (s.screen !== 'home') this._tapAway = true;
    if (s.screen === 'home' && this._tapAway && s.sendPhase !== 'in' && !this.changeStillDue()) {
      /* Home again, with the payment over: the next tap may start.
       *
       * The marks cannot be cleared the moment the offer lands, because that
       * happens *on* home — the payer has no screen of its own any more — and
       * clearing them there tore down the link the payment was about to cross
       *. They cannot be left for ever either, or one tap ends
       * listening for the life of the app. So the release is "went away and
       * came back": `tapStartPay` navigates to the confirmation the instant an
       * offer lands, so a return to home is the payment being finished with. */
      this._tapAway = false;
      this._tapGot = false;
      this._tapKeep = false;
      /* And five seconds of not listening, when what ended was a payment.
       *
       * The receiver is very likely still on the air: an invoice paid over
       * Lightning is news its mint has to give it. Listening at once heard
       * it again and put CONNECT TO PAY up on both phones, for a payment
       * that was already made. */
      if (this._tapPaidAt) { this._tapPaidAt = 0; this._tapQuietUntil = Date.now() + 5000; }
    }
    const quietFor = (this._tapQuietUntil || 0) - Date.now();
    if (quietFor > 0 && !this._tapQuietT) {
      this._tapQuietT = setTimeout(() => { this._tapQuietT = null; this.syncTap(); }, quietFor + 30);
    }
    if (listening && quietFor <= 0 && !this._tapPaying && !this._tapGot) this.tapStartPay();
    else if (!listening && this._tapPaying && !this.changeStillDue()) {
      /* Not while change is owed.
       *
       * `listening` is false the moment the payment leaves — the payer is on
       * the confirmation screen, not home — so this fired about four seconds
       * before the receiver's change was ready and took the link with it. The
       * release on reaching home was guarded and this, which happens first, was
       * not. Both have to know. */
      this._tapPaying = null;
      this.hideTapNearby();
      this.tapBuzz(false);
      W.tapPayStop();
    }
    if (!listening && this._tapGot && !this._tapKeep) this._tapGot = false;
    /* And a backstop, for a tap that ended somewhere this does not know about.
     *
     * The release above is "went away from home and came back", which is how a
     * finished payment announces itself. Every path that ends a tap WITHOUT
     * going anywhere has to say so itself (`tapGaveNothing`), and the ones that
     * exist do — but a path added later would not, and the cost is a payer that
     * silently stops hearing taps until it is navigated away and back. So: sitting on home, nothing in flight, nothing owed,
     * and an offer that landed fifteen seconds ago and went nowhere, is a tap
     * that is over. A real one is off home inside a second. */
    /* Not while an answer is being waited for. The price talk happens on home
     * — the waiting screen is drawn over it — and a person reading two figures
     * on the other phone takes longer than fifteen seconds as often as not.
     * This let the link go under them: let go 26 seconds after the question,
     * and their YES two seconds later went to nobody. The wait has its own
     * clock, ninety seconds, and its own CANCEL. */
    const waitingOnAnswer = !!this._tapQuoteSeq || !!s.tapQuoteWait || !!this._tapTalking;
    if (listening && this._tapGot && !this._tapPaying && !this.changeStillDue() && !waitingOnAnswer
        && this._tapGotAt && Date.now() - this._tapGotAt > 15000) {
      this.tapGaveNothing('nothing came of it');
    }
  }

  /* ---- a payment by tap that the other phone has not seen yet ----------
   *
   * Ecash crosses the link and is answered on it, so both phones know at
   * once. An invoice paid over Lightning is not: the payer's mint pays the
   * receiver's, and the receiver hears from its own mint, on its own clock.
   * For those seconds the receiver is still on its invoice screen and on the
   * air, and the payer is home again and listening (CONNECT TO PAY on both,
   * for a payment already made).
   *
   * Three things, each of which is enough by itself:
   *   the payer says "paid" over the link, and the receiver asks its mint
   *     at once (`tapSayPaid`, `tapPaidNotice`);
   *   the payer does not listen for five seconds after a payment (`syncTap`);
   *   an offer this phone has already paid is said to be ALREADY PAID and is
   *     not paid again (`tapWasPaid`, in `tapStartPay`). */

  /* What names an offer: the end of its invoice, and its request's id. Kept
   * for a day, thirty at most, on this phone only. */
  tapPaidKeys(offer, req) {
    const keys = [];
    const inv = String((offer && offer.inv) || '');
    if (inv.length > 40) keys.push('i:' + inv.toLowerCase().slice(-24));
    const id = String((offer && offer.read && offer.read.id) || '');
    if (id) keys.push('r:' + id);
    const paid = String((req && req.id) || '');
    if (paid && paid !== id) keys.push('r:' + paid);
    return keys;
  }
  tapPaidList() {
    let list = [];
    try { list = JSON.parse(localStorage.getItem('foxy.tap.paid') || '[]'); } catch (e) { list = []; }
    const since = Date.now() - 86400000;
    return (Array.isArray(list) ? list : []).filter(x => x && typeof x.k === 'string' && Number(x.at) > since);
  }
  tapMarkPaid(offer, req) {
    const keys = this.tapPaidKeys(offer, req);
    // home again from this, the phone does not listen for five seconds (syncTap)
    this._tapPaidAt = Date.now();
    if (!keys.length) return;
    const list = this.tapPaidList().filter(x => keys.indexOf(x.k) < 0);
    keys.forEach(k => list.push({ k: k, at: Date.now() }));
    try { localStorage.setItem('foxy.tap.paid', JSON.stringify(list.slice(-30))); } catch (e) {}
  }
  /* When this phone paid that offer, or 0. */
  tapWasPaid(offer) {
    const keys = this.tapPaidKeys(offer, null);
    if (!keys.length) return 0;
    const hit = this.tapPaidList().filter(x => keys.indexOf(x.k) >= 0).map(x => Number(x.at) || 0);
    return hit.length ? Math.max.apply(null, hit) : 0;
  }
  tapAgoWords(at) {
    const s = Math.max(0, Math.round((Date.now() - at) / 1000));
    return s < 5 ? 'a moment ago' : s < 90 ? s + ' seconds ago' : s < 5400 ? Math.round(s / 60) + ' minutes ago' : Math.round(s / 3600) + ' hours ago';
  }
  /* The payer, telling the receiver its invoice is paid. Over the link the
   * tap made, if it is still there; said and forgotten if it is not, because
   * the receiver's mint will tell it anyway. Only which invoice: the end of
   * the invoice the receiver itself made. */
  tapSayPaid(inv) {
    const W = window.FoxyWallet;
    if (!W || !W.tapQuote || !inv) return;
    W.tapQuote(JSON.stringify({ paid: { tail: String(inv).toLowerCase().slice(-16) } })).then(
      () => console.log('[foxy] tap: told them the invoice is paid'),
      (e) => console.log('[foxy] tap: could not tell them the invoice is paid (' + ((e && e.message) || e) + '); their mint will'));
  }
  /* A Lightning send has finished (03-send.js). If the invoice was a tap's,
   * the other phone is told and the offer is remembered as paid. */
  tapPaidByLightning(inv) {
    const offer = this._tapOfferNow;
    const same = (a, b) => String(a || '').replace(/^lightning:/i, '').toLowerCase() === String(b || '').replace(/^lightning:/i, '').toLowerCase();
    if (!offer || !offer.inv || !same(offer.inv, inv)) return;
    this.tapMarkPaid(offer, null);
    this.tapSayPaid(inv);
  }
  /* The receiver's mint is asked every second for a while (`watchKick`). */
  tapWatchClosely(ms) {
    const W = window.FoxyWallet, s = this.state;
    if (!W || !W.watchKick || !s.invoiceHash || !this._watching) return false;
    return W.watchKick(s.invoiceHash, ms);
  }
  /* The payer has said this screen's invoice is paid, within the last twenty
   * seconds, and the mint has not agreed yet. */
  tapPaidChecking() {
    return !!this._tapPaidNote && Date.now() - this._tapPaidNote < 20000;
  }
  /* The receiver, hearing the payer say so (M10 `{ paid }`).
   *
   * Not believed: the payer's word moves no money. It is a reason to ask the
   * mint now instead of in ten seconds, and to stop offering the same invoice
   * to the phone that says it has paid it. The screen says what is happening
   * and goes to PAYMENT RECEIVED only when the mint says so; if the mint has
   * not seen it in twenty seconds the invoice is simply open again. */
  tapPaidNotice(info) {
    const s = this.state;
    const tail = String((info && info.tail) || '').toLowerCase();
    const mine = String(s.invoice || '').toLowerCase();
    const onScreen = s.screen === 'confirm' && s.flow === 'receive';
    if (!onScreen || tail.length < 12 || !mine || mine.slice(-tail.length) !== tail) {
      console.log('[foxy] tap: the payer says it paid an invoice that is not the one on this screen; nothing done');
      return;
    }
    if (this.tapPaidChecking()) return;
    console.log('[foxy] tap: the payer says this invoice is paid; asking the mint now');
    this._tapPaidNote = Date.now();
    clearTimeout(this._nearGoneT);
    this._nearEdge = '';
    if (this.hideConnectRecv) this.hideConnectRecv();
    this.tapWatchClosely(20000);
    this.waitingScreen('paidCheck', {
      art: 'phone', title: 'Confirming<br>payment', dots: true, forMs: 20000,
      body: 'The payer says this is paid. Foxy is asking your mint.',
      code: s.tapShownCode || '',
      button: 'CLOSE',
      go: () => {},
    });
    clearTimeout(this._tapPaidNoteT);
    this._tapPaidNoteT = setTimeout(() => {
      if (!this._tapPaidNote) return;          // the mint agreed, and the screen moved on
      this._tapPaidNote = 0;
      if (this.hideStage) this.hideStage('paidCheck');
      console.log('[foxy] tap: the mint has not seen that payment after 20s; the invoice is still open');
      this.toast('Your mint has not seen that payment yet. The invoice is still open.', true);
      this.syncTap();
    }, 20200);
  }

  /* A tap that produced no payment, so the next one may be heard.
   *
   * `_tapGot` and `_tapKeep` exist to stop `syncTap` searching again under a
   * link the payment is about to cross. When there is no payment there is no
   * link to protect, and holding them is just deafness. */
  tapGaveNothing(why) {
    this._pricedFor = null;      // the next tap agrees its own price
    this._crossReady = null;     // and asks its own crossing
    if (!this._tapGot && !this._tapKeep) return;
    console.log('[foxy] tap: letting that one go \u2014 ' + (why || 'nothing came of it'));
    this._tapGot = false;
    this._tapKeep = false;
    this._tapAway = false;
    this._tapGotAt = 0;
    this.syncTap();
  }

  /* Is this phone still owed change over a link it must not let go of?
   *
   * An offline payer with no exact pieces over-pays, and the receiver hands the
   * difference back over the same link — but it has to swap at the mint to make
   * it, and that takes seconds. The payer was finishing first: the payment
   * went, the person was back on home 1.6 seconds later, the link went with
   * them, and the receiver's change was ready a second after that and had
   * nowhere to go. One second.
   *
   * Bounded, because a link held for ever is a radio held for ever. Thirty
   * seconds is a swap over a cold circuit with room to spare; past it the change
   * is on the receiver's token screen, which is where an undelivered one lives
   * anyway. */
  CHANGE_WAIT_MS = 30000;

  changeStillDue() {
    // the change is here, and the receiver is being told so: the link stays for that
    if (this._ackHold && Date.now() < this._ackHold) return true;
    if (!this._changeDueAt) return false;
    if (Date.now() < this._changeDueAt) return true;
    console.log('[foxy] tap: no change arrived within '
      + Math.round(this.CHANGE_WAIT_MS / 1000) + 's; letting the link go');
    this._changeDueAt = 0;
    /* The payment's entry said what it would cost once the change came back.
     * It did not, so the entry becomes what it really cost. */
    const W = window.FoxyWallet;
    if (this._changeForHash && W && W.changeSettled) {
      W.changeSettled(this._changeForHash, 0);
      this._changeForHash = '';
      this.loadHistory();
    }
    /* Said, not only written down. The diary had "no change came back" and
     * the person had nothing: they had been shown a payment that worked. */
    const owed = Math.round(Number(this._changeOwedSats) || 0);
    this._changeOwedSats = 0;
    this.refreshBalance();               // it was counted while it was awaited
    const money = owed > 0 && this.stageMoney ? this.stageMoney(owed) : '';
    this.waitingScreen('changeNeverCame', {
      title: 'You are<br>owed change', amount: money,
      body: (money ? 'You are due <strong>' + money + '</strong> in change.<br>' : '')
        + 'Please scan the QR code on the receiver\u2019s screen.',
      button: 'SCAN',
      go: () => this.setState(p => ({ screen: 'sendScan', stack: p.stack.concat([p.screen]), flow: 'send' })),
    });
    return false;
  }

  /* Told by the send when the receiver owes change back, and cleared when it
   * arrives (onTapChange) or the wait runs out. */
  expectChange(sats, hash) {
    if (!(Number(sats) > 0)) return;
    this._changeDueAt = Date.now() + this.CHANGE_WAIT_MS;
    this._changeForHash = hash || '';
    this._changeOwedSats = Number(sats) || 0;
    console.log('[foxy] tap: ' + this.group(sats)
      + ' sats of change are owed, so the link is held open for it');
    /* And looked at again when the wait runs out, in case nothing else redraws:
     * `syncTap` only runs on a render, and a phone sitting on home has none. */
    clearTimeout(this._changeWaitT);
    this._changeWaitT = setTimeout(() => this.syncTap(), this.CHANGE_WAIT_MS + 250);
  }

  changeArrived(sats) {
    if (!this._changeDueAt) return;
    this._changeDueAt = 0;
    this._changeOwedSats = 0;
    /* One transaction, with the change inside it: the payment's own entry is
     * finished rather than a second row appearing for money coming back. */
    const W = window.FoxyWallet;
    if (this._changeForHash && W && W.changeSettled) {
      W.changeSettled(this._changeForHash, Number(sats) || 0);
      this._changeForHash = '';
    }
    clearTimeout(this._changeWaitT);
    console.log('[foxy] tap: the change arrived, so the link may go');
    this.refreshBalance();
    this.syncTap();
  }

  /* TAP, on a receive screen. This is what puts the phone on the air.
   *
   * Pressed again after a payment it is a new receiver, with a new service
   * UUID and new keys — the bridge does that, because reusing the old one
   * would put the same number back on the air and hand the next customer a
   * conversation the last payer's keys belong to (FoxyBridge+Tap.swift).
   * Here that is just: clear what the last payer left on screen, and ask. */
  /* Whether the invoice screen arms itself. On unless the person turned it
   * off (MENU > TAP ON PRESS); the press and the shake work either way. */
  tapAutoArms() {
    try { return localStorage.getItem('foxy.tap.auto') !== 'off'; } catch (e) { return true; }
  }

  tapAutoSet(on) {
    try { localStorage.setItem('foxy.tap.auto', on ? 'on' : 'off'); } catch (e) {}
    console.log('[foxy] tap: the invoice screen ' + (on ? 'arms itself' : 'arms on a press only'));
    if (!on && this.state.tapArmed && !this.state.tapShownCode) this.setState({ tapArmed: false });
    this.forceUpdate();
  }

  /* The X on the code card: that phone is let go, and this one goes back on
   * the air.
   *
   * It only hid the card. The handshake is open to anything in radio range
   * that speaks it (TAP-TO-PAY.md, "What it gives away"), and a phone that
   * links and then says nothing holds this receiver for as long as it likes:
   * one payer at a time, and the code card over the QR. A clock would drop a
   * real payer who is still reading their screen, so it is the person's call
   * instead — a code up and nobody paying is something they can see, and this
   * is the one press that answers it. If it keeps
   * happening, Bluetooth off, or AUTO TAP TO PAY off, ends it.
   *
   * Not while a payment or a price is in the middle of crossing: then X only
   * puts the card away, as it always did, and the link is left alone. */
  /* The receiver's CONNECT TO PAY card is up exactly when a payer has said it
   * is near AND this screen has a code for it to cover. Asked on every pass,
   * so it arrives with the invoice screen and leaves with it. */
  syncConnectRecv() {
    const s = this.state;
    const onCode = (s.screen === 'confirm' && s.flow === 'receive') || s.screen === 'spPayer';
    if (this._nearEdge && onCode && !s.tapShownCode && s.tapRecvStage !== 'connecting' && this.tapOffering()) {
      this.showConnectRecv(this._nearEdge);
    } else {
      this.hideConnectRecv();
    }
  }

  tapDropPayer() {
    const s = this.state;
    const W = window.FoxyWallet;
    const midway = !!this._tapTalking || !!this._tapPaidHere || s.tapRecvStage === 'connecting';
    if (!s.tapShownCode || midway || !W || !W.tapReceiveStop) {
      this.setState({ tapCardOff: true });
      return;
    }
    console.log('[foxy] tap: X on the code; that phone is let go and this one goes back on the air');
    this._tapOffer = null;
    W.tapReceiveStop();
    // `syncTap` arms the screen afresh (a new number, new keys) where it arms itself
    this.setState({ tapShownCode: '', tapArmed: false, tapRecvStage: '', tapCardOff: true, tapAutoFresh: false });
    this.toast('That phone was let go.');
  }

  tapArm() {
    /* With the radio off there is nothing to arm: the button is greyed and
     * says why. */
    if (['off', 'denied', 'unsupported'].indexOf(this.state.tapRecvStage) >= 0) {
      /* Refused once, iOS never asks again: the only way back is Foxy's own
       * page in Settings, and the button takes them there. */
      if (this.state.tapRecvStage === 'denied') {
        const W = window.FoxyWallet;
        this.blockedCard('bluetoothDenied', {
          tone: 'warn',
          title: 'BLUETOOTH NOT ALLOWED',
          reason: 'Tap to pay needs Bluetooth, and Foxy was not allowed to use it. Turn it on for Foxy in Settings.',
          retry: 'OPEN SETTINGS',
          go: () => { if (W && W.openSettings) W.openSettings(); },
        });
        return;
      }
      this.toast('Enable Bluetooth to use tap to pay.', true);
      return;
    }
    if (!this.tapOffering()) { this.toast('This cannot be paid by tap.', true); return; }
    const s = this.state;
    /* Pressed while the card is up, it is the card's X.
     *
     * The card covers the QR — TAP HERE, then the four digits — and the only
     * way to get the code back used to be a small X in its corner that nobody
     * found. The button that raised it puts it away. It
     * does not go off the air: that is the screen's doing, and after a payment
     * this phone has already stopped advertising by itself. */
    if (s.tapShownCode || (s.tapArmed && !s.tapCardOff)) {
      console.log('[foxy] tap: TAP pressed; the card goes away, the phone stays on the air');
      this.setState({ tapCardOff: true });
      return;
    }
    /* Armed by the screen, no code yet: the press brings the TAP HERE card up,
     * which is the one thing the screen does not do by itself. */
    if (s.tapArmed && s.tapCardOff && s.tapAutoFresh && s.tapRecvStage !== 'connecting') {
      console.log('[foxy] tap: TAP pressed; showing the card over the code');
      this.setState({ tapCardOff: false, tapAutoFresh: false });
      return;
    }
    /* Not while a payer is on the way in.
     *
     * Pressing TAP again is a NEW receiver: a new service UUID and new keys,
     * because reusing the old one would hand the next customer a conversation
     * the last payer's keys belong to. That is right after a payment and wrong
     * in the middle of one — and the two were indistinguishable here.
     *
     * What the person does is press TAP, see the prompt, press again when
     * nothing has happened yet (which only put the prompt away), and press a
     * third time — and that third press tore the radio down and put a
     * different number on the air while a payer was part way through its
     * handshake. So the payer found nothing where it had just been talking and
     * had to start over, which is the tapping-several-times this is named for. The press still brings the prompt back; it just does
     * not throw away the conversation it is waiting for.
     */
    if (s.tapRecvStage === 'connecting') {
      console.log('[foxy] tap: TAP pressed while a payer is connecting; keeping that link');
      this.setState({ tapCardOff: false });
      return;
    }
    console.log('[foxy] tap: TAP pressed; going on the air'
      + (s.tapArmed ? ' again, with a new number and new keys' : ''));
    this._tapOffer = null;
    this.haptic('tap');
    this.setState({ tapArmed: true, tapShownCode: '', tapCardOff: false, tapRecvStage: '' });
  }

  /* Shake to tap, armed for exactly as long as the receive invoice screen
   * has something a payer could pay, and synced from the same place the
   * screen is kept awake (TAP-TO-PAY.md). iOS recognises the shake; a
   * shake then presses TAP. Nothing goes over the air for it: it is a press. */
  syncShake() {
    const W = window.FoxyWallet;
    if (!W || !W.shakeSense) return;
    const s = this.state;
    const want = s.screen === 'confirm' && s.flow === 'receive' && !!this.tapOffering();
    if (want === !!this._shaking) return;
    this._shaking = want;
    W.shakeSense(want);
  }

  /* Screens somebody looks at without touching, so iOS must not dim them.
   *
   * A receive screen is held up for another phone to read or scan, and the
   * payer's tap screen is held next to it — neither gets a touch for as long
   * as it is doing its job, and the phone was locking part way through. The gate asks for itself (foxy-tor-gate.js): its
   * screen is up before this one exists. */
  /* The invoice screen the right way up for the person across the table.
   *
   * A receiver lays the phone down with its top towards the payer, and the
   * code and the amount were upside down to the one person who needed to
   * read them. The app stays in portrait as far as iOS is
   * concerned — every iPhone since the X refuses to rotate an app upside
   * down — and the page turns itself round instead, on the one screen where
   * it is wanted. Everything on it, the overlays included, goes with it. */
  syncFlip() {
    const s = this.state;
    /* Off: a phone lying top-down made the tap less
     * reliable — the marks and the edges to bring together stopped agreeing.
     * The screen stays as it is whichever way up the phone lies; the code
     * below is kept for when it comes back. */
    const FLIP = false;
    const want = FLIP && !!s.upsideDown && s.screen === 'confirm' && s.flow === 'receive';
    if (want === !!this._flipOn) return;
    this._flipOn = want;
    try {
      const root = document.documentElement;
      root.style.transform = want ? 'rotate(180deg)' : '';
      root.style.transformOrigin = want ? '50% 50%' : '';
      // the card is drawn for the way up the page is: again, now that it has turned
      if (this.hideConnectRecv) this.hideConnectRecv();
      if (this.syncConnectRecv) this.syncConnectRecv();
      console.log('[foxy] the invoice screen is ' + (want ? 'turned round for the phone lying top-down' : 'the right way up again'));
    } catch (e) {}
  }

  syncAwake() {
    const W = window.FoxyWallet;
    if (!W || !W.keepAwake) return;
    const s = this.state;
    /* And while a payment is actually going out.
     *
     * `sendPhase === 'in'` is money on the wire — a swap at the mint, then a
     * delivery over Bluetooth, an onion or a relay, and the delivery can take
     * tens of seconds if the first route fails. The screen was not held for
     * any of it, so iOS locked the phone part way through, and locking runs
     * `appEnteredBackground` → `TorService.backgrounded`, which zeroes the
     * SOCKS port: the next attempt came back `noTor` and the payment fell to
     * the token screen for no reason but the lock. Released as soon as the
     * phase ends, like every other. */
    /* And while a tap is being talked about.
     *
     * `priceConfirm` and `crossConfirm` are a person reading figures with a
     * payer holding a Bluetooth link open on the other side of the table. The
     * screen was allowed to sleep through exactly that — "screen kept awake:
     * no" at the moment the price screen came up — and a phone that locks takes
     * the link down with it, which is a second, independent way for the answer
     * to reach nobody.
     *
     * The link's own clocks are what end it: 90 seconds once a person is being
     * asked, 95 before the payer gives up. The screen has to outlast those. */
    const talking = !!this._tapTalking;
    const want = (s.screen === 'confirm' && s.flow === 'receive') || /^sp/.test(String(s.screen || ''))
      || talking || s.sendPhase === 'in';
    if (want === !!this._awake) return;
    this._awake = want;
    W.keepAwake(want);
  }

  /* Ecash that arrived and was never swapped in, swapped before it is needed.
   *
   * A payment locked to this phone counts in the balance the moment it lands,
   * because it is already this phone's money. The swap that puts it in the
   * pile can still fail — the mint unreachable, a write refused — and it then
   * waits on the unclaimed list. That is fine until somebody is paid and
   * spends it straight away: the balance counts it, the proofs are not in the
   * pile, and the send is refused for money the screen says is there.
   *
   * Every screen money can leave from, not only the confirmations — a token is
   * generated straight from SET AMOUNT with nothing in between. Done from the
   * screen rather than inside sendToken, where it belongs on paper: a claim is
   * itself a swap, and starting one from inside a send re-enters the wallet's
   * own swap machinery and hangs. Cheap to call: it returns at once when there
   * is nothing waiting, which is almost always. */
  syncClaim() {
    const W = window.FoxyWallet;
    if (!W || !W.claimUnclaimed) return;
    const s = this.state;
    const at = s.screen;
    const spending = CONFIRM_SCREENS.indexOf(at) >= 0
      || (at === 'amount' && s.flow === 'send')
      || at === 'sendHow';
    if (!spending) { this._claimedAt = null; return; }
    if (this._claimedAt === at) return;
    this._claimedAt = at;
    W.claimUnclaimed().catch(() => {});
  }

  /* A waiting screen, or the card it replaced where there is no screen to
   * draw (the suites lift these methods without the loaders). The diary line
   * is the card's own, so a log reads as it did. */
  waitingScreen(kind, o) {
    if (this.hideConnecting) this.hideConnecting();
    if (!this.stageScreen) { this.blockedCard(kind, { tone: 'ask', title: String(o.title).replace(/<br>/g, ' ').toUpperCase(), reason: o.body }); return; }
    console.log('[foxy] blocked: ' + kind + ' \u2014 ' + String(o.body || '').replace(/<[^>]+>/g, ' '));
    this.stageScreen(kind, o);
  }

  /* The receiver, with a payer linked and nothing to do but wait for them.
   *
   * The link is made, the offer has gone and the four digits are up; what
   * happens next happens on the other phone. `offline` is the payer saying it
   * has no route and is being asked to agree this phone's bitcoin price. */
  waitingForPayer(offline) {
    /* Only the price check. A payer who is simply deciding whether to press
     * SEND is waited for on the invoice screen, with the four digits, as it
     * always was. */
    if (!offline) { if (this.hideStage) this.hideStage('waitPayer'); return; }
    if (!this._tapOffer && !this.state.tapArmed) return;
    this.waitingScreen('waitPayer', {
      art: 'phone', title: 'Waiting<br>for payer', dots: true, forMs: 95000,
      body: 'This payer is offline and must agree to the current Bitcoin price before continuing.',
      code: this.state.tapShownCode || '',
      button: 'CANCEL',
      go: () => this.setState({ tapArmed: false, tapRecvStage: '' }),
    });
  }

  /* What the native side says as either side goes. */
  /* RECEIVING ECASH, with a percentage, while a large payment is still
   * arriving. Put up once and written to after that; taken down if nothing
   * more is heard for twenty seconds, which is a payer that went. The
   * payment landing puts up the ordinary receiving screen in its place. */
  tapReceiving(pct) {
    if (!this._recvProg || !document.getElementById('foxy-melt')) {
      this._recvProg = true;
      this.showMelt('Receiving ecash\u2026');
    }
    const h = document.querySelector('#foxy-melt h1');
    if (h) h.innerHTML = 'Receiving ecash<br>' + Math.max(0, Math.min(99, Math.round(pct))) + '%';
    clearTimeout(this._recvProgT);
    this._recvProgT = setTimeout(() => {
      if (!this._recvProg) return;
      this._recvProg = false;
      this.hideMelt();
    }, 20000);
  }

  tapHeard(ev) {
    /* How far a large payment has got across the link. Said by both radios
     * for anything that will take more than a moment, and shown where the
     * person is already looking: the payer's SENDING, and on the receiver a
     * RECEIVING ECASH screen over the code. */
    if (ev.side === 'pay' && ev.stage === 'sending') {
      if (this.state.sendPct !== ev.pct) this.setState({ sendPct: Number(ev.pct) || 0 });
      return;
    }
    if (ev.side === 'receive' && ev.stage === 'receiving') {
      this.tapReceiving(Number(ev.pct) || 0);
      return;
    }
    /* The other phone speaks another version of the tap, so the two cannot
     * talk (TAP-TO-PAY.md, *Versions*). Said, on whichever side can know it:
     * a tap that just does nothing is the one outcome the version was added
     * to prevent. */
    if (ev.stage === 'version') {
      this.tapVersionCard(ev.side);
      return;
    }
    /* Shaken: the button is pressed, with every rule the button has. Only on
     * a receive screen with an offer, and only when not already on the air —
     * a shake never puts the code card away and never touches a payer that
     * is connecting; `tapArm` keeps both (TAP-TO-PAY.md). */
    if (ev.side === 'receive' && ev.stage === 'shake') {
      const s = this.state;
      const onScreen = s.screen === 'confirm' && s.flow === 'receive' && !!this.tapOffering();
      if (!onScreen || s.tapArmed || s.tapShownCode || s.tapRecvStage === 'connecting') {
        console.log('[foxy] tap: shake ignored \u2014 '
          + (!onScreen ? 'not on a receive screen with an offer' : 'already on the air'));
        return;
      }
      console.log('[foxy] tap: shaken; pressing TAP');
      this.tapArm();
      return;
    }
    if (ev.side === 'receive' && ev.stage === 'code' && this._tapOffer) {
      /* Armed stays true, and it is not about the radio.
       *
       * It was cleared here for a few minutes, on the reasoning that the radio
       * stops at the subscribe so the button should go plain. That reasoning
       * was about the wrong thing: `tapArmed` is what `syncTap` reads to decide
       * whether this screen wants a receiver at all, so clearing it tore the
       * receiver down the instant the code appeared — ten seconds before the
       * payer even tried to send, and long before `busy` could protect it. The
       * payment went into a link that was no longer there, `tapSend` timed out,
       * and it fell back to the onion.
       *
       * So it means "this screen has a tap going", from the press until the
       * payment is done or the screen goes. The accent says the same. */
      this.hideConnecting();          // the code is the link being made
      /* A payer has the offer. If it pays the invoice rather than the
       * request, nothing comes back over this link, so the mint is asked
       * every second for the next minute instead of every ten. */
      if (this.tapWatchClosely) this.tapWatchClosely(60000);
      this.setState({ tapShownCode: ev.code || '', tapCardOff: false });
      if (this._buzzRecv) this.tapBuzz(false);
      this.haptic('success');
      return;
    }
    /* The payer left with the link made and nothing answered. If they had
     * pressed SEND, their phone is now showing the payment as a code and the
     * way to finish is to scan it; if they had not, there is nothing to scan
     * and NOT NOW says so. This phone cannot tell which, so it offers both. */
    if (ev.side === 'receive' && ev.stage === 'gone') {
      // it may have paid the invoice and left: asked quickly for a while longer
      if (this.tapWatchClosely) this.tapWatchClosely(30000);
      if (this._buzzRecv) this.tapBuzz(false);
      const was = this.stageUp && this.stageUp('waitPayer');
      const talking = !!this._tapTalking;
      if (this.hideStage) this.hideStage('waitPayer');
      /* The conversation is over: the other phone has gone. The hold was left
       * set, so TAP did nothing for ninety seconds and this phone would not
       * listen as a payer either, until the app was put in the background and
       * brought back. The code and the arming go with it, so the next TAP is
       * a fresh receiver. */
      this.tapTalking(false);
      this.setState({ tapShownCode: '', tapArmed: false, tapRecvStage: '' });
      // they said why before leaving: nothing to scan, and the person has been told
      if (this._payerGaveUp) { this._payerGaveUp = false; return; }
      if ((was || talking) && this.stageScreen && !this.stageUp('changeStuck')) {
        console.log('[foxy] tap: the payer left before anything arrived; offering to scan');
        this.stageScreen('youScan', {
          title: 'You need<br>to scan',
          body: 'Scan the QR code on the payer\u2019s screen.',
          button: 'SCAN',
          go: () => { if (this.scanTokenToReceive) this.scanTokenToReceive(); },
          alt: 'NOT NOW',
        });
      }
      return;
    }
    /* A payer has said it is near, or has gone again (the third door). The
     * invoice screen shows CONNECT TO PAY where the QR is; the handshake
     * starting, or the code arriving, takes it down. */
    /* Remembered, not only drawn: a payer may say it is near while this phone
     * is still on the amount screen, where there is no code to cover, and the
     * card has to be there when the invoice screen arrives (syncConnectRecv). */
    if (ev.side === 'receive' && ev.stage === 'nearby') {
      // not for a payer that has just said it paid: the mint is being asked
      if (this.tapPaidChecking && this.tapPaidChecking()) return;
      clearTimeout(this._nearGoneT);
      this._nearEdge = ev.edge === 'left' ? 'left' : 'right';
      this.syncConnectRecv();
      return;
    }
    /* Gone, but not at once: a payer that drops its quiet link and opens
     * another is "far" for about a second, and the card went with it. It
     * waits two and a half seconds for the payer to come back first. */
    if (ev.side === 'receive' && ev.stage === 'far') {
      clearTimeout(this._nearGoneT);
      this._nearGoneT = setTimeout(() => { this._nearEdge = ''; this.hideConnectRecv(); }, 2500);
      return;
    }
    if (ev.side === 'receive' && (ev.stage === 'connecting' || ev.stage === 'code' || ev.stage === 'gone')) this.hideConnectRecv();
    if (ev.side === 'receive' && (ev.stage === 'off' || ev.stage === 'denied')) {
      this.setState({ tapRecvStage: ev.stage });
      return;
    }
    /* A payer has been picked and is being connected to. The code is a second
     * or two behind it, and until this the invoice screen showed nothing at
     * all while somebody held their phone against it. */
    if (ev.side === 'receive' && ev.stage === 'connecting' && this._tapOffer) {
      if (this.state.tapRecvStage !== 'connecting') {
        this.haptic('tap');
        // and the knock the payer's phone is making, for as long as it makes it
        if (!this._tapPaying) this.tapBuzz(true, true);
      }
      /* No screen for it here. The receiver's was up for an instant — the
       * code follows the subscribe by a tenth of a second — and a screen that
       * flashes is worse than none. The knock says contact
       * was made, and the four digits are what there is to look at. */
      this.setState({ tapRecvStage: 'connecting' });
      return;
    }
    // that one came to nothing; back to waiting for a payer
    if (ev.side === 'receive' && ev.stage === 'searching') {
      if (this._buzzRecv) this.tapBuzz(false);
      /* `off` too: the radio was switched back on and the receiver went on
       * the air by itself, so the button comes back with it. */
      if (this.state.tapRecvStage === 'connecting' || this.state.tapRecvStage === 'off') this.setState({ tapRecvStage: '' });
      if (this.hideStage) this.hideStage('waitPayer');
      return;
    }
    if (ev.side === 'pay' && this._tapPaying) {
      /* Contact made is contact made: it does not go back to SEARCHING.
       *
       * The native side drops a connection it could not finish and scans
       * again, which is right — but it was showing every step of that as a
       * new state, so holding the phones together read as HOLD CLOSER,
       * CONNECTING, SEARCHING, HOLD CLOSER, and then the confirmation anyway. Nothing about that flicker is useful to the
       * person holding the phone: they are already doing the one thing there
       * is to do. So once this says connecting, it keeps saying connecting.
       *
       * Unlatched after a while, because a phone that never connects must
       * eventually be allowed to say so rather than pretending for ever. */
      /* Nor may a later SEARCHING paper over it: the radio being off is the
       * answer until the radio says otherwise. */
      const settled = ['off', 'denied', 'unsupported'];
      if (settled.indexOf(this.state.tapStage) >= 0 && ev.stage === 'searching') return;
      const held = this.state.tapStage === 'connecting' || this.state.tapStage === 'linked';
      const goingBack = ev.stage === 'searching' || ev.stage === 'far' || ev.stage === 'nearby';
      if (held && goingBack && Date.now() < (this._tapHeldUntil || 0)) return;
      /* A receiver is near — within -60 dBm — but not touching. The payer's
       * screen says TAP TO PAY, tall, from the top edge down to the balance
       * pill, so the person knows to put the phones together. Only while listening from home or SEND, and it comes down
       * the moment the link is made, the receiver fades, or the screen moves. */
      if (ev.stage === 'nearby') {
        if (this._tapPaying && !held) this.showTapNearby(ev.edge);
        return;
      }
      if (ev.stage === 'far' || ev.stage === 'searching') this.hideTapNearby();
      /* The phone it was connecting to went away (the doors went, or the
       * link died). CONNECTING TO INVOICE stayed up through the twelve-second
       * hold meant for far/searching flicker, and CANCEL was the only way
       * off it. */
      if (ev.stage === 'gone') {
        this._tapHeldUntil = 0;
        this.tapBuzz(false);
        this.hideConnecting();
        return;
      }
      if (ev.stage === 'connecting') {
        this.hideTapNearby();
        this._tapHeldUntil = Date.now() + 12000;
        /* Contact, felt rather than shown. The payer is on home or on SEND and
         * there is no tap screen to change; what says something happened is
         * the phone in the hand, and then the confirmation a moment later. */
        if (!this._tapPaying) return;
        this.tapBuzz(true);
        this.haptic('tap');
        /* And something to look at. The buzz was the whole of what the payer
         * got — no screen changes at this point, because the phone is on home
         * or on SEND — so the seconds between contact and the confirmation
         * were a phone that had vibrated and done nothing.
         * Cancelling here costs nothing: the link is a handshake and no ecash
         * has been touched. */
        /* CANCEL lets the link go, and stays gone. It only hid the screen and
         * went back: the link stayed up, the next `connecting` event put the
         * screen straight back, and the person pressed a button that did
         * nothing. The payer is stopped —
         * `tapPay` rejects, and `syncTap` listens again from home — and for
         * a few seconds this link's events draw nothing. */
        if (Date.now() < (this._tapCancelUntil || 0)) return;
        this.showConnecting(() => {
          console.log('[foxy] tap: CANCEL on connecting; letting that link go');
          this._tapCancelUntil = Date.now() + 8000;
          this.tapBuzz(false);
          const W0 = window.FoxyWallet;
          if (W0 && W0.tapPayStop) W0.tapPayStop();
          this.back();
        });
        /* Contact that comes to nothing is let go of quietly.
         *
         * There is no screen to be stranded on any more, so this no longer
         * navigates — it stops the knocking and leaves a note. The listen
         * itself carries on: the phone is still on home, and the next merchant
         * to press TAP should still be heard. */
        clearTimeout(this._tapStranded);
        this._tapStranded = setTimeout(() => {
          if (this._tapGot) return;
          console.warn('[foxy] tap: connected but nothing came of it');
          this.tapBuzz(false);
          this._tapHeldUntil = 0;
          this.hideConnecting();
        }, 15000);
      }
      if (goingBack) this.tapBuzz(false);   // 'linked' keeps knocking: the screen has not changed yet
      this.setState({ tapStage: ev.stage });
    }
  }

  /* A knock every second while the two phones are talking, until the payer is
   * looking at the confirmation.
   *
   * The person is holding one phone against another and can see neither screen
   * properly, so the phone in their hand is the only thing that can say "still
   * working, keep it there". One buzz at the start said it once and then left
   * them guessing; this keeps saying it, and stops the moment there is
   * something to look at.
   *
   * Straight to the bridge rather than through `haptic`, which allows one buzz
   * of a kind every 1.2 seconds — right for events, wrong for a heartbeat.
   * Capped, so a tap that never finishes does not knock for ever. */
  /* Both phones, and together. The receiver knocks the
   * same way for the same seconds — `recv` — and the knocks fall on the
   * second by the clock rather than a second after each phone happened to
   * start, so two phones whose clocks agree knock in step with nothing passed
   * between them. The first is felt at once, because contact should be. */
  tapBuzz(on, recv) {
    if (this._buzz) { clearInterval(this._buzz); this._buzz = null; }
    if (this._buzzStart) { clearTimeout(this._buzzStart); this._buzzStart = null; }
    this._buzzRecv = false;
    if (!on) return;
    this._buzzRecv = !!recv;
    const bridge = (window.webkit || {}).messageHandlers;
    const one = () => {
      if (bridge && bridge.foxy) { try { bridge.foxy.postMessage({ haptic: 'pulse' }); return; } catch (e) {} }
      if (navigator.vibrate) navigator.vibrate(100);
    };
    one();
    const until = Date.now() + 30000;
    const alive = () => Date.now() <= until && (recv ? this._buzzRecv : !!this._tapPaying);
    const beat = () => { if (!alive()) { this.tapBuzz(false); return; } one(); };
    // to the next whole second, or the one after where that is too soon to feel as a second knock
    let wait = 1000 - (Date.now() % 1000);
    if (wait < 350) wait += 1000;
    this._buzzStart = setTimeout(() => {
      this._buzzStart = null;
      beat();
      if (alive()) this._buzz = setInterval(beat, 1000);
    }, wait);
  }

  tapStartPay() {
    const W = window.FoxyWallet;
    const run = {};
    this._tapPaying = run;
    this._tapSearchAt = Date.now();
    /* SEARCHING is a guess, and it must not overwrite an answer.
     *
     * The native side reports a Bluetooth that is off or not allowed as soon
     * as its manager wakes, which can be before this optimistic setState
     * lands — and then the screen said SEARCHING for ever while the radio was
     * switched off, telling somebody to hold their phone nearer when the
     * problem was Bluetooth. A stage that says why nothing
     * can happen stays. */
    this.setState(p => ({
      tapStage: ['off', 'denied', 'unsupported'].indexOf(p.tapStage) >= 0 ? p.tapStage : 'searching',
      nfcLinked: false, tapLinkCode: '',
    }));
    // still started, so the radio coming back on is noticed and reported
    W.tapPay().then(got => {
      if (this._tapPaying !== run) return;
      this._tapPaying = null;
      this.hideTapNearby();
      const offer = this.tapOfferOf(got.payload);
      if (!offer) {
        this.toast('That phone sent something Foxy could not read.', true);
        this.back();
        this.tapGaveNothing('their offer could not be read');
        return;
      }
      /* Already paid, by this phone, a moment ago.
       *
       * A payment over Lightning crosses no link, so the receiver learns of
       * it from its mint and is still on its invoice screen, on the air,
       * for as long as that takes. The payer got home, heard it again and
       * was offered the same invoice a second time. Said, and not paid again;
       * the other phone is told once
       * more, since its screen is what has not caught up. */
      const paidAt = this.tapWasPaid ? this.tapWasPaid(offer) : 0;
      if (paidAt) {
        console.log('[foxy] tap: that offer was paid from this phone ' + Math.round((Date.now() - paidAt) / 1000) + 's ago; not paying it again');
        if (offer.inv) this.tapSayPaid(offer.inv);
        this.hideConnecting();
        // long enough for their mint to tell them, so this is not said every few seconds
        this._tapQuietUntil = Date.now() + 15000;
        // and the link is let go once the word has had time to cross it
        setTimeout(() => { if (!this._tapPaying && !this._tapGot && W.tapPayStop) W.tapPayStop(); }, 1500);
        this.blockedCard('alreadyPaid', {
          tone: 'ask',
          title: 'ALREADY PAID',
          reason: 'You paid this ' + this.tapAgoWords(paidAt) + '. Their phone has not shown it yet.',
          chip: 'Nothing was sent again.',
        });
        return;
      }
      this._tapOfferNow = offer;           // what a payment that follows is paying (tapMarkPaid)
      this._tapGot = true;                 // do not go looking again: the link is the payment's
      this._tapKeep = true;
      this._tapGotAt = Date.now();         // and when, so a tap that goes nowhere can be let go
      clearTimeout(this._tapStranded);
      this.haptic('success');
      /* CONNECTING TO INVOICE stays up until there is something to put in its
       * place. It was taken down here, a beat before the confirmation opened,
       * so what the payer saw between the two was the home screen — for most
       * of a second, in the middle of paying somebody. It
       * comes down below, once the next screen is on. */
      this.setState({ nfcLinked: true, tapLinkCode: got.code, tapStage: 'linked' });
      /* A beat, then the confirmation opens itself.
       *
       * There is no tap screen to be on any more: this phone was listening
       * from home or from SEND, and what it heard is a merchant who pressed
       * TAP while the two phones were touching. The beat is so the haptic
       * lands before the screen moves, not a wait for anything.
       *
       * It still refuses to barge in on a payment already going out — the
       * listen is not running then (`syncTap`), and this checks again because
       * the offer can arrive in the same tick the person starts one. */
      setTimeout(() => {
        /* `'in'`, not any phase.
         *
         * This is meant to stop a second payment opening itself over one
         * already going out. Written as a truthiness test it also caught
         * `'settled'`, which is what every *finished* send leaves behind — so
         * the tap after the first payment of a launch buzzed, connected, and
         * then silently returned here rather than opening the confirmation.
         * The receiver's side was working perfectly, which is why it looked
         * like a payer bug and was.
         *
         * Same mistake as the listening gate above, in the same afternoon. A
         * phase that has ended is not a payment in flight. */
        const now = this.state;
        if (now.sendPhase === 'in' || now.reqBusy) {
          /* This tap is over and nothing came of it, so the marks that stop the
           * next one have to come off here.
           *
           * They are released by going away from home and coming back, which is
           * how a finished payment announces itself. A tap abandoned right here
           * never goes anywhere: the phone stays on home with `_tapGot` set, and
           * `syncTap` will not listen again for the life of the app — which is
           * a payer that cannot tap until they visit SEND and come back. */
          this.hideConnecting();
          this.tapGaveNothing('a payment was already going out');
          return;
        }
        /* Down once the screen under it has changed: a render is a frame
         * away, and taking this off first is the flash of home again. */
        setTimeout(() => this.hideConnecting(), 140);
        this.setState({ tapInvoice: offer.inv || '', tapCode: got.code });
        /* Same mint: pay with ecash and never mention Lightning.
         *
         * Paying a Lightning invoice made by the mint this phone pays from
         * shows that mint both sides of the payment, and costs a routing fee
         * to go out and come back to itself. The request goes straight to the
         * receiver's onion instead. The card that used to ask which way — USE
         * CASHU or CONTINUE OVER LIGHTNING — is for a stranger's invoice that
         * happens to share a mint; two Foxys held together are not that, and
         * the person should not be asked a question with one right answer. */
        /* They asked in dollars, so nothing is paid until they agree the
         * price. This phone has a current one; theirs may be hours old. It
         * says what its price is and what that makes of the amount, and waits
         * for the request to come back in sats (M10, M11). The sats never
         * leave here until that answer arrives. */
        /* The amount first, then the mint.
         *
         * They asked in dollars, so nothing is paid until they agree the price.
         * The mint question is answered after that and not before: a routing
         * fee cannot be quoted for an amount neither side has agreed to. */
        /* Across two mints, both phones online — or nothing (`tapOfflineCross`).
         * Before the price, because there is no price to agree for a payment
         * that is not going to be made. */
        if (this.tapOfflineCross && this.tapOfflineCross(offer)) return;
        if (offer.asksUsd) { this.tapQuoteTheirDollars(offer); return; }
        this.tapPayOffer(offer);
      }, 900);
    }, e => {
      if (this._tapPaying !== run) return;
      this._tapPaying = null;
      this.hideTapNearby();
      console.warn('[foxy] tap: search ended:', e.message);
      /* And then start listening again, because nothing else will.
       *
       * `tapPayStart` is asked with a 30 minute budget and answers with an
       * error when it runs out, which is what a payer sitting on home through a
       * long background does. `syncTap` is the only thing that starts a listen
       * and it runs from componentDidUpdate — on a state change, never on a
       * clock — so after the budget expired the phone stopped hearing taps
       * until some unrelated update happened to come along. On one
       * phone one did, 16 seconds later, because the price poll ticked; on a
       * phone whose price sources are all timing out, there is no such
       * luck.
       *
       * The delay backs off when the search failed at once — Bluetooth off or
       * not allowed rejects immediately, and re-arming that every second would
       * be a hot loop — and resets as soon as one listen has run a while, so a
       * budget that expires after half an hour is always picked straight up. */
      const lasted = Date.now() - (this._tapSearchAt || 0);
      if (lasted >= 30000) this._tapReArm = 1000;
      else this._tapReArm = Math.min((this._tapReArm || 1000) * 2, 60000);
      clearTimeout(this._tapReArmTimer);
      this._tapReArmTimer = setTimeout(() => {
        this._tapReArmTimer = null;
        if (!this._tapPaying) this.syncTap();
      }, this._tapReArm);
    });
  }

  /* What the other phone offered, and whether ecash can pay it.
   *
   * `sameMint` is this wallet's own mint being named by their request — the
   * one case where a token can go straight there and Lightning is pure loss.
   * Anything else is paid by the invoice, exactly as before. */
  tapOfferOf(text) {
    const W = window.FoxyWallet;
    let o = null;
    try { o = JSON.parse(String(text || '')); } catch (e) { return null; }
    if (!o || o.v !== 2) return null;
    const inv = typeof o.inv === 'string' && W.classify(o.inv) === 'invoice' ? o.inv : '';
    const req = typeof o.req === 'string' ? o.req : '';
    if (!inv && !req) return null;
    let sameMint = false;
    let theirs = [];
    if (req && W.decodeRequest) {
      const r = W.decodeRequest(req);
      theirs = (r && r.mints) || [];
      const mine = String(W.mintUrl || '').replace(/\/+$/, '');
      sameMint = !!(mine && theirs.some(m => String(m).replace(/\/+$/, '') === mine));
    }
    /* A request naming dollars and no sats: theirs to name, ours to convert.
     *
     * Not tied to the mint. A receiver with no route asks in dollars whoever
     * they bank with, and the mint is a separate question answered after the
     * amount is — you cannot quote a routing fee for an amount nobody has
     * agreed yet. An offer with an invoice on it is not this: the invoice
     * carries its own sat figure and paying it is one payment, not two. */
    const req0 = (req && W.decodeRequest) ? W.decodeRequest(req) : null;
    const asksUsd = !!(!inv && W.asksInDollars && W.asksInDollars(req0));
    console.log('[foxy] tap: they offered ' + (inv ? 'an invoice' : 'no invoice')
      + (req ? ' and a request for ' + (theirs.join(' ') || '(no mint named)') : ' and no request')
      + '; mine is ' + (W.mintUrl || '?')
      + ' — paying by ' + (sameMint ? 'ecash'
          : this.offlineNow() ? 'neither: no route here, so their invoice is no use'
          : 'lightning'));
    /* A request at a mint this phone could move money to: one mint named, and
     * it is not this one. Nothing about whether it is worth doing — that is the
     * quote's answer, and the fee card's. */
    const crossable = !sameMint && theirs.length === 1 && !!String(theirs[0] || '').trim();
    /* Tri-state on purpose: true, false, and "they did not say". An older Foxy
     * says nothing, and nothing must not read as offline. */
    const theirRoute = typeof o.up === 'boolean' ? o.up : null;
    /* Their bitcoin price, if they had a current one. A phone with no route of
     * its own is trusting this figure, so it is carried through to the screens
     * rather than quietly used for arithmetic. */
    const theirRate = Number(o.rate) > 0 ? Math.round(Number(o.rate)) : 0;
    const theirRateAt = Number(o.at) > 0 ? Math.round(Number(o.at)) * 1000 : 0;
    return { inv: inv, req: req, sameMint: sameMint, asksUsd: asksUsd, read: req0,
             mints: theirs, crossable: crossable, theirRoute: theirRoute,
             // whether they answer a question before the payment (`askFirst`)
             asks: o.ask === 1,
             theirRate: theirRate, theirRateAt: theirRateAt };
  }

  /* Between two mints, both phones must be online.
   *
   * Two ways round it existed. A payer with no route asked the receiver to
   * come to the payer's mint, take the ecash there and melt it home; a payer
   * with a route moved its sats to an offline receiver's mint and paid in
   * ecash there. Each is half a dozen questions of two mints over Tor while
   * two people hold their phones together, and each leaves money somewhere
   * nobody chose when a mint is slow: in testing, four tries to make one
   * payment, seven minutes to bring it home, and a card asking to bring it
   * home again for the rest of the session.
   *
   * So a tap across two mints is paid over Lightning by two phones that can
   * both reach their mints, and is otherwise refused here, before a price is
   * discussed or a fee is asked for. Both phones say why, in the same words:
   * this one on a card, theirs from the word sent on M10 (`tapPriceOffered`).
   *
   * `OFFLINE_CROSS` is the switch. The code for both ways is still below it
   * and still tested; turning this on is all it takes to have them back.
   *
   * "They did not say" is not offline: an older Foxy sends no `up`, and is
   * paid as before. Answers whether the tap was ended. */
  OFFLINE_CROSS = false;

  tapOfflineCross(offer) {
    const W = window.FoxyWallet;
    if (this.OFFLINE_CROSS || !offer || offer.sameMint) return false;
    const strip = (u) => String(u || '').replace(/\/+$/, '');
    const mine = strip(W.mintUrl);
    const theirs = strip((offer.mints || [])[0]);
    // a different mint is something their request says; with no mint named there is nothing to compare
    if (!mine || !theirs) return false;
    const meOff = this.offlineNow();
    const themOff = offer.theirRoute === false;
    if (!meOff && !themOff) return false;
    const name = (u) => this.mintNameOf(u) || strip(u).replace(/^https?:\/\//, '') || 'another mint';
    console.log('[foxy] tap: ' + (meOff && themOff ? 'neither phone has a' : meOff ? 'this phone has no' : 'their phone has no')
      + ' connection and the mints differ (' + mine + ' here, ' + theirs + ' there); not paid');
    /* Said to them, with this phone's mint, so their card can name both. The
     * words ride `gaveUp`, which an older Foxy shows as it stands. */
    const said = W.tapQuote ? W.tapQuote(JSON.stringify({
      gaveUp: 'Your payer uses a different mint. Both of you must be online to transact between mints.',
      why: 'offline-cross', mint: mine,
    })) : Promise.resolve();
    // the link is kept while the words leave: resolving means queued, not delivered
    said.catch(() => {}).then(() => setTimeout(() => this.tapGaveNothing('offline, and a different mint'), 1500));
    // and not heard again at once: they are very likely still on the air
    this._tapQuietUntil = Date.now() + 15000;
    this.hideConnecting();
    const held = W.balanceAt && W.balanceAt(theirs) > 0;
    this.blockedCard('offlineCross', {
      tone: 'warn',
      title: 'OFFLINE & DIFFERENT MINT',
      reason: 'Your receiver uses a different mint.\nBoth of you must be online to transact between mints.',
      chip: 'You use ' + name(mine) + ' while they use ' + name(theirs) + '.',
      // money already at their mint is a same-mint payment, one switch away
      retry: held ? 'CHOOSE A MINT' : '',
      go: held ? () => this.goSwitchMint() : null,
    });
    return true;
  }

  /* The receiver's half (M10 in, M11 out).
   *
   * This phone asked in dollars because it has no route and its own price may
   * be hours old. The payer has said what its price is and what that makes in
   * sats; a person here agrees to that number or does not, and only an ACCEPT
   * sends a request back — this time naming the sats, so the payment that
   * follows is the payment that was agreed.
   *
   * A DENY is sent, not left as silence: the payer is holding a link open and
   * "no" is something it can act on where a timeout is only a wait.
   */
  tapPriceOffered(text) {
    const W = window.FoxyWallet;
    /* Two things arrive on M10 and they are told apart by what is in them: a
     * price, or a mint the payer cannot leave. The first is a receiver with no
     * route being offered a conversion; the second is a payer with no route
     * asking this phone — which has one — to bring the money home. */
    let body = null;
    try { body = JSON.parse(String(text || '')); } catch (e) {}
    /* A third thing, and the smallest: the payer has no route and is reading
     * this phone's price. Nothing to answer; only something to say. */
    /* And the payer saying it cannot pay, before it goes. Without this the
     * receiver saw the payer leave and offered to scan a code the payer had
     * never made. */
    if (body && typeof body === 'object' && typeof body.gaveUp === 'string') {
      console.log('[foxy] tap: the payer could not pay \u2014 ' + body.gaveUp);
      this._payerGaveUp = true;
      this.waitingForPayer(false);
      this.tapTalking(false);
      // two mints and one of the phones offline: the same card the payer shows (`tapOfflineCross`)
      if (body.why === 'offline-cross') { this.offlineCrossCard(body.mint); return; }
      this.blockedCard('payerGaveUp', {
        tone: 'warn',
        title: 'THE PAYER COULD NOT PAY',
        reason: body.gaveUp.slice(0, 240),
      });
      return;
    }
    if (body && typeof body === 'object' && typeof body.deciding === 'boolean') {
      console.log(body.deciding
        ? '[foxy] tap: the payer is offline and is being asked to agree the price'
        : '[foxy] tap: the payer has answered about the price');
      this.waitingForPayer(body.deciding);
      if (this.OFFLINE_CROSS && body.deciding && body.ahead && body.ahead.mint) this.tapCarryAhead(body.ahead);
      return;
    }
    // anything else is a question for this phone, and its own screen
    if (this.hideStage) this.hideStage('waitPayer');
    if (body && typeof body === 'object' && body.mint && !(Number(body.rate) > 0)) {
      /* A payer with no route, at another mint, asking to have its sats
       * carried home. Not done any more (`tapOfflineCross`): a payer on this
       * build never asks, and one on an older build is told no, with the
       * reason, and both phones show it. */
      if (!this.OFFLINE_CROSS) {
        console.log('[foxy] tap: a payer with no connection asked to be carried from ' + body.mint + '; told that both must be online');
        if (W.tapTerms) {
          W.tapTerms(JSON.stringify({ no: true, why: 'Both of you must be online to transact between mints.' })).catch(() => {});
        }
        this._payerGaveUp = true;
        this.tapTalking(false);
        this.offlineCrossCard(body.mint);
        return;
      }
      this.tapCarryHome(body);
      return;
    }
    const q = W.readQuote ? W.readQuote(text) : null;
    if (!q) {
      console.warn('[foxy] tap: a price arrived that could not be read');
      if (W.tapTerms) W.tapTerms(JSON.stringify({ no: true })).catch(() => {});
      return;
    }
    console.log('[foxy] tap: they offer ' + q.sats + ' sats at $'
      + this.group(Math.round(q.theirRate)) + ' per bitcoin'
      + (q.differsPct == null ? '; this phone has no price to compare'
         : '; ' + q.differsPct.toFixed(1) + '% from the one this phone last saw'));
    /* From here until the answer has gone, this phone is in a conversation and
     * nothing may be torn down under it — not the radio, not the screen, not
     * the inbox. Set before the person is asked and cleared only once the
     * answer is actually on the wire (`syncTap`). */
    this.tapTalking(true);
    this.priceTermsCard(q).then(yes => {
      if (!yes) {
        console.log('[foxy] tap: the price was not accepted');
        /* This phone ended it, so the payer leaving is not news: without
         * this, the payer's going put YOU NEED TO SCAN over the screen after
         * the person had just said no. */
        this._payerGaveUp = true;
        const no = W.tapTerms ? W.tapTerms(JSON.stringify({ no: true })) : Promise.resolve();
        /* A refusal IS the end, but the write still has to leave before the
         * radio goes: `tapTerms` resolving means queued, not delivered. A
         * couple of seconds is more than the link needs and far less than the
         * clock that would otherwise hold it. */
        no.catch(() => {}).then(() => setTimeout(() => this.tapTalking(false), 2000));
        return;
      }
      /* The sats request is made now, not earlier: it is the agreed number, and
       * making it before the person agreed would be this phone doing the
       * conversion it has spent this whole leg refusing to do. `railRequest`
       * keeps it, so the QR on screen and this are the same request.
       *
       * Waited for, not read once. It answers '' for an amount it has not made
       * a request for yet — and the agreed sats are always a new amount, since
       * this screen asked in dollars — so reading it once sent the payer a
       * refusal for every ACCEPT. */
      this.railRequestReady(q.sats).then(req => {
          if (!req) {
          console.warn('[foxy] tap: the agreed request could not be made');
          const no = W.tapTerms ? W.tapTerms(JSON.stringify({ no: true })) : Promise.resolve();
          no.catch(() => {}).then(() => setTimeout(() => this.tapTalking(false), 2000));
          this.toast('Foxy could not make the request for that amount.', true);
          return;
        }
        console.log('[foxy] tap: the price was accepted; sending the request for ' + q.sats + ' sats');
        /* The hold STAYS. Sending the terms is not the end of the conversation,
         * it is the middle: the payment this phone just agreed to is what comes
         * next, over this same link.
         *
         * Released on the send, it was released four milliseconds after
         * `sendTerms` returned — and that return means the write is QUEUED, not
         * delivered. `syncTap` then found the screen back on home, retired the
         * receiver, and took the un-sent write with it. The answer was never
         * transmitted, and the payer sat there until it gave up (the answer
         * was sent, the hold freed four milliseconds later, and the payer gave
         * up a few seconds after).
         *
         * So the release belongs at the end of the conversation — the payment
         * arriving (`requestPaidHere`), the tap ending, or the clock. */
        W.tapTerms(JSON.stringify({ req: req, sats: q.sats })).catch((e) => {
          this.tapTalking(false);
          this.toast(W.reason ? W.reason(e) : 'That phone is no longer connected.', true);
        });
      });
    });
  }

  /* The amount is settled; now, how it is paid.
   *
   * Everything that has to happen before this — the price talk with a receiver
   * that asked in dollars — has happened, so `sats` is a number both phones
   * agree on and `offer.req` is the request that names it. From here it is one
   * question: can this phone's ecash answer that request, and if not, what else
   * is there.
   *
   * One place, because the price leg reaches it as well as the plain tap, and
   * having each work out the mint for itself is how the two ended up
   * disagreeing about which payments were possible.
   */
  tapPayOffer(offer, sats) {
    const W = window.FoxyWallet;
    /* Their price, where this phone has no current one of its own.
     *
     * A phone with no route is trusting the other one's bitcoin price for
     * every dollar figure it shows — so it should be showing THAT price, said
     * to be theirs, rather than converting at its own hours-old one and saying
     * nothing. Kept on state, never written into `_rate`:
     * this is a number somebody else vouched for, and the moment this phone has
     * a route again its own is the one that counts. */
    if (offer && offer.theirRate > 0 && this.offlineNow()) {
      this.setState({ peerRate: offer.theirRate, peerRateAt: offer.theirRateAt || Date.now() });
      console.log('[foxy] tap: they are online and their bitcoin price is $'
        + this.group(offer.theirRate) + '; showing theirs while this phone has none');
      /* And it is agreed, not merely displayed.
       *
       * Whoever has no route is trusting the other one's bitcoin price, and
       * that is a thing to say yes to rather than something to notice on a
       * confirmation screen. It is the same question the offline RECEIVER is
       * asked, from the other side ("offline user will
       * always confirm BTC PRICE difference").
       *
       * Once per tap: `_pricedFor` is the offer this phone has already agreed
       * a price for, so coming back through here — the mint question, a
       * crossing — does not ask again. */
      const want = Math.round(Number(sats) || Number(offer.read && offer.read.sats) || 0);
      if (want > 0 && this._pricedFor !== offer.req) {
        this._pricedFor = offer.req;
        this.tapAgreeTheirPrice(offer, want);
        return;
      }
    }
    /* An invoice is no use to a phone with no route.
     *
     * Every branch below was gated on `!offer.inv` — written for a receiver
     * with no route, which cannot make one. It reads the wrong way round when
     * it is the PAYER that has no route: an online receiver at another mint
     * offers an invoice, all the gates fall through, and the offline payer is
     * walked to a Lightning send screen that can only fail. It did, all the way
     * to "send failed: Foxy is working offline" (an offline payer at one mint
     * paying a receiver at another).
     *
     * Lightning needs a route, so with no route there is no invoice to speak
     * of. Dropped here, once, rather than tested for at four separate gates. */
    const offline = this.offlineNow();
    const inv = offline ? '' : offer.inv;
    /* Same mint: pay with ecash and never mention Lightning.
     *
     * Paying a Lightning invoice made by the mint this phone pays from shows
     * that mint both sides of the payment, and costs a routing fee to go out
     * and come back to itself. The request goes straight to the receiver
     * instead. The card that used to ask which way — USE CASHU or CONTINUE
     * OVER LIGHTNING — is for a stranger's invoice that happens to share a
     * mint; two Foxys held together are not that, and the person should not be
     * asked a question with one right answer. */
    if (offer.sameMint) { this.openRequest(offer.req, { viaTap: true, theirRoute: offer.theirRoute, asks: offer.asks }); return; }
    /* Their mint is not this phone's, and this phone has a route.
     *
     * Ecash is only ever worth what its own mint will honour, so a request at
     * another mint cannot be answered out of this pile — but the money can be
     * moved there, which is the transfer Foxy already does, and then the
     * request is an ordinary one. It costs a Lightning fee, so it is asked
     * about before anything moves.
     *
     * An offer with an invoice on it still goes the Lightning way below: that
     * is one payment where this is two, and the receiver made the invoice
     * precisely so a stranger could pay it. This is for the offer with no
     * invoice at all — a receiver with no route, which cannot make one — where
     * the choice is a transfer or nothing. */
    /* No invoice, and they say they have a route: it is on its way.
     *
     * "No invoice" was read as "a receiver with no route", which is who the
     * crossing below is for. A receiver that is online has asked its mint for
     * one and has not been answered yet. Paying that invoice is one Lightning
     * payment; the crossing is a move and then a swap at their mint. So it is
     * waited for, five seconds, and the crossing is what happens if it does
     * not come. Only with a route here: a payer without one cannot pay an
     * invoice at all, and goes on to ask them to carry it home. */
    if (!inv && offer.crossable && !offline && offer.theirRoute === true && !offer.invWaited) {
      this.tapAwaitInvoice(offer, sats);
      return;
    }
    if (!inv && offer.crossable && !offline) {
      this.tapCrossMint(offer, sats);
      return;
    }
    /* Their mint is not this phone's, and this phone has no route.
     *
     * Nothing can be moved from here: no melt, no transfer, not even a swap.
     * But they are the ones with a route — that is why they have an amount in
     * sats and an open link — so they can bring the money home themselves and
     * say what it costs. This phone says where it is stuck and what it holds
     * there; they answer with a request at *this* mint for the amount plus
     * their costs, which the person here agrees to or does not.
     *
     * The fees are the payer's, as they are everywhere on this path: the
     * receiver named an amount and gets that amount. */
    /* Not gated on their invoice either: whether they made one says nothing
     * about whether this phone can pay it, and this phone cannot. */
    const stuck = W.stuckAtMint ? W.stuckAtMint(offer.read) : null;
    if (offer.crossable && stuck) { this.tapStuckAtMint(offer, stuck, sats); return; }
    if (!inv) { this.tapWrongMint(offer); return; }
    if (!this.acceptTarget(inv)) return;
  }

  /* The offline payer agreeing the price it is about to pay at.
   *
   * The receiver asked in sats, because it has a route and its own price. This
   * phone has neither, so every dollar figure it is about to show comes from
   * the figure THEY sent — and the person should agree to that, not discover it. The same screen the offline receiver sees, asked from
   * the other side, so there is one place that question is put.
   *
   * The link is held across it like any other decision (`tapTalking`): the
   * payer is the one deciding here, but the receiver is still holding a link
   * open waiting for a payment.
   */
  tapAgreeTheirPrice(offer, sats) {
    const W = window.FoxyWallet;
    const mine = (W.lastPrice && W.lastPrice()) || { rate: null, ageMs: 0 };
    const theirs = Math.round(Number(offer.theirRate) || 0);
    const q = {
      sats: sats,
      usd: Math.round((sats / 1e8) * theirs * 100),
      theirRate: theirs,
      myRate: mine.rate || 0,
      myRateAgeMs: mine.rate ? mine.ageMs : 0,
      differsPct: mine.rate ? ((theirs - mine.rate) / mine.rate) * 100 : null,
      // which side of the payment this phone is on, for the screen's words
      side: 'pay',
    };
    console.log('[foxy] tap: their bitcoin price is $ ' + this.group(theirs)
      + (q.differsPct == null ? '; this phone has none to compare'
         : '; ' + q.differsPct.toFixed(1) + '% from the one this phone last saw'));
    this.tapTalking(true);
    /* And the receiver is told, so its screen can say who it is waiting on and
     * why. It rides M10, which is the one message a payer sends before the
     * money: a body with `deciding` and no price and no mint is this. */
    // the same price is agreed without asking, so there is no wait to announce
    const asked = !(q.differsPct != null && Math.abs(q.differsPct) < 0.1);
    /* And where this phone is stuck at another mint, that goes with it: the
     * fee for carrying the money home is theirs to work out, and it depends on
     * nothing the person here is deciding, so it is started now rather than
     * after their answer. */
    const stuckNow = (offer.crossable && W.stuckAtMint) ? W.stuckAtMint(offer.read) : null;
    const ahead = stuckNow ? { mint: stuckNow.mint, have: stuckNow.have, sats: sats } : null;
    if (asked && W.tapQuote) {
      W.tapQuote(JSON.stringify(ahead ? { deciding: true, ahead: ahead } : { deciding: true })).catch(() => {});
    }
    this.priceTermsCard(q).then(yes => {
      // and told when it is over, so their screen goes back to the invoice and its code
      if (asked && W.tapQuote) W.tapQuote(JSON.stringify({ deciding: false })).catch(() => {});
      if (!yes) {
        console.log('[foxy] tap: their price was not agreed; nothing was sent');
        /* Said to them, or their phone reads this leaving as a payment lost
         * in flight and puts YOU NEED TO SCAN up. And the link is kept up
         * while the words leave: the conversation flag stays set for a moment,
         * as the receiver's own refusal does, because `tapQuote` resolving
         * means queued, not delivered — the first cut let go at once and the
         * receiver never heard it. */
        const said = W.tapQuote ? W.tapQuote(JSON.stringify({ gaveUp: 'The payer did not agree the price.' })) : Promise.resolve();
        said.catch(() => {}).then(() => setTimeout(() => {
          this.tapTalking(false);
          this.tapGaveNothing('their price was not agreed');
        }, 1500));
        return;
      }
      this.tapTalking(false);
      /* On to the mint question, which is where this came from. `_pricedFor`
       * stops it looping back here. */
      this.tapPayOffer(offer, sats);
    });
  }

  /* Wait for an online receiver's invoice, then go on with or without it. */
  tapAwaitInvoice(offer, sats) {
    const W = window.FoxyWallet;
    let done = false;
    let t = null;
    const close = () => {
      clearTimeout(t);
      if (W.onTapTerms) W.onTapTerms(null);
      this.dismissCard('invWait');
      if (this.hideStage) this.hideStage('invWait');
    };
    const finish = (inv) => {
      if (done) return;
      done = true;
      close();
      console.log(inv ? '[foxy] tap: their invoice came after the offer; paying it over Lightning'
        : '[foxy] tap: no invoice in five seconds; moving the sats to their mint instead');
      this.tapPayOffer(Object.assign({}, offer, { invWaited: true }, inv ? { inv: inv } : {}), sats);
    };
    if (W.onTapTerms) {
      W.onTapTerms(text => {
        let said = null;
        try { said = JSON.parse(String(text || '')); } catch (e) { said = null; }
        if (said && typeof said.inv === 'string' && /^ln(bc|tb|bcrt)[0-9a-z]+$/i.test(said.inv)) finish(said.inv);
      });
    }
    console.log('[foxy] tap: they are online at another mint and their invoice is not in yet; waiting up to 5s for it');
    t = setTimeout(() => finish(''), 5000);
    this.waitingScreen('invWait', {
      art: 'mints', title: 'Getting<br>their invoice', dots: true, forMs: 6000,
      body: 'The receiver uses another mint. Waiting a moment for their Lightning invoice.',
      button: 'CANCEL',
      go: () => { if (done) return; done = true; close(); this.tapGaveNothing('cancelled'); this.back(); },
    });
  }

  /* Ask the two mints what a crossing costs, while somebody is still deciding.
   *
   * The answer to "same mint?" is known the moment the offer arrives, and the
   * fee for crossing depends only on the amount this phone has just offered —
   * neither waits on whether the person agrees the price. Asking now means the
   * screen after their YES is ready instead of starting a two-mint round trip.
   *
   * Kept as a promise rather than a plan, so the screen can wait on it if the
   * person answers faster than two mints do. A failure is kept too: it is the
   * same failure the screen would have shown, and re-asking would only make
   * them wait for it twice.
   */
  tapPreQuoteMint(offer, sats) {
    const W = window.FoxyWallet;
    this._crossReady = null;
    const want = Math.round(Number(sats) || 0);
    const theirs = String((offer && offer.mints || [])[0] || '').replace(/\/+$/, '');
    const mine = String(W.mintUrl || '').replace(/\/+$/, '');
    if (!want || !theirs || !mine || theirs === mine) return;      // nothing to cross
    if (offer.inv && !this.offlineNow()) return;                   // Lightning pays it
    if (this.offlineNow()) return;                                 // their side quotes this one
    if (!W.transferQuote) return;
    console.log('[foxy] tap: asking what crossing to ' + theirs + ' costs, while they decide');
    this._crossReady = {
      sats: want, to: theirs, from: mine,
      plan: W.transferQuote(mine, want, { to: theirs, land: true }),
    };
    // a rejection here is an answer the screen will use; it must not go unhandled
    this._crossReady.plan.catch(() => {});
  }

  /* Paying somebody at another mint, from the phone that has the route.
   *
   * Ecash is only ever worth what its own mint will honour, so proofs from this
   * phone's mint are no use to a receiver at another one. What is possible is
   * moving the money there first — the transfer Foxy already does: melt here,
   * pay the destination's mint quote, claim the ecash at the far end — and then
   * the request is an ordinary same-mint request and the payment is the
   * payment it always was.
   *
   * It is a real Lightning payment, so it costs a real routing fee, and the fee
   * is asked about before anything moves. At the moment the card is up nothing
   * has been melted and nothing has been sent: cancelling costs the person
   * nothing but the seconds spent quoting.
   *
   * The order is quote, ask, move, pay. Anything else either spends money on a
   * question nobody answered or asks a question with no number in it.
   *
   * `sats` is passed when the amount came from the price leg; a request that
   * names its own sat figure is read from the request.
   */
  tapCrossMint(offer, sats) {
    const W = window.FoxyWallet;
    const theirs = String((offer.mints || [])[0] || '').replace(/\/+$/, '');
    const mine = String(W.mintUrl || '').replace(/\/+$/, '');
    const want = Math.round(Number(sats) || Number(offer.read && offer.read.sats) || 0);
    if (!theirs || !mine || !(want > 0)) {
      console.log('[foxy] tap: no crossing \u2014 ' + (!theirs ? 'they named no mint' : !mine
        ? 'this phone has no mint connected' : 'no amount'));
      this.tapWrongMint(offer);
      return;
    }
    /* A mint this phone has never used is named in full and connected to
     * deliberately, exactly as a scanned request at a strange mint is
     * (makeTokenForRequest). Moving money to an attacker's mint destroys it
     * just as surely as making a token there. */
    /* No card first. The crossing's own confirmation names THEIR MINT and
     * moves nothing until PAY is pressed, and that is the deliberate act; a
     * warning card before CALCULATING FEE was a second screen saying the same
     * thing. */
    /* Money actually in flight stops this. An invoice being watched does not.
     *
     * `refuseSwitchWhileBusy` counts a watched invoice as busy, and rightly for
     * a mint switch the PERSON asked for: the live watch claims at whichever
     * mint is connected, so switching under it would claim at the wrong one.
     * But refusing the payment is the wrong way out — the person tapped to pay
     * somebody and got "Wait for the payment to finish before switching mints",
     * about an invoice of their own that has nothing to do with it.
     *
     * So the watch is stopped instead. Nothing is lost by that: the quote is
     * written down with the mint that issued it, and `sweepQuotes` claims it at
     * that mint on the next connect — which is exactly what it exists for. */
    /* Housekeeping is waited for, not refused for.
     *
     * The proof lock is also held by Foxy's own tidying — breaking a large
     * piece into small change, a claim catching up — which takes a second or
     * two and is nobody's payment. A crossing that arrived in that second was
     * turned away with "wait for the payment in progress", about a payment
     * that did not exist, and the receiver sat on its four digits until the
     * person gave up (held by tidyChange for 2s). The lock is a queue; this
     * joins it.
     *
     * A send of this phone's own, or change being chased, still refuses:
     * those are payments, and two at once is what the rule is for. */
    if (!this._sendRun && !this._chasingChange && this.moneyMoving() && !this._crossWaited) {
      const began = Date.now();
      console.log('[foxy] tap: the crossing waits for ' + (this.busyWhy ? this.busyWhy() : 'the wallet'));
      const look = () => {
        if (!this.moneyMoving()) {
          console.log('[foxy] tap: the wallet is free after ' + (Date.now() - began) + 'ms; crossing now');
          this._crossWaited = true;
          try { this.tapCrossMint(offer, want); } finally { this._crossWaited = false; }
          return;
        }
        if (Date.now() - began > 15000) {
          this._crossWaited = true;
          try { this.tapCrossMint(offer, want); } finally { this._crossWaited = false; }
          return;
        }
        setTimeout(look, 200);
      };
      setTimeout(look, 200);
      return;
    }
    if (this.moneyMoving()) {
      /* Said in the diary too. The payer's phone showed a toast and went home,
       * the receiver's sat on its four digits, and neither log had a word
       * about why nothing followed the handshake. */
      console.log('[foxy] tap: the crossing was refused, money is already moving ('
        + (this.busyWhy ? this.busyWhy() : '?') + ')');
      this.toast('Wait for the payment in progress to finish, then tap again.', true);
      this.back();
      return;
    }
    if (this._watching) {
      console.log('[foxy] tap: stopping the invoice watch for the crossing; the sweep will claim it');
      this.stopReceive();
    }
    this._crossMintOk = null;
    /* Sats of this phone's own already at their mint pay it, and nothing is
     * moved.
     *
     * A crossing is a Lightning payment and then the payment itself. When
     * the first is made and the second is not — their mint slow to hand the
     * sats over, a swap that never left — the sats are this phone's, at
     * their mint. Tapping again quoted and made a second move, paid a second
     * routing fee, and left the first lot sitting at a mint the person does
     * not use (tools/live/offline-cross-scenarios.js `move-twice`,
     * `move-fail`). A move that is paid and not yet collected is
     * collected first, and then what is there is what pays. */
    const settle = (W.pendingMoves && W.pendingMoves().length && W.finishMove)
      ? W.finishMove().then(() => null, () => null) : Promise.resolve(null);
    settle.then(() => {
      const there = W.balanceAt ? W.balanceAt(theirs) : 0;
      // enough on its face; whether it covers that mint's fee too is asked once there (`sendShortfall`)
      if (there >= want && W.sendShortfall) { this.tapPayFromThere(offer, want, theirs, mine, there); return; }
      this.tapCrossQuote(offer, want, theirs, mine);
    });
    return;
  }

  /* Paid out of what this phone already holds at their mint. The same
   * confirmation the crossing shows, with no fee on it; a visit, and home
   * again whichever way it ends (`crossComeHome`). */
  tapPayFromThere(offer, want, theirs, mine, there) {
    const W = window.FoxyWallet;
    console.log('[foxy] tap: ' + there + ' sats of this phone\u2019s are already at ' + theirs + '; paying from there, with no move');
    this.crossMintCard({ net: want, feeSats: 0 }, theirs, mine).then(yes => {
      if (!yes) { console.log('[foxy] tap: paying from ' + theirs + ' was not accepted'); return null; }
      return W.connect(theirs, null, null, { remember: false }).then(() => {
        const sf = W.sendShortfall(want, { locked: true });
        if (sf && sf.short) {
          // not enough there once its fee is counted: home, and the ordinary crossing
          console.log('[foxy] tap: what is at their mint does not cover it with the fee; moving the rest instead');
          return W.connect(mine).then(() => { this.setState({ crossBusy: false, crossQ: null }); this.back(); this.tapCrossQuote(offer, want, theirs, mine); });
        }
        this._crossMovedTo = null;
        this._crossCameFrom = mine;
        this.refreshBalance();
        const read = W.decodeRequest(offer.req);
        if (!read) throw new Error('Their request could not be read.');
        read.viaTap = true;
        if (typeof offer.theirRoute === 'boolean') read.theirRoute = offer.theirRoute;
        if (offer.asks) read.asks = true;
        this.setState({ req: read, reqBusy: false, crossBusy: false,
                        crossQ: null, note: '', noteDraft: '' });
        this.makeTokenForRequest();
        return null;
      });
    }).catch(e => this.crossFailed(e, mine));
  }

  /* Quote the move, ask, move, pay. */
  tapCrossQuote(offer, want, theirs, mine) {
    const W = window.FoxyWallet;
    /* The one asked for while they were deciding, if it is the same crossing.
     *
     * `tapPreQuoteMint` starts this the moment the price goes out, so by the
     * time somebody has agreed it the answer is usually already here and this
     * screen opens at once instead of after a two-mint round trip. Matched on
     * all three of amount, source and destination: anything else is a different
     * question and gets asked fresh. */
    const ready = this._crossReady;
    this._crossReady = null;
    const ahead = !!(ready && ready.sats === want && ready.to === theirs && ready.from === mine);
    if (ahead) console.log('[foxy] tap: the crossing was already quoted while they decided');
    /* No overlay: the screen itself opens now, on what is already known, and
     * the fee fills in when the two mints answer. An overlay over a screen
     * nobody can see yet is a wait with nothing in it. */
    const quoting = ahead ? ready.plan : W.transferQuote(mine, want, { to: theirs, land: true });
    quoting.catch(() => {});
    // CALCULATING FEE is `crossMintCard`'s to show, until the quote is in
    this.crossMintCard(quoting, theirs, mine).then(yes => {
      if (!yes) {
        console.log('[foxy] tap: the fee to reach ' + theirs + ' was not accepted');
        return;
      }
      return quoting.then(plan => this.crossRun(plan, offer, theirs, mine));
    }).catch(e => this.crossFailed(e, mine));
    return;
  }

  /* The crossing itself, once the fee has been agreed: melt there, claim
   * there, then pay from there. One press did all of it, which is the point —
   * the screen they agreed on IS this payment's confirmation. */
  /* A crossing's own two entries are not payments to announce.
   *
   * Moving sats between mints writes a melt at one and a claim at the other,
   * and the history pass announced the claim as money received: PAYMENT
   * RECEIVED over a card saying they had refused it, for sats this phone had
   * moved itself, and a second
   * confirmation after a payment carried home. Marked seen by the
   * ids the plan already holds, before the move writes them. */
  hushMove(plan) {
    this._seenTx = this._seenTx || {};
    ['mintQuote', 'meltQuote'].forEach(k => {
      const id = plan && plan[k] && plan[k].quote;
      if (id) this._seenTx[id] = true;
    });
  }

  crossRun(plan, offer, theirs, mine) {
    const W = window.FoxyWallet;
    /* Asked before the move, not after it. A move is a Lightning payment
     * and its fee; made for a request that is closed, or that the receiver
     * cannot take, it left the sats at a mint the person does not use. The
     * payment asks again when it is made; this is the one that saves the fee. */
    if (offer.asks && W.askFirst && !this._crossAsked) {
      const read0 = W.decodeRequest(offer.req);
      if (read0) {
        this._crossAsked = true;
        // their request names an amount and their mint; the payment will be locked when they have no route
        return W.askFirst(read0, { mint: theirs, locked: true }).then((a) => {
          if (!a || a.go !== true) {
            this._crossAsked = false;
            const eNo = /** @type {any} */ (new Error((a && a.why) || 'They cannot take this payment. Nothing was sent.'));
            eNo.foxyAskedNo = true;
            throw eNo;
          }
          return this.crossRun(plan, offer, theirs, mine);
        }).then((r) => { this._crossAsked = false; return r; }, (e) => { this._crossAsked = false; throw e; });
      }
    }
    this.hushMove(plan);
    this.showMelt('Moving your sats to ' + (this.mintNameOf(theirs) || 'their mint') + '\u2026',
                  0, { sats: plan.net, mint: this.mintNameOf(theirs) });
    /* On the mint the money leaves, which is where the melt has to run from —
     * the same step the transfer screen takes for the same reason. `moveRun`
     * connects to the destination itself once the invoice is paid, and leaves
     * this phone there, which is where the payment is made from anyway. */
    /* Quiet while it moves, and its entries marked seen before anything reads
     * history again. `hushMove` names the quotes the plan holds, and the move
     * makes its own at the moment it runs — so the melt was announced as
     * WITHDRAWAL SENT in the middle of a payment. The sweep's own way of
     * doing this, which goes by what is new in history rather than by a
     * name. */
    this._quiet = true;
    W.transactions(50).then(list => { this._sweepBefore = new Set(list.map(x => x.hash)); })
      .catch(() => { this._sweepBefore = null; });
    const loud = () => { this._quiet = false; };
    /* A visit: their mint is where this payment is made from, not where this
     * phone banks, and it is not saved as the phone's own. */
    return W.connect(mine).then(() => W.moveRun(plan, () => {}, { visit: true })).then((done) => {
      const quiet = this.hushSweepEntries ? this.hushSweepEntries() : Promise.resolve();
      return quiet.then(() => done, () => done);
    }).then(() => {
      loud();
      this.hideMelt();
      this.refreshBalance();
      console.log('[foxy] tap: the sats are at ' + theirs + '; paying their request now');
      /* From here the money is at their mint whatever happens next, and that is
       * worth knowing about: a failure now leaves the balance at a mint the
       * person was not on when they tapped (`theyRefused`'s chip). */
      this._crossMovedTo = theirs;
      /* And the mint to come home to once the payment is made: the crossing is
       * Foxy's business, the mint the person banks at is theirs. */
      this._crossCameFrom = mine;
      /* Paid straight from here, with no second confirmation: the screen they
       * agreed on is this payment's confirmation. */
      const read = W.decodeRequest(offer.req);
      if (!read) throw new Error('Their request could not be read.');
      read.viaTap = true;
      if (typeof offer.theirRoute === 'boolean') read.theirRoute = offer.theirRoute;
        if (offer.asks) read.asks = true;
      this.setState({ req: read, reqBusy: false, crossBusy: false,
                      crossQ: null, note: '', noteDraft: '' });
      this.makeTokenForRequest();
    });
  }

  /* Whatever went wrong, the wallet goes back to the mint it was on: a failed
   * quote never left it, and a failed move may have. */
  crossFailed(e, mine) {
    const W = window.FoxyWallet;
    this._quiet = false;
    this.hideMelt();
    if (W.mintUrl !== mine) W.connect(mine).then(() => this.refreshBalance(), () => {});
    const why = W.reason ? W.reason(e) : String((e && e.message) || e);
    console.warn('[foxy] tap: could not pay across mints:', why);
    this.setState({ crossBusy: false, crossQ: null });
    /* What is true of the money, which is not always "nothing was sent".
     *
     * A move is a Lightning payment and then a claim. With the payment made
     * and the claim refused or unreachable, this card said nothing had been
     * sent and the sats were where they were — while 507 of them had left
     * the mint for a 500-sat payment nobody received
     * (tools/live/offline-cross-scenarios.js `move-cut`). The move's own
     * error says which it was. */
    const theirs = this.mintNameOf(e && e.moveTo) || 'their mint';
    if (e && e.foxyAskedNo) {
      this.blockedCard('crossMint', {
        tone: 'warn',
        title: 'THEY CANNOT TAKE IT',
        reason: why,
        chip: 'Nothing was sent, and nothing was moved.',
      });
    } else if (e && e.movePaid) {
      this.blockedCard('crossMint', {
        tone: 'warn',
        title: 'YOUR SATS ARE ON THEIR WAY',
        reason: 'The sats left your mint for ' + theirs + ', and ' + theirs + ' has not handed them over yet. '
          + 'Foxy collects them by itself. They have not been paid.',
        chip: this.group(Math.round(Number(e.moveSats) || 0)) + ' sats will be yours at ' + theirs
          + '. Tap again once they are there.',
      });
    } else if (e && e.pending) {
      this.blockedCard('crossMint', {
        tone: 'warn',
        title: 'THE MOVE MAY STILL GO THROUGH',
        reason: 'Your mint has not said whether the payment to ' + theirs + ' went. Foxy is holding the sats until it says either way. '
          + 'They have not been paid.',
        chip: 'Nothing is lost. Wait for it to settle before paying again.',
      });
    } else {
      this.blockedCard('crossMint', {
        tone: 'warn',
        title: 'COULD NOT REACH THEIR MINT',
        reason: why,
        chip: 'Nothing was sent, and your sats are where they were.',
      });
    }
    this.back();
  }


  /* Whether a decision is being put to a person with a payer holding the link.
   *
   * While it is true, nothing that watches the screen may tear anything down:
   * not the Bluetooth radio, not the screen-awake lock, not the onion address
   * (`syncTap`, `syncAwake`, `syncInbox`). It is deliberately NOT a screen
   * test — the answer is sent after the screen has already gone back to home,
   * so any screen test loses the race.
   *
   * A clock ends it whatever happens, because a flag that holds the radio open
   * for ever is its own bug. Ninety-five seconds is the payer's own patience,
   * so by then there is nobody left to answer.
   */
  tapTalking(on) {
    clearTimeout(this._tapTalkT);
    if (!on) {
      if (!this._tapTalking) return;
      this._tapTalking = false;
      console.log('[foxy] tap: the answer has gone; the link is free again');
      this.syncTap();
      return;
    }
    this._tapTalking = true;
    /* And the payer is told to wait, because otherwise it will not.
     *
     * A payer gives up on the result after 25 seconds, which is right for a
     * swap over a cold circuit. It is wrong for everything this hold covers: a
     * person reading two bitcoin prices, and a carry-home quote that is allowed
     * 25 seconds of its own before it even fails. M9 moves the payer's clock to
     * 90, and until now only the offline-risk card sent one — so the price
     * screens and the carry-home ran the payer's patience out from under
     * themselves, and the payer sat on "waiting on their answer" until it gave
     * up.
     *
     * Harmless on a phone that is not the receiver: with no link to push it
     * down, the native side answers false and nothing happens. */
    const W = window.FoxyWallet;
    if (W && W.tapAsking) {
      W.tapAsking().catch(() => {});
    }
    this._tapTalkT = setTimeout(() => {
      if (!this._tapTalking) return;
      console.warn('[foxy] tap: nobody answered in time; letting the link go');
      this._tapTalking = false;
      if (this.hideStage) this.hideStage('waitPayer');
      this.syncTap();
    }, 95000);
  }


  /* The receiver's side of `tapOfflineCross`: the same card, from where
   * this phone stands. `theirMint` is the payer's, as the payer said it. */
  offlineCrossCard(theirMint) {
    const W = window.FoxyWallet;
    const strip = (u) => String(u || '').replace(/\/+$/, '');
    const name = (u) => this.mintNameOf(u) || strip(u).replace(/^https?:\/\//, '') || 'another mint';
    const theirs = strip(theirMint);
    this.blockedCard('offlineCross', {
      tone: 'warn',
      title: 'OFFLINE & DIFFERENT MINT',
      reason: 'Your payer uses a different mint.\nBoth of you must be online to transact between mints.',
      chip: 'You use ' + name(W.mintUrl) + ' while they use ' + (theirs ? name(theirs) : 'another mint') + '.',
    });
  }


  /* The card for a phone that speaks another version of the tap. A code on a
   * screen is read by every version, so that is the way through for now, said
   * from where this phone stands. Once in a quarter of a minute: phones held
   * together try again, and the card would come up over and over. */
  tapVersionCard(side) {
    if (Date.now() < (this._tapVersionSaid || 0)) return;
    this._tapVersionSaid = Date.now() + 15000;
    console.log('[foxy] tap: the other phone speaks another version of the tap; saying so');
    if (side === 'pay') { this.tapBuzz(false); this.hideConnecting(); }
    this.blockedCard('tapVersion', {
      tone: 'warn',
      title: 'UPDATE FOXY TO TAP',
      reason: 'The other phone has a different version of Foxy, so the two cannot tap.\nUpdate Foxy on both phones.',
      chip: side === 'pay' ? 'For now, scan the code on their screen.' : 'For now, they can scan the code on this screen.',
    });
  }

  /* The receiver's half: they are stuck at another mint and this phone is not.
   *
   * They have no route, so the sats cannot leave their mint by their own hand.
   * This phone has one, so it can: take their ecash where it is, swap it in at
   * their mint — the moment there is no risk left in any of this — and then
   * melt it home. Every cost of doing that is quoted back to them and paid by
   * them, because the amount asked for is the amount that lands here.
   *
   * The request goes out naming *their* mint, so what they send is ecash they
   * already hold; this phone connects there to receive it, and goes home
   * afterwards. Nothing is claimed as paid until the swap at their mint has
   * come back, which is what makes "no risk" true rather than hopeful.
   */
  /* The fee for that, asked about early: the payer has said which mint it is
   * stuck at while its owner is still reading the price. A quote only — nothing
   * is connected to and nothing moves — kept for `tapCarryHome` to pick up. A
   * failure is dropped, and the real ask is made afresh. */
  tapCarryAhead(ahead) {
    const W = window.FoxyWallet;
    const want = Math.round(Number(ahead && ahead.sats) || 0)
      || Math.round(Number(this.wantedSats && this.wantedSats()) || 0);
    const from = String((ahead && ahead.mint) || '').replace(/\/+$/, '');
    if (!(want > 0) || !from || !W.crossTerms || this.offlineNow()) return;
    // asked already and still good (the link dropped and they are back): not asked of two mints again
    const live = this._carryAsk, had = this._carryAhead;
    if (live && live.from === from && live.want === want && Date.now() - live.at < 180000) return;
    if (had && had.from === from && had.want === want && Date.now() - had.at < 60000) return;
    console.log('[foxy] tap: working out the fee from ' + from + ' while they read the price');
    const held = { from: from, want: want, at: Date.now(),
                   terms: W.crossTerms({ mint: from, have: Number(ahead.have) || 0, sats: want }, want) };
    held.terms.catch(() => { if (this._carryAhead === held) this._carryAhead = null; });
    this._carryAhead = held;
  }

  tapCarryHome(said) {
    const W = window.FoxyWallet;
    const want = Math.round(Number(said && said.sats) || 0)
      || Math.round(Number(this.wantedSats && this.wantedSats()) || 0);
    const no = (why) => {
      console.warn('[foxy] tap: cannot carry it home:', why);
      const sent = W.tapTerms
        ? W.tapTerms(JSON.stringify({ no: true, why: why })) : Promise.resolve();
      sent.catch(() => {}).then(() => this.tapTalking(false));
    };
    if (!(want > 0)) { no('Foxy could not tell how much this is for.'); return; }
    if (this.offlineNow()) { no('This phone has no connection either, so nothing here can move it.'); return; }
    const mintSaid = String((said && said.mint) || '').replace(/\/+$/, '');
    /* One asking for one payment.
     *
     * The link can drop while the fee is being worked out, and the payer
     * touches again and asks the same thing. Each asking wrote a job down
     * and went to their mint, so one payment had two jobs: it was written
     * on the first, the walk home was started on the second, and the second
     * — with nothing paid to it — was left asking to be brought home for
     * good (IT COSTS MORE TO BRING HOME, ten times,
     * for a payment that had landed). Asked again for the same mint and
     * amount, the asking already under way answers: its terms go out on
     * whichever link is up when they are ready, and again if they have
     * already gone. Before the busy check, because the first asking is
     * itself what makes this phone busy. */
    const live = this._carryAsk;
    if (live && live.from === mintSaid && live.want === want && Date.now() - live.at < 180000) {
      console.log('[foxy] tap: this was asked a moment ago; '
        + (live.sent ? 'the same terms go out again' : 'its answer is still being worked out'));
      this.tapTalking(true);
      if (live.sent && W.tapTerms) W.tapTerms(live.sent).catch(() => {}).then(() => this.tapTalking(false));
      return;
    }
    /* `moneyMoving`, not `moneyBusy`: this runs on the receive screen, and
     * that screen is always watching for a payment. Asking the wider
     * question refused every carry-home for being the thing it was
     * (09-melt-paste-switch.js). */
    if (this.moneyMoving()) { no('This phone is busy moving money. Try again in a moment.'); return; }
    const home = String(W.mintUrl || '').replace(/\/+$/, '');
    const ask = { from: mintSaid, want: want, at: Date.now(), sent: '' };
    this._carryAsk = ask;
    // asked for something else since: that asking has the link, and this one says nothing more
    const SUPERSEDED = {};
    const mine = () => { if (this._carryAsk !== ask) throw SUPERSEDED; };
    let visit = null;
    this.tapTalking(true);
    // the quote started while they were deciding, where it is this one and fresh
    const early = this._carryAhead;
    this._carryAhead = null;
    const useEarly = !!(early && early.from === mintSaid && early.want === want
                        && Date.now() - early.at < 60000);
    if (useEarly) console.log('[foxy] tap: the fee was already being worked out');
    (useEarly ? early.terms.catch(() => W.crossTerms(said, want)) : W.crossTerms(said, want)).then(terms => {
      mine();
      /* The request is made at their mint, which means being on it: the payment
       * that answers it is ecash that mint issued, and it is checked against
       * whichever mint this wallet is on when it lands. Home again as soon as
       * the money is. */
      visit = { back: home, terms: terms, id: '' };
      this._carryHome = visit;
      /* Written down first, and the visit not saved as this phone's mint
       * (`carryBegin`): an app killed over there used to open on the payer's
       * mint, with the payment sitting at it and nothing to say it was to
       * come home. */
      const going = W.carryBegin ? W.carryBegin(terms).then(id => { visit.id = id; })
                                 : W.connect(terms.from);
      return going.then(() => {
        mine();
        // waited for, for the reason the price leg above gives
        return this.railRequestReady(terms.ask, 'carry:' + terms.from);
      }).then(req => {
        mine();
        if (!req) throw new Error('Foxy could not make a request at their mint.');
        console.log('[foxy] tap: asking ' + terms.ask + ' at ' + terms.from
                    + ' so ' + terms.net + ' lands at ' + home);
        /* And a clock on it, because being on somebody else's mint is not a
         * state to sit in.
         *
         * The terms go out and the person on the other phone decides. If they
         * say no, or put the phone in a pocket, nothing comes back at all —
         * there is no message for "I thought about it and stopped" — and this
         * phone would wait on their mint for ever, showing their mint's
         * balance, offering their mint's request to the next person who tapped.
         * Ninety seconds is the payer's own patience (`tapStuckAtMint`), so
         * this outlives it and then goes home. */
        clearTimeout(this._carryHomeT);
        this._carryHomeT = setTimeout(() => {
          if (this._carryHome !== visit) return;   // the payment arrived, or another asking has it; not this
          const gone = this._carryHome;
          this._carryHome = null;
          if (this._carryAsk === ask) this._carryAsk = null;
          console.log('[foxy] tap: nothing came of the cross-mint offer; going home to ' + home);
          if (W.carryEnd && gone.id) W.carryEnd(gone.id).then(() => this.refreshBalance(), () => {});
          else if (W.mintUrl !== home && home) W.connect(home).then(() => this.refreshBalance(), () => {});
        }, 120000);
        // kept, to be said again to a payer who lost the link and came back (above)
        ask.sent = JSON.stringify({ req: req, sats: terms.ask,
                                    net: terms.net, fee: terms.feeSats,
                                    at: terms.from });
        return W.tapTerms(ask.sent)
          .then((r) => { this.tapTalking(false); return r; });
      });
    }).catch(e => {
      const stale = e === SUPERSEDED || this._carryAsk !== ask;
      if (stale) {
        // its job goes, and the phone stays where the newer asking has taken it
        if (W.carryEnd && visit && visit.id) W.carryEnd(visit.id, true).catch(() => {});
        if (this._carryHome === visit) this._carryHome = null;
        return;
      }
      const why = W.reason ? W.reason(e) : String((e && e.message) || e);
      /* Back where this phone belongs, whatever went wrong: a quote that failed
       * never left it and a connect that half-worked may have. */
      const failed = visit;
      if (W.carryEnd && failed && failed.id) W.carryEnd(failed.id).then(() => this.refreshBalance(), () => {});
      else if (W.mintUrl !== home && home) W.connect(home).then(() => this.refreshBalance(), () => {});
      this._carryHome = null;
      this._carryAsk = null;
      clearTimeout(this._carryHomeT);
      no(why);
      this.toast(why, true);
    });
  }


  /* The payment they sent at their mint is in. Bring it home.
   *
   * Called once the swap has come back — the money is this phone's, at their
   * mint, and nothing about the rest of this can lose it. The melt home is
   * ordinary work from here, and a failure leaves the sats sitting at their
   * mint where the transfer screen can move them by hand.
   */
  carryHomeNow() {
    const W = window.FoxyWallet;
    const job = this._carryHome;
    this._carryHome = null;
    this._carryAsk = null;
    clearTimeout(this._carryHomeT);
    if (!job || !job.terms) return Promise.resolve();
    const home = job.back;
    console.log('[foxy] tap: their ecash is in; melting it home to ' + home);
    /* Not received until it is home.
     *
     * Their ecash has been swapped in at their mint, which is what makes it
     * this phone's and lets the payer be answered. It is not yet money at a
     * mint this person chose to trust, and until it is, showing PAYMENT
     * RECEIVED is calling something final that is not.
     * So the screen says it is being brought home, the entries this makes on
     * the way are kept quiet, and the confirmation is raised once — for what
     * landed, where it landed.
     *
     * If it cannot be brought home the card below says so: paid, and still at
     * their mint. */
    const from = String(W.mintUrl || '').replace(/\/+$/, '');
    const heldThere = (W.balanceAt && from) ? W.balanceAt(from) : 0;
    const paid = Math.round(Number(job.terms.ask) || Number(job.terms.sats) || 0);
    this._quiet = true;
    /* Off the air while it is brought home. The screen underneath is still
     * the invoice, so it armed itself again the moment the payer's link
     * closed and advertised the same request for the eighteen seconds the
     * move took: the payer, sent and dismissed, saw CONNECT TO PAY on its
     * home screen for a payment it had just made. */
    this._carryingHome = true;
    if (this.syncTap) this.syncTap();
    this._hushUntil = Date.now() + 120000;
    W.transactions(50).then(list => { this._sweepBefore = new Set(list.map(x => x.hash)); })
      .catch(() => { this._sweepBefore = null; });
    this.showMelt('Bringing the payment to your mint\u2026', 0,
                  { sats: Math.round(Number(job.terms.net) || 0), mint: this.mintNameOf(home) });
    this.hushMove(job.terms.plan);
    const settle = () => {
      this.hideMelt();
      this._quiet = false;
      this._carryingHome = false;
      this._hushUntil = Date.now() + 20000;
      if (this.syncTap) this.syncTap();
    };
    /* The wallet does the walk and says what became of it (`carryHome`): it
     * landed, it is on its way, it has to wait, it would cost more than was
     * paid for, or it went back to the payer. The phone is at its own mint
     * when the answer comes, whichever it is. */
    const walk = (W.carryHome && job.id)
      ? W.carryHome(job.id, job.terms.plan, () => {})
      : W.moveRun(job.terms.plan, () => {}).then(done => ({ state: 'home', sats: done && done.sats, done: done }),
          e => ({ state: 'stuck', why: W.reason ? W.reason(e) : String((e && e.message) || e) }));
    return walk.then((r) => {
      const quiet = (r && r.state === 'home' && this.hushSweepEntries) ? this.hushSweepEntries() : Promise.resolve();
      return quiet.then(() => r, () => r);
    }).then((r) => {
      settle();
      this.carryOutcome(r, { home: home, heldThere: heldThere, paid: paid, net: job.terms.net });
    }).catch(e => {
      settle();
      console.warn('[foxy] tap: bringing the payment home:', (e && e.message) || e);
      this.loadHistory();
    });
  }

  /* What became of a payment being brought home, said once.
   *
   * From the walk itself, and from the wallet when it is the one that found
   * out — a launch that finished one, a claim made late (`W.onCarry`). It is
   * received when it is at this phone's own mint and at no moment before:
   * until then it is money at a mint this person did not choose, and every
   * card here says which of those it is. */
  carryOutcome(r, ctx) {
    const W = window.FoxyWallet;
    const c = ctx || {};
    const job = (r && r.job) || {};
    const home = String(c.home || job.home || W.mintUrl || '').replace(/\/+$/, '');
    const homeName = this.mintNameOf(home) || 'your mint';
    const theirName = this.mintNameOf(job.from) || 'their mint';
    const state = String((r && r.state) || '');
    this.refreshBalance();
    this.loadHistory();
    // somebody else is already on it (the wallet, on a launch): it says what became of it
    if (state === 'busy' || state === 'none') return;
    if (state === 'home') {
      const landed = Math.round(Number(r.sats) || Number(c.net) || Number(job.net) || 0);
      console.log('[foxy] tap: the payment is home, ' + landed + ' sats at ' + home);
      // its own entry at home is the crossing's, and is not a second payment
      this._seenTx = this._seenTx || {};
      if (r.quote) this._seenTx[r.quote] = true;
      this.dismissCard('carryHome');
      this.noteReceived();
      this.announcePayment({ dir: 'in', sats: landed, force: true, to: 'ecash',
                             hash: 'carry-' + Date.now() });
      /* What THIS payment left at their mint, and nothing else. `leftBehind`
       * is everything held there, so a phone with a balance of its own at
       * that mint was told after every payment that thousands of sats had been
       * left behind by carrying home a dollar. What it held there before the
       * payment is taken off. */
      const done = r.done || {};
      const whole = Math.round(Number(done.leftBehind) || 0);
      const mine = Math.max(0, (Number(c.heldThere) || 0) - (Number(c.paid) || 0));
      const left = Math.max(0, whole - mine);
      const at = String(done.from || '').replace(/\/+$/, '');
      if (left > 0 && at && c.paid) this.saySatsLeftAt(left, at);
      return;
    }
    if (state === 'moving' || state === 'waiting') {
      console.log('[foxy] tap: the payment is on its way to ' + home + ' (' + state + ')');
      this.blockedCard('carryHome', {
        tone: 'ask',
        title: 'ON ITS WAY TO YOUR MINT',
        reason: state === 'moving'
          ? 'The payment has left ' + theirName + ' for ' + homeName + ', and ' + homeName
            + ' has not handed it over yet. Foxy collects it by itself.'
          : 'The payment is leaving ' + theirName + ' for ' + homeName + ', and their mint has not said it is done. '
            + 'Foxy is holding it until the mint says either way.',
        chip: 'It is not received until it is at ' + homeName + '. Nothing is lost.',
      });
      return;
    }
    if (state === 'short') {
      const lands = Math.round(Number(r.lands) || 0);
      const net = Math.round(Number(r.net) || Number(job.net) || 0);
      console.log('[foxy] tap: bringing it home would now land ' + lands + ' of ' + net + '; asking');
      this.blockedCard('carryHome', {
        tone: 'ask',
        title: 'IT COSTS MORE TO BRING HOME',
        reason: 'The payment is at ' + theirName + '. Bringing it to ' + homeName + ' now costs more than the payer paid for: '
          + this.group(lands) + ' sats would arrive, not ' + this.group(net) + '.',
        chip: 'It is not received until it is at ' + homeName + '.',
        retry: 'BRING ' + this.group(lands) + ' HOME',
        go: () => {
          this.showMelt('Bringing the payment to your mint\u2026', 0, { sats: lands, mint: homeName });
          W.carryHome(job.id, null, () => {}, { less: true }).then(x => { this.hideMelt(); this.carryOutcome(x, { home: home }); });
        },
        shut: { label: 'SEND IT BACK', tap: () => {
          this.showMelt('Sending the payment back\u2026');
          W.carryRefund(job.id).then(x => { this.hideMelt(); this.carryOutcome(x, { home: home }); });
        } },
      });
      return;
    }
    if (state === 'refunded') {
      console.log('[foxy] tap: the payment could not be brought home and went back to the payer'
        + (r.handed ? ' over the link' : ', as a code'));
      // not handed: the wallet has raised the code for the payer to scan (`changeStuckCard`)
      if (r.handed) {
        this.blockedCard('carryHome', {
          tone: 'warn',
          title: 'NOT RECEIVED',
          reason: 'The payment could not be brought to ' + homeName + ', so it was sent back to the payer. ' + String(r.why || ''),
          chip: 'They have it back. Nothing was received.',
        });
      }
      return;
    }
    if (state === 'retry') {
      console.warn('[foxy] tap: the payment is still at their mint, to be brought home later:', r.why);
      this.blockedCard('carryHome', {
        tone: 'warn',
        title: 'NOT HOME YET',
        reason: 'The payment is at ' + theirName + ' and has not reached ' + homeName + ' yet. ' + String(r.why || '')
          + ' Foxy tries again when it can reach both mints.',
        chip: 'It is not received until it is at ' + homeName + '.',
        retry: 'TRY AGAIN',
        go: () => {
          this.showMelt('Bringing the payment to your mint\u2026', 0, { sats: Math.round(Number(job.net) || 0), mint: homeName });
          W.carryHome(job.id, null, () => {}).then(x => { this.hideMelt(); this.carryOutcome(x, { home: home }); });
        },
        shut: job.payerKey ? { label: 'SEND IT BACK', tap: () => {
          this.showMelt('Sending the payment back\u2026');
          W.carryRefund(job.id).then(x => { this.hideMelt(); this.carryOutcome(x, { home: home }); });
        } } : { label: 'CLOSE' },
      });
      return;
    }
    if (state === 'stuck') {
      console.warn('[foxy] tap: the payment is at their mint and could not be sent back:', r.why);
      this.blockedCard('carryHome', {
        tone: 'warn',
        title: 'PAID, STILL AT THEIR MINT',
        reason: 'The payment is yours, at ' + theirName + '. It could not be brought to ' + homeName
          + ' and could not be sent back. ' + String(r.why || ''),
        chip: 'Move it whenever you like, from the mint screen.',
        retry: 'MOVE IT', go: () => this.goSwitchMint(),
        shut: { label: 'LEAVE IT' },
      });
    }
  }


  /* Money of this phone's own, at somebody else's mint.
   *
   * Carrying a payment home melts it out of the payer's mint, and a melt
   * reserves more than the route spends. What is left is this phone's, at a
   * mint its owner does not use, and the only way they would have known is the
   * diary. It is not a warning — nothing is wrong and nothing is at risk — so
   * it says the figure, names the mint, and offers the screen that moves it.
   */
  saySatsLeftAt(sats, mint) {
    const name = this.mintNameOf(mint) || String(mint).replace(/^https?:\/\//, '');
    console.log('[foxy] ' + sats + ' sats of yours are still at ' + mint);
    this.blockedCard('leftBehind', {
      tone: 'ask',
      title: 'SATS LEFT AT ' + name.toUpperCase(),
      reason: this.group(sats) + ' sats of yours are at ' + name + ', which is their mint, not '
        + (this.mintNameOf(window.FoxyWallet && window.FoxyWallet.mintUrl) || 'yours') + '. '
        + 'Bringing the payment home left it there, and it is yours to move whenever you like.',
      chip: 'Nothing is at risk. It spends at ' + name + ', or moves to your mint over Lightning.',
      retry: 'MOVE IT', go: () => this.goSwitchMint(),
      shut: { label: 'LEAVE IT' },
    });
  }


  /* The payer's half of the other cross-mint talk (M10 out, M11 back).
   *
   * This phone has no route and its sats are at a mint they do not use. It says
   * so — which mint, and how much is there — and waits for them to answer with
   * a request at this mint for the amount plus what bringing it home will cost
   * them. Nothing has left and nothing will until the person here agrees to
   * that figure.
   *
   * It is the same two messages the price talk uses, in the same directions and
   * for the same reason: a number one phone can work out, offered to the other
   * to agree to, with the money still where it was.
   */
  tapStuckAtMint(offer, stuck, sats) {
    const W = window.FoxyWallet;
    const want = Math.round(Number(sats) || Number(offer.read && offer.read.sats) || 0);
    const said = Object.assign({ id: String((offer.read && offer.read.id) || ''), sats: want }, stuck);
    const seq = (this._tapQuoteSeq = (this._tapQuoteSeq || 0) + 1);
    const done = (over) => {
      if (this._tapQuoteSeq !== seq) return false;
      this._tapQuoteSeq = 0;
      clearTimeout(this._tapQuoteT);
      if (W.onTapTerms) W.onTapTerms(null);
      this.dismissCard('priceSent');
      if (this.hideStage) this.hideStage('priceSent');
      // a talk that ended with no payment leaves nothing to protect
      if (over) { this._crossReady = null; this.tapGaveNothing(over); }
      return true;
    };
    if (W.onTapTerms) {
      W.onTapTerms(text => {
        let terms = null;
        try { terms = JSON.parse(String(text || '')); } catch (e) {}
        /* Their invoice, arriving late on this same message: not an answer.
         * A phone with no route has no use for it either way, and reading it
         * as "no" ended the talk the receiver was still working on. */
        if (terms && typeof terms.inv === 'string' && !terms.req && !terms.no && !terms.why) {
          console.log('[foxy] tap: their invoice came in while they work out the cost; still waiting for the answer');
          return;
        }
        if (!done()) return;
        if (!terms || !terms.req || !(Number(terms.sats) > 0)) {
          this.toast(terms && terms.why ? String(terms.why)
            : 'They could not take a payment from your mint. Nothing was sent.', true);
          this.back();
          this.tapGaveNothing('they could not take it');
          return;
        }
        /* The request is read BEFORE the figure is shown, and has to be for
         * that figure, at this phone's own mint.
         *
         * The fee screen showed what the other phone said (`terms.sats`) and
         * PAY then paid what its request asked for, which nothing compared:
         * a card for 1,028 sats sent 5,000, and that screen is the only
         * confirmation this payment has (tests/offline-hostile.js). A request
         * for any other amount, or at any other mint,
         * is not the offer on the screen, and is not paid. */
        const read = W.decodeRequest(String(terms.req));
        const shownSats = Math.round(Number(terms.sats) || 0);
        const reqSats = read ? Math.round(Number(read.sats) || 0) : 0;
        const reqMint = String(((read && read.mints) || [])[0] || '').replace(/\/+$/, '');
        const myMint = String(W.mintUrl || '').replace(/\/+$/, '');
        if (!read || reqSats !== shownSats || (reqMint && reqMint !== myMint)) {
          console.warn('[foxy] tap: their terms and their request do not agree ('
            + (read ? 'the request is for ' + reqSats + ' sats' + (reqMint && reqMint !== myMint ? ' at ' + reqMint : '') : 'the request could not be read')
            + ', the terms say ' + shownSats + '); nothing was sent');
          this.toast(!read ? 'Their request could not be read. Nothing was sent.'
            : 'Their request does not match the amount they quoted. Nothing was sent.', true);
          this.back();
          this.tapGaveNothing('their terms and their request did not agree');
          return;
        }
        this.crossFeeCard(terms, stuck, (offer.mints || [])[0]).then(yes => {
          if (!yes) return;            // `crossAnswer` has already left the screen
          console.log('[foxy] tap: paying ' + terms.sats + ' at ' + stuck.mint
                      + '; they carry it home and keep ' + (terms.net || want));
          /* Paid from here, with no second confirmation: the screen they just
           * agreed to IS this payment's confirmation. */
          read.viaTap = true;
          if (typeof offer.theirRoute === 'boolean') read.theirRoute = offer.theirRoute;
        if (offer.asks) read.asks = true;
          /* If they cannot bring it home, it comes back: the whole payment,
           * locked to this phone, over the link if it is still up. Noted so
           * that is taken as what it is and not refused as change nobody
           * owed (15-paid-wake-keyboard.js). */
          this._carriedPay = { sats: Math.round(Number(terms.sats) || 0), hash: '', until: Date.now() + 300000 };
          this.setState({ req: read, reqBusy: false, crossBusy: false, crossQ: null,
                          note: '', noteDraft: '' });
          this.makeTokenForRequest();
        });
      });
    }
    /* CALCULATING FEE, because that is what is happening: the fee is being
     * worked out, by their phone rather than this one, and which phone does
     * the arithmetic is not something the person paying needs to hold in
     * their head. */
    this.waitingScreen('priceSent', {
      art: 'mints', title: 'Calculating<br>fee', dots: true,
      body: 'The receiver uses another mint, wait while I calculate the fee to pay them.',
      button: 'CANCEL', go: () => { if (done('cancelled')) this.back(); },
    });
    console.log('[foxy] tap: stuck at ' + stuck.mint + ' with ' + stuck.have
                + ' sats and no route; asking them what bringing it home costs');
    this._tapQuoteT = setTimeout(() => {
      if (!done('they never answered')) return;
      this.toast('They did not answer. Nothing was sent.', true);
      this.back();
    }, 90000);
    W.tapQuote(JSON.stringify(said)).catch(e => {
      if (!done('the link went before this phone could ask')) return;
      this.toast(W.reason ? W.reason(e) : 'That phone is no longer connected.', true);
      this.back();
    });
  }

  /* They can only take ecash, and not at the mint this phone pays from.
   *
   * With a route on their side this never happens: there is an invoice, and the
   * invoice is what gets paid. It is the offline receive that lands here, where
   * the mint is the whole of the deal — the payment is proofs that mint issued,
   * handed over, and a mint that did not issue them will not take them.
   *
   * It said "a mint you hold nothing at", which is often untrue: `sameMint` is
   * only about the mint this wallet is *on*, and money sitting at their mint
   * under another tab is money that could pay this. Naming the mints, and
   * saying which of the two situations it is, is the difference between a wall
   * and an instruction.
   *
   * A card rather than a toast: two seconds is not long enough to read a mint
   * host, and nothing else on the screen says what went wrong.
   */
  tapWrongMint(offer) {
    const W = window.FoxyWallet;
    const theirs = (offer && offer.mints || []).map(m => String(m).replace(/\/+$/, ''));
    const name = (u) => this.mintNameOf(u) || String(u).replace(/^https?:\/\//, '') || 'their mint';
    const held = theirs.filter(m => W.balanceAt && W.balanceAt(m) > 0);
    const mine = this.mintNameOf(W.mintUrl) || String(W.mintUrl || '').replace(/^https?:\/\//, '');
    const asked = theirs.length ? name(theirs[0]) : 'their mint';
    this.tapGaveNothing('their mint is not one this phone can pay');
    this.blockedCard('wrongMint', {
      tone: 'warn',
      title: 'A DIFFERENT MINT',
      reason: held.length
        ? 'They can only be paid ecash from ' + asked + ', and Foxy is paying from '
          + (mine || 'another mint') + '. You do hold money at ' + name(held[0])
          + ' \u2014 switch to it and tap again.'
        : 'They can only be paid ecash from ' + asked + ', and you hold nothing there. '
          + 'Foxy is paying from ' + (mine || 'another mint') + '.',
      chip: held.length
        ? 'Nothing was sent.'
        : 'Nothing was sent. With a connection, Foxy could pay them over Lightning instead.',
      retry: held.length ? 'CHOOSE A MINT' : '',
      go: held.length ? () => this.goSwitchMint() : null,
    });
    console.log('[foxy] tap: they can only take ecash at ' + (theirs.join(' ') || '(no mint named)')
      + '; this phone pays from ' + (W.mintUrl || '?')
      + (held.length ? ' \u2014 but there is a balance at theirs' : ''));
    this.back();
  }

  /* The payer's half of the price talk (M10 out, M11 back).
   *
   * Nothing has left this phone and nothing will until they answer: the sats
   * are still here, the link is open, and what crosses is two numbers. A
   * refusal, a silence or a phone put away all end the same way — back where
   * the person was, with their money untouched.
   *
   * `personWait` on the link is 95 seconds. This is a little under it, so the
   * words on screen come from Foxy rather than from a link that went quiet. */
  tapQuoteTheirDollars(offer) {
    const W = window.FoxyWallet;
    const quote = W.quoteFor ? W.quoteFor(offer.read) : null;
    if (!quote) {
      /* No price, nothing honest to offer. Their request names no sats, so
       * this phone cannot pay it either — saying so beats a spinner. */
      this.tapGaveNothing('no bitcoin price to quote with');
      this.blockedCard('noPriceToQuote', {
        tone: 'warn',
        title: 'NO BITCOIN PRICE',
        reason: 'They asked for a dollar amount, and this phone has no bitcoin price to work out the sats from.',
        chip: 'Nothing was sent. Try again once Foxy has a price.',
      });
      this.back();
      return;
    }
    /* The mint question is worked out WHILE they are deciding.
     *
     * It used to wait for the answer, so agreeing a price was followed by
     * several more seconds of nothing while this phone asked two mints what a
     * crossing would cost. Those two questions do not depend on the answer at
     * all — the amount is the one this phone just offered, and the mints are
     * whatever they already are. So they are asked now, and the moment the
     * answer comes back the next screen is ready ("don't
     * wait for BTC price agreement to determine the mint").
     *
     * Nothing moves on it: a quote is two questions and a fee, and a refusal
     * throws it away unused. */
    this.tapPreQuoteMint(offer, quote.sats);
    const seq = (this._tapQuoteSeq = (this._tapQuoteSeq || 0) + 1);
    const done = (over) => {
      if (this._tapQuoteSeq !== seq) return false;
      this._tapQuoteSeq = 0;
      clearTimeout(this._tapQuoteT);
      if (W.onTapTerms) W.onTapTerms(null);
      this.dismissCard('priceSent');
      if (this.hideStage) this.hideStage('priceSent');
      // a talk that ended with no payment leaves nothing to protect
      if (over) this.tapGaveNothing(over);
      return true;
    };
    if (W.onTapTerms) {
      W.onTapTerms(text => {
        let said = null;
        try { said = JSON.parse(String(text || '')); } catch (e) {}
        // their invoice, arriving late on this same message: not their answer about the price
        if (said && typeof said.inv === 'string' && !said.req && !said.no && !said.why) {
          console.log('[foxy] tap: their invoice came in while they read the price; still waiting for the answer');
          return;
        }
        if (!done()) return;
        this.setState({ tapQuoteWait: false });
        if (!said || !said.req) {
          this.toast('They did not agree that price. Nothing was sent.', true);
          this.back();
          this.tapGaveNothing('they did not agree the price');
          return;
        }
        /* And it has to be for the sats this phone offered. The answer is
         * the other phone's word, and the crossing's fee screen shows the
         * figure it states: a request for more than was offered is not an
         * agreement to the offer, it is a different request. */
        const back = W.decodeRequest ? W.decodeRequest(String(said.req)) : null;
        const backSats = back ? Math.round(Number(back.sats) || 0) : 0;
        if (!back || backSats !== Math.round(Number(quote.sats) || 0)) {
          console.warn('[foxy] tap: they answered the price with a request for ' + backSats + ' sats, not the '
            + quote.sats + ' this phone offered; nothing was sent');
          this.toast('Their request does not match the amount this phone offered. Nothing was sent.', true);
          this.back();
          this.tapGaveNothing('their request was not for what was offered');
          return;
        }
        console.log('[foxy] tap: they agreed the price; the request is in sats now');
        /* The agreed request, on the offer it came from: the mints have not
         * changed — a receiver makes its request at its own mint either way —
         * so whether this is a same-mint payment or a transfer first is the
         * same question it was, now with a number in it. */
        this.tapPayOffer(Object.assign({}, offer, { req: String(said.req) }), backSats);
      });
    }
    /* Something on screen while they read.
     *
     * The wait is a person on the other phone looking at two numbers, which is
     * seconds at best, and a payer's phone with nothing on it reads as a broken
     * app — the same argument M9 exists for. CANCEL is real: nothing has left
     * this phone, so there is nothing to undo. */
    this.waitingScreen('priceSent', {
      art: 'phone', title: 'Waiting<br>for receiver', dots: true,
      body: 'This receiver is offline and must agree to the current Bitcoin price before continuing.',
      button: 'CANCEL', go: () => { if (done('cancelled')) this.back(); },
    });
    this.setState({ tapQuoteWait: true, tapQuoteSats: quote.sats, tapQuoteUsd: quote.usd });
    console.log('[foxy] tap: quoting ' + quote.sats + ' sats for $'
      + (quote.usd / 100).toFixed(2) + ' at $ ' + this.group(Math.round(quote.rate)) + ' per bitcoin');
    this._tapQuoteT = setTimeout(() => {
      if (!done('they never answered')) return;
      this.setState({ tapQuoteWait: false });
      this.toast('They did not answer about the price. Nothing was sent.', true);
      this.back();
    }, 90000);
    W.tapQuote(JSON.stringify(quote)).catch(e => {
      if (!done('the link went before the price could be sent')) return;
      this.setState({ tapQuoteWait: false });
      this.toast(W.reason ? W.reason(e) : 'That phone is no longer connected.', true);
      this.back();
    });
  }

  tapStatusText() {
    const s = this.state;
    switch (s.tapStage) {
      case 'far': return 'HOLD CLOSER';
      case 'nearby': return 'CONNECT TO PAY';
      /* Contact made is "connected" as far as the person holding the phone is
       * concerned: the two seconds between touching and having the offer are
       * Foxy's business, not theirs, and a CONNECTING that becomes CONNECTED is
       * two states where one will do. The code joins the
       * same word when it arrives, so nothing moves but the digits. */
      case 'connecting':
      case 'linked':
        /* One word, and only that word. The digits used to follow it here and
         * are on the confirmation a moment later, where they are big and next
         * to the amount — two places to read the same four numbers, one of
         * them while the phone is still being held against another phone. */
        return 'CONNECTED';
      case 'off': return 'TURN ON BLUETOOTH';
      case 'denied': return 'BLUETOOTH NOT ALLOWED';
      case 'unsupported': return 'NO BLUETOOTH';
      default: return 'SEARCHING';
    }
  }

  tapStatusHint() {
    switch (this.state.tapStage) {
      case 'off': return 'Turn Bluetooth on in Control Center.';
      case 'denied': return 'Allow Bluetooth for Foxy in Settings.';
      case 'unsupported': return 'This phone cannot do tap to pay.';
      case 'nearby': return 'A phone is close. Touch it to pay.';
      case 'connecting': return 'Hold still.';
      case 'linked': return 'Check the same code is on their screen.';
      default: return 'Hold your phone near theirs while their invoice is open.';
    }
  }
  /* The two full-screen loaders, drawn exactly as the design exports draw
   * them.
   *
   * The markup is lifted from those files rather than rewritten from a
   * description, because the loaders are to match the design exactly and a
   * reinterpretation is not that. The only changes are the
   * four the app forces: the screen fills the overlay instead of a phone frame,
   * a texture image that is not in the bundle is dropped (the ground reads the
   * same without it), the heading and the bill's two figures become
   * substitutions, and the CANCEL button is put in by the builder so a wait
   * with nothing safe to cancel can leave it out.
   *
   * Their keyframes live in the page's own stylesheet (build/markup.html), so
   * both loaders animate without a style element of their own.
   *
   * CONNECTING is the two phones and the dashes between them, for the moment
   * between the first buzz and the link being made. VERIFYING is the bill going
   * round, for every wait where money is the thing being waited on.
   */
  loaderConnecting() { return "<div style=\"position:relative;height:100%;overflow:hidden;display:flex;flex-direction:column;background:linear-gradient(170deg,#D3EDF4 0%,#C5E6EF 45%,#B5DDE9 80%,#A9D6E4 100%);color:#13333C\">\n\n      <div style=\"position:absolute;left:50%;top:44%;width:420px;height:420px;border-radius:50%;background:radial-gradient(circle, rgba(255,255,255,.75) 0%, rgba(255,255,255,0) 65%);animation:glowDrift 5s ease-in-out infinite;pointer-events:none\"></div>\n      \n\n      \n\n      <div style=\"position:relative;z-index:1;flex:1 1 auto;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:56px;padding:0 28px\">\n\n        <div style=\"position:relative;width:260px;height:150px;display:flex;align-items:center;justify-content:space-between\">\n\n          <div style=\"position:relative;width:72px;height:128px;animation:phoneBob 2.8s ease-in-out infinite\">\n            <div style=\"position:absolute;left:50%;top:50%;width:130px;height:130px;margin:-65px 0 0 -65px;border-radius:50%;border:2px solid rgba(19,51,60,.45);animation:wave 2.4s ease-out infinite\"></div>\n            <div style=\"position:absolute;left:50%;top:50%;width:130px;height:130px;margin:-65px 0 0 -65px;border-radius:50%;border:2px solid rgba(19,51,60,.45);animation:wave 2.4s ease-out .8s infinite\"></div>\n            <div style=\"position:absolute;left:50%;top:50%;width:130px;height:130px;margin:-65px 0 0 -65px;border-radius:50%;border:2px solid rgba(19,51,60,.45);animation:wave 2.4s ease-out 1.6s infinite\"></div>\n            <div style=\"position:relative;width:100%;height:100%;border-radius:16px;border:3px solid #13333C;background:rgba(255,255,255,.45);display:flex;align-items:center;justify-content:center\">\n              <div style=\"position:absolute;top:7px;width:20px;height:4px;border-radius:2px;background:#13333C;opacity:.8\"></div>\n              <svg viewBox=\"0 0 24 24\" fill=\"none\" style=\"width:30px;height:30px\"><path d=\"M13.5 2.5 5.5 13.5h5.5l-1 8 8-11h-5.5z\" fill=\"#13333C\"></path></svg>\n            </div>\n          </div>\n\n          <div style=\"position:absolute;left:86px;right:86px;top:50%;height:12px;margin-top:-6px\">\n            <div style=\"position:absolute;left:0;right:0;top:5px;border-top:2px dashed rgba(19,51,60,.3)\"></div>\n            <div style=\"position:absolute;inset:0;animation:travel 1.6s cubic-bezier(.45,0,.55,1) infinite\"><div style=\"width:12px;height:12px;border-radius:50%;background:#13333C;box-shadow:0 0 12px rgba(255,255,255,.9)\"></div></div>\n            <div style=\"position:absolute;inset:0;animation:travel 1.6s cubic-bezier(.45,0,.55,1) .53s infinite\"><div style=\"width:12px;height:12px;border-radius:50%;background:#13333C;box-shadow:0 0 12px rgba(255,255,255,.9)\"></div></div>\n            <div style=\"position:absolute;inset:0;animation:travel 1.6s cubic-bezier(.45,0,.55,1) 1.06s infinite\"><div style=\"width:12px;height:12px;border-radius:50%;background:#13333C;box-shadow:0 0 12px rgba(255,255,255,.9)\"></div></div>\n          </div>\n\n          <div style=\"position:relative;width:72px;height:128px;border-radius:16px;border:3px solid #13333C;background:rgba(255,255,255,.45);display:flex;align-items:center;justify-content:center;animation:receivePulse 1.6s ease-out infinite\">\n            <div style=\"position:absolute;top:7px;width:20px;height:4px;border-radius:2px;background:#13333C;opacity:.8\"></div>\n            <svg viewBox=\"0 0 24 24\" fill=\"none\" style=\"width:32px;height:32px\"><rect x=\"3.5\" y=\"3.5\" width=\"7\" height=\"7\" rx=\"1.5\" stroke=\"#13333C\" stroke-width=\"2\"></rect><rect x=\"13.5\" y=\"3.5\" width=\"7\" height=\"7\" rx=\"1.5\" stroke=\"#13333C\" stroke-width=\"2\"></rect><rect x=\"3.5\" y=\"13.5\" width=\"7\" height=\"7\" rx=\"1.5\" stroke=\"#13333C\" stroke-width=\"2\"></rect><path d=\"M14 14h2.5v2.5H14zM18 18h2.5v2.5H18zM18 14h2.5M14 18v2.5\" stroke=\"#13333C\" stroke-width=\"2\" stroke-linecap=\"round\"></path></svg>\n          </div>\n        </div>\n\n        <div style=\"display:flex;flex-direction:column;align-items:center;gap:12px;text-align:center\">\n          <h1 style=\"margin:0;font-weight:800;font-size:30px;line-height:1.1;letter-spacing:-.01em;text-transform:uppercase;color:#13333C\">{{TITLE}}</h1>\n          <div style=\"display:flex;gap:8px\">\n            <span style=\"width:8px;height:8px;border-radius:50%;background:#13333C;animation:dot 1.4s ease-in-out infinite\"></span>\n            <span style=\"width:8px;height:8px;border-radius:50%;background:#13333C;animation:dot 1.4s ease-in-out .2s infinite\"></span>\n            <span style=\"width:8px;height:8px;border-radius:50%;background:#13333C;animation:dot 1.4s ease-in-out .4s infinite\"></span>\n          </div>\n        </div>\n      </div>\n\n      {{CANCEL}}\n    </div>"; }

  loaderVerifying() { return "<div style=\"position:relative;height:100%;overflow:hidden;display:flex;flex-direction:column;background:linear-gradient(170deg,#D3EDF4 0%,#C5E6EF 45%,#B5DDE9 80%,#A9D6E4 100%);color:#13333C\">\n      <div style=\"position:absolute;left:50%;top:44%;width:420px;height:420px;border-radius:50%;background:radial-gradient(circle, rgba(255,255,255,.75) 0%, rgba(255,255,255,0) 65%);animation:glowDrift 5s ease-in-out infinite;pointer-events:none\"></div>\n      \n\n      \n\n      <div style=\"position:relative;z-index:1;flex:1 1 auto;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:56px;padding:0 28px\">\n        <div style=\"position:relative;width:240px;height:150px;display:flex;align-items:center;justify-content:center\">\n          <div style=\"position:absolute;left:50%;top:50%;width:230px;height:230px;margin:-115px 0 0 -115px;border-radius:50%;border:2px dashed rgba(19,51,60,.2);animation:orbit 18s linear infinite\"></div>\n          <div style=\"position:absolute;left:50%;top:50%;width:230px;height:230px;margin:-115px 0 0 -115px;animation:orbit 2.4s linear infinite\"><div style=\"position:absolute;left:50%;top:-6px;width:12px;height:12px;margin-left:-6px;border-radius:50%;background:#13333C;box-shadow:0 0 12px rgba(255,255,255,.9)\"></div></div>\n\n          <div style=\"position:relative;width:200px;height:86px;animation:billFloat 3.2s ease-in-out infinite\">\n            <div style=\"position:absolute;inset:0;border-radius:8px;background:#FFFFFF;box-shadow:0 14px 30px rgba(19,51,60,.22);overflow:hidden\">\n              <div style=\"position:absolute;inset:5px;border-radius:5px;border:1.5px solid #2D6273;background:repeating-linear-gradient(135deg, rgba(45,98,115,.08) 0 2px, transparent 2px 6px)\"></div>\n              <div style=\"position:absolute;inset:10px;border-radius:3px;border:1px dashed rgba(45,98,115,.5)\"></div>\n              <div style=\"position:absolute;left:50%;top:50%;width:44px;height:44px;margin:-22px 0 0 -22px;border-radius:50%;border:1.5px solid #2D6273;background:#FFFFFF;display:flex;align-items:center;justify-content:center\">\n                <svg viewBox=\"0 0 24 24\" fill=\"none\" style=\"width:24px;height:24px\"><path d=\"M12 3v18M7 8h10M7 12h10M7 16h10\" stroke=\"#13333C\" stroke-width=\"2.4\" stroke-linecap=\"round\"></path></svg>\n              </div>\n              <div style=\"position:absolute;left:16px;top:14px;font-family:'Sora',sans-serif;font-weight:800;font-size:10px;letter-spacing:.08em;color:#13333C;;display:flex;align-items:center;gap:1px\"><svg viewBox=\"0 0 24 24\" fill=\"none\" style=\"width:11px;height:11px\"><path d=\"M12 3v18M7 8h10M7 12h10M7 16h10\" stroke=\"#13333C\" stroke-width=\"3\" stroke-linecap=\"round\"></path></svg>{{SATS}}</div>\n              <div style=\"position:absolute;right:16px;bottom:14px;font-family:'Sora',sans-serif;font-weight:800;font-size:10px;letter-spacing:.08em;color:#13333C;\">{{MINT}}</div>\n              <div style=\"position:absolute;left:0;right:0;height:18px;background:linear-gradient(180deg, rgba(255,255,255,0) 0%, rgba(191,227,236,.95) 50%, rgba(255,255,255,0) 100%);animation:scan 1.6s cubic-bezier(.45,0,.55,1) infinite alternate\"></div>\n            </div>\n          </div>\n        </div>\n\n        <div style=\"display:flex;flex-direction:column;align-items:center;gap:12px;text-align:center\">\n          <h1 style=\"margin:0;font-weight:800;font-size:30px;line-height:1.1;letter-spacing:-.01em;text-transform:uppercase;color:#13333C\">{{TITLE}}</h1>\n          <div style=\"display:flex;gap:8px\">\n            <span style=\"width:8px;height:8px;border-radius:50%;background:#13333C;animation:dot 1.4s ease-in-out infinite\"></span>\n            <span style=\"width:8px;height:8px;border-radius:50%;background:#13333C;animation:dot 1.4s ease-in-out .2s infinite\"></span>\n            <span style=\"width:8px;height:8px;border-radius:50%;background:#13333C;animation:dot 1.4s ease-in-out .4s infinite\"></span>\n          </div>\n        </div>\n      </div>\n\n      {{CANCEL}}\n    </div>"; }

  /* ---- the waiting and the asking screens (from the design exports) ----
   *
   * One ground, one heading, one paragraph and
   * one button, with a piece of art or a code above them. They replace the
   * cards that used to say these things, because a card is a note over a
   * screen and each of these IS the screen for as long as it lasts — two
   * people are standing together and one of them is waiting on the other.
   *
   * Drawn from the exports' own markup. What the app changes: the texture is
   * the fur already in the bundle (snow-fur.jpg, the same picture), the code is
   * a real one, and the amount and the words are filled in.
   *
   * One at a time. `kind` names it, so whatever put one up can take down its
   * own and nothing else's.
   */
  STAGE_ART = {
    phone: '<div style="position:relative;width:72px;height:128px;border-radius:16px;border:3px dashed #13333C;background:rgba(255,255,255,.45);display:flex;align-items:center;justify-content:center;animation:offlineFade 2.4s ease-in-out infinite">'
      + '<div style="position:absolute;top:7px;width:20px;height:4px;border-radius:2px;background:#13333C;opacity:.8"></div>'
      + '<div style="position:relative;width:34px;height:34px;border-radius:50%;border:3px solid #13333C">'
      + '<div style="position:absolute;left:50%;top:50%;width:3px;height:10px;margin:-10px 0 0 -1.5px;border-radius:2px;background:#13333C;transform-origin:50% 100%;animation:hand 3s linear infinite"></div>'
      + '<div style="position:absolute;left:50%;top:50%;width:3px;height:7px;margin:-7px 0 0 -1.5px;border-radius:2px;background:#13333C;transform-origin:50% 100%;transform:rotate(90deg)"></div>'
      + '</div></div>',
    /* A card held to the phone: its outline, its chip, and the contactless
     * mark breathing beside it (the FLASHCARD screens, 26f-flashcard.js). */
    card: '<div style="position:relative;width:150px;height:96px;border-radius:14px;border:3px dashed #13333C;background:rgba(255,255,255,.45);animation:offlineFade 2.4s ease-in-out infinite">'
      + '<div style="position:absolute;left:16px;top:30px;width:30px;height:24px;border-radius:5px;border:3px solid #13333C;box-sizing:border-box"></div>'
      + '<svg viewBox="0 0 24 24" fill="none" stroke="#13333C" stroke-width="2.2" stroke-linecap="round" style="position:absolute;right:14px;top:24px;width:44px;height:44px">'
      + '<path d="M7.75 9A3.5 3.5 0 0 1 7.75 15M9.25 6.4A6.5 6.5 0 0 1 9.25 17.6M10.75 3.8A9.5 9.5 0 0 1 10.75 20.2"></path></svg>'
      + '</div>',
    mints: (function () {
      var bank = '<svg viewBox="0 0 64 64" fill="none" style="width:64px;height:64px"><path d="M6 22 32 8l26 14z" fill="#13333C"></path><rect x="8" y="24" width="48" height="4" rx="1" fill="#13333C"></rect><rect x="12" y="31" width="6" height="19" rx="1.5" fill="#13333C"></rect><rect x="23" y="31" width="6" height="19" rx="1.5" fill="#13333C"></rect><rect x="35" y="31" width="6" height="19" rx="1.5" fill="#13333C"></rect><rect x="46" y="31" width="6" height="19" rx="1.5" fill="#13333C"></rect><rect x="6" y="52" width="52" height="5" rx="1.5" fill="#13333C"></rect></svg>';
      var side = function (name) {
        return '<div style="display:flex;flex-direction:column;align-items:center;gap:8px">' + bank
          + '<span style="font-weight:800;font-size:11px;letter-spacing:.14em;color:#13333C">' + name + '</span></div>';
      };
      return '<div style="position:relative;width:260px;display:flex;flex-direction:column;align-items:center">'
        + '<div style="position:relative;width:100%;display:flex;align-items:flex-end;justify-content:space-between">'
        + side('YOUR MINT')
        + '<div style="position:absolute;left:78px;right:78px;top:24px;height:22px">'
        + '<div style="position:absolute;left:0;right:0;top:20px;border-top:2px dashed rgba(19,51,60,.3)"></div>'
        + '<div style="position:absolute;inset:0;width:calc(100% - 22px);animation:coinHop 1.8s ease-in-out infinite">'
        + '<div style="width:22px;height:22px;border-radius:50%;background:#13333C;display:flex;align-items:center;justify-content:center;box-shadow:0 0 12px rgba(255,255,255,.9)"><svg viewBox="0 0 24 24" fill="none" style="width:13px;height:13px"><path d="M12 3v18M7 8h10M7 12h10M7 16h10" stroke="#FFFFFF" stroke-width="3" stroke-linecap="round"></path></svg></div>'
        + '</div></div>'
        + side('THEIR MINT')
        + '</div></div>';
    })(),
  };

  /* `o`: art ('phone' | 'mints' | ''), title (may hold <br>), amount, body (may
   * hold <br> and <strong>), code (the four digits), qr (text to draw), dots,
   * button, go, and `keep` to leave the screen up after the button. */
  stageScreen(kind, o) {
    this.hideStage();
    const W = window.FoxyWallet;
    const esc = (t) => String(t == null ? '' : t).replace(/[&<>"]/g,
      (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[c]));
    const root = document.createElement('div');
    root.id = 'foxy-stage';
    root.setAttribute('data-stage', kind);
    root.style.cssText = 'position:fixed;inset:0;z-index:2147483300;display:flex;flex-direction:column;'
      + 'overflow:hidden;background:linear-gradient(170deg,#D3EDF4 0%,#C5E6EF 45%,#B5DDE9 80%,#A9D6E4 100%);'
      + "color:#13333C;font-family:Sora,system-ui,sans-serif;animation:foxyIn .18s ease";
    const hasQr = !!(o.qr && W && W.qr);
    const head = '<h1 style="margin:0;font-weight:800;font-size:30px;line-height:1.1;letter-spacing:-.01em;'
      + 'text-transform:uppercase;color:#13333C">' + o.title + '</h1>';
    const amount = o.amount
      ? '<div style="font-weight:800;font-size:44px;line-height:1;letter-spacing:-.03em;color:#13333C">'
        + esc(o.amount) + '</div>' : '';
    const body = o.body
      ? '<p style="margin:0;max-width:300px;text-align:center;font-family:Figtree,Sora,system-ui,sans-serif;'
        + 'font-weight:500;font-size:17px;line-height:1.45;color:#13333C;text-wrap:pretty">' + o.body + '</p>' : '';
    /* The four digits, where this screen covers the one that was showing
     * them. They are what the two people compare, and a waiting screen that
     * hid them would hide the one check the tap has. */
    const code = o.code
      ? '<div style="display:flex;flex-direction:column;align-items:center;gap:4px">'
        + '<span style="font-weight:800;font-size:11px;letter-spacing:.14em;opacity:.7">THEIR SCREEN SHOWS</span>'
        + '<span style="font-weight:800;font-size:40px;letter-spacing:.12em;line-height:1">' + esc(o.code) + '</span></div>' : '';
    const dots = o.dots
      ? '<div style="display:flex;gap:8px;margin-top:4px">'
        + [0, .2, .4].map((d) => '<span style="width:8px;height:8px;border-radius:50%;background:#13333C;'
          + 'animation:dot 1.4s ease-in-out ' + d + 's infinite"></span>').join('') + '</div>' : '';
    // full width on its own; smaller when rows share the screen with it
    const qrSize = (o.rows && o.rows.length) ? 'min(58vw,236px)' : 'min(100vw - 84px,420px)';
    const qr = hasQr
      ? '<div style="position:relative;padding:14px;border-radius:24px;background:#FFFFFF;'
        + 'box-shadow:0 18px 40px rgba(19,51,60,.22)"><img data-stage-qr alt="" '
        + 'style="width:' + qrSize + ';height:' + qrSize + ';display:block;image-rendering:pixelated"></div>' : '';
    /* Label-and-value rows under the code, for a screen with more than one
     * number on it (the change card's three). */
    const rows = (o.rows && o.rows.length)
      ? '<div style="width:100%;max-width:320px;display:flex;flex-direction:column">'
        + o.rows.map((r) => '<div style="display:flex;justify-content:space-between;align-items:baseline;gap:12px;'
          + 'padding:9px 0;border-top:1px solid rgba(19,51,60,.14)">'
          + '<span style="font-weight:700;font-size:12px;letter-spacing:.1em;opacity:.7">' + esc(r.label) + '</span>'
          + '<span style="font-weight:800;font-size:19px;letter-spacing:-.01em;white-space:nowrap">' + esc(r.value) + '</span></div>').join('')
        + '</div>' : '';
    const art = this.STAGE_ART[o.art] || '';
    root.innerHTML =
      '<div style="position:absolute;left:50%;top:44%;width:420px;height:420px;border-radius:50%;'
      + 'background:radial-gradient(circle, rgba(255,255,255,.75) 0%, rgba(255,255,255,0) 65%);'
      + 'animation:glowDrift 5s ease-in-out infinite;pointer-events:none"></div>'
      + '<div style="position:absolute;inset:-10%;background-image:url(snow-fur.jpg);background-size:cover;'
      + 'background-position:center;mix-blend-mode:soft-light;opacity:.18;animation:grain 14s ease-in-out infinite;'
      + 'pointer-events:none"></div>'
      + '<div style="position:relative;z-index:1;flex:1 1 auto;display:flex;flex-direction:column;align-items:center;'
      + 'justify-content:center;gap:' + (hasQr ? '18px' : art ? '56px' : '40px')
      + ';padding:calc(20px + env(safe-area-inset-top)) 28px 0">'
      + (hasQr
          ? '<div style="display:flex;flex-direction:column;align-items:center;gap:10px;text-align:center">' + head + amount + '</div>'
            + qr + rows + body
          : art + '<div style="display:flex;flex-direction:column;align-items:center;gap:14px;text-align:center">'
            + head + amount + body + code + dots + '</div>')
      + '</div>';
    const wrap = document.createElement('div');
    wrap.style.cssText = 'position:relative;z-index:1;padding:20px 24px calc(44px + env(safe-area-inset-bottom))';
    const b = document.createElement('div');
    b.style.cssText = 'width:100%;height:60px;border-radius:18px;border:2px solid rgba(19,51,60,.85);'
      + "background:rgba(255,255,255,.35);font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:17px;"
      + 'letter-spacing:.04em;text-transform:uppercase;color:#13333C;display:flex;align-items:center;'
      + 'justify-content:center;cursor:pointer';
    /* A button above the main one, for something to do that does not end the
     * screen: sharing the code with somebody who is not in the room. */
    if (o.above) {
      const u = document.createElement('div');
      u.style.cssText = b.style.cssText + ';margin-bottom:12px;background:#13333C;color:#fff';
      u.textContent = o.above;
      u.addEventListener('click', () => { if (typeof o.aboveGo === 'function') o.aboveGo(); });
      wrap.appendChild(u);
    }
    b.textContent = o.button || 'CANCEL';
    // found by a screen that takes its button away part-way through (26f-flashcard.js)
    b.setAttribute('data-stage-button', '1');
    b.addEventListener('click', () => {
      if (!o.keep) this.hideStage(kind);
      if (typeof o.go === 'function') o.go();
    });
    wrap.appendChild(b);
    /* A second way out, in plain words under the button, for a screen whose
     * one button is not always the right answer. */
    if (o.alt) {
      const a = document.createElement('div');
      a.style.cssText = "margin-top:14px;text-align:center;font-family:Sora,system-ui,sans-serif;font-weight:800;"
        + 'font-size:14px;letter-spacing:.1em;color:#13333C;opacity:.75;cursor:pointer;padding:6px';
      a.textContent = o.alt;
      a.addEventListener('click', () => { this.hideStage(kind); if (typeof o.altGo === 'function') o.altGo(); });
      wrap.appendChild(a);
    }
    root.appendChild(wrap);
    document.body.appendChild(root);
    if (this.syncPreview) this.syncPreview();
    console.log('[foxy] screen: ' + kind + (hasQr ? ', with a code of ' + String(o.qr).length + ' chars' : ''));

    if (hasQr) {
      const img = root.querySelector('[data-stage-qr]');
      const text = String(o.qr);
      const moving = !!(W.tokenQrAnimates && W.tokenQrAnimates(text) && W.animatedQr);
      if (moving) {
        // the token screen's own frames, read by the same scanners (syncTokenQr)
        const frames = W.animatedQr(text, this.TOKEN_QR.fragment);
        const tick = () => {
          const src = W.qr(frames.next(), { ecc: this.TOKEN_QR.ecc });
          if (src && img) img.setAttribute('src', src);
        };
        tick();
        this._stageQrT = setInterval(tick, this.TOKEN_QR.everyMs);
      } else {
        const src = W.qr(text);
        if (src && img) img.setAttribute('src', src);
      }
    }
    /* A screen that outlives what it was waiting for hides a working app, the
     * rule the loaders follow. Only the waits: a code somebody has been asked
     * to scan stays until they say they are done. */
    if (o.dots) {
      this._stageT = setTimeout(() => this.hideStage(kind), Number(o.forMs) || 100000);
    }
  }

  /* Down, if it is this one — or whichever is up, when nothing is named. */
  hideStage(kind) {
    const old = document.getElementById('foxy-stage');
    if (!old) return false;
    if (kind && old.getAttribute('data-stage') !== kind) return false;
    clearTimeout(this._stageT);
    clearInterval(this._stageQrT);
    this._stageT = null; this._stageQrT = null;
    if (old.parentNode) old.parentNode.removeChild(old);
    if (this.syncPreview) this.syncPreview();
    return true;
  }

  stageUp(kind) {
    const el = document.getElementById('foxy-stage');
    return !!el && (!kind || el.getAttribute('data-stage') === kind);
  }

  /* An amount for a heading: dollars where this phone has a price to say them
   * at, the sats where it has not. */
  stageMoney(sats) {
    const n = Math.round(Number(sats) || 0);
    const px = this.px ? this.px() : 0;
    // under half a cent, the sats: "$ 0.00" of change owed is a wrong number (one sat)
    if (px && n > 0 && (n / 1e8) * px < 0.005) return '₿ ' + this.group(n);
    return px ? '$ ' + this.usd((n / 1e8) * px) : '₿ ' + this.group(n);
  }

  /* CONNECTING TO INVOICE, on both phones, from the payer's first buzz until
   * the link is made.
   *
   * The two are looking at each other across a table and what they need to know
   * is the same thing — that something is happening and roughly how far along
   * it is. The payer was told by a vibration and nothing else, and the receiver
   * by its own screen not changing.
   *
   * CANCEL is real here and only here: nothing has been swapped, nothing has
   * left, and letting go costs the person nothing but the tap.
   */
  showConnecting(onCancel) {
    if (document.getElementById('foxy-connecting')) return;
    const root = document.createElement('div');
    root.id = 'foxy-connecting';
    root.style.cssText = 'position:fixed;inset:0;z-index:2147483300;'
      + 'display:flex;flex-direction:column;animation:foxyIn .18s ease';
    root.innerHTML = this.loaderConnecting()
      .replace('{{TITLE}}', 'Connecting<br>to invoice')
      .replace('{{CANCEL}}', '');
    const wrap = document.createElement('div');
    wrap.style.cssText = 'position:absolute;left:0;right:0;bottom:0;z-index:2;'
      + 'padding:0 24px calc(44px + env(safe-area-inset-bottom))';
    const b = document.createElement('div');
    b.style.cssText = 'width:100%;height:60px;border-radius:18px;'
      + 'border:2px solid rgba(19,51,60,.85);background:rgba(255,255,255,.35);'
      + "font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:17px;"
      + 'letter-spacing:.08em;color:#13333C;display:flex;align-items:center;'
      + 'justify-content:center;cursor:pointer';
    b.textContent = 'CANCEL';
    b.addEventListener('click', () => {
      this.hideConnecting();
      if (typeof onCancel === 'function') onCancel();
    });
    wrap.appendChild(b);
    root.appendChild(wrap);
    document.body.appendChild(root);
    if (this.syncPreview) this.syncPreview();
    /* A loader that outlives its task hides a working screen, the same rule the
     * melt overlay follows. The link's own patience is well under this. */
    clearTimeout(this._connT);
    this._connT = setTimeout(() => this.hideConnecting(), 40000);
  }

  hideConnecting() {
    clearTimeout(this._connT);
    const old = document.getElementById('foxy-connecting');
    if (old && old.parentNode) old.parentNode.removeChild(old);
    if (old && this.syncPreview) this.syncPreview();
  }

  /* TAP TO PAY: a receiver is close by and the payer is on home or SEND. A
   * tall toast from the top edge of the screen down to the bottom of the
   * balance pill ("+1,362 last 24 hours"), with the tap icon ringing out. It measures the pill each time it is shown; with no
   * pill on the screen it takes a fixed height. The native side says `nearby`
   * about once a second while the receiver is heard, so the toast is renewed
   * on each and takes itself down 1.6 s after the last. */
  /* What both CONNECT TO PAY cards are drawn from: the mark at the edge the
   * phones should touch, an arrow in it pointing at that edge, and the words. `edge` is which side of this screen the mark
   * sits on — the payer's left meets the receiver's right, which is where the
   * antennas are closest. The accent, black ink,
   * and the light that sweeps across every two seconds. */
  /* Which edge the mark sits on is told with the `nearby` event: it depends
   * on the pair of phones and who is paying (TapEdges, TapProtocol.swift —
   * a 17 Pro uses its left against an XS and its right against a 15 Pro Max),
   * and the native side works it out. `left` is the layout for anything it
   * could not. */
  ctpParts(edge, withX) {
    const left = edge === 'left';
    const INK = '#050505';
    /* One arrow in the half of the mark that shows, pointing at the edge of
     * the screen, thin with a small open head, and giving the little hop the
     * reference design has: it darts at the edge, squashes against it,
     * springs back past where it started and settles.
     * The mark itself beats like a heart: boom boom, a rest, boom boom. */
    const arrow = '<svg viewBox="0 0 34 16" width="34" height="16" fill="none" stroke="var(--acc)" stroke-width="2.6" '
      + 'stroke-linecap="round" stroke-linejoin="round" style="position:absolute;top:48px;' + (left ? 'left:82px' : 'left:24px')
      + ';transform-origin:' + (left ? '0% 50%' : '100% 50%') + ';animation:' + (left ? 'foxyCtpHopL' : 'foxyCtpHopR')
      + ' .93s ease-in-out infinite"><path d="' + (left ? 'M32 8 L2 8 M8 2 L2 8 L8 14' : 'M2 8 L32 8 M26 2 L32 8 L26 14') + '"></path></svg>';
    return '<div style="position:absolute;top:0;bottom:0;left:0;width:40%;background:linear-gradient(100deg,rgba(255,255,255,0) 0%,rgba(255,255,255,.45) 50%,rgba(255,255,255,0) 100%);animation:foxyNearbySweep 2s ease-out infinite;pointer-events:none"></div>'
      + '<div style="position:absolute;' + (left ? 'left:-70px' : 'right:-70px') + ';top:50%;margin-top:-65px;width:140px;height:130px;animation:foxyCtpBeat 1.9s ease-in-out infinite;pointer-events:none">'
      + '<div style="position:absolute;inset:0;animation:foxyCtpGlow 1.9s ease-in-out infinite">'
      + '<svg viewBox="0 0 100 92" width="140" height="130" fill="none"><path d="M50 90 C20 68 2 50 2 28 C2 13 14 2 28 2 C38 2 46 8 50 16 C54 8 62 2 72 2 C86 2 98 13 98 28 C98 50 80 68 50 90 Z" fill="' + INK + '"></path></svg></div>'
      + arrow + '</div>'
      // the words, centred in what the mark leaves of the card
      + '<div style="position:absolute;left:' + (left ? 'calc(70px + (100% - 70px) / 2)' : 'calc((100% - 70px) / 2)') + ';top:50%;transform:translate(-50%,-50%);font-family:Sora,system-ui,sans-serif;font-weight:800;font-size:min(42px,10.4vw);line-height:1.02;color:' + INK + ';text-align:left;white-space:nowrap;pointer-events:none">CONNECT<br>TO PAY</div>'
      // the payer's sheet has no X: pressing it connects, and it goes when the receiver does.
      // The receiver's sits in the corner away from the mark.
      + (!withX ? '' : '<div data-ctp-x="1" style="position:absolute;' + (left ? 'right:16px' : 'left:16px') + ';top:16px;width:44px;height:44px;border-radius:50%;background:' + INK + ';display:flex;align-items:center;justify-content:center;cursor:pointer">'
      + '<svg viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="var(--acc)" stroke-width="2.6" stroke-linecap="round" style="pointer-events:none"><path d="M4 4 L16 16 M16 4 L4 16"></path></svg></div>');
  }

  /* CONNECT TO PAY on the payer: a receiver is close by and this phone is on
   * home or SEND. A sheet from the top edge of the screen down to the bottom
   * of the balance pill, with the mark on the edge to hold against the other
   * phone (it was TAP TO PAY with the
   * tap icon in the middle). The native side says `nearby` about once a
   * second while the receiver is heard, so the sheet is renewed on each and
   * takes itself down 1.6 s after the last. */
  showTapNearby(edge) {
    const side = edge === 'right' ? 'right' : 'left';
    clearTimeout(this._nearT);
    this._nearT = setTimeout(() => this.hideTapNearby(), 1600);
    const pill = document.querySelector('[data-foxy-delta-pill]');
    const bottom = pill ? Math.round(pill.getBoundingClientRect().bottom) : 0;
    const height = bottom > 80 ? bottom : 220;
    let root = document.getElementById('foxy-tap-nearby');
    if (root && root.getAttribute && root.getAttribute('data-edge') === side) { root.style.height = height + 'px'; return; }
    // the other phone's model has just been read, and the edge with it: drawn again
    if (root && root.parentNode) root.parentNode.removeChild(root);
    root = document.createElement('div');
    root.id = 'foxy-tap-nearby';
    root.style.cssText = 'position:fixed;left:0;right:0;top:0;z-index:2147483200;'
      + 'background:var(--acc);border-radius:0 0 30px 30px;box-shadow:0 12px 30px rgba(var(--acc-rgb),.35);'
      + 'overflow:hidden;pointer-events:none;animation:foxyNearbyIn .55s cubic-bezier(.22,1,.36,1) both';
    root.style.height = height + 'px';
    if (root.setAttribute) root.setAttribute('data-edge', side);
    root.innerHTML = this.ctpParts(side, false);
    /* Not a button, for now. Pressing it took the receiver from a couple of
     * metres without the phones touching; the touch is meant to be the only
     * way in while the rest is tried (the handshake waits for the phones to
     * be touching: `nearDbm`, TapProtocol.swift). The card says where to hold
     * the phone and nothing else. `tapPayNow` and the native side of it are left in place. */
    document.body.appendChild(root);
  }

  hideTapNearby() {
    clearTimeout(this._nearT);
    const old = document.getElementById('foxy-tap-nearby');
    if (old && old.parentNode) old.parentNode.removeChild(old);
  }

  /* And on the receiver: a payer has said it is near (the third door,
   * TapLink.swift), so the QR's place is taken by the same card, the mark on
   * the edge the payer's door named. Full width, over where the code is; the code is
   * still underneath, and the X — or the payer going away, or the handshake
   * starting — gives it back. It changes a picture: nothing about the tap
   * depends on it. */
  showConnectRecv(edge) {
    /* With the phone lying top-down the whole page is turned through 180
     * degrees (syncFlip), and this card turns with it. Two things follow.
     * The edge the payer named is an edge of the PHONE, and on a page turned
     * round the phone's right is the page's left — so the mark swaps sides.
     * And the code's place is measured on the screen, while the card is
     * placed on the turned page — so its top is measured from the other end.
     * Unturned, the card covered the amount and pointed at the wrong edge. */
    const turned = !!this._flipOn;
    const named = edge === 'left' ? 'left' : 'right';
    const side = turned ? (named === 'left' ? 'right' : 'left') : named;
    const key = side + (turned ? ':turned' : '');
    if (Date.now() < (this._ctpRecvOffUntil || 0)) return;
    const was = document.getElementById('foxy-connect-recv');
    if (was && was.getAttribute && was.getAttribute('data-edge') === key) return;
    if (was && was.parentNode) was.parentNode.removeChild(was);
    const img = document.querySelector('[data-req-qr]');
    const box = img && img.parentElement ? img.parentElement.getBoundingClientRect() : null;
    const tall = (typeof window !== 'undefined' && window.innerHeight) || 800;
    const seen = box && box.height > 80;
    const top = !seen ? Math.round(tall * 0.42) : Math.round(turned ? tall - box.bottom : box.top);
    const height = seen ? Math.round(box.height) : 300;
    const root = document.createElement('div');
    root.id = 'foxy-connect-recv';
    root.style.cssText = 'position:fixed;left:0;right:0;z-index:2147483100;background:var(--acc);'
      + 'border-radius:30px;overflow:hidden;animation:foxyIn .2s ease';
    root.style.top = top + 'px';
    root.style.height = height + 'px';
    if (root.setAttribute) root.setAttribute('data-edge', key);
    root.innerHTML = this.ctpParts(side, true);
    root.addEventListener('click', (e) => {
      const t = /** @type {any} */ (e && e.target);
      const x = t && t.closest && t.closest('[data-ctp-x]');
      if (!x) return;
      console.log('[foxy] tap: CONNECT TO PAY put away on the invoice');
      this._ctpRecvOffUntil = Date.now() + 20000;
      this.hideConnectRecv();
    });
    document.body.appendChild(root);
  }

  /* GET DOLLARS: informational, and deliberately nothing else.
   *
   * Four companies that take bitcoin and pay dollars to a bank. Foxy saves no
   * username, looks nothing up and pays nobody from here — an earlier design
   * did all three and every hole in it was one of those (a typo paying a
   * stranger, an identity kept on the phone, a lookup over Tor that may be
   * refused). The person makes an account there and comes back to SEND.
   *
   * A tile opens that company's site in the phone's browser, by name: the
   * addresses themselves are on the native side (openCompany). The icons are
   * each company's own, as the App Store shows them (Web/gd-*.jpg). */
  showGetDollars() {
    this.hideGetDollars();
    const W = window.FoxyWallet;
    const apps = [
      { key: 'cashapp', icon: 'gd-cashapp.jpg', name: 'CASH APP', url: 'cash.app' },
      { key: 'strike', icon: 'gd-strike.jpg', name: 'STRIKE', url: 'strike.me' },
      { key: 'river', icon: 'gd-river.jpg', name: 'RIVER', url: 'river.com' },
      { key: 'flash', icon: 'gd-flash.jpg', name: 'FLASH', url: 'getflash.io' },
    ];
    const root = document.createElement('div');
    root.id = 'foxy-get-dollars';
    root.style.cssText = 'position:fixed;inset:0;z-index:2147483200;display:flex;flex-direction:column;'
      + 'box-sizing:border-box;padding:calc(34px + env(safe-area-inset-top)) 24px calc(28px + env(safe-area-inset-bottom));'
      + 'background:var(--bg,#050505);color:rgb(var(--ink-rgb,255,255,255));'
      + "font-family:Sora,system-ui,sans-serif;overflow-y:auto;animation:foxyIn .18s ease";
    const para = 'margin:0;font-weight:500;font-size:18px;line-height:1.42;text-align:center;'
      + 'color:rgba(var(--ink-rgb,255,255,255),.84)';
    root.innerHTML = ''
      + '<div style="text-align:center;font-weight:800;font-size:24px;letter-spacing:.01em">GET DOLLARS</div>'
      + '<div style="flex:0 0 1px;height:1px;margin:20px 4px 0;background:rgba(var(--ink-rgb,255,255,255),.14)"></div>'
      + '<p style="' + para + ';margin-top:24px">These apps let you sell your bitcoin and deposit dollars into your bank account.</p>'
      + '<div style="margin:28px auto 0;display:grid;grid-template-columns:1fr 1fr;gap:22px 34px;width:fit-content">'
      + apps.map(a => ''
        + '<div data-gd="' + a.key + '" style="display:flex;flex-direction:column;align-items:center;gap:9px;cursor:pointer">'
        + '<img alt="" src="' + a.icon + '" style="display:block;box-sizing:border-box;width:96px;height:96px;'
        + 'border-radius:22px;border:1px solid rgba(var(--ink-rgb,255,255,255),.16);box-shadow:0 6px 16px rgba(0,0,0,.45)">'
        + '<div style="font-weight:700;font-size:14px;letter-spacing:.04em;white-space:nowrap">' + a.name + '</div>'
        + '<div style="margin-top:-4px;font-weight:500;font-size:13px;white-space:nowrap;color:rgba(var(--ink-rgb,255,255,255),.55)">' + a.url + '</div>'
        + '</div>').join('')
      + '</div>'
      + '<p style="' + para + ';margin-top:28px">Create an account with one of them and ask your AI how to receive bitcoin and sell it for dollars on that app.</p>'
      + '<div style="flex:1 1 auto;min-height:24px"></div>'
      + '<div data-gd-close="1" style="flex:0 0 auto;height:58px;border-radius:30px;background:var(--acc);color:#050505;'
      + 'display:flex;align-items:center;justify-content:center;font-weight:800;font-size:20px;letter-spacing:.04em;cursor:pointer">CLOSE</div>';
    root.addEventListener('click', (e) => {
      const t = /** @type {any} */ (e && e.target);
      if (!t || !t.closest) return;
      if (t.closest('[data-gd-close]')) { this.hideGetDollars(); return; }
      const hit = t.closest('[data-gd]');
      if (hit && W && W.openCompany) {
        this.haptic && this.haptic('tap');
        W.openCompany(hit.getAttribute('data-gd'));
      }
    });
    document.body.appendChild(root);
  }

  hideGetDollars() {
    const old = document.getElementById('foxy-get-dollars');
    if (old && old.parentNode) old.parentNode.removeChild(old);
  }

  hideConnectRecv() {
    const old = document.getElementById('foxy-connect-recv');
    if (old && old.parentNode) old.parentNode.removeChild(old);
  }
  /* ---- FLASHCARD: a card that holds ecash ----------------------------------
   *
   * The screens over the wallet's card functions (build/wallet/08a-flashcard.js
   * and 21a-flashcard.js). Two places use them:
   *
   *   the receive screen's CARD button   somebody pays this phone with their
   *                                      card: its PIN on this phone's pad,
   *                                      a tap, paid or not;
   *   MENU > FLASHCARD                   a holder's own card: what it holds,
   *                                      money on and off it, its PIN and its
   *                                      limit, and the cards this phone can
   *                                      take back if they are lost.
   *
   * The daily limit is the most the card signs for in one day. The card keeps
   * its own clock (told the time by every phone that taps it), counts the whole
   * worth of every piece it signs against the day it falls in, and starts the
   * count again by itself when the day is over. A card has none until its owner
   * sets one; only the phone that holds the words the card was set up with, the
   * owner, can set, change or remove it, change the card's PIN, or add funds
   * without the PIN. While the time the card is told comes from the receiving
   * phone's own clock (build/wallet/08a-flashcard.js, CARD_TIME_KEY), the limit
   * bounds an honest receiver and the holder's own overspending, and nothing is
   * said anywhere on these screens about stopping an attacker.
   *
   * Three things here are not this app's to draw. The sheet that slides up
   * while the phone looks for a card is the phone's own, and one line of text
   * on it is ours (`link.say`). The page behind it cannot be touched while it
   * is up. And a card is let go as soon as it has signed: its sheet ends with
   * "Done. Remove the card.", and a screen of ours says that the mint is being
   * asked for as long as that takes (the card's part is seconds; the mint's is
   * as long as Tor).
   *
   * A card's PIN is not Foxy's PIN. It is typed on the same pad because that
   * is the pad a person already knows; it is held in a variable for the length
   * of one flow, passed to the card, and never stored.
   */

  /* A tap, step by step: the heading on our screen, and the line on the
   * phone's sheet. The wallet names the steps as it reaches them. */
  FC_STEPS = {
    hold: ['HOLD THE CARD<br>TO THE TOP OF THE PHONE', 'Hold the card to the top of the phone'],
    reading: ['READING<br>THE CARD', 'Reading the card'],
    signing: ['KEEP THE CARD<br>THERE', 'Keep the card there'],
    mint: ['KEEP THE CARD<br>THERE', 'Keep the card there: asking the mint'],
    change: ['PUTTING CHANGE<br>BACK ON THE CARD', 'Putting change back on the card'],
    /* The card has signed and been let go; its sheet is gone, and these are said
     * on our screen alone (`fcTap`'s `on`). */
    checking: ['VERIFYING<br>WITH THE MINT', ''],
    making: ['MAKING<br>THE CHANGE', ''],
    writing: ['WRITING<br>TO THE CARD', 'Keep the card there: writing to it'],
    done: ['REMOVE<br>THE CARD', 'Done. Remove the card.'],
  };
  FC_MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
  // how near its date a card's own phone starts saying RENEW
  FC_RENEW_DAYS = 30;
  /* Cards are cash, for now.
   *
   * The card and the wallet can do more: a card set up as recoverable names a
   * key of the phone that loaded it, and that phone can take its money back
   * a year later if the card is lost or blocked. It is switched off here, in
   * the one place that offers it: a new card is set up as cash with nothing
   * asked, the list of cards this phone could take back is not shown, and
   * with no list there is no screen for a card that has not been tapped.
   * True brings all three back as they were (tests/flashcard-screens.js runs
   * both ways). A card set up as recoverable by anything else still reads
   * and pays as what it is. */
  FC_RECOVERABLE = false;

  fcW() {
    const W = window.FoxyWallet;
    return (W && W.cardSession) ? W : null;
  }

  /* A card has no name. The last four characters of its key tell two apart. */
  fcName(key) { return 'CARD ··' + String(key || '').slice(-4).toUpperCase(); }

  fcSats(n) { return '₿' + this.group(Math.round(Number(n) || 0)); }

  /* An amount for a button or a sentence: dollars where this phone has a
   * price to say them at, the sats where it has not, and the sats too for an
   * amount under half a cent, which in dollars would read as nothing. */
  fcPrice(n) {
    const sats = Math.round(Number(n) || 0);
    const usd = (sats / 1e8) * ((this.px && this.px()) || 0);
    return usd >= 0.005 ? '$' + this.usd(usd) : this.fcSats(sats);
  }

  /* The same with the sats after it: "$1.28 (₿1,499)". */
  fcBoth(n) {
    const sats = Math.round(Number(n) || 0);
    const usd = (sats / 1e8) * ((this.px && this.px()) || 0);
    return usd >= 0.005 ? '$' + this.usd(usd) + ' (' + this.fcSats(sats) + ')' : this.fcSats(sats);
  }

  /* A piece's date, as a day. Written out here and not left to the phone's
   * region, so the same card reads the same on every phone. */
  fcDay(secs) {
    const d = new Date((Number(secs) || 0) * 1000);
    return d.getDate() + ' ' + this.FC_MONTHS[d.getMonth()] + ' ' + d.getFullYear();
  }

  /* FLASHCARD in the menu asks for the card at once: the phone's own sheet
   * comes up with no screen of ours to read first. A card tapped, and the
   * screen is that card. The sheet dismissed, and the person is where they
   * were: there is no screen for no card.
   *
   * Except where cards can be taken back (FC_RECOVERABLE): a lost card
   * cannot be tapped, so the screen with no card on it is opened first and
   * stays when the sheet goes, with the cards this phone loaded listed on it. */
  goFlashcard() {
    // a card read on an earlier visit is not shown again: it may be somebody else's
    this._fcCard = null;
    if (this.FC_RECOVERABLE) {
      this.setState(p => ({ fc: null, screen: 'flashcard', stack: p.stack.concat([p.screen]) }));
      this.fcRead();
      return;
    }
    if (this.state.fc) this.setState({ fc: null });
    this.fcRead(true);
  }

  /* ---- one tap ------------------------------------------------------------
   *
   * `o`: amount (a heading under the title) and body, for the screen behind
   * the sheet, and `warm`, for a tap that goes on to the mint (the road to it
   * is opened as the sheet opens). `fn(link, on)` is what to do with the card;
   * `on(step)` moves both screens on, and after the card is let go
   * (`link.released`) only ours. Resolves and rejects as `fn` does, with our
   * screen down either way. */
  fcTap(o, fn) {
    const W = this.fcW();
    if (!W) return Promise.reject(new Error('The wallet is not ready.'));
    this._fcTapO = o || {};
    this.fcStage('hold');
    /* What the phone's own link says is happening, as it says it: the card
     * found ("Scanning. Hold still."), each line put on the sheet, the card
     * lost. The screen behind the sheet shows the same line. */
    if (W.onCard) W.onCard((ev) => { if (ev && ev.text && ev.stage !== 'end') this.fcLine(ev.text); });
    const over = () => { if (W.onCard) W.onCard(null); this.hideStage('card'); };
    return W.cardSession((o && o.sheet) || this.FC_STEPS.hold[1], (link) => {
      const on = (step) => {
        const words = this.FC_STEPS[step];
        if (!words) return;
        // the card has been let go and the sheet is gone: nothing to say on it, and "remove the card" has been said
        if (link.released && step === 'done') return;
        this.fcStage(step);
        if (!link.released) link.say(words[1]);
        /* The card's part is over. The mint's work can take as long as Tor does
         * (this screen is not the sheet, which iOS ends after a minute), and what
         * is said under the heading is what a person who has taken the card away
         * needs to hear. */
        if (step === 'checking') {
          clearTimeout(this._stageT);
          this._stageT = setTimeout(() => this.hideStage('card'), 180000);
          this.fcLine('You can remove the card.');
        }
        if (step === 'making') {
          this.fcLine('The payment is made.');
          // and the payment's PAYMENT RECEIVED waits for its change to be back on the card
          if (this._fcTapO && this._fcTapO.paying) this.fcHoldConfirm();
        }
      };
      /* Which piece, of how many: said on the sheet and on the screen at once,
       * before the card is asked, so the line is up for as long as it works on
       * that piece and a person keeps holding. */
      const progress = (p) => {
        const text = this.fcProgressText(p);
        if (!text) return;
        this.fcLine(text);
        link.say(text);
      };
      on('reading');
      return fn(link, on, progress);
      // a tap that goes on to the mint opens the road to it as the sheet opens, not when the card has signed
    }, { warm: !!(o && o.warm), again: (o && o.again) || null }).then((r) => { over(); return r; },
            (e) => { over(); throw e; });
  }

  /* "Signing piece 3 of 9", "Writing 2 of 4": the words for one step of a
   * card's work, or '' for a step with none. */
  fcProgressText(p) {
    const i = Math.round(Number(p && p.i)), n = Math.round(Number(p && p.n));
    if (!(i > 0 && n > 0)) return '';
    if (p.step === 'signing') return 'Signing piece ' + i + ' of ' + n;
    if (p.step === 'writing') return 'Writing ' + i + ' of ' + n;
    return '';
  }

  /* The line under the heading on the card's screen: what the card is doing
   * now. Made the first time it is needed, above the dots. */
  fcLine(text) {
    if (!this.stageUp('card')) return;
    const up = document.getElementById('foxy-stage');
    const h = up && up.querySelector('h1');
    if (!h || !h.parentElement) return;
    let line = /** @type {HTMLElement | null} */ (up.querySelector('[data-stage-line]'));
    if (!line) {
      line = document.createElement('p');
      line.setAttribute('data-stage-line', '1');
      line.style.cssText = 'margin:0;max-width:300px;text-align:center;font-family:Sora,system-ui,sans-serif;'
        + 'font-weight:800;font-size:19px;line-height:1.3;letter-spacing:.01em;color:#13333C';
      const col = h.parentElement;
      const dots = Array.from(col.children).filter((el) => el.querySelector && el.querySelector('span'))[0];
      col.insertBefore(line, dots || null);
    }
    line.textContent = String(text);
  }

  fcStage(step) {
    const words = this.FC_STEPS[step] || this.FC_STEPS.hold;
    const o = this._fcTapO || {};
    if (!this.stageUp('card')) {
      this.stageScreen('card', {
        art: 'card', title: words[0], amount: o.amount || '', body: o.body || '',
        dots: true, forMs: 120000, button: 'CANCEL', keep: true,
        // the session ends as cancelled, and that is what takes this screen down
        go: () => { const W = this.fcW(); if (W) W.cardStop(); },
      });
    }
    const up = document.getElementById('foxy-stage');
    if (!up) return;
    const h = up.querySelector('h1');
    if (h) h.innerHTML = words[0];
    /* CANCEL is offered only while nothing has been asked of the card. After
     * that the way to stop is to finish: a card pulled away half-way has
     * signed for some of its money, and getting that back to it is a second
     * tap nobody needed. */
    const b = /** @type {HTMLElement | null} */ (up.querySelector('[data-stage-button]'));
    if (b) b.style.visibility = step === 'hold' ? 'visible' : 'hidden';
  }

  /* A card's PIN, on the pad the lock uses. `o`: title, subtitle, warn, and
   * `cta`, what the button says: it names the thing the PIN is for ("PAY
   * $0.43"), and it cannot be pressed until four digits are in. The way out
   * is a back button at the top left, where every screen's is; `o.onBack`
   * runs after it. */
  fcAskPin(o, then) {
    const opt = o || {};
    this.pinOverlay({
      title: opt.title || 'CARD PIN',
      subtitle: opt.subtitle || '',
      warn: opt.warn || '',
      cta: opt.cta || 'NEXT',
      gate: true,
      back: () => { if (opt.onBack) opt.onBack(); },
      onSubmit: (pin) => { this.pinDismiss(); then(pin); },
    });
  }

  /* An amount for a card, typed where every other amount in Foxy is typed:
   * the SET AMOUNT screen, with its dollars first, its swap to sats, its 00
   * key, the back button at the top and NEXT at the bottom. `flow` says which
   * question is being asked ('cardAdd', 'cardWd', 'cardLimit'); NEXT comes
   * back through `fcAmountNext`. */
  fcAmount(flow) {
    this.setState(p => ({
      // one keypad at a time: asked from another card question's keypad, this takes its place
      screen: 'amount', stack: p.screen === 'amount' ? p.stack : p.stack.concat([p.screen]), flow,
      // dollars, as the receive flow starts; sats where there is no price to say dollars at
      amount: '', unit: this.px() ? 'USD' : 'SATS',
      asset: '', network: '', note: '', noteDraft: '', recipient: '', recipientKind: '',
    }));
  }

  fcAmountNext() {
    const flow = String(this.state.flow);
    const fc = this.state.fc;
    const sats = this.wantedSats();
    if (!fc) { this.back(); return; }
    if (!(sats > 0)) { this.toast('Type an amount first.', true); return; }
    /* In sats, whatever the screen was typed in. The line under the figure
     * says the same thing in red, but it is worked out in dollars and has
     * nothing to say with no price. */
    const have = Math.floor(this.balNow().sats || 0);
    if (flow === 'cardAdd' && sats > have) { this.toast('You have ' + this.fcBoth(have) + '.', true); return; }
    if (flow === 'cardWd' && sats > fc.balance) { this.toast('The card holds ' + this.fcBoth(fc.balance) + '.', true); return; }
    /* The PIN pad goes up over the keypad, which stays where it is: back
     * from the pad is back to the amount, still typed. The keypad is left
     * only when the PIN has been given (`fcLeaveAmount`). */
    if (flow === 'cardAdd') this.fcAddPin(sats);
    else if (flow === 'cardWd') this.fcWithdrawPin(sats);
    else if (flow === 'cardLimit') this.fcLimitConfirm(sats);
  }

  /* Off the keypad and back to the card's own screen, once an amount has
   * been taken from it. */
  fcLeaveAmount() {
    if (this.state.screen !== 'amount' || !/^card/.test(String(this.state.flow))) return;
    this.setState(p => ({
      screen: p.stack.length ? p.stack[p.stack.length - 1] : 'flashcard', stack: p.stack.slice(0, -1),
      flow: 'receive', amount: '', unit: 'USD',
    }));
  }

  /* ---- what went wrong, as a card --------------------------------------------
   *
   * Every refusal the wallet or the card can give, by its kind, in the words
   * of the screen list. `o.again` is what TRY AGAIN does, where trying again
   * can work; `o.taken` says whether "nothing was taken" is a true thing to
   * add (it is for a payment and a withdrawal, and means nothing for a read).
   */
  fcFailed(e, o) {
    const opt = o || {};
    const kind = String((e && e.card) || '');
    const said = String((e && e.message) || 'That did not work.');
    const safe = opt.taken ? ' Nothing was taken.' : '';
    const again = opt.again ? { retry: 'TRY AGAIN', go: opt.again, shut: { label: 'CANCEL' } } : {};
    console.log('[foxy] card: ' + (kind || 'failed') + ' — ' + said);
    // their own cancel, or no card held up: the screen they were on is the answer
    if (kind === 'cancelled') return;
    if (kind === 'waiting') { this.fcChecking(e && e.id, opt); return; }
    const cards = {
      'wrong-pin': () => Object.assign({ tone: 'warn', title: 'WRONG PIN',
        reason: ((e.tries === 1) ? '1 try left.' : (e.tries + ' tries left.')) + safe,
        // the last one is said for what it is: the card blocks itself for good
        chip: e.tries === 1 ? 'One more wrong PIN blocks this card for good.' : '' }, again),
      'blocked': () => ({ title: 'CARD BLOCKED',
        reason: 'Too many wrong PINs. This card can no longer pay until its owner sets a new PIN on it.' }),
      'not-enough': () => ({ tone: 'warn', title: 'NOT ENOUGH ON THE CARD',
        reason: 'It holds ' + this.fcSats(e.balance) + '.' + safe }),
      'other-mint': () => ({ tone: 'warn', title: 'A DIFFERENT MINT', reason: said }),
      'renew': () => ({ tone: 'warn', title: 'CARD NEEDS RENEWING',
        reason: 'Its owner must renew it with their own phone before it can pay.' }),
      'past-date': () => ({ tone: 'warn', title: 'ITS DATE HAS PASSED',
        reason: 'This phone can take this card’s money back with no card.',
        chip: 'FLASHCARD › CARDS YOU LOADED' }),
      'empty': () => ({ tone: 'warn', title: 'NO MONEY ON THIS CARD',
        reason: 'It has not been set up, or nothing has been put on it.' }),
      'not-a-card': () => ({ title: 'NOT A FOXY CARD', reason: said }),
      'no-route': () => Object.assign({ tone: 'warn', title: opt.taken ? 'NOT PAID' : 'NO CONNECTION',
        reason: 'The mint could not be reached.' + safe }, again),
      /* A till, and the card's day has too little left for this payment: said
       * before the PIN was sent, in the amounts a person reads, with when the
       * day turns. */
      'limit': () => ({ tone: 'warn', title: 'OVER THE CARD’S DAILY LIMIT',
        reason: (e.left !== undefined ? this.fcLimitRefusal(e) : said) + safe }),
      'not-owner': () => ({ tone: 'warn', title: 'NOT THIS PHONE’S CARD',
        reason: 'This phone does not hold the seed phrase this card was set up with, so it cannot change the card’s PIN or limit.',
        chip: 'Restore that seed phrase in Foxy, on this phone or another, to do it.' }),
      'no-owner': () => ({ tone: 'warn', title: 'THIS CARD HAS NO OWNER', reason: said }),
      'set-up': () => ({ tone: 'warn', title: 'THIS CARD HAS AN OWNER', reason: said }),
      'no-owner-key': () => ({ tone: 'warn', title: 'NO SEED PHRASE', reason: said }),
      'wrong-signer': () => ({ title: 'NOT A FOXY CARD', reason: said }),
      'no-time': () => ({ tone: 'warn', title: 'THE CARD HAS NO TIME', reason: said }),
      'no-time-source': () => ({ tone: 'warn', title: 'NO TIME TO TELL THE CARD', reason: said }),
      'gone': () => Object.assign({ tone: 'warn', title: 'THE CARD LEFT TOO SOON',
        reason: 'Hold it still until the phone says to remove it.' + safe }, again),
      /* The card left part-way through signing: nothing moved, and what it did
       * sign goes back on it at its next tap (with no PIN), or, where the mint
       * has not answered yet, once it has. Said by what the person was doing. */
      /* Not made yet (no route to the mint): there is nothing to write, and a
       * TAP CARD here only found "nothing was waiting for this card". */
      'interrupted': () => Object.assign({ tone: 'warn', title: opt.paying ? 'NOT PAID' : 'THE CARD LEFT TOO SOON',
        reason: 'The card was taken away too soon. ' + (opt.paying ? 'Nothing was paid. ' : 'Nothing was taken. ')
          + (e.made === false
            ? 'What it signed for is made ready to go back on it once this phone reaches the mint, and the card\u2019s next tap here puts it back.'
            : 'Tap it again to put back the ' + this.fcSats(e.owed) + ' it signed for. No PIN is needed.'),
        chip: 'Hold it still until the phone says to remove it.' },
        e.made === false ? { shut: { label: 'OK' } } : { retry: 'TAP CARD', go: () => this.fcWriteAsk({}), shut: { label: 'LATER' } }),
      'spent': () => ({ title: opt.taken ? 'NOT PAID' : 'ALREADY SPENT',
        reason: 'The mint says this card’s money was already spent.' }),
      'no-nfc': () => ({ tone: 'warn', title: 'NO CARD READER', reason: 'This phone cannot read a card.' }),
      'full': () => ({ tone: 'warn', title: 'THE CARD IS FULL', reason: said }),
      // offline, only an exact set of the card's pieces can be taken: said before the PIN, so nothing was taken
      'inexact': () => ({ tone: 'warn', title: 'NO CHANGE WHILE OFFLINE', reason: said + safe }),
      'bad-pieces': () => ({ tone: 'warn', title: 'THE CARD’S PIECES ARE NOT GOOD', reason: said }),
      /* The mint refused after the card had signed. The card burned the pieces
       * when it signed, so it has to be tapped again to have them put back (the
       * next tap clears the places and loads the same pieces). Its day stays
       * charged: only the owner's phone can give a day back. */
      'putback': () => ({ tone: 'warn', title: opt.paying ? 'PAYMENT FAILED' : 'NOT TAKEN OFF',
        reason: 'The mint refused it, and the card had already signed for it. Tap the card again to put ' + this.fcSats(e.owed) + ' back on it.',
        chip: e.limited ? 'The card’s daily limit stays used for it.' : '',
        retry: 'TAP CARD', go: () => this.fcWriteAsk({}), shut: { label: 'LATER' } }),
      'misfit': () => ({ tone: 'warn', title: 'NOT AT THIS MINT', reason: said, chip: 'Nothing was taken.' }),
      'misfit-kept': () => ({ tone: 'warn', title: 'KEPT FOR THE CARD', reason: said }),
      'locked': () => ({ tone: 'warn', title: 'THE CARD IS LOCKED', reason: 'Nothing more can be written to it. It can still pay.' }),
      'too-soon': () => ({ tone: 'warn', title: 'NOT YET',
        reason: e.date ? 'This card can be taken back after ' + this.fcDay(e.date) + '.' : said }),
      'nothing': () => ({ tone: 'warn', title: 'NOTHING WAS LEFT ON IT', reason: said }),
    };
    const spec = (cards[kind] || (() => ({ tone: 'warn', title: 'THAT DID NOT WORK', reason: said + safe })))();
    this.haptic && this.haptic('error');
    this.blockedCard('fc-' + (kind || 'failed'), spec);
  }

  /* A time as a person reads it on a card's day: "3:40 PM" for today, and
   * with the day after it for any other. Written out here and not left to the
   * phone's region, as fcDay is. */
  fcWhen(secs) {
    const d = new Date((Number(secs) || 0) * 1000);
    const h = d.getHours();
    const clock = ((h % 12) || 12) + ':' + ('0' + d.getMinutes()).slice(-2) + (h < 12 ? ' AM' : ' PM');
    const t = new Date();
    return (d.getFullYear() === t.getFullYear() && d.getMonth() === t.getMonth() && d.getDate() === t.getDate())
      ? clock : clock + ', ' + this.fcDay(secs);
  }

  /* What a till is told when the card's day cannot cover the payment: how much
   * the card can still spend today and when its day turns. `e.left`, `e.turns`
   * and `e.limit` are the card's own, read before the PIN was sent. */
  fcLimitRefusal(e) {
    if (e.turns > 0 && e.left < e.limit) {
      return 'The card can still spend ' + this.fcBoth(e.left) + ' today. Its day turns at ' + this.fcWhen(e.turns) + '.';
    }
    return 'The card can spend ' + this.fcBoth(e.limit || e.left) + ' in a day, and this payment is more than that.';
  }

  /* The card has signed and the mint has not answered.
   *
   * The one state in which nobody knows yet: the card has marked its pieces
   * spent, and whether they became this phone's is the mint's to say. Asked
   * again every five seconds, a dozen times, and never past this screen: the
   * wallet asks again by itself whenever it connects, and the payment is in
   * HISTORY when it lands. */
  fcChecking(id, o) {
    const W = this.fcW();
    const opt = o || {};
    let tries = 0;
    clearTimeout(this._fcCheckT);
    this.stageScreen('cardChecking', {
      art: 'card', title: 'CHECKING',
      body: 'The card has signed and the mint has not answered yet.',
      dots: true, forMs: 70000, button: 'CLOSE',
      go: () => clearTimeout(this._fcCheckT),
    });
    const settled = (how, row) => {
      clearTimeout(this._fcCheckT);
      this.hideStage('cardChecking');
      if (how === 'paid') {
        this.fcMoved(opt);
        // the mint's answer came late, and the change it made waits for the card's second tap (RECEIVE)
        if (opt.paying && row && row.change > 0 && !row.refund) this.fcReceiveNow(row.change, row.sats);
        return;
      }
      if (how === 'spent') { this.fcFailed({ card: 'spent' }, { taken: opt.taken }); return; }
      if (how === 'putback') { this.fcFailed({ card: 'putback', owed: row && row.owed, limited: row && row.limited }, opt); return; }
      if (how === 'bad') { this.fcFailed({ card: 'bad-pieces', message: 'The card gave pieces the mint did not sign. Nothing was paid.' }, opt); return; }
      this.blockedCard('fc-still', { tone: 'warn', title: 'STILL CHECKING',
        reason: 'The mint has not answered. Foxy keeps asking, and this will be in HISTORY when it does.',
        chip: opt.paying ? 'It is not paid until then.' : '' });
    };
    const ask = () => {
      // closed, or timed out: the asking stops with the screen
      if (!this.stageUp('cardChecking')) return;
      W.cardSettle().then((rows) => {
        if (!this.stageUp('cardChecking')) return;
        const mine = (rows || []).filter(r => r.id === id)[0];
        if (mine && mine.state === 'paid') return settled('paid', mine);
        if (mine && mine.state === 'spent') return settled('spent');
        if (mine && mine.state === 'putback') return settled('putback', mine);
        if (mine && mine.state === 'bad') return settled('bad');
        if (!mine) {
          // answered by the wallet's own asking, between two of ours: the entry says which way
          return W.transactions(50).then((list) => settled((list || []).some(t => t.hash === id) ? 'paid' : 'spent'));
        }
        tries += 1;
        if (tries >= 12) return settled('waiting');
        this._fcCheckT = setTimeout(ask, 5000);
        return null;
      }, () => settled('waiting'));
    };
    this._fcCheckT = setTimeout(ask, 3000);
  }

  /* Money has moved by a card and the screens catch up. A payment is
   * announced by the history pass like any other; a holder's own move is said
   * by the flow that made it (16-history-lists.js keeps the pass quiet). */
  fcMoved(o) {
    const opt = o || {};
    if (opt.paying && this.state.screen === 'confirm') this.closeReceive();
    if (opt.paying && this.noteReceived) this.noteReceived();
    this.refreshBalance();
    this.loadHistory();
    if (opt.paying && this.tidyChangeNow) this.tidyChangeNow();
    if (!opt.paying && opt.done) opt.done();
  }

  /* ---- being paid by a card (the receive screen's CARD button) -------------- */

  payByCard() {
    const W = this.fcW();
    if (!W) return;
    const s = this.state;
    const sats = (!s.invoiceIsAddress && W.amountOf && W.amountOf(s.invoice)) || this.wantedSats();
    if (!(sats > 0)) { this.toast('Enter an amount first.', true); return; }
    /* No route to the mint: the mint cannot say paid. The card may still be taken,
     * as plain ecash is on trust, if the person says so, in front of the amount,
     * before the PIN is asked for (the HIGH RISK card: until this phone is online,
     * whoever gave it can still spend it). Only an exact set of the card's pieces
     * is taken then, which the tap finds out before the PIN is sent. */
    if (W.cardOnline && !W.cardOnline() && W.cardOffline && W.cardOffline()) {
      W.cardOfflineAsk(sats).then((yes) => { if (yes) this.fcPayAsk(sats, true); });
      return;
    }
    if (this.offlineNow()) { this.offlineNo('A card payment'); return; }
    this.fcPayAsk(sats);
  }

  /* `trusted`: the person has said yes to taking it with no route. */
  fcPayAsk(sats, trusted) {
    this.fcAskPin({
      title: 'CARD PIN',
      subtitle: 'To pay ' + this.fcBoth(sats) + '. The card\u2019s owner types its PIN here.',
      cta: 'PAY ' + this.fcPrice(sats),
    }, (pin) => this.fcPayRun(sats, pin, trusted));
  }

  /* A card payment is two taps, and is said as two every time, so a person
   * learns one way of paying: SEND (the card signs no more than two pieces and
   * is let go), VERIFY (this screen, while the mint swaps them), RECEIVE (the
   * change goes back on, with no PIN) and COMPLETE. Paid exactly, there is
   * nothing to receive, and the payment is complete at once. Taken on trust
   * with no route, it is one tap: only an exact set is taken then. */
  /* `resuming`: the same payment, taken up again after the card left part way
   * through: the card signs only what it had not (08a-flashcard.js, `cardHeld`). */
  fcPayRun(sats, pin, trusted, resuming) {
    const W = this.fcW();
    const opt = { paying: true, taken: true, again: () => this.fcPayAsk(sats, trusted) };
    this.fcTap({ amount: this.stageMoney(sats), body: resuming ? 'Tap again to finish paying.' : trusted ? '' : 'Tap 1 of 2: SEND.',
                 sheet: resuming ? 'Hold the card here again to finish paying' : '', warm: !trusted, paying: true,
                 /* the card left part way through: the same sheet asks for it again, and the payment is taken up in it */
                 again: (e) => (e && e.card === 'interrupted' && e.resumable) ? 'Hold the card here again to finish paying'
                   : (e && e.card === 'gone') ? 'Hold the card here again' : '' },
               (link, on, progress) => W.cardPay(link, { sats, pin, on, progress, trusted: !!trusted }))
      .then((r) => {
        this.haptic && this.haptic('success');
        /* Taken on trust: kept, and not paid. The mint has not been asked, so
         * nothing here says paid; it settles when this phone is online. */
        if (r && r.trusted) { this.fcTrusted(r); return; }
        const ch = r && r.change;
        const receiving = !!(ch && !ch.written && !ch.unmade && ch.sats > 0);
        // no change to take after all (made and written, too small, or not made): the confirmation is not held for it
        if (!receiving) this.fcReleaseConfirm('no change to take');
        this.fcMoved(opt);
        // made, and the card left before it was written back: the second tap is asked for at once
        if (receiving) this.fcReceiveNow(ch.sats, sats);
        // not made: this phone tries again when it connects, and says so
        if (ch && ch.unmade && ch.sats > 0) this.fcChangeLater(ch.sats, sats);
        /* A payment of this card's held for another amount was let go as this
         * one finished: its pieces go back on at the same second tap. */
        const back = r && r.letGo && r.letGo.made ? Math.round(Number(r.letGo.sats) || 0) : 0;
        if (back > 0 && !(ch && !ch.written && !ch.unmade && ch.sats > 0)) this.fcReceiveNow(back, sats);
        // a piece the card signed as it was taken away, whose answer never came: said, quietly
        if (r && r.torn > 0) this.toast(this.fcSats(r.torn) + ' the card signed as it was taken away never reached this phone.', true);
      }, (e) => {
        /* The card left part way through signing, and the sheet that looked for
         * it again was dismissed: what it signed is held, said with TAP CARD.
         * Where the phone could not keep the sheet up (an older one), a new
         * sheet comes up by itself instead, once iOS has taken the last down. */
        if (e && e.card === 'interrupted' && e.resumable) {
          if (e.sheetClosed) this.fcHeldCard(sats, pin, trusted); else this.fcResumeNow(sats, pin, trusted);
          return;
        }
        // taken up, and the card could not make the rest: what it signed goes back, and why is said
        if (e && e.card === 'not-enough' && e.still > 0) { this.fcShortHeld(e, sats); return; }
        // that tap read no card, or the card left before signing anything more: the hold stands, said with TAP CARD
        if (resuming && e && (e.card === 'cancelled' || e.card === 'gone')) { this.fcHeldCard(sats, pin, trusted); return; }
        this.fcFailed(e, opt);
      });
  }

  /* The sheet again, a moment after the one the card left: iOS refuses a
   * reading session started on the heels of the last. The PIN typed for this
   * payment is used again, as it is for every tap of the one payment. And a
   * settling once the hold could be stale, so one nobody came back for goes
   * back to the card even with Foxy left open. */
  fcResumeNow(sats, pin, trusted) {
    clearTimeout(this._fcResumeT);
    this._fcResumeT = setTimeout(() => this.fcPayRun(sats, pin, trusted, true), 2500);
    this.fcHeldClock();
  }

  /* A payment taken up again that the card could not finish: it holds too
   * little for the rest (often because a piece it signed as it was taken away
   * never arrived). What it signed for the payment is given back; the tap that
   * puts it on is one press away. */
  fcShortHeld(e, sats) {
    const back = e.letGo && e.letGo.made ? Math.round(Number(e.letGo.sats) || 0) : 0;
    this.fcReleaseConfirm('the payment was not finished');
    this.blockedCard('fc-short', Object.assign({
      tone: 'warn', title: 'NOT PAID',
      reason: 'The card holds ' + this.fcSats(e.balance) + ', and ' + this.fcSats(e.still) + ' of ' + this.fcSats(sats) + ' was still to pay.'
        + (e.torn > 0 ? ' ' + this.fcSats(e.torn) + ' it signed as it was taken away never reached this phone, and cannot be spent.' : '')
        + (back > 0 ? ' What it signed for this payment goes back on it: tap it to put it back.' : ' What it signed for this payment goes back on it once this phone reaches the mint.'),
    }, back > 0 ? { retry: 'TAP CARD', go: () => this.fcWriteAsk({ sheet: 'Hold the card here to put back what it signed' }), shut: { label: 'LATER' } }
                : { shut: { label: 'OK' } }));
  }

  fcHeldClock() {
    const W = this.fcW();
    clearTimeout(this._fcHeldT);
    this._fcHeldT = setTimeout(() => { if (W && W.cardSettle) W.cardSettle().then(null, () => {}); }, 185000);
  }

  /* Held, and the tap to finish read no card: said, with the tap again, and
   * CANCEL, which gives back what the card signed (`fcLetGo`). */
  fcHeldCard(sats, pin, trusted) {
    this.fcHeldClock();
    this.blockedCard('fc-held', {
      tone: 'warn', title: 'NOT PAID YET',
      reason: 'The card was taken away before it had signed for all of ' + this.fcSats(sats) + '. Tap it again to finish paying.',
      chip: 'Nothing is paid until then. CANCEL puts back what it signed.',
      retry: 'TAP CARD', go: () => this.fcPayRun(sats, pin, trusted, true),
      shut: { label: 'CANCEL', tap: () => this.fcLetGo() },
    });
  }

  /* The payment is given up: what the card signed for it is made into pieces
   * for the card again, and the sheet comes up by itself to put them back. With
   * no route to the mint they are made once there is one, and said so. */
  fcLetGo() {
    const W = this.fcW();
    if (!W || !W.cardHeldLetGo) return;
    W.cardHeldLetGo().then((r) => {
      if (r && r.made && r.sats > 0) { this.fcReceiveNow(r.sats, 0, { putBack: true }); return; }
      if (r && r.sats > 0) {
        this.blockedCard('fc-let-go', {
          tone: 'warn', title: 'NOT PAID',
          reason: 'What the card signed goes back on it once this phone reaches the mint, and the card\u2019s next tap here puts it back.',
          shut: { label: 'OK' },
        });
      }
    }, () => {});
  }

  fcTrusted(r) {
    this.blockedCard('fc-trusted', {
      tone: 'warn', title: 'TAKEN ON TRUST',
      reason: this.fcSats(r.sats) + ' was taken from the card, but this phone is offline, so the mint has not been asked. '
        + 'It is not paid until this phone is online and the mint has swapped it. Until then it waits in HISTORY, pending.',
      chip: 'Whoever gave it can still spend it until then.',
      shut: { label: 'OK', tap: () => { if (this.state.screen === 'confirm') this.closeReceive(); } },
    });
    // the pending entry is in HISTORY now, and the balance counts what is waiting
    this.refreshBalance();
    this.loadHistory();
  }

  /* The change for a payment could not be made (the mint did not make it):
   * the payment stands, and this phone makes the change when it next
   * connects, after which a tap of the card here receives it. */
  fcChangeLater(sats, paid) {
    const p = Math.round(Number(paid) || 0);
    this.blockedCard('fc-change-later', {
      tone: 'warn', title: 'CHANGE NOT MADE YET',
      reason: (p > 0 ? 'Paid ' + this.fcSats(p) + '. ' : '') + 'The mint did not make its ' + this.fcSats(sats)
        + ' of change. This phone tries again whenever it connects, and then a tap of the card here receives it.',
      chip: 'It is owed to that card and no other.',
      shut: { label: 'OK' },
    });
  }

  /* The second tap of a payment, asked for as soon as the mint has said paid:
   * the phone's sheet comes up by itself for the card again, with nothing to
   * press first. PIN, tap, remove the card, wait, tap again. A sheet that ends
   * with no card read (cancelled, timed out, Foxy put away) leaves TAP TO
   * RECEIVE up instead, so the change is never left without a way to it. A
   * moment's pause first: iOS refuses a reading session started on the heels
   * of the last one. */
  fcReceiveNow(sats, paid, o) {
    const p = Math.round(Number(paid) || 0);
    const putBack = !!(o && o.putBack);
    clearTimeout(this._fcReceiveT);
    this._fcReceiveT = setTimeout(() => {
      const W = this.fcW();
      // written meanwhile (or never owed here): nothing to ask for
      if (!W || !this.fcOwedAfterPaying()) return;
      this.fcWriteRun('', { change: true, receive: !putBack, paid: p, sats: Math.round(Number(sats) || 0),
                            sheet: putBack ? 'Hold the card here to put back what it signed' : '' });
    }, 700);
  }

  /* The second tap of a payment: RECEIVE. `paid` is what was paid, where
   * this phone was the till; a holder's own withdrawal with change has none. */
  fcChangeWaiting(sats, paid) {
    const p = Math.round(Number(paid) || 0);
    this.blockedCard('fc-change', {
      tone: 'warn', title: 'TAP TO RECEIVE',
      reason: (p > 0 ? 'Paid ' + this.fcSats(p) + '. ' : 'The money is off the card. ')
        + 'Tap the card again to receive its ' + this.fcSats(sats) + ' of change. No PIN is needed.',
      chip: (p > 0 ? 'Tap 2 of 2. ' : '') + 'The change is kept for that card and no other.',
      retry: 'TAP CARD', go: () => this.fcWriteAsk({ paid: p, receive: true }),
      shut: { label: 'LATER', tap: () => this.fcReleaseConfirm('the change is left for later') },
    });
  }

  /* ---- what this phone owes cards -------------------------------------------
   *
   * Pieces made for a card and not on it yet: a top-up whose tap was cut
   * short, a payer's change, something a card signed for and was not paid.
   * They are locked to that card, so only it can spend them, and they go on
   * at the next tap with its PIN. */
  fcOwed() {
    const W = this.fcW();
    const by = {};
    ((W && W.cardOwed()) || []).forEach((r) => { by[r.card] = (by[r.card] || 0) + (Number(r.sats) || 0); });
    return Object.keys(by).map(key => ({ key, sats: by[key] }));
  }

  fcWriteAsk(o) {
    const opt = o || {};
    /* Money moved for a card waits at the mint it was moved to, and can only
     * be written from there: said here, with the way to get there, and not
     * found out at the tap. */
    const W = this.fcW();
    const here = String((W && W.mintUrl) || '').replace(/\/+$/, '');
    const away = ((W && W.cardOwed()) || []).filter(r => r.mint && here && r.mint !== here)[0];
    if (away && !opt.here) {
      this.blockedCard('fc-other-mint', {
        tone: 'warn', title: 'A DIFFERENT MINT',
        reason: 'That money is at ' + this.mintNameOf(away.mint) + '. Switch this phone to it, then tap the card.',
        retry: 'SWITCH MINT', go: () => this.goSwitchMint(), shut: { label: 'CANCEL' },
      });
      return;
    }
    /* The card on screen is this phone's own: it loads it with its own proof and
     * no PIN. Any other card is written to as a till writes change, with its PIN. */
    const fc = this.state.fc;
    if (fc && fc.ownedHere && this.state.screen === 'flashcard' && !opt.pin) { this.fcWriteRun('', Object.assign({}, opt, { owner: true })); return; }
    /* What is owed is a payment's change, or pieces a card signed for a payment
     * that was not made: the card has just paid, and lets the tap after a payment
     * put pieces on with no PIN. Tapped first without one; a card that asks for
     * it after all is given it on the next tap. */
    if (!opt.pin && this.fcOwedAfterPaying()) { this.fcWriteRun('', Object.assign({}, opt, { change: true })); return; }
    const owed = this.fcOwed().reduce((n, r) => n + r.sats, 0);
    this.fcAskPin({
      title: 'CARD PIN',
      subtitle: owed > 0 ? 'To put ' + this.fcBoth(owed) + ' on the card.' : 'To write to the card.',
      cta: owed > 0 ? 'PUT ' + this.fcPrice(owed) + ' ON CARD' : 'WRITE TO CARD',
      // backed out of: a payment's confirmation held for this goes up
      onBack: () => this.fcReleaseConfirm('the change was not taken'),
    }, (pin) => this.fcWriteRun(pin, opt));
  }

  /* Whether what this phone owes cards came of a payment: change, a refund of
   * what a card signed and left with, or a payment the mint refused put back. */
  fcOwedAfterPaying() {
    const W = this.fcW();
    return ((W && W.cardOwed()) || []).some((r) => r && (r.kind === 'change' || r.kind === 'refund' || r.kind === 'putback'));
  }

  /* `opt.owner`: this phone's own proof that it owns the card, and no PIN.
   * `opt.change`: the tap after a payment, which needs none either. */
  fcWriteRun(pin, o) {
    const W = this.fcW();
    const opt = o || {};
    const how = opt.owner ? { owner: true } : opt.change ? { change: true } : { pin };
    this.fcTap({ amount: opt.sats ? this.stageMoney(opt.sats) : '', body: opt.receive && opt.paid > 0 ? 'Tap 2 of 2: RECEIVE.' : '',
                 sheet: opt.sheet || (opt.receive ? 'Hold the card here again for its change' : ''),
                 // what went on stays on: the same sheet asks for the card again for the rest
                 again: (e) => (e && e.card === 'gone') ? 'Hold the card here again for the rest' : '' },
               (link, on, progress) => { on('writing'); return W.cardWrite(link, Object.assign({ progress }, how)); })
      .then((r) => this.fcWrote(r, opt),
            /* Not the owner after all (another card was tapped), or not the tap
             * after a payment after all: the PIN is what writes then. */
            (e) => ((opt.owner && e && e.card === 'not-owner') || (opt.change && e && e.card === 'pin-needed'))
              ? this.fcWriteAsk(Object.assign({}, opt, { pin: true, owner: false, change: false }))
              : (e && e.card === 'cancelled')
                ? this.fcStillWaiting(opt)
                /* The card left after some pieces went on: the sheet again by
                 * itself for the rest. A tap of it that reads no card says what
                 * is still waiting. Where nothing went on, the card says so and
                 * waits to be asked, so a card that keeps leaving is not asked forever. */
                // the sheet asked for the card again and was dismissed: what is still waiting is said, with TAP CARD
                : (e && e.card === 'gone' && e.sheetClosed)
                  ? this.fcStillWaiting(opt)
                : (e && e.card === 'gone' && e.wrote > 0)
                  ? this.fcWriteAgain(opt)
                  : (this.fcReleaseConfirm('the change tap failed'), this.fcFailed(e, { again: () => this.fcWriteAsk(opt) })));
  }

  /* A card payment's PAYMENT RECEIVED (announcePayment, 12-receive.js) waits
   * while its change is made and taken: it came up the moment the payment
   * landed, with the payer still to tap for their change, and read as if it
   * were over. It goes up when the change is back on the card (DONE on
   * COMPLETE), when the change is left for later, or after two and a half
   * minutes whatever happens, so it is never lost. */
  fcHoldConfirm() {
    this._holdConfirmUntil = Date.now() + 150000;
    clearTimeout(this._holdConfirmT);
    this._holdConfirmT = setTimeout(() => this.fcReleaseConfirm('the change tap took too long'), 150000);
  }

  fcReleaseConfirm(why) {
    if (this.releaseHeldConfirm) { this.releaseHeldConfirm(why); return; }
    clearTimeout(this._holdConfirmT);
    this._holdConfirmUntil = 0;
  }

  fcWriteAgain(o) {
    clearTimeout(this._fcResumeT);
    this._fcResumeT = setTimeout(() => this.fcWriteAsk(Object.assign({}, o, { sheet: 'Hold the card here again for the rest' })), 2500);
  }

  /* A write tap that closed with no card read (the sheet went without a tap,
   * or was cancelled): what is still waiting is said again, with the tap to
   * try once more, instead of nothing. A person who has just been told to tap
   * for their change must not be left wondering whether anything happened. */
  fcStillWaiting(opt) {
    const owed = this.fcOwed().reduce((n, r) => n + r.sats, 0);
    if (!(owed > 0)) return;
    const after = this.fcOwedAfterPaying();
    this.blockedCard('fc-change', {
      tone: 'warn', title: after ? 'TAP TO RECEIVE' : 'TAP THE CARD AGAIN',
      reason: 'The card was not read. ' + this.fcSats(owed) + ' is still waiting to go ' + (after ? 'back on it.' : 'onto it.') + (after ? ' No PIN is needed.' : ''),
      chip: 'It is kept for that card and no other.',
      retry: 'TAP CARD', go: () => this.fcWriteAsk(opt),
      shut: { label: 'LATER', tap: () => this.fcReleaseConfirm('the change is left for later') },
    });
  }

  fcWrote(r, o) {
    // a card that was at another mint and has been moved by this write is told so, below
    const was = String((this.state.fc && this.state.fc.mint) || '').replace(/\/+$/, '');
    this.fcShow(r.card);
    const now = String((r.card && r.card.record && r.card.record.mint) || '').replace(/\/+$/, '');
    const moved = !!(was && now && was !== now);
    this.refreshBalance();
    this.loadHistory();
    /* Cut short with some of it written: the sheet comes up again by itself
     * for the rest (a tap of it that reads no card says what is still waiting,
     * `fcStillWaiting`). Not where nothing went on: that would ask forever. */
    if (r.left > 0 && r.why !== 'full' && r.sats > 0) { this.fcWriteAgain(o); return; }
    if (r.left > 0) {
      this.blockedCard('fc-more', {
        tone: 'warn', title: r.why === 'full' ? 'THE CARD IS FULL' : 'TAP THE CARD AGAIN',
        reason: (r.sats > 0 ? this.fcSats(r.sats) + ' went on. ' : '')
          + (r.why === 'full' ? 'There is no room for the rest. Take some money off it first.' : 'The rest is still waiting for it.'),
        retry: 'TAP CARD', go: () => this.fcWriteAsk(o), shut: { label: 'LATER' },
      });
      return;
    }
    if (!(r.sats > 0)) {
      /* Nothing was owed to the card that was tapped. Where something is
       * still owed, it is owed to another card, and saying so is the only way
       * the person finds out they picked up the wrong one. */
      const owed = this.fcOwed();
      this.blockedCard('fc-none', {
        tone: 'warn', title: owed.length ? 'A DIFFERENT CARD' : 'NOTHING TO WRITE',
        reason: owed.length
          ? 'Nothing was waiting for this card. ' + this.fcSats(owed[0].sats) + ' is waiting for ' + this.fcName(owed[0].key) + '.'
          : 'Nothing was waiting for this card.',
      });
      return;
    }
    this.haptic && this.haptic('success');
    /* A payment the mint refused, put back: said as that, with what else went on in the same tap. */
    if (r.back > 0) {
      this.blockedCard('fc-put-back', {
        tone: 'ask', title: 'PUT BACK ON THE CARD',
        reason: this.fcSats(r.back) + ' is back on the card. The payment was not made.'
          + (r.sats > r.back ? ' ' + this.fcSats(r.sats - r.back) + ' more went on.' : '')
          + (this.state.screen === 'flashcard' ? ' It now holds ' + this.fcSats(r.card.balance) + '.' : ''),
        shut: { label: 'DONE' },
      });
      return;
    }
    /* The second tap of a payment: its change is back on the card, and the
     * payment is COMPLETE. */
    if (r.change > 0 && r.change + (r.refund || 0) === r.sats) {
      const paid = Math.round(Number(o && o.paid) || 0);
      this.blockedCard('fc-complete', {
        tone: 'ask', title: 'COMPLETE',
        reason: (paid > 0 ? 'Paid ' + this.fcSats(paid) + '. ' : '') + this.fcSats(r.change) + ' of change is back on the card.'
          // and a payment of the card's given up here, which went back in the same tap
          + (r.refund > 0 ? ' So is ' + this.fcSats(r.refund) + ' from a payment that was not finished.' : '')
          + (this.state.screen === 'flashcard' ? ' It now holds ' + this.fcSats(r.card.balance) + '.' : ''),
        // and then the payment's own PAYMENT RECEIVED, held until now
        shut: { label: 'DONE', tap: () => this.fcReleaseConfirm('the change is back on the card') },
      });
      return;
    }
    /* What a card signed for a payment that was not made, back on it: said
     * as that, and not as money put on it. */
    if (r.refund > 0 && r.refund === r.sats) {
      this.blockedCard('fc-refunded', {
        tone: 'ask', title: 'BACK ON THE CARD',
        reason: this.fcSats(r.refund) + ' is back on the card. The payment was not made.'
          + (this.state.screen === 'flashcard' ? ' It now holds ' + this.fcSats(r.card.balance) + '.' : ''),
        shut: { label: 'DONE' },
      });
      return;
    }
    /* What it now holds is said to its holder, on the FLASHCARD screen. A
     * till putting a payer's change back says the change and nothing else. */
    this.blockedCard('fc-on', {
      tone: 'ask', title: 'ON THE CARD',
      reason: this.fcSats(r.sats) + ' went onto the card.'
        + (this.state.screen === 'flashcard' ? ' It now holds ' + this.fcSats(r.card.balance) + '.' : '')
        + (moved ? ' The card is now at ' + this.mintNameOf(now) + '.' : '')
        // an amount of too many pieces is rounded up, so the card has fewer to sign for and is quicker to use
        + ((o && o.rounded > 0) ? ' ' + this.fcSats(o.rounded) + ' more than you asked for, so the card holds fewer pieces and is quicker to use.' : ''),
      shut: { label: 'DONE' },
    });
  }

  /* ---- MENU > FLASHCARD: reading a card ---------------------------------- */

  /* `open`: the card's screen is opened by what is read (the menu's way in). */
  fcRead(open) {
    const W = this.fcW();
    if (!W) return;
    this.fcTap({}, (link) => W.cardLook(link, { mine: true }))
      .then((card) => this.fcShow(card, open), (e) => this.fcFailed(e, { again: () => this.fcRead(open) }));
  }

  /* What a card said, kept for the screen. Only on the FLASHCARD screen, or
   * on the way to it (`open`): a payer's card read at the till is not left
   * on show in the menu. */
  fcShow(card, open) {
    if (!card || !card.key) return;
    if (this.state.screen !== 'flashcard') {
      if (!open) return;
      this.setState(p => ({ screen: 'flashcard', stack: p.stack.concat([p.screen]) }));
    }
    const W = this.fcW();
    const dates = (card.pieces || []).map(x => x.date).filter(Boolean);
    this._fcCard = card;
    this.setState({ fc: {
      key: card.key, balance: card.balance, count: (card.pieces || []).length,
      room: card.info.empty + card.info.spent,
      pin: card.info.pin, locked: !!card.info.locked, hasRecord: !!card.info.hasRecord,
      limit: (card.record && card.record.limit) || 0,
      day: card.day || null,
      owner: !!(card.info && card.info.owner),
      // whether this phone is its owner, which the card was asked (a till does not ask)
      ownedHere: card.mine === true,
      mint: (card.record && card.record.mint) || '',
      recoverable: !!(card.record && card.record.refundKey),
      mine: !!(W && W.cardIsMine(card)),
      first: dates.length ? Math.min.apply(null, dates) : 0,
      last: dates.length ? Math.max.apply(null, dates) : 0,
      check: (card.pieces || []).length ? 'asking' : 'none',
    } });
    if ((card.pieces || []).length) this.fcCheck(card);
    // ecash found for this card is asked of the mint, and the line about it redrawn if any of it was not owed after all
    if (W && W.cardOwedCheck) W.cardOwedCheck(card).then((gone) => { if (gone) this.forceUpdate(); }, () => {});
  }

  /* The mint's word on what the card says it holds. A card is a list of
   * pieces and a promise not to sign twice; whether the pieces are still good
   * is something only the mint knows. */
  fcCheck(card) {
    const W = this.fcW();
    /* With the mint's word goes when it was given: now, or, where the mint
     * could not be asked, when this phone last had it for these same pieces
     * (`cardCheckedAt`). The screen says that under its title. */
    const put = (check, at) => {
      if (!this.state.fc || this.state.fc.key !== card.key || this._fcCard !== card) return;
      this.setState({ fc: Object.assign({}, this.state.fc, { check, checkedAt: Number(at) || 0 }) });
    };
    const before = () => { try { return W.cardCheckedAt ? W.cardCheckedAt(card) : 0; } catch (e) { return 0; } };
    W.cardCheck(card).then((r) => put(r.spent > 0 ? { spent: r.spent } : 'ok', r.spent > 0 ? 0 : (r.at || Date.now())),
                           (e) => put((e && e.card) === 'other-mint' ? 'other' : 'off', before()));
  }

  /* How long ago, as a title says it: "Just Now", "2 Hours Ago" (`agoWords`,
   * with its words capitalised). */
  fcAgo(ms) {
    const n = Math.max(0, Number(ms) || 0);
    if (n < 90 * 1000) return 'Just Now';
    return String(this.agoWords(n)).replace(/\b[a-z]/g, (c) => c.toUpperCase());
  }

  /* Whether money can be moved on or off the card that is on screen, said
   * before any pad is raised. */
  fcReady(doing) {
    const fc = this.state.fc;
    if (!fc || !this._fcCard) return false;
    if (this.offlineNow()) { this.offlineNo(doing); return false; }
    const W = this.fcW();
    const here = (W && W.mintHost && W.mintHost()) || '';
    const there = String(fc.mint || '').replace(/^https?:\/\//, '').replace(/\/+$/, '');
    if (there && here && there !== String(here).replace(/^https?:\/\//, '').replace(/\/+$/, '')) {
      this.fcOtherMint(doing);
      return false;
    }
    return true;
  }

  /* The card is at another mint than this phone. What can be done about it
   * depends on what is on it:
   *
   *   anything, and the only way is to take it all off first (a card's money is
   *   at one mint, and the record cannot change under it): ADD FUNDS says so, in
   *   those words, with nothing to press but CLOSE; the other things a card does
   *   offer to move the phone to the card's mint, as ever;
   *   nothing, on its owner's phone: SWITCH TO <this phone's mint> goes straight
   *   to the amount, and the card's record is rewritten in the same tap that
   *   writes the funds (`fcAddRun`, the owner's proof, no PIN; its PIN, its
   *   owner, its limit and its time key stay as they are);
   *   nothing, on any other phone: only the phone that set the card up can
   *   change its record, and the card says so. */
  fcOtherMint(doing) {
    const fc = this.state.fc;
    const adding = doing === 'Adding funds';
    const at = this.mintNameOf(fc.mint), here = this.mintName();
    if (adding && fc.count > 0) {
      this.blockedCard('fc-other-mint', {
        tone: 'warn', title: 'A DIFFERENT MINT',
        reason: 'You need to withdraw all funds on the card before you can switch mints.',
      });
      return;
    }
    if (adding && fc.ownedHere && fc.owner) {
      this.blockedCard('fc-other-mint', {
        tone: 'warn', title: 'A DIFFERENT MINT',
        reason: 'This card holds nothing, and is set up at ' + at + '. This phone is at ' + here + '.',
        retry: 'SWITCH TO ' + String(here).toUpperCase(), go: () => this.fcAmount('cardAdd'), shut: { label: 'CANCEL' },
      });
      return;
    }
    if (adding) {
      this.blockedCard('fc-other-mint', {
        tone: 'warn', title: 'A DIFFERENT MINT',
        reason: 'This card holds nothing, and is set up at ' + at + '. This phone is at ' + here
          + '. Only the phone that set the card up can switch it to another mint: use that phone to do it.',
      });
      return;
    }
    this.blockedCard('fc-other-mint', {
      tone: 'warn', title: 'A DIFFERENT MINT',
      reason: 'This card’s money is at ' + at + '. This phone is at ' + here + '.',
      retry: 'SWITCH MINT', go: () => this.goSwitchMint(), shut: { label: 'CANCEL' },
    });
  }

  /* ---- a new card ----------------------------------------------------------
   * A PIN, typed twice; a notice, once, that this phone becomes the card's owner
   * and what that means; then whether a lost card's money can come back (while
   * FC_RECOVERABLE offers it); then one tap that writes the PIN, the record and,
   * last, the owner. No limit is asked for or suggested: a new card has none, and
   * one is set later from CHANGE LIMIT. The PIN is typed here, once, and never
   * again to add funds. The mint is this phone's, shown and not chosen. */
  fcSetUp() {
    if (!this.state.fc) return;
    // no mint is asked: the card is told this phone's mint and given a key from this phone's words
    const first = (warn) => this.fcAskPin({
      title: 'CHOOSE A PIN',
      subtitle: 'Four to eight digits. The card asks for it every time it pays.',
      warn: warn || '',
    }, (a) => this.fcAskPin({
      title: 'TYPE IT AGAIN',
      subtitle: 'So a mistyped digit does not become the card’s PIN.',
    }, (b) => {
      if (a !== b) { first('Those did not match. Start again.'); return; }
      this.fcSetUpOwner(a);
    }));
    first('');
  }

  /* The one place that says what making this phone the owner means. */
  fcSetUpOwner(pin) {
    this.blockedCard('fc-owner', {
      tone: 'ask', title: 'SET UP THIS CARD',
      reason: 'This phone can reset this card’s PIN and limit. Whoever holds the card and this phone’s seed phrase holds its money.',
      retry: 'CONTINUE',
      go: () => { if (this.FC_RECOVERABLE) this.fcSetUpKind(pin); else this.fcSetUpRun(pin, false); },
      shut: { label: 'CANCEL' },
    });
  }

  fcSetUpRun(pin, recoverable) {
    const W = this.fcW();
    this.fcTap({ body: 'Setting it up at ' + this.mintName() + '.' }, (link, on) => { on('writing'); return W.cardSetUp(link, { pin, recoverable }); })
      .then((card) => {
        this.fcShow(card);
        this.haptic && this.haptic('success');
        /* What cash means, said once, where the card becomes one: there is
         * nobody to ask for it back. Its PIN is part of that. The card
         * blocks itself for good after three wrong ones in a row, and what
         * is on a blocked cash card can be spent by nobody but this phone,
         * which can unblock it. */
        this.blockedCard('fc-ready', {
          tone: 'ask', title: 'THE CARD IS READY',
          reason: recoverable
            ? 'It holds nothing yet. What you put on it can be taken back by this phone a year later, if the card is lost.'
            : 'It holds nothing yet. It is cash: whoever has the card and its PIN has the money.',
          chip: recoverable ? '' : 'Lose the card and the money on it is gone.',
          retry: 'ADD FUNDS', go: () => this.fcAdd(), shut: { label: 'LATER' },
        });
      }, (e) => this.fcFailed(e, { again: () => this.fcSetUpRun(pin, recoverable) }));
  }

  fcSetUpKind(pin) {
    this.blockedCard('fc-kind', {
      tone: 'ask', title: 'IF THE CARD IS LOST',
      reason: 'RECOVERABLE: this phone can take the money back after a year.\n'
        + 'LIKE CASH: lose the card and the money is gone. Choose it for a gift.',
      chip: 'Its money will be at ' + this.mintName() + '.',
      retry: 'RECOVERABLE', go: () => this.fcSetUpRun(pin, true),
      shut: { label: 'LIKE CASH', tap: () => this.fcSetUpRun(pin, false) },
    });
  }

  /* ---- add funds ------------------------------------------------------------
   * The amount, the card's PIN, then the mint, then the card: the pieces are
   * made before the tap, so the card is held for as long as writing takes and
   * no longer. A tap that fails leaves them owed to the card. */
  fcAdd() {
    if (!this.fcReady('Adding funds')) return;
    this.fcAmount('cardAdd');
  }

  /* The owner's phone adds funds with its own proof and no PIN: the PIN was
   * typed once, at set-up. Any other phone, with the card's PIN, adds them as a
   * till writes change. The daily limit is not touched by putting money on. */
  fcAddPin(sats) {
    const fc = this.state.fc;
    if (fc && fc.ownedHere) { this.fcLeaveAmount(); this.fcAddRun(sats, '', true); return; }
    this.fcAddAskPin(sats);
  }

  fcAddAskPin(sats) {
    this.fcAskPin({
      title: 'CARD PIN',
      subtitle: 'To add ' + this.fcBoth(sats) + ' to the card.',
      cta: 'ADD ' + this.fcPrice(sats) + ' TO CARD',
    }, (pin) => { this.fcLeaveAmount(); this.fcAddRun(sats, pin, false); });
  }

  fcAddRun(sats, pin, owner) {
    const W = this.fcW();
    const card = this._fcCard;
    this.stageScreen('cardReady', {
      art: 'card', title: 'GETTING<br>IT READY', amount: this.stageMoney(sats),
      body: 'Keep the card nearby. You will be asked to tap it in a moment.',
      dots: true, forMs: 90000, button: 'CLOSE',
    });
    /* A card that holds nothing and is at another mint than this phone's is told
     * its new mint in the tap that writes the funds (the owner's proof; `fcOtherMint`
     * only offers this to its owner): the money is made for the mint this phone is at. */
    const there = String((card && card.record && card.record.mint) || '').replace(/\/+$/, '');
    const here = String(W.mintUrl || '').replace(/\/+$/, '');
    const moving = !!(there && here && there !== here && !((card.pieces || []).length));
    W.cardPrepare(card, sats, { moving }).then((made) => {
      // said by this flow, so not announced as a payment sent (16-history-lists.js)
      if (made && made.hash) this.txIsNew(made.hash);
      this.hideStage('cardReady');
      this.fcWriteRun(pin, { sats: made.sats, owner: !!owner, asked: sats, rounded: Number(made.rounded) || 0 });
    }, (e) => {
      this.hideStage('cardReady');
      this.fcFailed(e, {});
    });
  }

  /* ---- withdraw --------------------------------------------------------------
   * An amount on the keypad, or ALL OF IT, which is the button under its
   * NEXT (23-render-home-and-amount.js). */
  fcWithdraw() {
    if (!this.fcReady('Withdrawing')) return;
    const fc = this.state.fc;
    if (!(fc.balance > 0)) { this.toast('There is nothing on this card.', true); return; }
    this.fcAmount('cardWd');
  }

  fcWithdrawPin(sats) {
    const fc = this.state.fc;
    if (!fc) return;
    this.fcAskPin({
      title: 'ENTER PIN TO WITHDRAW',
      subtitle: (sats ? this.fcBoth(sats) : 'Everything') + ' from the card to this phone.',
      cta: sats ? 'WITHDRAW ' + this.fcPrice(sats) : 'WITHDRAW ALL',
    }, (p) => { this.fcLeaveAmount(); this.fcWithdrawRun(sats, p); });
  }

  /* `before`: what earlier taps of this same withdrawal took off the card
   * (a tap cut short keeps what the card signed, and the next takes the rest).
   * The PIN is held for the length of the withdrawal, as for one tap: the
   * card that says TAP CARD for the rest is still this flow, and LATER ends it. */
  /* `again`: { rest } where this is the sheet come up by itself for the rest of
   * a withdrawal cut short; a tap of it that reads no card puts the TAP CARD
   * card up instead. */
  fcWithdrawRun(sats, pin, before, again) {
    const W = this.fcW();
    const prior = Math.round(Number(before) || 0);
    /* What came off in this tap's sheet, as it is cut short and taken up again
     * in the same sheet (`again` below), and what is still to take. */
    let took = prior, ask = sats;
    const counted = new Set();
    const absorb = (e) => {
      if (!e || e.card !== 'partial' || counted.has(e)) return;
      counted.add(e);
      took += Math.round(Number(e.sats) || 0);
      if (e.hash) this.txIsNew(e.hash);
      ask = sats ? Math.round(Number(e.left) || 0) : 0;
    };
    const partCard = (got, rest) => this.blockedCard('fc-part', {
      tone: 'warn', title: 'TAP THE CARD AGAIN',
      reason: this.fcSats(got) + ' came off the card into this phone before it was taken away. Tap it again for the rest'
        + (rest > 0 ? ', ' + this.fcSats(rest) + '.' : '.'),
      chip: 'Hold it still until the phone says to remove it.',
      retry: 'TAP CARD', go: () => this.fcWithdrawRun(sats ? rest : 0, pin, got),
      shut: { label: 'LATER' },
    });
    const said = (r) => {
      // the card as it reads now, where the tap lasted long enough to read it; otherwise its screen goes
      if (r && r.card) this.fcShow(r.card); else this.fcGone();
      this.haptic && this.haptic('success');
      const got = took + Math.round(Number(r && r.sats) || 0);
      this.blockedCard('fc-out', {
        tone: 'ask', title: 'IN YOUR WALLET',
        reason: (got > 0 ? this.fcSats(got) : 'The money') + ' from the card is in this phone now.',
        shut: { label: 'DONE' },
      });
    };
    const opt = { taken: true, again: () => this.fcWithdraw(), done: () => said(null) };
    this.fcTap({ amount: sats ? this.stageMoney(sats) : '', warm: true, sheet: again ? 'Hold the card here again for the rest' : '',
                 again: (e) => {
                   if (e && e.card === 'partial' && Number(e.left) > 0) { absorb(e); return 'Hold the card here again for the rest'; }
                   return (e && e.card === 'gone') ? 'Hold the card here again' : '';
                 } },
               (link, on, progress) => W.cardWithdraw(link, ask ? { pin, sats: ask, on, progress } : { pin, on, progress }))
      .then((r) => {
        if (r && r.hash) this.txIsNew(r.hash);
        this.fcMoved({});
        said(r);
        const ch = r && r.change;
        if (ch && !ch.written && !ch.unmade && ch.sats > 0) this.fcChangeWaiting(ch.sats);
      }, (e) => {
        absorb(e);
        /* The sheet looked for the card again and was dismissed, or a sheet for
         * the rest read no card: the TAP CARD card, with what came off so far. */
        if (took > prior || (again && e && (e.card === 'cancelled' || e.card === 'gone'))) {
          if (e && (e.sheetClosed || e.card === 'cancelled' || e.card === 'gone')) {
            this.fcMoved({});
            this.fcGone();
            partCard(took, sats ? ask : 0);
            return;
          }
        }
        if (!(e && e.card === 'partial')) { this.fcFailed(e, opt); return; }
        /* Cut short where the phone could not keep the sheet up (an older one):
         * a new sheet comes up by itself for the rest, once iOS has taken the
         * last down, with the PIN already given. */
        this.fcMoved({});
        this.fcGone();
        this.haptic && this.haptic('warning');
        // nothing left on the card to take: the withdrawal is whole
        if (!(Math.round(Number(e.left) || 0) > 0)) { said({ sats: 0 }); return; }
        clearTimeout(this._fcResumeT);
        this._fcResumeT = setTimeout(() => this.fcWithdrawRun(sats ? ask : 0, pin, took, { rest: ask }), 2500);
      });
  }

  /* What the screen knew of the card is out of date and is not shown as if it
   * were current: the next thing to do with the card is to tap it. */
  fcGone() {
    this._fcCard = null;
    if (this.state.fc) this.setState({ fc: null });
    // with no list of cards to show, the screen with no card on it is not one to be left on
    if (!this.FC_RECOVERABLE && this.state.screen === 'flashcard') this.back();
  }

  /* ---- its PIN, its limit, its date ------------------------------------------ */

  /* CHANGE PIN, and UNBLOCK, which is the same: the owner's phone sets a new PIN
   * with its proof. The old PIN is not asked for, because this phone does not
   * know it and a blocked or forgotten PIN is the case that needs this. */
  fcChangePin() {
    const fc = this.state.fc;
    if (!fc) return;
    const W = this.fcW();
    // said before anything is asked
    if (!fc.owner) { this.fcFailed({ card: 'no-owner', message: 'This card has no owner, so its PIN cannot be changed.' }); return; }
    if (fc.ownedHere === false) { this.fcFailed({ card: 'not-owner' }); return; }
    const was = fc.pin === 'blocked';
    const fresh = (warn) => this.fcAskPin({
      title: 'NEW PIN', subtitle: 'Four to eight digits.', warn: warn || '',
    }, (a) => this.fcAskPin({ title: 'NEW PIN AGAIN', subtitle: 'So a mistyped digit does not become the card’s PIN.' }, (b) => {
      if (a !== b) { fresh('Those did not match. Start again.'); return; }
      this.fcTap({}, (link, on) => { on('writing'); return W.cardChangePin(link, { newPin: a }); })
        .then(() => {
          this.haptic && this.haptic('success');
          this.blockedCard('fc-pin', { tone: 'ask', title: was ? 'CARD UNBLOCKED' : 'PIN CHANGED', reason: 'The card asks for the new one from now on.', shut: { label: 'DONE' } });
          // what the screen knew of the card is out of date: a blocked card is not blocked now
          if (was && this.state.fc) this.setState({ fc: Object.assign({}, this.state.fc, { pin: 'set' }) });
        }, (e) => this.fcFailed(e, { again: () => this.fcChangePin() }));
    }));
    fresh('');
  }

  /* ---- the daily limit ---------------------------------------------------------
   *
   * The most the card signs for in one day. CHANGE LIMIT asks for it in three
   * steps, and the owner's phone sets it with its proof and
   * no PIN:
   *
   *   a warning       what a daily limit is, and who can change it
   *   an amount       the keypad every amount is typed on, dollars first, with
   *                   NO LIMIT as the way to remove one
   *   a confirmation  the amount again, and what it means
   *
   * `fcLimitAsk(done)` runs them and calls `done(sats)` with the screens that
   * were opened for them gone: `sats` is 0 for NO LIMIT. */
  fcLimitAsk(done) {
    this._fcLimitDone = done;
    this.blockedCard('fc-limit-warn', {
      tone: 'warn', title: 'SET DAILY LIMIT',
      reason: 'A daily limit is the most this card will spend in one day. It starts again by itself each day.\n\n'
        + 'Only this phone, or a phone restored from its seed phrase, can change or remove the limit.\n\n'
        + 'If you lose the seed phrase for this Foxy app, the PIN and the limit on this card can never be changed.\n\n'
        + 'Do you wish to continue?',
      retry: 'CONTINUE', go: () => this.fcAmount('cardLimit'),
      shut: { label: 'CANCEL', tap: () => { this._fcLimitDone = null; } },
    });
  }

  /* After NEXT on the keypad, or NO LIMIT under it: the confirmation, over it. */
  fcLimitConfirm(sats) {
    this.setState(p => ({ screen: 'fcLimitConfirm', stack: p.stack.concat([p.screen]), fcLimit: { sats: Math.max(0, Math.round(Number(sats) || 0)) } }));
  }

  /* The confirmation shell's contents (confirmSpec). */
  fcLimitSpec() {
    const sats = ((this.state.fcLimit || {}).sats) || 0;
    const secondary = { label: 'CANCEL', go: () => this.fcLimitCancel() };
    if (!(sats > 0)) {
      return {
        title: 'CONFIRMATION', amountLabel: 'YOU ARE REMOVING THIS CARD’S DAILY LIMIT.',
        amount: 'NO LIMIT', amountSub: '', rows: [],
        warn: 'It will be able to spend everything on it.',
        secondary, cta: 'CONFIRM', ctaTone: 'go',
        go: () => this.fcLimitConfirmed(),
      };
    }
    return {
      title: 'CONFIRMATION', amountLabel: 'YOU ARE APPLYING A DAILY LIMIT OF:',
      amount: this.money(sats).main, amountSub: this.money(sats).sub, rows: [],
      /* The two sentences go under the amount, in this order. They are set as
       * `warn` because the shell's subtitle sits above the amount, and would read first. */
      warn: 'This card will spend no more than this in one day. The limit starts again by itself each day. '
        + 'Only this phone, or a phone restored from its seed phrase, can change or remove it.',
      secondary, cta: 'CONFIRM', ctaTone: 'go',
      go: () => this.fcLimitConfirmed(),
    };
  }

  /* Off the confirmation and the keypad under it, to where the flow began. */
  fcLimitLeave() {
    this.setState(p => {
      const at = p.screen === 'fcLimitConfirm' ? 2 : p.screen === 'amount' ? 1 : 0;
      const back = p.stack.length >= at ? p.stack[p.stack.length - at] : 'flashcard';
      return at ? { screen: back, stack: p.stack.slice(0, -at), fcLimit: null, flow: 'receive', amount: '', unit: 'USD' } : { fcLimit: null };
    });
  }

  fcLimitCancel() {
    this._fcLimitDone = null;
    this.fcLimitLeave();
  }

  fcLimitConfirmed() {
    const sats = ((this.state.fcLimit || {}).sats) || 0;
    const done = this._fcLimitDone;
    this._fcLimitDone = null;
    this.fcLimitLeave();
    // zero is a choice here: NO LIMIT
    if (done) done(sats);
  }

  /* CHANGE LIMIT. */
  fcSetLimit() {
    const fc = this.state.fc;
    if (!fc) return;
    // said before anything is asked: a card with no owner has nobody to set its limit, and another phone's card is not this one's to
    if (!fc.owner) { this.fcFailed({ card: 'no-owner', message: 'This card has no owner, so its limit cannot be changed.' }); return; }
    if (fc.ownedHere === false) { this.fcFailed({ card: 'not-owner' }); return; }
    this.fcLimitAsk((sats) => this.fcLimitRun(sats));
  }

  /* One tap that sets the limit with this phone's proof that it is the owner. No PIN is asked. */
  fcLimitRun(sats) {
    const W = this.fcW();
    this.fcTap({}, (link, on) => { on('writing'); return W.cardSetLimit(link, { sats }); })
      .then((card) => {
        this.fcShow(card);
        this.haptic && this.haptic('success');
        this.toast(sats > 0 ? 'Daily limit set.' : 'Daily limit removed.');
      }, (e) => this.fcFailed(e, { again: () => this.fcLimitRun(sats) }));
  }

  /* ---- its mint -------------------------------------------------------------
   *
   * SWITCH MINT moves the card, and its money with it, to another mint:
   *
   *   which mint            the app's own list of mints, asked "TO WHICH MINT?"
   *   what it costs         the confirmation screen every move has: what
   *                         moves, about what arrives, the most the fee can be
   *   the PIN, and a tap    everything comes off the card into this phone
   *   the crossing          by Lightning, with no card: it takes longer than
   *                         a card can be held, and the phone's own card sheet
   *                         gives up after a minute
   *   a second tap          the card is told its new mint, and the money is
   *                         written onto it
   *
   * The money pays for its own crossing (`cardMoveQuote`): this phone's own
   * balance is not dipped into, and what stays behind is the part of the
   * Lightning fee's reserve that was not used, in this phone at the old mint.
   * Cut short anywhere, the money is in this phone and the card is empty and
   * still good. A card with nothing on it needs none of this: one tap.
   *
   * The phone is taken to the other mint for as long as this lasts and put
   * back when it ends, however it ends (`fcMoveEnd`). */
  fcSwitchMint() {
    const fc = this.state.fc;
    const W = this.fcW();
    if (!fc || !this._fcCard || !W) return;
    if (this.offlineNow()) { this.offlineNo('Moving a card to another mint'); return; }
    // a move connects to another mint, and waits like every switch for money that is already moving
    if (this.refuseSwitchWhileBusy && this.refuseSwitchWhileBusy()) return;
    if (this.fcOwed().some(r => r.key === fc.key)) {
      this.blockedCard('fc-owed-first', {
        tone: 'warn', title: 'PUT IT ON FIRST',
        reason: 'Money is waiting to go onto this card. Put it on, then move the card.',
        retry: 'TAP CARD', go: () => this.fcWriteAsk({}), shut: { label: 'CANCEL' },
      });
      return;
    }
    /* Whichever mint this phone is at. The money comes off the card at the
     * card's own mint, and this phone is taken there for as long as the move
     * lasts (`fcMoveQuote`) and put back after (`fcMoveEnd`). It was refused
     * from any other mint with a card whose button opened this phone's own
     * list of mints: a person at the mint they wanted the card moved to was
     * sent to switch away from it, and round again. */
    // through the one way into that list, which clears every other question it can be asking
    this.goSwitchMint({ fcPick: true });
  }

  /* A mint tapped on that list. */
  fcSwitchPick(url) {
    const fc = this.state.fc;
    const W = this.fcW();
    const to = String(url || '').replace(/\/+$/, '');
    if (!this.state.fcPick) return;
    if (!fc || !W || !to) { this.setState({ fcPick: false }); this.back(); return; }
    this._fcMoveWas = String(W.mintUrl || '').replace(/\/+$/, '');
    if (!(fc.balance > 0)) {
      // nothing to move: off the list, and the card is told its new mint in one tap, with this phone's proof that it owns it
      this.setState(p => ({ fcPick: false, screen: p.stack.length ? p.stack[p.stack.length - 1] : 'flashcard', stack: p.stack.slice(0, -1) }));
      this.fcRepointRun(to);
      return;
    }
    // the confirmation takes the list's place: back from it is the card's own screen
    this.setState({
      fcPick: false, screen: 'fcMoveConfirm',
      fcMove: { from: String(fc.mint || '').replace(/\/+$/, ''), to, sats: fc.balance, plan: null, fee: null, lands: 0, err: '', busy: false },
    });
    this.fcMoveQuote();
  }

  fcRepointRun(to) {
    const W = this.fcW();
    const end = () => this.fcMoveEnd();
    Promise.resolve()
      .then(() => (String(W.mintUrl || '').replace(/\/+$/, '') === to ? null : W.connect(to, null, null, { remember: false })))
      .then(() => this.fcTap({}, (link, on) => { on('writing'); return W.cardRepoint(link); }))
      .then((card) => {
        this.fcShow(card);
        end();
        this.haptic && this.haptic('success');
        this.blockedCard('fc-moved', { tone: 'ask', title: 'MOVED', reason: 'This card is now at ' + this.mintNameOf(to) + '.', shut: { label: 'DONE' } });
      }, (e) => { end(); this.fcFailed(e, { again: () => this.fcSwitchMint() }); });
  }

  /* About what it will cost, asked of both mints before the card is touched.
   * Nothing is spent by asking. */
  fcMoveQuote() {
    const W = this.fcW();
    const m = this.state.fcMove;
    if (!W || !m) return;
    const put = (more) => { if (this.state.fcMove) this.setState({ fcMove: Object.assign({}, this.state.fcMove, more) }); };
    put({ quoting: true, err: '' });
    // to the card's mint first, where this phone is not there already: a visit, not a change of this phone's own mint
    const bare = (u) => String(u || '').replace(/\/+$/, '');
    this._fcVisit = Promise.resolve()
      .then(() => (bare(W.mintUrl) === bare(m.from) ? null : W.connect(m.from, null, null, { remember: false })));
    this._fcVisit.then(() => W.cardMoveQuote(m.from, m.to, m.sats, { quoteOnly: true, pieces: (this.state.fc || {}).count })).then((plan) => {
      // what leaves the card, less what lands, is the most the crossing can cost
      put({ quoting: false, plan, lands: plan.net, fee: Math.max(0, m.sats - plan.net) });
    }, (e) => {
      put({ quoting: false, plan: null, fee: null, err: (e && e.card === 'too-little') ? String(e.message) : W.reason(e) });
    });
  }

  /* The confirmation screen's contents (confirmSpec), in the transfer's own shape. */
  fcMoveSpec() {
    const m = this.state.fcMove || { sats: 0 };
    const rows = [
      this.cfRow('MOVING TO', (this.mintNameOf(m.to) || '').toUpperCase()),
      this.cfRow('FROM', (this.mintNameOf(m.from) || '').toUpperCase(), { half: true }),
      this.cfRow('NETWORK', 'LIGHTNING', { half: true }),
      this.cfRow('ARRIVES ON THE CARD', m.err ? 'UNKNOWN' : m.fee == null ? 'CHECKING\u2026' : 'ABOUT ' + this.money(m.lands).main, { ink: 'var(--acc)', half: true }),
      this.cfRow('FEE', m.err ? 'UNKNOWN' : m.fee == null ? 'CHECKING\u2026' : 'UP TO ' + this.money(m.fee).main, { half: true }),
    ];
    const cancel = { label: 'CANCEL', go: () => this.fcMoveCancel() };
    if (m.err) {
      return {
        title: 'CONFIRMATION', amountLabel: 'MOVING THIS CARD',
        amount: this.money(m.sats).main, amountSub: this.money(m.sats).sub, amountInk: '#FF5C5C', rows,
        warn: m.err, cta: 'TRY AGAIN', ctaTone: 'warn', go: () => this.fcMoveQuote(), secondary: cancel,
      };
    }
    return {
      title: 'CONFIRMATION', amountLabel: 'MOVING THIS CARD',
      amount: this.money(m.sats).main, amountSub: this.money(m.sats).sub, rows,
      subtitle: m.fee == null ? '' : 'The card is tapped twice: once to take the money off, once to put it back.',
      secondary: cancel,
      cta: m.busy ? 'MOVING\u2026' : m.fee == null ? 'CHECKING THE FEE\u2026' : 'MOVE ' + this.money(m.sats).main,
      ctaTone: 'go', ctaBusy: !!m.busy || m.fee == null,
      go: () => { if (m.fee != null && !m.busy) this.fcMoveGo(); },
    };
  }

  /* CANCEL on the confirmation: nothing has moved, and the phone goes back to the mint it was at. */
  fcMoveCancel() {
    this.fcMoveEnd(null);
  }

  fcMoveGo() {
    const m = this.state.fcMove;
    if (!m || m.fee == null || m.busy) return;
    if (this.refuseSwitchWhileBusy && this.refuseSwitchWhileBusy()) return;
    this.fcAskPin({
      title: 'CARD PIN',
      subtitle: 'To move ' + this.fcBoth(m.sats) + ' to ' + this.mintNameOf(m.to) + '.',
      cta: 'MOVE ' + this.fcPrice(m.sats),
    }, (pin) => this.fcMoveOff(pin));
  }

  /* The first tap: everything off the card, into this phone. */
  fcMoveOff(pin) {
    const W = this.fcW();
    const m = this.state.fcMove;
    if (!m) return;
    const busy = (on) => { if (this.state.fcMove) this.setState({ fcMove: Object.assign({}, this.state.fcMove, { busy: on }) }); };
    busy(true);
    /* One thing was asked for, and it writes four entries: off the card, out
     * of one mint, into the other, onto the card. None is a payment to
     * announce. Quiet from here, as a crossing made for a tap is
     * (26d-tap.js), and every entry it wrote is marked seen when it ends
     * (`fcMoveEnd`): the crossing asks for its quote again when it pays, so
     * the entries cannot be named in advance. */
    this._quiet = true;
    this._fcQuiet = true;
    W.transactions(50).then((list) => { this._sweepBefore = new Set(list.map(x => x.hash)); },
                            () => { this._sweepBefore = null; });
    this.fcTap({ amount: this.stageMoney(m.sats), body: 'The first of two taps: the money comes off the card.', warm: true },
      (link, on) => W.cardWithdraw(link, { pin, on, hold: true }))
      .then((r) => {
        if (r && r.hash) this.txIsNew(r.hash);
        this.fcMoveAcross(r);
      }, (e) => { busy(false); this.fcLoud(); this.fcFailed(e, { taken: true, again: () => this.fcMoveGo() }); });
  }

  /* The quiet a move began is ended, with what it wrote marked as seen. */
  fcLoud() {
    if (!this._fcQuiet) return;
    this._fcQuiet = false;
    const loud = () => { this._quiet = false; };
    (this.hushSweepEntries ? this.hushSweepEntries() : Promise.resolve()).then(loud, loud);
  }

  /* The crossing, with no card: a plan the money itself pays for, the move,
   * and what landed made into pieces for the card at the far mint. */
  fcMoveAcross(off) {
    const W = this.fcW();
    const m = this.state.fcMove;
    const to = this.mintNameOf(m.to);
    const card = off.card || this._fcCard;
    let crossed = false;
    this.showMelt('Moving your sats to ' + to + '\u2026', 0, { sats: off.sats, mint: to });
    W.cardMoveQuote(m.from, m.to, off.sats).then((plan) => {
      /* More than was agreed to, by more than a sat or two of rounding: asked
       * again, with the money safe in this phone meanwhile. */
      const fee = Math.max(0, off.sats - plan.net);
      if (fee > m.fee + 2) { const e = /** @type {any} */ (new Error('fee')); e.fcFee = fee; throw e; }
      if (this.hushMove) this.hushMove(plan);
      return W.moveRun(plan, () => {}, { visit: true });
    }).then((done) => {
      crossed = true;
      return W.cardMoveLoad(card, done.sats);
    }).then((made) => {
      if (made && made.hash) this.txIsNew(made.hash);
      this.hideMelt();
      this.fcMoveOn(made);
    }, (e) => {
      this.hideMelt();
      /* Not moved, or moved and too little to put on a card. Either way the
       * money is this phone's, at a mint it can be seen at, and the card is
       * empty. Said with where it is. */
      const where = this.mintNameOf(crossed ? m.to : m.from);
      this.fcMoveEnd(off.card);
      this.blockedCard('fc-move-failed', {
        tone: 'warn', title: crossed ? 'NOT PUT ON THE CARD' : 'NOT MOVED',
        reason: (e && e.fcFee) ? 'The fee is now up to ' + this.fcSats(e.fcFee) + ', more than was shown.'
          : (e && e.card) ? String(e.message) : W.reason(e),
        chip: 'The money is in this phone, at ' + where + '. The card is empty.',
      });
    });
  }

  /* The second tap: the card is told its new mint, and the money goes on, both
   * with this phone's proof that it owns the card: no PIN is asked again. */
  fcMoveOn(made) {
    const W = this.fcW();
    const m = this.state.fcMove;
    const to = this.mintNameOf(m.to);
    this.fcTap({ amount: this.stageMoney(made.sats), body: 'The second tap: the money goes back on, at ' + to + '.' },
      (link, on) => { on('writing'); return W.cardWrite(link, { owner: true }); })
      .then((r) => {
        this.fcMoveEnd(r.card);
        if (r.left > 0 || !(r.sats > 0)) { this.fcWrote(r, {}); return; }
        this.haptic && this.haptic('success');
        this.blockedCard('fc-moved', {
          tone: 'ask', title: 'MOVED',
          reason: 'This card is now at ' + to + ' and holds ' + this.fcBoth(r.card.balance) + '.',
          shut: { label: 'DONE' },
        });
      }, (e) => {
        /* The money is at the new mint, made for this card and waiting for
         * it. Tapped again now, or later from the line on the card's screen. */
        if (e && (e.card === 'cancelled' || e.card === 'gone')) {
          this.blockedCard('fc-move-tap', {
            tone: 'warn', title: 'TAP THE CARD AGAIN',
            reason: this.fcBoth(made.sats) + ' is at ' + to + ', waiting to go onto this card.',
            retry: 'TAP CARD', go: () => this.fcMoveOn(made),
            shut: { label: 'LATER', tap: () => this.fcMoveEnd(null) },
          });
          return;
        }
        this.fcMoveEnd(null);
        this.fcFailed(e, {});
      });
  }

  /* The end of a move, however it went: the confirmation gives way to the
   * card's screen (showing `card` where there is one to show), and the phone
   * goes back to the mint it was at. */
  fcMoveEnd(card) {
    const W = this.fcW();
    const was = this._fcMoveWas;
    this._fcMoveWas = '';
    if (this.state.screen === 'fcMoveConfirm') {
      this.setState(p => ({ fcMove: null, screen: p.stack.length ? p.stack[p.stack.length - 1] : 'flashcard', stack: p.stack.slice(0, -1) }));
    } else if (this.state.fcMove) {
      this.setState({ fcMove: null });
    }
    if (card) this.fcShow(card);
    this.fcLoud();
    const home = () => { this.refreshBalance(); this.loadHistory(); };
    // after a visit that is still being made (CANCEL pressed while it was): put back from where that leaves it
    const visit = this._fcVisit || Promise.resolve();
    this._fcVisit = null;
    const put = () => {
      if (W && was && String(W.mintUrl || '').replace(/\/+$/, '') !== was) W.connect(was).then(home, home);
      else home();
    };
    visit.then(put, put);
  }

  /* Everything off the card and on again, which is the only way its pieces
   * get a new date: the date is part of each piece. */
  fcRenew() {
    if (!this.fcReady('Renewing a card')) return;
    const W = this.fcW();
    const fc = this.state.fc;
    this.fcAskPin({
      title: 'CARD PIN',
      subtitle: 'To renew ' + this.fcBoth(fc.balance) + ' for another year.',
      cta: 'RENEW',
    }, (pin) => this.fcTap({ amount: this.stageMoney(fc.balance), body: 'This takes longer than a payment. Keep the card there.', warm: true },
      (link, on, progress) => W.cardRenew(link, { pin, on, progress }))
      .then((r) => {
        (r.hashes || []).forEach(h => this.txIsNew(h));
        this.fcWrote(r, {});
      }, (e) => {
        ((e && e.hashes) || []).forEach(h => this.txIsNew(h));
        this.refreshBalance();
        this.loadHistory();
        this.fcFailed(e, { again: () => this.fcRenew() });
      }));
  }

  /* ---- a lost card ---------------------------------------------------------- */
  fcRowCard(row) {
    const name = this.fcName(row.key);
    if (row.takenBack) {
      this.blockedCard('fc-row', { tone: 'ask', title: name, reason: 'Its money was taken back to this phone.' });
      return;
    }
    if (!row.due) {
      this.blockedCard('fc-row', {
        tone: 'ask', title: name,
        reason: (row.sats ? this.fcSats(row.sats) + ' when this phone last saw it. ' : 'Empty when this phone last saw it. ')
          + (row.date ? 'If it is lost or blocked, this phone can take its money back after ' + this.fcDay(row.date) + '.' : ''),
      });
      return;
    }
    this.blockedCard('fc-row', {
      tone: 'warn', title: 'TAKE IT BACK?',
      reason: this.fcSats(row.sats) + ' was on ' + name + ' when this phone last saw it. '
        + 'Use this only if the card is lost or blocked.',
      chip: 'The card will be empty.',
      retry: 'TAKE IT BACK', go: () => this.fcTakeBack(row.key),
      shut: { label: 'CANCEL' },
    });
  }

  fcTakeBack(key) {
    const W = this.fcW();
    if (this.offlineNow()) { this.offlineNo('Taking a card back'); return; }
    this.stageScreen('cardBack', { art: 'card', title: 'TAKING<br>IT BACK', body: 'Asking the mint what is left on it.',
                                   dots: true, forMs: 90000, button: 'CLOSE' });
    W.cardTakeBack(key).then((r) => {
      this.hideStage('cardBack');
      if (r && r.hash) this.txIsNew(r.hash);
      this.refreshBalance();
      this.loadHistory();
      this.forceUpdate();
      if (!(r.sats > 0)) {
        this.blockedCard('fc-back', { tone: 'warn', title: 'NOTHING WAS LEFT ON IT', reason: 'Everything this phone put on that card has been spent.' });
        return;
      }
      this.haptic && this.haptic('success');
      this.blockedCard('fc-back', {
        tone: 'ask', title: 'BACK IN YOUR WALLET',
        reason: this.fcSats(r.sats) + ' from the card is in this phone now.'
          + (r.later > 0 ? ' ' + this.fcSats(r.later) + ' more can be taken back later.' : ''),
        shut: { label: 'DONE' },
      });
    }, (e) => {
      this.hideStage('cardBack');
      if ((e && e.card) === 'other-mint') {
        this.blockedCard('fc-other-mint', { tone: 'warn', title: 'A DIFFERENT MINT', reason: String(e.message || ''),
          retry: 'SWITCH MINT', go: () => this.goSwitchMint(), shut: { label: 'CANCEL' } });
        return;
      }
      this.fcFailed(e, { again: () => this.fcTakeBack(key) });
    });
  }

  /* The designs a card's face can be drawn in, each by a code of three
   * characters (capital letters and digits).
   *
   * A card maker takes a code nobody has taken and adds its drawing; the
   * codes taken are listed here and in docs/CARD-DESIGNS.md of the card
   * repository (https://github.com/getfoxy/card), so that anybody can see which are. FL1 is the first
   * Flash design, and the one design drawn so far (build/markup.html, the
   * card on the FLASHCARD screen). A card does not yet say which design it
   * is, so every card is drawn as FC_DESIGN. */
  FC_DESIGNS = {
    FL1: { name: 'Flash, first design', by: 'Flash' },
  };
  FC_DESIGN = 'FL1';

  /* The design to draw a card in: the one it names, where it names one this
   * build can draw, and FC_DESIGN otherwise. */
  fcDesignOf(card) {
    const code = String((card && card.design) || '').toUpperCase();
    return (/^[A-Z0-9]{3}$/.test(code) && this.FC_DESIGNS[code]) ? code : this.FC_DESIGN;
  }

  /* What has been done with this card, as this phone knows it: the history
   * screen, with only the entries that name it. A card keeps no list of its
   * own, so a payment it made at somebody else's phone is not here. */
  fcHistory() {
    const fc = this.state.fc;
    if (!fc || !fc.key) return;
    this.setState(p => ({ screen: 'history', stack: p.stack.concat([p.screen]), histCard: fc.key, histFilter: 'all' }));
    this.loadHistory();
  }

  /* flashcard: the card that was tapped, or the invitation to tap one. */
  /** @param {RenderContext} c */
  renderFlashcard(c) {
    const { s, sc } = c;
    const on = sc === 'flashcard';
    const W = on ? this.fcW() : null;
    const fc = (on && s.fc) || null;
    const now = Math.floor(Date.now() / 1000);
    const DIM = 'rgba(var(--ink-rgb),.55)';
    const AMBER = '#F7931A';
    const RED = '#FF5C5C';

    /* What this phone owes cards, first and in the warning colour: it is the
     * one thing on this screen that is waiting on the person. */
    const notes = !on ? [] : this.fcOwed().map(r => ({
      // the card on screen is "this card"; any other is named, since its name is shown nowhere else
      text: this.fcSats(r.sats) + ' is waiting to go onto '
        + ((fc && fc.key === r.key) ? 'this card. Press here, then tap it.' : this.fcName(r.key) + '. Press here, then tap that card.'),
      tap: () => this.fcWriteAsk({}),
    }));

    const rows = (!W || fc || !this.FC_RECOVERABLE) ? [] : W.cardsList().map(r => ({
      name: this.fcName(r.key),
      sub: r.takenBack ? 'Taken back'
        : r.sats ? this.fcSats(r.sats) + ' when last seen' : 'Empty when last seen',
      // only what can be done; the date it waits for is said when the row is opened
      text: (!r.takenBack && r.due && r.sats > 0) ? 'TAKE BACK' : '',
      ink: (r.due && r.sats > 0 && !r.takenBack) ? 'var(--acc-ink)' : DIM,
      tap: () => this.fcRowCard(r),
    }));

    const fresh = !!fc && (fc.pin === 'none' || !fc.hasRecord) && fc.pin !== 'blocked';
    const blocked = !!fc && fc.pin === 'blocked';
    // the owner's phone is offered UNBLOCK on a blocked card, which is CHANGE PIN
    const unblock = blocked && !!fc.ownedHere;
    // the card's day: the daily limit, what is left today, and when the day turns
    const day = (fc && fc.hasRecord && fc.day) || null;
    const limited = !!(day && day.limited);
    const usable = !!fc && fc.pin === 'set' && fc.hasRecord;
    const near = !!fc && fc.mine && fc.first > 0 && fc.first - now < this.FC_RENEW_DAYS * 86400;
    const past = near && fc.first <= now;

    /* One line on the card's own face, for what is true of the card itself
     * and is not the ordinary state: blocked, new, locked, or holding pieces
     * the mint says are spent. How fresh the mint's word is, is said once,
     * under the screen's title (`verified`, below); it was said here as well.
     * The card is drawn dark whatever the app's theme, so its inks are its
     * own. */
    const ON_CARD = 'rgba(255,255,255,.46)';
    const check = !fc ? ['', ON_CARD]
      : blocked ? ['Blocked', RED]
      : (fc.check && fc.check.spent) ? ['The mint says ' + this.fcSats(fc.check.spent) + ' is already spent', RED]
      : fc.pin === 'none' ? ['No PIN yet', AMBER]
      : !fc.hasRecord ? ['Not finished', AMBER]
      : fc.locked ? ['Locked', AMBER]
      : ['', ON_CARD];

    /* The card's mint and what it holds are in the pill, as home's are, and
     * under what it holds how much of its limit is left. CHANGE LIMIT is where
     * it is changed. */
    // a card in the last month before its date: said where the money waiting for a card is said, and renewed from there
    if (on && fc && near && !past && fc.balance > 0) {
      notes.push({ text: 'This card must be renewed by ' + this.fcDay(fc.first) + '. Press here, then tap it.', tap: () => this.fcRenew() });
    }

    /* The two smaller things to do with a card, in home's SCAN and PASTE
     * slots under ADD FUNDS and WITHDRAW: a lock for its PIN, a dial for its
     * limit. Both are the owner's: only the phone that holds the words the card
     * was set up with can do either. */
    const links = !usable ? [] : [
      { label: 'CHANGE PIN', ink: 'var(--ink)', tap: () => this.fcChangePin(), spin: 'rotate(180deg)',
        path: 'M6.4 10.4V7.6a5.6 5.6 0 0 1 11.2 0v2.8M5.2 10.4h13.6a1.4 1.4 0 0 1 1.4 1.4v7.4a1.4 1.4 0 0 1-1.4 1.4H5.2a1.4 1.4 0 0 1-1.4-1.4v-7.4a1.4 1.4 0 0 1 1.4-1.4Z' },
      { label: 'CHANGE LIMIT', ink: 'var(--ink)', tap: () => this.fcSetLimit(), spin: 'none',
        path: 'M4.6 16.8a8.2 8.2 0 1 1 14.8 0M12 13.6l3.7-4.4M12 14.6a1 1 0 1 0 0-2 1 1 0 0 0 0 2Z' },
    ];

    /* Under the title: how fresh the mint's word on this card is. Just now,
     * where it has just been asked; how long ago, on a phone that cannot ask
     * and has asked before about these same pieces; not verified, where it
     * never has, or where the mint says some of it is spent. A card with
     * nothing on it has nothing a mint could dispute. */
    const DIMMED = 'rgba(var(--ink-rgb),.62)';
    const nowMs = Date.now();
    const verified = (!fc || fresh || blocked || !fc.hasRecord) ? ['', DIMMED]
      : fc.check === 'asking' ? ['Verifying\u2026', DIMMED]
      : (fc.check && fc.check.spent) ? ['Not Verified', RED]
      : (fc.check === 'ok' || !(fc.count > 0)) ? ['Verified ' + this.fcAgo(fc.checkedAt ? nowMs - fc.checkedAt : 0), DIMMED]
      : fc.checkedAt ? ['Verified ' + this.fcAgo(nowMs - fc.checkedAt), DIMMED]
      : ['Not Verified', AMBER];

    const px = this.px ? this.px() : 0;
    return {
      isFlashcard: on,
      fcVerified: verified[0], fcVerifiedInk: verified[1], fcVerifiedShown: !!verified[0],
      // which design the card on screen is drawn in (FC_DESIGNS)
      fcDesign: this.fcDesignOf(fc),
      // a card that has been read says what it is on its own face
      fcSub: fc ? '' : 'Ecash on a card, spent with a tap and a PIN.',
      fcNone: on && !fc,
      fcHas: !!fc,
      fcNotes: notes,
      fcHasRows: rows.length > 0,
      fcRows: rows,
      /* Dollars first and the sats under them, as on home. With no price to
       * say dollars at, the sats are the figure and there is no second line. */
      /* Home's own pill, for a card that has a mint: the mint by the name this
       * phone knows it by, and what the card holds. */
      fcPill: !!fc && !!fc.hasRecord,
      fcPillMint: (fc && fc.hasRecord) ? String(this.mintNameOf(fc.mint) || '') : '',
      fcPillLetter: (fc && fc.hasRecord) ? (String(this.mintNameOf(fc.mint) || '?').slice(0, 1).toUpperCase() || '?') : '',
      fcBalance: !fc ? '' : px > 0 ? '$ ' + this.usd((fc.balance / 1e8) * px) : '\u20bf ' + this.group(fc.balance),
      fcShowAlt: !!fc && px > 0,
      fcBalanceAlt: (fc && px > 0) ? '\u20bf ' + this.group(fc.balance) : '',
      /* How much of its limit the card has left, under what it holds, in
       * dollars first as the balance is. A card that has none left says so. */
      fcLimitShown: !!fc && !!fc.hasRecord && fc.pin !== 'blocked',
      fcLimitLine: (fc && fc.hasRecord) ? (limited ? 'DAILY LIMIT ' + this.fcPrice(day.limit) : 'NO LIMIT') : '',
      // under the balance, where there is a limit: what the day has left, and when it turns
      fcDayShown: !!fc && !!fc.hasRecord && fc.pin !== 'blocked' && limited,
      fcDayLeft: limited ? 'LEFT TODAY ' + (day.left > 0 || !px ? this.fcPrice(day.left) : '$0.00') : '',
      fcDayTurns: limited ? (day.turns > 0 ? 'THE DAY TURNS AT ' + this.fcWhen(day.turns).toUpperCase() : 'A NEW DAY BEGINS WITH THE NEXT PAYMENT') : '',
      fcCheck: check[0], fcCheckInk: check[1],
      fcHasCheck: !!check[0],
      // what has been done with this card, on this phone: only for a card that is one (it has a key and a record)
      fcHistoryVis: (fc && fc.hasRecord) ? 'visible' : 'hidden',
      fcHistory: () => this.fcHistory(),
      fcNew: fresh,
      fcNewLine: (fc && fc.pin === 'set' && !fc.hasRecord)
        ? 'Its set-up was cut short. Finish it to put money on it.'
        : 'This card is new. Give it a PIN to put money on it.',
      fcBlocked: blocked,
      fcUnblock: unblock,
      fcUnblockTap: () => this.fcChangePin(),
      /* A blocked card's money: gone, where the card is cash; the loader's to
       * take back, where it is not (and here, where this phone can). */
      fcBlockedLine: (fc && fc.ownedHere)
        ? 'Too many wrong PINs. This phone can unblock the card by giving it a new PIN.'
        : (fc && fc.owner)
        ? 'Too many wrong PINs. Only the phone that owns this card can unblock it, with a new PIN.'
        : (fc && !fc.recoverable)
        ? 'Too many wrong PINs. This card is cash, so what is on it cannot be got back.'
        : (fc && fc.mine && this.FC_RECOVERABLE)
        ? 'Too many wrong PINs. This phone can take its money back after its date, from CARDS YOU LOADED.'
        : 'Too many wrong PINs. Only the phone that loaded it can take its money back, after its date.',
      fcUsable: usable,
      fcLinks: links,
      fcTap: () => this.fcRead(),
      fcAdd: () => this.fcAdd(),
      fcWithdraw: () => this.fcWithdraw(),
      fcSetUp: () => this.fcSetUp(),
    };
  }


  /* switchMint: the mint list. */
  /** @param {RenderContext} c */
  renderMints(c) {
    const { s, sc } = c;
    return {
      isSwitchMint: sc === 'switchMint',
      // adding a mint belongs to switching, not to picking one to move between
      mintPickers: !s.trStep && !s.fcPick,
      /* The same list does three jobs: switching, and the two steps of a
       * transfer between your own mints. */
      /* And a fourth, for a card: which mint it moves to (26f-flashcard.js).
       * `fcPick` says so, and like trStep it is named by whoever opens the
       * list and cleared by every other way in. */
      mintTitle: s.fcPick ? 'TO WHICH MINT?'
        : s.trStep === 'from' ? 'FROM WHICH MINT?'
        : s.trStep === 'to' ? 'TO WHICH MINT?' : 'SWITCH MINT',
      mintNowLine: s.fcPick ? 'This card is at ' + this.mintNameOf(s.fc && s.fc.mint) + '.'
        : s.trStep === 'from' ? 'Move money between the mints you use.'
        : s.trStep === 'to' ? 'Moving from ' + this.mintNameOf(s.trFrom) + '.'
        : 'Connected to ' + (this.mintHost() || 'no mint')
        // balances in other units, which no sat figure on this screen includes
        + (this.otherUnitsLine() ? '. ' + this.otherUnitsLine() : ''),
      /* The mint you are on comes first and looks different. It used to be
       * filtered out, which left the screen showing every mint except the one
       * that matters. */
      mintRows: (() => {
        const all = this.allMints();
        const row = (m, here) => {
          const pile = this.mintPile(m.url);
          const busy = s.mintBusy === m.url.replace(/\/+$/, '');
          // "not answering since 10:42", once the wallet counts it down (11-mint-risk.js)
          const downText = this.mintDownText(m.url);
          /* Working offline, a mint whose keysets are not on this phone cannot
           * be connected to. Greyed out, with the reason under its name, and a
           * tap says it rather than doing nothing. */
          const reach = this.mintReachable(m.url);
          return {
            name: m.name, host: m.host,
            dim: reach ? '1' : '0.4',
            down: !!downText, downText: downText,
            initial: m.name.slice(0, 1).toUpperCase(),
            tint: m.tint,
            logo: m.logo ? "url('" + m.logo + "')" : 'none',
            here: here, notHere: !here,
            text: busy ? 'CONNECTING\u2026' : pile.text,
            ink: (here || busy) ? 'var(--acc-ink)' : pile.ink,
            busy: busy,
            bg: here ? 'rgba(var(--acc-rgb),.12)' : 'var(--surface)',
            border: here ? 'rgba(var(--acc-rgb),.75)' : 'rgba(var(--ink-rgb),.12)',
            // tapping the one you are already on should do nothing at all
            tap: !reach ? (() => this.offlineNo('Switching to ' + m.name))
              : s.fcPick ? (() => this.fcSwitchPick(m.url))
              : s.trStep ? (() => this.trPick(m.url)) : here ? (() => {}) : (() => this.justSwitch(m.url)),
          };
        };
        if (s.fcPick) {
          // every mint but the one the card is at
          const at = String((s.fc && s.fc.mint) || '').replace(/\/+$/, '');
          return all.filter(m => m.url.replace(/\/+$/, '') !== at).map(m => row(m, false));
        }
        if (s.trStep === 'from') {
          // only mints with something at them can be moved from
          return all.filter(m => this.mintPile(m.url).sats > 0).map(m => row(m, false));
        }
        if (s.trStep === 'to') {
          const from = String(s.trFrom || '').replace(/\/+$/, '');
          return all.filter(m => m.url.replace(/\/+$/, '') !== from).map(m => row(m, false));
        }
        return all.filter(m => this.onMint(m.url)).map(m => row(m, true))
          .concat(all.filter(m => !this.onMint(m.url)).map(m => row(m, false)));
      })(),
      scanOtherMint: () => this.scanOtherMint(),
      typeOtherMint: () => this.typeMint(),
    };
  }

  /* newMint: a token from a mint this wallet has no balance at. */
  /** @param {RenderContext} c */
  renderNewMint(c) {
    const { s, sc } = c;
    const keepName = s.nmInfo ? this.mintNameOf(s.nmInfo.mint) : '';
    return {
      isNewMint: sc === 'newMint',
      nmSats: s.nmInfo ? (this.nmUnit() ? this.unitMoney(s.nmInfo.amount, s.nmInfo.unit) : this.group(s.nmInfo.sats) + ' sats') : '\u2014',
      nmHost: s.nmInfo ? String(s.nmInfo.mint).replace(/^https?:\/\//, '') : '',
      // a range, because the reserve and the margin usually come back
      nmFee: s.nmPlan
        ? (s.nmPlan.feeMin === s.nmPlan.feeMax
            ? this.group(s.nmPlan.feeMax) + ' sats'
            : 'between ' + this.group(s.nmPlan.feeMin) + ' \u2013 '
              + this.group(s.nmPlan.feeMax) + ' sats')
        : '\u2014',
      // the floor: the quote reserves for the worst case, and change comes back
      nmNetBig: this.nmUnit() ? this.unitMoney(s.nmInfo.amount, s.nmInfo.unit) : s.nmPlan ? 'at least ' + this.group(s.nmPlan.net) + ' sats' : '\u2014',
      // dollars under every figure, always — sats alone mean little to most
      nmSatsUsd: s.nmInfo ? (this.nmUnit() ? this.unitLabel(s.nmInfo.unit) + ' ecash' : '$ ' + this.usd(s.nmInfo.sats * this.satUsd())) : '\u2014',
      nmFeeUsd: s.nmPlan
        ? (s.nmPlan.feeMin === s.nmPlan.feeMax
            ? '$ ' + this.usd(s.nmPlan.feeMax * this.satUsd())
            : '$ ' + this.usd(s.nmPlan.feeMin * this.satUsd()) + ' \u2013 $'
              + this.usd(s.nmPlan.feeMax * this.satUsd()))
        : '\u2014',
      nmNetUsd: this.nmUnit() ? 'kept at that mint' : s.nmPlan ? '$ ' + this.usd(s.nmPlan.net * this.satUsd()) : '\u2014',
      // an error, a step or another unit's note; nothing otherwise
      nmNote: s.nmErr || s.nmStage || this.nmUnitNote() || '',
      nmNoteInk: s.nmErr ? '#FF5C5C' : 'rgba(var(--ink-rgb),.55)',
      nmRedeemCta: s.nmBusy ? 'WORKING\u2026'
        : s.nmTooSmall ? 'KEEP IT AT ' + keepName.toUpperCase()
        : (s.nmPlan || this.nmUnit()) ? 'REDEEM'
        : s.nmErr ? 'RETRY'
        : 'WAITING FOR THE FEE\u2026',
      // live when there is a plan to act on, and again when there is an error
      // to retry — dead only while it is actually waiting
      // a quieter way to keep a token of sats at its own mint, asked for, never assumed
      nmKeepShow: !!s.nmInfo && !this.nmUnit() && !s.nmTooSmall && !s.nmBusy,
      nmKeepLabel: 'Keep it at ' + keepName,
      nmKeep: () => this.newMintKeep(),
      nmGoBg: ((!!s.nmPlan || !!s.nmErr || this.nmUnit()) && !s.nmBusy)
        ? 'var(--acc)' : 'rgba(var(--ink-rgb),.14)',
      nmGoImg: ((!!s.nmPlan || !!s.nmErr || this.nmUnit()) && !s.nmBusy)
        ? "radial-gradient(120% 84% at 26% 0%,rgba(255,240,220,.26),rgba(255,240,220,0) 62%),"
          + "linear-gradient(168deg,rgba(247,154,60,.62),rgba(232,98,42,.72) 48%,"
          + "rgba(194,74,27,.78)),url('foxy-fur.webp')"
        : 'none',
      nmGoInk: ((!!s.nmPlan || !!s.nmErr || this.nmUnit()) && !s.nmBusy) ? '#fff' : 'rgba(var(--ink-rgb),.4)',
      nmGoCur: ((!!s.nmPlan || !!s.nmErr || this.nmUnit()) && !s.nmBusy) ? 'pointer' : 'default',
      nmRedeem: () => ((this.nmUnit() || this.state.nmTooSmall) ? this.newMintKeep()
        : this.state.nmPlan ? this.newMintRedeem() : this.nmQuote()),
      nmReject: () => this.setState({ screen: 'home', stack: [], nmInfo: null, nmPlan: null, nmErr: '', nmTooSmall: false }),
    };
  }

  /* importSeed and rsConfirm: the twelve-word restore and what it found. */
  /** @param {RenderContext} c */
  renderRestore(c) {
    const { s, sc } = c;
    /* The twelve words are typed on the phone's own screen: no cells here,
     * and the button asks the phone for them, so it is always ready. */
    const ready = true;
    return {
      isImportSeed: sc === 'importSeed',
      /* Paste proofs back in.
       *
       * The seed covers the normal case. This is for when it does not: a mint
       * that refuses deterministic restore, a lost counter, proofs saved out
       * of a wallet that is now gone. importProofs takes either a cashuB
       * token or a raw proofs array, and reconcile drops anything already
       * spent — so a stale paste is safe, it just recovers less. */
      goImportSeed: () => this.setState(p => ({
        screen: 'importSeed', stack: p.stack.concat([p.screen]),
        rsRows: [], rsErr: '', rsBusy: false, rsKept: '',
      })),
      rsScan: () => this.runSeedScan(false),
      rsRetry: () => this.runSeedScan(true),
      rsSubtitle: 'Type the twelve words from your other wallet on the phone\u2019s own screen, then tap a mint.',
      rsScanCta: s.rsBusy ? 'LOOKING\u2026' : 'ENTER YOUR 12 WORDS',
      rsScanBg: ready ? 'var(--acc)' : 'rgba(var(--ink-rgb),.14)',
      rsScanImg: ready
        ? "radial-gradient(120% 84% at 26% 0%,rgba(255,240,220,.26),rgba(255,240,220,0) 62%),"
          + "linear-gradient(168deg,rgba(247,154,60,.62),rgba(232,98,42,.72) 48%,"
          + "rgba(194,74,27,.78)),url('foxy-fur.webp')"
        : 'none',
      rsScanInk: ready ? '#fff' : 'rgba(var(--ink-rgb),.4)',
      rsScanCur: ready ? 'pointer' : 'default',
      rsScanSh: ready
        ? 'inset 0 2px 0 rgba(255,255,255,.4),inset 0 -4px 0 rgba(0,0,0,.16),'
          + '0 12px 24px rgba(var(--acc-rgb),.34)'
        : 'none',
      rsIdle: !s.rsBusy && !(s.rsRows || []).length,
      rsLooking: !!s.rsBusy,
      rsDone: !s.rsBusy && (s.rsRows || []).some(r => r.state === 'done'),
      // A mint holding something is the orange button; one that answered with
      // nothing is still selectable, just quiet about it.
      rsRows: (s.rsRows || []).map(r => {
        const live = r.state === 'done' && (r.sats > 0 || this.rowUnits(r).length > 0);
        const done = r.state === 'done';
        return {
          host: r.host,
          line: r.state === 'looking' ? '\u2026'
            : r.state === 'failed' ? 'no answer'
            : r.partial ? (live ? this.rowAmounts(r) + ' so far' : 'incomplete')
            : live ? this.rowAmounts(r) : 'nothing',
          bg: live
            ? 'linear-gradient(168deg,rgba(247,154,60,.92),rgba(232,98,42,.94) 48%,'
              + 'rgba(194,74,27,.96))'
            : 'var(--surface)',
          border: live ? 'rgba(255,255,255,.22)'
            : r.state === 'failed' ? 'rgba(255,92,92,.4)' : 'rgba(var(--ink-rgb),.12)',
          ink: live ? '#fff'
            : r.state === 'failed' ? '#FF5C5C' : 'rgba(var(--ink-rgb),.5)',
          sh: live ? 'inset 0 2px 0 rgba(255,255,255,.4),inset 0 -3px 0 rgba(0,0,0,.16),'
                     + '0 8px 18px rgba(var(--acc-rgb),.3)' : 'none',
          cursor: done ? 'pointer' : 'default',
          tap: () => this.pickRestoreMint(r),
        };
      }),
      isRsConfirm: sc === 'rsConfirm',
      rsPickHost: (s.rsPick && s.rsPick.host) || '',
      rsPickSats: s.rsPick ? (this.rowUnits(s.rsPick).length ? this.rowAmounts(s.rsPick) : this.group(s.rsPick.sats) + ' sats') : '\u2014',
      rsPickErr: s.rsPickErr || '',
      rsConfirmCta: s.rsBusy2 ? 'WORKING\u2026' : 'REPLACE AND RESTORE',
      rsConfirmGo: () => this.adoptRestoreMint(),
      rsConfirmCancel: () => this.setState({ screen: 'importSeed', rsPick: null, rsPickErr: '' }),
      rsShowSeedFirst: () => this.showSeed(),
      rsCanRetry: !s.rsBusy && (s.rsRows || []).some(r => r.state === 'failed' || r.partial),
      rsNote: s.rsErr || s.rsKept || '',
      rsNoteInk: s.rsErr ? '#FF5C5C' : 'rgba(var(--ink-rgb),.55)',
    };
  }

  /* bkStart, and the sheet that asks for a backup. The words themselves and
   * their quiz are the phone's screens, opened by showSeed. */
  /** @param {RenderContext} c */
  renderBackup(c) {
    const { s, sc } = c;
    return {
      // the sheet, raised the first time a payment lands
      bkAskOpen: !!s.bkAskOpen,
      // not now, and not again for a day (`backupAskedLately`)
      bkAskLater: () => this.setState({ bkAskOpen: false, bkAsk: false }),
      // The seed screen is an overlay, not a template screen: bkStart renders
      // blank, which is why this went nowhere. Close the card and open it.
      bkAskNow: () => { this.setState({ bkAskOpen: false, bkAsk: false }); this.showSeed(); },
      // ---- recovery phrase flow ----
      isBkStart: sc === 'bkStart',
      /* bkStart's button: the phone's own screen for the words, and its quiz.
       * The page's word grid and quiz are gone; the page never has the words. */
      goBkPhrase: () => this.showSeed(),
    };
  }
}
